                "end_ms": 20520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Return the decision to the clinician; do not prescribe an amount of garlic as medicine.",
                "start_ms": 20820,
                "end_ms": 27660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Bawang cards; choose Allium sativum, bulb, use and safe next step.",
                "start_ms": 27960,
