              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Confirm the current team, role, lead and reporting channel with the barangay and health supervisor.",
                "start_ms": 2260,
                "end_ms": 10060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Report the minimum needed: location, hazard, urgent need, action taken and next contact.",
                "start_ms": 10360,
                "end_ms": 18960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hand over and record time; protect sensitive details.",
                "start_ms": 19260,
                "end_ms": 23980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "In a mock team change, identify what to confirm and give a short handover without personal details.",
                "start_ms": 24280,
                "end_ms": 31840
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/bhert-coordination/action.fil.65e25607c885.mp3",
