              {
                "zone": "body",
                "index": 0,
                "text": "Kumpirmahin sa barangay at health supervisor ang kasalukuyang team, tungkulin, lider at reporting channel.",
                "start_ms": 2580,
                "end_ms": 11500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iulat ang minimum na kailangan: lugar, panganib, agarang pangangailangan, ginawa at susunod na contact.",
                "start_ms": 11800,
                "end_ms": 21680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mag-handover at itala ang oras; panatilihing pribado ang sensitibong detalye.",
                "start_ms": 21980,
                "end_ms": 28180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa mock team change, tukuyin ang dapat kumpirmahin at magbigay ng maikling handover nang walang personal na detalye.",
                "start_ms": 28480,
                "end_ms": 37120
