            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c5d0afd1403c33ddc643ada7e7906710af91e758f1a6002677314f0ab11cf95b",
            "sha256": "5dcd0ba4e32b979b95d0b49704bbf61dace041bee24c38931263157eb65eb4cc",
            "duration_seconds": 27.716,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos ng pagbaha, hinihiling sa BHW na itala ang mga alalahanin at maghatid ng impormasyon sa response team.",
                "start_ms": 3700,
                "end_ms": 14580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi malinaw kung aktibo ang lumang BHERT roster.",
                "start_ms": 14880,
                "end_ms": 19520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pagkatapos ng baha: itala ang mga alalahanin, iulat ito, at alamin kung aktibo ang lumang roster.",
                "start_ms": 19820,
                "end_ms": 27660
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/bhert-coordination/scope.en.5b7b055a34d1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5b7b055a34d1f03533949825aa867c9fb305ba3f9afc0f9431704172d90b89a2",
            "sha256": "d5c5cc22cee2032082ce3cf2404bcddbb5bfde795c25fb5e220f510036285461",
            "duration_seconds": 25.313,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The old pandemic-era BHERT slide does not establish today’s team composition, isolation or contact-tracing mandate.",
                "start_ms": 2540,
                "end_ms": 12700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not assign clinical or enforcement duties to a BHW.",
                "start_ms": 13000,
                "end_ms": 18360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "An old slide does not set today's team; no clinical or enforcement duties.",
                "start_ms": 18660,
                "end_ms": 25260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/bhert-coordination/scope.fil.28cb0d23e398.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "28cb0d23e3985876e76de470ce9950926b17036f847a918058703bcc5f4e039f",
            "sha256": "6e9e16d9f85f9d4c010b19a2286183c3c4daa8619c8ac8c5e8649484db6c8f14",
            "duration_seconds": 25.365,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang lumang pandemic-era BHERT slide ay hindi patunay ng kasalukuyang team composition, isolation o contact-tracing mandate.",
                "start_ms": 2820,
                "end_ms": 13020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag magtalaga ng klinikal o enforcement na papel sa BHW.",
                "start_ms": 13320,
                "end_ms": 18800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi batayan ng team ngayon ang lumang slide; walang klinikal o enforcement na papel.",
                "start_ms": 19100,
                "end_ms": 25300
              }
            ]
          }
        }
      }
    },
    "bhs-decline": {
      "module": "03-polisiya-bhs",
      "sections": {
        "hold-boundary": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/hold-boundary.en.97ec7a9d2b44.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "97ec7a9d2b44535ec85a7a24e563741585aabf325b05cb69a9ce17cb86cf9efb",
            "sha256": "edad1c6b97b874669900b2b8f4a9cde29bc531c3fc33acf023a4d35d90341c5b",
            "duration_seconds": 59.324,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "When the visitor presses",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“It is free.",
                "start_ms": 2340,
                "end_ms": 3900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "I will just leave it, and you can decide later,” the visitor says.",
                "start_ms": 4200,
                "end_ms": 9240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mimi does not need to argue or invent an excuse.",
                "start_ms": 9540,
                "end_ms": 13620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She calmly repeats the boundary: “I understand the offer, but I will not accept or distribute these items.",
                "start_ms": 13920,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Please do not leave them with us.",
                "start_ms": 22220,
                "end_ms": 24580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "I will inform the supervisor about your visit.”",
                "start_ms": 24880,
                "end_ms": 28160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She does not arrange distribution outside the facility, accept secretly, or display the poster while waiting for the midwife.",
                "start_ms": 28460,
                "end_ms": 36980
              },
              {
                "zone": "body",
                "index": 7,
                "text": "She does not promise that another offer will be approved.",
                "start_ms": 37280,
                "end_ms": 40920
              },
              {
                "zone": "body",
                "index": 8,
                "text": "If the conversation becomes difficult, she asks the supervisor for help through the local process.",
                "start_ms": 41220,
                "end_ms": 47820
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Respect is expressed in how she speaks; it does not require agreement.",
                "start_ms": 48120,
                "end_ms": 53760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Repeat the boundary calmly; make no arrangement to bypass policy.",
                "start_ms": 54060,
                "end_ms": 59260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/hold-boundary.fil.54fbfa1d34b6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "54fbfa1d34b6d5f2a1c4fa685f23808acc254e12d50532a77ffa264ebe86890b",
            "sha256": "7f2f69bcb3f683178d2f0cc9178a5b565f6565f95bbb81a06e4b991a02a15653",
            "duration_seconds": 63.974,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kapag nagpumilit ang bisita",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Libre naman.",
                "start_ms": 2780,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iwan ko na lang, tapos kayo na ang bahala,” sabi ng bisita.",
                "start_ms": 4720,
                "end_ms": 9280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi kailangang makipagtalo o magbigay ng palusot si Mimi.",
                "start_ms": 9580,
                "end_ms": 13660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Inuulit niya ang hangganan sa mahinahong boses: “Nauunawaan ko po ang alok, pero hindi ko po tatanggapin o ipamimigay ang mga ito.",
                "start_ms": 13960,
                "end_ms": 23520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mangyaring huwag po itong iwan sa amin.",
                "start_ms": 23820,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ipapaalam ko ang pagbisita sa namamahala.”",
                "start_ms": 27320,
                "end_ms": 30640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi siya nakikipagkasundo na sa labas na lang ipamigay, tanggapin nang lihim, o ipaskil muna habang hinihintay ang midwife.",
                "start_ms": 30940,
                "end_ms": 39700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi rin niya sinasabing siguradong maaaprubahan ang ibang alok.",
                "start_ms": 40000,
                "end_ms": 44040
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung hindi maayos ang usapan, humingi ng tulong sa namamahala ayon sa lokal na proseso.",
                "start_ms": 44340,
                "end_ms": 50540
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Ang paggalang ay nasa paraan ng pagsasalita; hindi ito nangangahulugang pagsang-ayon.",
                "start_ms": 50840,
                "end_ms": 57280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ulitin ang hangganan nang mahinahon; walang kasunduang umiikot sa polisiya.",
                "start_ms": 57580,
                "end_ms": 63900
              }
            ]
          }
        },
        "match-policy": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/match-policy.en.cf0493403f5d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf0493403f5dc4f30ac9660aa93518d0738644eccb12131f4ced5a0914ea9c5f",
            "sha256": "933ee842dc39c3f85cd496f789715edf306781f736b5e67190826b6b55f1829d",
            "duration_seconds": 75.624,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Match the reason to the product",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Different products need different policy explanations.",
                "start_ms": 3700,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The first situation involves infant-formula samples for mothers, a BHS product poster, and a gift for promotion; the Milk Code is the relevant basis.",
                "start_ms": 7600,
                "end_ms": 20520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If Mimi is asked to give prescription-medicine samples to families instead, she needs a different explanation: “I cannot distribute prescription samples to the public.",
                "start_ms": 20820,
                "end_ms": 32100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Under the pharmaceutical order, samples are for licensed physicians and dentists under its rules.",
                "start_ms": 32400,
                "end_ms": 38680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "I will refer the details to the supervisor.”",
                "start_ms": 38980,
                "end_ms": 42060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "That order covers prescription pharmaceutical products and medical devices.",
                "start_ms": 42360,
                "end_ms": 48240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Some educational items and scientific activities are permitted under conditions; this is not automatic permission for a BHW.",
                "start_ms": 48540,
                "end_ms": 57300
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If the product or conditions are uncertain, state what is unknown, pause acceptance while checking, and ask for guidance.",
                "start_ms": 57600,
                "end_ms": 65960
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Referral cannot make prohibited promotion lawful.",
                "start_ms": 66260,
                "end_ms": 70340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match the policy to the product; do not invent permission.",
                "start_ms": 70640,
                "end_ms": 75560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/match-policy.fil.2ded5507efc7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2ded5507efc780c92cf27ec0730bdadde08182582ddf2cb0915a5ea00bd3466a",
            "sha256": "f34e118f999698b87223e0e7c51579c4b86e7be7a894afd5bfdebc984357ab03",
            "duration_seconds": 80.744,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Itugma ang paliwanag sa produkto",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi iisang polisiya ang ginagamit sa lahat ng produkto.",
                "start_ms": 2780,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Para sa infant-formula samples para sa mga nanay, product poster sa BHS, at regalong kapalit ng promosyon sa unang sitwasyon, Milk Code ang batayan.",
                "start_ms": 7480,
                "end_ms": 20880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung prescription-medicine samples naman ang hinihiling na ipamigay ni Mimi sa mga pamilya, ibang paliwanag ang kailangan: “Hindi ko po maaaring ipamigay ang prescription samples sa publiko.",
                "start_ms": 21180,
                "end_ms": 33140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa pharmaceutical order, para sa licensed physicians at dentists ang mga sample sa ilalim ng mga tuntunin nito.",
                "start_ms": 33440,
                "end_ms": 41560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Idudulog ko ang detalye sa namamahala.”",
                "start_ms": 41860,
                "end_ms": 44860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Saklaw ng order ang prescription pharmaceutical products at medical devices.",
                "start_ms": 45160,
                "end_ms": 51000
              },
              {
                "zone": "body",
                "index": 6,
                "text": "May kondisyong pinapayagang educational items at scientific activities; hindi ito awtomatikong pahintulot sa BHW.",
                "start_ms": 51300,
                "end_ms": 60020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung hindi tiyak ang produkto o kondisyon, sabihin ang hindi pa alam, huwag tumanggap habang tinitiyak, at humingi ng gabay.",
                "start_ms": 60320,
                "end_ms": 69600
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi ginagawang legal ng pagdulog ang ipinagbabawal na promosyon.",
                "start_ms": 69900,
                "end_ms": 74980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tamang produkto, tamang batayan; huwag mag-imbento ng pahintulot.",
                "start_ms": 75280,
                "end_ms": 80680
              }
            ]
          }
        },
        "refusal-check": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/refusal-check.en.5a4d0e0de768.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5a4d0e0de768b3d23986e5902731af98baf9990f913217c4ab68c4cab5fa8add",
            "sha256": "1ee3a4b2e566e7ed31d3218c38c949880e247b833c2f39000cf273daf5e23c64",
            "duration_seconds": 33.254,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Practice a clear refusal",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A representative asks you to give prescription-medicine samples to families.",
                "start_ms": 2740,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is a personal gift, and the visitor offers to leave the box while the midwife is away.",
                "start_ms": 8000,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose a clear, respectful response within the BHW role.",
                "start_ms": 14460,
                "end_ms": 19300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Then practice it in your own words without taking the items.",
                "start_ms": 19600,
                "end_ms": 23920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "You do not need to memorize a law number.",
                "start_ms": 24220,
                "end_ms": 27180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Acknowledge, decline, explain the correct basis, and report.",
                "start_ms": 27480,
                "end_ms": 33200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/refusal-check.fil.81dd6a33a4c6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81dd6a33a4c64428412d0d04d4835d2abc69a60086d49fa858f86dc97a678a12",
            "sha256": "03a45390826c864550d125894fedf6942678ebb7e2deb9096c244aaf7b084d8f",
            "duration_seconds": 40.229,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isagawa ang malinaw na pagtanggi",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isang kinatawan ang humihiling na ipamigay mo sa mga pamilya ang prescription-medicine samples.",
                "start_ms": 2860,
                "end_ms": 9500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May personal na regalo at sinasabing puwedeng iwan ang box habang wala ang midwife.",
                "start_ms": 9800,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang tugong malinaw, magalang, at nasa tungkulin ng BHW.",
                "start_ms": 17060,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pagkatapos, sabihin ito sa sariling pananalita nang hindi kumukuha ng mga bagay.",
                "start_ms": 23640,
                "end_ms": 29680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi kailangang kabisaduhin ang numero ng batas.",
                "start_ms": 29980,
                "end_ms": 33700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magpasalamat, tumanggi, ipaliwanag ang tamang batayan, at mag-ulat.",
                "start_ms": 34000,
                "end_ms": 40160
              }
            ]
          }
        },
        "report-facts": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/report-facts.en.fabcb91ce467.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fabcb91ce467cf9560bc6becc5c7f13b48febb542740c7f5d26a28e41209e892",
            "sha256": "6391b8a46f548bf68ff118e4361bd0f3d0cb3d3a0447bf6bf3660e934bba1fea",
            "duration_seconds": 64.679,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Report what happened",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "After the conversation, Mimi informs the midwife or facility supervisor through the local process.",
                "start_ms": 2180,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In this fictional example, she reports that day.",
                "start_ms": 9120,
                "end_ms": 12640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This is not a new legal deadline.",
                "start_ms": 12940,
                "end_ms": 15900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She says: “A representative offered infant-formula samples for mothers, a BHS poster, and a gift for promotion.",
                "start_ms": 16200,
                "end_ms": 25080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "I declined and accepted, displayed, and distributed nothing.",
                "start_ms": 25380,
                "end_ms": 31100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "I said I would tell you the details.”",
                "start_ms": 31400,
                "end_ms": 34080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "If a record is required, include the time, place, product, offer, requested activity, and her response.",
                "start_ms": 34380,
                "end_ms": 42940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Follow local rules for handling records; omit patient data and guesses about motives.",
                "start_ms": 43240,
                "end_ms": 49240
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Ask the supervisor to determine the next step.",
                "start_ms": 49540,
                "end_ms": 52580
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Do not blame families for feeding choices; a health professional handles feeding or clinical questions.",
                "start_ms": 52880,
                "end_ms": 60280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Report the facts and your response, without speculation.",
                "start_ms": 60580,
                "end_ms": 64620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/report-facts.fil.5fffc6a0fd04.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5fffc6a0fd045452365f7e3d6fbf0ce6f30c3daddd610951fe388292c113ff54",
            "sha256": "57c28e65eeef075a09d6aa8ccb106ec04cb212cedb1759426b674e8f136d6eb5",
            "duration_seconds": 75.128,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipabatid ang nangyari",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos ng usapan, ipinaalam ni Mimi sa midwife o namamahala ang pagbisita ayon sa lokal na proseso.",
                "start_ms": 2140,
                "end_ms": 9860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa kathang-isip na halimbawang ito, nag-ulat siya sa araw ding iyon.",
                "start_ms": 10160,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi ito bagong legal na deadline.",
                "start_ms": 16420,
                "end_ms": 19580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sinabi niya: “May kinatawang nag-alok ng infant-formula samples para sa mga nanay, poster sa BHS, at regalo kapalit ng promosyon.",
                "start_ms": 19880,
                "end_ms": 30720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tumanggi ako at walang tinanggap, ipinaskil, o ipinamahagi.",
                "start_ms": 31020,
                "end_ms": 36860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sinabi kong ipapaalam ko ang detalye sa inyo.”",
                "start_ms": 37160,
                "end_ms": 40760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kung kailangan ng tala, ilagay ang oras, lugar, produkto, alok, hinihinging gawain, at sariling tugon.",
                "start_ms": 41060,
                "end_ms": 50100
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sundin ang lokal na patakaran sa paghawak ng tala; huwag isama ang datos ng pasyente o haka-haka sa motibo.",
                "start_ms": 50400,
                "end_ms": 58080
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Ipatukoy ang susunod na hakbang sa namamahala.",
                "start_ms": 58380,
                "end_ms": 61780
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Huwag sisihin ang mga pamilya sa feeding choices; health professional ang sasagot sa feeding o clinical questions.",
                "start_ms": 62080,
                "end_ms": 69680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mag-ulat ng katotohanan at sariling tugon, hindi haka-haka.",
                "start_ms": 69980,
                "end_ms": 75060
              }
            ]
          }
        },
        "section-4": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/section-4.en.d072d01cdd2c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d072d01cdd2caa5995e9f2fcc98d76d642f6587a8c7492996cceb66a579f68c0",
            "sha256": "2623ce414c7e32f986d6a0bf3bc46912ed15492259704e3ae1c20625a156d7ab",
            "duration_seconds": 60.813,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Clear and respectful",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The company representative returns to the BHS with infant-formula samples for mothers, a product poster, and a personal gift in return for promotion.",
                "start_ms": 2540,
                "end_ms": 14420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mimi knows she will decline this offer.",
                "start_ms": 14720,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "How can she say no respectfully?",
                "start_ms": 18180,
                "end_ms": 21060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mimi says: “Thank you for coming.",
                "start_ms": 21360,
                "end_ms": 24320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "I will not accept the samples or gift, or display the product poster.",
                "start_ms": 24620,
                "end_ms": 30100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "This falls under the Milk Code: the facility cannot be used for this promotion, and an inducement for promotion cannot be accepted.",
                "start_ms": 30400,
                "end_ms": 39440
              },
              {
                "zone": "body",
                "index": 6,
                "text": "I will tell our midwife or facility supervisor the details.”",
                "start_ms": 39740,
                "end_ms": 43780
              },
              {
                "zone": "body",
                "index": 7,
                "text": "She does not take the items, assume the visitor’s motives, or promise permission later.",
                "start_ms": 44080,
                "end_ms": 49960
              },
              {
                "zone": "body",
                "index": 8,
                "text": "The story is optional; you can complete Read or Slides without watching it.",
                "start_ms": 50260,
                "end_ms": 54660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use a respectful tone, a clear refusal, and a specific reason.",
                "start_ms": 54960,
                "end_ms": 60760
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/section-4.fil.dda983cbd882.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dda983cbd882820af3ec8d6815f25d8ae41f3480def3853348d694786cb660b6",
            "sha256": "66fe9d0663ac5ad622ca2ed91b3412ad70af9a0fd970cb359ea571580359f6ff",
            "duration_seconds": 68.728,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Malinaw at magalang",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bumalik ang kinatawan ng kumpanya sa BHS.",
                "start_ms": 2500,
                "end_ms": 6140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May infant-formula samples para sa mga nanay, product poster, at personal na regalong kapalit ng tulong sa promosyon.",
                "start_ms": 6440,
                "end_ms": 16040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alam ni Mimi na hindi niya tatanggapin ang alok na ito.",
                "start_ms": 16340,
                "end_ms": 20100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Paano niya sasabihin ang hindi nang may paggalang?",
                "start_ms": 20400,
                "end_ms": 24400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sinabi ni Mimi: “Salamat po sa pagpunta.",
                "start_ms": 24700,
                "end_ms": 28460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi ko po tatanggapin ang mga sample at regalo o ipapaskil ang product poster.",
                "start_ms": 28760,
                "end_ms": 33880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Saklaw ito ng Milk Code: hindi ginagamit ang pasilidad para sa ganitong promosyon, at hindi tinatanggap ang insentibong kapalit ng pagpromote.",
                "start_ms": 34180,
                "end_ms": 43660
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ipapaalam ko ang detalye sa aming midwife o namamahala.”",
                "start_ms": 43960,
                "end_ms": 48560
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi niya kinukuha ang mga bagay, ipinapalagay ang motibo ng bisita, o nangangakong may pahintulot mamaya.",
                "start_ms": 48860,
                "end_ms": 57300
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Opsyonal ang kuwento; maaari mong tapusin ang Read o Slides nang hindi nanonood.",
                "start_ms": 57600,
                "end_ms": 63120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magalang na tono, malinaw na hindi, at tiyak na dahilan.",
                "start_ms": 63420,
                "end_ms": 68660
              }
            ]
          }
        },
        "section-7": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/section-7.en.611351ff6c6b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "611351ff6c6b8860ed38caac4f51f7152b16ec739769fba143d24feba3f3166f",
            "sha256": "7c73b0730e338c0ae98710b8b04ca142c380618086dac261ac3095afbf919949",
            "duration_seconds": 58.802,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Compare two responses",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Both responses concern the same infant-formula offer.",
                "start_ms": 2260,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Danilo accepts the samples for mothers and gift because “saying no might be rude.”",
                "start_ms": 7000,
                "end_ms": 12080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "He suggests distributing them outside instead.",
                "start_ms": 12380,
                "end_ms": 16780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Accepting and arranging an alternative cross the boundary; a polite tone does not correct that.",
                "start_ms": 17080,
                "end_ms": 22920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mimi thanks the visitor, clearly declines the samples, gift, and poster, explains the Milk Code as it applies to the offer, and makes no alternative promotional arrangement.",
                "start_ms": 23220,
                "end_ms": 35940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She informs the supervisor of the facts.",
                "start_ms": 36240,
                "end_ms": 39200
              },
              {
                "zone": "body",
                "index": 6,
                "text": "In the medicine-sample situation, she would use the pharmaceutical explanation, not the Milk Code.",
                "start_ms": 39500,
                "end_ms": 46460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "A good response combines respect, an accurate reason, and actions consistent with the refusal.",
                "start_ms": 46760,
                "end_ms": 54160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Polite words are insufficient if the offer is still accepted.",
                "start_ms": 54460,
                "end_ms": 58740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-decline/section-7.fil.3e2046bba5f6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3e2046bba5f659952401a5c35a382b269e205d22f3c71fecc5b9f102011cc65c",
            "sha256": "92102df83248bfb97d856e9418126221694db256e61bba6397d71b17362d4746",
            "duration_seconds": 63.478,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ihambing ang dalawang tugon",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Parehong infant-formula offer ang pinag-uusapan.",
                "start_ms": 3140,
                "end_ms": 6900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tinanggap ni Danilo ang mga sample para sa mga nanay at regalo dahil “baka bastos ang tumanggi.”",
                "start_ms": 7200,
                "end_ms": 13920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sinabi niyang puwedeng sa labas na lang ipamigay.",
                "start_ms": 14220,
                "end_ms": 17220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nalampasan ang hangganan sa mismong pagtanggap at kasunduan; hindi ito naitatama ng magalang na tono.",
                "start_ms": 17520,
                "end_ms": 24680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Si Mimi ay nagpasalamat sa pagbisita, malinaw na tumanggi sa mga sample, regalo, at poster, ipinaliwanag ang Milk Code na naaangkop sa alok, at walang iminungkahing kapalit na promosyon.",
                "start_ms": 24980,
                "end_ms": 39700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ipinaalam niya ang katotohanan sa namamahala.",
                "start_ms": 40000,
                "end_ms": 43440
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Sa medicine-sample situation, pharmaceutical order ang ipapaliwanag niya, hindi Milk Code.",
                "start_ms": 43740,
                "end_ms": 50740
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ang magandang tugon ay may paggalang, tamang dahilan, at kilos na tugma sa sinabi.",
                "start_ms": 51040,
                "end_ms": 58160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi sapat ang magalang na salita kung tinatanggap pa rin ang alok.",
                "start_ms": 58460,
                "end_ms": 63420
              }
            ]
          }
        }
      }
    },
    "bhs-improvement": {
      "module": "03-polisiya-bhs",
      "sections": {
        "factual-concern": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/factual-concern.en.5c8469e0b441.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5c8469e0b44133fdfc69aefc98558dd358b6475d4ceaf8af388092e68968d614",
            "sha256": "bc197a73cc7e323d5355e2b5455560c17d66c80d2092387023fdf9517c8d73db",
            "duration_seconds": 48.274,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "State the factual concern",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi says: “After the meeting, the lights and fan were on in the meeting area.",
                "start_ms": 2620,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "I confirmed another activity was scheduled, but there was no clear reminder of who checks the schedule.”",
                "start_ms": 8560,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This is the concern to discuss, without accusing anyone of carelessness.",
                "start_ms": 16180,
                "end_ms": 21220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If a record is needed, include the date, time, place and observation using the local process.",
                "start_ms": 21520,
                "end_ms": 29600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "State what remains unknown, such as an existing checklist or assigned duty.",
                "start_ms": 29900,
                "end_ms": 35580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Omit patient data, guesses about motives and savings amounts that have not been measured.",
                "start_ms": 35880,
                "end_ms": 43400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A specific concern, without blame or invented savings.",
                "start_ms": 43700,
                "end_ms": 48220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/factual-concern.fil.2e029df9b990.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2e029df9b990b20fa6dfee43af46ad22cbf475eec8bbd5994b0e9f7183971459",
            "sha256": "6cab099cdcc245c0af454cd69ef3e2346a1525902c6609439062c1e2520f725c",
            "duration_seconds": 49.972,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sabihin ang tiyak na concern",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ni Mimi: “Pagkatapos ng meeting, nakabukas ang ilaw at fan sa meeting area.",
                "start_ms": 2860,
                "end_ms": 9460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nakumpirma kong may susunod na gawain, pero wala pang malinaw na paalala kung sino ang titingin sa schedule.”",
                "start_ms": 9760,
                "end_ms": 17480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ito ang concern na tatalakayin, hindi paratang na may pabaya.",
                "start_ms": 17780,
                "end_ms": 22980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung gagawa ng tala, ilagay ang petsa, oras, lugar at napansin ayon sa lokal na proseso.",
                "start_ms": 23280,
                "end_ms": 31120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sabihin ang hindi pa alam, gaya ng umiiral na checklist o itinalagang tungkulin.",
                "start_ms": 31420,
                "end_ms": 37140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Huwag maglagay ng datos ng pasyente, hula sa motibo o halagang matitipid na hindi nasukat.",
                "start_ms": 37440,
                "end_ms": 45240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyak na concern, walang sisi o imbentong savings.",
                "start_ms": 45540,
                "end_ms": 49900
              }
            ]
          }
        },
        "one-feasible-proposal": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/one-feasible-proposal.en.b0a1e86c30d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b0a1e86c30d0e315c35499a5b4c639dd2beb03ee3518e86cc128a64f3cff8d56",
            "sha256": "0606622e9f4c634b9f4dc3caf7169b497f922f6037135e05ffc2a688d53e4797",
            "duration_seconds": 52.297,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Propose one feasible first step",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi proposes: “Could we review whether a short meeting-end checklist is needed, so the designated person checks the next scheduled use and shares concerns with the right contact?”",
                "start_ms": 3340,
                "end_ms": 15620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It is one proposal; she does not claim the duty or tell everyone to use the checklist immediately.",
                "start_ms": 15920,
                "end_ms": 23960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Check for an existing process before creating another.",
                "start_ms": 24260,
                "end_ms": 28140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If one exists, clarifying its reminder may be enough.",
                "start_ms": 28440,
                "end_ms": 33000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If a change is needed, check the time, materials and person who could carry it out.",
                "start_ms": 33300,
                "end_ms": 39540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Do not include independent repairs, reductions in clinical supplies or new tasks beyond the role.",
                "start_ms": 39840,
                "end_ms": 48240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start with one small, clear proposal.",
                "start_ms": 48540,
                "end_ms": 52220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/one-feasible-proposal.fil.c277b2ee8b92.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c277b2ee8b926223e35ba023b104a209fabfed1a107acb8a5ce01c0855da2546",
            "sha256": "201d16ec0ddeb92af6a25be23e04144ead4d2e28defa461e1f514d0b80ee9116",
            "duration_seconds": 55.771,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Magmungkahi ng isang unang hakbang",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iminungkahi ni Mimi: “Maaari po bang suriin natin kung kailangan ng maikling meeting-end checklist para matingnan ng itinalagang tao ang susunod na schedule at maipaalam ang concern sa tamang contact?”",
                "start_ms": 3220,
                "end_ms": 18580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Isang panukala lamang ito; hindi niya inaangkin ang tungkulin o nag-uutos na sundin agad ang checklist.",
                "start_ms": 18880,
                "end_ms": 26320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tiyakin kung may umiiral nang paraan bago gumawa ng bago.",
                "start_ms": 26620,
                "end_ms": 30980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mayroon, maaaring linawin lamang ang paalala.",
                "start_ms": 31280,
                "end_ms": 35040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung kailangan ng pagbabago, alamin ang oras, materyales at taong maaaring gumawa nito.",
                "start_ms": 35340,
                "end_ms": 43060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Huwag isama ang sariling pagkumpuni, pagbawas ng clinical supplies o bagong gawain na lampas sa tungkulin.",
                "start_ms": 43360,
                "end_ms": 51600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Isang maliit at malinaw na panukala muna.",
                "start_ms": 51900,
                "end_ms": 55700
              }
            ]
          }
        },
        "proposal-check": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/proposal-check.en.5090f6c77807.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5090f6c778072a6e922da4a1b9f836a36bc6fc5a5b10c7a7cf1be069cb5dc2a5",
            "sha256": "33a4331bb157aac2719bab9d096f575c7e93b698013ed8eba515c7c86ca69206",
            "duration_seconds": 47.334,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the workable suggestion",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A colleague wants to post a new checklist immediately and tell everyone to follow it.",
                "start_ms": 2740,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Which response from Mimi is appropriate?",
                "start_ms": 8920,
                "end_ms": 12520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose the suggestion with a specific concern, practical first step, reason, local checks and an agreed follow-up.",
                "start_ms": 12820,
                "end_ms": 22220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For your own situation, state four things: what you observed; one proposal; what to check and with whom; and the follow-up you agreed.",
                "start_ms": 22520,
                "end_ms": 34160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Online completion does not demonstrate observed workplace skill; practice and feedback are still needed.",
                "start_ms": 34460,
                "end_ms": 41580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Observation → Proposal → Checks → Follow-up.",
                "start_ms": 41880,
                "end_ms": 47280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/proposal-check.fil.5e61df66728b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5e61df66728b7089422152793a36d9594e11fdb28b54478dfbdfe975463d19c1",
            "sha256": "c24e10d9240701ad87e34516bd95e379828cb16bbde960e335f1bbafd495d65e",
            "duration_seconds": 51.461,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang mungkahing maisasagawa",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gusto ng isang kasamahan na agad maglagay ng bagong checklist at atasan ang lahat na sundin ito.",
                "start_ms": 3580,
                "end_ms": 9860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Aling tugon ni Mimi ang angkop?",
                "start_ms": 10160,
                "end_ms": 12880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang mungkahing may tiyak na concern, praktikal na unang hakbang, dahilan, lokal na pagsusuri at napagkasunduang follow-up.",
                "start_ms": 13180,
                "end_ms": 25140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa sariling sitwasyon, sabihin ang apat: ano ang nakita; ano ang isang panukala; ano ang dapat tiyakin at kanino; at ano ang follow-up na napagkasunduan.",
                "start_ms": 25440,
                "end_ms": 37840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang online completion ay hindi katumbas ng naobserbahang workplace skill; kailangan pa ng pagsasanay at feedback.",
                "start_ms": 38140,
                "end_ms": 45540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pansin → Panukala → Pagsusuri → Follow-up.",
                "start_ms": 45840,
                "end_ms": 51400
              }
            ]
          }
        },
        "reason-service-checks": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/reason-service-checks.en.56c65bccb8ee.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "56c65bccb8ee325a2956496f77cc29f55cbe40c23ddfeaa525ae2e9087e3d217",
            "sha256": "9d63ac12c4736e0ad7318af13fd2b8b08f4cef7755f6f63c4473d7cbb7be2610",
            "duration_seconds": 46.629,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Explain the reason and limits",
                "start_ms": 0,
                "end_ms": 3360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi explains: “A clear reminder could help people remember to check the schedule and coordinate after a meeting.”",
                "start_ms": 3660,
                "end_ms": 10900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The purpose is to reduce confusion about responsibility; electricity or money savings have not been measured.",
                "start_ms": 11200,
                "end_ms": 18640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She asks whether the checklist is practical, who has time for it and whether another group needs the area.",
                "start_ms": 18940,
                "end_ms": 26340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "It must follow the rules and protect service and safety.",
                "start_ms": 26640,
                "end_ms": 32520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If a possible hazard is present, use the local safety process; a checklist does not replace a repair or clinical procedure.",
                "start_ms": 32820,
                "end_ms": 41660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Give a reason and service checks, without guaranteeing a result.",
                "start_ms": 41960,
                "end_ms": 46560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/reason-service-checks.fil.ee7630596c55.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ee7630596c5519778320e6e7e0aceaaa47bd3d1744c2a1c56e6ca0c116ee27d6",
            "sha256": "ba798a62d4ec72bc52e9a2473b20df8f2a24b10ae33ffe1ecc5639a23efe7968",
            "duration_seconds": 53.055,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipaliwanag ang dahilan at limitasyon",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dahilan ni Mimi: “Makakatulong ang malinaw na paalala upang hindi malimutan ang pagtingin sa schedule at pag-ugnayan pagkatapos ng meeting.”",
                "start_ms": 3460,
                "end_ms": 14060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Layunin nitong bawasan ang kalituhan sa responsibilidad; hindi pa nasusukat kung may matitipid na kuryente o pera.",
                "start_ms": 14360,
                "end_ms": 23120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itatanong niya kung praktikal ang checklist, sino ang may oras para rito, at kung may susunod na gumagamit ng lugar.",
                "start_ms": 23420,
                "end_ms": 31700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dapat naaayon ito sa tuntunin at hindi nakaaabala sa serbisyo o kaligtasan.",
                "start_ms": 32000,
                "end_ms": 38240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may posibleng panganib, idulog sa lokal na safety process; hindi kapalit ng repair o clinical procedure ang checklist.",
                "start_ms": 38540,
                "end_ms": 48060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May dahilan at service checks, walang garantisadong resulta.",
                "start_ms": 48360,
                "end_ms": 53000
              }
            ]
          }
        },
        "responsibility-followup": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/responsibility-followup.en.48ab2b42f519.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "48ab2b42f519f9736e7af79273f191d69ff7234b04c7922814cb5d7364f677e7",
            "sha256": "dfe3f56862d40be067785085f0f45acaa6cd71712e381b1e749927ca087cf4f4",
            "duration_seconds": 58.436,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Confirm responsibility and follow-up",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi first confirms who is responsible for the area and who has authority to approve a change.",
                "start_ms": 3460,
                "end_ms": 10220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It may be the midwife, facility supervisor or another designated person, depending on local roles and the proposal.",
                "start_ms": 10520,
                "end_ms": 19920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A colleague agreeing does not automatically give permission.",
                "start_ms": 20220,
                "end_ms": 24780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In the fictional conversation, the contact agrees to review the existing process with Mimi at the next meeting.",
                "start_ms": 25080,
                "end_ms": 32080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "They record who will check, what will be reviewed and when they will speak again.",
                "start_ms": 32380,
                "end_ms": 38300
              },
              {
                "zone": "body",
                "index": 5,
                "text": "If there is no decision, Mimi reports the status and follows the local referral process.",
                "start_ms": 38600,
                "end_ms": 44800
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She does not promise approval, repairs or savings, and does not implement a new checklist yet.",
                "start_ms": 45100,
                "end_ms": 53380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Agree on the next conversation, without promising an outcome.",
                "start_ms": 53680,
                "end_ms": 58360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/responsibility-followup.fil.064aeb15a8ab.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "064aeb15a8ab40221bc75448bfc5935e6f73b582fda5907616b18313770a4073",
            "sha256": "c04ccbffa767ac64deb072d17b00261042616705202b781cebd93b7594dcf29c",
            "duration_seconds": 63.504,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tiyakin ang responsable at follow-up",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kinumpirma muna ni Mimi kung sino ang responsable sa lugar at sino ang may saklaw na magpahintulot ng pagbabago.",
                "start_ms": 3260,
                "end_ms": 10940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring midwife, facility supervisor o ibang itinalagang tao; depende ito sa lokal na tungkulin at uri ng panukala.",
                "start_ms": 11240,
                "end_ms": 22280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang pagsang-ayon ng kasamahan ay hindi awtomatikong pahintulot.",
                "start_ms": 22580,
                "end_ms": 27700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa fictional na usapan, pumayag ang contact na suriin ang umiiral na proseso kasama ni Mimi sa susunod na meeting.",
                "start_ms": 28000,
                "end_ms": 36520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itinala nila kung sino ang titingin, ano ang susuriin at kailan sila mag-uusap muli.",
                "start_ms": 36820,
                "end_ms": 43580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung walang desisyon, iuulat ni Mimi ang status at susundin ang lokal na pagdulog.",
                "start_ms": 43880,
                "end_ms": 51040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi siya nangangako ng approval, repair o savings, at hindi muna nagpapatupad ng bagong checklist.",
                "start_ms": 51340,
                "end_ms": 58540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magkasundo sa susunod na pag-uusap; hindi pa sa resulta.",
                "start_ms": 58840,
                "end_ms": 63440
              }
            ]
          }
        },
        "section-6": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/section-6.en.31acf4fca6cb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "31acf4fca6cb4bb089d7d245ede67fb305b8052dd2654d8d5e1a07c1b973f64f",
            "sha256": "9cbc757fd55b30a9ebe1ff5dd4a4fa0b1a3853c7099e3307fa1a0b60ac26480f",
            "duration_seconds": 48.875,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "From concern to proposal",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the previous lesson, BHW Mimi checked why the lights and fan were on in an empty meeting area.",
                "start_ms": 2780,
                "end_ms": 9780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In this fictional continuation, she confirms another activity is scheduled there; she does not simply turn them off.",
                "start_ms": 10080,
                "end_ms": 17400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She also learns there is no clear reminder of who checks the schedule after a meeting.",
                "start_ms": 17700,
                "end_ms": 22700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Now she will form one workable suggestion: a small first step with a reason, consistent with local rules and service needs.",
                "start_ms": 23000,
                "end_ms": 32320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "It is not yet permission to act or a promise of savings.",
                "start_ms": 32620,
                "end_ms": 37140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The story is optional; you can complete Read or Slides without watching it.",
                "start_ms": 37440,
                "end_ms": 43080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Separate the observation, proposal, checks and follow-up.",
                "start_ms": 43380,
                "end_ms": 48820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-improvement/section-6.fil.9f29625e0483.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9f29625e048368b75478a215106f5415ccafdf2ac80878fdec1ec24002944969",
            "sha256": "b1ef4aedb779e94ca75331647b019bfdd3a5e7100ca7a57d36affe98b685a63a",
            "duration_seconds": 56.085,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mula sa pansin, tungo sa mungkahi",
                "start_ms": 0,
                "end_ms": 3600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa naunang aralin, sinuri ni BHW Mimi ang nakabukas na ilaw at fan sa bakanteng meeting area.",
                "start_ms": 3900,
                "end_ms": 11540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa pagpapatuloy ng kathang-isip na kuwento, nakumpirma niyang may susunod na gawain doon; hindi niya ito basta pinatay.",
                "start_ms": 11840,
                "end_ms": 20080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Napag-alaman ding walang malinaw na paalala kung sino ang titingin sa schedule pagkatapos ng meeting.",
                "start_ms": 20380,
                "end_ms": 26860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ngayon, bubuo siya ng isang mungkahing maisasagawa: isang maliit na unang hakbang na may dahilan, naaayon sa lokal na tuntunin at hindi nakasasagabal sa serbisyo.",
                "start_ms": 27160,
                "end_ms": 39760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi pa ito pahintulot na kumilos o pangakong makatitipid.",
                "start_ms": 40060,
                "end_ms": 44380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Opsyonal ang kuwento; maaaring tapusin ang Read o Slides nang hindi nanonood.",
                "start_ms": 44680,
                "end_ms": 49960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihiwalay ang nakita, mungkahi, dapat tiyakin at follow-up.",
                "start_ms": 50260,
                "end_ms": 56020
              }
            ]
          }
        }
      }
    },
    "bhs-ipc-policies": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/action.en.655682bbf11c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "655682bbf11c7d469dc6a0d3d16c57159f9451035f03774627c2a3a1ca54e8d1",
            "sha256": "b45b3989e75dde207049f59c3f8751d2947f64fe8b54c56dd69e7976bc2d52a2",
            "duration_seconds": 43.259,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Locate each policy and its date or version.",
                "start_ms": 2420,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Confirm with the IPC contact that it is in use.",
                "start_ms": 6560,
                "end_ms": 10760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Record the owner, relevant role and training needed.",
                "start_ms": 11060,
                "end_ms": 15900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Include hand hygiene, precautions, triage, cleaning, waste, injection safety and worker protection.",
                "start_ms": 16200,
                "end_ms": 25800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report missing or conflicting guidance rather than inventing a procedure.",
                "start_ms": 26100,
                "end_ms": 32020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Complete the sample policy and training checklist. Identify old guidance, a missing contact and two tasks requiring specialist staff.",
                "start_ms": 32320,
                "end_ms": 43200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/action.fil.411fe36a30d7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "411fe36a30d7bdf1b6c3fcd37541c05ac296dfaa22c28934a6d4d906cfcdc2ff",
            "sha256": "9cadb15d622333e3c486beee9d2a2e72fa6e702191bbf1d55bb5de2a0e7806b1",
            "duration_seconds": 48.666,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hanapin ang patakaran at petsa o bersiyon.",
                "start_ms": 2860,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kumpirmahin sa IPC contact kung iyon ang ginagamit.",
                "start_ms": 7320,
                "end_ms": 11600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itala ang responsable, naaangkop na tungkulin at training na kailangan.",
                "start_ms": 11900,
                "end_ms": 18100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Isama ang hand hygiene, precautions, triage, paglilinis, basura, injection safety at worker protection sa checklist.",
                "start_ms": 18400,
                "end_ms": 29560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung kulang o magkasalungat ang gabay, ipaalam; huwag gumawa ng sariling procedure.",
                "start_ms": 29860,
                "end_ms": 36300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Punan ang sample policy at training checklist. Tukuyin ang lumang gabay, kulang na contact at dalawang gawain na kailangan ng specialist staff.",
                "start_ms": 36600,
                "end_ms": 48600
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/check-start.en.949ff96252fa.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "949ff96252fa8ef51bfaac435da7921b2b37411841cf7b7545656266ef60bb93",
            "sha256": "485ac9e8b3b20e4bcb78a2ced4a807810844f6caaef48dcdf40a3fe37d212467",
            "duration_seconds": 16.457,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2420,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4960,
                "end_ms": 8760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Finding the policy is a first step; confirm who does sterilization and what training it needs.",
                "start_ms": 9060,
                "end_ms": 16380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/check-start.fil.8090155063b7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8090155063b79ab7bae20f9b1091da4f38a20b469ea5905281c0e8e3e6be7ba0",
            "sha256": "b8dbd2464ce4723c9f226389bb7d34723645f9706f98ebbe35edb0568dffdf69",
            "duration_seconds": 17.998,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2900,
                "end_ms": 4940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5240,
                "end_ms": 9760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Unang hakbang ang pagkakita; kumpirmahin kung sino ang gumagawa ng sterilization at anong training ang kailangan.",
                "start_ms": 10060,
                "end_ms": 17940
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/check-transfer.en.eed54e88d400.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eed54e88d400d9e2f338bc49560ee520c75ee965da288ed08474b824be240406",
            "sha256": "1d6c7b7ee39c07a7808fcb181cfb3a7dbea16f39f9fa3be0b80340a721d92b68",
            "duration_seconds": 11.572,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2860,
                "end_ms": 4940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5240,
                "end_ms": 7960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This clarifies the applicable guidance.",
                "start_ms": 8260,
                "end_ms": 11500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/check-transfer.fil.6a90da2d1321.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6a90da2d13217fe6f769619d79e50e650242d39a7b61d18b5bbfe2766920f745",
            "sha256": "60dfe627eea7a945d89d0daf28f70598b891ea6618abb03f776050ddc4718601",
            "duration_seconds": 12.251,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2540,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5040,
                "end_ms": 8080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nililinaw ang kasalukuyang naaangkop na gabay.",
                "start_ms": 8380,
                "end_ms": 12180
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/example.en.f0a309a9671b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f0a309a9671b3620fcac7e629951fd67a36dd2eeb8dd46c7c2a5045988e7934a",
            "sha256": "03e7074f0122b0b4ed96de17b6644a0b6ce39732903825f8f8b4e5752abc338b",
            "duration_seconds": 33.463,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For hand hygiene, Nilo records the location and confirms the version with the nurse.",
                "start_ms": 1980,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He records the return demonstration still needed.",
                "start_ms": 8560,
                "end_ms": 12480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For sterilization, he identifies specialist staff.",
                "start_ms": 12780,
                "end_ms": 16980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For exposure, he obtains the contact and immediate reporting process.",
                "start_ms": 17280,
                "end_ms": 22560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "He does not mark unfinished training as completed.",
                "start_ms": 22860,
                "end_ms": 26900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Record what is found and confirmed; never mark unfinished training as done.",
                "start_ms": 27200,
                "end_ms": 33400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/example.fil.c62acdc33aa5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c62acdc33aa5ae327d01195822bc15d1b33c795cbdb549214d836644c36bccff",
            "sha256": "499096bb487f73c674a80b740cf4226e9a02c8cad4e865d5703a80b4f4f7cf59",
            "duration_seconds": 37.46,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa hand hygiene row, isinulat ni Nilo ang lokasyon at kinumpirma ang bersiyon sa nurse.",
                "start_ms": 1940,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itinala niya ang kailangan pang return demonstration.",
                "start_ms": 8800,
                "end_ms": 12800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa sterilization row, isinulat niyang specialist staff ang gagawa.",
                "start_ms": 13100,
                "end_ms": 18940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa exposure row, hiningi niya ang contact at paraan ng agarang pag-uulat.",
                "start_ms": 19240,
                "end_ms": 25480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi niya nilagyan ng “trained” ang hindi pa niya nagawa.",
                "start_ms": 25780,
                "end_ms": 30180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itala ang nakita at nakumpirma; huwag markahang tapos ang training na hindi pa nagagawa.",
                "start_ms": 30480,
                "end_ms": 37400
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/next-step.en.4f68eca0e3af.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4f68eca0e3af210598b97dec9a5c253627152383825c144b4c3c102e163aa7d3",
            "sha256": "a488cb41b94f1261a866cd5d29e55dec089ca0974b5886dcda8c573655cd5987",
            "duration_seconds": 34.56,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nilo now has contacts, versions and a plan for missing training.",
                "start_ms": 2740,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, have the supervisor review the blank checklist before using it in the actual BHS.",
                "start_ms": 8920,
                "end_ms": 16080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: policy — the facility’s agreed guidance.",
                "start_ms": 16380,
                "end_ms": 21500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Distinguish found, confirmed, started and observed.",
                "start_ms": 21800,
                "end_ms": 28440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Have the supervisor review the checklist before using it at the BHS.",
                "start_ms": 28740,
                "end_ms": 34500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/next-step.fil.469471094b14.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "469471094b1441f62e2735ba5cb392737ee67c652e717af3a2eadd007d01e526",
            "sha256": "065b93a6f1405535015a5bb8975f08d885d55501a6484fea8cb47bb084deea91",
            "duration_seconds": 35.683,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May contact, bersiyon at plano sa kulang na training si Nilo.",
                "start_ms": 2540,
                "end_ms": 7900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, ipasuri sa supervisor ang blangkong checklist bago punan sa tunay na BHS.",
                "start_ms": 8200,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: policy — napagkasunduang gabay ng facility.",
                "start_ms": 16420,
                "end_ms": 22140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ihiwalay ang “nakita,” “nakumpirma,” “nasimulan” at “naobserbahan.”",
                "start_ms": 22440,
                "end_ms": 29400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipasuri sa supervisor ang checklist bago gamitin sa BHS.",
                "start_ms": 29700,
                "end_ms": 35620
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/scene.en.debde7693a3f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "debde7693a3f38ebeb2d944106b84037c8e0822896dde45ebecaee8bbfc2cbe0",
            "sha256": "d989e4d08c49e5a901c9712e46db86461a68345ef5c6d650be0bbb2021299430",
            "duration_seconds": 27.847,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Nilo finds an IPC folder with some old pages and no exposure-reporting contact.",
                "start_ms": 2060,
                "end_ms": 10620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It includes injection and sterilization documents.",
                "start_ms": 10920,
                "end_ms": 15000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Finding them does not authorize him to perform those procedures.",
                "start_ms": 15300,
                "end_ms": 20020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "He needs the applicable guidance and his own role.",
                "start_ms": 20320,
                "end_ms": 24560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A document is not authorization.",
                "start_ms": 24860,
                "end_ms": 27780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/scene.fil.7b1f6583ef1a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7b1f6583ef1a12defda222db1b9d290995c609e2ebd8bc7d5ebad7b0576ea590",
            "sha256": "b73c889f829c17d68fa06ad81ac1bf76d52a08cc3fc27618da00bd534446132d",
            "duration_seconds": 30.041,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May folder ng IPC si BHW Nilo, pero luma ang ilang pahina at walang contact sa exposure reporting.",
                "start_ms": 1820,
                "end_ms": 10100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nakakita siya ng dokumento tungkol sa injection at sterilization.",
                "start_ms": 10400,
                "end_ms": 15760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi ibig sabihin na maaari na niyang gawin ang mga ito.",
                "start_ms": 16060,
                "end_ms": 20220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kailangan niyang malaman ang tamang gabay at sariling tungkulin.",
                "start_ms": 20520,
                "end_ms": 25880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dokumento ay hindi awtorisasyon.",
                "start_ms": 26180,
                "end_ms": 29980
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/scope.en.0d14379fd73e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0d14379fd73e6d59ae063c923664915884d1ee98232593af69d2d18dccdf478c",
            "sha256": "5199c0bf6217cabb67ff42aa872a87d75e99165a65f2bba839f9a1d20727ff34",
            "duration_seconds": 37.146,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Reading or attendance alone is not authorization.",
                "start_ms": 2460,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tasks require appropriate instruction, training and permission.",
                "start_ms": 7560,
                "end_ms": 13120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For a sharps or body-fluid exposure, promptly use the local reporting and clinical-assessment process.",
                "start_ms": 13420,
                "end_ms": 20700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not prescribe or start medicines from this checklist.",
                "start_ms": 21000,
                "end_ms": 25200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not assume BHWs need no IPC training.",
                "start_ms": 25500,
                "end_ms": 30540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reading or attendance is not authorization; report exposures promptly.",
                "start_ms": 30840,
                "end_ms": 37080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/bhs-ipc-policies/scope.fil.77e6eb7af6c8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "77e6eb7af6c800d369e0e5738d88da2650c366279da65f97fba2065ee409372e",
            "sha256": "a8d33ca77b1f9f4a85784cfc6d71b65092448b2217ab433980a742db3e54fa52",
            "duration_seconds": 39.027,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi awtorisasyon ang pagbabasa o attendance lamang.",
                "start_ms": 3260,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan ang gabay, training at pahintulot ayon sa gawain.",
                "start_ms": 7360,
                "end_ms": 13280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung may tusok o body-fluid exposure, gamitin agad ang lokal na reporting at clinical assessment process.",
                "start_ms": 13580,
                "end_ms": 22020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag magreseta o magsimula ng gamot mula sa checklist.",
                "start_ms": 22320,
                "end_ms": 26680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag sabihing hindi kailangan ng BHW ang anumang IPC training.",
                "start_ms": 26980,
                "end_ms": 32660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi awtorisasyon ang pagbabasa o attendance; iulat agad ang exposure.",
                "start_ms": 32960,
                "end_ms": 38960
              }
            ]
          }
        }
      }
    },
    "bhs-promotions": {
      "module": "03-polisiya-bhs",
      "sections": {
        "identify-offer": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/identify-offer.en.5f4f737cc901.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5f4f737cc90108e0fea4f52bf18bd207493c3c6cf37279f0cea2ee8aaa32c95d",
            "sha256": "712f9c03f9afbe99e860c6bf5482a24439ac6e79a5597f907389300e71e7051b",
            "duration_seconds": 48.849,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What exactly is being offered?",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi identifies four details: the product, requested promotion, place and audience, and gift or inducement.",
                "start_ms": 2700,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Here she sees samples whose scope must be checked, a BHS tarpaulin, distribution to mothers, and a gift alongside the promotion.",
                "start_ms": 12080,
                "end_ms": 22240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For a medicine offer, ask whether it is a prescription product and who would receive the sample.",
                "start_ms": 22540,
                "end_ms": 28700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Under AO 2015-0053, prescription samples cannot be distributed to the general public; only licensed physicians and dentists may receive these samples under its rules.",
                "start_ms": 29000,
                "end_ms": 42600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The word “free” does not establish permission to accept or distribute.",
                "start_ms": 42900,
                "end_ms": 48780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/identify-offer.fil.d214ba912027.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d214ba91202728ac9c5fdc9c558314af7cd59cb2ffa062dc4236993a40412f94",
            "sha256": "4ea5ba76b7a2e7e4a171df2293bb042f61c2ee2858a61b809b58e7bfb6c3580f",
            "duration_seconds": 55.771,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano mismo ang alok?",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinutukoy ni Mimi ang apat na detalye: produkto, hinihinging promosyon, lugar at kausap, at regalo o insentibo.",
                "start_ms": 2700,
                "end_ms": 13340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa bisitang ito: sample ng produktong kailangang tiyakin ang saklaw, tarpaulin sa BHS, pamimigay sa mga nanay, at regalo kasabay ng promosyon.",
                "start_ms": 13640,
                "end_ms": 26000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung gamot ang alok, itanong kung prescription product ito at para kanino ang sample.",
                "start_ms": 26300,
                "end_ms": 33340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa AO 2015-0053, hindi maaaring ipamigay ang prescription samples sa pangkalahatang publiko; licensed physicians at dentists lamang ang maaaring tumanggap ng ganitong sample ayon sa tuntunin.",
                "start_ms": 33640,
                "end_ms": 49560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang salitang “libre” ay hindi patunay na puwedeng tanggapin o ipamigay.",
                "start_ms": 49860,
                "end_ms": 55700
              }
            ]
          }
        },
        "independent-information": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/independent-information.en.3ae50596dd3f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3ae50596dd3f2be66a13c659fbb3ce5de119703fa114cb5fabdd790c4f672e32",
            "sha256": "6ece06dce043002dbe54fb873b5c0cc398551132520b3097d53b60ca93a76b87",
            "duration_seconds": 41.456,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Information independent of promotion",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi does not endorse a brand.",
                "start_ms": 3260,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She uses information approved for the facility’s health education and asks the health team to review company materials.",
                "start_ms": 6360,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Following local guidance, she records or reports the product, offer, requested activity, time and place, without patient data.",
                "start_ms": 15060,
                "end_ms": 26420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not blame families for their feeding choices.",
                "start_ms": 26720,
                "end_ms": 30080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Refer feeding, medicine, or treatment questions to a trained health professional.",
                "start_ms": 30380,
                "end_ms": 35580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Keep health information independent of company influence; report facts.",
                "start_ms": 35880,
                "end_ms": 41400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/independent-information.fil.a1315e1f3c96.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a1315e1f3c965d94c1f3c1ebefe63842b9c80e3e207e996f41902ed8f8c27e6f",
            "sha256": "28c30b66f1d8efea07d7d8bc2dc7c21b978e20015b8a3b7b8f1af8db62801ddd",
            "duration_seconds": 46.55,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Impormasyong hiwalay sa promosyon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi nag-eendorso si Mimi ng brand.",
                "start_ms": 2820,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ginagamit niya ang impormasyong inaprubahan para sa health education ng pasilidad at ipinapatingin sa health team ang materyal ng kumpanya.",
                "start_ms": 5960,
                "end_ms": 15280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinatala o iniuulat niya ang produkto, alok, hinihinging gawain, at oras at lugar ayon sa lokal na gabay, nang walang datos ng pasyente.",
                "start_ms": 15580,
                "end_ms": 28060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Walang sisihin sa paraan ng pagpapakain ng pamilya.",
                "start_ms": 28360,
                "end_ms": 31760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang tanong sa pagpapakain, gamot, o paggamot ay idulog sa trained health professional.",
                "start_ms": 32060,
                "end_ms": 39740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihiwalay ang kalusugang impormasyon sa impluwensya ng kumpanya; mag-ulat ng katotohanan.",
                "start_ms": 40040,
                "end_ms": 46480
              }
            ]
          }
        },
        "pause-route": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/pause-route.en.76d53bad6dae.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "76d53bad6daeaca4af87b95316f3c230c963c9b3c42d20b0e4f7a2c778242985",
            "sha256": "48c058bd981a73a72c59b062b060a2a8aed40ca97febe845e6f6b7197e5b6000",
            "duration_seconds": 53.133,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pause and coordinate",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi says: “Thank you for approaching us.",
                "start_ms": 2820,
                "end_ms": 6620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "I will not accept or distribute these items.",
                "start_ms": 6920,
                "end_ms": 10600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "I will refer the details to the facility supervisor.”",
                "start_ms": 10900,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not hang the tarpaulin or pass samples to families.",
                "start_ms": 14960,
                "end_ms": 19560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "AO 2015-0053 prohibits using a government facility for pharmaceutical or medical-device promotion, with a stated exception for scientific conventions.",
                "start_ms": 19860,
                "end_ms": 36540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The supervisor checks the applicable process and required authorization; a BHW cannot create an exception independently.",
                "start_ms": 36840,
                "end_ms": 47200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not accept an inducement to promote; route the offer to the supervisor.",
                "start_ms": 47500,
                "end_ms": 53060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/pause-route.fil.4df99ce68ae7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4df99ce68ae74ae6427aae8307e45ded79b0478da822a8dbee1f025a5ee295ea",
            "sha256": "a37189171524eb41b36f0d16631625ff0f7fb91d390ed392887c5d82bbd0aa70",
            "duration_seconds": 55.406,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Huminto at makipag-ugnayan",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ni Mimi: “Salamat po sa paglapit.",
                "start_ms": 3260,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ko po tatanggapin o ipamamahagi ang mga ito.",
                "start_ms": 7280,
                "end_ms": 11160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Idudulog ko ang detalye sa namamahala ng pasilidad.”",
                "start_ms": 11460,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi niya ipinaskil ang tarpaulin o ipinasa ang sample sa mga pamilya.",
                "start_ms": 15480,
                "end_ms": 21600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa government facility, ipinagbabawal ng AO 2015-0053 ang paggamit nito para sa pharmaceutical o medical-device promotion; may nakasaad na exception para sa scientific conventions.",
                "start_ms": 21900,
                "end_ms": 38140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang namamahala ang magtitiyak ng naaangkop na proseso at kinakailangang awtorisasyon; hindi maaaring gumawa ang BHW ng sariling exception.",
                "start_ms": 38440,
                "end_ms": 49520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag tanggapin ang insentibo para magpromote; idulog ang alok sa namamahala.",
                "start_ms": 49820,
                "end_ms": 55340
              }
            ]
          }
        },
        "recognition-check": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/recognition-check.en.b779d63ae4de.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b779d63ae4def03cf0ddb59be0742e1b9bae8ee76af80f24b2c6a5d63687676d",
            "sha256": "bdac58cf0b885a6bd5d9c7e78332914059ff63dc678f1c7bef0a9b4951323835",
            "duration_seconds": 51.853,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Recognize before deciding",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Two offers arrive.",
                "start_ms": 2660,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Offer A: infant-formula samples for mothers, a BHS product poster, and a gift if Mimi helps promote.",
                "start_ms": 4960,
                "end_ms": 15240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Offer B: an anatomical model for a scientific activity already coordinated by the supervisor, with no endorsement in return.",
                "start_ms": 15540,
                "end_ms": 25060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The two are not automatically identical.",
                "start_ms": 25360,
                "end_ms": 28480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The pharmaceutical order permits certain educational items under conditions, but that does not authorize a BHW to accept independently.",
                "start_ms": 28780,
                "end_ms": 39060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "What is the correct recognition and first step?",
                "start_ms": 39360,
                "end_ms": 43080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Recognize promotion and inducement, pause, and confirm scope and authorization with the supervisor.",
                "start_ms": 43380,
                "end_ms": 51780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/recognition-check.fil.fe00228add06.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fe00228add062ed748cfc9d43d3e8b6d4bd805278692a6fc65077c261bc184af",
            "sha256": "f11e6b77dd6ab8da16e99ffc0ee2f007375746ba661cbb2cc8846797fda011bc",
            "duration_seconds": 57.652,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kilalanin bago magpasya",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dalawang alok ang dumating.",
                "start_ms": 3740,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Alok A: sample ng infant formula para sa mga nanay, product poster sa BHS, at regalo kay Mimi kung tutulong siyang magpromote.",
                "start_ms": 5960,
                "end_ms": 17360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alok B: anatomical model para sa scientific activity na iniugnay na ng namamahala, walang kapalit na pag-endorso.",
                "start_ms": 17660,
                "end_ms": 28220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi awtomatikong magkakapareho ang dalawa.",
                "start_ms": 28520,
                "end_ms": 32520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "May mga kondisyong pinapayagang educational items sa pharmaceutical order, ngunit hindi ito pahintulot para tumanggap ang BHW nang mag-isa.",
                "start_ms": 32820,
                "end_ms": 44500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ano ang tamang pagkilala at unang hakbang?",
                "start_ms": 44800,
                "end_ms": 48960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kilalanin ang promosyon at insentibo, huminto, at tiyakin sa namamahala ang saklaw at awtorisasyon.",
                "start_ms": 49260,
                "end_ms": 57580
              }
            ]
          }
        },
        "section-1": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/section-1.en.2b107ad834f8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2b107ad834f811b92ea57e1fe7d428b6792c89bbcb63b3c9caff9a8f96a86200",
            "sha256": "99d0e18e88d95d9706324c871473058e7c9ffaf453aac8d6c1b02c994932d415",
            "duration_seconds": 39.184,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The visitor at the BHS",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A milk-company representative arrives at BHW Mimi’s barangay health station with samples, a tarpaulin, and a small gift.",
                "start_ms": 2860,
                "end_ms": 13060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Please give the samples to mothers and hang the tarpaulin.",
                "start_ms": 13360,
                "end_ms": 17120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The gift is for you.”",
                "start_ms": 17420,
                "end_ms": 20220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mimi listens: what product is being offered, and what is expected in return?",
                "start_ms": 20520,
                "end_ms": 27440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She does not accept, display, or distribute the items.",
                "start_ms": 27740,
                "end_ms": 33660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "First recognize the offer and what is expected in return.",
                "start_ms": 33960,
                "end_ms": 39120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/section-1.fil.547de947c69e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "547de947c69e68a03d0e437d5f1bb8d6462ec255665896bfc328bfe40be188a5",
            "sha256": "a3553a6376acedc02a1fda0c2e36f36c48515b6085de8c99afd913c241fca93e",
            "duration_seconds": 42.162,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang bisita sa BHS",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May dumating na kinatawan ng kumpanya ng gatas sa barangay health station ni BHW Mimi.",
                "start_ms": 3140,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May dala siyang mga sample, tarpaulin, at maliit na regalo.",
                "start_ms": 10280,
                "end_ms": 15560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Ipamigay po ninyo sa mga nanay ang mga sample at isabit ang tarpaulin.",
                "start_ms": 15860,
                "end_ms": 21740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Para po sa inyo ang regalo.”",
                "start_ms": 22040,
                "end_ms": 24560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Nakinig si Mimi: ano ang produktong iniaalok, at ano ang hinihinging kapalit?",
                "start_ms": 24860,
                "end_ms": 32340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya tinanggap, ipinaskil, o ipinamahagi ang mga ito.",
                "start_ms": 32640,
                "end_ms": 37440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kilalanin muna ang alok at hinihinging kapalit bago kumilos.",
                "start_ms": 37740,
                "end_ms": 42100
              }
            ]
          }
        },
        "section-2": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/section-2.en.5da497ea5a5f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5da497ea5a5f267e9c68bba8059ab5a0f963e5eaed6fb272188864e7a785879c",
            "sha256": "332078ead43ecf99f2f2af2b51c734dd37ea23c5381de2614d9fa39636dcc54c",
            "duration_seconds": 44.931,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Two policy topics",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The Milk Code covers infant formula, other products marketed as breastmilk replacements, and feeding bottles and teats.",
                "start_ms": 2380,
                "end_ms": 11660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It prohibits promotion and product posters in health-care facilities and inducements to health workers to promote covered products.",
                "start_ms": 11960,
                "end_ms": 20680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "DOH AO 2015-0053 has separate rules for prescription pharmaceutical products and medical devices.",
                "start_ms": 20980,
                "end_ms": 30860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "It includes prohibitions and activities allowed under conditions; the two policies have different scopes.",
                "start_ms": 31160,
                "end_ms": 39120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check the product and applicable policy; offers are not all identical.",
                "start_ms": 39420,
                "end_ms": 44860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-promotions/section-2.fil.4d662554b95e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4d662554b95e72e22ce3d71460a649a2761faa34d88575a86155749f89fe7c1f",
            "sha256": "8c06f1244532f584f3b0e6114d01da450d44a0f64d65884291a4d3a4a86c42cb",
            "duration_seconds": 50.887,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Dalawang paksa ng polisiya",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Saklaw ng Milk Code ang infant formula, iba pang produktong ipinakikilalang pamalit sa gatas ng ina, at feeding bottles at teats.",
                "start_ms": 2820,
                "end_ms": 13260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinagbabawal nito ang promosyon at product posters sa health-care facilities at insentibo sa health workers para magpromote.",
                "start_ms": 13560,
                "end_ms": 22880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May hiwalay na tuntunin ang DOH AO 2015-0053 para sa prescription pharmaceutical products at medical devices.",
                "start_ms": 23180,
                "end_ms": 35540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May mga ipinagbabawal at may kondisyong pinapayagang gawain; hindi pareho ang saklaw ng dalawang polisiya.",
                "start_ms": 35840,
                "end_ms": 44000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang produkto at naaangkop na polisiya; hindi magkakapareho ang lahat ng alok.",
                "start_ms": 44300,
                "end_ms": 50820
              }
            ]
          }
        }
      }
    },
    "bhs-resources": {
      "module": "03-polisiya-bhs",
      "sections": {
        "check-before-change": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/check-before-change.en.fc4c079fd46f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fc4c079fd46f372f339e7727b54e701a2edeb23fca6e46ec7eaad995cac8c74c",
            "sha256": "afcde707b745e4c9e8b12af72e2cc81e09245cb5d26ea658324a6127af37f650",
            "duration_seconds": 64.653,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Coordinate before acting",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi tells the confirmed responsible person: “I noticed the lights and fan were on in the meeting area after the meeting.",
                "start_ms": 2540,
                "end_ms": 10580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Is another activity planned?",
                "start_ms": 10880,
                "end_ms": 13160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What is the closing rule, and who is responsible?”",
                "start_ms": 13460,
                "end_ms": 17300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She explains the specific observation and her questions instead of announcing a change she has already made.",
                "start_ms": 17600,
                "end_ms": 25400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "In this example, they agree first to review the schedule and existing checklist with the person responsible.",
                "start_ms": 25700,
                "end_ms": 33020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Mimi records that agreed first step if the local process requires it.",
                "start_ms": 33320,
                "end_ms": 38880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "This does not automatically approve shutdowns or cuts.",
                "start_ms": 39180,
                "end_ms": 43740
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If the rule or authority is unclear, ask for guidance before changing anything.",
                "start_ms": 44040,
                "end_ms": 50080
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Lesson 1.3.5 develops one detailed suggestion; here the focus is appropriate first coordination.",
                "start_ms": 50380,
                "end_ms": 58620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Share the observation, check the rule, and clarify the first step.",
                "start_ms": 58920,
                "end_ms": 64600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/check-before-change.fil.6b5081767a81.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6b5081767a81917df4e30c9db84bc7995e566a528ec1d7c67e278122f84b10f0",
            "sha256": "7a1b569ac3b9bc75dac43f1f28ac0184bd7645d4cf4ba756982a55a1b8d8fba4",
            "duration_seconds": 68.075,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makipag-ugnayan bago kumilos",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ni Mimi sa kinumpirmang namamahala: “Napansin ko pong nakabukas ang ilaw at fan sa meeting area matapos ang meeting.",
                "start_ms": 3020,
                "end_ms": 11100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May susunod po bang gagamit?",
                "start_ms": 11400,
                "end_ms": 13400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano po ang tuntunin sa pagsasara, at sino ang responsable?”",
                "start_ms": 13700,
                "end_ms": 18940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipinapaliwanag niya ang tiyak na obserbasyon at mga tanong, hindi nag-aanunsiyo ng ginawa nang pagbabago.",
                "start_ms": 19240,
                "end_ms": 26160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa halimbawa, pinagkasunduan nilang suriin muna ang schedule at umiiral na checklist kasama ang taong responsable.",
                "start_ms": 26460,
                "end_ms": 34620
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Itatala ni Mimi ang napagkasunduang unang hakbang kung kailangan sa lokal na proseso.",
                "start_ms": 34920,
                "end_ms": 40840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Walang awtomatikong approval sa pagsara o pagbabawas.",
                "start_ms": 41140,
                "end_ms": 45140
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung hindi pa malinaw ang tuntunin o saklaw ng pahintulot, magpatulong bago magbago.",
                "start_ms": 45440,
                "end_ms": 52520
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Sa 1.3.5, gagawa ng isang detalyadong mungkahi; dito, mahalaga ang tamang unang pakikipag-ugnayan.",
                "start_ms": 52820,
                "end_ms": 61860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaalam ang obserbasyon, tiyakin ang tuntunin, at linawin ang unang hakbang.",
                "start_ms": 62160,
                "end_ms": 68000
              }
            ]
          }
        },
        "know-responsibilities": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/know-responsibilities.en.eaa7226fc3db.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eaa7226fc3dbf9e99b30ccea05bea4a1230a37d3e7dca0166681da5771833d9a",
            "sha256": "05a60cd8116d0d5d282f5c699b7b2b292a0c13e77994243da426111b04109c57",
            "duration_seconds": 54.988,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Check the policy and responsibility",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi does not assume she makes the decision because she noticed the concern.",
                "start_ms": 3860,
                "end_ms": 9460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks the confirmed responsible person: “Who is responsible for the meeting area after use?",
                "start_ms": 9760,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Is there a closing checklist, and who may authorize a change?”",
                "start_ms": 17060,
                "end_ms": 22180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The right contact may be the midwife, facility supervisor or another designated person at their BHS; confirm local responsibilities rather than assuming one universal chain of command.",
                "start_ms": 22480,
                "end_ms": 35920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If the contact is absent, follow the local referral process.",
                "start_ms": 36220,
                "end_ms": 41340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A colleague agreeing with an idea does not automatically authorize it.",
                "start_ms": 41640,
                "end_ms": 46640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The action must comply with policy and the limits of the role.",
                "start_ms": 46940,
                "end_ms": 51300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm local responsibility and permission.",
                "start_ms": 51600,
                "end_ms": 54920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/know-responsibilities.fil.70009ede4d3b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "70009ede4d3b13f3553642856f64b181f12ceff3cedf940571b6359823407476",
            "sha256": "fd2153c49df65f4b1ebf0a8d48a2d1f90ea6f8c059befa8f2369eba24a5b177c",
            "duration_seconds": 58.384,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Alamin ang tuntunin at tungkulin",
                "start_ms": 0,
                "end_ms": 3640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi ipinapalagay ni Mimi na siya ang magdedesisyon dahil siya ang nakapansin.",
                "start_ms": 3940,
                "end_ms": 8700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itatanong niya sa kinumpirmang namamahala: “Sino po ang responsable sa meeting area pagkatapos gamitin?",
                "start_ms": 9000,
                "end_ms": 16520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May closing checklist po ba, at sino ang maaaring magpahintulot ng pagbabago?”",
                "start_ms": 16820,
                "end_ms": 22740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring midwife, facility supervisor o ibang itinalagang tao ang tamang contact sa kanilang BHS; tiyakin ang lokal na tungkulin, huwag manghula ng iisang chain of command para sa lahat.",
                "start_ms": 23040,
                "end_ms": 37120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung wala ang contact, sundin ang lokal na proseso para sa pagdulog.",
                "start_ms": 37420,
                "end_ms": 42020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi awtomatikong may pahintulot ang isang mungkahi dahil may pumayag na kasamahan.",
                "start_ms": 42320,
                "end_ms": 48680
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kailangang naaayon ito sa polisiya at saklaw ng tungkulin.",
                "start_ms": 48980,
                "end_ms": 53700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang lokal na responsibilidad at pahintulot.",
                "start_ms": 54000,
                "end_ms": 58320
              }
            ]
          }
        },
        "observe-resource-use": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/observe-resource-use.en.20a90d9e06d7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "20a90d9e06d7ec76ab10b5e8fb8b9f9eb605aa34413584f8f1fbaf70a6e797d6",
            "sha256": "9cf32c504eba5e9a15e24bb601ef33ab85008185fc77444c332f2d9f99787acf",
            "duration_seconds": 54.491,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Describe what you observed",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional example, Mimi records: “After the meeting, the lights and fan were on in the meeting area; I saw no one there when I checked.”",
                "start_ms": 2660,
                "end_ms": 12300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She does not write that a colleague is careless or that a particular amount of money is definitely being wasted.",
                "start_ms": 12600,
                "end_ms": 20880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She does not yet know whether another activity is planned or there is another reason.",
                "start_ms": 21180,
                "end_ms": 27060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If a local record is needed, include only the date, time, place and specific observation.",
                "start_ms": 27360,
                "end_ms": 35920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Omit patient names or data, guesses about motives, and invented consumption or savings measurements.",
                "start_ms": 36220,
                "end_ms": 43060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "An observation starts a conversation; it is not a conclusion or permission to change something.",
                "start_ms": 43360,
                "end_ms": 50520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "State the facts and what is still unknown.",
                "start_ms": 50820,
                "end_ms": 54420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/observe-resource-use.fil.d745e9469524.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d745e9469524c1e5441c122eb4d0af062b76262d87f27d257d3719a9f520753e",
            "sha256": "c47ce375795c15487b8cbe17e02fc3c2e53bed6bc31dd571f7efa192ee948768",
            "duration_seconds": 55.928,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ilarawan ang nakita",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa fictional na halimbawa, itinala ni Mimi: “Pagkatapos ng meeting, nakabukas ang ilaw at fan sa meeting area; wala akong nakitang tao roon sa oras ng pagtingin.”",
                "start_ms": 2220,
                "end_ms": 14420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya isinulat na pabaya ang kasamahan o tiyak na nasasayang ang isang halaga ng pera.",
                "start_ms": 14720,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa niya alam kung may susunod na gawain o ibang dahilan.",
                "start_ms": 22220,
                "end_ms": 26660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung kailangan ng lokal na tala, ilagay lamang ang petsa, oras, lugar at tiyak na napansin.",
                "start_ms": 26960,
                "end_ms": 34600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang pangalan o datos ng pasyente, haka-haka sa motibo, o imbentong sukat ng konsumo at savings.",
                "start_ms": 34900,
                "end_ms": 43380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang obserbasyon ay simula ng pag-uusap, hindi pa hatol o pahintulot na magbago.",
                "start_ms": 43680,
                "end_ms": 50600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Katotohanan muna; sabihin din ang hindi pa alam.",
                "start_ms": 50900,
                "end_ms": 55860
              }
            ]
          }
        },
        "protect-service": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/protect-service.en.6faccbea258d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6faccbea258d58da5ab766b3dd4675a43cd95062bc2af2e046f8c65945c16df9",
            "sha256": "a831b3d3d56b3090db7fc3e2d6bff7981fb58e89b2716f83b7904c0413424f1d",
            "duration_seconds": 58.018,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Protect service needs",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A colleague says: “Let us reduce the supplies on the shelf to save resources.”",
                "start_ms": 2540,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mimi does not do this independently.",
                "start_ms": 8400,
                "end_ms": 11120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Those supplies may be needed for service; noticing lights in a meeting area is different from deciding which supplies to reduce.",
                "start_ms": 11420,
                "end_ms": 19780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For the meeting area, she first checks the next planned use, requirements for the area, and who is responsible for the closing procedure.",
                "start_ms": 20080,
                "end_ms": 29200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She does not repair electrical systems, operate clinical equipment controls, reuse clinical supplies or ration services.",
                "start_ms": 29500,
                "end_ms": 39900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "If there is a possible hazard, refer it through the local safety process; do not attempt repairs beyond training.",
                "start_ms": 40200,
                "end_ms": 48080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "A nonclinical example is not automatically free of safety risks.",
                "start_ms": 48380,
                "end_ms": 53340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not independently make cuts that may compromise service.",
                "start_ms": 53640,
                "end_ms": 57960
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/protect-service.fil.19fa1616e5de.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "19fa1616e5de47f0edbe00ec9ece327da4e7a7c37758d2937a232f08aaa71dda",
            "sha256": "7e5fceecf394a8e06fe51b644a42b36e07c66f4b896cc313fee1df8eedbaa864",
            "duration_seconds": 64.104,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Unahin ang kailangan ng serbisyo",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ng isang kasamahan: “Bawasan na lang natin ang gamit sa shelf para makatipid.”",
                "start_ms": 3220,
                "end_ms": 9180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ito ginagawa ni Mimi nang kusa.",
                "start_ms": 9480,
                "end_ms": 12280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaaring kailangan ang mga gamit para sa serbisyo; hindi pareho ang napansing ilaw sa meeting area at pagpapasya kung aling supply ang babawasan.",
                "start_ms": 12580,
                "end_ms": 22700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa meeting area, aalamin muna kung may susunod na gawain, kung may requirement sa lugar, at kung sino ang may responsibilidad sa closing procedure.",
                "start_ms": 23000,
                "end_ms": 34240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi siya nagkukumpuni ng kuryente, humahawak ng controls ng clinical equipment, nagre-reuse ng clinical supplies o nagrarasyon ng serbisyo.",
                "start_ms": 34540,
                "end_ms": 45740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung may posibleng panganib, idulog ayon sa lokal na safety process; huwag subukang ayusin nang lampas sa pagsasanay.",
                "start_ms": 46040,
                "end_ms": 53880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kahit nonclinical ang halimbawa, hindi awtomatikong walang safety risk.",
                "start_ms": 54180,
                "end_ms": 59980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang sariling pagbawas na maaaring makasira sa serbisyo.",
                "start_ms": 60280,
                "end_ms": 64040
              }
            ]
          }
        },
        "resource-check": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/resource-check.en.9f200f222363.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9f200f22236340791b1d9aaec473aca6630058643d6b1a58a0a4e6a2cc8660f8",
            "sha256": "c0682e15f22dffd69e4611f3d6a7cb1bcb10fb63e8808a42bdcdb55ed5917b51",
            "duration_seconds": 33.541,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first step",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "After an activity, you see the lights and fan on in an empty meeting area.",
                "start_ms": 2020,
                "end_ms": 7900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "You do not yet know the next scheduled use or closing procedure.",
                "start_ms": 8200,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A colleague wants to reduce supplies to save resources.",
                "start_ms": 13020,
                "end_ms": 17180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "What is your appropriate first step as a BHW?",
                "start_ms": 17480,
                "end_ms": 21400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose and explain your answer, then practice stating what you would report and ask.",
                "start_ms": 21700,
                "end_ms": 27900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Observation → Rule and responsibility → Coordination.",
                "start_ms": 28200,
                "end_ms": 33480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-resources/resource-check.fil.af44af166c9b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "af44af166c9b91554ac10250a66b3d68221a09a6a7209d73477017276b4a8a7f",
            "sha256": "90194ab9acb6571423da239697aa250a713dbea84ed2443ffe8f1f325af91b20",
            "duration_seconds": 40.751,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang hakbang",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos ng isang gawain, nakita mong nakabukas ang ilaw at fan sa bakanteng meeting area.",
                "start_ms": 3460,
                "end_ms": 11020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi mo pa alam ang susunod na schedule o closing procedure.",
                "start_ms": 11320,
                "end_ms": 15600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May kasamahang gustong magbawas ng supplies para makatipid.",
                "start_ms": 15900,
                "end_ms": 20300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ano ang angkop mong unang hakbang bilang BHW?",
                "start_ms": 20600,
                "end_ms": 25720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin at ipaliwanag ang sagot, saka sabihin sa sariling pananalita ang iuulat at itatanong mo.",
                "start_ms": 26020,
                "end_ms": 33500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Obserbasyon → Tuntunin at responsibilidad → Pakikipag-ugnayan.",
