                "end_ms": 22120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi niya sinasabing ligtas ito sa bahay.",
                "start_ms": 22420,
                "end_ms": 25740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ipinasusuri niya kung malawak o delikado ang lokasyon.",
