            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1c6f3124e9d0f16b996822a262530b5aa144e51f6c65f07fbfc2670ea7721864",
            "sha256": "5fa29cccd2d4e1ca1bd76244db49bed1185b17a13c42abd3be0df07d5c8c2039",
            "duration_seconds": 29.179,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Activate urgent medical assessment and keep the person at rest while following responder directions.",
                "start_ms": 2540,
                "end_ms": 9940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Report onset, symptoms and known medicines or allergies.",
                "start_ms": 10240,
                "end_ms": 15840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Medication decisions follow the current local protocol and qualified advice.",
                "start_ms": 16140,
                "end_ms": 21900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Activate the urgent pathway and hand over onset and symptoms without prescribing aspirin.",
                "start_ms": 22200,
                "end_ms": 29120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/chest-pain-referral/action.fil.6808816fb57b.mp3",
