              {
                "zone": "body",
                "index": 0,
                "text": "Humingi agad ng medikal na tulong at pagpahingahin ang tao habang sinusunod ang tagubilin.",
                "start_ms": 2460,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iulat ang simula, sintomas at alam na gamot o allergy.",
                "start_ms": 9440,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang gamot ay ayon sa kasalukuyang lokal na protocol at kwalipikadong payo.",
                "start_ms": 15500,
                "end_ms": 21540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gamitin ang agarang referral at iulat ang simula at sintomas nang hindi nagrereseta ng aspirin.",
                "start_ms": 21840,
                "end_ms": 29360
