              {
                "zone": "body",
                "index": 0,
                "text": "Call for help and follow current age-specific choking training.",
                "start_ms": 2660,
                "end_ms": 7340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Distinguish mild cough from severe obstruction.",
                "start_ms": 7640,
                "end_ms": 11640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Practise the trainer-approved adult and infant pathways only on appropriate manikins.",
                "start_ms": 11940,
                "end_ms": 18900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "With two training manikins, classify cough versus severe obstruction and show the supervised age-specific response.",
