            "src": "/training/audio/chapter2/04-first-aid/choking-response/scene.en.29a20dfe4ffe.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "29a20dfe4ffe3e7dbf8fb07adb34afd2e08106134dd9d25596826762c42f3e3d",
            "sha256": "9ff392766b9ef8735d08351a6b023b7c3418f1474a94b62b004be5170fa33b86",
            "duration_seconds": 17.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At lunch, an adult cannot speak or cough effectively.",
                "start_ms": 2020,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A nearby infant case card shows a different age pathway.",
                "start_ms": 6880,
                "end_ms": 11360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: At lunch, an adult cannot speak or cough effectively",
                "start_ms": 11660,
                "end_ms": 17540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scene.fil.cf9929b1d9dd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf9929b1d9dd16761b497c93933f205d7a3034ac8114c31ce22fc580c3963ad1",
            "sha256": "ac59b2643addb39411e253dae960494e97191517c52b77f9873576dd60751eb9",
            "duration_seconds": 17.763,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa tanghalian, hindi makapagsalita o makaubo nang mabisa ang adult.",
                "start_ms": 2860,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May hiwalay na case card ng sanggol.",
                "start_ms": 8680,
                "end_ms": 11720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Hindi makapagsalita o makaubo nang mabisa ang adult",
                "start_ms": 12020,
                "end_ms": 17700
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scope.en.d6c6afb89afe.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d6c6afb89afe888d5355b4416762878e601c1fab3e3fb257571f74ab90cdbf83",
            "sha256": "cb2d8b460f47ecee12ca07b2a221fb656da6471de57762b6ec7f63374c173e85",
            "duration_seconds": 19.513,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not apply adult abdominal thrusts to an infant, use blind finger sweeps, or rehearse thrusts on a live partner.",
                "start_ms": 2780,
                "end_ms": 12100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No adult thrusts on an infant, no blind finger sweeps, no thrusts on a live partner.",
                "start_ms": 12400,
                "end_ms": 19440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scope.fil.2cc73918f3e3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2cc73918f3e366022ec5996ed1a04240dd8d7ca90a9eb805daac5f22582ebdd3",
            "sha256": "4db1dc835a9c7785328d812403b451084e9a2ac83a2ab05d15b62cbb6a6d6d4b",
            "duration_seconds": 20.297,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag gumamit ng abdominal thrust sa sanggol, bulag na paghugot sa bibig, o magsanay ng thrust sa totoong kapareha.",
                "start_ms": 3100,
                "end_ms": 12020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang adult thrust sa sanggol, walang bulag na paghugot sa bibig, walang thrust sa totoong kapareha.",
                "start_ms": 12320,
                "end_ms": 20240
              }
            ]
          }
        }
      }
    },
    "communication-clarify": {
      "module": "06-komunikasyon",
      "sections": {
        "barriers": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/barriers.en.485918ef4bd5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "485918ef4bd53afd43dd302462ac653f51bf70c2c6f2ff92ec25ed60a27df297",
            "sha256": "138bc79d22219fc6ea12f31911452438312809a280a23493d68f27a88a301e6f",
            "duration_seconds": 41.012,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What was unheard in Rosario’s story",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the Rosario case studied in Module 7, poverty, service gaps and misinformation affect the family together.",
                "start_ms": 3540,
                "end_ms": 13180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Why didn’t you follow instructions?”",
                "start_ms": 13480,
                "end_ms": 16280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "is not enough.",
                "start_ms": 16580,
                "end_ms": 18180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“What were you told, and what prevented you from getting help?”",
                "start_ms": 18480,
                "end_ms": 22800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "is more useful.",
                "start_ms": 23100,
                "end_ms": 24740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Communication brings barriers into view and clarifies them.",
                "start_ms": 25040,
                "end_ms": 30080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The next module examines which partners can address them.",
                "start_ms": 30380,
                "end_ms": 34540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A barrier to services is important information, not a reason to judge a family.",
                "start_ms": 34840,
                "end_ms": 40960
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/barriers.fil.40a688e56fc6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "40a688e56fc670def86c279d368a9c08798ec431f7151f3ebb64b2408bb9f384",
            "sha256": "a88ab90163d508ec69d1ad94f40bcb5a27165bc808a43690f4c31cd7e32d1a7a",
            "duration_seconds": 44.826,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang hindi narinig sa kuwento ni Rosario",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kasong Rosario na pag-aaralan sa Modyul 7, sabay-sabay ang kahirapan, kakulangan sa serbisyo at maling impormasyong natanggap ng pamilya.",
                "start_ms": 3700,
                "end_ms": 14220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi sapat ang tanong na “Bakit hindi kayo sumunod?”",
                "start_ms": 14520,
                "end_ms": 18600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mas makabuluhan ang “Ano ang sinabi sa inyo, at ano ang pumigil sa pagkuha ng tulong?”",
                "start_ms": 18900,
                "end_ms": 25820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa komunikasyon, ang gawain ay ilabas at linawin ang hadlang.",
                "start_ms": 26120,
                "end_ms": 31480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa susunod na modyul, susuriin kung sino-sinong kasosyo ang makakatugon dito.",
                "start_ms": 31780,
                "end_ms": 37900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang hadlang sa serbisyo ay mahalagang impormasyon, hindi dahilan para husgahan ang pamilya.",
                "start_ms": 38200,
                "end_ms": 44760
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/check.en.d9b7b1ad1149.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d9b7b1ad114977bcf5436c2cfeaad85ec42dee43184b49be59a5fbdcec5b6175",
            "sha256": "cb1aaa1d88eb0b3986d0fc9823fbd1f04eec507ed17c875d94b17ba7595fd855",
            "duration_seconds": 16.927,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2100,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7240,
                "end_ms": 10720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A clear question elicits information rather than the answer we expect.",
                "start_ms": 11020,
                "end_ms": 16860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/check.fil.58fde8ae9c90.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "58fde8ae9c902e48aadc341cd2f027eb3116598d78f8cc9ec9b742d0dd923aab",
            "sha256": "41ab14aa55dc122efa8e837f9cbea14a243f65ee411e1bb353b26a581c591bee",
            "duration_seconds": 20.297,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3220,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8680,
                "end_ms": 13480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang malinaw na tanong ay naglalabas ng impormasyon, hindi ng sagot na gusto nating marinig.",
                "start_ms": 13780,
                "end_ms": 20220
              }
            ]
          }
        },
        "open-question": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/open-question.en.2204e0aa0cc7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2204e0aa0cc7b7a59d5e73070b387b9f990a6a68313afbf18bd33804bba10acf",
            "sha256": "e3f8dca1e664d27661bf1db3d4b6274a14ba7d978311561825acb34fbbc39b8c",
            "duration_seconds": 48.98,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Open first, then clarify",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza, 29, missed a health-center visit because of childcare barriers.",
                "start_ms": 3060,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "BHW Gibs is finding out what happened.",
                "start_ms": 9360,
                "end_ms": 13320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Why don’t you follow instructions?”",
                "start_ms": 13620,
                "end_ms": 16340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "sounds like an accusation.",
                "start_ms": 16640,
                "end_ms": 19000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“What makes it hard to attend?”",
                "start_ms": 19300,
                "end_ms": 21780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "invites an explanation.",
                "start_ms": 22080,
                "end_ms": 24320
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Follow an open question with focused clarification: “When was your last visit?”",
                "start_ms": 24620,
                "end_ms": 30700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Yes-or-no questions are useful when confirming one detail.",
                "start_ms": 31000,
                "end_ms": 35520
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Avoid asking three questions at once or putting the answer into the person’s mouth.",
                "start_ms": 35820,
                "end_ms": 42140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use open questions for the story and focused questions to clarify information.",
                "start_ms": 42440,
                "end_ms": 48920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/open-question.fil.993ca87f7911.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "993ca87f791195f00348b7580ba754b4109a8d73547cabc31a2503a010814f3a",
            "sha256": "be238d1220d6fc4a507486a4211e12b2b8fc93e133f63950781aecc4b759ab2b",
            "duration_seconds": 55.719,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bukas muna, saka linawin",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Liza, 29, ay hindi nakapunta sa health center dahil may hadlang sa pag-aalaga ng anak.",
                "start_ms": 3300,
                "end_ms": 11380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inaalam ni BHW Gibs kung ano ang nangyari.",
                "start_ms": 11680,
                "end_ms": 16320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Bakit hindi ka sumusunod?”",
                "start_ms": 16620,
                "end_ms": 19180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "ay paratang na tanong.",
                "start_ms": 19480,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mas makakatulong ang “Ano ang nagpapahirap sa pagpunta mo?”",
                "start_ms": 22220,
                "end_ms": 27460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Pagkatapos ng bukas na tanong, gumamit ng tiyak na paglilinaw: “Kailan ka huling nakapunta?”",
                "start_ms": 27760,
                "end_ms": 35240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi masama ang tanong na oo o hindi kung isang detalye ang kailangang kumpirmahin.",
                "start_ms": 35540,
                "end_ms": 41900
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Iwasan ang tatlong tanong na magkakasabay at ang sagot na isinusubo na sa kausap.",
                "start_ms": 42200,
                "end_ms": 48800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bukas na tanong para sa kuwento; tiyak na tanong para sa paglilinaw ng impormasyon.",
                "start_ms": 49100,
                "end_ms": 55660
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/practice.en.79c5e81faec8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "79c5e81faec82b905e0c2de40abf469fe3794936f94b653fd7f5d6ec2555a984",
            "sha256": "cdd8b02831b3703c2b2550140f8110810437ac48b15d414f8ae2bd731550b538",
            "duration_seconds": 36.493,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Replace “Why don’t you follow instructions?”",
                "start_ms": 2860,
                "end_ms": 6500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "with an open question.",
                "start_ms": 6800,
                "end_ms": 9040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Your partner replies, “I have nobody with me.”",
                "start_ms": 9340,
                "end_ms": 12980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Clarify whether this means a travel companion or someone to watch the children, then check your summary.",
                "start_ms": 13280,
                "end_ms": 20440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, write and read the three lines aloud.",
                "start_ms": 20740,
                "end_ms": 24740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "At the next visit, clarify one ambiguous answer before recording it.",
                "start_ms": 25040,
                "end_ms": 30840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A clear question elicits information rather than the answer we expect.",
                "start_ms": 31140,
                "end_ms": 36420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/practice.fil.b1e4b5dc8e84.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b1e4b5dc8e8448bade5131e5cd4e6ba80bc5d3c62480e28d6b72da9756688bbc",
            "sha256": "436bda070e7c7544f949bbc7f8c79e2d9108a057f526ff0d278d91c982c5f49f",
            "duration_seconds": 39.915,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Palitan ang “Bakit hindi ka sumusunod?”",
                "start_ms": 2940,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "ng isang bukas na tanong.",
                "start_ms": 6880,
                "end_ms": 9000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang kapareha ay sasagot: “Wala akong kasama.”",
                "start_ms": 9300,
                "end_ms": 13420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Linawin kung kasama sa biyahe o magbabantay sa anak ang ibig sabihin, saka ipasuri ang iyong buod.",
                "start_ms": 13720,
                "end_ms": 21680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, isulat ang tatlong linya at basahin nang malakas.",
                "start_ms": 21980,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa susunod na pagbisita, maglinaw ng isang malabong sagot bago magtala.",
                "start_ms": 27320,
                "end_ms": 33400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang malinaw na tanong ay naglalabas ng impormasyon, hindi ng sagot na gusto nating marinig.",
                "start_ms": 33700,
                "end_ms": 39860
              }
            ]
          }
        }
      }
    },
    "communication-explain": {
