                "zone": "body",
                "index": 0,
                "text": "Clear nearby hazards, cushion the head if possible and note the start time.",
                "start_ms": 2900,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Seek urgent help for a child and monitor breathing after the episode.",
                "start_ms": 9360,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Give the responding clinician a factual description.",
                "start_ms": 14940,
                "end_ms": 19020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clear a simulated space, call for help, state time and observations, and reject restraint and mouth insertion.",
                "start_ms": 19320,
                "end_ms": 29520
              }
            ]
          },
