            "content_hash": "86d63af6e52243edb77a3e1e5060f7b036128949ee1cb1a29596ccb01b991161",
            "sha256": "427aeb58f6c2e773f0a40ba6f944ab509e5cec9dd2dc96f4e0f07a547fdbf46a",
            "duration_seconds": 40.725,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mahinahong sinabi ng BHW sa kapitbahay na huwag pigilan ang bata o lagyan ng kutsara ang bibig.",
                "start_ms": 2100,
                "end_ms": 10260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inalis niya ang panganib sa paligid, sinapinan ang ulo at sinabi nang malakas ang oras ng simula.",
                "start_ms": 10560,
                "end_ms": 18840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nagpatawag siya sa kumpirmadong contact at binantayan ang paghinga pagkatapos ng pangingisay.",
                "start_ms": 19140,
                "end_ms": 26620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Factual ang ulat sa clinician: ang oras ng simula at ang nakita.",
                "start_ms": 26920,
                "end_ms": 32440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tanggihan ang pagpigil at kutsara; protektahan, orasan, tumawag at iulat.",
                "start_ms": 32740,
                "end_ms": 40660
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/next-step.en.b980aa1a0d93.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b980aa1a0d93fa9d89babe7285e750a41f2a3c4f5fdc841627991e1336da15a5",
            "sha256": "da9b4b081aaff9ef33af6d26039b56e5b6d653205f6e05c32b2c1bbb3419a7cd",
            "duration_seconds": 29.414,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2540,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 8160,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Clear a simulated space, call for help, state time and observations, and reject restraint and mouth insertion.",
                "start_ms": 12500,
                "end_ms": 22180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Practise the space, time, call and a kind refusal with a new case.",
                "start_ms": 22480,
                "end_ms": 29360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/next-step.fil.7ea8ee193c42.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7ea8ee193c42506cf6d6ceb289a84ad48685baf269520652f930fe8595eaaafc",
            "sha256": "ff1892a17b175af7c2e7927123f79e0783241c6d4178229add8af95822d5c033",
            "duration_seconds": 31.269,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2660,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 8760,
                "end_ms": 12840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Linisin ang paligid sa simulation, humingi ng tulong, sabihin ang oras at nakita, at tanggihan ang pagpigil at kutsara.",
                "start_ms": 13140,
                "end_ms": 23540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang paligid, oras, tawag at mahinahong pagtanggi sa bagong kaso.",
                "start_ms": 23840,
                "end_ms": 31200
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/scene.en.9a3aa4ea9b81.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9a3aa4ea9b8182ffe5cfaaa2643f6306bfa7955d2324cff5f2bde92612eed921",
            "sha256": "abd44f2001caf912487c30556dabf85bec0919fbe0f2d741ca757182c4831b51",
            "duration_seconds": 17.006,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A child begins shaking on the floor.",
                "start_ms": 1940,
                "end_ms": 5220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A neighbor wants to hold the child down and put a spoon in the mouth.",
                "start_ms": 5520,
                "end_ms": 10200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: A child shakes on the floor; a neighbor wants to restrain and use a spoon.",
                "start_ms": 10500,
                "end_ms": 16940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/scene.fil.ebcdc72329b1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ebcdc72329b1b09a0931c8716c9bf5b305fa427d425498fdc02afd99f652584a",
            "sha256": "8a74f8e70b5e99e9a4f5cb7558be001e9b4bb90d6c01395f72854bbbd8f9dd58",
            "duration_seconds": 17.633,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nangingisay ang isang bata sa sahig.",
                "start_ms": 1620,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gustong pigilan siya ng kapitbahay at lagyan ng kutsara ang bibig.",
                "start_ms": 4840,
                "end_ms": 10080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Nangingisay ang bata; gusto siyang pigilan at lagyan ng kutsara ng kapitbahay.",
                "start_ms": 10380,
                "end_ms": 17580
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/scope.en.c77e9114258f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c77e9114258f990561366a1405101bc33623559b609586c2e4de9bf88d418268",
            "sha256": "c5a47e75df39c9ba12ba157ea25a14cd612f0acde4c03652193b5bf0671ec8ce",
            "duration_seconds": 21.943,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not restrain, put anything in the mouth, give food or drink before full alertness, or rely on wiping with cold water to stop a seizure.",
                "start_ms": 2540,
                "end_ms": 14100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No restraint, nothing in the mouth, no food or drink before full alertness.",
                "start_ms": 14400,
                "end_ms": 21880
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/scope.fil.fc31cccaa040.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fc31cccaa040c20d96f6170291ebe5079d65952ca3b6b5c31587f6ec3ec8b18b",
            "sha256": "b799485e15e5511b3bf86b512b54a7cdc4d1408cd10c158968854b62ff617ce6",
            "duration_seconds": 27.455,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag pigilan ang bata o maglagay ng anuman sa bibig.",
                "start_ms": 3220,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag magpakain o magpainom bago siya lubos na magkamalay.",
                "start_ms": 7960,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag umasa sa pagpupunas ng malamig na tubig para mapatigil ang kombulsyon.",
                "start_ms": 13220,
                "end_ms": 18780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang pagpigil, walang anuman sa bibig, walang pagkain o inumin bago lubos na magkamalay.",
                "start_ms": 19080,
                "end_ms": 27400
              }
            ]
          }
        }
      }
    },
    "cough-etiquette": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/action.en.b050a0be7bb1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b050a0be7bb1c7adf0cae39c987fc6c707b372f52932a57cc3644af741bc5efc",
            "sha256": "20c738de9e856926a1c2d225c53f4c9de7c74f3dab579ca725f1ce1b834e34f2",
            "duration_seconds": 33.228,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Cover nose and mouth with a tissue when coughing or sneezing.",
                "start_ms": 2540,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Without tissue, use the inside of a bent elbow rather than hands.",
                "start_ms": 7480,
                "end_ms": 12440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Discard used tissue in the designated bin.",
                "start_ms": 12740,
                "end_ms": 16100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Clean hands after contact with respiratory secretions.",
                "start_ms": 16400,
                "end_ms": 20720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report symptoms to staff and follow their instructions.",
                "start_ms": 21020,
                "end_ms": 25140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mime tissue and elbow methods. Show disposal and hand hygiene; explain reporting to staff.",
                "start_ms": 25440,
                "end_ms": 33160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/action.fil.677636c3e3fd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "677636c3e3fda4f2d1c6ffd9c5cb8afb7bdd2520c2b8d5a9c319cc6debbe48f6",
            "sha256": "77157bf1e83881ce0ff0b3e58a4609a483422545219e607de468705942d20741",
            "duration_seconds": 39.393,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Takpan ang ilong at bibig gamit ang tissue kapag umuubo o bumabahing.",
                "start_ms": 2420,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung walang tissue, gamitin ang loob ng nakabaluktot na siko, hindi ang palad.",
                "start_ms": 8840,
                "end_ms": 14720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itapon ang ginamit na tissue sa itinalagang basurahan.",
                "start_ms": 15020,
                "end_ms": 19060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Linisin ang kamay matapos mahawakan ang sipon o laway.",
                "start_ms": 19360,
                "end_ms": 24040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipaalam ang sintomas sa staff at sundin ang kanilang tagubilin.",
                "start_ms": 24340,
                "end_ms": 29220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gayahin ang tissue at elbow methods. Ipakita ang pagtatapon at hand hygiene; ipaliwanag ang pag-uulat sa staff.",
                "start_ms": 29520,
                "end_ms": 39320
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-start.en.cf5abf76bb2c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf5abf76bb2cde4de67fa9acb298e9c220c1e7a55b17b76569ea3779a44e4d79",
            "sha256": "bc33e2f4a63ee1fd73892005101643b266f52d9d0a087bff8f1caa4809a5369f",
            "duration_seconds": 13.531,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2820,
                "end_ms": 5220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5520,
                "end_ms": 8960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This covers nose and mouth without using hands.",
                "start_ms": 9260,
                "end_ms": 13460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-start.fil.a5aae9f00f05.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a5aae9f00f05dddad27e7f89e25a82d1ab439908d779a5dca51b144b665bdbe0",
            "sha256": "40eba7b1ec8e9e91a564175b0f9994ff148547f6f8d296bfe99c2bab2732f26f",
            "duration_seconds": 15.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2900,
                "end_ms": 5260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5560,
                "end_ms": 10360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Natatakpan ang ilong at bibig nang hindi ginagamit ang palad.",
                "start_ms": 10660,
                "end_ms": 15060
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-transfer.en.408a1dda4a79.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "408a1dda4a79f4a057989ad3470c86025e86ba9fc6ae76261faaf0896320ec98",
            "sha256": "d2d6049df6667a487dedc80744b5a661e7035a50e9412340ff42112476cb64cf",
            "duration_seconds": 11.807,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2740,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hand hygiene is part of the complete sequence.",
                "start_ms": 8180,
                "end_ms": 11740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-transfer.fil.e34bd4598481.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e34bd45984811d76d5ff0b35fd490483383abf00421a033e2bcc819a551bdc7e",
            "sha256": "4b99e801bab5cb808d12d0b0cbad990bd9beabb3c17748f123864161780be1a3",
            "duration_seconds": 13.923,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 4180,
                "end_ms": 5940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 6240,
                "end_ms": 9560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bahagi ng kumpletong sequence ang hand hygiene.",
                "start_ms": 9860,
                "end_ms": 13860
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/example.en.e6f09eaf1813.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6f09eaf1813ece20425e5b48d6f51ffe0a1a8b37511208e278f425ed556793b",
            "sha256": "a952b82803c3c1e9edb58d3ff7e557967d7517b87527a81b7eb7437f05c6ae17",
            "duration_seconds": 34.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rina: “Tissues are available here.",
                "start_ms": 2100,
                "end_ms": 4940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If none are available, sneeze into your elbow.”",
                "start_ms": 5240,
                "end_ms": 8880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She points out the bin and hand-hygiene station.",
                "start_ms": 9180,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She reports symptoms and asks staff about the waiting area.",
                "start_ms": 12840,
                "end_ms": 17200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Follow the facility protocol and staff assistance for a recommended mask.",
                "start_ms": 17500,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She does not diagnose Mang Lito.",
                "start_ms": 23640,
                "end_ms": 26520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Rina offers a tissue or the elbow, points to the bin and hand hygiene, and reports to staff.",
                "start_ms": 26820,
                "end_ms": 34220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/example.fil.01a6166d8be4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "01a6166d8be42ecef63fce1db6a637d9b548c8e6b7ab310fae13707d4e666b59",
            "sha256": "b98243dec1617dc59dc6a47e1518e38324919b2a3b179460c0173d9a726e9740",
            "duration_seconds": 36.441,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rina: “May tissue po rito.",
                "start_ms": 1980,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung wala, sa siko po tayo bumahing.”",
                "start_ms": 5000,
                "end_ms": 8240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinuro niya ang basurahan at hand-hygiene station.",
                "start_ms": 8540,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipinaalam niya sa staff ang sintomas at tinanong ang waiting area.",
                "start_ms": 12840,
