            "duration_seconds": 34.011,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gayahin lamang ang kilos sa practice; huwag talagang umubo o dumura sa kapareha.",
                "start_ms": 3420,
                "end_ms": 9660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag hawakan ang ginamit na tissue ng iba nang walang angkop na pamamaraan.",
                "start_ms": 9960,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang pagtakip ng sariling bibig kapag may umuubo ay hindi kapalit ng respiratory controls.",
                "start_ms": 15780,
                "end_ms": 22460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Igalang ang pribadong impormasyon habang nag-uulat.",
                "start_ms": 22760,
                "end_ms": 27200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gayahin lamang; huwag umubo sa kapareha, at igalang ang privacy sa pag-uulat.",
                "start_ms": 27500,
                "end_ms": 33940
              }
            ]
          }
