            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Activate help and request an AED.",
                "start_ms": 2500,
                "end_ms": 5780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Follow the current adult BLS algorithm demonstrated by a qualified trainer.",
                "start_ms": 6080,
                "end_ms": 12120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Practise compressions and AED prompts on approved equipment; distinguish the pediatric algorithm and drowning response before any child or water case.",
                "start_ms": 12420,
                "end_ms": 24580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "At a supervised manikin station, show help activation, AED request and the trainer-approved adult sequence; record each observed action.",
                "start_ms": 24880,
                "end_ms": 37240
              }
