            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ask about ability to drink, vomiting, blood in stool and alertness.",
                "start_ms": 2380,
                "end_ms": 8300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Encourage continued breastfeeding when the child can feed.",
                "start_ms": 8600,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Explain that packaged ORS uses safe water and the exact packet directions.",
                "start_ms": 13020,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Refer urgently for danger signs or dehydration concerns.",
                "start_ms": 20040,
                "end_ms": 25160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use the packet label in a dry simulation, explain safe water and continued feeding, and identify a referral trigger.",
                "start_ms": 25460,
                "end_ms": 34420
              }
            ]
          },
