        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/example.en.61c6b2cf5b90.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "61c6b2cf5b90ff29c152cfd5e835ab9f54e189011bdb924b171f59f90f503415",
            "sha256": "92667fa9e47b5f22d10c545916bca116437623f846cac7bcc0cd8e6c3e75266b",
            "duration_seconds": 37.799,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW first asks whether Mina can drink, is vomiting, has blood in her stool and is alert.",
                "start_ms": 2020,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mina is still breastfeeding, so the BHW encourages the caregiver to continue.",
                "start_ms": 10280,
                "end_ms": 16560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Holding the sachet, the BHW reads its directions aloud and explains that it needs safe water.",
                "start_ms": 16860,
                "end_ms": 24140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She also names when to go urgently: any danger sign or dehydration concern.",
                "start_ms": 24440,
                "end_ms": 30920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask first, keep breastfeeding, read the packet, and name when to refer.",
                "start_ms": 31220,
                "end_ms": 37740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/example.fil.b8c69d6ecd9b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b8c69d6ecd9b021377de378dd82d4487af775f5f880c7b53f2a874b9ad16797e",
            "sha256": "5339ccafa3396f33e837a9e08e00c4af567d1e2e53e536405b5fda2318004b40",
            "duration_seconds": 43.337,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Unang itinatanong ng BHW kung nakaiinom si Mina, kung sumusuka, kung may dugo sa dumi at kung alerto siya.",
                "start_ms": 1820,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sumususo pa si Mina, kaya hinihikayat ng BHW na ituloy ito.",
                "start_ms": 11120,
                "end_ms": 17040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hawak ang sachet, binabasa niya nang malakas ang panuto at ipinapaliwanag na kailangan ng ligtas na tubig.",
                "start_ms": 17340,
                "end_ms": 25860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sinasabi rin niya kung kailan agad pupunta: kapag may danger sign o alalahanin sa dehydration.",
                "start_ms": 26160,
                "end_ms": 33520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magtanong muna, ituloy ang pagpapasuso, basahin ang sachet, at sabihin kung kailan magre-refer.",
                "start_ms": 33820,
                "end_ms": 43260
              }
            ]
          }
        },
