    "disaster-tabletop": {
      "module": "chapter2/07-disaster-preparedness",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/disaster-tabletop/action.en.7990cf0dc83b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7990cf0dc83bb83b0d87518e616757b700e12244550529d491b9355ee37ec97e",
            "sha256": "cad57b8ce93975a0c3002dae556037d2c1bf7ac272a69068e0cdf3dc0c8fef10",
            "duration_seconds": 36.441,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Check the official warning and local plan.",
                "start_ms": 2380,
                "end_ms": 5700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Identify confirmed contacts for evacuation, clinical continuity, WASH and psychosocial support.",
                "start_ms": 6000,
                "end_ms": 14680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Report immediate risk to the right team, confirm handover, and set follow-up.",
                "start_ms": 14980,
                "end_ms": 21380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A responder should rest and seek support when it is unsafe to continue.",
                "start_ms": 21680,
                "end_ms": 26960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "In a 10-minute tabletop, sequence priorities, handover, continuity, follow-up and responder support.",
                "start_ms": 27260,
                "end_ms": 36380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/disaster-tabletop/action.fil.8eaab71d8f4d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8eaab71d8f4d8b358ecb3bd9e1af00075b076764f277929fd6411c59b315549d",
            "sha256": "e9da13b9e3c523d846ba199b75350a283049918efe28a5b63852f0d86306adba",
            "duration_seconds": 42.24,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Suriin ang opisyal na babala at lokal na plano.",
                "start_ms": 2460,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Magtalaga ng kumpirmadong contact sa evacuation, clinical continuity, WASH at psychosocial support.",
                "start_ms": 6720,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iulat ang agarang panganib sa tamang team, kumpirmahin ang handover, at magtakda ng follow-up.",
                "start_ms": 17060,
                "end_ms": 24860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magpahinga at humingi ng suporta ang responder kung hindi ligtas magpatuloy.",
                "start_ms": 25160,
                "end_ms": 31520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa 10 minutong tabletop, ayusin ang prayoridad, handover, continuity, follow-up at suporta sa responder.",
                "start_ms": 31820,
                "end_ms": 42180
              }
            ]
          }
        },
