              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Call trained rescuers and keep yourself out of the water.",
                "start_ms": 2460,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use an available reach or throw aid only when safe.",
                "start_ms": 6680,
                "end_ms": 11560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Once rescued by trained personnel, arrange urgent medical assessment and follow the current drowning resuscitation protocol.",
                "start_ms": 11860,
                "end_ms": 20740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose a safe shore response, activate trained rescue and state the need for medical assessment.",
                "start_ms": 21040,
                "end_ms": 28320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/action.fil.6f191506e22a.mp3",
