                "end_ms": 7540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She calls trained rescuers and gives the location.",
                "start_ms": 7840,
                "end_ms": 11440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "When a bystander urges her to jump in, she says no and uses a reach or throw aid only if it is safe.",
                "start_ms": 11740,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She states that the person will need urgent medical assessment once rescued.",
                "start_ms": 20680,
                "end_ms": 26080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea stays on dry ground, calls rescuers and states the need for medical assessment.",
                "start_ms": 26380,
                "end_ms": 32780
              }
            ]
          },
          "fil": {
