            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nananatili si Lea sa tuyong lupa sa tabi ng binahang kanal at hindi lumulusong.",
                "start_ms": 1900,
                "end_ms": 7940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tinatawagan niya ang sanay na rescuer at sinasabi ang lokasyon.",
                "start_ms": 8240,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nang udyukan siya ng saksi na lumusong, tumanggi siya.",
                "start_ms": 13380,
                "end_ms": 17860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Gumagamit lamang siya ng abot o hagis na tulong kung ligtas.",
                "start_ms": 18160,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sinasabi niyang kailangan ng agarang medikal na pagsusuri kapag nailigtas na ang tao.",
                "start_ms": 23660,
                "end_ms": 29540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nasa tuyong lupa si Lea, tumatawag ng rescuer at sinasabing kailangan ng pagsusuri.",
                "start_ms": 29840,
                "end_ms": 36760
              }
            ]
          }
        },
