    "effective-safe-person-centered": {
      "module": "chapter2/02-quality-service",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/action.en.9447a448403a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9447a448403ab499c7e7d2eecf98170e630ea5b1d6ab4276ee6a01d409c164b2",
            "sha256": "c63589e42cbf1c539dae3e1590d1766fcdafcb1d7d62e95bbbec2c6401d1ec70",
            "duration_seconds": 34.978,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Check three dimensions.",
                "start_ms": 2300,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Effective: confirm information against current guidance or with the designated staff.",
                "start_ms": 4960,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Safe: notice potential harm and seek appropriate help.",
                "start_ms": 11660,
                "end_ms": 16620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "People-centered: ask about needs and preferences.",
                "start_ms": 16920,
                "end_ms": 20720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Speed or courtesy alone does not make service high quality.",
                "start_ms": 21020,
                "end_ms": 26100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Compare the two encounters. For each dimension, record the evidence and one improvement. Explain the difference to a partner.",
                "start_ms": 26400,
                "end_ms": 34920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/action.fil.d30c3e24d98c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d30c3e24d98ce2b07b6250e2900b84a78c32addcb584c20ad9c2f0b38ab41416",
            "sha256": "f7e24057898547b0236574897a853f6cae1d3723544d7eb187aa7aadea0ebbb2",
            "duration_seconds": 41.143,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Suriin ang tatlong katangian.",
                "start_ms": 2420,
                "end_ms": 5460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Epektibo: kumpirmahin ang impormasyon sa kasalukuyang gabay o nakatalagang staff.",
                "start_ms": 5760,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ligtas: pansinin ang maaaring makapinsala at humingi ng angkop na tulong.",
                "start_ms": 13220,
                "end_ms": 19620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakatuon sa tao: itanong ang pangangailangan at kagustuhan.",
                "start_ms": 19920,
                "end_ms": 25400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi sapat na mabilis o magalang lamang ang serbisyo.",
                "start_ms": 25700,
                "end_ms": 30340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihambing ang dalawang usapan. Sa bawat katangian, itala ang ebidensiya at isang pagbabago. Ipaliwanag ang pagkakaiba sa kapareha.",
                "start_ms": 30640,
                "end_ms": 41080
              }
            ]
          }
        },
        "check-start": {
