            "duration_seconds": 13.453,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2500,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4960,
                "end_ms": 8440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This establishes a reliable basis before giving a schedule.",
