            "sha256": "32070efdbdf18ca0b6224f435e4a24bd9fe3aa9984ac9f837a176c8ba0df3500",
            "duration_seconds": 15.282,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2780,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5440,
                "end_ms": 10400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May mapagkakatiwalaang batayan bago magbigay ng iskedyul.",
                "start_ms": 10700,
                "end_ms": 15220
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/check-transfer.en.fecac31294f4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fecac31294f4c9c375c918d58cd5d4f1e350a083ec6df2ef4a6ce50446b9417a",
            "sha256": "3360d5b96c1df5e5528dc05df23ca20baeb6ee8e5bf5216fd8f01c04938ae46e",
            "duration_seconds": 11.755,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2700,
                "end_ms": 4580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4880,
                "end_ms": 7640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safety and responsiveness to needs also matter.",
