            "sha256": "b750186432bb1f10cecc469147f553fa05952f4ccda516306526299de2b9c76a",
            "duration_seconds": 12.957,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2620,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4800,
                "end_ms": 8000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan din ang kaligtasan at pagtugon sa pangangailangan.",
                "start_ms": 8300,
                "end_ms": 12900
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/example.en.959f1818cec5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "959f1818cec51d4f0beb692f9a66790d7729ff2dc946893932049bdadff415b4",
            "sha256": "9ef89259297ead639e7f29af11e9f2d380f97cef07198b734ab978a3f7e15a74",
            "duration_seconds": 30.955,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the second encounter, Mila confirms the schedule with staff.",
                "start_ms": 2020,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks for the box to be removed from the walkway.",
                "start_ms": 6960,
                "end_ms": 10640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She asks what time Nena can manage and explains the confirmed options.",
                "start_ms": 10940,
                "end_ms": 16220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Information is reliable, the path is safer and Nena participates in the decision.",
                "start_ms": 16520,
                "end_ms": 23320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identifies evidence for all three dimensions and proposes an appropriate improvement for each.",
                "start_ms": 23620,
                "end_ms": 30900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/example.fil.05a69beb3095.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "05a69beb3095cb527dd3fd0f056141c3430dac58cc4ccb7266bf5580562e590f",
            "sha256": "cdc8c7d246c8f446c95824a67841ec5773776bf9bad3892cee50c0739867f134",
            "duration_seconds": 34.9,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa ikalawang usapan, kinumpirma ni Mila ang iskedyul sa staff.",
                "start_ms": 2060,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hiniling niyang alisin ang kahon sa daanan.",
                "start_ms": 7280,
                "end_ms": 10560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinanong niya kung anong oras ang kaya ni Nena.",
                "start_ms": 10860,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipinaliwanag niya ang mga kumpirmadong pagpipilian.",
                "start_ms": 14960,
                "end_ms": 19320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Epektibo ang impormasyon, mas ligtas ang daan, at kasama si Nena sa pagpapasya.",
                "start_ms": 19620,
                "end_ms": 26100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tinutukoy ang ebidensiya para sa tatlong katangian at nagmumungkahi ng isang angkop na pagbabago sa bawat isa.",
                "start_ms": 26400,
                "end_ms": 34840
              }
            ]
          }
        },
        "next-step": {
