            "duration_seconds": 32.209,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nena chooses a confirmed time.",
                "start_ms": 2500,
                "end_ms": 5420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mila checks every dimension rather than only speed.",
                "start_ms": 5720,
                "end_ms": 10360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On Monday, compare two fictional visits using three questions: Is the basis reliable?",
                "start_ms": 10660,
                "end_ms": 18260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Is it safe?",
                "start_ms": 18560,
                "end_ms": 20080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Have we considered the person?",
                "start_ms": 20380,
                "end_ms": 22780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Word: effective — consistent with appropriate guidance and purpose.",
                "start_ms": 23080,
                "end_ms": 28960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 29260,
                "end_ms": 32140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/next-step.fil.61e01c285c12.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "61e01c285c1201cbaa9e45625a63188994758d9fb35283744848ecb4f5f43e5b",
            "sha256": "b180b917356ff2a472922e921f4d200890977c03e41680637016e70b58351aaa",
            "duration_seconds": 36.937,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nakapili si Nena ng kumpirmadong oras.",
                "start_ms": 2740,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinuri ni Mila ang bawat katangian, hindi lamang ang bilis ng usapan.",
                "start_ms": 7080,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, ihambing ang dalawang kathang-isip na pagbisita gamit ang tatlong tanong: Tama ba ang batayan?",
                "start_ms": 13020,
                "end_ms": 21700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ligtas ba?",
                "start_ms": 22000,
                "end_ms": 23400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Naisaalang-alang ba ang tao?",
                "start_ms": 23700,
                "end_ms": 26260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Salita: epektibo — naaayon sa tamang gabay at layunin.",
                "start_ms": 26560,
                "end_ms": 32800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 33100,
                "end_ms": 36860
              }
            ]
