                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a fictional BHS, Nena asks about the schedule.",
                "start_ms": 1940,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In the first encounter, BHW Mila reads an old message.",
                "start_ms": 6680,
                "end_ms": 11840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A box blocks the walkway.",
                "start_ms": 12140,
                "end_ms": 14860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nobody asks when Nena can return.",
                "start_ms": 15160,
                "end_ms": 18440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The conversation is fast, but is it good service?",
                "start_ms": 18740,
                "end_ms": 22900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Fast, but high quality?",
