                "end_ms": 13400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May kahong nakaharang sa daan.",
                "start_ms": 13700,
                "end_ms": 16260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi naitanong kung kailan makakabalik si Nena.",
                "start_ms": 16560,
                "end_ms": 20160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mabilis ang usapan, pero dekalidad ba ito?",
                "start_ms": 20460,
                "end_ms": 24220
              },
              {
                "zone": "takeaway",
                "index": 0,
