              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not diagnose or change a clinician’s advice.",
                "start_ms": 8000,
                "end_ms": 12000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If unsure, say so and ask the designated staff.",
                "start_ms": 12300,
                "end_ms": 16820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Listen to the resident’s preferences while staying within safe service boundaries.",
                "start_ms": 17120,
                "end_ms": 22560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm boundaries and requirements with the appropriate person.",
                "start_ms": 22860,
                "end_ms": 27300
