        "example": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/example.en.072506297c1b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "072506297c1bcbd375464a7d0f851a2257cf95b88cf64144be0a68d6c44b114d",
            "sha256": "fea93b911468e145594ae2ec342d320fd6fe2b96ff5e99a94852211f0aea50b9",
            "duration_seconds": 26.018,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW routes water to WASH, food to nutrition and medicines to a clinician.",
                "start_ms": 2100,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "They speak calmly with the distressed person without demanding a story and offer referral.",
                "start_ms": 10120,
                "end_ms": 16880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Water to WASH, food to nutrition, medicine to a clinician; calm listening and referral.",
                "start_ms": 17180,
                "end_ms": 25940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/example.fil.2d7fea4f2409.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2d7fea4f24097c813238d309465cf31f50cfa08e7cdc8da2cb318f796fd8eb0d",
            "sha256": "5dcc026030078295dc11da20051e1eb8307d3377b5351c7526b5e2b4346ded57",
            "duration_seconds": 31.138,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinasa ng BHW ang tubig sa WASH team.",
                "start_ms": 1980,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang pagkain ay sa nutrition team; ang gamot ay sa clinician.",
                "start_ms": 7800,
                "end_ms": 13360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nakinig siya sa nababagabag nang hindi pinilit ang salaysay at nag-alok ng referral.",
                "start_ms": 13660,
                "end_ms": 20540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tubig sa WASH, pagkain sa nutrition, gamot sa clinician; mahinahong pakikinig at referral.",
                "start_ms": 20840,
                "end_ms": 31080
              }
            ]
          }
        },
        "next-step": {
