            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea sets the old inventory sheet aside and works from the current local list.",
                "start_ms": 2020,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "For each item, she records quantity, seal, expiry and storage.",
                "start_ms": 7960,
                "end_ms": 14600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She marks the expired item and the unsealed packet, sets both aside unused, and reports them to the named replacement owner.",
                "start_ms": 14900,
                "end_ms": 24940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Having them in the kit does not mean she may use them.",
                "start_ms": 25240,
                "end_ms": 29640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea fills every row, sets aside the expired and unsealed items unused, and reports them to the owner.",
