              {
                "zone": "body",
                "index": 1,
                "text": "Sa bawat gamit, itinatala niya ang dami, selyo, expiry at imbakan.",
                "start_ms": 9240,
                "end_ms": 16880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Minamarkahan niya ang expired item at ang bukas na pakete.",
