            "duration_seconds": 36.258,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For food: keep hands, utensils and surfaces clean.",
                "start_ms": 2500,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Separate raw and cooked food.",
                "start_ms": 7440,
                "end_ms": 10120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Cook thoroughly.",
                "start_ms": 10420,
                "end_ms": 12100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Keep food at safe temperatures instead of leaving it exposed.",
                "start_ms": 12400,
                "end_ms": 16960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Use safe water and ingredients.",
                "start_ms": 17260,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Wash produce with safe water.",
                "start_ms": 20680,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Protect food from insects and rodents.",
                "start_ms": 23660,
                "end_ms": 26900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mark risks in the household story. Complete the food, water and sanitation rows and add a contact for uncertainties.",
                "start_ms": 27200,
                "end_ms": 36200
              }
            ]
          },
