              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pagkain: panatilihing malinis ang kamay, kagamitan at lugar.",
                "start_ms": 2460,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihiwalay ang hilaw sa luto.",
                "start_ms": 9200,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Lutuing mabuti.",
                "start_ms": 12860,
                "end_ms": 14620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Panatilihin sa ligtas na temperatura ang pagkain; huwag basta iwang nakabuyangyang.",
                "start_ms": 14920,
                "end_ms": 21360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gumamit ng ligtas na tubig at sangkap.",
                "start_ms": 21660,
                "end_ms": 24820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hugasan ang prutas at gulay gamit ang ligtas na tubig.",
                "start_ms": 25120,
                "end_ms": 29600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Takpan laban sa insekto at daga.",
                "start_ms": 29900,
                "end_ms": 33180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Markahan ang panganib sa kuwento ng bahay. Punan ang pagkain, tubig at sanitasyon na hanay; magdagdag ng contact para sa hindi tiyak.",
                "start_ms": 33480,
                "end_ms": 44840
              }
            ]
          }
        },
