          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/check-start.fil.d18ec91baba3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d18ec91baba36e7c78b03626b8351b4b55c80b6c3349a11e9d1104c1cb0d6b3b",
            "sha256": "020f8a197de4cbfccca5947b6af885fb5eb7fd644bf34b08583f3c4f96c45bd2",
            "duration_seconds": 15.438,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
