                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2540,
                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5160,
                "end_ms": 9960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan ng tamang batayan at tagubilin, hindi hitsura lamang.",
