    "hand-hygiene": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/action.en.6d565ef14874.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6d565ef14874c0763d4973c3ec2cf89ff0c72559903afdeb30b6bdd95e02e2df",
            "sha256": "415bcdcb94dc0f75890d2c56900750712d5e883e20f1d964a9a1bf4e04952880",
            "duration_seconds": 35.605,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Wet hands and apply soap.",
                "start_ms": 2420,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Rub palm against palm, then each hand’s back with fingers interlaced.",
                "start_ms": 5320,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Clean between fingers and rub their backs against the opposite palm.",
                "start_ms": 11700,
                "end_ms": 16540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Rotate around each thumb.",
                "start_ms": 16840,
                "end_ms": 19400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Rub fingertips and nails against the opposite palm.",
                "start_ms": 19700,
                "end_ms": 23860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Work on both hands.",
                "start_ms": 24160,
                "end_ms": 26200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose a method for two cards: visibly dirty and not visibly dirty. Demonstrate handwashing and handrub to the supervisor.",
                "start_ms": 26500,
                "end_ms": 35540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/action.fil.2203b65bb79b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2203b65bb79bc1cc5b2ebbd3725b2442d855cd3c202cd02122e86e13a439b48c",
            "sha256": "e7086ab55a4f08948af71f75c8c51c357c7846b60b78ccbb1ec8c6c025af20f9",
            "duration_seconds": 40.281,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Basain at sabunin ang kamay.",
                "start_ms": 2460,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kuskusin ang palad sa palad, saka bawat likod ng kamay habang nakasalikop ang daliri.",
                "start_ms": 5960,
                "end_ms": 12520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kuskusin ang pagitan ng mga daliri at likod ng daliri laban sa kabilang palad.",
                "start_ms": 12820,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Paikuting kuskusin ang bawat hinlalaki.",
                "start_ms": 20040,
                "end_ms": 23080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ikuskos ang dulo ng daliri at kuko sa kabilang palad.",
                "start_ms": 23380,
                "end_ms": 27980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Gawin sa magkabilang kamay.",
                "start_ms": 28280,
                "end_ms": 30560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng paraan para sa dalawang card: may dumi at walang dumi. Ipakita ang handwash at handrub sa supervisor.",
                "start_ms": 30860,
                "end_ms": 40220
              }
            ]
          }
        },
        "check-start": {
