    "incident-handover": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/action.en.04541290cad1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "04541290cad1ae2e098dc00f1d6356f003bb328c03f05f40ea159695a786f08d",
            "sha256": "61728edd33343c2d5702d287706674d1f3fb3a748d22ae384b1794ee89eaae99",
            "duration_seconds": 27.115,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "State the situation, observed response and breathing, key timeline, actions taken, changes and support needed.",
                "start_ms": 2460,
                "end_ms": 12100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Confirm the receiver heard the urgent concern and document only factual, necessary details.",
                "start_ms": 12400,
                "end_ms": 19800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Deliver a timed, factual handover and invite the receiving worker to confirm the next action.",
                "start_ms": 20100,
                "end_ms": 27060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/action.fil.da0cdba3113c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "da0cdba3113c09d7893874130bb7216b8fe12e14621dff5a0ab47f5af053f01f",
            "sha256": "a13b496cb6bdb00ba78c6b004820b2825725602bfac321280b5fe071720f3488",
            "duration_seconds": 27.246,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sabihin ang sitwasyon, tugon at paghinga, oras, ginawa, pagbabago at kailangang tulong.",
                "start_ms": 2540,
                "end_ms": 12500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kumpirmahing narinig ang agarang alalahanin at itala lamang ang kinakailangang facts.",
                "start_ms": 12800,
                "end_ms": 19360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magbigay ng factual na handover na may oras at hilinging kumpirmahin ng tatanggap ang susunod na hakbang.",
                "start_ms": 19660,
                "end_ms": 27180
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/check-start.en.e8cb08df8a48.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e8cb08df8a483e5c79822bae18b3e1455ade319b56168d6ea9409355e882e49e",
            "sha256": "7ca792da498735283822a142da131e7865f72bb7ab3b221b99b11c18e8bf5498",
            "duration_seconds": 12.042,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2860,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5400,
                "end_ms": 8640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start with the situation and the time.",
                "start_ms": 8940,
                "end_ms": 11980
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/check-start.fil.4ef6c8264983.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ef6c82649833183dad78c17aee8f861cf0aeaac546f99bc0658be063a56e439",
            "sha256": "1f629b0e1fc7bd2031c59f2ba8292ad57324dc66c2765c73c7e9515b1d506eac",
            "duration_seconds": 13.244,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 4780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5080,
                "end_ms": 9680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Unahin ang sitwasyon at ang oras.",
                "start_ms": 9980,
                "end_ms": 13180
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/check-transfer.en.5f5029adb572.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5f5029adb572c747063d3b4528ae4f7c93b7bbace9243d51bf78bc8e4614a5d1",
            "sha256": "440d10cbd9c57bd08a406166a11d92819332849961bd464859af1d9cc33fd356",
            "duration_seconds": 12.565,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2780,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "End by asking the receiver to confirm the next action.",
                "start_ms": 8180,
                "end_ms": 12500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/check-transfer.fil.284bb82f9233.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "284bb82f923384ec1c066be288024ed6fd11bd74d188a5b585f27497ba3e7b85",
            "sha256": "22cbe84a5bcf50bf01f6392deacd2bb946224c47f5e032fe3ad45840f01b9df5",
            "duration_seconds": 14.289,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2820,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5320,
                "end_ms": 8760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tapusin sa paghiling na kumpirmahin ng tatanggap ang susunod na hakbang.",
                "start_ms": 9060,
                "end_ms": 14220
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/example.en.235d18f59083.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "235d18f59083a3b3a9289ecfa7c7cad138f6c71705e3da763eb6dfa7addb8683",
            "sha256": "63ba979cbd86a676beea8e92bcf091001c6b2118b99808d1fdad4f1decf59360",
            "duration_seconds": 37.355,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "When the health worker arrives, Lea says what happened and when.",
                "start_ms": 2060,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She reports the response and breathing she observed, what she has done, the help already called, any changes, and the support needed.",
                "start_ms": 7280,
                "end_ms": 17080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She gives no guess about the injury.",
                "start_ms": 17380,
                "end_ms": 20500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She asks the receiver to confirm the urgent concern and the next action, and records only the facts needed.",
                "start_ms": 20800,
                "end_ms": 29240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea hands over facts and times in order, then asks the receiver to confirm the next action.",
                "start_ms": 29540,
                "end_ms": 37300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/example.fil.e9030b08ce24.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e9030b08ce24dad42e8d51f42bc928411a7db0a4d1085b27d744fec659728646",
            "sha256": "396f294985583645dd716e9c1160b1c571c535a5a0ec66d9028ef922af695eb5",
            "duration_seconds": 44.199,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagdating ng health worker, sinasabi ni Lea ang nangyari at kailan.",
                "start_ms": 1860,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iniuulat niya ang nakitang tugon at paghinga, ang ginawa, at ang natawag na tulong.",
                "start_ms": 7600,
                "end_ms": 14200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sinasabi rin niya ang pagbabago at kailangang tulong.",
                "start_ms": 14500,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi siya nanghuhula ng diagnosis.",
                "start_ms": 19280,
                "end_ms": 22520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hinihiling niyang kumpirmahin ng tatanggap ang agarang alalahanin at susunod na hakbang.",
                "start_ms": 22820,
                "end_ms": 29860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Itinatala lamang niya ang kinakailangang facts.",
                "start_ms": 30160,
                "end_ms": 34320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iniuulat ni Lea ang facts at oras nang maayos, saka hinihiling sa tatanggap na kumpirmahin ang susunod na hakbang.",
                "start_ms": 34620,
                "end_ms": 44140
              }
            ]
          }
        },
        "next-step": {
