            "content_hash": "f05949b21d1971215aa9ef2d55a18e12cf04e1240a160ed6069e854466c81bf0",
            "sha256": "a227e1d9ce75f8a1d3d9b23c17c8483876c149e31f0f5caa6dbacebffbd7d167",
            "duration_seconds": 21.812,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos ng pagkahulog, dumating ang isa pang health worker.",
