                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2860,
