            "sha256": "f8a31878d90a6800bfcc5c3fb6479d9f6416cc9e13971e0822ee92122ef34436",
            "duration_seconds": 14.733,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2460,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4840,
                "end_ms": 8520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The card lists leaves of Vitex negundo; this is not a dose.",
                "start_ms": 8820,
                "end_ms": 14660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/lagundi/check-start.fil.e0e96038d57c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e0e96038d57c011b115bef468ee4cfe8081d6562de1659d00cb0f7fdbf79b570",
            "sha256": "38e6127269fb2a32a4d106aedaa83a779f8f8b8b41ab55380fa68db95e9bf304",
            "duration_seconds": 14.576,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2460,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 4720,
                "end_ms": 9800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dahon ng Vitex negundo ang nasa card; hindi ito dose.",
                "start_ms": 10100,
                "end_ms": 14500
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/lagundi/check-transfer.en.83a8b474fc8d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "83a8b474fc8d7c6598d2406b25bdd765bdcb52f2c6cc9400415edce869067a6e",
            "sha256": "94f6793e55492a4c7cc1f23d39a8ad5c011909c406fc1db5a39c61ba8dfcc433",
            "duration_seconds": 12.408,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2820,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Connect Ben promptly and report his breathing difficulty.",
                "start_ms": 8020,
                "end_ms": 12340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/lagundi/check-transfer.fil.3d693051b31c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3d693051b31c6d6d7df06ccdf120c3c95d543d89af5128ba175608b9ae6a03f4",
            "sha256": "809da593fdfa45869a354a73727b8a037a93e14e63cf9ce7e4deeedd14a4cadf",
            "duration_seconds": 14.811,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 4280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 4580,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 7080,
                "end_ms": 10200
              },
              {
