            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use a calm voice.",
                "start_ms": 2500,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Say, “I would like to hear what happened.”",
                "start_ms": 5200,
                "end_ms": 8680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Offer a more private, safe place if she wants.",
                "start_ms": 8980,
                "end_ms": 12980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask, “What concerns you most?”",
                "start_ms": 13280,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Listen without interrupting.",
                "start_ms": 16420,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Summarize what she said, then ask, “Have I understood correctly?”",
                "start_ms": 19280,
                "end_ms": 24120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask about the concern, listen, summarize and check understanding.",
                "start_ms": 24420,
                "end_ms": 30100
              }
            ]
          },
