            "sha256": "94fbf4944f39c9b532bda2580b0d4234f4b281d9293b8f2657c7820b483d573b",
            "duration_seconds": 37.016,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Magsalita sa mahinahong boses.",
                "start_ms": 3060,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sabihin: “Gusto ko pong marinig ang nangyari.”",
                "start_ms": 6360,
                "end_ms": 10400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mag-alok ng lugar na mas pribado at ligtas kung nais niya.",
                "start_ms": 10700,
                "end_ms": 15460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magtanong: “Ano po ang pinaka-inaalala ninyo?”",
                "start_ms": 15760,
                "end_ms": 19880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Makinig nang hindi sumasabat.",
                "start_ms": 20180,
                "end_ms": 23020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ibuod ang sinabi, saka itanong: “Tama po ba ang pagkaintindi ko?”",
                "start_ms": 23320,
                "end_ms": 29000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itanong ang alalahanin, makinig, ibuod at ipasuri ang pagkaintindi.",
                "start_ms": 29300,
                "end_ms": 36940
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/check-start.en.30df6bbb7d70.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "30df6bbb7d70038b74c65814aae1180159fa2ce50ec458ca2cc37fbadc957aa2",
            "sha256": "284d763049f79c103a9e59069370f9245a7df0df1da6b793871b438a060c3887",
            "duration_seconds": 13.322,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read why each choice helps or does not help.",
                "start_ms": 4960,
                "end_ms": 9280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This invites Liza to explain without judgment.",
                "start_ms": 9580,
                "end_ms": 13260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/check-start.fil.70482a74df1d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "70482a74df1dfd42fdc1b569e60ef39a79cdba9cb7ac2a5bff1df861859f3d1f",
            "sha256": "4bf62a7f548092977a635d04a2d3360b79812fcbd286cf9af4cacfff8f09e97b",
            "duration_seconds": 16.17,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 3100,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag para sa bawat pagpipilian.",
                "start_ms": 5440,
                "end_ms": 10600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Inaanyayahan nitong magpaliwanag si Liza nang walang panghuhusga.",
                "start_ms": 10900,
                "end_ms": 16100
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/check-transfer.en.6038332019f1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6038332019f1d3129179fb255a85241e50240169798ed95b17b609bd01620791",
            "sha256": "c1d9c98a39353c067a794351d162db87591b1041764548c1a904b6063d7f979e",
            "duration_seconds": 12.33,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2700,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose the appropriate next step.",
                "start_ms": 4960,
                "end_ms": 7880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This summarizes what was heard and invites correction.",
                "start_ms": 8180,
                "end_ms": 12260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/check-transfer.fil.ca848365b338.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ca848365b338a10d2e8c4d48a088d2edb740c61f62a4f1d4cd52f5de784511de",
            "sha256": "7fc6c3355a9a7ab870e840d330a3d8f3a15475ccdd02d8a7dfd23f5ae339408c",
            "duration_seconds": 13.897,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang nangyari sa kuwento.",
                "start_ms": 3260,
                "end_ms": 5460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5760,
                "end_ms": 9000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ibinubuod nito ang narinig at humihingi ng pagwawasto.",
                "start_ms": 9300,
                "end_ms": 13820
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/example.en.d14fccab174d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d14fccab174d06060f99aa54ee1443275cc3cbe8a1d0a9ba7f88b1cf398f612f",
            "sha256": "0bc2d03869e269cb3632bea28b49d94f1e71eac2e484448e50f8d3ffa21bc10a",
            "duration_seconds": 35.683,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza: “I went twice.",
                "start_ms": 1860,
                "end_ms": 4580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "I don’t know whom to speak to.”",
                "start_ms": 4880,
                "end_ms": 7600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Jun: “You have been twice, but it is still unclear who can help.",
                "start_ms": 7900,
                "end_ms": 13700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Is that right?”",
                "start_ms": 14000,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Liza: “Yes, that is the problem.”",
                "start_ms": 15780,
                "end_ms": 19860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Jun clarifies the concern before suggesting a step.",
                "start_ms": 20160,
                "end_ms": 24280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "In the conversation with Liza, uses a calm voice and open question, lets her finish, summarizes her reply and invites correction.",
                "start_ms": 24580,
                "end_ms": 35620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/example.fil.75d200d85a5f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "75d200d85a5fe13c308401494acf42dc15c1e9813ebb7689bca81118b581d6c3",
            "sha256": "27ac9e3f946fc619b55ea4d6c750c5452fdc2fcd39c705a3655f3faad406715f",
            "duration_seconds": 37.93,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawa ng usapan",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza: “Dalawang beses akong pumunta.",
                "start_ms": 2340,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ko alam kung sino ang kakausapin.”",
                "start_ms": 6360,
                "end_ms": 9480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Jun: “Dalawang punta na po, pero hindi pa malinaw kung sino ang tutulong.",
                "start_ms": 9780,
                "end_ms": 15620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tama po ba?”",
                "start_ms": 15920,
                "end_ms": 17240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Liza: “Oo, iyon ang problema.”",
                "start_ms": 17540,
                "end_ms": 21740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Nalinaw ang alalahanin bago nagbigay ng mungkahi si Jun.",
                "start_ms": 22040,
                "end_ms": 26600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa usapan kay Liza, gumamit ng mahinahong boses at bukas na tanong; hinayaang matapos ang sagot; ibinuod ito at humingi ng pagwawasto.",
                "start_ms": 26900,
                "end_ms": 37860
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/next-step.en.40caf4af4935.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "40caf4af493542f43751d83f34a201d82dab4e0f8546d9dc509d448435d8b93e",
            "sha256": "e1dae95b5fb421916b9083a6436b267ad5af246cef6796fb70304065f9c6d798",
            "duration_seconds": 28.421,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza chooses a more private place.",
                "start_ms": 2460,
                "end_ms": 5540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Jun confirms the concern.",
                "start_ms": 5840,
                "end_ms": 8080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "They are ready to find out which staff member to approach.",
                "start_ms": 8380,
                "end_ms": 12380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "On Monday, use the listening checklist in practice with the midwife.",
                "start_ms": 12680,
                "end_ms": 17840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Word: summary — a brief restatement of the person’s main message.",
                "start_ms": 18140,
                "end_ms": 24180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose one action and follow up on the result.",
                "start_ms": 24480,
                "end_ms": 28360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/next-step.fil.cbce2367d451.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cbce2367d45144dae1ecc182aceb3c31a3762ed0836692c4c3cde4420b1f9242",
            "sha256": "0c50ab7e6decdd8c9e0e0c269f3cd8ec728795d550be49e1c514afd3db9b0fc1",
            "duration_seconds": 33.306,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pinili ni Liza na makipag-usap sa mas pribadong lugar.",
                "start_ms": 2740,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kinumpirma ni Jun ang alalahanin.",
                "start_ms": 7000,
                "end_ms": 9880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Handa na silang alamin kung sinong staff ang dapat lapitan.",
                "start_ms": 10180,
                "end_ms": 14620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa Lunes, gamitin ang pakikinig na checklist sa pagsasanay kasama ang midwife.",
                "start_ms": 14920,
                "end_ms": 21280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Salita: buod — maikling pagsasabi muli ng pangunahing sinabi ng kausap.",
                "start_ms": 21580,
                "end_ms": 28660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng isang hakbang at balikan ang naging resulta.",
                "start_ms": 28960,
                "end_ms": 33240
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/scene.en.6236b2af07cd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6236b2af07cdc1b74f9574063b768224703508501a653dde1082c1fb8ac0373c",
            "sha256": "849b22561ae2d6739758feac39caac86007118dae1bfca08308023321ff1da95",
            "duration_seconds": 25.652,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a barangay in Iloilo, Liza meets BHW Jun.",
                "start_ms": 2060,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“You keep coming back.",
                "start_ms": 8000,
                "end_ms": 9880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nothing happens!”",
                "start_ms": 10180,
                "end_ms": 11860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Her voice is raised.",
                "start_ms": 12160,
                "end_ms": 14400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "People in the queue are listening.",
                "start_ms": 14700,
                "end_ms": 17180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Jun needs to find out what happened without arguing.",
                "start_ms": 17480,
                "end_ms": 21640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Find out the concern before choosing a response.",
                "start_ms": 21940,
                "end_ms": 25580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/scene.fil.4764cb860c45.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4764cb860c45505bca0da6017e01f141dc16d8d88d17716d7e9d28e123a11610",
            "sha256": "f1a0afc4b110b564eae10d2e794a3e1e4db966d4a1c46cdd56491176cd37984e",
            "duration_seconds": 27.768,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa barangay sa Iloilo, sinalubong ni Liza si BHW Jun.",
                "start_ms": 1940,
                "end_ms": 7620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Paulit-ulit kayo.",
                "start_ms": 7920,
                "end_ms": 9680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Wala namang nangyayari!”",
                "start_ms": 9980,
                "end_ms": 12300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malakas ang boses niya.",
                "start_ms": 12600,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "May mga taong nakikinig sa pila.",
                "start_ms": 15060,
                "end_ms": 17860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kailangang alamin ni Jun ang nangyari nang hindi nakikipagtalo.",
                "start_ms": 18160,
                "end_ms": 23240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alamin ang alalahanin bago pumili ng tugon.",
                "start_ms": 23540,
                "end_ms": 27700
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/scope.en.0feee48bf1d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0feee48bf1d09005da14d56a8ed6d0d19e6d283169d6436bf1c9262429ab4404",
            "sha256": "60cf7f9ac77d4b24e6571b7ed2d9ddacfbf2d82e7d0be17765ca00f3624f09f5",
            "duration_seconds": 31.634,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Calm listening is not a promise to grant every request.",
                "start_ms": 2460,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Clarify and connect the resident with the appropriate staff.",
                "start_ms": 7720,
                "end_ms": 12040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the midwife or supervisor for support when the situation is unsafe or beyond your role.",
                "start_ms": 12340,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If there is immediate danger, use the local emergency service from a safe place.",
                "start_ms": 20040,
                "end_ms": 25960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Seek the appropriate support when a situation exceeds your role.",
                "start_ms": 26260,
                "end_ms": 31580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/scope.fil.2fabbb3c3bdd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2fabbb3c3bdd35cb08e044254d7d6df89c4c3a166b6fa88d0a21ae3e899dd29e",
            "sha256": "928833c90f59e3593908f92d6b85cd4256091fbcbd537569ecc2f8514f08ecb3",
            "duration_seconds": 34.038,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang mahinahong pakikinig ay hindi pangakong matutupad ang lahat ng hinihingi.",
                "start_ms": 3300,
                "end_ms": 9380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring maglinaw at ikonekta ang residente sa tamang staff.",
                "start_ms": 9680,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Humingi ng tulong sa midwife o supervisor kung hindi na ligtas o hindi kayang lutasin ang sitwasyon.",
                "start_ms": 15060,
                "end_ms": 23180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may agarang panganib, gamitin ang lokal na emergency service mula sa ligtas na lugar.",
                "start_ms": 23480,
                "end_ms": 29520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong sa tamang tao kapag lampas sa saklaw.",
                "start_ms": 29820,
                "end_ms": 33980
              }
            ]
          }
        }
      }
    },
    "malaria": {
      "module": "chapter3/04-priority-area-2-be-clean-live-sustainably",
      "sections": {
