                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find Quisqualis indica on the reference card.",
                "start_ms": 2460,
                "end_ms": 6220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is seeds; the use topic is intestinal worms requiring confirmation.",
                "start_ms": 6520,
                "end_ms": 13320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 13620,
                "end_ms": 16860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 17160,
                "end_ms": 20560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Refer the child to the health center for diagnosis and an appropriate deworming plan.",
                "start_ms": 20860,
                "end_ms": 27060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Niyog-niyogan cards; choose Quisqualis indica, seeds, use and safe next step.",
                "start_ms": 27360,
                "end_ms": 35880
              }
            ]
          },
