          "fil": {
            "src": "/training/audio/chapter3/03-priority-area-1-move-more-eat-right/pinggang-pinoy-and-oral-health/scope.fil.13d88855b65e.mp3",
            "voice": "fil-PH-BlessicaNeural",
            "content_hash": "13d88855b65e3dda409b3ef8e19af957b33d59212aee069c99be97f470488ba7",
            "sha256": "25d4cc72ef5eb98416dba79d9b5a49b10649fcc6971c7b71337c1e4a6cfa0efd",
            "duration_seconds": 22.08,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at kaligtasan",
                "start_ms": 0,
                "end_ms": 2328
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Gumamit ng iisang plate o paraan sa lahat ng edad kahit hindi iyon angkop.",
                "start_ms": 2328,
                "end_ms": 8976
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi tiyak ang susunod na hakbang, humingi ng gabay sa midwife o aprubadong lokal na protocol.",
                "start_ms": 8976,
                "end_ms": 15432
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Gumamit ng iisang plate o paraan sa lahat ng edad kahit hindi iyon angkop.",
                "start_ms": 15432,
                "end_ms": 22080
              }
            ]
          }
        }
      }
    },
    "plant-integrated-practice": {
      "module": "chapter2/05-medicinal-plants",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/action.en.260a078c3c68.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "260a078c3c68f5387be5fa7b71cb209bcac2d225c6afcbb619c63eb7558dc87a",
            "sha256": "5af04c44ddfe383baac80b6f31a4e031f713b1c150b5fc34c89f667ada3f79fb",
            "duration_seconds": 33.411,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Match each plant to its botanical name and listed use.",
                "start_ms": 2580,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Escalate breathing difficulty and the infected wound.",
                "start_ms": 7560,
                "end_ms": 11560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Do not replace diabetes medicine.",
                "start_ms": 11860,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If a trainer authorizes a station, demonstrate identification only, with dry props; dispense no product.",
                "start_ms": 15120,
                "end_ms": 23880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "For three case cards, record identity, use, concern, referral and missing local authorization.",
                "start_ms": 24180,
                "end_ms": 33340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/action.fil.5fb5c43e2f05.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5fb5c43e2f05a617cf9800b6a9cd37a27802f8667adc2cedc1cfc0ad509586bc",
            "sha256": "09cdb8b93b7cbc6e36c3c540c48070e3630da897b11189aee22dc0648981aa48",
            "duration_seconds": 34.56,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itugma ang bawat halaman sa botanical name at nakalistang gamit.",
                "start_ms": 2540,
                "end_ms": 7900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Agad i-refer ang hirap sa paghinga at ang infected wound.",
                "start_ms": 8200,
                "end_ms": 12800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag palitan ang diabetes medicine.",
                "start_ms": 13100,
                "end_ms": 15980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may awtorisadong trainer, pagkilala lamang ang ipakita, gamit ang dry props; walang ibibigay na produkto.",
                "start_ms": 16280,
                "end_ms": 24600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa tatlong case card, itala ang identity, gamit, panganib, referral at kulang na local authorization.",
                "start_ms": 24900,
                "end_ms": 34500
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/check-start.en.2cd3686b04be.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2cd3686b04be305d65df4efd236fe8a06b84e7cc623354da27c5b12e529b1b75",
            "sha256": "6c41a4917631ca22bc88603d8a160f62a78e1c14d623812c7b4617b95f6878b7",
            "duration_seconds": 12.408,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2460,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5000,
                "end_ms": 8720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A verified card is the proper start.",
                "start_ms": 9020,
                "end_ms": 12340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/check-start.fil.8637ff1d7860.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8637ff1d786062d6bbac589bd43e940ed15a3730431612ff7f2499e3a7ca64f3",
            "sha256": "1522c4d7fc1dfd5dddaf8f29624f13f85386ebd98d8164e91f5a035443ce1f2d",
            "duration_seconds": 13.166,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2660,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5040,
                "end_ms": 9520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang kumpirmadong card ang tamang simula.",
                "start_ms": 9820,
                "end_ms": 13100
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/check-transfer.en.c0fae29cfdd8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c0fae29cfdd86a8e35bc5254a47cba28689a997ecabcb6c0763ddf9920af0564",
            "sha256": "bc0cf643dfcd99c1bc54e1c806e266acca076b52ff59d315a6b93ff8c04af37b",
            "duration_seconds": 13.767,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4720,
                "end_ms": 7680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Escalate Ben and Mara; Joel's clinician decides about his medicine.",
                "start_ms": 7980,
                "end_ms": 13700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/check-transfer.fil.ead26fbee14b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ead26fbee14b20c78b5682bf79544bdda18f3ec8e7596bcd2bd320e41496fe53",
            "sha256": "5c839e14cb36eb20b0a6260270aa168ea9051756b83309fbdbba6d3a87c4f010",
            "duration_seconds": 13.688,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2460,
                "end_ms": 4140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4440,
                "end_ms": 7720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "I-refer agad sina Ben at Mara; ang clinician ni Joel ang magpapasya sa gamot niya.",
                "start_ms": 8020,
                "end_ms": 13620
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/example.en.21a9171bb134.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "21a9171bb134dcb32b4690aa1319d35b8060f0048fc5b8d598425204b05cbeff",
            "sha256": "b5f12dc75bc3d2640986936ff3afb476796a3b91f646e5826f8d79394bd95bba",
            "duration_seconds": 36.728,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW reads each current card and listens to each resident.",
                "start_ms": 2060,
                "end_ms": 7740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ben's breathing difficulty and Mara's wound with pus are escalated first.",
                "start_ms": 8040,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For Joel, the BHW says Ampalaya does not replace his diabetes medicine and takes his question to his clinician.",
                "start_ms": 14460,
                "end_ms": 23420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "On each worksheet, the BHW marks local authorization as missing.",
                "start_ms": 23720,
                "end_ms": 29720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Escalate Ben and Mara, keep Joel's medicine unchanged and mark authorization missing.",
                "start_ms": 30020,
                "end_ms": 36660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/example.fil.1451709e95fc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1451709e95fc97d60914073dd5a5fc89c602cfda43eac1769b3dadfd02efb610",
            "sha256": "a347f5652d2e3dfbc01dcedeb89a34a17eae98652fbf4aec9b97cfbac37c17e5",
            "duration_seconds": 38.792,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Binasa ng BHW ang bawat kasalukuyang card at pinakinggan ang bawat residente.",
                "start_ms": 1980,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inuna niyang i-refer ang hirap sa paghinga ni Ben at ang sugat ni Mara na may nana.",
                "start_ms": 9200,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kay Joel, sinabi niyang hindi ipapalit ang Ampalaya sa diabetes medicine.",
                "start_ms": 15460,
                "end_ms": 21220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dinala niya ang tanong ni Joel sa clinician nito.",
                "start_ms": 21520,
                "end_ms": 25160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa bawat worksheet, minarkahan niyang kulang ang local authorization.",
                "start_ms": 25460,
                "end_ms": 30500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "I-refer agad sina Ben at Mara, huwag palitan ang gamot ni Joel at markahang kulang ang awtorisasyon.",
                "start_ms": 30800,
                "end_ms": 38720
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/next-step.en.9ee828944d59.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9ee828944d59e228b0dde96c2ff97f198ee39d3ec5bcf04fd0be5e51bff8d868",
            "sha256": "55d6d9752de4f5a3b29a4f3dce70d61864da3798b3315b057c514ed0abfb8709",
            "duration_seconds": 17.398,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, review the card with a supervisor.",
                "start_ms": 2660,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mark what needs confirmation before a real consultation.",
                "start_ms": 6600,
                "end_ms": 11280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, review the card with a supervisor and mark what needs confirmation.",
                "start_ms": 11580,
                "end_ms": 17340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/next-step.fil.37aa3e4ec854.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "37aa3e4ec854bb54a2bf723d2a67da1c1a81dbf38d8f8b9a6ff23dd140224728",
            "sha256": "ef11f4730dec7cbfeba5911ba4c7557683688be7ea2bc2d781d89b50b4fceef5",
            "duration_seconds": 19.879,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, dalhin ang card sa supervisor.",
                "start_ms": 2620,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Markahan ang dapat kumpirmahin bago gamitin sa tunay na konsultasyon.",
                "start_ms": 6960,
                "end_ms": 13120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, ipasuri ang card sa supervisor at markahan ang dapat kumpirmahin.",
                "start_ms": 13420,
                "end_ms": 19820
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/scene.en.c13135c35686.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c13135c356868769e79369170e04ca69fdb4e38601d0dedfda7fa39a4f776f1d",
            "sha256": "9dbc42ed86678b72b9ad0173cec09bb08a9795ef68369d32d94b73f3da817732",
            "duration_seconds": 27.768,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Three residents ask about plants.",
                "start_ms": 1980,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ben asks about Lagundi and has breathing difficulty.",
                "start_ms": 5320,
                "end_ms": 9640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Joel asks about Ampalaya and takes diabetes medicine.",
                "start_ms": 9940,
                "end_ms": 15100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mara asks about Bayabas and has a wound with pus.",
                "start_ms": 15400,
                "end_ms": 20000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: Ben, Joel and Mara ask about Lagundi, Ampalaya and Bayabas",
                "start_ms": 20300,
                "end_ms": 27700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/scene.fil.dbfe9c3362d8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dbfe9c3362d87de1b8df6a13e09649ad4ecf5a8a82e1905035a3451e4b5d6c1f",
            "sha256": "19fb49425c24ee201c20b6ba4d2699d6123708413907c1e25860e03683cf14d0",
            "duration_seconds": 30.328,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tatlong residente ang nagtatanong tungkol sa halaman.",
                "start_ms": 1900,
                "end_ms": 5620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong si Ben tungkol sa Lagundi at hirap siyang huminga.",
                "start_ms": 5920,
                "end_ms": 10400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nagtanong si Joel tungkol sa Ampalaya at umiinom siya ng diabetes medicine.",
                "start_ms": 10700,
                "end_ms": 16900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nagtanong si Mara tungkol sa Bayabas at may sugat siyang may nana.",
                "start_ms": 17200,
                "end_ms": 22080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Nagtanong sina Ben, Joel at Mara tungkol sa Lagundi, Ampalaya at Bayabas",
                "start_ms": 22380,
                "end_ms": 30260
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/scope.en.b223301f2634.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b223301f26345c3c9434ac340ee7619039514cdbc77da206d9219903d39c6f9e",
            "sha256": "1451f399b7dce533801065251fc42a5d2c603f94cd435328d53f4cf10b3aab1d",
            "duration_seconds": 19.278,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Attendance at the station is not clinical sign-off.",
                "start_ms": 2340,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "No hot water, ingestion, dose or dispensing occurs in practice.",
                "start_ms": 6720,
                "end_ms": 13040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Station attendance is not clinical sign-off; no product is dispensed.",
                "start_ms": 13340,
                "end_ms": 19220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-integrated-practice/scope.fil.efdbc8f2380f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "efdbc8f2380fc4d837954d5b6e4df535572962b6d11a915c5eb8aec03aaff2cf",
            "sha256": "477a5ff25b46e162371915a737a3ca31485f115951e3f4bec614e672cb8b1c20",
            "duration_seconds": 21.969,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang pagdalo sa station ay hindi clinical sign-off.",
                "start_ms": 3020,
                "end_ms": 6820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Walang mainit na tubig, aktuwal na ingestion, dosage o pagbibigay ng halamang gamot sa practice.",
                "start_ms": 7120,
                "end_ms": 15520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi clinical sign-off ang pagdalo sa station; walang ibibigay na produkto.",
                "start_ms": 15820,
                "end_ms": 21900
              }
            ]
          }
        }
      }
    },
    "plant-scope-identification": {
      "module": "chapter2/05-medicinal-plants",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/action.en.d245a3af5dbf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d245a3af5dbf63447e95a7306aeee7b919a3c93ef1971c1b11aaadff600b204a",
            "sha256": "d6687a332e1f5ff10b723939f0be219eec1c232e3eed7a9485f72f63a5f13d25",
            "duration_seconds": 25.339,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find the botanical name and listed part in a current PITAHC card.",
                "start_ms": 2380,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If identity is uncertain, do not prepare or provide it.",
                "start_ms": 9360,
                "end_ms": 14120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask about symptoms and medicines; consult a clinician.",
                "start_ms": 14420,
                "end_ms": 19020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Compare two cards and identify what needs confirmation before any use.",
                "start_ms": 19320,
                "end_ms": 25280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/action.fil.efe71e2ba5d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "efe71e2ba5d02cb0facbbb679dbfdcd52cf5126adb38e5b15f77e076b30e7ebd",
            "sha256": "1c39b69d8aa867825636f5efd51bbebd7ce8730aaf62f20bf73a0d994ea66fa4",
            "duration_seconds": 27.115,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hanapin ang botanical name at nakalistang bahagi sa current PITAHC card.",
                "start_ms": 2620,
                "end_ms": 10180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi tiyak ang identity, huwag maghanda o magbigay.",
                "start_ms": 10480,
                "end_ms": 15320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tanungin ang sintomas at gamot; iugnay sa clinician.",
                "start_ms": 15620,
                "end_ms": 20220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihambing ang dalawang card at tukuyin ang kailangan pang kumpirmahin bago ang anumang paggamit.",
                "start_ms": 20520,
                "end_ms": 27040
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/check-start.en.d4e692924da3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d4e692924da317b7fe01abb1a26b66a4c7aa69b7a03405095a76130d06a8e51d",
            "sha256": "573abb636c52b5c6c22feaa84aec07d30961b8829c39b9780d0810cd3c08ee93",
            "duration_seconds": 13.688,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2620,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5280,
                "end_ms": 9000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start from the botanical name and part on a current card.",
                "start_ms": 9300,
                "end_ms": 13620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/check-start.fil.3341ef11b92e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3341ef11b92e3ca3e77ee7d04255f1aed3ae38349942c4acf50192fbcae735a3",
            "sha256": "f76e59a72ffbc75ddefc7e137e2467fe20ca2db3ad8df33fd3cca72980b19451",
            "duration_seconds": 14.315,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5200,
                "end_ms": 9800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magsimula sa botanical name at bahagi sa current card.",
                "start_ms": 10100,
                "end_ms": 14260
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/check-transfer.en.4ec2e256232f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ec2e256232f8ca43dee0bf73e7c4fcb3af493f3aa4ccb5c628d6a49611c55c4",
            "sha256": "f49b5ef3d41d1af2b37f7f4f47ee110952f8abcd982383fb07cea0b4f0e978b2",
            "duration_seconds": 14.237,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2660,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "After the card check, ask about symptoms and medicines; consult a clinician.",
                "start_ms": 8020,
                "end_ms": 14180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/check-transfer.fil.dc9d9dc905fa.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dc9d9dc905fa51ec3e836f7cada1aa28e7650f48ab0917693b87d610a08f127a",
            "sha256": "dfc3606e0c85ebfb6d4a319e1e35e010f9f422f9995e94977e828c321fd3a41a",
            "duration_seconds": 15.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2980,
                "end_ms": 4780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5080,
                "end_ms": 8360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pagkatapos ng card check, itanong ang sintomas at gamot; iugnay sa clinician.",
                "start_ms": 8660,
                "end_ms": 15060
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/example.en.c9f372865232.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c9f372865232a69e855e580d44d43167f6a882669929367780dbbd20a46691b5",
            "sha256": "018510967bceec374aedd9d16460c5f3cf944d942b2d6815b3b60a62e3f8f319",
            "duration_seconds": 34.403,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW reads the current card and listens to the resident.",
                "start_ms": 2100,
                "end_ms": 7100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Both plants are called “tsaang gubat,” but the card lists one botanical name and part.",
                "start_ms": 7400,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The identity of the yard plants is uncertain, so the BHW does not prepare or provide either one.",
                "start_ms": 13980,
                "end_ms": 22420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The BHW asks about symptoms and medicines and consults a clinician.",
                "start_ms": 22720,
                "end_ms": 28280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Two plants, one name: the card, not the name, guides the check.",
                "start_ms": 28580,
                "end_ms": 34340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/example.fil.7d5af14cf46f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7d5af14cf46ffa196efde2a9407901e74cba36ebdf6c2e871002e13625c5a777",
            "sha256": "e4af1243052b5f7a836199a08f53e67ab040f18d7abbfdae93525f371015d323",
            "duration_seconds": 37.642,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Binasa ng BHW ang kasalukuyang card at pinakinggan ang residente.",
                "start_ms": 2060,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Parehong tinatawag na “tsaang gubat” ang dalawang halaman, pero iisang botanical name at bahagi ang nasa card.",
                "start_ms": 8400,
                "end_ms": 16240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi tiyak ang identity ng mga halaman, kaya hindi naghanda o nagbigay ang BHW.",
                "start_ms": 16540,
                "end_ms": 23820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinanong niya ang sintomas at gamot, at iniugnay ang residente sa clinician.",
                "start_ms": 24120,
                "end_ms": 30400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dalawang halaman, iisang pangalan: ang card, hindi ang pangalan, ang batayan.",
                "start_ms": 30700,
                "end_ms": 37580
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/next-step.en.83bcdfdbe87d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "83bcdfdbe87d4c7dd00572c5000b8fcb2f7d14c75ed4cbb0dde078900599e0a9",
            "sha256": "a6e250862563f6bd3e1dafea1ca7d46cf43a9b745502b1faadea9ff197bf8097",
            "duration_seconds": 15.856,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, review the card with a supervisor.",
                "start_ms": 2580,
                "end_ms": 6140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mark what needs confirmation before a real consultation.",
                "start_ms": 6440,
                "end_ms": 10920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, mark with a supervisor what needs confirmation.",
                "start_ms": 11220,
                "end_ms": 15780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/next-step.fil.754bae2a594d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "754bae2a594d04d98e6d684f44e94334d7ed0dcc2d6c02aa42ade00ac2601256",
            "sha256": "4924d7a36b73108ea61417e9a6a746b806918d5e031f684dc0867a001ec667ff",
            "duration_seconds": 18.521,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, dalhin ang card sa supervisor.",
                "start_ms": 2820,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Markahan ang dapat kumpirmahin bago gamitin sa tunay na konsultasyon.",
                "start_ms": 6720,
                "end_ms": 12640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, markahan kasama ang supervisor ang dapat kumpirmahin.",
                "start_ms": 12940,
                "end_ms": 18460
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scene.en.485a5ce17d0c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "485a5ce17d0c1e189796765c9e76e76e10ebac1ff895398850e6d99e416032ff",
            "sha256": "8ba77d3ac1024537124d7fc088cd6ba833e22a3716066274d98d43de2b3ff99a",
            "duration_seconds": 15.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Two yard plants share the local name “tsaang gubat.”",
                "start_ms": 1940,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A resident asks which one to use.",
                "start_ms": 6680,
                "end_ms": 9760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: two yard plants are both called “tsaang gubat”",
                "start_ms": 10060,
                "end_ms": 15060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scene.fil.c12f4794501c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c12f4794501c26e381dae33b3c0c5780aef8b94ebea0654aae0baf5da23d9257",
            "sha256": "9f65418374ac75c430e0645a0c99bfd5a8eaf6685e5c907692f2a4658c57404d",
            "duration_seconds": 17.528,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dalawang halaman sa isang bakuran ang parehong tinatawag na “tsaang gubat.”",
                "start_ms": 1740,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong ang residente kung alin ang gagamitin.",
                "start_ms": 8000,
                "end_ms": 11520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: dalawang halaman sa bakuran ang tinatawag na “tsaang gubat”",
                "start_ms": 11820,
                "end_ms": 17460
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scope.en.c72be68bc2e6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c72be68bc2e6fde15c0718f3ebcfb93dca7960eeff787c6f3ebe55885dd61e54",
            "sha256": "ff59a3eacb871507a5b11ad4589a3bf223c0f7856280acf3e2865cdf025e9c1b",
            "duration_seconds": 18.756,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A local name, picture or “natural” label alone does not establish identity, efficacy or safety.",
                "start_ms": 2500,
                "end_ms": 11900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A name, picture or “natural” label is not proof of identity or safety.",
                "start_ms": 12200,
                "end_ms": 18680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scope.fil.d07784a4502e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d07784a4502e3a6ab34b79b7540fb126264d1361d86ed600c234fb6e6f436f6f",
            "sha256": "e8bf078d60e69b40a32b6c997faaa6e7b3d6f45fbd1af53341f84bb90272aa0f",
            "duration_seconds": 21.185,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang local name, larawan at “natural” na label ay hindi sapat na patunay ng identity, bisa o kaligtasan.",
                "start_ms": 3460,
                "end_ms": 13300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi patunay ng identity o kaligtasan ang pangalan, larawan o “natural” na label.",
                "start_ms": 13600,
                "end_ms": 21120
              }
            ]
          }
        }
      }
    },
    "poisoning-response": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/action.en.097459e8f1fd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "097459e8f1fd91e60a3f08034089d479c6a5cc39190262a69146cd7c26708e7e",
            "sha256": "f7abd1921ac1dedac7581be50e781e4c4943b31655b6fafeeeec824e07f8881b",
            "duration_seconds": 40.098,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Avoid exposure, move others away and activate the verified emergency or poison-advice route.",
                "start_ms": 2100,
                "end_ms": 9940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Read the product label only if you can do so without exposure, such as from a container already away from the spill or held by someone else.",
                "start_ms": 10240,
                "end_ms": 20520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Give the label, estimated time, exposure route, symptoms and age to the responder.",
                "start_ms": 20820,
                "end_ms": 29340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Follow their instructions.",
                "start_ms": 29640,
                "end_ms": 31920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Rehearse the information call from a fictional label while keeping the simulated scene clear of exposure.",
                "start_ms": 32220,
                "end_ms": 40020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/action.fil.5af6cc549e65.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5af6cc549e651a5e57d340e79b73f1639538363c0ecc2c5652a59abce767fe0c",
            "sha256": "2789cf38cbffd858f3c22ea6bd42b7e8d99faa25667b8709a40944c37308e746",
            "duration_seconds": 38.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang exposure, ilayo ang iba at tawagan ang kumpirmadong emergency o poison adviser.",
                "start_ms": 2700,
                "end_ms": 10860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Basahin lamang ang label kung walang exposure, gaya ng lalagyang malayo na sa spill o hawak ng iba.",
                "start_ms": 11160,
                "end_ms": 18720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ibigay ang label, tinatayang oras, paraan ng exposure, sintomas at edad.",
