          "en": {
            "src": "/training/audio/08-osh/safety-controls/body.en.16e8bb1b2f20.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "16e8bb1b2f20ad36063dbe8b898e5103d03542ddb19441c47e3c0ab8b4add933",
            "sha256": "04f6016f073b5b67bee637f4ea1252f4fbbf6571cb40e20ba3024eedfaf098ca",
            "duration_seconds": 36.415,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Protect the body during work",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana walks far and often stands for long periods.",
                "start_ms": 2540,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Plan breaks and changes of position, use comfortable footwear and a supportive chair.",
                "start_ms": 7480,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Arrange supplies to reduce repeated bending and heavy carrying; ask for lifting assistance.",
                "start_ms": 14100,
                "end_ms": 21100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Report pain to the supervisor and seek assessment when needed.",
                "start_ms": 21400,
                "end_ms": 25920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Enduring pain is not proof of dedication.",
                "start_ms": 26220,
                "end_ms": 29900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safer posture, breaks and sensible carrying are part of work preparation.",
                "start_ms": 30200,
                "end_ms": 36360
              }
            ]
          },
