            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4f311cecf7ef5f18a5282af67483a010df7d5aff6bb5c20ee6f8d1360480be39",
            "sha256": "c5e6030b4587c5d37a4303ad3b879e1dc76b740790b7744298e57d0c5a65f8a0",
            "duration_seconds": 30.563,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Look for hazards before approaching.",
                "start_ms": 2500,
                "end_ms": 5220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Direct the bystander to activate the locally confirmed emergency route.",
                "start_ms": 5520,
                "end_ms": 10560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Check response and normal breathing from a safe position; share location and observed facts.",
                "start_ms": 10860,
                "end_ms": 17460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Wait for trained help and follow the local referral plan.",
                "start_ms": 17760,
                "end_ms": 22120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mark hazards, assign the call, state response and breathing observations, and give a concise location report.",
                "start_ms": 22420,
                "end_ms": 30500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/scene-help-referral/action.fil.97e07f758f5f.mp3",
