            "sha256": "e6ae6dda39bff381c47cabb20a5532b44bc183c632f27dcded79fb91808b74d6",
            "duration_seconds": 31.504,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tingnan muna ang panganib bago lumapit.",
                "start_ms": 2260,
                "end_ms": 5460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pakiusapan ang saksi na tumawag sa kumpirmadong emergency contact.",
                "start_ms": 5760,
                "end_ms": 10680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Suriin ang tugon at normal na paghinga kung ligtas.",
                "start_ms": 10980,
                "end_ms": 16020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ibigay ang lokasyon at nakita.",
                "start_ms": 16320,
                "end_ms": 19280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sundin ang lokal na referral.",
                "start_ms": 19580,
                "end_ms": 22260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tukuyin ang panganib, magtalaga ng tatawag, ilarawan ang tugon at paghinga, at ibigay ang lokasyon.",
                "start_ms": 22560,
                "end_ms": 31440
              }
