        "example": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/example.en.c110ac2d027f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c110ac2d027f5940756ad647bb612c2c1a6223062e73874523169f6966acc7ae",
            "sha256": "6f09a91eb7d6c14e873978fb4095fe3d8577a1a9c9236801151107197d8617ba",
            "duration_seconds": 35.579,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Safety: report the blocking box and arrange a clear walkway.",
                "start_ms": 1980,
                "end_ms": 7540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Self-discipline: carry out assigned checks without repeated reminders.",
                "start_ms": 7840,
                "end_ms": 13480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sustain: repeat and review the routine.",
                "start_ms": 13780,
                "end_ms": 17700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tess and staff agree on a daily checklist and a Friday review.",
                "start_ms": 18000,
                "end_ms": 23160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "All seven categories matter, not just sweeping.",
                "start_ms": 23460,
                "end_ms": 27460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Checks all seven categories and proposes a safe, authorized improvement with an owner and review date.",
                "start_ms": 27760,
                "end_ms": 35520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/example.fil.69ef92f0daef.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "69ef92f0daefbe8588891a4a2f329324cee5b69df6f7d838c7c92ab0f636e7a6",
