            "duration_seconds": 40.908,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Safety: iulat ang kahong nakaharang at ipaayos ang daan.",
                "start_ms": 1860,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Self-discipline: gampanan ang nakatalagang pagsusuri nang hindi laging inuutusan.",
                "start_ms": 7880,
                "end_ms": 14840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sustain: ulitin at balikan ang routine.",
                "start_ms": 15140,
                "end_ms": 19380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Napagkasunduan ni Tess at staff ang araw-araw na checklist at pagsusuri sa Biyernes.",
                "start_ms": 19680,
                "end_ms": 26400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kumpleto ang pitong kategorya; hindi lang pagwawalis.",
                "start_ms": 26700,
                "end_ms": 30900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nasusuri ang lahat ng pitong kategorya at may ligtas, awtorisadong pagbabago na may responsable at petsa ng pagbalik.",
                "start_ms": 31200,
                "end_ms": 40840
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/next-step.en.c074f470b75e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c074f470b75e1d5588b9e561fd0e22e8749305e20e43befdb6cc3eb695781f17",
            "sha256": "425c38061d1cff2a4bdd144114ee5c52ffba7fc0d3ef78688f8ff8767a4809e5",
            "duration_seconds": 27.246,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tess’s group has a checklist, owner and review date.",
