            "duration_seconds": 29.884,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May contact at takdang update na si Pilar.",
                "start_ms": 2620,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Susuriin pa ng staff ang paggamit ng naunang tala.",
                "start_ms": 6560,
                "end_ms": 10880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, gumawa ng mapa ng kathang-isip na pagbisita at ipasuri ang isang pagbabago.",
                "start_ms": 11180,
                "end_ms": 18500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: integrated — magkakaugnay ang angkop na serbisyo at tagapagbigay.",
                "start_ms": 18800,
                "end_ms": 26120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 26420,
                "end_ms": 29820
              }
            ]
          }
