            "content_hash": "ee8a72c081cc976ce66b36b46babc9e07cb802f9979184d1b387af57c265855c",
            "sha256": "4f3b8ae71d6733425ad137df452b6679dd866adef0b5bb1af4493d2db53256d1",
            "duration_seconds": 27.507,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pilar has returned to the BHS twice.",
                "start_ms": 2140,
                "end_ms": 5860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On the first visit, the staff contact was unclear.",
                "start_ms": 6160,
                "end_ms": 10080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On the second, she was asked to write the same details again.",
                "start_ms": 10380,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She works in the afternoon.",
                "start_ms": 15120,
                "end_ms": 17320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "BHW Arnel wants to help without promising that everything will finish in one day.",
                "start_ms": 17620,
                "end_ms": 24380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Where could a barrier be reduced?",
                "start_ms": 24680,
                "end_ms": 27440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scene.fil.c8b3b4eff4b2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c8b3b4eff4b23f1eb970538831f4d64ccec7353c9cd6fa512eadea9f8a2360d2",
            "sha256": "37606ddbb85263a682d9940b6e8ccc0ce896ee7bab977cf5a674b929c656fd16",
            "duration_seconds": 28.317,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dalawang beses nang bumalik si Pilar sa BHS.",
                "start_ms": 1820,
                "end_ms": 5740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa unang punta, hindi malinaw kung aling staff ang lalapitan.",
                "start_ms": 6040,
                "end_ms": 10720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa ikalawa, pinasulat muli ang parehong detalye.",
                "start_ms": 11020,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May trabaho siya sa hapon.",
                "start_ms": 15480,
                "end_ms": 17720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gustong tumulong ni BHW Arnel nang hindi nangangakong matatapos ang lahat sa isang araw.",
                "start_ms": 18020,
                "end_ms": 24900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Saan maaaring bawasan ang hadlang?",
                "start_ms": 25200,
                "end_ms": 28240
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scope.en.67b9fc42694b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "67b9fc42694b147c8d1ac91671dc56694e6ef1b834f10648f9d26d5bf9e8b08b",
