            "duration_seconds": 29.388,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Integrated service connects the appropriate providers.",
                "start_ms": 2500,
                "end_ms": 6460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It does not mean the BHW delivers every service.",
                "start_ms": 6760,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Do not remove a form or check that staff require.",
                "start_ms": 11660,
                "end_ms": 15780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not change queue priority without authorization.",
                "start_ms": 16080,
                "end_ms": 20000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report barriers and have the proposal reviewed.",
                "start_ms": 20300,
                "end_ms": 24100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm boundaries and requirements with the appropriate person.",
                "start_ms": 24400,
                "end_ms": 29320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scope.fil.778e36b23012.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "778e36b230122845e931a00cb176b297c7044aeea36d16c91bda3468ae29fe1e",
            "sha256": "9d4866d3cd940207e6410dbaa2e3db842cfe697ddfa62797b6cc4745c6364a5c",
            "duration_seconds": 32.47,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang integrated na serbisyo ay may ugnayan sa tamang tagapagbigay.",
                "start_ms": 3180,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ibig sabihin na gagawin ng BHW ang lahat ng serbisyo.",
                "start_ms": 8760,
                "end_ms": 14080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag alisin ang form o pagsusuring kailangan ng staff.",
                "start_ms": 14380,
                "end_ms": 18940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag baguhin ang pila o prayoridad nang walang awtorisasyon.",
                "start_ms": 19240,
                "end_ms": 23960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Iulat ang hadlang at ipasuri ang mungkahi.",
                "start_ms": 24260,
                "end_ms": 28220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin ang saklaw at kailangan sa tamang tao.",
                "start_ms": 28520,
                "end_ms": 32400
              }
            ]
          }
        }
