    "trust-and-core-group": {
      "module": "chapter2/06-community-mobilization",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/action.en.f12de6dbec53.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f12de6dbec53d65c862ce92ea147937ebef0e637f1b3d9e1654969a54fd3441c",
            "sha256": "7b230a355abdf657b3cb4ee69212650df2da1590ba292b0d892e1bd86ab556ba",
            "duration_seconds": 31.896,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Explain the purpose and agree on respectful discussion.",
                "start_ms": 2740,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Invite everyone to contribute, allowing people to pass.",
                "start_ms": 7360,
                "end_ms": 11760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Summarize different suggestions.",
                "start_ms": 12060,
                "end_ms": 14700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Consider working with the existing group.",
                "start_ms": 15000,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Identify willing members, clarify roles and ask them to restate the agreement.",
                "start_ms": 18180,
                "end_ms": 24660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "As Ina, state the purpose, invite each voice and confirm two voluntary roles.",
                "start_ms": 24960,
                "end_ms": 31840
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/action.fil.d3855055eef6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d3855055eef653550b20d84226a35e2032b9369e17eaad7d5584c1f63aab6c33",
            "sha256": "15fe61186cb3687643c41878a89f19afebf7d9c74fec014968dc6a3597769419",
            "duration_seconds": 39.236,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipaliwanag ang layunin at magkasundo sa magalang na usapan.",
                "start_ms": 2580,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Anyayahang mag-ambag ang bawat isa; payagang lumampas muna kung ayaw magsalita.",
                "start_ms": 8160,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ibuod ang magkakaibang mungkahi.",
                "start_ms": 15060,
                "end_ms": 17980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alamin kung makikipagtulungan sa umiiral na grupo.",
                "start_ms": 18280,
                "end_ms": 22280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin ang handang kasapi, linawin ang papel at ipaulit ang napagkasunduan.",
                "start_ms": 22580,
                "end_ms": 29380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bilang si Ina, sabihin ang layunin, anyayahan ang bawat boses at kumpirmahin ang dalawang kusang tungkulin.",
                "start_ms": 29680,
                "end_ms": 39160
              }
            ]
          }
        },
