            "sha256": "41f107cab4b2dbac29df491fe8f96d63814a74aa8cd0f341dff5f37b3437317a",
            "duration_seconds": 14.211,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2700,
                "end_ms": 4620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
