            "duration_seconds": 13.453,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
