            "content_hash": "a7eb79a5ddd51b2dbc04f79c7d7231ca38f63d4b276d6ffbfd2b95ab4d675935",
            "sha256": "78c0225fa113e7c87f2efdba90ae443a80e87a1ed6bb53cba684a905ab7d6ab7",
            "duration_seconds": 14.524,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2460,
                "end_ms": 4620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4920,
                "end_ms": 8200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nasusuri ang umiiral na grupo at nililinaw ang handang gagampan.",
                "start_ms": 8500,
                "end_ms": 14460
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/example.en.09e755dfe3ed.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "09e755dfe3ed2b3efc35307cba25c99e9a3d0c3890f64bac45fa7b3cc964d638",
            "sha256": "3dfa32be917fdd1e6586d4eee083a8d1d8b0e6d0f62c8c008a849c60d5be4e8e",
            "duration_seconds": 39.158,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ina: “We have heard about chat.",
                "start_ms": 2100,
                "end_ms": 5700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sari, would you like to share another approach?”",
                "start_ms": 6000,
                "end_ms": 9360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sari suggests personal invitations.",
                "start_ms": 9660,
                "end_ms": 12700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The group chooses to work with the existing association.",
                "start_ms": 13000,
                "end_ms": 17120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The leader agrees to receive confirmed updates, and Sari to propose options for people without phones.",
                "start_ms": 17420,
                "end_ms": 25140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Quiet Eva is not assigned a role without agreement.",
                "start_ms": 25440,
                "end_ms": 30000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Invites contributions, summarizes differences and confirms voluntary roles while considering the existing group.",
                "start_ms": 30300,
                "end_ms": 39100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/example.fil.d9581b8def9a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d9581b8def9a1cd1e5eeb51ece5575cd89041291469e7454357e9e3ac7b2bcb6",
            "sha256": "bf5907fcc13c67caaa65dfb3637c03247b2847a0ca055b5398654f2dab916823",
            "duration_seconds": 46.132,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ina: “Narinig natin ang chat.",
                "start_ms": 2060,
                "end_ms": 5300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sari, gusto mo bang ibahagi ang ibang paraan?”",
                "start_ms": 5600,
                "end_ms": 9160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nagmungkahi si Sari ng personal na paanyaya.",
                "start_ms": 9460,
                "end_ms": 13060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Piniling makipagtulungan ng grupo sa umiiral na samahan.",
                "start_ms": 13360,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pumayag ang lider na tumanggap ng kumpirmadong balita, at si Sari na magmungkahi ng paraan para sa walang cellphone.",
                "start_ms": 18180,
                "end_ms": 28060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi hinirang ang tahimik na si Eva nang walang pahintulot.",
                "start_ms": 28360,
                "end_ms": 33080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nagbibigay ng pagkakataong mag-ambag, nagbubuod ng pagkakaiba at nagkukumpirma ng kusang tungkulin habang isinasaalang-alang ang umiiral na grupo.",
                "start_ms": 33380,
                "end_ms": 46060
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/next-step.en.fbdb23a75f30.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fbdb23a75f30ffc712c5e6d51228bbc00551e92fa7947438e9469acb2e9e895a",
            "sha256": "4a7168de1dd8582eaf84a11f9f612401be49b0b27e0cd00e52363ad732a6bab1",
            "duration_seconds": 27.716,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The core group has willing members and clear initial responsibilities, with room for others to contribute.",
                "start_ms": 2580,
                "end_ms": 10300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, practise the meeting with three fictional roles.",
                "start_ms": 10600,
                "end_ms": 15120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: core group — willing members who help lead with the community.",
                "start_ms": 15420,
                "end_ms": 22100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, practise a short meeting with three fictional roles.",
                "start_ms": 22400,
                "end_ms": 27640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/trust-and-core-group/next-step.fil.8067c7e57124.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8067c7e57124f91ecfd58321b2f8fc36a0c6374d8908e78692238fb55853b31d",
            "sha256": "daa547b66e64f38cd3f5c774472c378c8ee71a6d8283083b89893e202979f3d0",
            "duration_seconds": 32.235,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May handang kasapi at malinaw na unang tungkulin ang pangunahing grupo.",
                "start_ms": 2620,
                "end_ms": 8580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May puwang pa rin para sa iba.",
                "start_ms": 8880,
                "end_ms": 11280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, magsanay ng pulong gamit ang tatlong kathang-isip na papel.",
                "start_ms": 11580,
                "end_ms": 17340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: pangunahing grupo — mga kusang kasaping tutulong mamuno kasama ng komunidad.",
                "start_ms": 17640,
                "end_ms": 25560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, magsanay ng maikling pulong gamit ang tatlong kathang-isip na papel.",
                "start_ms": 25860,
                "end_ms": 32180
              }
            ]
          }
        },
