            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ded8f3fdffa7a2e7ec959edd5bf35d2c34431046630cf3db9f706b7d319d44e4",
            "sha256": "84558c4e2f181efe74338a80bfd3ca8ecf016f1500d4eabfcd6e468228ae7675",
            "duration_seconds": 39.314,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find Peperomia pellucida on the reference card.",
                "start_ms": 2380,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is leafy tops; the use topic is uric-acid or gout concern under clinical advice.",
                "start_ms": 6360,
                "end_ms": 14680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 14980,
                "end_ms": 18260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 18560,
                "end_ms": 21800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ask the health center to assess the pain and current medicines.",
                "start_ms": 22100,
                "end_ms": 26820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Ulasimang bato / pansit-pansitan cards; choose Peperomia pellucida, leafy tops, use and safe next step.",
                "start_ms": 27120,
                "end_ms": 39240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/ulasimang-bato/action.fil.cda0a5c8dc08.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cda0a5c8dc08b054dd63442d5261ca53f0b0b925a0d538ebf7ddecc6a132de78",
