            "duration_seconds": 40.986,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa reference card, hanapin ang Peperomia pellucida.",
                "start_ms": 2540,
                "end_ms": 6620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang nakalistang bahagi ay talbos; ang paksang gamit ay uric-acid o gout concern sa payo ng clinician.",
                "start_ms": 6920,
                "end_ms": 14880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sabihin kung ano ang alam at hindi alam.",
                "start_ms": 15180,
                "end_ms": 18620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itanong ang kasalukuyang gamot at sintomas.",
                "start_ms": 18920,
                "end_ms": 22960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipasuri ang dahilan ng sakit at ang kasalukuyang gamot sa health center.",
                "start_ms": 23260,
                "end_ms": 28580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itugma ang dalawang Ulasimang bato / pansit-pansitan card; piliin ang Peperomia pellucida, talbos, gamit at ligtas na susunod na hakbang.",
                "start_ms": 28880,
                "end_ms": 40920
              }
            ]
          }
        },
