            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0b610cce9c8f0b82c455bc3f4a8ecaad45d19a9aa9f04927e8a81a4e380c7045",
            "sha256": "2f4c64367c4313ecdee7a586ddfe5611070ac59c004b68d8add85ecb5643dcad",
