                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW hears the neighbor's gout claim and does not call Carlo's joint pain gout.",
                "start_ms": 2100,
                "end_ms": 9620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW points to Peperomia pellucida and \"Part: leafy tops\" on the card.",
                "start_ms": 9920,
                "end_ms": 16800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The BHW asks about Carlo's current medicine, says not to stop it, and asks the health center to assess the pain and his medicines.",
                "start_ms": 17100,
                "end_ms": 26900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not call it gout or stop medicine; ask the health center to assess Carlo.",
                "start_ms": 27200,
                "end_ms": 33600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/ulasimang-bato/example.fil.72d8be4099b4.mp3",
