            "duration_seconds": 35.187,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Narinig ng BHW ang sinabi ng kapitbahay tungkol sa gout.",
                "start_ms": 2020,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya tinawag na gout ang sakit sa kasukasuan ni Carlo.",
                "start_ms": 7280,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinuro niya ang Peperomia pellucida at \"Bahagi: talbos\" sa card.",
                "start_ms": 11700,
                "end_ms": 18700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinanong niya ang kasalukuyang gamot ni Carlo at sinabing huwag itong itigil.",
                "start_ms": 19000,
                "end_ms": 24800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipinasuri niya sa health center ang sakit at ang gamot.",
                "start_ms": 25100,
                "end_ms": 29260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag tawaging gout o itigil ang gamot; ipasuri si Carlo sa health center.",
                "start_ms": 29560,
                "end_ms": 35120
              }
            ]
          }
        },
