                "end_ms": 2184
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Avoid this action: Tell the story at a barangay meeting without consent or a safety plan.",
                "start_ms": 2184,
                "end_ms": 8256
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If the next step is uncertain, consult the midwife or approved local protocol.",
                "start_ms": 8256,
                "end_ms": 13968
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Avoid this action: Tell the story at a barangay meeting without consent or a safety plan.",
                "start_ms": 13968,
                "end_ms": 20040
              }
            ]
          },
          "fil": {
