            "duration_seconds": 22.416,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at kaligtasan",
                "start_ms": 0,
                "end_ms": 2328
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Ipahayag ang kuwento sa barangay meeting nang walang pahintulot o safety plan.",
                "start_ms": 2328,
                "end_ms": 9144
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi tiyak ang susunod na hakbang, humingi ng gabay sa midwife o aprubadong lokal na protocol.",
                "start_ms": 9144,
                "end_ms": 15600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Ipahayag ang kuwento sa barangay meeting nang walang pahintulot o safety plan.",
