    "wounds-bleeding": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/action.en.ed78c2c06291.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ed78c2c062919b6c8e2904f0e904812bb817e30b84560df23399b36a42b9c090",
            "sha256": "23ebe1be76f9fb6b048c6af7f897dd03b1869f6c20843c821fcc9188590cee49",
            "duration_seconds": 30.903,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Protect your hands and apply firm direct pressure with clean material.",
                "start_ms": 2500,
                "end_ms": 8020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Activate urgent help for severe or persistent bleeding.",
                "start_ms": 8320,
                "end_ms": 12840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Add material if soaked while maintaining pressure; ask trained staff about further measures and wound follow-up.",
                "start_ms": 13140,
                "end_ms": 21180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On clean props, show hand protection, continuous direct pressure, urgent escalation and a factual wound report.",
                "start_ms": 21480,
                "end_ms": 30840
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/action.fil.5c947ba24147.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5c947ba241471225f55e60b32f208ae7a2e7cd6ef09c55d7c8299850eb8014af",
            "sha256": "12144ee919356a516d364937d94b1c423a0e05e6d7784d618d1f18dadf23750b",
            "duration_seconds": 33.959,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Protektahan ang kamay at idiin nang matatag ang malinis na tela.",
                "start_ms": 2620,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Humingi agad ng tulong kung malubha o tuloy-tuloy ang pagdurugo.",
                "start_ms": 8120,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung mabasa ang tela, magdagdag ng tela habang tuloy ang pressure.",
                "start_ms": 13300,
                "end_ms": 18540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tanungin ang sanay na staff tungkol sa iba pang hakbang at follow-up ng sugat.",
                "start_ms": 18840,
                "end_ms": 24320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa malinis na props, ipakita ang proteksiyon sa kamay, tuloy-tuloy na direct pressure, agarang referral at malinaw na ulat.",
                "start_ms": 24620,
                "end_ms": 33900
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/check-start.en.1f5736ee55cb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
