            "sha256": "488ec1eb41751d75c6a500afe7242a16addf1d6bb0cfa271ed2f63d28ceae7bd",
            "duration_seconds": 14.002,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5400,
                "end_ms": 8800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Protect your hands, then press firmly with clean material.",
                "start_ms": 9100,
                "end_ms": 13940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/check-start.fil.684502c33aa7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "684502c33aa7db9737aba1fff8fb9b1e6d32a0d73c3c352bc42506250d4cd04a",
            "sha256": "70912cdde39b10d4e30ec75718a1a0b96ae9ffe8cd495cedfaf22245470c60da",
            "duration_seconds": 16.039,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2780,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5280,
                "end_ms": 10360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Protektahan ang kamay, saka idiin nang matatag ang malinis na tela.",
                "start_ms": 10660,
                "end_ms": 15980
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/check-transfer.en.c141d232fcf8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c141d232fcf8c68bf35bb7c0e202ab20d1c63f8ea739a92da73f816a64eedbdc",
            "sha256": "9b3d973ab913dcc169ed4ec363c8d9c94f02e7b714c9768a541f7ee6710cbf41",
            "duration_seconds": 13.61,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2620,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "If soaked, add cloth on top and keep pressing; send for help.",
                "start_ms": 8260,
                "end_ms": 13540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/check-transfer.fil.d093d81dd2a3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d093d81dd2a300918a19106dda9e4f9d81f6607b30d01a9af1cc62deccd7e5cf",
            "sha256": "2580223594ec9b9e621ceec55c12005f405c2392c017ef33158af1089a9caf9a",
            "duration_seconds": 15.334,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2460,
                "end_ms": 4340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4640,
                "end_ms": 8600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kung basa, magpatong ng tela at ituloy ang diin; magpatawag ng tulong.",
                "start_ms": 8900,
                "end_ms": 15260
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/example.en.30659f8043e6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "30659f8043e6c0951d200b27adb482fe1427e9a813a6a2cb1f69cbca9d3ae911",
            "sha256": "a0f7a52233aee1085ad42f70c7dd6811e5c0a6135bfe3536fd3f4b4e2b7e3cf5",
            "duration_seconds": 34.717,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea puts on gloves and presses firmly on the cut with a clean cloth.",
                "start_ms": 2100,
                "end_ms": 7220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The cloth soaks through and a bystander wants to wipe it away; Lea keeps the first cloth in place and adds another on top without stopping the pressure.",
                "start_ms": 7520,
                "end_ms": 18280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Because the bleeding persists, she has someone call urgent help.",
                "start_ms": 18580,
                "end_ms": 22980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She then reports where the cut is, what was done and the time.",
                "start_ms": 23280,
                "end_ms": 28120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea never stops pressing: she adds cloth, sends for help and reports.",
                "start_ms": 28420,
                "end_ms": 34660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/example.fil.1c36998252cf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1c36998252cf1914d14463eff74b340fda55394ea88485384f30b801102f5e47",
            "sha256": "521398d8dbf90a9740ffc68c257003d4efc96da503898510abf82bc8f6a4ba1f",
            "duration_seconds": 38.713,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nagsuot ng gloves si Lea at idiniin nang matatag ang malinis na tela sa hiwa.",
                "start_ms": 2020,
                "end_ms": 7980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nabasa ang tela at gusto itong tanggalin ng saksi.",
                "start_ms": 8280,
                "end_ms": 12360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi inalis ni Lea ang unang tela; nagpatong siya ng isa pa nang hindi tumitigil sa pagdiin.",
                "start_ms": 12660,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dahil tuloy ang pagdurugo, nag-utos siyang tumawag ng agarang tulong.",
                "start_ms": 20360,
                "end_ms": 25440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Iniulat niya kung saan ang sugat, ano ang ginawa at ang oras.",
                "start_ms": 25740,
                "end_ms": 31740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi tumitigil sa pagdiin si Lea: nagpapatong, nagpapatawag at nag-uulat.",
                "start_ms": 32040,
                "end_ms": 38640
              }
            ]
          }
        },
