            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2620,
                "end_ms": 8300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 8600,
                "end_ms": 12800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa malinis na props, ipakita ang proteksiyon sa kamay, tuloy-tuloy na direct pressure, agarang referral at malinaw na ulat.",
                "start_ms": 13100,
                "end_ms": 22460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 22760,
                "end_ms": 26000
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/scene.en.276a014e375c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "276a014e375cd77a536871efd4b0b19024e39104caa98de69b87b250a5f50356",
            "sha256": "7d69e08bd663ef981e956ab5889b2a3a9377f8cc5c68216d8758736a51a99cfd",
            "duration_seconds": 16.614,
            "timings": [
              {
                "zone": "heading",
