                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A gardener has a cut that continues to bleed through a clean cloth.",
                "start_ms": 1900,
                "end_ms": 6820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A bystander suggests wiping away the first dressing.",
                "start_ms": 7120,
                "end_ms": 10920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: A gardener's cut keeps bleeding through a clean cloth.",
                "start_ms": 11220,
                "end_ms": 16540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/scene.fil.c23861bcd5b6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c23861bcd5b6433fe067826a08ad0b55a9774bfa51e1fd6d0f0719e7fcc1dba1",
            "sha256": "4664138774646e91d327b7836c6125b03cab5f4680b17d4a59d1ee3a6cee3707",
            "duration_seconds": 18.155,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May hiwa ang hardinero na patuloy na dumudugo sa malinis na tela.",
                "start_ms": 1740,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gustong tanggalin ng saksi ang unang dressing.",
                "start_ms": 7600,
                "end_ms": 11360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Patuloy na dumudugo ang hiwa ng hardinero sa malinis na tela.",
                "start_ms": 11660,
                "end_ms": 18100
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/scope.en.4619b5f41fbf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4619b5f41fbf893a33df4c278eef5773185027dab99da8a650879fe0507d6fb6",
            "sha256": "d84c83cab311bb3a0fefd114bf4b193642585e61b7f353f3e06c2f660873e1c8",
            "duration_seconds": 22.936,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not remove an embedded object, rely on gentle pressure for severe bleeding, or use routine herbal wash, iodine inside the wound or a fixed tetanus deadline without clinical advice.",
                "start_ms": 2580,
                "end_ms": 17740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not remove an embedded object or rely on gentle pressure.",
                "start_ms": 18040,
                "end_ms": 22880
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/wounds-bleeding/scope.fil.4d8a20b52e49.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4d8a20b52e49a20016d4b819f419210422b51d05ada9e92571f59af5f387f847",
            "sha256": "bde95eff80106c7007276a0f5a833973cd506c7618ff4fbb509d8996ddfe7b10",
            "duration_seconds": 25.104,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag bunutin ang nakabaong bagay o umasa sa mahinang pressure sa malubhang pagdurugo.",
                "start_ms": 3100,
                "end_ms": 9220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag gumamit ng rutinang herbal wash o iodine sa loob ng sugat.",
                "start_ms": 9520,
                "end_ms": 15120
              },
              {
