              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is leaves; the use topic is tooth pain requiring dental assessment.",
                "start_ms": 6840,
                "end_ms": 13640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 13940,
                "end_ms": 17420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 17720,
                "end_ms": 20960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Refer the swelling promptly to a dental or health professional and report symptoms.",
                "start_ms": 21260,
                "end_ms": 27460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Yerba buena cards; choose Mentha cordifolia, leaves, use and safe next step.",
                "start_ms": 27760,
                "end_ms": 38720
              }
            ]
