      {
        "module": "03-polisiya-bhs",
        "sections": {
          "check-before-change": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/check-before-change.en.fc4c079fd46f.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "fc4c079fd46f372f339e7727b54e701a2edeb23fca6e46ec7eaad995cac8c74c",
              "sha256": "afcde707b745e4c9e8b12af72e2cc81e09245cb5d26ea658324a6127af37f650",
              "duration_seconds": 64.653,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Coordinate before acting",
                  "start_ms": 0,
                  "end_ms": 2240
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Mimi tells the confirmed responsible person: “I noticed the lights and fan were on in the meeting area after the meeting.",
                  "start_ms": 2540,
                  "end_ms": 10580
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Is another activity planned?",
                  "start_ms": 10880,
                  "end_ms": 13160
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "What is the closing rule, and who is responsible?”",
                  "start_ms": 13460,
                  "end_ms": 17300
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "She explains the specific observation and her questions instead of announcing a change she has already made.",
                  "start_ms": 17600,
                  "end_ms": 25400
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "In this example, they agree first to review the schedule and existing checklist with the person responsible.",
                  "start_ms": 25700,
                  "end_ms": 33020
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Mimi records that agreed first step if the local process requires it.",
                  "start_ms": 33320,
                  "end_ms": 38880
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "This does not automatically approve shutdowns or cuts.",
                  "start_ms": 39180,
                  "end_ms": 43740
                },
                {
                  "zone": "body",
                  "index": 7,
                  "text": "If the rule or authority is unclear, ask for guidance before changing anything.",
                  "start_ms": 44040,
                  "end_ms": 50080
                },
                {
                  "zone": "body",
                  "index": 8,
                  "text": "Lesson 1.3.5 develops one detailed suggestion; here the focus is appropriate first coordination.",
                  "start_ms": 50380,
                  "end_ms": 58620
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Share the observation, check the rule, and clarify the first step.",
                  "start_ms": 58920,
                  "end_ms": 64600
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/check-before-change.fil.e396acdd2ae3.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "e396acdd2ae3d4678ae9acfcff6f715ddd3fa1d46d117b3c4963f61f60c793d5",
              "sha256": "7987643ee18a1980bd56317d739f6aad8a2f4ba9e07d025d947033d9366471ef",
              "duration_seconds": 70.139,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Makipag-ugnayan bago kumilos",
                  "start_ms": 0,
                  "end_ms": 2600
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Sinabi ni Mimi sa kinumpirmang namamahala: “Napansin ko pong nakabukas ang ilaw at fan sa meeting area matapos ang meeting.",
                  "start_ms": 2900,
                  "end_ms": 11180
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "May susunod po bang gagamit?",
                  "start_ms": 11480,
                  "end_ms": 13960
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Ano po ang closing rule, at sino ang responsable?”",
                  "start_ms": 14260,
                  "end_ms": 18820
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Ipinapaliwanag niya ang tiyak na obserbasyon at mga tanong, hindi nag-aanunsiyo ng ginawa nang pagbabago.",
                  "start_ms": 19120,
                  "end_ms": 27400
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Sa halimbawa, pinagkasunduan nilang suriin muna ang schedule at umiiral na checklist kasama ang taong responsable.",
                  "start_ms": 27700,
                  "end_ms": 36140
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Itatala ni Mimi ang napagkasunduang unang hakbang kung kailangan sa lokal na proseso.",
                  "start_ms": 36440,
                  "end_ms": 42440
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Walang awtomatikong approval sa pagsara o pagbabawas.",
                  "start_ms": 42740,
                  "end_ms": 47380
                },
                {
                  "zone": "body",
                  "index": 7,
                  "text": "Kung hindi pa malinaw ang tuntunin o saklaw ng pahintulot, magpatulong bago magbago.",
                  "start_ms": 47680,
                  "end_ms": 53880
                },
                {
                  "zone": "body",
                  "index": 8,
                  "text": "Sa 1.3.5, gagawa ng isang detalyadong mungkahi; dito, mahalaga ang tamang unang pakikipag-ugnayan.",
                  "start_ms": 54180,
                  "end_ms": 63140
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ipaalam ang obserbasyon, tiyakin ang tuntunin, at linawin ang unang hakbang.",
                  "start_ms": 63440,
                  "end_ms": 70080
                }
              ]
            }
          },
          "know-responsibilities": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/know-responsibilities.en.2825a37957e1.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "2825a37957e1d9621ac8d9d587d9d7f7418b3b08f4a68c4f0831ab9413fe7f17",
              "sha256": "abde450916c6cb5fc9790ed372465852d8927740d571c13ed20f52f6903755cc",
              "duration_seconds": 54.387,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Know the rule and responsibility",
                  "start_ms": 0,
                  "end_ms": 2720
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Mimi does not assume she makes the decision because she noticed the concern.",
                  "start_ms": 3020,
                  "end_ms": 7940
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "She asks the confirmed responsible person: “Who is responsible for the meeting area after use?",
                  "start_ms": 8240,
                  "end_ms": 15440
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Is there a closing checklist, and who may authorize a change?”",
                  "start_ms": 15740,
                  "end_ms": 20780
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "The right contact may be the midwife, facility supervisor or another designated person at their BHS; confirm local responsibilities rather than assuming one universal chain of command.",
                  "start_ms": 21080,
                  "end_ms": 34880
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "If the contact is absent, follow the local referral process.",
                  "start_ms": 35180,
                  "end_ms": 39740
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "A colleague agreeing with an idea does not automatically authorize it.",
                  "start_ms": 40040,
                  "end_ms": 45280
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "The action must comply with policy and the limits of the role.",
                  "start_ms": 45580,
                  "end_ms": 50580
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Confirm local responsibility and permission.",
                  "start_ms": 50880,
                  "end_ms": 54320
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/know-responsibilities.fil.70009ede4d3b.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "70009ede4d3b13f3553642856f64b181f12ceff3cedf940571b6359823407476",
              "sha256": "fd2153c49df65f4b1ebf0a8d48a2d1f90ea6f8c059befa8f2369eba24a5b177c",
              "duration_seconds": 58.384,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Alamin ang tuntunin at tungkulin",
                  "start_ms": 0,
                  "end_ms": 3640
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Hindi ipinapalagay ni Mimi na siya ang magdedesisyon dahil siya ang nakapansin.",
                  "start_ms": 3940,
                  "end_ms": 8700
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Itatanong niya sa kinumpirmang namamahala: “Sino po ang responsable sa meeting area pagkatapos gamitin?",
                  "start_ms": 9000,
                  "end_ms": 16520
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "May closing checklist po ba, at sino ang maaaring magpahintulot ng pagbabago?”",
                  "start_ms": 16820,
                  "end_ms": 22740
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Maaaring midwife, facility supervisor o ibang itinalagang tao ang tamang contact sa kanilang BHS; tiyakin ang lokal na tungkulin, huwag manghula ng iisang chain of command para sa lahat.",
                  "start_ms": 23040,
                  "end_ms": 37120
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Kung wala ang contact, sundin ang lokal na proseso para sa pagdulog.",
                  "start_ms": 37420,
                  "end_ms": 42020
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Hindi awtomatikong may pahintulot ang isang mungkahi dahil may pumayag na kasamahan.",
                  "start_ms": 42320,
                  "end_ms": 48680
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Kailangang naaayon ito sa polisiya at saklaw ng tungkulin.",
                  "start_ms": 48980,
                  "end_ms": 53700
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Tiyakin ang lokal na responsibilidad at pahintulot.",
                  "start_ms": 54000,
                  "end_ms": 58320
                }
              ]
            }
          },
          "observe-resource-use": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/observe-resource-use.en.20a90d9e06d7.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "20a90d9e06d7ec76ab10b5e8fb8b9f9eb605aa34413584f8f1fbaf70a6e797d6",
              "sha256": "9cf32c504eba5e9a15e24bb601ef33ab85008185fc77444c332f2d9f99787acf",
              "duration_seconds": 54.491,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Describe what you observed",
                  "start_ms": 0,
                  "end_ms": 2360
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "In this fictional example, Mimi records: “After the meeting, the lights and fan were on in the meeting area; I saw no one there when I checked.”",
                  "start_ms": 2660,
                  "end_ms": 12300
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "She does not write that a colleague is careless or that a particular amount of money is definitely being wasted.",
                  "start_ms": 12600,
                  "end_ms": 20880
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "She does not yet know whether another activity is planned or there is another reason.",
                  "start_ms": 21180,
                  "end_ms": 27060
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "If a local record is needed, include only the date, time, place and specific observation.",
                  "start_ms": 27360,
                  "end_ms": 35920
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Omit patient names or data, guesses about motives, and invented consumption or savings measurements.",
                  "start_ms": 36220,
                  "end_ms": 43060
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "An observation starts a conversation; it is not a conclusion or permission to change something.",
                  "start_ms": 43360,
                  "end_ms": 50520
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "State the facts and what is still unknown.",
                  "start_ms": 50820,
                  "end_ms": 54420
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/observe-resource-use.fil.d745e9469524.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "d745e9469524c1e5441c122eb4d0af062b76262d87f27d257d3719a9f520753e",
              "sha256": "c47ce375795c15487b8cbe17e02fc3c2e53bed6bc31dd571f7efa192ee948768",
              "duration_seconds": 55.928,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Ilarawan ang nakita",
                  "start_ms": 0,
                  "end_ms": 1920
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Sa fictional na halimbawa, itinala ni Mimi: “Pagkatapos ng meeting, nakabukas ang ilaw at fan sa meeting area; wala akong nakitang tao roon sa oras ng pagtingin.”",
                  "start_ms": 2220,
                  "end_ms": 14420
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Hindi niya isinulat na pabaya ang kasamahan o tiyak na nasasayang ang isang halaga ng pera.",
                  "start_ms": 14720,
                  "end_ms": 21920
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Hindi pa niya alam kung may susunod na gawain o ibang dahilan.",
                  "start_ms": 22220,
                  "end_ms": 26660
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Kung kailangan ng lokal na tala, ilagay lamang ang petsa, oras, lugar at tiyak na napansin.",
                  "start_ms": 26960,
                  "end_ms": 34600
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Walang pangalan o datos ng pasyente, haka-haka sa motibo, o imbentong sukat ng konsumo at savings.",
                  "start_ms": 34900,
                  "end_ms": 43380
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Ang obserbasyon ay simula ng pag-uusap, hindi pa hatol o pahintulot na magbago.",
                  "start_ms": 43680,
                  "end_ms": 50600
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Katotohanan muna; sabihin din ang hindi pa alam.",
                  "start_ms": 50900,
                  "end_ms": 55860
                }
              ]
            }
          },
          "protect-service": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/protect-service.en.6faccbea258d.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "6faccbea258d58da5ab766b3dd4675a43cd95062bc2af2e046f8c65945c16df9",
              "sha256": "a831b3d3d56b3090db7fc3e2d6bff7981fb58e89b2716f83b7904c0413424f1d",
              "duration_seconds": 58.018,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Protect service needs",
                  "start_ms": 0,
                  "end_ms": 2240
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "A colleague says: “Let us reduce the supplies on the shelf to save resources.”",
                  "start_ms": 2540,
                  "end_ms": 8100
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Mimi does not do this independently.",
                  "start_ms": 8400,
                  "end_ms": 11120
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Those supplies may be needed for service; noticing lights in a meeting area is different from deciding which supplies to reduce.",
                  "start_ms": 11420,
                  "end_ms": 19780
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "For the meeting area, she first checks the next planned use, requirements for the area, and who is responsible for the closing procedure.",
                  "start_ms": 20080,
                  "end_ms": 29200
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "She does not repair electrical systems, operate clinical equipment controls, reuse clinical supplies or ration services.",
                  "start_ms": 29500,
                  "end_ms": 39900
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "If there is a possible hazard, refer it through the local safety process; do not attempt repairs beyond training.",
                  "start_ms": 40200,
                  "end_ms": 48080
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "A nonclinical example is not automatically free of safety risks.",
                  "start_ms": 48380,
                  "end_ms": 53340
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Do not independently make cuts that may compromise service.",
                  "start_ms": 53640,
                  "end_ms": 57960
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/protect-service.fil.2eb20dc57411.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "2eb20dc574116e39731dc883185c9e3406cce67703b2ab1329ace32e765d87ef",
              "sha256": "772ece5b7ba7dacab8571f807d915c190d9182ac978dc4b5a1ef46a2e0863021",
              "duration_seconds": 64.653,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Unahin ang kailangan ng serbisyo",
                  "start_ms": 0,
                  "end_ms": 3040
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "May kasamahang nagsabing: “Bawasan na lang natin ang gamit sa shelf para makatipid.”",
                  "start_ms": 3340,
                  "end_ms": 8900
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Hindi ito ginagawa ni Mimi nang kusa.",
                  "start_ms": 9200,
                  "end_ms": 12200
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Maaaring kailangan ang mga gamit para sa serbisyo; hindi pareho ang napansing ilaw sa meeting area at pagpapasya kung aling supply ang babawasan.",
                  "start_ms": 12500,
                  "end_ms": 22820
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Sa meeting area, aalamin muna kung may susunod na gawain, kung may requirement sa lugar, at kung sino ang may responsibilidad sa closing procedure.",
                  "start_ms": 23120,
                  "end_ms": 34600
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Hindi siya nagkukumpuni ng kuryente, humahawak ng controls ng clinical equipment, nagre-reuse ng clinical supplies o nagrarasyon ng serbisyo.",
                  "start_ms": 34900,
                  "end_ms": 45780
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Kung may posibleng panganib, idulog ayon sa lokal na safety process; huwag subukang ayusin nang lampas sa pagsasanay.",
                  "start_ms": 46080,
                  "end_ms": 54040
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Kahit nonclinical ang halimbawa, hindi awtomatikong walang safety risk.",
                  "start_ms": 54340,
                  "end_ms": 59620
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Walang sariling pagbawas na maaaring makasira sa serbisyo.",
                  "start_ms": 59920,
                  "end_ms": 64600
                }
              ]
            }
          },
          "resource-check": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/resource-check.en.9f200f222363.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "9f200f22236340791b1d9aaec473aca6630058643d6b1a58a0a4e6a2cc8660f8",
              "sha256": "c0682e15f22dffd69e4611f3d6a7cb1bcb10fb63e8808a42bdcdb55ed5917b51",
              "duration_seconds": 33.541,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Choose the first step",
                  "start_ms": 0,
                  "end_ms": 1720
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "After an activity, you see the lights and fan on in an empty meeting area.",
                  "start_ms": 2020,
                  "end_ms": 7900
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "You do not yet know the next scheduled use or closing procedure.",
                  "start_ms": 8200,
                  "end_ms": 12720
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "A colleague wants to reduce supplies to save resources.",
                  "start_ms": 13020,
                  "end_ms": 17180
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "What is your appropriate first step as a BHW?",
                  "start_ms": 17480,
                  "end_ms": 21400
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Choose and explain your answer, then practice stating what you would report and ask.",
                  "start_ms": 21700,
                  "end_ms": 27900
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Observation → Rule and responsibility → Coordination.",
                  "start_ms": 28200,
                  "end_ms": 33480
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/resource-check.fil.af44af166c9b.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "af44af166c9b91554ac10250a66b3d68221a09a6a7209d73477017276b4a8a7f",
              "sha256": "90194ab9acb6571423da239697aa250a713dbea84ed2443ffe8f1f325af91b20",
              "duration_seconds": 40.751,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Piliin ang unang hakbang",
                  "start_ms": 0,
                  "end_ms": 3160
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Pagkatapos ng isang gawain, nakita mong nakabukas ang ilaw at fan sa bakanteng meeting area.",
                  "start_ms": 3460,
                  "end_ms": 11020
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Hindi mo pa alam ang susunod na schedule o closing procedure.",
                  "start_ms": 11320,
                  "end_ms": 15600
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "May kasamahang gustong magbawas ng supplies para makatipid.",
                  "start_ms": 15900,
                  "end_ms": 20300
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Ano ang angkop mong unang hakbang bilang BHW?",
                  "start_ms": 20600,
                  "end_ms": 25720
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Piliin at ipaliwanag ang sagot, saka sabihin sa sariling pananalita ang iuulat at itatanong mo.",
                  "start_ms": 26020,
                  "end_ms": 33500
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Obserbasyon → Tuntunin at responsibilidad → Pakikipag-ugnayan.",
                  "start_ms": 33800,
                  "end_ms": 40680
                }
              ]
            }
          },
          "section-5": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/section-5.en.57c21804b85e.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "57c21804b85e4868cbd44ff3efefa5896a90c7c7e1c8b16e736d911593ca438a",
              "sha256": "09496782900df00b8fd76dac87ee7292c8bafb87cca24d32621627188bc00837",
              "duration_seconds": 64.888,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Policies before changes",
                  "start_ms": 0,
                  "end_ms": 2720
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Mimi, a BHW, notices that the lights and electric fan are on in an empty meeting area after an activity.",
                  "start_ms": 3020,
                  "end_ms": 11860
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Resources at the BHS are limited.",
                  "start_ms": 12160,
                  "end_ms": 15360
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "How can she help without affecting service?",
                  "start_ms": 15660,
                  "end_ms": 18660
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "The workplace competency includes understanding policies and responsibilities, using electricity, water and supplies efficiently, and being resourceful.",
                  "start_ms": 18960,
                  "end_ms": 30240
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Efficiency does not mean simply reducing everything.",
                  "start_ms": 30540,
                  "end_ms": 34660
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "First, Mimi will check the rule, who is responsible, and whether the area is still needed for service.",
                  "start_ms": 34960,
                  "end_ms": 42600
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Mimi is also the BHW who declined the company offer in the previous lesson; here she applies the same understanding and clear communication to a different situation.",
                  "start_ms": 42900,
                  "end_ms": 54980
                },
                {
                  "zone": "body",
                  "index": 7,
                  "text": "The story is optional; you can complete Read or Slides without watching it.",
                  "start_ms": 55280,
                  "end_ms": 61040
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Protect service while looking for a better way.",
                  "start_ms": 61340,
                  "end_ms": 64820
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-resources/section-5.fil.ad87caad7e88.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "ad87caad7e88ab5c48534fe35cbe02703479388e6c9dffea41980bb41f877f96",
              "sha256": "8e1a755b2e83b480364e69dea6ba708767cb24fb784e82d1224cd5e0930c5853",
              "duration_seconds": 68.65,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Polisiya bago pagbabago",
                  "start_ms": 0,
                  "end_ms": 2760
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Napansin ni Mimi, isang BHW, na nakabukas ang ilaw at electric fan sa bakanteng meeting area matapos ang isang gawain.",
                  "start_ms": 3060,
                  "end_ms": 12140
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Limitado ang rekurso sa BHS.",
                  "start_ms": 12440,
                  "end_ms": 15440
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Paano siya makatutulong nang hindi naaapektuhan ang serbisyo?",
                  "start_ms": 15740,
                  "end_ms": 20180
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Saklaw ng workplace competency ang pag-unawa sa polisiya at responsibilidad, mahusay na paggamit ng kuryente, tubig at gamit, at pagiging maparaan.",
                  "start_ms": 20480,
                  "end_ms": 31560
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Hindi simpleng pagbawas sa lahat ang efficiency.",
                  "start_ms": 31860,
                  "end_ms": 35700
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Una, aalamin ni Mimi ang tuntunin, sino ang responsable, at kung kailangan pa ang lugar para sa serbisyo.",
                  "start_ms": 36000,
                  "end_ms": 45200
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Si Mimi rin ang BHW na tumanggi sa alok ng kumpanya sa naunang aralin; dito, ibang sitwasyon ng parehong pag-unawa at malinaw na pakikipag-usap ang gagamitin niya.",
                  "start_ms": 45500,
                  "end_ms": 56980
                },
                {
                  "zone": "body",
                  "index": 7,
                  "text": "Opsyonal ang kuwento; maaaring tapusin ang Read o Slides nang hindi nanonood.",
                  "start_ms": 57280,
                  "end_ms": 63360
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Protektahan ang serbisyo habang naghahanap ng mas mahusay na paraan.",
                  "start_ms": 63660,
                  "end_ms": 68580
                }
              ]
            }
          }
        }
      }
    ],
    "bhs-improvement": [
      {
        "module": "03-polisiya-bhs",
        "sections": {
          "section-6": {
            "en": {
              "src": "/training/audio/03-polisiya-bhs/bhs-improvement/section-6.en.57fae1b4f6a8.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "57fae1b4f6a84be3e86c067b42c6133e0a9f57b1a5da67bd7dca92d78996e8ea",
              "sha256": "1a2e50d619612064f60560b4d2181a343471e234acb6dae855058b657f474432",
              "duration_seconds": 47.517,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "One efficient suggestion",
                  "start_ms": 0,
                  "end_ms": 2400
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Try it: think of one thing at your own barangay health station that could be made more efficient — for example, a light left on with no one around, water dripping unnoticed, or plastics that shouldn't be used any more under DC 2021-0486.",
                  "start_ms": 2700,
                  "end_ms": 23660
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Write your suggestion as one sentence you could actually say to the midwife or a fellow BHW — not just \"we should change,\" but exactly what to change and why it would help.",
                  "start_ms": 23960,
                  "end_ms": 37360
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "A suggestion that's specific and has a reason is far more likely to be believed and actually carried out than a general complaint.",
                  "start_ms": 37660,
                  "end_ms": 47460
                }
              ]
            },
            "fil": {
              "src": "/training/audio/03-polisiya-bhs/bhs-improvement/section-6.fil.e26c2c989eca.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "e26c2c989ecafb9bc1e50ed2cb702c4c18e4ea67625342df8e2b6233a72dfc34",
              "sha256": "36b51245d45b81925a46b3ae609d076a24bbc92aa865d934d65e6269d550b400",
              "duration_seconds": 53.734,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Isang mungkahing episyente",
                  "start_ms": 0,
                  "end_ms": 2880
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Subukan mo: mag-isip ng isang bagay sa iyong barangay health station na kayang gawing mas episyente — halimbawa, ang ilaw na naiiwang bukas kahit walang tao, o ang tubig na tumutulo nang hindi napapansin, o ang mga plastic na hindi na dapat ginagamit ayon sa DC 2021-0486.",
                  "start_ms": 3180,
                  "end_ms": 29340
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Isulat ang mungkahi mo sa isang pangungusap na kaya mong sabihin sa midwife o sa kapwa BHW — hindi lang \"dapat magbago,\" kundi tiyak na kung ano ang babaguhin at bakit ito makakatulong.",
                  "start_ms": 29640,
                  "end_ms": 43880
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ang mungkahing tiyak at may dahilan ang mas malamang na paniwalaan at tuluyang maisagawa kaysa sa pangkalahatang reklamo.",
                  "start_ms": 44180,
                  "end_ms": 53660
                }
              ]
            }
          }
        }
      }
    ],
    "bhw-legal-role": [
      {
        "module": "04-ra7883",
        "sections": {
          "section-1": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-legal-role/section-1.en.0d4f2018853c.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "0d4f2018853c07db431058c2d41b2fab9c91fe5d267be47024c67188d8afa9db",
              "sha256": "5decdce4bd5aa36450e1358baee02bc6eb4edeef9eb1381af4cdb35c0f00388a",
              "duration_seconds": 51.278,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "The question BHW Josie couldn't bring herself to ask",
                  "start_ms": 0,
                  "end_ms": 4880
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "BHW Josie has been volunteering for six months.",
                  "start_ms": 5180,
                  "end_ms": 9900
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "She once heard another BHW mention a \"hazard allowance\" — but she didn't know whether she too was entitled to it, and she was too embarrassed to ask.",
                  "start_ms": 10200,
                  "end_ms": 21000
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "\"I'm just a volunteer, maybe I'll look greedy if I ask about money,\" she thought.",
                  "start_ms": 21300,
                  "end_ms": 27620
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "The truth is, goodwill alone is not the basis of Josie's work — it has a legal basis, and that same law provides benefits she has every right to ask about — not out of greed, but because it's her right to know them.",
                  "start_ms": 27920,
                  "end_ms": 44880
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Asking about your benefits isn't greed — it's part of being a responsible BHW.",
                  "start_ms": 45180,
                  "end_ms": 51220
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-legal-role/section-1.fil.03e805a3a6d1.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "03e805a3a6d14af693c9c8362fbe8a68356c7a4abf8cac3678b60208cecd80b2",
              "sha256": "6a47b5274f867e9abfd6077785b7d7b20cc76be0ddfa2f0b1ae07cd862820701",
              "duration_seconds": 54.857,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Ang tanong na hindi maitanong ni BHW Josie",
                  "start_ms": 0,
                  "end_ms": 4640
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Anim na buwan nang boluntaryo si BHW Josie.",
                  "start_ms": 4940,
                  "end_ms": 9100
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Narinig niya minsan sa ibang BHW ang tungkol sa \"hazard allowance\" — pero hindi niya alam kung siya rin ba ay dapat makatanggap nito, at nahihiya siyang magtanong.",
                  "start_ms": 9400,
                  "end_ms": 20760
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "\"Boluntaryo lang naman ako, baka mukhang mataray ako kung magtatanong ako tungkol sa pera,\" naisip niya.",
                  "start_ms": 21060,
                  "end_ms": 28220
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Ang totoo, hindi lang kabutihang-loob ang batayan ng gawain ni Josie — may batas ito, at kasama sa batas na iyon ang mga bagay na dapat niyang malaman, hindi dahil sa kasakiman, kundi dahil karapatan niya ang malaman ang mga ito.",
                  "start_ms": 28520,
                  "end_ms": 45280
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ang pagtatanong tungkol sa nararapat matanggap ay hindi kasakiman — ito ay bahagi ng pagiging responsableng BHW.",
                  "start_ms": 45580,
                  "end_ms": 54780
                }
              ]
            }
          },
          "section-2": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-legal-role/section-2.en.9ad79eaa193f.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "9ad79eaa193fe0340664e5acc5fd47d3325deb31db4b27dc5d03d9249da24016",
              "sha256": "97822e7a30343b8c9af2bf52f708fda41e487cf3ca273f827f9d9058e017d6f1",
              "duration_seconds": 61.571,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Where the BHW's duty comes from",
                  "start_ms": 0,
                  "end_ms": 3400
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "A BHW's status as a voluntary frontliner is not simply assumed — it is written into law.",
                  "start_ms": 3700,
                  "end_ms": 11420
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Under Republic Act 7883, a BHW \"voluntarily renders primary health care services\" in the community after receiving proper training and accreditation from the local health board.",
                  "start_ms": 11720,
                  "end_ms": 26080
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "This is also where the Primary Health Care Approach as the guiding strategy comes from, and why the barangay health station exists as a service hub.",
                  "start_ms": 26380,
                  "end_ms": 36740
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "In other words: a BHW is not a \"volunteer\" in the everyday sense only — their duty has a legal basis, and that is also why an accreditation process exists before the work can begin.",
                  "start_ms": 37040,
                  "end_ms": 52280
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "The BHW's duty has a legal basis — it is not just goodwill, it is part of RA 7883.",
                  "start_ms": 52580,
                  "end_ms": 61500
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-legal-role/section-2.fil.a04c9dba7215.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "a04c9dba7215a078553bf5a460dddf03dc8aa7f82005cfb3149fd6a45ee77a5a",
              "sha256": "f3171353dc887ba006f6a3797a0513cefd67f53ac81ca63025746a3665afcd6b",
              "duration_seconds": 67.291,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Saan nanggagaling ang tungkulin ng BHW",
                  "start_ms": 0,
                  "end_ms": 3400
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Ang katayuan ng BHW bilang boluntaryong frontliner ay hindi basta-basta naitalaga — nasa batas ito.",
                  "start_ms": 3700,
                  "end_ms": 11940
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Ayon sa Republic Act 7883, ang BHW ay \"boluntaryong nagbibigay ng primary health care services sa komunidad\" matapos makatanggap ng tamang pagsasanay at akreditasyon mula sa local health board.",
                  "start_ms": 12240,
                  "end_ms": 28720
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Dito rin nakabatay ang paggamit ng Primary Health Care Approach bilang pangunahing estratehiya, at ang pagkakaroon ng barangay health station bilang sentro ng serbisyo.",
                  "start_ms": 29020,
                  "end_ms": 41700
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Sa madaling salita: hindi lang \"boluntir\" sa pangkaraniwang kahulugan ang BHW — may legal na batayan ang kanilang tungkulin, at ito rin ang dahilan kung bakit may proseso ng akreditasyon bago simulan ang gawain.",
                  "start_ms": 42000,
                  "end_ms": 57880
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "May legal na batayan ang tungkulin ng BHW — hindi lang ito kagustuhan, kundi bahagi ng RA 7883.",
                  "start_ms": 58180,
                  "end_ms": 67220
                }
              ]
            }
          }
        }
      }
    ],
    "bhw-benefits": [
      {
        "module": "04-ra7883",
        "sections": {
          "section-3": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-benefits/section-3.en.eb3060b56c9b.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "eb3060b56c9b2933eca5cfa69131ab5bb1301dcb6b2a20496b4614311dcb0cce",
              "sha256": "91c1553e2f17d23e85de08e89cbb71273fbb5f39f1a3d0cd87678f027c842ac2",
              "duration_seconds": 96.496,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "The benefits under RA 7883",
                  "start_ms": 0,
                  "end_ms": 3920
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "RA 7883 names specific benefits a BHW may receive: hazard allowance, subsistence allowance (for BHWs who serve at isolated barangay health stations), training and career enrichment programs, civil service eligibility, free legal services, and priority access to loans.",
                  "start_ms": 4220,
                  "end_ms": 29020
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "The amounts are set locally: the hazard allowance by the local health board and the local peace and order council, and the subsistence allowance by the LGU.",
                  "start_ms": 29320,
                  "end_ms": 39960
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "There is a condition before becoming eligible for these: a BHW must be registered with the local health board of the city or municipality where they render service.",
                  "start_ms": 40260,
                  "end_ms": 52260
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "There is also a limit: the total number of BHWs nationwide must not exceed one percent (1%) of the country's population, and the DOH sets the ideal number of BHWs per household — so registration is not simply given to anyone, and getting it right matters.",
                  "start_ms": 52560,
                  "end_ms": 72920
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "These benefits have specific conditions and administrative procedures.",
                  "start_ms": 73220,
                  "end_ms": 78380
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Confirm eligibility, documentation and any locally funded allowance with the local health board; do not promise automatic or uniform payment.",
                  "start_ms": 78680,
                  "end_ms": 89840
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "These benefits aren't automatic — they depend on proper registration with the local health board.",
                  "start_ms": 90140,
                  "end_ms": 96420
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-benefits/section-3.fil.08b382f14bc6.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "08b382f14bc6ab431f2f0c3cc5cfe5c016557584c1e73a219c004fa93b847b6a",
              "sha256": "66e0b316cf3f48ca4dd4c20aa4d2e2f4b1582733328008684561cb374571c1e0",
              "duration_seconds": 107.964,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Ang mga benepisyo sa ilalim ng RA 7883",
                  "start_ms": 0,
                  "end_ms": 4720
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Kasama sa RA 7883 ang mga partikular na benepisyong maaaring matanggap ng isang BHW: hazard allowance, subsistence allowance (para sa BHW na naglilingkod sa isolated o liblib na barangay health station), mga programa sa pagsasanay at career enrichment, civil service eligibility, libreng legal services, at priority access sa mga loan o pautang.",
                  "start_ms": 5020,
                  "end_ms": 34900
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Lokal na itinatakda ang halaga: ang hazard allowance ng local health board at ng local peace and order council, at ang subsistence allowance ng LGU.",
                  "start_ms": 35200,
                  "end_ms": 46320
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "May kondisyon bago maging eligible dito: kailangang rehistrado ang BHW sa local health board ng lungsod o munisipyo kung saan siya nagbibigay ng serbisyo.",
                  "start_ms": 46620,
                  "end_ms": 58620
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "May limitasyon din: ang kabuuang bilang ng mga BHW sa buong bansa ay hindi dapat lumampas sa isang porsiyento (1%) ng populasyon ng bansa, at ang DOH ang nagtatakda ng angkop na bilang ng BHW kada dami ng sambahayan — kaya't hindi basta-basta tinatanggap ang lahat, at mahalaga ang tamang rehistrasyon.",
                  "start_ms": 58920,
                  "end_ms": 82040
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "May tiyak na kondisyon at prosesong administratibo ang mga benepisyong ito.",
                  "start_ms": 82340,
                  "end_ms": 87380
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Tiyakin sa local health board ang pagiging kwalipikado, dokumento, at allowance na lokal ang pondo; huwag mangako ng awtomatiko o pare-parehong bayad.",
                  "start_ms": 87680,
                  "end_ms": 98440
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ang mga benepisyong ito ay hindi awtomatiko — nakasalalay ito sa tamang rehistrasyon sa local health board.",
                  "start_ms": 98740,
                  "end_ms": 107900
                }
              ]
            }
          }
        }
      }
    ],
    "bhw-eligibility": [
      {
        "module": "04-ra7883",
        "sections": {
          "section-4": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/section-4.en.b66ac55ebd3f.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "b66ac55ebd3fa814a01a83ae06c23d3e52f147bc0edd4288b7604069b79375ce",
              "sha256": "91a3e22071a4eac23ac60cc5d77112aff36b3a834903ef7e1c52cf64b7afd09d",
              "duration_seconds": 103.706,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "BHW Eligibility (BHWE) in the Civil Service",
                  "start_ms": 0,
                  "end_ms": 5920
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "There is a separate qualification for BHW Eligibility under the Civil Service Commission (CSC Resolution No.",
                  "start_ms": 6220,
                  "end_ms": 14460
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "99-2845).",
                  "start_ms": 14760,
                  "end_ms": 18400
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Four conditions are required: accredited by the local health board; completed a minimum of two (2) years of college leading to a degree; actively and voluntarily serving continuously, full time, for five (5) years or more as an accredited BHW; and having a satisfactory service record as an accredited BHW in the community.",
                  "start_ms": 18700,
                  "end_ms": 44380
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "The five years count only if the service was voluntary — no salary or other pay except an honorarium for the whole period — and only from the time the BHW was already accredited.",
                  "start_ms": 44680,
                  "end_ms": 58880
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Service before 20 February 1995, when RA 7883 was approved, does not count.",
                  "start_ms": 59180,
                  "end_ms": 66900
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "A BHW hired under a job order or contract of service can still qualify.",
                  "start_ms": 67200,
                  "end_ms": 73880
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "This is not the same thing as general accreditation — it asks for more, and it is for BHWs who want official eligibility in the civil service.",
                  "start_ms": 74180,
                  "end_ms": 85180
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "BHWE needs four conditions — accreditation, two years of college, five years of continuous, full-time voluntary service as an accredited BHW, and a satisfactory record. Missing even one means it isn't met yet.",
                  "start_ms": 85480,
                  "end_ms": 103640
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/section-4.fil.f700ccb44f55.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "f700ccb44f5503e83f96b28965db4052e4daa2cffe3ef03d3221bda138738a43",
              "sha256": "78d020ed6e359cf3c54d5923839f674e8b38db16dade068133c50b49c49be34f",
              "duration_seconds": 111.987,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Ang BHW Eligibility (BHWE) sa Civil Service",
                  "start_ms": 0,
                  "end_ms": 6280
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "May hiwalay na kwalipikasyon para sa BHW Eligibility sa ilalim ng Civil Service Commission (CSC Resolution No.",
                  "start_ms": 6580,
                  "end_ms": 15940
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "99-2845).",
                  "start_ms": 16240,
                  "end_ms": 19240
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Apat na kondisyon ang kailangan: akreditado ng local health board; nakatapos ng minimum na dalawang (2) taon sa kolehiyo tungo sa isang degree; aktibo at boluntaryong naglilingkod nang tuloy-tuloy at full time sa loob ng limang (5) taon o higit pa bilang accredited BHW; at may satisfactory service bilang accredited BHW sa komunidad.",
                  "start_ms": 19540,
                  "end_ms": 46900
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Bibilangin lang ang limang taon kung boluntaryo ang serbisyo — walang sahod o ibang bayad maliban sa honorarium sa buong panahon — at mula lamang nang akreditado na ang BHW.",
                  "start_ms": 47200,
                  "end_ms": 61240
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Hindi binibilang ang serbisyo bago ang 20 Pebrero 1995, nang maaprubahan ang RA 7883.",
                  "start_ms": 61540,
                  "end_ms": 70020
                },
                {
                  "zone": "body",
                  "index": 5,
                  "text": "Maaari pa ring mag-qualify ang BHW na naka-job order o contract of service.",
                  "start_ms": 70320,
                  "end_ms": 76720
                },
                {
                  "zone": "body",
                  "index": 6,
                  "text": "Hindi ito parehong bagay sa pangkalahatang akreditasyon — mas mataas ang hinihingi nito, at para ito sa mga BHW na nais magkaroon ng opisyal na eligibility sa serbisyo sibil.",
                  "start_ms": 77020,
                  "end_ms": 90500
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Apat na kondisyon ang kailangan sa BHWE — akreditasyon, dalawang taon sa kolehiyo, limang taon ng tuloy-tuloy, full-time at boluntaryong serbisyo bilang accredited BHW, at satisfactory service. Kulang ang isa, hindi pa ito matutugunan.",
                  "start_ms": 90800,
                  "end_ms": 111920
                }
              ]
            }
          }
        }
      },
      {
        "module": "04-ra7883",
        "sections": {
          "section-4": {
