                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itanong kung may naiisip siyang ibang paraan.",
                "start_ms": 6680,
                "end_ms": 10320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mag-alok lamang ng kayang gawin o kumpirmahin.",
                "start_ms": 10620,
                "end_ms": 14740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sabihin: “Maaari kong itanong ang ibang iskedyul.",
                "start_ms": 15040,
                "end_ms": 19280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gusto po ba ninyo iyon?”",
                "start_ms": 19580,
                "end_ms": 21460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kumpirmahin kung sino ang kikilos at kailan magbabalitaan.",
                "start_ms": 21760,
                "end_ms": 26840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gamit ang action card, mag-alok ng dalawang makatotohanang paraan ng pag-follow-up kay Ben. Ipasabi kung alin ang nais niya.",
                "start_ms": 27140,
                "end_ms": 36700
              }
            ]
          }
        },
