                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Salma: “Itatanong ko po sa health center.",
                "start_ms": 5160,
                "end_ms": 8640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tatawagan ko kayo bukas ng alas-dos kung iyon ay ayos.”",
                "start_ms": 8940,
                "end_ms": 14100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ben: “Oo.”",
                "start_ms": 14400,
                "end_ms": 16320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Salma: “Wala pa pong kumpirmadong appointment; update muna bukas.”",
                "start_ms": 16620,
                "end_ms": 22180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Malinaw kung ano ang napagkasunduan at kung ano ang hindi pa tiyak.",
                "start_ms": 22480,
                "end_ms": 27800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itinatala ang piniling hakbang, taong kikilos at oras; kinukumpirma ang pagpili ni Ben at hindi tinatawag na appointment ang update.",
                "start_ms": 28100,
                "end_ms": 39420
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/next-step.en.4ba8089cbf4e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ba8089cbf4ed07356ef96222298961d3ddfedf563e299c6b73290652b9fd649",
            "sha256": "c4c2c8ca512ef04898410f3f1b417d074890074506d286747a885f8a31704383",
            "duration_seconds": 26.958,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Salma writes that she will ask the health center and call Ben tomorrow at two.",
                "start_ms": 2660,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ben repeats the agreement.",
                "start_ms": 8720,
                "end_ms": 11240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On Monday, use the blank action card in practice with a colleague.",
                "start_ms": 11540,
                "end_ms": 16460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Word: follow-up — returning to an agreement to find out the result.",
                "start_ms": 16760,
                "end_ms": 22760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose one action and follow up on the result.",
                "start_ms": 23060,
                "end_ms": 26900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/next-step.fil.a19c2467f811.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a19c2467f8113d7e35d48100ce5030ddd6fe2deb956ec46bd80160bf677e7047",
            "sha256": "eef80a0a0e7f8d7d2ffaa42d46f5b2244ef2ffdf58e5f186cd0d903ba62e0965",
            "duration_seconds": 31.634,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isinulat ni Salma: siya ang magtatanong sa health center at tatawag kay Ben bukas ng alas-dos.",
                "start_ms": 2780,
                "end_ms": 10140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inulit ni Ben ang napagkasunduan.",
                "start_ms": 10440,
                "end_ms": 13360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, gamitin ang blangkong action card sa isang pagsasanay kasama ang katrabaho.",
                "start_ms": 13660,
                "end_ms": 19980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: follow-up — pagbabalik sa napag-usapan upang alamin ang resulta.",
                "start_ms": 20280,
                "end_ms": 27080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng isang hakbang at balikan ang naging resulta.",
                "start_ms": 27380,
                "end_ms": 31580
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/scene.en.262102fd1bc3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "262102fd1bc373e650b5b916d5d46274c3e65915058c7896cf328399f2e3887f",
            "sha256": "d60cd44ca3659e51e46c0d5e03763f3f5366c361831b1bbff87bcbfd4f1b526a",
            "duration_seconds": 23.406,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Salma visits Ben in Marawi.",
                "start_ms": 2020,
                "end_ms": 5980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He cannot go to the health center in the morning because of work.",
                "start_ms": 6280,
                "end_ms": 10760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“I cannot lose a whole day,” he says.",
                "start_ms": 11060,
                "end_ms": 14620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salma does not yet know whether staff offer another schedule.",
                "start_ms": 14920,
                "end_ms": 19440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Find out the concern before choosing a response.",
                "start_ms": 19740,
                "end_ms": 23340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/scene.fil.99a8afa3e8d3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "99a8afa3e8d37f2cc921c3b2b4719a66bc1f953b2308999bda406824ba8152b5",
            "sha256": "d92192c70717b9c3453118aac637ea5ae073870e15cb6f3f792293d5c459ce2a",
            "duration_seconds": 25.365,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Binisita ni BHW Salma si Ben sa Marawi.",
                "start_ms": 2660,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi siya makapunta sa health center sa umaga dahil sa trabaho.",
                "start_ms": 7760,
                "end_ms": 12480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Hindi ko kayang mawala buong araw,” sabi niya.",
                "start_ms": 12780,
                "end_ms": 16500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi pa alam ni Salma kung may ibang iskedyul ang staff.",
                "start_ms": 16800,
                "end_ms": 20960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alamin ang alalahanin bago pumili ng tugon.",
                "start_ms": 21260,
                "end_ms": 25300
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/scope.en.f58080bd5629.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f58080bd562943a77092215b49520df479d50708fb7e85d441c47529a1612d8b",
            "sha256": "be7fe0f7a256f61c7f3a234cd7809f1221954d954b7e643e5430e3918364bf8f",
            "duration_seconds": 29.153,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW helps coordinate; do not guarantee a schedule or force agreement.",
                "start_ms": 2660,
                "end_ms": 9540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If no suitable option is available, ask the midwife or supervisor.",
                "start_ms": 9840,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If there is immediate danger, prioritize emergency services; routine follow-up must not replace urgent help.",
                "start_ms": 15500,
                "end_ms": 23780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Seek the appropriate support when a situation exceeds your role.",
                "start_ms": 24080,
                "end_ms": 29080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/agree-the-next-step/scope.fil.892f27bb6e83.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "892f27bb6e83a940152c226950af390f9c9d0d45bbee82abf9886beefac01855",
            "sha256": "6e31625f5d2a18d573063a2d2f36abc09b763c3c91a2a4bba01eedfb07456d7f",
            "duration_seconds": 33.384,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tungkulin ng BHW na tumulong sa pakikipag-ugnayan, hindi maggarantiya ng iskedyul o pilitin ang pagsang-ayon.",
                "start_ms": 3020,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kapag walang angkop na pagpipilian, humingi ng gabay sa midwife o supervisor.",
                "start_ms": 12080,
                "end_ms": 18240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung may agarang panganib, unahin ang emergency service; huwag gamitin ang ordinaryong follow-up bilang kapalit ng agarang tulong.",
                "start_ms": 18540,
                "end_ms": 27900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong sa tamang tao kapag lampas sa saklaw.",
                "start_ms": 28200,
                "end_ms": 33320
              }
            ]
          }
        }
      }
    },
    "akapulko": {
      "module": "chapter2/05-medicinal-plants",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/action.en.7996df1b5f6e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7996df1b5f6e2b56ec8734d97846e633fde25e73eb5a1967da27d92483ae19ce",
            "sha256": "5f46ccd0623c66c662d55918dd84bf8e004760f8eab9e3f1caf81bc87d0b3a67",
            "duration_seconds": 39.654,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find Senna alata on the reference card.",
                "start_ms": 2500,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is leaves; the use topic is ringworm or another fungal skin concern.",
                "start_ms": 6560,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 13980,
                "end_ms": 17180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 17480,
                "end_ms": 20920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Seek health-center assessment if the rash worsens, spreads, looks infected or the diagnosis is uncertain.",
                "start_ms": 21220,
                "end_ms": 30020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Akapulko cards; choose Senna alata, leaves, use and safe next step.",
                "start_ms": 30320,
                "end_ms": 39600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/action.fil.2723385f8585.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2723385f8585f5bcf0c88ff1c6334f1a1159618a5578ee2cf589f4a321a400e4",
            "sha256": "4f7646353b2bb43d06264c6ceb46e0693abb128da4f422d6328c3df8ad46dfbf",
            "duration_seconds": 41.352,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa reference card, hanapin ang Senna alata.",
                "start_ms": 2700,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang nakalistang bahagi ay dahon; ang paksang gamit ay buni o ibang fungal na problema sa balat.",
                "start_ms": 6880,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sabihin kung ano ang alam at hindi alam.",
                "start_ms": 14660,
                "end_ms": 18220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itanong ang kasalukuyang gamot at sintomas.",
                "start_ms": 18520,
                "end_ms": 22600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung lumalala, kumakalat, may impeksiyon o hindi tiyak ang diagnosis, ipasuri sa health center.",
                "start_ms": 22900,
                "end_ms": 31420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itugma ang dalawang Akapulko card; piliin ang Senna alata, dahon, gamit at ligtas na susunod na hakbang.",
                "start_ms": 31720,
                "end_ms": 41280
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/check-start.en.e12d6b38788d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e12d6b38788d1013636f580b67e1e3fa7f11457f92ea1d8ee647405aabc14737",
            "sha256": "92b0e35932a4f7ca50b68b377bc620c90b0339d08cd49798a2e5552ddd3ac308",
            "duration_seconds": 13.793,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2420,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4800,
                "end_ms": 8280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The card lists leaves of Senna alata; this is not a dose.",
                "start_ms": 8580,
                "end_ms": 13740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/check-start.fil.c388d7cd9b3b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c388d7cd9b3bb9982b5b347de445984e309c4ca3757ca7e6610a9564625f0e58",
            "sha256": "76b6a2a164b208f75b5d3f7d131b5a0f00f2c8902b3bdac576b15d5add97f8c2",
            "duration_seconds": 15.203,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 3060,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5440,
                "end_ms": 10280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dahon ng Senna alata ang nasa card; hindi ito dose.",
                "start_ms": 10580,
                "end_ms": 15140
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/check-transfer.en.7a58bdd5de74.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7a58bdd5de74c796aaabce68c57fe066192397a0235c2d500e8af9406ac3d986",
            "sha256": "68dbbf4e1678de3232d096c4ba243151287990c845b9451251d4e85e346e9689",
            "duration_seconds": 13.767,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2780,
                "end_ms": 4620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4920,
                "end_ms": 7840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Say what is unknown; the health center assesses Ana’s rash.",
                "start_ms": 8140,
                "end_ms": 13700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/check-transfer.fil.8516d60dd44d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8516d60dd44da0db008a9930786245038fad5105d599a023913deb01cadd9692",
            "sha256": "9d73bf904505395ff0dd922c0e1e7848542e47cb945141f41abef631807994f3",
            "duration_seconds": 14.446,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2660,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4960,
                "end_ms": 8160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sabihin ang hindi pa alam; sa health center ipasuri ang pantal ni Ana.",
                "start_ms": 8460,
                "end_ms": 14380
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/example.en.d6869f6a0f4a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d6869f6a0f4a169ebcb11564a4f9a272b23c4c62f59f538d86efc48e02682115",
            "sha256": "d649c81a248ad40f19234d30443b5c200dde7514e7ae51c0a0acd367ff1e89dd",
            "duration_seconds": 38.609,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW shows Ana the card: Akapulko is Senna alata, and the listed part is leaves.",
                "start_ms": 2060,
                "end_ms": 9700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW says the yard plant is not yet confirmed and the rash is not yet diagnosed.",
                "start_ms": 10000,
                "end_ms": 18000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The BHW asks about her medicines and symptoms.",
                "start_ms": 18300,
                "end_ms": 22580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Because the diagnosis is uncertain, the BHW asks Ana to have the rash assessed at the health center.",
                "start_ms": 22880,
                "end_ms": 30800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ana’s case: card matched, yard plant unconfirmed, rash sent for assessment.",
                "start_ms": 31100,
                "end_ms": 38540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/akapulko/example.fil.54b18686a55f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "54b18686a55fa39ba51a51e08393c774ad5c011c5f0721bea5615ecd05c48f1e",
            "sha256": "c88a761c087a8acf5748a3a6410682def7c4ceb383e5ac11dd2037db7a258f7c",
            "duration_seconds": 37.12,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinakita ng BHW kay Ana ang card: Senna alata ang Akapulko, at dahon ang nakalistang bahagi.",
                "start_ms": 1940,
                "end_ms": 10460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinabi ng BHW na hindi pa kumpirmado ang halaman sa bakuran at hindi pa tiyak kung ano ang pantal.",
                "start_ms": 10760,
                "end_ms": 18480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinanong niya ang gamot at sintomas ni Ana.",
                "start_ms": 18780,
                "end_ms": 22380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dahil hindi tiyak ang diagnosis, ipinasuri niya ang pantal sa health center.",
