    "bhs-support-environment": {
      "module": "03-polisiya-bhs",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/check.en.657e24972ee0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "657e24972ee018f0f9a7646d966bd73f10080314a74cbd4fa0dd17b9d0459ffc",
            "sha256": "189bb9a540b5599fabb678e1e5d35f728f64e2ed44e1147a2d2c4bdb85e2a511",
            "duration_seconds": 40.751,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mimi’s decision",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The parent wants someone to talk to about breastfeeding, but Mimi has not yet confirmed the contact or space.",
                "start_ms": 2100,
                "end_ms": 9740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Staff also want to reduce disposable items in their break area.",
                "start_ms": 10040,
                "end_ms": 14480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mimi needs a next step that respects the parent, checks local arrangements and protects safe care.",
                "start_ms": 14780,
                "end_ms": 21940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Start with listening and privacy; confirm trained support and the non-clinical alternative with the supervisor.",
                "start_ms": 22240,
                "end_ms": 29440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Which response can she carry out within her role?",
                "start_ms": 29740,
                "end_ms": 33300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Respectful support and safe waste reduction: listen, confirm, then help.",
                "start_ms": 33600,
                "end_ms": 40680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/check.fil.d45fcac0dcaa.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d45fcac0dcaa01495b39805c2035cbc9023303083159e4066c20950f1dcc2426",
            "sha256": "4f4b63d94083550ce01c73ee48b3e434fe26309893b5c24ba171888a8d260591",
            "duration_seconds": 47.673,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pasya ni Mimi",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nais ng magulang ng kausap tungkol sa breastfeeding, pero hindi pa kumpirmado ni Mimi ang contact o lugar.",
                "start_ms": 2020,
                "end_ms": 9220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nais din ng staff na mabawasan ang disposable na gamit sa kanilang break area.",
                "start_ms": 9520,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pipili si Mimi ng susunod na hakbang na may paggalang, lokal na kumpirmasyon at proteksiyon sa ligtas na pangangalaga.",
                "start_ms": 15060,
                "end_ms": 23860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Unahin ang pakikinig at privacy; tiyakin ang sinanay na suporta at ang non-clinical na alternatibo kasama ang supervisor.",
                "start_ms": 24160,
                "end_ms": 33520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alin sa mga sagot ang maisasagawa niya nang hindi lumalampas sa kanyang papel?",
                "start_ms": 33820,
                "end_ms": 39260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magalang na suporta at ligtas na pagbabawas ng basura: makinig, kumpirmahin, saka umalalay.",
                "start_ms": 39560,
                "end_ms": 47600
              }
            ]
          }
        },
        "facility-roles": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/facility-roles.en.aff4ba6a514f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "aff4ba6a514f2081dc32a48886bad907c0524de82bcab1e22721e69b721edd28",
            "sha256": "bdf4507dee0c88cc0760db1e714bb54b29fffb9e6a23dabb2ae00d5644aca92d",
            "duration_seconds": 59.481,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Facilities and roles",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "RA 10028 strengthens breastfeeding support.",
                "start_ms": 2420,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It requires lactation stations: private, clean and well-ventilated spaces for breastfeeding or expressing milk.",
                "start_ms": 7280,
                "end_ms": 15840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A station must not be in a toilet.",
                "start_ms": 16140,
                "end_ms": 19340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Equipment and facility requirements apply, and exemptions have a formal process.",
                "start_ms": 19640,
                "end_ms": 25480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The institution is responsible for complying with the requirements.",
                "start_ms": 25780,
                "end_ms": 30260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A BHW does not decide an exemption or establish a facility alone.",
                "start_ms": 30560,
                "end_ms": 36760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Mimi asks the midwife or supervisor: “Who is trained to help, and what suitable space and guidance are available here?”",
                "start_ms": 37060,
                "end_ms": 45220
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If something is missing, she raises it with the supervisor rather than making a promise.",
                "start_ms": 45520,
                "end_ms": 51200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The institution is responsible for facilities; the BHW checks, supports and reports gaps.",
                "start_ms": 51500,
                "end_ms": 59420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/facility-roles.fil.36f6d2e57883.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "36f6d2e57883cc6fda2913ecbb912c068af4f3278b91b56c67d75e18988e9d4e",
            "sha256": "7f2dfa549d22d78be80b38d795ce526605b2a765e08b343f61cbd85339ac95b7",
            "duration_seconds": 63.53,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pasilidad at papel",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pinalalakas ng RA 10028 ang suporta sa breastfeeding.",
                "start_ms": 2460,
                "end_ms": 7740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itinatakda nito ang lactation stations: pribado, malinis at maaliwalas na lugar para sa pagpapasuso o pag-express ng gatas.",
                "start_ms": 8040,
                "end_ms": 19040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi ito dapat nasa toilet.",
                "start_ms": 19340,
                "end_ms": 21940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May mga tuntunin sa kagamitan at pasilidad; may pormal ding proseso para sa mga exemption.",
                "start_ms": 22240,
                "end_ms": 29160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pananagutan ng institusyon ang pagsunod sa mga tuntunin.",
                "start_ms": 29460,
                "end_ms": 33260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi ang BHW ang nagpapasya sa exemption o nagtatatag mag-isa ng pasilidad.",
                "start_ms": 33560,
                "end_ms": 39640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Itatanong ni Mimi sa midwife o supervisor: “Sino ang sinanay na makakausap, at anong angkop na lugar at gabay ang mayroon dito?”",
                "start_ms": 39940,
                "end_ms": 49060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung may kulang, ipaaalam niya sa supervisor sa halip na mangako.",
                "start_ms": 49360,
                "end_ms": 54000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Institusyon ang responsable sa pasilidad; BHW ang nagtatanong, umaalalay at nag-uulat ng kakulangan.",
                "start_ms": 54300,
                "end_ms": 63460
              }
            ]
          }
        },
        "listen-connect": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/listen-connect.en.ab196f75cb91.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ab196f75cb915d411c5d2519e578149e091b1474b459cfe6e70e6966f53d58b4",
            "sha256": "d071e054869de3e5c6907386f1cf72dcdcc8b21f9dd80f2acc8af2eae4f6d6d5",
            "duration_seconds": 51.122,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen and connect",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“What would you like to ask, and would you like to speak with someone trained to support you?”",
                "start_ms": 2340,
                "end_ms": 7620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mimi asks calmly.",
                "start_ms": 7920,
                "end_ms": 9840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She respects the parent and avoids discussing personal concerns in front of other people.",
                "start_ms": 10140,
                "end_ms": 16380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not impose a feeding choice or shame the parent.",
                "start_ms": 16680,
                "end_ms": 20800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She confirms who can help and where a private conversation can take place.",
                "start_ms": 21100,
                "end_ms": 26220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "With the parent’s permission, she helps make the connection to a trained health worker under local guidance.",
                "start_ms": 26520,
                "end_ms": 32760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She does not give a diagnosis, treatment or her own clinical feeding instructions.",
                "start_ms": 33060,
                "end_ms": 39380
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If the answer is not yet known, she says she will check with the health team.",
                "start_ms": 39680,
                "end_ms": 44200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen respectfully, protect privacy, and connect to confirmed trained support.",
                "start_ms": 44500,
                "end_ms": 51060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/listen-connect.fil.b9d21e4feb1c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b9d21e4feb1c51a76d0bd1f9bc27eb70307f97efe25ca1e08105f4bc5908396c",
            "sha256": "389911e40d4fd6ee10f1c37c2606ceffd631aecd898655a87a3d1d50e129ff9f",
            "duration_seconds": 56.921,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig at iugnay",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Ano po ang gusto ninyong itanong, at nais po ba ninyong makausap ang sinanay na tagasuporta?”",
                "start_ms": 2100,
                "end_ms": 8060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "mahinahong tanong ni Mimi.",
                "start_ms": 8360,
                "end_ms": 10440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iginagalang niya ang magulang at iniiwasang talakayin ang personal na concern sa harap ng ibang tao.",
                "start_ms": 10740,
                "end_ms": 17260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi niya ipinipilit ang isang feeding choice o pinapahiya ang magulang.",
                "start_ms": 17560,
                "end_ms": 22760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kukumpirmahin niya kung sino ang makatutulong at kung saan maaaring mag-usap nang may privacy.",
                "start_ms": 23060,
                "end_ms": 29580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa pahintulot ng magulang, tutulong siyang makaugnay sa sinanay na health worker ayon sa lokal na gabay.",
                "start_ms": 29880,
                "end_ms": 36920
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi siya magbibigay ng diagnosis, paggamot o sariling clinical feeding instructions.",
                "start_ms": 37220,
                "end_ms": 44180
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung hindi pa alam ang sagot, sasabihin niyang aalamin niya sa health team.",
                "start_ms": 44480,
                "end_ms": 49080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig nang magalang, pangalagaan ang privacy, at iugnay sa nakumpirmang sinanay na suporta.",
                "start_ms": 49380,
                "end_ms": 56860
              }
            ]
          }
        },
        "safe-alternative": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/safe-alternative.en.356da90846a8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "356da90846a863fcede81436a38596f49ae30ac4259d01d8d8afa061b27d44af",
            "sha256": "3a38a7971a3b0522e29f0defce591cf40c8a372fbeadbc5907c44d94c20163ae",
            "duration_seconds": 54.361,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A safe alternative",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi suggests: “Could staff use their own reusable lunch containers in the break area, under the guidance here?”",
                "start_ms": 2260,
                "end_ms": 9380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "This is a non-clinical example that needs the supervisor’s confirmation.",
                "start_ms": 9680,
                "end_ms": 14440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "It is not a suggestion to reuse medical supplies.",
                "start_ms": 14740,
                "end_ms": 18940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The circular considered infection prevention and control in its phased implementation.",
                "start_ms": 19240,
                "end_ms": 25520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A BHW must not independently remove or reuse sterile or necessary clinical supplies.",
                "start_ms": 25820,
                "end_ms": 33980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Trained staff guidance governs infection control and handling healthcare waste.",
                "start_ms": 34280,
                "end_ms": 39800
              },
              {
                "zone": "body",
                "index": 6,
                "text": "If the safety of a change is uncertain, ask first.",
                "start_ms": 40100,
                "end_ms": 43780
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Saving resources must not override safe care.",
                "start_ms": 44080,
                "end_ms": 48200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm the non-clinical alternative; protect supplies needed for safe clinical care.",
                "start_ms": 48500,
                "end_ms": 54300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/safe-alternative.fil.08269badd990.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "08269badd990abf9b0dc0d86140822fa86c4cabd65506bf4632b64d9895a7357",
            "sha256": "a918202523e1dd222d91d3002d34114dd776eef438d26f2faf7a04e7f4f2a042",
            "duration_seconds": 63.843,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ligtas na alternatibo",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mungkahi ni Mimi: “Maaari po bang gumamit ng sariling reusable na lalagyan para sa baon sa staff break area, ayon sa gabay dito?”",
                "start_ms": 2420,
                "end_ms": 13180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Isa itong non-clinical na halimbawa na kailangan munang kumpirmahin sa supervisor.",
                "start_ms": 13480,
                "end_ms": 19080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi ito mungkahing mag-reuse ng gamit na panggamot.",
                "start_ms": 19380,
                "end_ms": 23140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Isinaalang-alang ng circular ang infection prevention at control sa phased implementation nito.",
                "start_ms": 23440,
                "end_ms": 29840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi dapat alisin o muling gamitin ng BHW nang mag-isa ang sterile o kinakailangang clinical supplies.",
                "start_ms": 30140,
                "end_ms": 39100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Mananatili sa gabay ng sinanay na staff ang infection control at paghawak ng healthcare waste.",
                "start_ms": 39400,
                "end_ms": 46160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kung hindi tiyak kung ligtas ang isang pagbabago, magtanong muna.",
                "start_ms": 46460,
                "end_ms": 50900
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi dapat manaig ang pagtitipid sa ligtas na pangangalaga.",
                "start_ms": 51200,
                "end_ms": 55280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin ang non-clinical na alternatibo; protektahan ang kinakailangang ligtas na clinical supplies.",
                "start_ms": 55580,
                "end_ms": 63780
              }
            ]
          }
        },
        "section-3": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/section-3.en.712869b1d454.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "712869b1d454241662fe9956a100b020ffa056d841036471abeff21e5f58a4bf",
            "sha256": "27175a5cb2d35da5f9258f43c3d9fe8d274b1662d17ab1bf97302e4954571417",
            "duration_seconds": 52.376,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A supportive BHS",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A parent carrying an infant arrives at the barangay health station.",
                "start_ms": 2540,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Is there someone I can talk to about breastfeeding?”",
                "start_ms": 7000,
                "end_ms": 10520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "the parent asks BHW Mimi.",
                "start_ms": 10820,
                "end_ms": 13820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mimi listens first.",
                "start_ms": 14120,
                "end_ms": 16280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Two distinct policies matter here: breastfeeding support under RA 10028, and reducing unnecessary single-use plastic under DOH DC 2021-0486.",
                "start_ms": 16580,
                "end_ms": 32780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "They meet in a respectful, safe environment.",
                "start_ms": 33080,
                "end_ms": 36480
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Mimi can help confirm local support and safe practices without promising a service that has not been verified.",
                "start_ms": 36780,
                "end_ms": 44580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Two topics: respectful breastfeeding support and safe reduction of unnecessary waste.",
                "start_ms": 44880,
                "end_ms": 52320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/section-3.fil.aa1eff5fe4ff.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "aa1eff5fe4ffc49a7f51518ec22788877fb72f2d9c00b39a8597c4e0e5d48089",
            "sha256": "1af67e1fabe430545b6f90433c3bcbb6c88eec2dadc3471bfee5d25b849e240b",
            "duration_seconds": 55.301,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Suportadong BHS",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dumating sa barangay health station ang isang magulang na may kargang sanggol.",
                "start_ms": 2540,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“May makakausap po ba ako tungkol sa breastfeeding?”",
                "start_ms": 7880,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong niya kay BHW Mimi.",
                "start_ms": 11700,
                "end_ms": 14180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakinig muna si Mimi.",
                "start_ms": 14480,
                "end_ms": 16400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Dalawang magkaibang polisiya ang mahalaga rito: suporta sa breastfeeding sa ilalim ng RA 10028, at pagbabawas ng hindi kailangang single-use plastic sa ilalim ng DOH DC 2021-0486.",
                "start_ms": 16700,
                "end_ms": 32860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Magkaugnay ang mga ito sa isang magalang at ligtas na kapaligiran.",
                "start_ms": 33160,
                "end_ms": 38480
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Tutulong si Mimi na tiyakin ang lokal na suporta at ligtas na gawain, nang walang ipinapangakong serbisyong hindi pa nakumpirma.",
                "start_ms": 38780,
                "end_ms": 47380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dalawang paksa: magalang na suporta sa breastfeeding at ligtas na pagbabawas ng hindi kailangang basura.",
                "start_ms": 47680,
                "end_ms": 55240
              }
            ]
          }
        },
        "unnecessary-plastic": {
          "en": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/unnecessary-plastic.en.a9020183029f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a9020183029f45ef871e1ec6c5361bb5878a5598338d9ae77453bf75daa9fd29",
            "sha256": "887776dc4017eaba9bf0f585204546c6ed91c136543ee9533bbaf379da633283",
            "duration_seconds": 59.873,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Unnecessary plastic",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mimi also notices disposable items in the staff break area.",
                "start_ms": 2580,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "DOH DC 2021-0486 addresses unnecessary single-use plastics in hospitals, other health facilities and DOH offices.",
                "start_ms": 7480,
                "end_ms": 19680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Its list includes thin plastic cups, drinking straws, coffee stirrers, plastic cutlery and certain thin plastic bags.",
                "start_ms": 19980,
                "end_ms": 30020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The circular set successive phases beginning in 2022 and 2023 for specified settings and groups.",
                "start_ms": 30320,
                "end_ms": 39120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "It does not say that all plastic is illegal everywhere.",
                "start_ms": 39420,
                "end_ms": 43620
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Mimi checks the facility’s current directive with the supervisor: which items are unnecessary, and which safe alternatives are allowed?",
                "start_ms": 43920,
                "end_ms": 52600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check the scope and current directive; this lesson does not treat every plastic item as banned.",
                "start_ms": 52900,
                "end_ms": 59820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/03-polisiya-bhs/bhs-support-environment/unnecessary-plastic.fil.4ce153b289f6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ce153b289f6a00da5954cbde3744a79c3e72494dec1bd85046ffb57fbc0062e",
            "sha256": "25f1af2047f1fda75d483324af5612edb5cce9a7435d196fc0eeec022687b40d",
            "duration_seconds": 63.843,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Hindi kailangang plastic",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Napansin din ni Mimi ang mga disposable na gamit sa lugar ng pahinga ng staff.",
                "start_ms": 2420,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tungkol ang DOH DC 2021-0486 sa hindi kailangang single-use plastics sa mga ospital, ibang health facilities at DOH offices.",
                "start_ms": 8000,
                "end_ms": 20200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kabilang sa listahan nito ang manipis na plastic cups, drinking straws, coffee stirrers, plastic cutlery at ilang manipis na plastic bags.",
                "start_ms": 20500,
                "end_ms": 30620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinakda ng circular ang magkakasunod na yugto simula 2022 at 2023 para sa mga tinukoy na lugar at grupo.",
                "start_ms": 30920,
                "end_ms": 39600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi nito sinasabing ilegal ang lahat ng plastic sa lahat ng lugar.",
                "start_ms": 39900,
                "end_ms": 44220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Titingnan ni Mimi ang kasalukuyang direktiba ng pasilidad kasama ang supervisor: ano ang hindi kailangang gamit, at anong ligtas na alternatibo ang pinapayagan?",
                "start_ms": 44520,
                "end_ms": 55480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang saklaw at kasalukuyang direktiba; hindi blanket ban sa lahat ng plastic ang aralin.",
                "start_ms": 55780,
                "end_ms": 63780
              }
            ]
          }
        }
      }
    },
    "bhw-accreditation": {
      "module": "04-ra7883",
      "sections": {
        "accreditation-application-check": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-application-check.en.7629c6df5b3d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7629c6df5b3d90c04ff8a988c93cf7684e7d4aeae0869369fcb4de4d9ae0b474",
            "sha256": "5eed7464ff6cf87b968ed7b9154912e044a5bd2f176d510963ff76531b7a7cf2",
            "duration_seconds": 46.524,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the supported explanation",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to Card B: there is a committee recommendation, but no verified official decision.",
                "start_ms": 2940,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "What should Demi explain?",
                "start_ms": 10280,
                "end_ms": 12080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Distinguish the recommendation from the board’s decision, name the missing information, and choose a question about the process and official record.",
                "start_ms": 12380,
                "end_ms": 21540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A training certificate, BHWE or job title does not replace accreditation.",
                "start_ms": 21840,
                "end_ms": 29040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose an answer, then read the reasons for all options.",
                "start_ms": 29340,
                "end_ms": 33580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Completing the online lesson is separate from observed competency and does not grant accreditation.",
                "start_ms": 33880,
                "end_ms": 40760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Explain the roles, identify the gap and verify the official decision.",
                "start_ms": 41060,
                "end_ms": 46460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-application-check.fil.7d7d05c82fc5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7d7d05c82fc5d9852db396f4b7eb0a4eb0fabef91e653375a75f9061116488ea",
            "sha256": "b108dcaca5e85f486cab8294e644675c5612ddd21a76aacda3a4c09bde913765",
            "duration_seconds": 51.775,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang tamang paliwanag",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang Card B: may rekomendasyon ng komite, ngunit wala pang natiyak na opisyal na pasya.",
                "start_ms": 2580,
                "end_ms": 9780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ano ang dapat ipaliwanag ni Demi?",
                "start_ms": 10080,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ihiwalay ang rekomendasyon sa pasya ng board, sabihin ang kulang na impormasyon, at pumili ng tanong na magpapalinaw sa proseso at opisyal na tala.",
                "start_ms": 13300,
                "end_ms": 23980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi ipinapalit ang training certificate, Barangay Health Worker Eligibility o job title sa akreditasyon.",
                "start_ms": 24280,
                "end_ms": 31480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin ang sagot, saka basahin ang dahilan para sa lahat ng pagpipilian.",
                "start_ms": 31780,
                "end_ms": 36740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang pagkumpleto sa online lesson ay hiwalay sa obserbasyon ng kasanayan at hindi nagbibigay ng akreditasyon.",
                "start_ms": 37040,
                "end_ms": 44600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaliwanag ang mga papel, tukuyin ang kulang at tiyakin ang opisyal na pasya.",
                "start_ms": 44900,
                "end_ms": 51700
              }
            ]
          }
        },
        "accreditation-follow-up": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-follow-up.en.0448219b69d2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0448219b69d250eeef22bed8f8d12d821cdc2c7c9d7cc0843a5ea2e2ecb1cda7",
            "sha256": "9e07d0c448a47e0fa0130a1d877dc804bdbbf9d06badd6b87a9d8918af53551e",
            "duration_seconds": 52.767,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A question about the process",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi chooses Card B.",
                "start_ms": 2460,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On a blank planning sheet, she writes: ‘For this example with a committee recommendation, which office can confirm whether the local health board has made an official decision, where can it be verified, and what is the next step if none has been made?’",
                "start_ms": 5000,
                "end_ms": 19600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The question names the process, known fact, missing information and proper contact.",
                "start_ms": 19900,
                "end_ms": 26620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask the locally confirmed RHU, municipal or city health office, or board contact for current guidance.",
                "start_ms": 26920,
                "end_ms": 35200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This practice submits no actual application or private documents.",
                "start_ms": 35500,
                "end_ms": 40140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Proof of registration, proof of accreditation and a training certificate should not be treated as interchangeable.",
                "start_ms": 40440,
                "end_ms": 47360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Connect the question to the process, known fact and official record.",
                "start_ms": 47660,
                "end_ms": 52700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-follow-up.fil.3948a718eb8a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3948a718eb8a8d2e900a8c340a798a7f24798a040253ca6ab9b800050a4c9d06",
            "sha256": "1609881257b7e21061887a8d18ccd6a4579605b7642bb3eb96fe9a6b35cca59c",
            "duration_seconds": 59.638,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang tanong tungkol sa proseso",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pinili ni Demi ang Card B.",
                "start_ms": 2580,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa blankong planning sheet, isinulat niya: ‘Para sa halimbawang may rekomendasyon ng komite, aling tanggapan ang makapagsasabi kung may opisyal na pasya na ang local health board, saan ito matitiyak, at ano ang susunod na hakbang kung wala pa?’",
                "start_ms": 5320,
                "end_ms": 20800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tiyak ang tanong: pangalan ng proseso, alam na detalye, kulang na impormasyon at tamang contact.",
                "start_ms": 21100,
                "end_ms": 30100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Makipag-ugnayan sa locally confirmed na RHU, municipal o city health office, o board contact para sa kasalukuyang gabay.",
                "start_ms": 30400,
                "end_ms": 39640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang tunay na aplikasyon o pribadong dokumentong isusumite sa pagsasanay.",
                "start_ms": 39940,
                "end_ms": 44900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang katibayan ng rehistrasyon, katibayan ng akreditasyon at training certificate ay hindi dapat ipagpalit sa isa’t isa.",
                "start_ms": 45200,
                "end_ms": 53840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iugnay ang tanong sa proseso, alam na detalye at opisyal na tala.",
                "start_ms": 54140,
                "end_ms": 59580
              }
            ]
          }
        },
        "accreditation-question": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-question.en.13b00d2cd085.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "13b00d2cd0854c312904f1edeec366479cb4d04096bd511aacf08dabb18d02d7",
            "sha256": "0fcf29c8a70d8e5d93d919b64bbaaa0ae9e422f5318c590a4af9db1fe55b5d1a",
            "duration_seconds": 46.08,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Demi’s question",
                "start_ms": 0,
                "end_ms": 1480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi prepares a question about registration and accreditation.",
                "start_ms": 1780,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "‘Who reviews an application, and how can I verify the official decision?’",
                "start_ms": 6600,
                "end_ms": 11880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This is a fictional situation; we have not established that Demi has an application, registration or accreditation.",
                "start_ms": 12180,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "RA 7883 places accreditation with the local health board under DOH guidelines.",
                "start_ms": 20040,
                "end_ms": 27440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Registration and accreditation are related but distinct steps.",
                "start_ms": 27740,
                "end_ms": 32380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Asking a question, attending training or holding a title does not prove that the process is complete.",
                "start_ms": 32680,
                "end_ms": 40280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Understand the roles and verify the decision; do not assume status.",
                "start_ms": 40580,
                "end_ms": 46020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/accreditation-question.fil.04c3c989905d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "04c3c989905dd997c81f42736d3b352b152dd189f92b4306cbb70e2a9b04076c",
            "sha256": "1eb95e3d4eb198337210f99d886ce6b9b50083f2ce649841cb68934ac69fa3dc",
            "duration_seconds": 49.398,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tanong ni Demi",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naghahanda si Demi ng tanong tungkol sa rehistrasyon at akreditasyon.",
                "start_ms": 1860,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "‘Sino ang tumitingin sa aplikasyon, at saan ko makikita ang opisyal na tala ng pasya?’",
                "start_ms": 7360,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kathang-isip ang sitwasyong ito; hindi pa natin alam kung may aplikasyon, rehistrasyon o akreditasyon si Demi.",
                "start_ms": 13980,
                "end_ms": 21060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa RA 7883, nakaugnay ang akreditasyon sa local health board, ayon sa gabay ng DOH.",
                "start_ms": 21360,
                "end_ms": 29280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Magkaugnay ngunit magkaibang hakbang ang rehistrasyon at akreditasyon.",
                "start_ms": 29580,
                "end_ms": 34740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang pagtatanong, pagdalo sa pagsasanay o pagkakaroon ng titulo ay hindi patunay na tapos na ang proseso.",
                "start_ms": 35040,
                "end_ms": 43760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Unawain ang tungkulin at tiyakin ang pasya; huwag ipagpalagay ang status.",
                "start_ms": 44060,
                "end_ms": 49340
              }
            ]
          }
        },
        "fictional-process-cards": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/fictional-process-cards.en.840b9d7f8cf0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "840b9d7f8cf067511fe1e997cda462ccab86cb575996e2cba56c784a3bb8c5d0",
            "sha256": "b783f96148cb4dbd6479d727c027e6931cbe54d0952b2bf3e3ff1b8ca35379d0",
            "duration_seconds": 51.461,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What is known and missing?",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi uses three fictional practice cards.",
                "start_ms": 2500,
                "end_ms": 5540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A has only a training certificate; it does not prove accreditation.",
                "start_ms": 5840,
                "end_ms": 11120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "B has a committee recommendation but no verified board decision.",
                "start_ms": 11420,
                "end_ms": 17540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "C mentions a board resolution, but its process, scope and verification contact remain unclear.",
                "start_ms": 17840,
                "end_ms": 26240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "None of the cards decides a person’s status.",
                "start_ms": 26540,
                "end_ms": 29660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Match each known fact to the missing information: what is the next step for A, is there an official decision for B, and which official record should be checked for C?",
                "start_ms": 29960,
                "end_ms": 40680
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Do not invent a local form, fee, deadline or result.",
                "start_ms": 40980,
                "end_ms": 45820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Separate known facts from what needs verification; do not guess approval.",
                "start_ms": 46120,
                "end_ms": 51400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/fictional-process-cards.fil.5c8de306e4f2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5c8de306e4f23eacbfd932997f52f638b70b1d2e565bcaeee2f880c6441ed5e2",
            "sha256": "3bd110ba0843960a78b8b77aed37c6ed7b59e71adae03f197fde5264071100fb",
            "duration_seconds": 59.429,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang alam at kulang?",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tatlong kathang-isip na practice card ang ginagamit ni Demi.",
                "start_ms": 2940,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa A, may training certificate lamang; hindi nito pinatutunayan ang akreditasyon.",
                "start_ms": 7360,
                "end_ms": 14000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa B, may rekomendasyon ng komite ngunit walang natiyak na pasya ng board.",
                "start_ms": 14300,
                "end_ms": 20020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa C, may binanggit na board resolution ngunit hindi pa natiyak kung para sa anong proseso, sino ang saklaw at saan ito makukumpirma.",
                "start_ms": 20320,
                "end_ms": 29880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang card na nagpapasya sa status ng tao.",
                "start_ms": 30180,
                "end_ms": 34180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Itapat ang bawat alam na detalye sa kulang na impormasyon: anong susunod na hakbang sa A, may opisyal na pasya na ba sa B, at aling opisyal na tala ang dapat tiyakin sa C?",
                "start_ms": 34480,
                "end_ms": 47600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Huwag mag-imbento ng lokal na form, bayad, deadline o resulta.",
                "start_ms": 47900,
                "end_ms": 53620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihiwalay ang alam na detalye sa kailangang tiyakin; walang hulang approval.",
                "start_ms": 53920,
                "end_ms": 59360
              }
            ]
          }
        },
        "roles-and-records": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/roles-and-records.en.6dcdc61d3504.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6dcdc61d3504d55a9fcdc2aea62a38cf1273b9cf1ad1c122ab83aa285f6688cd",
            "sha256": "1aadbdfe1d71a643143b3a69444bce14bbf8c7c1b5f4851ea82cb5b8ecd7a70a",
            "duration_seconds": 54.674,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Recommendation or decision?",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Compare the two roles.",
                "start_ms": 2940,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A committee helps screen applications and recommend action; the board is responsible for acting and officially recording its decision.",
                "start_ms": 4960,
                "end_ms": 14200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The circular encourages municipal and city health boards to create a committee.",
                "start_ms": 14500,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If none exists yet or creation is pending, the board remains responsible for facilitating registration and accreditation.",
                "start_ms": 20040,
                "end_ms": 28280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Find out the actual local arrangement rather than assume every locality has the same committee and office.",
                "start_ms": 28580,
                "end_ms": 35260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The RHU or municipal or city health office can help identify the proper contact.",
                "start_ms": 35560,
                "end_ms": 42080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Their assistance, an interview or a training certificate does not replace an official decision.",
                "start_ms": 42380,
                "end_ms": 49460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Verify who assists and where the board’s decision is recorded.",
                "start_ms": 49760,
                "end_ms": 54600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/roles-and-records.fil.af8e730e444f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "af8e730e444ff939602283728e95067cd97f81b9fe96abfeb6a05d854c9173d4",
            "sha256": "d59d505508779e733951882de1b6a25c277d5983b698ab531fea9231d563821a",
            "duration_seconds": 58.462,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Rekomendasyon o pasya?",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ihambing ang dalawang papel.",
                "start_ms": 2660,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tumutulong ang komite sa pagsusuri at rekomendasyon; pananagutan ng board ang pag-aksiyon at opisyal na pagtatala ng pasya.",
                "start_ms": 5440,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hinihikayat ng circular ang mga municipal at city health board na bumuo ng komite.",
                "start_ms": 14660,
                "end_ms": 20980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kapag wala pa nito o habang binubuo ito, nananatili sa board ang tungkuling padaliin ang rehistrasyon at akreditasyon.",
                "start_ms": 21280,
                "end_ms": 30480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kaya dapat alamin ang aktuwal na lokal na ayos, sa halip na ipagpalagay na pare-pareho ang komite at opisina sa lahat ng lugar.",
                "start_ms": 30780,
                "end_ms": 40180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Makapagtuturo ng tamang contact ang RHU o municipal o city health office.",
                "start_ms": 40480,
                "end_ms": 46000
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi kapalit ng opisyal na pasya ang kanilang tulong, isang panayam o isang training certificate.",
                "start_ms": 46300,
                "end_ms": 53220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin kung sino ang tumutulong at saan nakatala ang pasya ng board.",
                "start_ms": 53520,
                "end_ms": 58400
              }
            ]
          }
        },
        "section-5": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/section-5.en.04768183e365.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "04768183e3658a00d2c740c1cdc01cd1c2afe6adf078515ad73ceae3ac04ace9",
            "sha256": "70e81bc8f45cb275749d8826681f8f53c5f9fbebd27d24fc48b1d08e610db754",
            "duration_seconds": 72.856,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Responsibilities in the process",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The local health board has specific responsibilities.",
                "start_ms": 2700,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The joint DILG and DOH circular issued in 2023 lists its duties: safeguard registration and accreditation; evaluate and act on applications; record decisions in a board resolution or meeting minutes; issue certificates to qualified BHWs; review and approve benefits using local funds; recommend benefits and fund allocation; provide a copy of the BHW registry to DOH; and monitor services.",
                "start_ms": 7080,
                "end_ms": 38920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "An accreditation decision and review of a benefit using local funds are different decisions.",
                "start_ms": 39220,
                "end_ms": 45820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The board may also create a BHW Registration and Accreditation Committee.",
                "start_ms": 46120,
                "end_ms": 51280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The facilitator guide describes screening, interviews, recommendations to the board and registry preparation as supporting committee tasks.",
                "start_ms": 51580,
                "end_ms": 61700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A recommendation alone is not the board’s official decision.",
                "start_ms": 62000,
                "end_ms": 66200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The board is responsible; the committee assists and decisions have official records.",
                "start_ms": 66500,
                "end_ms": 72780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-accreditation/section-5.fil.a2a6de70165f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a2a6de70165f6343cccc81603cbd5a4ef0277debe02f9d60d4fdfe35daf42fb0",
            "sha256": "ba3ef4c7a7ccd97d69a12bab75c4919a2cf0497ac843347f229ab45f54f2e6f6",
            "duration_seconds": 82.338,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tungkulin sa proseso",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May tiyak na pananagutan ang local health board.",
                "start_ms": 2660,
                "end_ms": 5700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inililista ng magkasanib na circular ng DILG at DOH noong 2023 ang mga tungkulin nito: pangalagaan ang proseso ng rehistrasyon at akreditasyon; suriin at aksiyunan ang mga aplikasyon; itala ang pasya sa board resolution o minutes ng pulong; maglabas ng sertipiko sa mga kwalipikadong BHW; suriin at aprubahan ang mga benepisyong gagamit ng pondong lokal; magrekomenda ng benepisyo at paglalaan ng pondo; magbigay ng kopya ng BHW registry sa DOH; at magsagawa ng monitoring sa serbisyo.",
                "start_ms": 6000,
                "end_ms": 45560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magkahiwalay ang pasya sa akreditasyon at ang pagsusuri ng benepisyong may lokal na pondo.",
                "start_ms": 45860,
                "end_ms": 52220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaari ring bumuo ang board ng BHW Registration and Accreditation Committee.",
                "start_ms": 52520,
                "end_ms": 58240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Inilalarawan ng facilitator guide ang pagsusuri, panayam, rekomendasyon sa board at pag-aayos ng registry bilang mga tungkuling pantulong ng komite.",
                "start_ms": 58540,
                "end_ms": 69500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang rekomendasyon lamang ng komite ay hindi katumbas ng opisyal na pasya ng board.",
                "start_ms": 69800,
                "end_ms": 75200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May pananagutan ang board; pantulong ang komite at may opisyal na tala ang pasya.",
                "start_ms": 75500,
                "end_ms": 82260
              }
            ]
          }
        }
      }
    },
    "bhw-barangay-partners": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "barangay-partners-application-check": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/barangay-partners-application-check.en.f7fd784e78e6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f7fd784e78e6b633434d84068408ef3eb42ddd6f25b167c28322382802785f1c",
            "sha256": "c6f659e86c383be1447d9aaf8bd92b61c4c883b409da828c74c588c69b9bf1ab",
            "duration_seconds": 41.796,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Explain your choice",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The space and ten chairs for Saturday are still unconfirmed.",
                "start_ms": 1980,
                "end_ms": 6500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "What is Malou’s appropriate next step?",
                "start_ms": 6800,
                "end_ms": 9520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose and explain your answer to the practice question.",
                "start_ms": 9820,
                "end_ms": 13180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Then form one question to confirm the local contact and approval.",
                "start_ms": 13480,
                "end_ms": 18600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "You may say it, write it or practise with a partner.",
                "start_ms": 18900,
                "end_ms": 22980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "What matters is explaining the role, making a clear request and verifying arrangements, rather than whether support is actually granted.",
                "start_ms": 23280,
                "end_ms": 32080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The story is optional and is not required to complete the lesson.",
                "start_ms": 32380,
                "end_ms": 36380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use the role, a clear request and verification to guide action.",
                "start_ms": 36680,
                "end_ms": 41720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/barangay-partners-application-check.fil.24fe0e24810f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "24fe0e24810f1e14ff8ce2dbc81d70315095e086a03bc02bc797af395f559629",
            "sha256": "0a5db3620592afcb0084fbf88bc8c06064610a8594d10b5696104a9f31c0000a",
            "duration_seconds": 45.558,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipaliwanag ang iyong pagpili",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi pa kumpirmado ang lugar at sampung upuan para sa Sabado.",
                "start_ms": 2780,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ano ang angkop na susunod na hakbang ni Malou?",
                "start_ms": 7240,
                "end_ms": 10480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin at ipaliwanag ang sagot sa tanong sa pagsasanay.",
                "start_ms": 10780,
                "end_ms": 14900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pagkatapos, bumuo ng isang tanong upang tiyakin ang lokal na contact at pahintulot.",
                "start_ms": 15200,
                "end_ms": 21360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Maaari itong sabihin, isulat o subukan kasama ang kapareha.",
                "start_ms": 21660,
                "end_ms": 26900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang mahalaga ay ang paliwanag ng papel, malinaw na kahilingan at pagtitiyak, hindi kung talagang naibigay ang suporta.",
                "start_ms": 27200,
                "end_ms": 35280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Opsyonal ang kuwento at hindi kailangan upang matapos ang aralin.",
                "start_ms": 35580,
                "end_ms": 39620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Papel, malinaw na kahilingan at pagtitiyak ang batayan ng pagkilos.",
                "start_ms": 39920,
                "end_ms": 45480
              }
            ]
          }
        },
        "barangay-support-request": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/barangay-support-request.en.8435bb297a55.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8435bb297a55e5bafd8263c235791903a645afa971f48399248bb512df9545a2",
            "sha256": "b364063ea00f90388c9433c3646e4a8cd79ee28868ded786e13d779e5368f75b",
            "duration_seconds": 39.001,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Make a specific request",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou explains: “We have an agreed activity on Saturday morning.",
                "start_ms": 2380,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "We need a space and ten chairs.",
                "start_ms": 7360,
                "end_ms": 10200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Who should we contact, and what steps or approval are needed?”",
                "start_ms": 10500,
                "end_ms": 15300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The purpose, time and requested support are clear.",
                "start_ms": 15600,
                "end_ms": 19560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She separates known facts from what is unconfirmed: there is a request, but no approval or confirmed equipment yet.",
                "start_ms": 19860,
                "end_ms": 28060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "This request does not need a resident’s name or personal health information.",
                "start_ms": 28360,
                "end_ms": 33120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "State the purpose, time, support and a clarification question.",
                "start_ms": 33420,
                "end_ms": 38940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/barangay-support-request.fil.8854eb4d5e6e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8854eb4d5e6ecc271a048233363fd34a14a4d9cbbd4ec0be2fde217c3deacc4a",
            "sha256": "5deefe09ff603ef6c025526e74cee0d619a9cbe2ad23c759a487a99c6fb5adc6",
            "duration_seconds": 44.8,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bumuo ng tiyak na kahilingan",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinapaliwanag ni Malou: “May napagkasunduang aktibidad sa Sabado ng umaga.",
                "start_ms": 2980,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan namin ng lugar at sampung upuan.",
                "start_ms": 8840,
                "end_ms": 12160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sino ang dapat lapitan, at anong hakbang o pahintulot ang kailangan?”",
                "start_ms": 12460,
                "end_ms": 17660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malinaw ang layunin, oras at hinihinging suporta.",
                "start_ms": 17960,
                "end_ms": 22840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hiwalay ang alam sa hindi pa kumpirmado: may kahilingan, ngunit wala pang pahintulot o kumpirmadong kagamitan.",
                "start_ms": 23140,
                "end_ms": 31420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya kailangang magsama ng pangalan o personal na impormasyong pangkalusugan ng residente sa ganitong kahilingan.",
                "start_ms": 31720,
                "end_ms": 38720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sabihin ang layunin, oras, suporta at tanong na maglilinaw.",
                "start_ms": 39020,
                "end_ms": 44740
              }
            ]
          }
        },
        "confirm-and-follow-through": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/confirm-and-follow-through.en.9086ef3cef45.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9086ef3cef451a8f706cd944ad6764b8030ce276973574289a008733e4829e83",
            "sha256": "9a54dbfb72a523b6df0ea70ebedb808975942019b934b36968fa6c3c7c2c08a4",
            "duration_seconds": 38.478,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Confirm and report accurately",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou records the responsible contact, next step and when to ask again.",
                "start_ms": 2940,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If the space is unconfirmed, she tells the group.",
                "start_ms": 8400,
                "end_ms": 11440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She listens to their preferences and discusses another appropriate plan if needed.",
                "start_ms": 11740,
                "end_ms": 16900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She checks actual availability and approval before saying arrangements are ready.",
                "start_ms": 17200,
                "end_ms": 22280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A personal health question goes separately to an authorized professional under local arrangements.",
                "start_ms": 22580,
                "end_ms": 28780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A guess or personal acquaintance is not confirmation.",
                "start_ms": 29080,
                "end_ms": 33720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Report confirmed and unconfirmed arrangements separately.",
                "start_ms": 34020,
                "end_ms": 38420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/confirm-and-follow-through.fil.034aa92ae2d5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "034aa92ae2d55e99d910c0ee69ff91b909691e69198971be6a4a1f1e15b97b5d",
            "sha256": "1de0da717d5eca18853f8f683cd496a84fcecd80a5ce7a77981139cbd3ea4d7d",
            "duration_seconds": 46.838,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tiyakin at magbalita nang tama",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itinatala ni Malou ang responsableng contact, susunod na hakbang at kailan muling magtatanong.",
                "start_ms": 3180,
                "end_ms": 9500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi pa kumpirmado ang lugar, sinasabi niya iyon sa grupo.",
                "start_ms": 9800,
                "end_ms": 14000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nakikinig siya sa kanilang pagpili at nakikipag-usap tungkol sa ibang angkop na plano kung kailangan.",
                "start_ms": 14300,
                "end_ms": 21220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tinitiyak niya ang aktuwal na pagkakaroon ng suporta at pahintulot bago sabihing handa na.",
                "start_ms": 21520,
                "end_ms": 27880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang personal na tanong pangkalusugan ay hiwalay na dinadala sa awtorisadong propesyonal ayon sa lokal na kaayusan.",
                "start_ms": 28180,
                "end_ms": 35900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya itinuturing na kumpirmasyon ang hula o pagiging kakilala.",
                "start_ms": 36200,
                "end_ms": 41280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ibalita ang kumpirmado at hindi pa kumpirmado nang magkahiwalay.",
                "start_ms": 41580,
                "end_ms": 46780
              }
            ]
          }
        },
        "council-health-role": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/council-health-role.en.51dca0870194.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "51dca08701947822556a19fd6cd8331c3bf213f1a2f5f89d34dbd10d28222465",
            "sha256": "2705ce83716ad1f9077ff8bf9b4565bdce5adc6f2074afd1c2a74a49388fed7b",
            "duration_seconds": 38.06,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Coordinate within clear limits",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For a proposed health policy or program support, the health kagawad may be a partner in advocating it in the council.",
                "start_ms": 2940,
                "end_ms": 10300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "That differs from simply asking who manages a space for an activity.",
                "start_ms": 10600,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Malou does not promise that one official can provide funding, payment or equipment alone.",
                "start_ms": 15460,
                "end_ms": 22020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She asks what decisions, approvals and local arrangements are needed.",
                "start_ms": 22320,
                "end_ms": 27600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This lesson does not give legal rules about budget appropriation or honoraria.",
                "start_ms": 27900,
                "end_ms": 33260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Coordination and approval differ; do not promise funding.",
                "start_ms": 33560,
                "end_ms": 38000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/council-health-role.fil.908aed2331c4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "908aed2331c47ce604ac2a585d6feedadf774fa6b66ad50ebfec3c5b132f90c8",
            "sha256": "0db75a1ed7b05f1451bbea7d50d872f9bf1fdf6cc2bd48ac118da724f62eac9f",
            "duration_seconds": 45.662,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pag-ugnayin nang may hangganan",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kung ang usapin ay mungkahing polisiya o suporta sa programang pangkalusugan, ang kagawad sa kalusugan ay maaaring maging katuwang sa pagtataguyod nito sa konseho.",
                "start_ms": 2740,
                "end_ms": 13300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iba ito sa simpleng pagtatanong kung sino ang namamahala sa lugar para sa isang aktibidad.",
                "start_ms": 13600,
                "end_ms": 19880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi nangangako si Malou na isang opisyal lamang ang makapagbibigay ng pondo, bayad o kagamitan.",
                "start_ms": 20180,
                "end_ms": 26300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinatanong niya kung anong pagpapasya, pag-apruba at lokal na kaayusan ang kailangan.",
                "start_ms": 26600,
                "end_ms": 33200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi nagbibigay ang araling ito ng tuntuning legal tungkol sa paglalaan ng pondo o honorarium.",
                "start_ms": 33500,
                "end_ms": 40540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magkaiba ang pag-uugnay at pag-apruba; huwag mangako ng pondo.",
                "start_ms": 40840,
                "end_ms": 45600
              }
            ]
          }
        },
        "section-4": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/section-4.en.3ebe7ea2b83e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3ebe7ea2b83e716c61abf14f2b9da74ac05b8b68c637a679e16225ee5e040d29",
            "sha256": "d8b8fbda71c8ddc3c27dbd9d090a742141bd7851dc5ae81aa336ad70df09ed13",
            "duration_seconds": 33.437,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Start with a clear need",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a fictional meeting, Malou helps prepare an agreed community health activity.",
                "start_ms": 2380,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The group needs a space and ten chairs on Saturday morning.",
                "start_ms": 8160,
                "end_ms": 12080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She first checks the number, time and participants’ preferences.",
                "start_ms": 12380,
                "end_ms": 16820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The space and chairs are not yet confirmed.",
                "start_ms": 17120,
                "end_ms": 19920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A clear need guides the choice of partner.",
                "start_ms": 20220,
                "end_ms": 23220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Knowing an official does not automatically give Malou equipment or permission.",
                "start_ms": 23520,
                "end_ms": 29800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clarify the need before requesting support.",
                "start_ms": 30100,
                "end_ms": 33380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/section-4.fil.6efeecef2f08.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6efeecef2f088d540b9adc224267346c445438125b49f05b79f32cea257e846f",
            "sha256": "ccb94419a195c13519f28eb23fccd81de48df4f507cb64a4205074b9d34f5a37",
            "duration_seconds": 39.367,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Unahin ang malinaw na pangangailangan",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na pulong, tumutulong si Malou sa paghahanda ng napagkasunduang aktibidad pangkalusugan.",
                "start_ms": 3220,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan ng grupo ng lugar at sampung upuan sa Sabado ng umaga.",
                "start_ms": 11120,
                "end_ms": 15680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinatanong muna niya kung tama ang bilang, oras at nais ng mga kalahok.",
                "start_ms": 15980,
                "end_ms": 21740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi pa kumpirmado ang lugar o mga upuan.",
                "start_ms": 22040,
                "end_ms": 25800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang malinaw na pangangailangan ang batayan ng pagpili ng katuwang.",
                "start_ms": 26100,
                "end_ms": 30500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi awtomatikong may kagamitan o pahintulot dahil may kakilalang opisyal si Malou.",
                "start_ms": 30800,
                "end_ms": 35960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Linawin ang kailangan bago humingi ng suporta.",
                "start_ms": 36260,
                "end_ms": 39300
              }
            ]
          }
        },
        "section-5": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/section-5.en.e80face1d65d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e80face1d65d1b34e66cd1037eb2038576608d5e4966e1a5fd89831358cce112",
            "sha256": "fbc99399ccd632f89714a1708097a340f9fa3958e501d57a297d8626ca4cf8c2",
            "duration_seconds": 45.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Know the partner’s role",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The DOH manual describes the punong barangay as a partner in health services, local leadership and administrative oversight.",
                "start_ms": 2300,
                "end_ms": 11140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The health kagawad advocates health policies and resolutions in the council.",
                "start_ms": 11440,
                "end_ms": 16480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Some barangays assign additional health-activity responsibilities.",
                "start_ms": 16780,
                "end_ms": 21020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malou can ask the responsible barangay contact about space and equipment.",
                "start_ms": 21320,
                "end_ms": 26360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She confirms who handles the request and which local process applies.",
                "start_ms": 26660,
                "end_ms": 31420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Technical or personal health questions belong with the designated authorized health professional; an official’s position does not replace that role.",
                "start_ms": 31720,
                "end_ms": 40440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match the need to the role; confirm local responsibility.",
                "start_ms": 40740,
                "end_ms": 45060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-barangay-partners/section-5.fil.ed9443e31072.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ed9443e3107209b006d58cbb44cb8c647a21c8060e07264c5f4d3d94f5584f5d",
            "sha256": "80c1950b2016e3baa54c20d400f5be9e496f962cf94d2fea9b55a7fc744b8f88",
            "duration_seconds": 53.734,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kilalanin ang papel ng katuwang",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Inilalarawan ng DOH manual ang punong barangay bilang katuwang sa serbisyong pangkalusugan, lokal na pamumuno at administratibong pangangasiwa.",
                "start_ms": 2940,
                "end_ms": 13100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang kagawad sa kalusugan ay nagtataguyod ng mga polisiya at resolusyong pangkalusugan sa konseho.",
                "start_ms": 13400,
                "end_ms": 20440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa ilang barangay, may itinalagang dagdag na tungkulin sa gawaing pangkalusugan.",
                "start_ms": 20740,
                "end_ms": 26140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring magtanong si Malou sa responsableng barangay contact tungkol sa lugar at kagamitan.",
                "start_ms": 26440,
                "end_ms": 32400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tinitiyak niya kung sino ang may saklaw sa kahilingan at anong lokal na proseso ang kailangan.",
                "start_ms": 32700,
                "end_ms": 38180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang teknikal o personal na tanong pangkalusugan ay sa itinalagang awtorisadong health professional; hindi ito napapalitan ng katungkulan ng opisyal.",
                "start_ms": 38480,
                "end_ms": 48880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itugma ang kailangan sa papel; tiyakin ang lokal na saklaw.",
                "start_ms": 49180,
                "end_ms": 53660
              }
            ]
          }
        }
      }
    },
    "bhw-benefits": {
      "module": "04-ra7883",
      "sections": {
        "benefit-verification": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefit-verification.en.b914c725592c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b914c725592cb3f908a9dfbb32f8468f3d49193464ee822b237717969a2eebf4",
            "sha256": "00856e25238b12ae6d0d3f6f229359fb3523df9542dc47a1f341e25137203fcc",
            "duration_seconds": 74.005,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Demi’s specific verification question",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi explains: “RA 7883 has six categories with different conditions.",
                "start_ms": 3220,
                "end_ms": 9300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Registration where service is rendered is required, and one credential does not establish qualification for every benefit.”",
                "start_ms": 9600,
                "end_ms": 18400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She asks her supervisor or RHU: “For hazard allowance, who is the right contact to verify accreditation and registration, the required exposure evidence, validation by proper authorities, and local review and approval?”",
                "start_ms": 18700,
                "end_ms": 34780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The RHU can help identify the contact; it does not replace the statutory authorities.",
                "start_ms": 35080,
                "end_ms": 41680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "For legal services, the case must connect with BHW duties and PAO is the named provider; for eligibility, CSC is the relevant office.",
                "start_ms": 41980,
                "end_ms": 52580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Demi uses only a blank question sheet.",
                "start_ms": 52880,
                "end_ms": 55920
              },
              {
                "zone": "body",
                "index": 6,
                "text": "It is not an official form, application, approval or proof of her status.",
                "start_ms": 56220,
                "end_ms": 61900
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Use fictional cases in practice; no one needs to share private records or a personal benefit-receipt history.",
                "start_ms": 62200,
                "end_ms": 69120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask a specific question without promising money or an outcome.",
                "start_ms": 69420,
                "end_ms": 73940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefit-verification.fil.27ba61e0b912.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "27ba61e0b912325d85cbc32f40c60a45e7e03c91eef465f65c0a526c8670b6f0",
            "sha256": "75d80f048872d194dcf2ec56a404296ee24eef408f1d6e23fba6661d2b8bad85",
            "duration_seconds": 77.845,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang tiyak na tanong ni Demi",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinaliwanag ni Demi: “May anim na kategorya sa RA 7883, pero magkakaiba ang kondisyon.",
                "start_ms": 2300,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan ang rehistrasyon kung saan naglilingkod, at hindi sapat ang isang credential para sa lahat ng benepisyo.”",
                "start_ms": 10120,
                "end_ms": 17920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tanong niya sa supervisor o RHU: “Para sa hazard allowance, sino ang tamang contact upang matiyak ang akreditasyon at rehistrasyon, ang kailangang ebidensiya ng exposure, ang validation ng tamang awtoridad, at ang lokal na review at pag-apruba?”",
                "start_ms": 18220,
                "end_ms": 35260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring tumulong ang RHU sa pag-alam ng contact; hindi nito pinapalitan ang mga awtoridad sa batas.",
                "start_ms": 35560,
                "end_ms": 42600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung legal services ang tanong, kaugnay ng tungkulin ang kaso at PAO ang tinutukoy na provider; kung eligibility, CSC ang kaugnay na tanggapan.",
                "start_ms": 42900,
                "end_ms": 53700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Blankong question sheet lamang ang ginagamit ni Demi.",
                "start_ms": 54000,
                "end_ms": 57520
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi ito opisyal na form, aplikasyon, approval o patunay ng kaniyang katayuan.",
                "start_ms": 57820,
                "end_ms": 63700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Gumamit ng kathang-isip na kaso sa pagsasanay; hindi kailangang magbahagi ng pribadong rekord o kasaysayan ng pagtanggap ng benepisyo.",
                "start_ms": 64000,
                "end_ms": 73200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magtanong nang tiyak at walang pangakong pera o resulta.",
                "start_ms": 73500,
                "end_ms": 77780
              }
            ]
          }
        },
        "benefits-application-check": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefits-application-check.en.247d74cb5442.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "247d74cb544255e0c63fa1af2fc04e47c8915d21fe735a07cf54c0bfc6a50f64",
            "sha256": "27d3169fdde2c0f3f054986d2501298e415b253446240c4bc1ab7ce3e370d5c9",
            "duration_seconds": 42.397,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose an explanation with an appropriate step",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi hears that every BHW receives the same allowance.",
                "start_ms": 3540,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Someone asks about hazard allowance, but status, exposure and local approval are still unverified.",
                "start_ms": 8560,
                "end_ms": 15600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What explanation and first step fit best?",
                "start_ms": 15900,
                "end_ms": 19420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Choose the answer naming the benefit, its specific conditions and appropriate verification.",
                "start_ms": 19720,
                "end_ms": 27000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Then explain why the other two choices are insufficient.",
                "start_ms": 27300,
                "end_ms": 30860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Finishing the online lesson is separate from a facilitator observing this competency.",
                "start_ms": 31160,
                "end_ms": 37320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Explain the condition and choose an appropriate verification step.",
                "start_ms": 37620,
                "end_ms": 42340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefits-application-check.fil.5d42dd79acc1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5d42dd79acc134bbcd02a6cf76e8d21b031be9278bf151f886cd3477f64b0f9c",
            "sha256": "55dfcc76d4b82e2a736553f86b392f9b51ddec8f0cf430652dfdf9823c8d98af",
            "duration_seconds": 44.8,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang paliwanag na may angkop na hakbang",
                "start_ms": 0,
                "end_ms": 3320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Narinig ni Demi na pare-pareho raw ang allowance ng lahat ng BHW.",
                "start_ms": 3620,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May nagtanong tungkol sa hazard allowance, pero hindi pa verified ang katayuan, exposure o lokal na pag-apruba.",
                "start_ms": 8840,
                "end_ms": 17240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano ang pinakamainam na paliwanag at unang hakbang?",
                "start_ms": 17540,
                "end_ms": 21540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Piliin ang sagot na may benepisyo, tiyak na kondisyon at tamang verification.",
                "start_ms": 21840,
                "end_ms": 28000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos, ipaliwanag kung bakit hindi sapat ang dalawang ibang pagpipilian.",
                "start_ms": 28300,
                "end_ms": 33540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hiwalay ang pagtatapos ng online lesson sa pagmamasid ng facilitator sa kakayahang ito.",
                "start_ms": 33840,
                "end_ms": 39800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaliwanag ang kondisyon at piliin ang naaangkop na verification.",
                "start_ms": 40100,
                "end_ms": 44740
              }
            ]
          }
        },
        "benefits-question": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefits-question.en.a64e75cf9fee.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a64e75cf9fee09c9d701efb3ef7cfa1f61b03a450f083150d828ce5ba40b957a",
            "sha256": "8b63d4e0b64ea568e41c2a88521c4f24ca59dd79ce71676cb509ceeac6f5d80c",
            "duration_seconds": 45.897,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Are allowances automatically identical?",
                "start_ms": 0,
                "end_ms": 3360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional story, someone tells Demi: “Every BHW gets the same allowance automatically.”",
                "start_ms": 3660,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She does not know whether this is correct.",
                "start_ms": 11120,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Her accreditation and registration have not been verified either.",
                "start_ms": 14100,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Instead of promising money, she asks which benefit they mean and which conditions need checking.",
                "start_ms": 18360,
                "end_ms": 25040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "RA 7883 provides six categories of benefits.",
                "start_ms": 25340,
                "end_ms": 30260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "They have different purposes, conditions and responsible authorities.",
                "start_ms": 30560,
                "end_ms": 35040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The story video is optional; you can complete Read or Slides without watching it.",
                "start_ms": 35340,
                "end_ms": 40940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Name the benefit and verify its conditions before promising anything.",
                "start_ms": 41240,
                "end_ms": 45840
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/benefits-question.fil.c6d00b3bfd9d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c6d00b3bfd9df06323c3850b31b0220b2a3e6dbfe6ed08e131ebfe7e86bf34a7",
            "sha256": "72227bdbd3465fd3369165e706f8ac7dd9d099cfae0c6395acf77c32c7c29256",
            "duration_seconds": 48.013,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Awtomatiko bang pare-pareho ang allowance?",
                "start_ms": 0,
                "end_ms": 3360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na kuwento, may nagsabi kay Demi: “Pare-pareho at awtomatiko ang allowance ng lahat ng BHW.”",
                "start_ms": 3660,
                "end_ms": 11140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya alam kung tama ito.",
                "start_ms": 11440,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa rin natitiyak ang kaniyang akreditasyon at rehistrasyon.",
                "start_ms": 13980,
                "end_ms": 18100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa halip na mangako ng pera, itinanong niya kung anong benepisyo ang tinutukoy at anong kondisyon ang dapat alamin.",
                "start_ms": 18400,
                "end_ms": 25840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang RA 7883 ay may anim na kategorya ng benepisyo.",
                "start_ms": 26140,
                "end_ms": 31180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Magkakaiba ang layunin, kondisyon at awtoridad na kaugnay ng mga ito.",
                "start_ms": 31480,
                "end_ms": 37000
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Opsyonal ang kuwentong video; maaari mong tapusin ang Read o Slides nang hindi ito pinapanood.",
                "start_ms": 37300,
                "end_ms": 43500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pangalanan ang benepisyo at tiyakin ang kondisyon bago mangako.",
                "start_ms": 43800,
                "end_ms": 47960
              }
            ]
          }
        },
        "compare-allowances": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/compare-allowances.en.07bda07be88f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "07bda07be88fa523d70a40b0753e57ae68a9d464213ec828a8f76e6a29e6b653",
            "sha256": "57a93243a65bfe921017cfa421db80883317fafd87dd4308621e0ea88f93c9a4",
            "duration_seconds": 75.99,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Different conditions for two allowances",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Card A: a fictional volunteer BHW may face risk in the workplace while performing duties.",
                "start_ms": 3260,
                "end_ms": 9700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Under section 6(a), hazard allowance concerns foreseeable but unavoidable danger affecting health or life during duty, validated by the proper authorities.",
                "start_ms": 10000,
                "end_ms": 21800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The local health board and local peace and order council of the LGU determine the amount.",
                "start_ms": 22100,
                "end_ms": 27100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Calling a place “dangerous” does not let us validate the exposure or set payment ourselves.",
                "start_ms": 27400,
                "end_ms": 34280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Card B: a fictional BHW serves within an isolated barangay health station to make services available at any and all times.",
                "start_ms": 34580,
                "end_ms": 44500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Under section 6(b), subsistence allowance is equivalent to meals taken during duty, computed according to prevailing circumstances determined by the LGU.",
                "start_ms": 44800,
                "end_ms": 55280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "A distant home alone is not the statutory condition.",
                "start_ms": 55580,
                "end_ms": 59380
              },
              {
                "zone": "body",
                "index": 7,
                "text": "A and B need different verification questions.",
                "start_ms": 59680,
                "end_ms": 63400
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Their status, validation and approved local amounts are unknown; we promise no receipt of benefits.",
                "start_ms": 63700,
                "end_ms": 69940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check the specific service and conditions; do not assume one fixed amount.",
                "start_ms": 70240,
                "end_ms": 75920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/compare-allowances.fil.6fb8f0acff78.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6fb8f0acff780316eba891d766af36fdd6799521b37cf7df9c4662c7c50da3be",
            "sha256": "0199e16bd55897daf884534bc564ce3fe2f1312d5f2edd1b1ae9a519a69468ca",
            "duration_seconds": 89.078,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Magkaibang kondisyon ng dalawang allowance",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Card A: isang kathang-isip na boluntaryong BHW ang maaaring malantad sa panganib sa lugar ng trabaho habang ginagampanan ang tungkulin.",
                "start_ms": 3540,
                "end_ms": 13260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa seksiyon 6(a), ang hazard allowance ay para sa foreseeable ngunit unavoidable na panganib na makaaapekto sa kalusugan o buhay habang nagtatrabaho, na dapat i-validate ng tamang awtoridad.",
                "start_ms": 13560,
                "end_ms": 27680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Local health board at local peace and order council ng LGU ang magtatakda ng halaga.",
                "start_ms": 27980,
                "end_ms": 34300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi sapat ang label na “mapanganib” upang tayo ang magpatunay o magtakda ng bayad.",
                "start_ms": 34600,
                "end_ms": 41040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Card B: isang kathang-isip na BHW ang naglilingkod sa loob ng isolated barangay health station upang maibigay ang serbisyo anumang oras.",
                "start_ms": 41340,
                "end_ms": 52020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa seksiyon 6(b), ang subsistence allowance ay katumbas ng mga pagkaing kinakain sa panahon ng tungkulin, na kinukuwenta ayon sa umiiral na kalagayang itinatakda ng LGU.",
                "start_ms": 52320,
                "end_ms": 65840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ang “malayo ang bahay” lamang ay hindi ang kondisyon sa batas.",
                "start_ms": 66140,
                "end_ms": 70180
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Magkaibang tanong sa verification ang kailangan ng A at B.",
                "start_ms": 70480,
                "end_ms": 74560
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi natin alam ang kanilang katayuan, validation o aprubadong lokal na halaga; walang pangako ng pagtanggap.",
                "start_ms": 74860,
                "end_ms": 83900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tingnan ang tiyak na serbisyo at kondisyon; huwag magtakda ng iisang halaga.",
                "start_ms": 84200,
                "end_ms": 89000
              }
            ]
          }
        },
        "registration-and-conditions": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/registration-and-conditions.en.7447399efe22.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7447399efe229802fa196aa4c7058a37f84a5b868811201ff1363fc71e582e33",
            "sha256": "db9ba7d7168e873297e16a501476c7b55ceb505634583704c80a0a0f647b7d60",
            "duration_seconds": 77.087,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Registration and further conditions",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Section 4 requires registration with the local health board of the city or municipality where service is rendered to receive the Act’s benefits and incentives.",
                "start_ms": 3340,
                "end_ms": 14500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It also provides appropriate proof of accreditation.",
                "start_ms": 14800,
                "end_ms": 18280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Accreditation and registration are related but distinct.",
                "start_ms": 18580,
                "end_ms": 23020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Section 6 refers to accredited BHWs actively and regularly performing their duties, alongside the conditions of each benefit.",
                "start_ms": 23320,
                "end_ms": 32400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Under section 5, DOH determines the ideal ratio of BHWs to households.",
                "start_ms": 32700,
                "end_ms": 39780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The total number of BHWs nationwide must not exceed one percent of the total population.",
                "start_ms": 40080,
                "end_ms": 46360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "This gives us no basis to invent a barangay quota or decide Demi’s qualification.",
                "start_ms": 46660,
                "end_ms": 53220
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Section 7 requires local health board review and approval for benefits using local funds.",
                "start_ms": 53520,
                "end_ms": 60120
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Not receiving a benefit does not prove that a BHW did something wrong or failed to register.",
                "start_ms": 60420,
                "end_ms": 66980
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Check the applicable conditions and local implementation without blame.",
                "start_ms": 67280,
                "end_ms": 72200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Registration is required; it does not guarantee every benefit.",
                "start_ms": 72500,
                "end_ms": 77020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/registration-and-conditions.fil.9f9fcafea029.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9f9fcafea029ab53771e404db4ba89e8bba8db642c4a2f132b453b19bae91278",
            "sha256": "c59b1784d1d33d977c5c040ce3e112b64b70e7ee6892aef23f723d06fa3c95f6",
            "duration_seconds": 86.962,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Rehistrasyon at mga karagdagang kondisyon",
                "start_ms": 0,
                "end_ms": 3800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa seksiyon 4, kailangang magparehistro sa local health board ng lungsod o munisipyo kung saan naglilingkod upang makinabang sa mga benepisyo at insentibo ng batas.",
                "start_ms": 4100,
                "end_ms": 15380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May angkop na patunay ng akreditasyon.",
                "start_ms": 15680,
                "end_ms": 18760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magkaugnay ngunit hindi mapagpapalit ang akreditasyon at rehistrasyon.",
                "start_ms": 19060,
                "end_ms": 24620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang seksiyon 6 ay tumutukoy sa mga akreditadong BHW na aktibo at regular na gumaganap ng kanilang tungkulin, kasama ang partikular na kondisyon ng bawat benepisyo.",
                "start_ms": 24920,
                "end_ms": 36240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa seksiyon 5, DOH ang magtatakda ng ideal na ratio ng BHW sa bilang ng mga sambahayan.",
                "start_ms": 36540,
                "end_ms": 43700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang kabuuang bilang ng BHW sa buong bansa ay hindi dapat lumampas sa isang porsiyento ng kabuuang populasyon.",
                "start_ms": 44000,
                "end_ms": 51720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi ito batayan upang gumawa tayo ng quota sa isang barangay o hulaan kung kwalipikado si Demi.",
                "start_ms": 52020,
                "end_ms": 58460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sa seksiyon 7, ang benepisyong gagamit ng lokal na pondo ay kailangang repasuhin at aprubahan ng local health board.",
                "start_ms": 58760,
                "end_ms": 67480
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung hindi pa natatanggap ang benepisyo, hindi nito pinatutunayang nagkamali o hindi nagparehistro ang BHW.",
                "start_ms": 67780,
                "end_ms": 75780
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Alamin ang naaangkop na kondisyon at lokal na pagpapatupad nang walang pagsisi.",
                "start_ms": 76080,
                "end_ms": 81440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan ang rehistrasyon; hindi nito ginagarantiya ang bawat benepisyo.",
                "start_ms": 81740,
                "end_ms": 86900
              }
            ]
          }
        },
        "section-3": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-benefits/section-3.en.2a1065f7d96c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2a1065f7d96c18afc5756edb1540eb421c96b12d726b6ceeb6c787cea2ab3449",
            "sha256": "129e18c1e368a528ccc25d20d811f20954f53c40df96ae855d096da4ffb88e2f",
            "duration_seconds": 74.998,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Six benefit categories",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Section 6 of RA 7883 includes hazard allowance and subsistence allowance.",
                "start_ms": 2820,
                "end_ms": 9460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Each has its own conditions; we will compare them on a later screen.",
                "start_ms": 9760,
                "end_ms": 13920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "It also includes training, education and career enrichment programs: opportunities for continuing education, training and other educational support.",
                "start_ms": 14220,
                "end_ms": 24860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The Act also provides tuition scholarship benefits in state colleges for one child of a BHW unable to use those programs.",
                "start_ms": 25160,
                "end_ms": 33800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Civil service eligibility is a separate category with its own CSC qualifications and application; lesson 1.4.3 covers it.",
                "start_ms": 34100,
                "end_ms": 43740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Free legal representation and consultation through the Public Attorney’s Office cover cases arising from or connected with BHW duties, including coercion or interference.",
                "start_ms": 44040,
                "end_ms": 55200
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Preferential access to loans concerns organized BHW groups with community-based income-generating projects supporting health programs.",
                "start_ms": 55500,
                "end_ms": 65580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "It is not a promise of a loan to every individual.",
                "start_ms": 65880,
                "end_ms": 69760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "There are six categories; they are not all monthly payments or personal loans.",
                "start_ms": 70060,
                "end_ms": 74940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-benefits/section-3.fil.ab61c1531cf7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ab61c1531cf71c46c27cd17ec54ee5fa428bb41990e0c046c837013fac8378c4",
            "sha256": "9d2a3d1e09b89be35048781c6b3ac2dc69ac249d9bfa3119967b82303c769c3c",
            "duration_seconds": 86.256,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Anim na kategorya ng benepisyo",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa seksiyon 6 ng RA 7883, kabilang ang hazard allowance at subsistence allowance.",
                "start_ms": 3060,
                "end_ms": 10300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May sariling kondisyon ang bawat isa; ihahambing natin ang mga ito sa susunod na screen.",
                "start_ms": 10600,
                "end_ms": 16640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kasama rin ang training, education at career enrichment programs: mga pagkakataon sa patuloy na pag-aaral, pagsasanay at iba pang suportang pang-edukasyon.",
                "start_ms": 16940,
                "end_ms": 29260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May nakasaad ding scholarship sa tuition sa state colleges para sa isang anak ng BHW na hindi makikinabang sa mga programang iyon.",
                "start_ms": 29560,
                "end_ms": 39160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang civil service eligibility ay hiwalay na kategorya na may sariling kwalipikasyon at aplikasyon sa CSC; tatalakayin ito sa aralin 1.4.3.",
                "start_ms": 39460,
                "end_ms": 50580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang libreng legal representation at consultation ng Public Attorney’s Office ay para sa mga kasong kaugnay ng pagganap ng tungkulin bilang BHW, kabilang ang coercion o interference.",
                "start_ms": 50880,
                "end_ms": 64040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ang preferential access sa loans ay para sa organisadong mga grupo ng BHW na may community-based income-generating projects na sumusuporta sa mga programang pangkalusugan.",
                "start_ms": 64340,
                "end_ms": 76460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi ito pangako ng pautang sa bawat indibidwal.",
                "start_ms": 76760,
                "end_ms": 80240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Anim ang kategorya; hindi lahat ay buwanang bayad o personal na pautang.",
                "start_ms": 80540,
                "end_ms": 86180
              }
            ]
          }
        }
      }
    },
    "bhw-community-organizer": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/check.en.422f76f5c30d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "422f76f5c30dee6b346d64bd02f73bf6fe5d4ccbf18fb142dad44efd757a0032",
            "sha256": "5ab69dc1ef25d9bdbc28565a8daffe5c1bf4964491b4428944658c46e5cc612b",
            "duration_seconds": 20.584,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply your learning",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Residents suggest a different time for the discussion.",
                "start_ms": 2100,
                "end_ms": 5540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "One resident also says the standing water caused children to become ill.",
                "start_ms": 5840,
                "end_ms": 10960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What should Riza do next?",
                "start_ms": 11260,
                "end_ms": 13940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen to responses, report what was seen, and use the local planning process.",
                "start_ms": 14240,
                "end_ms": 20520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/check.fil.9a72464dc635.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9a72464dc63584834268c3e886eb18d421ba45c8a7a30a979a9e993574e65650",
            "sha256": "b6b205ba8f66a9f97a606247f1f043164b2cdf82c7db72da5b6891d211551a92",
            "duration_seconds": 22.596,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin ang natutuhan",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nagmungkahi ng ibang oras ang mga residente para sa usapan.",
                "start_ms": 2580,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinabi rin ng isa na ang naipong tubig ang sanhi ng pagkakasakit ng mga bata.",
                "start_ms": 6680,
                "end_ms": 12000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano ang pinakamainam na susunod na gawin ni Riza?",
                "start_ms": 12300,
                "end_ms": 15380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig sa tugon, iulat ang nakita, at dalhin ang usapin sa tamang lokal na proseso.",
                "start_ms": 15680,
                "end_ms": 22520
              }
            ]
          }
        },
        "liph": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/liph.en.28bfa7b24c22.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "28bfa7b24c2223ffd6d960083da39d3ab6120e426253559df6bf9ea3b392305f",
            "sha256": "8c8266ad537a2872da46638c0366a01671dd12fb546b6d0b8f40d841d3b8aa42",
            "duration_seconds": 28.421,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Contribute to wider planning",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Barangay input can help identify health needs discussed for the city or provincial Local Investment Plan for Health, or LIPH.",
                "start_ms": 2500,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Share a proposal through the existing local process with the health team.",
                "start_ms": 12840,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Bringing a suggestion into planning does not mean it will automatically receive funding.",
                "start_ms": 17060,
                "end_ms": 22420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Barangay input may inform the LIPH; funding is not guaranteed.",
                "start_ms": 22720,
                "end_ms": 28360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/liph.fil.6db17e1a4217.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6db17e1a42172ebe138b7ceb444654e88047772e9c7684dffb3174fd291f3455",
            "sha256": "8a881e19e1a8e6ddb459478008c6d1c0c267b6d4e49cd548702ba98e0591b316",
            "duration_seconds": 35.135,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "May ambag sa mas malawak na plano",
                "start_ms": 0,
                "end_ms": 3200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maaaring makatulong ang ambag ng barangay sa pagtalakay ng mga pangangailangang pangkalusugan para sa Local Investment Plan for Health o LIPH ng lungsod o probinsya.",
                "start_ms": 3500,
                "end_ms": 15540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ibinabahagi ang mungkahi sa pamamagitan ng umiiral na lokal na proseso kasama ang health team.",
                "start_ms": 15840,
                "end_ms": 22520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi awtomatikong napopondohan ang mungkahi dahil naiparating ito sa pagpaplano.",
                "start_ms": 22820,
                "end_ms": 28380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maaaring makatulong ang ambag ng barangay sa LIPH; walang garantiyang pondo.",
                "start_ms": 28680,
                "end_ms": 35080
              }
            ]
          }
        },
        "observation": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/observation.en.5ecf1fa5f8b5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5ecf1fa5f8b5409feb8d0f7dca192ebb5cfd9b0b1901a0a37a2330a07410a249",
            "sha256": "7df518b33d0da82f9759ff5b43086430613bf859bd12f21af383f7606e682cbc",
            "duration_seconds": 28.735,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Report what was seen",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza writes, “There is standing water in three yards.”",
                "start_ms": 2100,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "That is what she saw.",
                "start_ms": 6600,
                "end_ms": 8760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She does not write that the water caused children to become ill; she has not established that.",
                "start_ms": 9060,
                "end_ms": 15060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She shares the specific observation and residents’ concern with health staff so they can discuss an appropriate next step.",
                "start_ms": 15360,
                "end_ms": 22840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Share what was seen and the concern without claiming an unverified cause.",
                "start_ms": 23140,
                "end_ms": 28660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/observation.fil.01eb957b7cb8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "01eb957b7cb812c8492afc1c0d9054db7867f9366d80782178b4c0d7f6162b93",
            "sha256": "035bd1c60cf222c51d81021527eb50f8e2db5a0dd0979419a8259b3a9b364264",
            "duration_seconds": 33.881,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sabihin ang nakita, hindi ang hinala",
                "start_ms": 0,
                "end_ms": 4200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isinulat ni Riza: “May naipong tubig sa tatlong bakuran.”",
                "start_ms": 4500,
                "end_ms": 9180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iyan ang nakita niya.",
                "start_ms": 9480,
                "end_ms": 11320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi niya isinulat na ang tubig ang sanhi ng pagkakasakit ng mga bata; hindi pa niya iyon napatunayan.",
                "start_ms": 11620,
                "end_ms": 18020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ibinahagi niya ang tiyak na obserbasyon at ang alalahanin ng mga residente sa health staff upang mapag-usapan ang angkop na susunod na hakbang.",
                "start_ms": 18320,
                "end_ms": 27320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ibahagi ang nakita at ang alalahanin; huwag magpahayag ng di-napatunayang sanhi.",
                "start_ms": 27620,
                "end_ms": 33820
              }
            ]
          }
        },
        "organizer-scene": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/organizer-scene.en.d90950d12490.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d90950d12490b1051443e434723d6e3c3ec394a828840d0daad4e388d59cbca1",
            "sha256": "c44f8f171606b21a0548c50712241217675c735d1d2dfbb5bf813b9fc3149394",
            "duration_seconds": 28.056,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "From observation to conversation",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Riza notices standing water in three yards.",
                "start_ms": 3300,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks residents what they have noticed and who else should join the discussion.",
                "start_ms": 8000,
                "end_ms": 13240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She also approaches the purok leader and health staff.",
                "start_ms": 13540,
                "end_ms": 16940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "As a Community Organizer, she connects people before they decide on a shared activity.",
                "start_ms": 17240,
                "end_ms": 23000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen and connect people before deciding on an activity.",
                "start_ms": 23300,
                "end_ms": 27980
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/organizer-scene.fil.1f233aba5f4a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1f233aba5f4ae1bc11cc7094487c746fdaa91e250f5c06b943eff99f3b9aa4c6",
            "sha256": "def6cf3e0e3ca75616422f86220d239b12d883bb9253edfd48b97790cfde6664",
            "duration_seconds": 31.896,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mula obserbasyon, tungo sa usapan",
                "start_ms": 0,
                "end_ms": 3320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Napansin ni BHW Riza ang naipong tubig sa tatlong bakuran.",
                "start_ms": 3620,
                "end_ms": 8340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kinausap niya ang mga residente: ano ang napansin nila, at sino pa ang dapat makasama sa usapan?",
                "start_ms": 8640,
                "end_ms": 15600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Lumapit din siya sa purok leader at health staff.",
                "start_ms": 15900,
                "end_ms": 18940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Bilang Community Organizer, pinag-uugnay niya ang mga tao bago magpasya tungkol sa sama-samang gawain.",
                "start_ms": 19240,
                "end_ms": 26280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig at pag-ugnayin muna ang mga tao bago magpasya sa gawain.",
                "start_ms": 26580,
                "end_ms": 31820
              }
            ]
          }
        },
        "participation": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/participation.en.228b095b06b6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "228b095b06b635ba8ee1164f25f43d36f144adfbdcd0c1210024ad2302d548a1",
            "sha256": "fff435a0ca46709c386fb347d4f43e4a5e8f46b1c41376ad8ec79dec5b120c97",
            "duration_seconds": 30.72,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Invite people to participate",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza says, “I noticed standing water in three yards.",
                "start_ms": 2660,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Could we meet with the purok leader and health staff to discuss what we might do?",
                "start_ms": 6960,
                "end_ms": 12520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "When could you join us?”",
                "start_ms": 12820,
                "end_ms": 14460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A resident suggests a different time.",
                "start_ms": 14760,
                "end_ms": 17360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Riza listens before they choose a time together.",
                "start_ms": 17660,
                "end_ms": 21100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Organizing gives residents a chance to shape the activity, rather than only attend it.",
                "start_ms": 21400,
                "end_ms": 27480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Residents have a chance to shape the plan.",
                "start_ms": 27780,
                "end_ms": 30660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/participation.fil.ebd7de64c2a7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ebd7de64c2a70d3662e8f22d9b37bd70f23f02f318d4bd006c6dbaa7378d1d39",
            "sha256": "15528e73a5b4d04dc99e7303bdb4e9de5913a39ede2ff97d284bb0c8f50974d3",
            "duration_seconds": 34.325,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Anyayahang makilahok",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ni Riza: “May napansin po akong naipong tubig sa tatlong bakuran.",
                "start_ms": 2340,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaari ba tayong mag-usap kasama ang purok leader at health staff tungkol sa maaaring gawin?",
                "start_ms": 7440,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kailan kayo makakasama?”",
                "start_ms": 13300,
                "end_ms": 15420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nagmungkahi ng ibang oras ang isang residente.",
                "start_ms": 15720,
                "end_ms": 19080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pinakinggan ito ni Riza bago sila pumili ng oras.",
                "start_ms": 19380,
                "end_ms": 23260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa pag-oorganisa, may pagkakataon ang mga residente na hubugin ang gawain, hindi lamang dumalo rito.",
                "start_ms": 23560,
                "end_ms": 30680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May pagkakataon ang mga residente na baguhin ang plano.",
                "start_ms": 30980,
                "end_ms": 34260
              }
            ]
          }
        },
        "planning-team": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/planning-team.en.848ad7c6bf82.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "848ad7c6bf82255c72747de50fa8b862535fa5b5fb3cb3e46cdebcab0c432e71",
            "sha256": "e59ce068323c0b253f12d96b8b6e3b2042849714844221d963ef63c0ae40254e",
            "duration_seconds": 28.735,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bring observations into planning",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "With residents and health staff, Riza identifies who will bring the observation to the barangay planning team for health.",
                "start_ms": 2860,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "They record the proposed action and who will report back to residents.",
                "start_ms": 10120,
                "end_ms": 14920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This brings what people saw into planning and lets them know what happened next.",
                "start_ms": 15220,
                "end_ms": 20260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Confirm the actual process with your local health team.",
                "start_ms": 20560,
                "end_ms": 24120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identify who will bring the concern forward and report back.",
                "start_ms": 24420,
                "end_ms": 28660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-community-organizer/planning-team.fil.a509e5f0917a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a509e5f0917aae61fc1e72f78bd40452a15895974f4deea31780aaedfe2b07b9",
            "sha256": "0e18ca9b7d845e425357468f8a376636cfbfd6439671ab53fa8a46079e7991ca",
            "duration_seconds": 34.769,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Dalhin ang nakita sa pagpaplano",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kasama ang mga residente at health staff, tinukoy ni Riza kung sino ang magdadala ng obserbasyon sa barangay planning team for health.",
                "start_ms": 2940,
                "end_ms": 10980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itinala nila ang napag-usapang mungkahi at kung sino ang magbabalik ng sagot sa mga residente.",
                "start_ms": 11280,
                "end_ms": 17200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa ganitong paraan, nakararating ang nakita sa pagpaplano at nalalaman ng mga tao ang naging kasunod na hakbang.",
                "start_ms": 17500,
                "end_ms": 24940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kumpirmahin sa health team ang aktuwal na proseso sa inyong barangay.",
                "start_ms": 25240,
                "end_ms": 29960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tukuyin kung sino ang magdadala ng usapin at magbabalik ng sagot.",
                "start_ms": 30260,
                "end_ms": 34700
              }
            ]
          }
        }
      }
    },
    "bhw-eligibility": {
      "module": "04-ra7883",
      "sections": {
        "bhwe-application-check": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-application-check.en.03c8abe269ad.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "03c8abe269ad09fe81dc5505b833fa876fd10dbf0e4aa135755e32c23ebd8d8e",
            "sha256": "6dcf16b91634ec231b5bf2c84a517d1c4ff13dd5cc6095b7274b0088c6a48373",
            "duration_seconds": 40.229,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose a careful explanation",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In fictional example A, the worker has eight years of service but only three years under accreditation.",
                "start_ms": 2820,
                "end_ms": 9500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Which explanation is best?",
                "start_ms": 9800,
                "end_ms": 11880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Connect the count to accredited status, check education and the other service conditions, and form a specific CSC question.",
                "start_ms": 12180,
                "end_ms": 21900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Demi should promise neither BHWE nor a job.",
                "start_ms": 22200,
                "end_ms": 27280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "After choosing, read the reasons for all three answers and explain to a partner what needs verification.",
                "start_ms": 27580,
                "end_ms": 35740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Explain conditions and evidence, then verify with CSC.",
                "start_ms": 36040,
                "end_ms": 40160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-application-check.fil.6a7358ba3748.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6a7358ba3748df6a80805160d6b67d650774347f824dbb27195844fa6352c69f",
            "sha256": "75762cb30c08452efe7d483b3b6ad3cd051134896da62092fff3198e936a309b",
            "duration_seconds": 44.513,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang maingat na paliwanag",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi sa kathang-isip na Card A na walong taon na ang serbisyo at tatlong taon pa lamang ang accreditation.",
                "start_ms": 3060,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Aling paliwanag ang pinakamainam?",
                "start_ms": 11120,
                "end_ms": 14400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iugnay ang bilang sa accredited status, suriin ang edukasyon at iba pang service conditions, at bumuo ng tiyak na tanong sa CSC.",
                "start_ms": 14700,
                "end_ms": 23620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi dapat mangako si Demi ng BHWE o trabaho.",
                "start_ms": 23920,
                "end_ms": 29160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos pumili, basahin ang dahilan para sa lahat ng tatlong sagot at ipaliwanag sa kapareha kung ano ang dapat tiyakin.",
                "start_ms": 29460,
                "end_ms": 38860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaliwanag ang kondisyon at ebidensiya, saka tiyakin sa CSC.",
                "start_ms": 39160,
                "end_ms": 44440
              }
            ]
          }
        },
        "bhwe-question": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-question.en.ccebf4e77f16.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ccebf4e77f166efaf3cfb5076c736dd3f5a1edfa0e893da32bfe8bd4d3ac028f",
            "sha256": "91535175a0afeb33348c14ded73dee1abdc2932607f9b18dbb5690a8436fed59",
            "duration_seconds": 39.262,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Demi's question",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi hears that accreditation or long BHW service automatically brings BHWE and a government job.",
                "start_ms": 2620,
                "end_ms": 12300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks, ‘Are accreditation, civil service eligibility and appointment the same?’",
                "start_ms": 12600,
                "end_ms": 19440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "They are different.",
                "start_ms": 19740,
                "end_ms": 21420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This is a fictional situation; Demi's education and qualifying service are not established.",
                "start_ms": 21720,
                "end_ms": 28360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "First understand the conditions and evidence before making a promise.",
                "start_ms": 28660,
                "end_ms": 33300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Accreditation, BHWE approval and appointment are different.",
                "start_ms": 33600,
                "end_ms": 39200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-question.fil.c1bc7e73a262.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c1bc7e73a262d8602cb13a2180121e781c487481af8f8f8322b7cea318196884",
            "sha256": "362fb276e59091c0d40c74289c4337025b3d44da287a64de088e2a0ead358487",
            "duration_seconds": 39.549,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tanong ni Demi",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May narinig si Demi: kapag accredited o matagal nang BHW, may BHWE at trabaho na raw agad.",
                "start_ms": 1820,
                "end_ms": 11420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong siya, ‘Pareho ba ang akreditasyon, civil service eligibility at appointment?’",
                "start_ms": 11720,
                "end_ms": 18520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magkakaibang bagay ang mga ito.",
                "start_ms": 18820,
                "end_ms": 21340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kathang-isip ang sitwasyon; hindi pa natin alam ang edukasyon o qualifying service ni Demi.",
                "start_ms": 21640,
                "end_ms": 28000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Unawain muna ang mga kondisyon at ebidensiya bago gumawa ng pangako.",
                "start_ms": 28300,
                "end_ms": 33620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magkaiba ang akreditasyon, BHWE approval at appointment.",
                "start_ms": 33920,
                "end_ms": 39480
              }
            ]
          }
        },
        "bhwe-verification": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-verification.en.f0d27a0c7131.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f0d27a0c71310e3b559aa982948e186b573bd3a467ff3e71af798fcd017da30e",
            "sha256": "21c3ab0b13f10322b77483eddc693ccfa9ad98e97bc044c634fafce354400535",
            "duration_seconds": 55.536,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A specific question for CSC",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Using a blank planning sheet, Demi asks, ‘For this fictional record, which accredited-service period and education and service evidence should be verified, including the JO/COS arrangement?’",
                "start_ms": 3580,
                "end_ms": 19340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The RHU and Local Health Board help identify records and contacts; they do not replace CSC approval.",
                "start_ms": 19640,
                "end_ms": 27680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the CSC Regional or Field Office with jurisdiction over the barangay of service.",
                "start_ms": 27980,
                "end_ms": 34140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "BHWE takes effect on approval by the responsible CSC Regional Office.",
                "start_ms": 34440,
                "end_ms": 41080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Confirm current documentary and form guidance there; this practice submits no actual application or private record.",
                "start_ms": 41380,
                "end_ms": 49340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Connect the question to records, conditions and the proper CSC office.",
                "start_ms": 49640,
                "end_ms": 55480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-verification.fil.6672b25a27c6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6672b25a27c6a71903881c8fb6c14ff2a36a6f6ed2cc9db0ef818df0c0117ff5",
            "sha256": "896b97ab205fec27a3c86de9b02ab94f6c80e73fd08133f31460d82c98d8bfa0",
            "duration_seconds": 57.783,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang tiyak na tanong sa CSC",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumawa si Demi ng tanong gamit ang blankong planning sheet: ‘Para sa kathang-isip na record na ito, aling panahon ng accredited service at anong education at service evidence ang dapat tiyakin, kasama ang JO/COS arrangement?’",
                "start_ms": 2940,
                "end_ms": 21860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tumutulong ang RHU at Local Health Board sa records at contact; hindi nila pinapalitan ang CSC approval.",
                "start_ms": 22160,
                "end_ms": 29240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magtanong sa CSC Regional o Field Office na may sakop sa barangay ng serbisyo.",
                "start_ms": 29540,
                "end_ms": 35300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang effectivity ng BHWE ay nakabatay sa approval ng kaukulang CSC Regional Office.",
                "start_ms": 35600,
                "end_ms": 42520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tiyakin doon ang kasalukuyang documentary at form guidance; walang tunay na application o pribadong record na isusumite sa practice na ito.",
                "start_ms": 42820,
                "end_ms": 51820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iugnay ang tanong sa record, kondisyon at tamang CSC office.",
                "start_ms": 52120,
                "end_ms": 57720
              }
            ]
          }
        },
        "evidence-and-scope": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/evidence-and-scope.en.eb3242833134.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eb324283313454bcbc1fc7e378ca422c5ec8299b034fcc68554b8e2c33a53c7a",
            "sha256": "b2450bb259910d576c990deab3f5e79d3db0454751b3dc2e134183fd1f5e9d06",
            "duration_seconds": 74.58,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One label is not enough",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The two college years must lead toward a degree.",
                "start_ms": 3020,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Voluntary BHW service means no salary or compensation except honorarium throughout the five-year service period.",
                "start_ms": 7240,
                "end_ms": 17040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "CSC clarifies no government appointment or salary from government plantilla payroll; meal and transport allowances are excluded from salary/compensation.",
                "start_ms": 17340,
                "end_ms": 29420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A Job Order or Contract of Service worker may still qualify; the label alone proves neither qualification nor disqualification.",
                "start_ms": 29720,
                "end_ms": 40000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Verify the actual arrangement and all conditions with CSC.",
                "start_ms": 40300,
                "end_ms": 44940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "BHWE is appropriate for first-level positions with exceptions: TESDA trade-test positions, positions requiring licenses, stenographer positions, and board-exam or special-law positions.",
                "start_ms": 45240,
                "end_ms": 60720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "It is not a professional license or an appointment guarantee; a position also has other qualification requirements.",
                "start_ms": 61020,
                "end_ms": 69740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check evidence and scope; do not decide from a label alone.",
                "start_ms": 70040,
                "end_ms": 74520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/evidence-and-scope.fil.5f0b5df3be44.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5f0b5df3be44b06b705fe4278f0a381dba61c3cfd1b9b932242daa4acda140c3",
            "sha256": "ba53fc181fa90e2d25aff354f106795119a0b69d8ffb2f8432b4809a6c48da63",
            "duration_seconds": 72.542,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Hindi sapat ang isang label",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dapat tungo sa degree ang dalawang taon sa kolehiyo.",
                "start_ms": 3020,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa buong limang-taong service period, voluntary ang BHW service: walang salary/compensation maliban sa honorarium.",
                "start_ms": 6880,
                "end_ms": 15920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nililinaw ng CSC ang kawalan ng government appointment at salary mula sa government plantilla payroll; hindi kabilang sa salary/compensation ang meal at transport allowances.",
                "start_ms": 16220,
                "end_ms": 28580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring maging kwalipikado pa rin ang nasa Job Order o Contract of Service; hindi sapat ang label para sabihing pasado o disqualified.",
                "start_ms": 28880,
                "end_ms": 37880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tiyakin ang aktuwal na arrangement at lahat ng kondisyon sa CSC.",
                "start_ms": 38180,
                "end_ms": 43020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang BHWE ay para sa naaangkop na first-level positions, may mga exception: TESDA trade-test positions, mga nangangailangan ng license, stenographer positions, at board-exam o special-law positions.",
                "start_ms": 43320,
                "end_ms": 59320
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi ito professional license o garantiya ng appointment; may iba pang qualification requirements ang posisyon.",
                "start_ms": 59620,
                "end_ms": 67300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Suriin ang ebidensiya at saklaw; huwag magpasya batay sa label lamang.",
                "start_ms": 67600,
                "end_ms": 72480
              }
            ]
          }
        },
        "section-4": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/section-4.en.26782f2dfc22.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "26782f2dfc226ac61e47efd9a9356762d2051861fd49cc3daeca60d4073324ea",
            "sha256": "7e949e3510358d3fe451882c3c75074ecd0bdb065ee2603426ea11582b3e4ee0",
            "duration_seconds": 68.65,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "BHWE conditions",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "RA 7883 section six, paragraph d, provides the statutory basis for second-grade eligibility after five years of continuous service.",
                "start_ms": 2980,
                "end_ms": 15100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "CSC implementing conditions are more detailed.",
                "start_ms": 15400,
                "end_ms": 19280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Use these four teaching groups: Local Health Board accreditation; at least two years of college education leading to a degree; at least five years of continuous, active, full-time voluntary service as an accredited BHW; and a satisfactory service record.",
                "start_ms": 19580,
                "end_ms": 41100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Accreditation must precede the qualifying service.",
                "start_ms": 41400,
                "end_ms": 45040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Service before 20 February 1995 is not counted.",
                "start_ms": 45340,
                "end_ms": 50660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Accreditation alone is insufficient: applicable conditions must be met and supported by evidence, and CSC decides the application.",
                "start_ms": 50960,
                "end_ms": 61000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Verify accreditation, education, qualifying service and a satisfactory record.",
                "start_ms": 61300,
                "end_ms": 68580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/section-4.fil.2dcc5bce3636.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2dcc5bce36365dfbeed5e231cae7d2825962983b9221a6f756e0222e27de4023",
            "sha256": "b80ff04f41f97891d7654c40527bc3895df4c054262d8cfc545a421a4aa9a65b",
            "duration_seconds": 72.96,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mga kondisyon ng BHWE",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang seksiyon 6(d) ng RA 7883 ay nagbibigay ng batayan para sa second-grade eligibility matapos ang limang taong tuloy-tuloy na serbisyo.",
                "start_ms": 3580,
                "end_ms": 15420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May mas detalyadong implementing conditions ang CSC.",
                "start_ms": 15720,
                "end_ms": 19840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gamitin ang apat na pangkat na ito: akreditasyon ng Local Health Board; hindi bababa sa dalawang taon sa kolehiyo tungo sa isang degree; hindi bababa sa limang taong tuloy-tuloy, aktibo, full-time at boluntaryong serbisyo bilang accredited BHW; at satisfactory service record.",
                "start_ms": 20140,
                "end_ms": 42460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dapat accredited na bago magsimula ang qualifying service.",
                "start_ms": 42760,
                "end_ms": 47160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi binibilang ang serbisyo bago ang 20 Pebrero 1995.",
                "start_ms": 47460,
                "end_ms": 54060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi sapat ang akreditasyon lamang; kailangang matugunan at mapatunayan ang naaangkop na kondisyon, at CSC ang nagpapasya sa application.",
                "start_ms": 54360,
                "end_ms": 64680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang akreditasyon, edukasyon, qualifying service at satisfactory record.",
                "start_ms": 64980,
                "end_ms": 72900
              }
            ]
          }
        },
        "service-count": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/service-count.en.77dec67ecd61.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "77dec67ecd61edbd8a16cade3933f8a415a624937349d8b99f4c9954b3e063b1",
            "sha256": "6c74d9f51ce93006c4de1d55a14f92aa3780df8b5771340b9928b29c91a98836",
            "duration_seconds": 56.111,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Which service can be counted?",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "All service in these fictional cards is after 20 February 1995.",
                "start_ms": 2420,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Card A has eight years of total service but only three under accredited status; the first five years before accreditation cannot be included.",
                "start_ms": 8680,
                "end_ms": 20160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Card B reports five years of continuous, active, full-time, voluntary and satisfactory service while already accredited, plus school evidence of two college years leading to a degree.",
                "start_ms": 20460,
                "end_ms": 35420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "B supports checking the conditions, but it is not CSC approval.",
                "start_ms": 35720,
                "end_ms": 40280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Unclear dates, an interruption or missing records require a CSC question, not an invented ruling.",
                "start_ms": 40580,
                "end_ms": 49020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Total service and qualifying accredited service are not always the same.",
                "start_ms": 49320,
                "end_ms": 56040
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-eligibility/service-count.fil.df122545f599.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "df122545f59941c30091b56fb953f99bacfdc4f9d8f19b75a1130fc6c8c50532",
            "sha256": "fb1e541b3bb46ca041b7a0c9ff48bb292c6cf747da47d5301afa1297d0fc0457",
            "duration_seconds": 60.212,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Aling serbisyo ang mabibilang?",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lahat ng serbisyo sa mga kathang-isip na card na ito ay matapos ang 20 Pebrero 1995.",
                "start_ms": 2620,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Card A, walong taon ang kabuuang serbisyo ngunit tatlo lamang ang nasa accredited status; hindi maisasama ang unang limang taon bago ang akreditasyon.",
                "start_ms": 12760,
                "end_ms": 24320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Card B, may limang taong tuloy-tuloy, aktibo, full-time, boluntaryo at satisfactory na serbisyo habang accredited na, at school evidence para sa dalawang taon sa kolehiyo tungo sa degree.",
                "start_ms": 24620,
                "end_ms": 39860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May batayan para suriin ang mga kondisyon sa B, ngunit hindi ito CSC approval.",
                "start_ms": 40160,
                "end_ms": 45760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung malabo ang petsa, may interruption o kulang ang record, magtanong sa CSC; huwag hulaan ang ruling.",
                "start_ms": 46060,
                "end_ms": 54180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kabuuang serbisyo at qualifying accredited service ay hindi laging pareho.",
                "start_ms": 54480,
                "end_ms": 60160
              }
            ]
          }
        }
      }
    },
    "bhw-follow-up": {
      "module": "04-ra7883",
      "sections": {
        "follow-up-application-check": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/follow-up-application-check.en.a7cb42d2b0b9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a7cb42d2b0b9b68d6eb005cef9ad433064e2a4d6ea55ea4ef6243ff0a5499beb",
            "sha256": "0dd3134740e87652d60488076eabb793b1118c260812183030d11285934c1bd5",
            "duration_seconds": 42.736,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What response fits Demi’s situation?",
                "start_ms": 0,
                "end_ms": 3200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the fictional case, Demi provided an application but receipt, status and the cause of delay are unconfirmed.",
                "start_ms": 3500,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "What is a constructive follow-up?",
                "start_ms": 12080,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose the response that separates facts from guesses, asks a specific question through a locally confirmed contact, and plans to clarify the answer and next step.",
                "start_ms": 14660,
                "end_ms": 25500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Explain why the other two options are insufficient.",
                "start_ms": 25800,
                "end_ms": 29360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This is an online self-check; observed practice and administrative outcomes are separate.",
                "start_ms": 29660,
                "end_ms": 36020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Facts · specific question · clarification · appropriate next step.",
                "start_ms": 36320,
                "end_ms": 42680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/follow-up-application-check.fil.33bda731e8d7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "33bda731e8d713c986b2ed132d1950f82771f8755c6b5a86d01f0f70f2889f2a",
            "sha256": "4e48d9b6527a13853482a05085dcde25716ef7b59c3179594ccb12427aedff4c",
            "duration_seconds": 46.576,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang angkop na tugon ni Demi?",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na kaso, nagbigay si Demi ng aplikasyon ngunit hindi pa nakukumpirma ang pagtanggap, status o sanhi ng pagkaantala.",
                "start_ms": 2860,
                "end_ms": 13260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ano ang maayos na follow-up?",
                "start_ms": 13560,
                "end_ms": 15800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang tugon na naghihiwalay ng alam sa hula, nagtatanong nang tiyak sa locally confirmed na contact, at nagpaplanong linawin ang sagot at susunod na hakbang.",
                "start_ms": 16100,
                "end_ms": 27980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipaliwanag kung bakit hindi sapat ang dalawang ibang pagpipilian.",
                "start_ms": 28280,
                "end_ms": 33320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Online self-check ito; hiwalay ang aktuwal na observed practice at administratibong resulta.",
                "start_ms": 33620,
                "end_ms": 40620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alam · tiyak na tanong · paglilinaw · angkop na susunod na hakbang.",
                "start_ms": 40920,
                "end_ms": 46520
              }
            ]
          }
        },
        "follow-up-question": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/follow-up-question.en.a5fa9283ab2f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a5fa9283ab2fb95b035a463bb5069db7d432cff1db958b7d88de64ee7f062092",
            "sha256": "99ddf012606c33349d9b99d58c075e6dee581b9d654eb2cdb76a179b92725180",
            "duration_seconds": 48.405,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What does Demi know?",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional continuation, Demi is waiting for news about her accreditation application.",
                "start_ms": 2340,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She knows she provided an application.",
                "start_ms": 8760,
                "end_ms": 11520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She has not confirmed whether it was received and complete, who is handling it, or whether a decision exists.",
                "start_ms": 11820,
                "end_ms": 19660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not know the cause of the delay.",
                "start_ms": 19960,
                "end_ms": 22640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "At the planning corner, a colleague helps her prepare a question.",
                "start_ms": 22940,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Fear, cost or difficulty travelling and communicating may be barriers.",
                "start_ms": 27320,
                "end_ms": 33240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She can seek support and choose an appropriate way to ask.",
                "start_ms": 33540,
                "end_ms": 37580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "The story video is optional; you can complete Read or Slides without watching it.",
                "start_ms": 37880,
                "end_ms": 44320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Separate known facts from what is unconfirmed.",
                "start_ms": 44620,
                "end_ms": 48340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/follow-up-question.fil.81952e31be5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81952e31be5b23ee335a4bf572237ef807e7be7d2a940b7e8f5ed7a4f1af9483",
            "sha256": "7d40c57bc64cf4b1d5b84104bd4de8301292aefdd4e7333821723947ac7953da",
            "duration_seconds": 48.64,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang alam ni Demi?",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na pagpapatuloy, naghihintay si Demi ng balita tungkol sa kaniyang aplikasyon sa akreditasyon.",
                "start_ms": 2180,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Alam niyang nagbigay siya ng aplikasyon.",
                "start_ms": 9360,
                "end_ms": 11680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa niya nakukumpirma kung natanggap at kumpleto ito, sino ang humahawak, o kung may pasya na.",
                "start_ms": 11980,
                "end_ms": 18860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi niya alam ang dahilan ng pagkaantala.",
                "start_ms": 19160,
                "end_ms": 22040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa planning corner, tinutulungan siya ng kasamahan na ihanda ang tanong.",
                "start_ms": 22340,
                "end_ms": 26540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Maaaring may pangamba, gastos o hirap sa pagpunta at pakikipag-usap.",
                "start_ms": 26840,
                "end_ms": 32960
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Puwedeng humingi ng suporta at pumili ng angkop na paraan.",
                "start_ms": 33260,
                "end_ms": 37980
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Opsyonal ang kuwentong video; maaaring tapusin ang Read o Slides nang hindi ito pinapanood.",
                "start_ms": 38280,
                "end_ms": 44680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihiwalay ang alam sa hindi pa nakukumpirma.",
                "start_ms": 44980,
                "end_ms": 48580
              }
            ]
          }
        },
        "known-and-unknown": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/known-and-unknown.en.d1899fb8b926.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d1899fb8b926d74270be97f1dfd838828a94e3e4dc7323d5f7a3b008f1327315",
            "sha256": "788838ce48d5859c7080842c23538126cfefd34d7244a1f85d7181b0a0bfaf79",
            "duration_seconds": 57.287,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Which card asks clearly?",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Card A: “When will this happen?”",
                "start_ms": 2780,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It expresses concern but does not identify the application or information requested.",
                "start_ms": 5960,
                "end_ms": 12320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Help make the purpose specific.",
                "start_ms": 12620,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Card B: “About my fictional accreditation application: has it been received, and how can I verify the status and next step?”",
                "start_ms": 15120,
                "end_ms": 23800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "It names the purpose and asks for unconfirmed information.",
                "start_ms": 24100,
                "end_ms": 28260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Card C: “A document must be lost; I will submit everything again.”",
                "start_ms": 28560,
                "end_ms": 33720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "It guesses the cause and requirement.",
                "start_ms": 34020,
                "end_ms": 36700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Waiting does not prove loss.",
                "start_ms": 37000,
                "end_ms": 39680
              },
              {
                "zone": "body",
                "index": 8,
                "text": "First ask whether an item needs verification, exactly which item and how to provide it safely through the appropriate channel.",
                "start_ms": 39980,
                "end_ms": 48820
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Practice uses no real documents.",
                "start_ms": 49120,
                "end_ms": 52320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Card B asks; it does not turn a guess into a fact.",
                "start_ms": 52620,
                "end_ms": 57220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/known-and-unknown.fil.d09098c4fa21.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d09098c4fa21a343457c59113d579a3455dd47e8a1c14624028f1165a73db310",
            "sha256": "c8e9fd31c7ce0a0cc874f89d6affd2995c8d16853f875406f90105f7beb8bf98",
            "duration_seconds": 62.877,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Aling card ang may malinaw na tanong?",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Card A: “Kailan pa ba ito?”",
                "start_ms": 2900,
                "end_ms": 5780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May pag-aalala, ngunit hindi malinaw kung aling aplikasyon o impormasyon ang hinihingi.",
                "start_ms": 6080,
                "end_ms": 13120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tulungang tukuyin ang pakay.",
                "start_ms": 13420,
                "end_ms": 16020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Card B: “Tungkol po sa kathang-isip na aplikasyon ko sa akreditasyon: natanggap na po ba ito, at paano ko matitiyak ang status at susunod na hakbang?”",
                "start_ms": 16320,
                "end_ms": 27840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tiyak ang pakay at humihingi ng impormasyong hindi pa nakukumpirma.",
                "start_ms": 28140,
                "end_ms": 33980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Card C: “Tiyak na may nawawalang dokumento; ipapasa ko na lang muli lahat.”",
                "start_ms": 34280,
                "end_ms": 40160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hula ang sanhi at requirement.",
                "start_ms": 40460,
                "end_ms": 43060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi patunay ng pagkawala ang paghihintay.",
                "start_ms": 43360,
                "end_ms": 46360
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Itanong muna kung may item na kailangang tiyakin, ano mismo iyon at paano ligtas na magbigay sa tamang channel.",
                "start_ms": 46660,
                "end_ms": 54140
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Walang totoong dokumentong gagamitin sa pagsasanay.",
                "start_ms": 54440,
                "end_ms": 57960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Card B ay nagtatanong; hindi nito ginagawang fact ang hula.",
                "start_ms": 58260,
                "end_ms": 62820
              }
            ]
          }
        },
        "next-contact-plan": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/next-contact-plan.en.bc5fec8475e3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bc5fec8475e3f756721a480d6b0e14e6b86494b18dd1638be9969114ec33d18d",
            "sha256": "46dc4f45f57187f1b9f4d175e60155cfa42b2aa3fc012a205a452ace4e91ad93",
            "duration_seconds": 60.578,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Plan a realistic next contact",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "If there is no date, ask how to agree on an appropriate next contact.",
                "start_ms": 3260,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If an item needs verification, clarify the exact item and proper method before acting.",
                "start_ms": 8920,
                "end_ms": 15640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If responsibility is unclear, ask the local health team to help identify the contact.",
                "start_ms": 15940,
                "end_ms": 22180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "There is no single prescribed interval for everyone.",
                "start_ms": 22480,
                "end_ms": 26240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "In a practice note, write only the fictional purpose, confirmed response, remaining question and agreed next contact or channel.",
                "start_ms": 26540,
                "end_ms": 36260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Use no private details or patient record.",
                "start_ms": 36560,
                "end_ms": 39960
              },
              {
                "zone": "body",
                "index": 6,
                "text": "A support person, written question or another accessible method may help.",
                "start_ms": 40260,
                "end_ms": 45860
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Reflect on whether the question was clear and try again after feedback.",
                "start_ms": 46160,
                "end_ms": 50520
              },
              {
                "zone": "body",
                "index": 8,
                "text": "A confirmed next question is useful even without an outcome.",
                "start_ms": 50820,
                "end_ms": 55220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm the contact and arrangement; do not invent a deadline.",
                "start_ms": 55520,
                "end_ms": 60520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/next-contact-plan.fil.dbb375011118.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dbb375011118920aee1ddf2f04fd9c24993112b34fc6ec8ca8bdee3432a77d90",
            "sha256": "99fc5ce60d53ecc7be9da5fb8533772d134aa5b7a3e743cfcd9eddc51396ba20",
            "duration_seconds": 65.933,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pumili ng makatotohanang susunod na contact",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kung walang petsa, itanong kung paano magkakasundo sa angkop na susunod na contact.",
                "start_ms": 3860,
                "end_ms": 9860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung may item na kailangang tiyakin, linawin ang eksaktong item at tamang paraan bago kumilos.",
                "start_ms": 10160,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung hindi malinaw kung sino ang responsable, humingi ng tulong sa lokal na health team upang matukoy ang contact.",
                "start_ms": 17060,
                "end_ms": 24340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Walang iisang itinakdang pagitan para sa lahat.",
                "start_ms": 24640,
                "end_ms": 27680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa practice note, isulat lamang ang kathang-isip na pakay, nakumpirmang sagot, natitirang tanong at napagkasunduang susunod na contact o channel.",
                "start_ms": 27980,
                "end_ms": 38500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Walang pribadong detalye o patient record.",
                "start_ms": 38800,
                "end_ms": 42240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Maaaring humingi ng katuwang, written question o iba pang accessible na paraan.",
                "start_ms": 42540,
                "end_ms": 48500
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Balikan kung naging malinaw ang tanong at subukang muli matapos ang feedback.",
                "start_ms": 48800,
                "end_ms": 54280
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kapaki-pakinabang ang nakumpirmang susunod na tanong kahit wala pang resulta.",
                "start_ms": 54580,
                "end_ms": 60340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang contact at napagkasunduan; huwag mag-imbento ng deadline.",
                "start_ms": 60640,
                "end_ms": 65880
              }
            ]
          }
        },
        "section-6": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/section-6.en.e383406435bc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e383406435bc38bcfc62c93e26f36a2b399034b0c6cd789291f3f0555cea949b",
            "sha256": "b14382833c709c6595f562320e9458c8589d9b8faef5501993e77bb74ded1da8",
            "duration_seconds": 52.532,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pause and ask a specific question",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "If helpful, pause and breathe before asking.",
                "start_ms": 3260,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Follow-up can be respectful and firm even when you feel worried or frustrated.",
                "start_ms": 7440,
                "end_ms": 13160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "You do not need to hide your feelings to form a clear question.",
                "start_ms": 13460,
                "end_ms": 17260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "With a locally confirmed contact, Demi might say: “Good day.",
                "start_ms": 17560,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "I would like to ask about my accreditation application.",
                "start_ms": 22220,
                "end_ms": 25740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Has it been received, and is anything still unclear when checking completeness?",
                "start_ms": 26040,
                "end_ms": 31600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Who is the appropriate person to ask, and what is the next step?”",
                "start_ms": 31900,
                "end_ms": 36420
              },
              {
                "zone": "body",
                "index": 7,
                "text": "This is a fictional example.",
                "start_ms": 36720,
                "end_ms": 38880
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Confirm the office and channel with the local health team; do not assume every staff member has the same responsibility.",
                "start_ms": 39180,
                "end_ms": 46540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "State your purpose, ask about status and clarify the next step.",
                "start_ms": 46840,
                "end_ms": 52480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/section-6.fil.ce75753b6d9d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ce75753b6d9db14227fb073f38d2a0890b1815c07f2e567f82982c5c9df9fb68",
            "sha256": "1d5dbb229cf0dcbaf73df8b05a90d09d72efdbdf73ddd0bafa388ed873320c08",
            "duration_seconds": 57.94,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Huminto sandali at magtanong nang tiyak",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kung makatutulong, huminto sandali at huminga bago magtanong.",
                "start_ms": 3220,
                "end_ms": 7980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring magalang at matatag ang follow-up kahit nakakaramdam ng pagkabahala o inis.",
                "start_ms": 8280,
                "end_ms": 14400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi kailangang itago ang damdamin upang makabuo ng malinaw na tanong.",
                "start_ms": 14700,
                "end_ms": 19420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa locally confirmed na contact, maaaring sabihin ni Demi: “Magandang araw po.",
                "start_ms": 19720,
                "end_ms": 25840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Nais ko pong magtanong tungkol sa aplikasyon ko sa akreditasyon.",
                "start_ms": 26140,
                "end_ms": 30180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Natanggap na po ba ito, at may kailangan pa bang linawin upang matiyak kung kumpleto?",
                "start_ms": 30480,
                "end_ms": 36320
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Sino po ang tamang kausap, at ano ang susunod na hakbang?”",
                "start_ms": 36620,
                "end_ms": 41060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kathang-isip na halimbawa ito.",
                "start_ms": 41360,
                "end_ms": 43600
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Tiyakin ang tamang opisina at channel sa lokal na health team; huwag ipagpalagay na lahat ng staff ay may parehong tungkulin.",
                "start_ms": 43900,
                "end_ms": 51820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sabihin ang pakay, itanong ang status at linawin ang susunod na hakbang.",
                "start_ms": 52120,
                "end_ms": 57880
              }
            ]
          }
        },
        "section-7": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/section-7.en.0159d16deb3e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0159d16deb3ef87033ed76becb44ce6504b24c48b938b66a7fb273f7cd7132bc",
            "sha256": "d4f9d2434e07b4391c74ada75b59cc3298750793eff6a5574a1e536b88901a3a",
            "duration_seconds": 62.772,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen, repeat and clarify",
                "start_ms": 0,
                "end_ms": 3360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Before: Demi thinks, “Perhaps it is approved because it has been a long time.”",
                "start_ms": 3660,
                "end_ms": 9340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She has not confirmed this.",
                "start_ms": 9640,
                "end_ms": 11760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "After: in the fictional conversation, the appropriate contact says the application is still being reviewed and no date can be given.",
                "start_ms": 12060,
                "end_ms": 20580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This is the example’s response, not a national procedure or timetable.",
                "start_ms": 20880,
                "end_ms": 26000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Demi repeats: “I understand it is still under review and there is no date yet.",
                "start_ms": 26300,
                "end_ms": 31820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Is that right?",
                "start_ms": 32120,
                "end_ms": 33480
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Is there anything I should do now?",
                "start_ms": 33780,
                "end_ms": 35940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Through which channel and with whom can I ask for the next update?”",
                "start_ms": 36240,
                "end_ms": 40560
              },
              {
                "zone": "body",
                "index": 8,
                "text": "She listens to clarification and names any remaining uncertainty.",
                "start_ms": 40860,
                "end_ms": 45460
              },
              {
                "zone": "body",
                "index": 9,
                "text": "The response establishes neither approval nor a missing document.",
                "start_ms": 45760,
                "end_ms": 50560
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Constructive follow-up does not guarantee an answer, accreditation, a benefit or an appointment.",
                "start_ms": 50860,
                "end_ms": 58340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Repeat what you understood and ask about what remains unclear.",
                "start_ms": 58640,
                "end_ms": 62720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-follow-up/section-7.fil.b75a20ed2590.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b75a20ed2590f1d55b998141b5f6391b8567b8b90285889f98382f61e6e02158",
            "sha256": "f6c0b095276b909bf5e6934a2c7ba7fd2c5c6a2618b3395a9b69c190ded2182d",
            "duration_seconds": 65.306,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig, ulitin at linawin",
                "start_ms": 0,
                "end_ms": 3880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bago: iniisip ni Demi na “baka aprubado na dahil matagal na.”",
                "start_ms": 4180,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya pa ito nakukumpirma.",
                "start_ms": 9120,
                "end_ms": 11440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pagkatapos: sa kathang-isip na usapan, sinabi ng tamang contact na sinusuri pa ang aplikasyon at wala pang petsang maibibigay.",
                "start_ms": 11740,
                "end_ms": 20900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ito ang sagot sa halimbawa, hindi pambansang proseso o takdang oras.",
                "start_ms": 21200,
                "end_ms": 26600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ulit ni Demi: “Ang pagkaunawa ko po ay sinusuri pa at wala pang petsa.",
                "start_ms": 26900,
                "end_ms": 33500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tama po ba?",
                "start_ms": 33800,
                "end_ms": 35040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "May kailangan po ba akong gawin ngayon?",
                "start_ms": 35340,
                "end_ms": 37780
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Saang channel at kanino ko maaaring itanong ang susunod na update?”",
                "start_ms": 38080,
                "end_ms": 43280
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Pinakikinggan niya ang paglilinaw at sinasabi kung may hindi pa malinaw.",
                "start_ms": 43580,
                "end_ms": 48420
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Walang natiyak na approval o kulang na dokumento sa sagot.",
                "start_ms": 48720,
                "end_ms": 52960
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Ang maayos na follow-up ay hindi garantiya ng sagot, akreditasyon, benepisyo o appointment.",
                "start_ms": 53260,
                "end_ms": 60220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ulitin ang naunawaan at itanong ang hindi pa malinaw.",
                "start_ms": 60520,
                "end_ms": 65240
              }
            ]
          }
        }
      }
    },
    "bhw-health-educator": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "all-sectors": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/all-sectors.en.84068d116e27.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "84068d116e2754fa452cbf909f25faeb7cdc2aa02ea951495c4f85f3ae0f8b04",
            "sha256": "8b2886aca960ed6c940105406920146875796fee87183a8317e92180937a15a6",
            "duration_seconds": 36.284,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Reach every community group",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Education must reach beyond people who already attend a health talk.",
                "start_ms": 2980,
                "end_ms": 8140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Consider who is missing: children, young people, older adults, and other groups in the barangay.",
                "start_ms": 8440,
                "end_ms": 15960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose a time, place, language, and format that support participation.",
                "start_ms": 16260,
                "end_ms": 22300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Offer information, knowledge, and opportunities to practise.",
                "start_ms": 22600,
                "end_ms": 27480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A BHW should offer information, knowledge, and opportunities to practise to every community group.",
                "start_ms": 27780,
                "end_ms": 36220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/all-sectors.fil.a091db5dd696.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a091db5dd6962a8e7d4651fabd4645d128210813d55c512a1f78e956456d8240",
            "sha256": "91b47a2a30fcf787e5f2ec51d1538fa4f2a2f96e1ef4176c65203d0fa30a504f",
            "duration_seconds": 40.333,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Abutin ang bawat sektor",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi lamang ang mga dumadalo na sa health talk ang kailangang maabot.",
                "start_ms": 2820,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pag-isipan kung sino ang hindi nakakasali: mga bata, kabataan, nakatatanda, at iba pang grupo sa barangay.",
                "start_ms": 7680,
                "end_ms": 16680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pumili ng oras, lugar, wika, at paraan na makatutulong sa kanila na makilahok.",
                "start_ms": 16980,
                "end_ms": 23980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magbigay ng impormasyon, kaalaman, at pagkakataong magsanay.",
                "start_ms": 24280,
                "end_ms": 30240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dapat magbigay ang BHW ng impormasyon, kaalaman, at pagkakataong magsanay sa bawat sektor ng komunidad.",
                "start_ms": 30540,
                "end_ms": 40260
              }
            ]
          }
        },
        "body-environment": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/body-environment.en.6c9a0b2e812b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6c9a0b2e812baee58667bb8364bc2eb3763d4ecbf3ef4322a74eb7d761010a44",
            "sha256": "b044e4ffa77a0a2b8e8b60c83fe59597ef281108f95fbee116eeda5caaa836e5",
            "duration_seconds": 30.616,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Body and environment",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Health education can cover care for the body and cleanliness of the surroundings.",
                "start_ms": 3180,
                "end_ms": 8980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Riza may also explain how residents can reach health services.",
                "start_ms": 9280,
                "end_ms": 14000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She uses materials approved by the health team.",
                "start_ms": 14300,
                "end_ms": 18220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In this lesson, she focuses on choosing a topic and audience; detailed health advice belongs in the relevant training.",
                "start_ms": 18520,
                "end_ms": 26560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "People’s health and their surroundings are connected.",
                "start_ms": 26860,
                "end_ms": 30540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/body-environment.fil.a0bed57ca978.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a0bed57ca9782169aab6dea32a19de48f0b7bb3e4f55d76c6cfed8275d0c4809",
            "sha256": "310ba60750ed629ffd785d3f46b9ee646a374e3ef3f6819d34dba17f613c39d7",
            "duration_seconds": 39.915,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Katawan at kapaligiran",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maaaring talakayin sa edukasyong pangkalusugan ang pangangalaga sa katawan at ang kalinisan ng paligid.",
                "start_ms": 2980,
                "end_ms": 10780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaari ring ipaliwanag ni Riza kung paano makalalapit ang mga residente sa serbisyong pangkalusugan.",
                "start_ms": 11080,
                "end_ms": 19160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gumagamit siya ng materyal na aprubado ng health team.",
                "start_ms": 19460,
                "end_ms": 24140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa araling ito, nakatuon siya sa pagpili ng paksa at kausap; ang detalyadong payong pangkalusugan ay nasa kaukulang pagsasanay.",
                "start_ms": 24440,
                "end_ms": 34360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magkaugnay ang kalusugan ng tao at ng kanyang paligid.",
                "start_ms": 34660,
                "end_ms": 39860
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/check.en.36473f0220ca.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "36473f0220ca3e5162234393f82d6869cbfffe9a35cf2da6c31ed4ea6a7c34bd",
            "sha256": "da82112a055bda1440a87c9f3f8afb0baa77ba67320d095687d75b4fdebd37f0",
            "duration_seconds": 19.879,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply your learning",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza holds a barangay health discussion, but only parents attend.",
                "start_ms": 2100,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "What could she change to help young people take part?",
                "start_ms": 7680,
                "end_ms": 11640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Health education works better when its topic and approach fit the audience and everyone has a chance to take part.",
                "start_ms": 11940,
                "end_ms": 19820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/check.fil.35e8bac9a888.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "35e8bac9a888e10bcd7e60f02a93ad008c52492637d5db0b4fc8f65c64170bca",
            "sha256": "86b52c702114c391e043fb34b16e7f82e4dfebc894935fc7aa276809f43c6325",
            "duration_seconds": 25.887,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin ang natutuhan",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nagsagawa si Riza ng talakayang pangkalusugan sa barangay, pero mga magulang lamang ang dumalo.",
                "start_ms": 2500,
                "end_ms": 10220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ano ang maaari niyang baguhin upang makasali ang mga kabataan?",
                "start_ms": 10520,
                "end_ms": 15920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nagiging mabisa ang pagtuturo kapag ang paksa at paraan ay angkop sa kausap at may pagkakataon siyang makilahok.",
                "start_ms": 16220,
                "end_ms": 25820
              }
            ]
          }
        },
        "educator-scene": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/educator-scene.en.8cc51a7e60d8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8cc51a7e60d874c0ed1b431d709927f6f6b4a7ee103ddf2aae1dcfadfb009b75",
            "sha256": "d03b4100aa93ade11542a7bcf2d7990e999659145d30d06235bc2e149a7677cd",
            "duration_seconds": 23.954,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Start with your audience",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a barangay health discussion, Riza does more than read a poster.",
                "start_ms": 2660,
                "end_ms": 7740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She first learns what residents are asking, then explains clearly.",
                "start_ms": 8040,
                "end_ms": 13040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "As a Health Educator, she helps people learn how to care for their bodies and keep their surroundings healthy.",
                "start_ms": 13340,
                "end_ms": 20460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Teaching is a purposeful conversation.",
                "start_ms": 20760,
                "end_ms": 23880
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/educator-scene.fil.6696e90a6854.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6696e90a685401b7b63ee530fabd3f5a5739bc7ba26d3f5b3d9f85812832bbd1",
            "sha256": "455b5f11654b7dec08382453f45cf0641e0958b73efa077bd844033aed6cc925",
            "duration_seconds": 30.694,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Magsimula sa kausap",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa isang talakayang pangkalusugan sa barangay, hindi lang binabasa ni Riza ang poster.",
                "start_ms": 2660,
                "end_ms": 8340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inaalam niya muna ang mga tanong ng mga residente, saka nagbibigay ng malinaw na paliwanag.",
                "start_ms": 8640,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Bilang Health Educator, tinutulungan niya ang mga tao na matutuhan kung paano pangalagaan ang kanilang katawan at panatilihing malinis ang paligid.",
                "start_ms": 15460,
                "end_ms": 26100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagtuturo ay pag-uusap na may layunin.",
                "start_ms": 26400,
                "end_ms": 30640
              }
            ]
          }
        },
        "life-stages": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/life-stages.en.4eb36ca50f68.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4eb36ca50f6871fb17b2d11270b14691d672d60865a1b6d36709a50d5e60698a",
            "sha256": "48fe9cc4d669b73a39a2e385e0e3b8b405cdb7a2c4bfec5bc163bd2032f52734",
            "duration_seconds": 36.728,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Needs change through life",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A BHW adapts health education to people at different life stages.",
                "start_ms": 2540,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "An infant’s caregiver, a young person, a pregnant resident, and an older adult may have different questions.",
                "start_ms": 8720,
                "end_ms": 16920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Discussions of illness, accidents, and risks should fit the listener’s life stage.",
                "start_ms": 17220,
                "end_ms": 23420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For example, a young person may ask different questions about health risks than an infant’s caregiver.",
                "start_ms": 23720,
                "end_ms": 30520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Adapt discussion of illness, accidents, and risks to each life stage.",
                "start_ms": 30820,
                "end_ms": 36660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-health-educator/life-stages.fil.fc789f21b9c9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fc789f21b9c9aa678db99f0da9b10b714ef824502bdfd408e3ffa456626b67d6",
            "sha256": "1f29c440d559de10b13c941a2bd7680e114b1f4fc54acd52b0dfe27b4020ad3a",
            "duration_seconds": 44.408,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Iba ang pangangailangan sa bawat yugto",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iniaangkop ng BHW ang edukasyong pangkalusugan sa iba’t ibang yugto ng buhay.",
                "start_ms": 3700,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring magkakaiba ang tanong ng tagapag-alaga ng sanggol, kabataan, buntis, at nakatatanda.",
                "start_ms": 11120,
                "end_ms": 19920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Dapat umangkop sa yugto ng buhay ng kausap ang usapan tungkol sa sakit, aksidente, at panganib.",
                "start_ms": 20220,
                "end_ms": 28340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Halimbawa, maaaring magkaiba ang itanong ng kabataan at ng tagapag-alaga ng sanggol tungkol sa panganib sa kalusugan.",
                "start_ms": 28640,
                "end_ms": 37560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iangkop ang usapan tungkol sa sakit, aksidente, at panganib sa yugto ng buhay.",
                "start_ms": 37860,
                "end_ms": 44340
              }
            ]
          }
        }
      }
    },
    "bhw-legal-role": {
      "module": "04-ra7883",
      "sections": {
        "explain-and-verify": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/explain-and-verify.en.07116e94c57f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "07116e94c57fb22312762667b67054d747026bc9ffde272d48e4d0c59d467d3f",
            "sha256": "a36f29d23d8161ef5df14b7bda9efd5dfaf297709265f62275d3f65d131ffa74",
            "duration_seconds": 54.073,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Explain, then ask a specific question",
                "start_ms": 0,
                "end_ms": 3760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi explains: “RA 7883 connects training under an accredited organization, voluntary community primary health care, and local health board accreditation under DOH guidelines.",
                "start_ms": 4060,
                "end_ms": 18020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Experience alone is insufficient.”",
                "start_ms": 18320,
                "end_ms": 21640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Her first question to the RHU or supervisor is: “Who is the appropriate contact to verify my training record and proof of local health board accreditation?”",
                "start_ms": 21940,
                "end_ms": 32500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "They may direct her to the local office handling the process.",
                "start_ms": 32800,
                "end_ms": 36600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This is a question, not a result or a new application.",
                "start_ms": 36900,
                "end_ms": 40820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Use fictional cases in practice; there is no need to share private records or perform a clinical procedure.",
                "start_ms": 41120,
                "end_ms": 48680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Give an explanation and one reasonable first verification step.",
                "start_ms": 48980,
                "end_ms": 54020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/explain-and-verify.fil.32263ce0f4d2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "32263ce0f4d2ffe57fb72f02656d06bb8bfe0f04336791127bdaea8f40eeab84",
            "sha256": "2f8e088151da5bd51dc91608f579385946f7de2b1db5ca443609a74be7092f23",
            "duration_seconds": 59.559,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipaliwanag, saka magtanong nang tiyak",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinaliwanag ni Demi: “Sa RA 7883, magkaugnay ang pagsasanay sa akreditadong organisasyon, boluntaryong primary health care sa komunidad at akreditasyon ng local health board ayon sa gabay ng DOH.",
                "start_ms": 3540,
                "end_ms": 19340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi sapat ang karanasan lang.”",
                "start_ms": 19640,
                "end_ms": 22200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Una niyang tanong sa RHU o supervisor: “Sino po ang tamang contact para matiyak ang rekord ng aking pagsasanay at patunay ng akreditasyon ng local health board?”",
                "start_ms": 22500,
                "end_ms": 33300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring ituro siya sa lokal na tanggapang humahawak ng proseso.",
                "start_ms": 33600,
                "end_ms": 38200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tanong pa lamang ito, hindi resulta o bagong aplikasyon.",
                "start_ms": 38500,
                "end_ms": 43980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa pagsasanay, gumamit ng kathang-isip na kaso; hindi kailangang ibahagi ang pribadong rekord o magsagawa ng clinical procedure.",
                "start_ms": 44280,
                "end_ms": 53720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magbigay ng paliwanag at isang makatwirang unang hakbang sa pag-verify.",
                "start_ms": 54020,
                "end_ms": 59500
              }
            ]
          }
        },
        "legal-basis-check": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/legal-basis-check.en.57efeac9a42a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "57efeac9a42a8701ea0454d97ee940a0fe0ad93adbe15d2af25c58d18bfd7bcf",
            "sha256": "b433bb9d23cac14a991d32266d2fb6ce1d341d6c91ea014c432bf9e438ff7b6f",
            "duration_seconds": 44.748,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What explanation and first step fit?",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Demi’s acquaintance says that helping for a long time is enough to become a recognized BHW and that she should already receive an allowance.",
                "start_ms": 3740,
                "end_ms": 13180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Her training record and accreditation have not been verified.",
                "start_ms": 13480,
                "end_ms": 17680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "How should she explain the legal basis and choose her first step?",
                "start_ms": 17980,
                "end_ms": 22140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Choose the answer that connects the RA 7883 definition, recognizes the local health board’s authority and asks about evidence.",
                "start_ms": 22440,
                "end_ms": 32800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Then explain in your own words why the other two answers are insufficient.",
                "start_ms": 33100,
                "end_ms": 38420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Basis, authority, evidence: explain without guessing.",
                "start_ms": 38720,
                "end_ms": 44680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/legal-basis-check.fil.f687a5ccdf0c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f687a5ccdf0c3d9af836786b3db18c7967487c7b82b772a5ec3c80894eb75721",
            "sha256": "9f4416b566f7a2637657752d9584372bc5b59b45fbecfeee568a0e4668c51e32",
            "duration_seconds": 52.715,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang angkop na paliwanag at unang hakbang?",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ng kakilala ni Demi na sapat na ang matagal na pagtulong upang maging kinikilalang BHW, at dapat may allowance na siya.",
                "start_ms": 3860,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi pa natitiyak ang kaniyang training record o akreditasyon.",
                "start_ms": 14960,
                "end_ms": 19360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Paano niya ipapaliwanag ang legal na batayan at pipiliin ang unang hakbang?",
                "start_ms": 19660,
                "end_ms": 25900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Piliin ang sagot na nag-uugnay sa depinisyon sa RA 7883, kumikilala sa awtoridad ng local health board at nagtatanong tungkol sa ebidensiya.",
                "start_ms": 26200,
                "end_ms": 37880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos, ipaliwanag sa sariling salita kung bakit hindi sapat ang dalawang ibang sagot.",
                "start_ms": 38180,
                "end_ms": 45180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Batayan, awtoridad, ebidensiya: ipaliwanag nang hindi nanghuhula.",
                "start_ms": 45480,
                "end_ms": 52640
              }
            ]
          }
        },
        "roles-and-authority": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/roles-and-authority.en.f428f1493157.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f428f1493157292a78a8cbe4941faab4f6155f91c07efb5c149d0030f3750be8",
            "sha256": "99914b3d07b049b3f56d1991ac8027912aafa88d1365e774383111ed24d29a30",
            "duration_seconds": 49.659,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Who helps, and who accredits?",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "People and offices have different roles.",
                "start_ms": 2940,
                "end_ms": 5580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A training provider can help clarify the training record.",
                "start_ms": 5880,
                "end_ms": 9480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A supervisor or RHU can identify the current local contact and process.",
                "start_ms": 9780,
                "end_ms": 15460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Section 3, however, identifies the local health board as the accreditation authority under DOH guidelines.",
                "start_ms": 15760,
                "end_ms": 23680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Demi does not accredit herself.",
                "start_ms": 23980,
                "end_ms": 26860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A fellow BHW’s agreement or a supervisor’s invitation is insufficient proof of a board decision.",
                "start_ms": 27160,
                "end_ms": 35480
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ask what evidence and official record can be checked with the appropriate local office; do not invent a document or procedure.",
                "start_ms": 35780,
                "end_ms": 44620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Process support and accreditation authority are different roles.",
                "start_ms": 44920,
                "end_ms": 49600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/roles-and-authority.fil.c27036056879.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c27036056879ff9f0f06a9ab49926014a2ea711d32e162ac6040eefbd4d08ad0",
            "sha256": "57adf8686399c9dac98053e8eb6faddc9571a945c9582603db5ff4df0ef239b3",
            "duration_seconds": 57.313,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sino ang tumutulong, at sino ang nag-aakredita?",
                "start_ms": 0,
                "end_ms": 4520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May magkakaibang papel ang mga tao at tanggapan.",
                "start_ms": 4820,
                "end_ms": 7980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring tulungan ng training provider na linawin ang rekord ng pagsasanay.",
                "start_ms": 8280,
                "end_ms": 13640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaaring ituro ng supervisor o RHU ang kasalukuyang lokal na contact at proseso.",
                "start_ms": 13940,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ngunit ang local health board ang tinutukoy ng seksiyon 3 bilang awtoridad sa akreditasyon, alinsunod sa mga gabay ng DOH.",
                "start_ms": 20360,
                "end_ms": 29960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi inaakreditahan ni Demi ang sarili.",
                "start_ms": 30260,
                "end_ms": 33220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi rin sapat ang pagsang-ayon ng kapwa BHW o ang paanyaya ng supervisor bilang patunay ng desisyon ng board.",
                "start_ms": 33520,
                "end_ms": 41920
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Itanong kung anong ebidensiya at opisyal na rekord ang maaaring tingnan sa tamang lokal na tanggapan; huwag mag-imbento ng dokumento o proseso.",
                "start_ms": 42220,
                "end_ms": 51860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iba ang tumutulong sa proseso sa awtoridad na nag-aakredita.",
                "start_ms": 52160,
                "end_ms": 57240
              }
            ]
          }
        },
        "section-1": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/section-1.en.f486f984b89b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f486f984b89bd3a9cf09765af647ce9261e1411b8cb894b7f6a945e6b8c74d01",
            "sha256": "afc2cd1a89b58311a42c735d1928656cf1f98199d0d7ffb20789e0d1809a2d3b",
            "duration_seconds": 44.487,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What establishes Demi’s BHW status?",
                "start_ms": 0,
                "end_ms": 3680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional story, Demi helps with community health activities.",
                "start_ms": 3980,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "An acquaintance says: “You have helped for a long time and were invited, so you must already be a recognized BHW.”",
                "start_ms": 9200,
                "end_ms": 17960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Demi wonders: are experience and an invitation enough?",
                "start_ms": 18260,
                "end_ms": 23380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Instead of guessing, she asks the health team about the legal basis and how to verify her training and accreditation.",
                "start_ms": 23680,
                "end_ms": 30920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Her status has not yet been established.",
                "start_ms": 31220,
                "end_ms": 34220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The story video is optional; you can complete Read or Slides without watching it.",
                "start_ms": 34520,
                "end_ms": 40040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask about the legal basis; do not assume status.",
                "start_ms": 40340,
                "end_ms": 44420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/section-1.fil.7bc2e38e5766.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7bc2e38e57666f5f59f9abd5853241b94cd802e63c249cbc000a33bdb08dc616",
            "sha256": "a6c15a9c2b128aebce4e09feaed0c168dfa24586ac9f6bd89d958118711182dc",
            "duration_seconds": 49.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang batayan ng katayuan ni Demi?",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na kuwento, tumutulong si Demi sa mga gawaing pangkalusugan ng komunidad.",
                "start_ms": 3100,
                "end_ms": 9580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinabi ng isang kakilala: “Matagal ka nang tumutulong at inanyayahan ka naman, kaya tiyak na kinikilalang BHW ka na.”",
                "start_ms": 9880,
                "end_ms": 19040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Napaisip si Demi: sapat na ba ang karanasan at paanyaya?",
                "start_ms": 19340,
                "end_ms": 24340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa halip na manghula, nagtanong siya sa health team kung ano ang legal na batayan at paano matitiyak ang kaniyang pagsasanay at akreditasyon.",
                "start_ms": 24640,
                "end_ms": 34040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi pa natin alam ang kaniyang katayuan.",
                "start_ms": 34340,
                "end_ms": 37180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Opsyonal ang kuwentong video; maaaring tapusin ang Read o Slides nang hindi ito pinapanood.",
                "start_ms": 37480,
                "end_ms": 43800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magtanong tungkol sa legal na batayan; huwag ipagpalagay ang katayuan.",
                "start_ms": 44100,
                "end_ms": 49540
              }
            ]
          }
        },
        "section-2": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/section-2.en.8994e4123c83.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8994e4123c835492ce971ad44e435236388969a593c6a8e7780408b78c6e07f6",
            "sha256": "d4ed81cdc5dced6c5198d358fb637d149bb87f0ba2a635d842c7bcfb71912b99",
            "duration_seconds": 60.238,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The definition in RA 7883",
                "start_ms": 0,
                "end_ms": 3200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Republic Act 7883 is the Barangay Health Workers’ Benefits and Incentives Act of 1995.",
                "start_ms": 3500,
                "end_ms": 10300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Section 3 defines a BHW as a person who has undergone training programs under an accredited government or nongovernment organization.",
                "start_ms": 10600,
                "end_ms": 21360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The person voluntarily provides primary health care services in the community after accreditation to function as a BHW by the local health board, following Department of Health guidelines.",
                "start_ms": 21660,
                "end_ms": 34860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This is a plain-language explanation of the definition, not a direct quotation.",
                "start_ms": 35160,
                "end_ms": 40960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Goodwill or length of service alone does not establish that status.",
                "start_ms": 41260,
                "end_ms": 46740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "This does not say that RA 7883 created every barangay health station.",
                "start_ms": 47040,
                "end_ms": 53480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Training, voluntary service and accreditation belong together in the definition.",
                "start_ms": 53780,
                "end_ms": 60180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/section-2.fil.7150e4dff4eb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7150e4dff4eb024a7a9289bb4542991c0315c434703a72d19ee3f1eb5735bfce",
            "sha256": "6a35f7c8ff2b70f73beafc5bfe4e2b1d589e689e0611eda1b16bb34f13003774",
            "duration_seconds": 63.138,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang depinisyon sa RA 7883",
                "start_ms": 0,
                "end_ms": 4120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang Republic Act 7883 ay ang Barangay Health Workers’ Benefits and Incentives Act of 1995.",
                "start_ms": 4420,
                "end_ms": 12340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa seksiyon 3, ang BHW ay taong dumaan sa mga programang pagsasanay sa ilalim ng akreditadong organisasyong pampamahalaan o di-pampamahalaan.",
                "start_ms": 12640,
                "end_ms": 23920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Boluntaryo siyang nagbibigay ng primary health care services sa komunidad matapos ma-akreditang gumanap bilang BHW ng local health board, ayon sa mga gabay ng Department of Health.",
                "start_ms": 24220,
                "end_ms": 37100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Payak na paliwanag ito ng depinisyon, hindi direktang sipi.",
                "start_ms": 37400,
                "end_ms": 41520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi sapat ang kabutihang-loob o tagal ng pagtulong lamang upang patunayan ang katayuang iyon.",
                "start_ms": 41820,
                "end_ms": 48300
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi rin nito sinasabi na ang RA 7883 ang batas na nagtatag ng bawat barangay health station.",
                "start_ms": 48600,
                "end_ms": 56560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magkaugnay ang pagsasanay, boluntaryong serbisyo at akreditasyon sa depinisyon.",
                "start_ms": 56860,
                "end_ms": 63060
              }
            ]
          }
        },
        "status-and-other-processes": {
          "en": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/status-and-other-processes.en.20a2ddfb5585.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "20a2ddfb5585200fa4c26bef4280c0fbd04d2c63a830312ae8561fc107c967ef",
            "sha256": "de1c05a7e7bff66d2492673cea017976a8f844284ea45ec3a4b2dafa5e32a490",
            "duration_seconds": 63.112,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Status, registration and eligibility",
                "start_ms": 0,
                "end_ms": 3680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Under section 4 of RA 7883, registration with the local health board of the city or municipality where the BHW serves is required for the Act’s benefits and incentives.",
                "start_ms": 3980,
                "end_ms": 18820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It also provides for appropriate proof of accreditation.",
                "start_ms": 19120,
                "end_ms": 22920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Individual benefits have further conditions; an invitation is insufficient grounds to promise an allowance.",
                "start_ms": 23220,
                "end_ms": 30780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Civil Service Commission Barangay Health Worker Eligibility has separate conditions and an application.",
                "start_ms": 31080,
                "end_ms": 38200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "BHW accreditation is not an automatic government appointment or a professional clinical licence.",
                "start_ms": 38500,
                "end_ms": 46380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Later lessons cover benefits, eligibility and the accreditation process.",
                "start_ms": 46680,
                "end_ms": 52080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Here, first understand the distinctions and the proper authority.",
                "start_ms": 52380,
                "end_ms": 56980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not turn accreditation into automatic benefits or an appointment.",
                "start_ms": 57280,
                "end_ms": 63040
              }
            ]
          },
          "fil": {
            "src": "/training/audio/04-ra7883/bhw-legal-role/status-and-other-processes.fil.0f2c3de2c317.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0f2c3de2c31768dd7c899f55a6025c9edd80e4108851d48bbcc1805fd2c86c0d",
            "sha256": "e8b3c883b1b3135cdce1fc13ade6287068799ccde1672108a39d58ac9b6166b8",
            "duration_seconds": 63.582,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Katayuan, rehistrasyon at eligibility",
                "start_ms": 0,
                "end_ms": 4240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa seksiyon 4 ng RA 7883, ang rehistrasyon sa local health board ng lungsod o munisipyo kung saan naglilingkod ang BHW ay kailangan para sa mga benepisyo at insentibo sa batas.",
                "start_ms": 4540,
                "end_ms": 18820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Binabanggit din dito ang angkop na patunay ng akreditasyon.",
                "start_ms": 19120,
                "end_ms": 23120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May mga kondisyon pa ang bawat benepisyo; hindi sapat ang isang paanyaya upang mangako ng allowance.",
                "start_ms": 23420,
                "end_ms": 31100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iba rin ang Barangay Health Worker Eligibility ng Civil Service Commission: may sariling kondisyon at aplikasyon ito.",
                "start_ms": 31400,
                "end_ms": 39200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi awtomatikong appointment o propesyonal na clinical licence ang akreditasyon bilang BHW.",
                "start_ms": 39500,
                "end_ms": 45860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa mga susunod na aralin tatalakayin ang benepisyo, eligibility at proseso ng akreditasyon.",
                "start_ms": 46160,
                "end_ms": 53720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Dito, unawain muna ang pagkakaiba at tamang awtoridad.",
                "start_ms": 54020,
                "end_ms": 58300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag gawing awtomatikong benepisyo o appointment ang akreditasyon.",
                "start_ms": 58600,
                "end_ms": 63520
              }
            ]
          }
        }
      }
    },
    "bhw-local-partners": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "city-role-map": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/city-role-map.en.c887c3bef423.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c887c3bef423099096a70a0d14a81a9870fd54bd52ac2594195cbcc496af8207",
            "sha256": "102a0de7e2364e9b39c7cb156d04c9dc4e5d7a06d0ebe5596ff3a110d2281426",
            "duration_seconds": 48.327,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Health team roles",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At the RHU, the city or municipal health officer, CHO or MHO, leads the local health service and its office staff.",
                "start_ms": 2180,
                "end_ms": 11620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The midwife and public health nurse, PHN, may provide technical support to BHWs according to actual local assignments; Malou confirms who handles the question or referral there.",
                "start_ms": 11920,
                "end_ms": 25440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The city or municipal HEPO supports health promotion, a different role from a BHW’s own HEPO designation.",
                "start_ms": 25740,
                "end_ms": 34140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A decision about one person’s care belongs with an authorized health professional, not a board that discusses budgets.",
                "start_ms": 34440,
                "end_ms": 42680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm actual assignments rather than assuming one hierarchy.",
                "start_ms": 42980,
                "end_ms": 48260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/city-role-map.fil.ea72a67086bb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea72a67086bbb177c0cc9a316500b5966e09e2159c07a5c38c1442cecbaeffee",
            "sha256": "194e5494d1fe2370b8c65033d48ab4982cc5401d82f56254ae5003d0178a5cd4",
            "duration_seconds": 56.085,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mga tungkulin ng health team",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa RHU, ang city o municipal health officer, CHO o MHO, ang namumuno sa lokal na serbisyong pangkalusugan at sa mga tauhan ng tanggapan.",
                "start_ms": 2940,
                "end_ms": 14980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang midwife at public health nurse, PHN, ay maaaring maging teknikal na katuwang ng BHW ayon sa aktuwal na pagtatalaga sa kanilang lugar; kinukumpirma ni Malou kung sino ang responsable sa tanong o referral.",
                "start_ms": 15280,
                "end_ms": 31640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang HEPO sa antas ng lungsod o munisipyo ay katuwang sa health promotion; iba ito sa HEPO na tungkulin ng BHW.",
                "start_ms": 31940,
                "end_ms": 40500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang tanong sa pangangalaga ng isang tao ay dinadala sa awtorisadong health professional, hindi sa board na nagbabalangkas ng badyet.",
                "start_ms": 40800,
                "end_ms": 50120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin ang aktuwal na pagtatalaga; huwag magpalagay ng iisang hierarchy.",
                "start_ms": 50420,
                "end_ms": 56020
              }
            ]
          }
        },
        "close-loop": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/close-loop.en.7ab039e9b03c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7ab039e9b03ccce89ae575a4680e102a16ff577f7d2a27acec559b8dc9ce6953",
            "sha256": "8f566fa90ff8da560e2c9d05e7e62d0cb3cfbdf8059d32bd12ce446f1884f0cb",
            "duration_seconds": 37.642,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Confirm and close the loop",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "After making contact, Malou records whom she reached, the agreed next step, and when to follow up under local rules.",
                "start_ms": 2460,
                "end_ms": 10780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She tells the family the verified next step without guaranteeing an outcome.",
                "start_ms": 11080,
                "end_ms": 16440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If clinical advice is needed, she returns the question to a health professional; for sanitation, she checks the designated sanitary contact.",
                "start_ms": 16740,
                "end_ms": 25900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "With a nonhealth partner, she shares only information the family has agreed to share and that is truly needed.",
                "start_ms": 26200,
                "end_ms": 33880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Return to the family with the verified next step.",
                "start_ms": 34180,
                "end_ms": 37580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/close-loop.fil.847c35dcde7b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "847c35dcde7b3ca07110f3b1a9416d2c6cdd0422fbb45dc9fbd030c586cac0ce",
            "sha256": "027618724795b0b0c438455262343722fab57c84529a8e42753bdf7babf8f734",
            "duration_seconds": 45.714,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kumpirmahin at balikan ang pamilya",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos ng pag-ugnay, tinatandaan ni Malou kung sino ang nakausap, anong hakbang ang napagkasunduan, at kailan dapat bumalik para sa sagot, ayon sa lokal na patakaran.",
                "start_ms": 3260,
                "end_ms": 16180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinababatid niya sa pamilya ang na-verify na susunod na hakbang nang hindi ipinangangako ang resulta.",
                "start_ms": 16480,
                "end_ms": 22920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung kailangan ng klinikal na payo, ibinabalik niya ito sa health professional; kung usapin ng kalinisan, tinatanong niya ang itinalagang sanitary contact.",
                "start_ms": 23220,
                "end_ms": 33180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa kapartner na hindi health worker, ibinabahagi lamang niya ang impormasyong may pahintulot at talagang kailangan.",
                "start_ms": 33480,
                "end_ms": 41440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Balikan ang pamilya sa na-verify na susunod na hakbang.",
                "start_ms": 41740,
                "end_ms": 45660
              }
            ]
          }
        },
        "local-partners-application-check": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/local-partners-application-check.en.81000fa0cab5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81000fa0cab56869a5d0a6b93e259b2ab8e41e73e4be106fa46c3e60276b6f72",
            "sha256": "729360c0fb477513afca57bb1834b293dd4c6ff7dacd253946719c67b56b7db4",
            "duration_seconds": 43.938,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it: choose the first step",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On the next question about medicine support, Malou still does not know the current contact.",
                "start_ms": 2980,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She sees three possible actions: seek consent and verify the local process with the midwife or RHU before sharing only necessary information; send a full record to any official; or promise funding because a local health board exists.",
                "start_ms": 9120,
                "end_ms": 28200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose the action that checks consent and the process.",
                "start_ms": 28500,
                "end_ms": 32340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The other two overshare information or promise a decision beyond a BHW’s role.",
                "start_ms": 32640,
                "end_ms": 39400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose an appropriate first step and explain why.",
                "start_ms": 39700,
                "end_ms": 43860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/local-partners-application-check.fil.577f3b0590a2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "577f3b0590a2e86535dc1cf7a43818b3b58bebe26ff2ad895b2e08b0a2fdf9f4",
            "sha256": "543c43ff156440e0ded91708ec3e44b74ad85097527aa5d5bd521ada547f9eca",
            "duration_seconds": 45.558,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan: piliin ang unang hakbang",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa susunod na tanong tungkol sa tulong sa gamot, hindi pa alam ni Malou ang kasalukuyang contact.",
                "start_ms": 3740,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May tatlong posibleng hakbang: tiyakin ang pahintulot at ang lokal na proseso sa midwife o RHU bago ibahagi ang kailangan lamang na impormasyon; ipadala ang buong tala sa sinumang kawani; o ipangako ang pondo dahil may local health board.",
                "start_ms": 10280,
                "end_ms": 27160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang hakbang na may pahintulot at pagtiyak.",
                "start_ms": 27460,
                "end_ms": 31220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang dalawang iba pa ay lumalampas sa kinakailangang pagbabahagi o nangangako ng desisyong hindi saklaw ng BHW.",
                "start_ms": 31520,
                "end_ms": 40680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang angkop na unang hakbang at ipaliwanag kung bakit.",
                "start_ms": 40980,
                "end_ms": 45500
              }
            ]
          }
        },
        "local-request": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/local-request.en.ebc131d0ffd3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ebc131d0ffd3f29625672edc239b34a11fde60085e2d6ec6f8fce8590336f1ca",
            "sha256": "118f50fdaf8d8b78522b801e931d6b48e2650a69cab2dfd0a06fc7e3af019709",
            "duration_seconds": 43.154,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Example: a locally verified request",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The family asks Malou whether medicine support is available.",
                "start_ms": 3860,
                "end_ms": 8020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She explains that she can check the proper process but cannot promise an amount or approval.",
                "start_ms": 8320,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "With the family’s consent, she asks the RHU midwife who the current contact is and what information is needed.",
                "start_ms": 14940,
                "end_ms": 22620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She learns to ask the designated social welfare contact about possible support.",
                "start_ms": 22920,
                "end_ms": 28520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The family or an authorized person provides requested documents through the proper office; Malou does not send the whole health record.",
                "start_ms": 28820,
                "end_ms": 38180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use a locally verified contact and only necessary information.",
                "start_ms": 38480,
                "end_ms": 43080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/local-request.fil.bb34a9c147ab.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bb34a9c147abb3b910663b992087830a5e6303ece155861a87c5b8e1b74289cc",
            "sha256": "3386cca0c639f2861e92f4304d91440485df7c4e388111ab139b495c56548afc",
            "duration_seconds": 49.946,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawa: tiyaking lokal na hiling",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinanong ng pamilya si Malou kung may tulong sa gamot.",
                "start_ms": 3540,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinaliwanag niyang maaari niyang alamin ang wastong proseso ngunit hindi niya maipapangako ang halaga o pag-apruba.",
                "start_ms": 7280,
                "end_ms": 15520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa pahintulot ng pamilya, tinanong niya ang midwife sa RHU kung sino ang kasalukuyang contact at anong impormasyon ang kailangan.",
                "start_ms": 15820,
                "end_ms": 25100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nalaman niyang dapat munang sa itinalagang social welfare contact itanong ang posibleng suporta.",
                "start_ms": 25400,
                "end_ms": 32360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang pamilya o awtorisadong kausap ang magbibigay ng hinihinging dokumento sa tamang tanggapan; hindi ipinadadala ni Malou ang buong health record.",
                "start_ms": 32660,
                "end_ms": 43220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumamit ng lokal na na-verify na contact at pinakamaliit na kailangang impormasyon.",
                "start_ms": 43520,
                "end_ms": 49880
              }
            ]
          }
        },
        "section-6": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/section-6.en.a465c2c6aa12.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a465c2c6aa121e4c8f7f4a1843cfb6e176fad53f4092a5e5211015c635f3a4ae",
            "sha256": "1927000eb17739d2b3e425e3a1e63edcd1747ade3612c48fd6a8195ec60408b2",
            "duration_seconds": 38.792,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Clarify the need",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou hears a family ask about possible help with medicine.",
                "start_ms": 2060,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Before contacting anyone, she clarifies whether the need is clinical, health promotion, social support, or environmental sanitation.",
                "start_ms": 6720,
                "end_ms": 16480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For an urgent health concern, she follows the local emergency or referral protocol and seeks guidance from the health team.",
                "start_ms": 16780,
                "end_ms": 24700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not turn a funding question into a promise.",
                "start_ms": 25000,
                "end_ms": 28200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She records only what is needed and asks whether the family agrees to an appropriate referral.",
                "start_ms": 28500,
                "end_ms": 34980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identify the need before choosing a contact.",
                "start_ms": 35280,
                "end_ms": 38720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/section-6.fil.a837f60e7947.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a837f60e79479da84435e3c5cf69277d7b6c0bf67ff5b67287d6f2f9464bfd16",
            "sha256": "85e6fe98990481271c651e0e0337f36e4f798ed06818b55f8f56088dbcf61a9a",
            "duration_seconds": 47.256,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Linawin ang pangangailangan",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Malou ay may tanong mula sa isang pamilya tungkol sa posibleng tulong para sa gamot.",
                "start_ms": 2780,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bago tumawag sa kahit sino, nililinaw niya kung klinikal na tanong ba ito, tanong sa health promotion, pangangailangang panlipunan, o suliranin sa kalinisan.",
                "start_ms": 8840,
                "end_ms": 21200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung may agarang kondisyong pangkalusugan, sinusunod niya ang lokal na emergency o referral protocol at humihingi ng gabay sa health team.",
                "start_ms": 21500,
                "end_ms": 30380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang tanong tungkol sa pondo ay hindi niya ginagawang pangako.",
                "start_ms": 30680,
                "end_ms": 34680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itinatala niya lamang ang kinakailangang impormasyon at nagtatanong kung pumapayag ang pamilya sa angkop na referral.",
                "start_ms": 34980,
                "end_ms": 42860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kilalanin ang pangangailangan bago piliin ang kausap.",
                "start_ms": 43160,
                "end_ms": 47200
              }
            ]
          }
        },
        "section-7": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/section-7.en.424c04856008.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "424c048560086746ea3d297d6d156e8503fb5801c1e6937d303f8e23cf72a33f",
            "sha256": "620769172244923e1192e1580b9d099eca2dca38a4cf851d1d1795138ccf83ca",
            "duration_seconds": 49.136,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Other partners and boundaries",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The mayor leads the local government and chairs the city or municipal local health board; the CHO or MHO is vice-chair.",
                "start_ms": 2780,
                "end_ms": 11100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The board proposes health service funding and advises the sanggunian.",
                "start_ms": 11400,
                "end_ms": 16480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "It does not automatically approve a family’s request or make an individual clinical decision.",
                "start_ms": 16780,
                "end_ms": 22780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A BHW president may help coordinate BHWs according to local arrangements.",
                "start_ms": 23080,
                "end_ms": 28800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A social welfare or development officer can help identify suitable social assistance, while a sanitary inspector handles sanitation concerns.",
                "start_ms": 29100,
                "end_ms": 39420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Verify the right person and scope before approaching anyone.",
                "start_ms": 39720,
                "end_ms": 44040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Institutional planning differs from a decision for one person.",
                "start_ms": 44340,
                "end_ms": 49060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-local-partners/section-7.fil.344bf64b4d9f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "344bf64b4d9f0e02da7984f53d356bdf639e64def0a5ce8c3ad47b2b11f027af",
            "sha256": "691e2abcdac70240b13700d0b124360f8ad0865c59c521f28e6263c17b371363",
            "duration_seconds": 58.645,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Iba pang katuwang at hangganan",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang mayor ay namumuno sa lokal na pamahalaan at chair ng city o municipal local health board; ang CHO o MHO ang vice-chair.",
                "start_ms": 2980,
                "end_ms": 13780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang board ay nagmumungkahi ng pondo para sa serbisyong pangkalusugan at nagpapayo sa sanggunian.",
                "start_ms": 14080,
                "end_ms": 21160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi nito kusang inaprubahan ang hiling ng isang pamilya at hindi ito ang gumagawa ng indibidwal na klinikal na pasya.",
                "start_ms": 21460,
                "end_ms": 30220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang BHW president ay makatutulong sa koordinasyon ng mga BHW ayon sa lokal na kaayusan.",
                "start_ms": 30520,
                "end_ms": 37880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Maaaring makatulong ang social welfare o development officer sa pag-alam sa angkop na social assistance, at ang sanitary inspector sa isyu ng kalinisan.",
                "start_ms": 38180,
                "end_ms": 49580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tiyakin ang tamang tao at saklaw ng gawain bago lumapit.",
                "start_ms": 49880,
                "end_ms": 53760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iba ang pagpaplano ng institusyon sa pasya para sa isang tao.",
                "start_ms": 54060,
                "end_ms": 58580
              }
            ]
          }
        }
      }
    },
    "bhw-records": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "assigned-form": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/assigned-form.en.d177ae9d8038.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d177ae9d803870665b7d6d00aa9bf10351ab77c26778352c04c78c19fbb5e21b",
            "sha256": "9fa70a74488c46ceb01455e3d741078199f5808e187a9c7a7e44dd607698630b",
            "duration_seconds": 44.304,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Clarify before handing it over",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "There is also an assigned form with the fictional label “recipient: midwife.”",
                "start_ms": 2460,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A nurse, midwife, or doctor may assign a government, DOH, or local-government form.",
                "start_ms": 7880,
                "end_ms": 14280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Before handing it over, Riza checks what information is requested, whether it matches the verified record, and who should receive it.",
                "start_ms": 14580,
                "end_ms": 23620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not guess missing details.",
                "start_ms": 23920,
                "end_ms": 26800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She follows the approved local method for safeguarding and submitting it; this example is neither a real form nor a universal rule for where every record goes.",
                "start_ms": 27100,
                "end_ms": 37420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Before handoff, confirm the requested details, recipient, and approved route.",
                "start_ms": 37720,
                "end_ms": 44240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/assigned-form.fil.4e3c1045045d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4e3c1045045df71885d0826c96c7541d4ca02a55c2440ee581ed57e3d58a36b8",
            "sha256": "f9cabbbd770190c8ab31b02c61c58854e771352b7b4856677bcdce3def88654d",
            "duration_seconds": 49.476,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Linawin bago ihatid",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May iniatas ding form na may kathang-isip na label na “tatanggap: midwife.”",
                "start_ms": 2500,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring magpagawa ang nurse, midwife, o doktor ng form ng gobyerno, DOH, o lokal na pamahalaan.",
                "start_ms": 8720,
                "end_ms": 16480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Bago ito ihatid, tinitiyak ni Riza kung anong impormasyon ang hinihingi, kung tugma ito sa natiyak na tala, at kung sino ang tatanggap.",
                "start_ms": 16780,
                "end_ms": 26740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi niya pupunan ng hula ang kulang.",
                "start_ms": 27040,
                "end_ms": 30000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Susundin niya ang aprubadong lokal na paraan ng pag-iingat at pagpapasa; ang halimbawa ay hindi tunay na form o pangkalahatang tuntunin kung saan dapat ipadala ang lahat ng tala.",
                "start_ms": 30300,
                "end_ms": 42300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bago ipasa: tiyakin ang hinihinging detalye, tatanggap, at aprubadong paraan.",
                "start_ms": 42600,
                "end_ms": 49400
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/check.en.1a2746d58982.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1a2746d58982bdb274f9b6f613706933839a0c7815a4ce1bfcd002512ea556b9",
            "sha256": "f3b10288205dbd71dc6ae57806d68d4bffdf50739581be84c56def51d886dad9",
            "duration_seconds": 23.536,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply your learning",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The midwife asks Riza for the record of who has received health teaching.",
                "start_ms": 2140,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She has a master list of older residents and a registry of services given, but one registry entry is unclear.",
                "start_ms": 7680,
                "end_ms": 16640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What should she do?",
                "start_ms": 16940,
                "end_ms": 18540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose the record by the question; verify details before handoff.",
                "start_ms": 18840,
                "end_ms": 23480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/check.fil.db604c787be1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "db604c787be1c3dff0d2c7baf5fb5552deff4731c971112cad39924430ed64a6",
            "sha256": "960b90d4884fd3e14e3d7d94daa9bb6ea2fd47161ba238d47e028f8c7759a6a7",
            "duration_seconds": 25.469,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin ang natutuhan",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hiniling ng midwife kay Riza ang tala kung sino ang nabigyan na ng health teaching.",
                "start_ms": 2420,
                "end_ms": 8140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May master list siya ng mga nakatatanda at registry ng mga serbisyong naibigay, ngunit may isang entry sa registry na hindi malinaw.",
                "start_ms": 8440,
                "end_ms": 17280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano ang pinakamainam niyang gawin?",
                "start_ms": 17580,
                "end_ms": 19780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang tala ayon sa tanong; tiyakin ang detalye bago magpasa.",
                "start_ms": 20080,
                "end_ms": 25400
              }
            ]
          }
        },
        "household-profile": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/household-profile.en.6ae0a2277719.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6ae0a2277719aa89d704b8888443096dfda4a4a0a3ec5b5a1f9067362a4a2976",
            "sha256": "af4ec562589ed43d53e94249ba59a92ab54c791f1385179ef72aba119a10ca20",
            "duration_seconds": 35.709,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What describes the household?",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza first looks at the household profile.",
                "start_ms": 2780,
                "end_ms": 5980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In the fictional example, code HH-014 stands for one household with four members.",
                "start_ms": 6280,
                "end_ms": 15840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This helps describe the household.",
                "start_ms": 16140,
                "end_ms": 18620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "It does not answer who has already received a service.",
                "start_ms": 18920,
                "end_ms": 23120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Use the approved local form and instructions for actual fields and safekeeping.",
                "start_ms": 23420,
                "end_ms": 29260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A household profile describes one household; it does not prove a service was given.",
                "start_ms": 29560,
                "end_ms": 35640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/household-profile.fil.ef156ec4c319.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ef156ec4c319fd246e57b44cf448bd1fea251516088bc4670f702294cd0a4b12",
            "sha256": "cdfd083f40c304226239aac7578c7912cb1b63b2bf03ab4260a58b1361daa82b",
            "duration_seconds": 39.184,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang larawan ng kabahayan?",
                "start_ms": 0,
                "end_ms": 3760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Unang tiningnan ni Riza ang household profile.",
                "start_ms": 4060,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa kathang-isip na halimbawa, ang code na HH-014 ay tumutukoy sa isang kabahayang may apat na miyembro.",
                "start_ms": 7560,
                "end_ms": 16520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Makakatulong ito upang makita ang larawan ng kabahayan.",
                "start_ms": 16820,
                "end_ms": 21180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi nito sinasagot kung sino ang nabigyan na ng serbisyo.",
                "start_ms": 21480,
                "end_ms": 25280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang tunay na fields at paraan ng pag-iingat ay ayon sa aprubadong lokal na form at tagubilin.",
                "start_ms": 25580,
                "end_ms": 32100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Household profile: larawan ng isang kabahayan, hindi patunay ng serbisyong naibigay.",
                "start_ms": 32400,
                "end_ms": 39120
              }
            ]
          }
        },
        "master-list": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/master-list.en.6ae1235d9772.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6ae1235d97720b220fd35bd2a99c8945f2033cecc1d73786c5a857cf3e6b1278",
            "sha256": "1b8d6d1c25b1b01a285f777964920665f8dc885a9953670a30d77ec813dc5e6e",
            "duration_seconds": 27.977,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Who belongs to the group?",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Next, Riza looks at a master list for a group, such as older residents in the neighborhood.",
                "start_ms": 2020,
                "end_ms": 7980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The manual describes a master list as grouping people by category.",
                "start_ms": 8280,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "It helps answer who belongs to that group.",
                "start_ms": 14940,
                "end_ms": 18300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Being listed there does not establish that someone received health teaching or another service.",
                "start_ms": 18600,
                "end_ms": 24520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A master list shows who belongs to a group.",
                "start_ms": 24820,
                "end_ms": 27900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/master-list.fil.a5de96020178.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a5de9602017829cb3e4d281a9061ecdad7c85abf01d905d7ef297c6464597f7f",
            "sha256": "5aa521e3186d87120fe4e5eb50f287ef51a92067ae15ebe58229dcfe9993539e",
            "duration_seconds": 32.914,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sino ang kabilang sa grupo?",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sumunod, nakita ni Riza ang master list para sa isang grupo, gaya ng mga nakatatanda sa purok.",
                "start_ms": 2780,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ayon sa manual, pinagsasama ng master list ang mga tao ayon sa grupo.",
                "start_ms": 10120,
                "end_ms": 16320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magagamit ito kung ang tanong ay kung sino ang kabilang sa grupong iyon.",
                "start_ms": 16620,
                "end_ms": 21660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi sapat ang pagkakalista rito upang sabihing nabigyan na sila ng health teaching o ibang serbisyo.",
                "start_ms": 21960,
                "end_ms": 28920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Master list: sino ang kabilang sa isang grupo.",
                "start_ms": 29220,
                "end_ms": 32860
              }
            ]
          }
        },
        "record-purpose": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/record-purpose.en.81cd88667601.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81cd8866760165c23de73bbca4ba837867e53c45417cbfb5e3c97c148529bb0a",
            "sha256": "aa6c7073f6d752dd6232206be265420e6fb7c0a08ecc321397c698753ce33bbf",
            "duration_seconds": 38.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "After the visit",
                "start_ms": 0,
                "end_ms": 1400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "After speaking with Aling Nena, BHW Riza returns to the health station.",
                "start_ms": 1700,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She has a fictional note about the conversation, but she will not put it into just any list.",
                "start_ms": 7280,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She asks the midwife, “What information is needed, and what will it be used for?”",
                "start_ms": 13300,
                "end_ms": 18780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Accurate records help the health team understand community needs and plan programs.",
                "start_ms": 19080,
                "end_ms": 25520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Every example in this lesson is fictional; it contains no real personal data or official form.",
                "start_ms": 25820,
                "end_ms": 33420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A record answers a question for someone who will use it.",
                "start_ms": 33720,
                "end_ms": 38040
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/record-purpose.fil.947943e7d725.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "947943e7d7258179a6710b0fea287161dbe7709e2bcf434549bfce3ab17bda42",
            "sha256": "bd618c4eb9a792c917e059084dfea8de1b09406f38770735e3c1cb49d4f4a991",
            "duration_seconds": 41.9,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pagkatapos ng pagbisita",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagkatapos kausapin si Aling Nena, bumalik si BHW Riza sa health station.",
                "start_ms": 2460,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May kathang-isip siyang tala ng napag-usapan, ngunit hindi niya ito basta ilalagay sa kahit aling listahan.",
                "start_ms": 8720,
                "end_ms": 15760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tinanong niya ang midwife: “Anong impormasyon ang kailangan, at para saan ito gagamitin?”",
                "start_ms": 16060,
                "end_ms": 22500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mahalaga ang wastong tala sa pag-unawa sa pangangailangan ng komunidad at sa pagpaplano ng programa.",
                "start_ms": 22800,
                "end_ms": 29720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang lahat ng halimbawa sa araling ito ay kathang-isip; wala itong tunay na personal na datos o opisyal na form.",
                "start_ms": 30020,
                "end_ms": 36940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang tala ay may tanong na sinasagot at taong gagamit nito.",
                "start_ms": 37240,
                "end_ms": 41840
              }
            ]
          }
        },
        "registry": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/registry.en.204a3d314294.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "204a3d314294ec71a84c0e0557972f3234b320c05274ddc57fa6456f508028c7",
            "sha256": "54929761fb105f86a6e1bd1126f204dc7181da96672c6b8cdd480a11e28f0db5",
            "duration_seconds": 32.575,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Who received a service?",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Who has received health teaching?”",
                "start_ms": 2100,
                "end_ms": 4300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "asks the midwife.",
                "start_ms": 4600,
                "end_ms": 6160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Riza checks the registry: the manual describes it as the record of people who received a service.",
                "start_ms": 6460,
                "end_ms": 13500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She checks the recorded service before answering.",
                "start_ms": 13800,
                "end_ms": 17000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If an entry is unclear, she clarifies it with the health team rather than inferring an answer from the master list or adding a guessed entry.",
                "start_ms": 17300,
                "end_ms": 26620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A registry shows who received a service, based on verified entries.",
                "start_ms": 26920,
                "end_ms": 32520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-records/registry.fil.b9b873a8f770.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b9b873a8f770586144ded66ca90a1380ffc15ccdfd58d6c611fbddbaa98ec5d0",
            "sha256": "67e91a6ce758194bfedd63e8813fec6ac08318881dd442fbef3d531273647255",
            "duration_seconds": 37.59,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sino ang nabigyan ng serbisyo?",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Sino na ang nabigyan ng health teaching?”",
                "start_ms": 3300,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "tanong ng midwife.",
                "start_ms": 6360,
                "end_ms": 8120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang registry ang titingnan ni Riza: ayon sa manual, ito ang tala ng mga taong nabigyan ng serbisyo.",
                "start_ms": 8420,
                "end_ms": 15740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Susuriin niya ang nakatalang serbisyo bago sumagot.",
                "start_ms": 16040,
                "end_ms": 19880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may detalyeng hindi malinaw, lilinawin muna niya ito sa health team; hindi niya hahanguin ang sagot mula sa master list o magdaragdag ng entry batay sa hula.",
                "start_ms": 20180,
                "end_ms": 31780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Registry: sino ang nabigyan ng serbisyo, batay sa natiyak na tala.",
                "start_ms": 32080,
                "end_ms": 37520
              }
            ]
          }
        }
      }
    },
    "bhw-relationships": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "community-listening": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/community-listening.en.53770bf83fd6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "53770bf83fd65cda404e7937a501a6b66cf45f4d2fe7f42e2809fcc6090df293",
            "sha256": "fa593f89129150be66ad4a65d4f600c9ef5f0678ba9a8fdcea04c772b3fd42a5",
            "duration_seconds": 48.405,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen before assuming",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou repeats what she heard: “You want to confirm the venue and speak with a health professional.",
                "start_ms": 3020,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Have I understood correctly?”",
                "start_ms": 9440,
                "end_ms": 11560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nena can correct that summary and explain what matters to her.",
                "start_ms": 11860,
                "end_ms": 15700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malou knows that Nena has two questions.",
                "start_ms": 16000,
                "end_ms": 19480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She still needs to confirm the venue, the locally designated professional contact, and Nena's preferred way to ask.",
                "start_ms": 19780,
                "end_ms": 27300
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Malou does not assume that Nena needs transport or has a particular illness.",
                "start_ms": 27600,
                "end_ms": 33040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She asks, “What information would help you, and how would you prefer to receive it?”",
                "start_ms": 33340,
                "end_ms": 39140
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Use fictional details only during practice.",
                "start_ms": 39440,
                "end_ms": 42920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Repeat, clarify and invite the resident to correct your understanding.",
                "start_ms": 43220,
                "end_ms": 48340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/community-listening.fil.cb01c2554014.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cb01c25540148604f10c724f9d6956d777e5af1431a7cde653d2e3bebc35997d",
            "sha256": "31623ba536262837b5be6a16755924f7ad87c5678d3ee0843f5f4015604cc62e",
            "duration_seconds": 55.876,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig bago magpalagay",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Inulit ni Malou ang narinig: “Gusto ninyong tiyakin ang lugar at makausap ang health professional.",
                "start_ms": 3180,
                "end_ms": 9180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tama po ba ang pagkaunawa ko?”",
                "start_ms": 9480,
                "end_ms": 11840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaaring itama ni Nena ang buod at sabihin kung ano ang mahalaga sa kaniya.",
                "start_ms": 12140,
                "end_ms": 17340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alam: may dalawang tanong si Nena.",
                "start_ms": 17640,
                "end_ms": 20320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi pa alam: ang tiyak na lugar, ang lokal na itinalagang propesyonal na contact at ang paraang nais ni Nena sa pagtatanong.",
                "start_ms": 20620,
                "end_ms": 31020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi ipinapalagay ni Malou na kailangan ni Nena ng transportasyon o may partikular siyang sakit.",
                "start_ms": 31320,
                "end_ms": 38360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Nagtanong siya: “Anong impormasyon ang makatutulong, at paano ninyo ito gustong matanggap?”",
                "start_ms": 38660,
                "end_ms": 45140
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kathang-isip na detalye lamang ang gamitin sa pagsasanay.",
                "start_ms": 45440,
                "end_ms": 49320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ulitin, linawin at hayaang itama ng residente ang iyong pagkaunawa.",
                "start_ms": 49620,
                "end_ms": 55820
              }
            ]
          }
        },
        "relationships-application-check": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/relationships-application-check.en.e4c0d280b174.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e4c0d280b1743f49c5224a3762affee7d59b0d2eb6579ec03cdcb27269e644cc",
            "sha256": "2d473649b4f4117c20e57cf31cf910cced08ceae0f13d67b20f504a6061149eb",
            "duration_seconds": 60.212,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Explain and apply the relationships",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Try the application check below.",
                "start_ms": 3140,
                "end_ms": 5620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In Nena's fictional situation, explain what each relationship can contribute and what it cannot decide.",
                "start_ms": 5920,
                "end_ms": 13760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Give a reason for the contact you choose and one question you would use to verify that person's role.",
                "start_ms": 14060,
                "end_ms": 21140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For equivalent written or paired practice, make four cards: resident's concern and choice; professional question; administrative support request; peer task.",
                "start_ms": 21440,
                "end_ms": 33920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Match each to an appropriate locally confirmed role, then explain the limits.",
                "start_ms": 34220,
                "end_ms": 40260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Your partner can ask, “What do you still need to clarify?”",
                "start_ms": 40560,
                "end_ms": 44280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Use invented details, receive feedback and try again.",
                "start_ms": 44580,
                "end_ms": 49100
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Judge the explanation, not the person's accent or personality.",
                "start_ms": 49400,
                "end_ms": 53880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Explain the choice, verify the role and respect the resident’s preferences.",
                "start_ms": 54180,
                "end_ms": 60140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/relationships-application-check.fil.cc2afe32192b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cc2afe32192bb5f7d37e10143778ccf2c3b097d5624912868de2b15a00358246",
            "sha256": "d2e91cd21f82bb4efd688fce559604d1b5185ebba7b951600ffd9b1c3668fa48",
            "duration_seconds": 66.56,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipaliwanag at gamitin ang mga ugnayan",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Subukan ang tanong sa ibaba.",
                "start_ms": 3780,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa kathang-isip na sitwasyon ni Nena, ipaliwanag ang maitutulong ng bawat ugnayan at ang hindi nito maaaring pagpasyahan.",
                "start_ms": 5960,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magbigay ng dahilan sa piniling contact at isang tanong upang tiyakin ang papel niya.",
                "start_ms": 14660,
                "end_ms": 20500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Para sa katumbas na pasulat o magkapares na pagsasanay, gumawa ng apat na card: alalahanin at pagpili ng residente; propesyonal na tanong; hiling na suportang administratibo; gawain ng kapwa BHW.",
                "start_ms": 20800,
                "end_ms": 37320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itugma sa angkop na papel na tiniyak sa lokalidad, saka ipaliwanag ang hangganan.",
                "start_ms": 37620,
                "end_ms": 43340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Maaaring itanong ng kapareha: “Ano pa ang kailangan mong linawin?”",
                "start_ms": 43640,
                "end_ms": 48360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Gumamit ng kathang-isip na detalye, tumanggap ng puna at umulit.",
                "start_ms": 48660,
                "end_ms": 54940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Paliwanag ang suriin, hindi punto ng pagsasalita o personalidad.",
                "start_ms": 55240,
                "end_ms": 60360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaliwanag ang pagpili, tiyakin ang papel at igalang ang nais ng residente.",
                "start_ms": 60660,
                "end_ms": 66500
              }
            ]
          }
        },
        "section-1": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-1.en.422ed4b48951.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "422ed4b48951648a2fdf81ec149d90bb1728d39e1a4eb2817a42fab67600615b",
            "sha256": "4656a5c8fd162da5875b63d8da0f722a14ccb70431c51cc9e63f06acbe640075",
            "duration_seconds": 50.756,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Malou listens in the courtyard",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional learning situation, BHW Malou meets Aling Nena in a shaded barangay courtyard.",
                "start_ms": 2820,
                "end_ms": 10380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nena asks about a planned community health activity: “Where will it be held?",
                "start_ms": 10680,
                "end_ms": 16240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "I also want to ask a health professional whether it is suitable for me.”",
                "start_ms": 16540,
                "end_ms": 20940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malou listens and asks which question Nena wants help with first.",
                "start_ms": 21240,
                "end_ms": 26480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The venue question and the personal health question need different kinds of support.",
                "start_ms": 26780,
                "end_ms": 32340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Nena's preferences matter; Malou does not decide what she needs without asking.",
                "start_ms": 32640,
                "end_ms": 38640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Learners can finish this lesson in either reading or slide mode without watching the optional story.",
                "start_ms": 38940,
                "end_ms": 45380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen to the resident and separate the questions before choosing support.",
                "start_ms": 45680,
                "end_ms": 50680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-1.fil.d655fff59fab.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d655fff59fab6cc759c98c8201583d9aea8db250eb35fa5969d88b04117eb26d",
            "sha256": "01ff80eb6071215c0eeaac5d7d680f8c68af844ca661859e1d7ec9ae5bebef45",
            "duration_seconds": 52.036,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Nakikinig si Malou sa bakuran",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na sitwasyong ito, nakatagpo ni BHW Malou si Aling Nena sa malilim na bakuran ng barangay.",
                "start_ms": 2620,
                "end_ms": 10380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong si Nena tungkol sa nakaplanong gawaing pangkalusugan: “Saan po ito gaganapin?",
                "start_ms": 10680,
                "end_ms": 16880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gusto ko ring itanong sa health professional kung angkop ito para sa akin.”",
                "start_ms": 17180,
                "end_ms": 21380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakinig si Malou at nagtanong kung alin ang gustong unahing linawin ni Nena.",
                "start_ms": 21680,
                "end_ms": 26880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Magkaibang suporta ang kailangan sa tanong tungkol sa lugar at sa personal na kalusugan.",
                "start_ms": 27180,
                "end_ms": 33420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Mahalaga ang pagpili ni Nena; hindi hinuhulaan ni Malou ang kaniyang pangangailangan.",
                "start_ms": 33720,
                "end_ms": 39240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Maaaring tapusin ang bahaging Basahin o Slides nang hindi pinapanood ang opsyonal na kuwento.",
                "start_ms": 39540,
                "end_ms": 46060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig sa residente at ihiwalay ang mga tanong bago pumili ng suporta.",
                "start_ms": 46360,
                "end_ms": 51960
              }
            ]
          }
        },
        "section-2": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-2.en.56ee444fbab3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "56ee444fbab33dfd5b5c2f38c3761cc43c7857ba262cea9d5bb0892f40f39b9b",
            "sha256": "10060417c252aa0be30144cf868cf10f025df570aad5253e28f88e1e35ce2a33",
            "duration_seconds": 76.669,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Four relationships, different purposes",
                "start_ms": 0,
                "end_ms": 3320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "This lesson uses four relationships as an authored teaching organizer, not an official four-category chain of command.",
                "start_ms": 3620,
                "end_ms": 11700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Community: residents and families contribute their concerns, information and choices.",
                "start_ms": 12000,
                "end_ms": 18720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Listen and clarify with them rather than treating them as passive recipients.",
                "start_ms": 19020,
                "end_ms": 24380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Designated midwife or Rural Health Unit health professional: seek authorized professional guidance for health questions, following locally confirmed arrangements.",
                "start_ms": 24680,
                "end_ms": 36240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A BHW or peer does not replace professional assessment.",
                "start_ms": 36540,
                "end_ms": 41340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Barangay officials: ask the responsible local contact about administrative support, facilities or activity arrangements.",
                "start_ms": 41640,
                "end_ms": 51400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Support depends on local roles and available resources; it is not guaranteed.",
                "start_ms": 51700,
                "end_ms": 57700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Fellow BHWs: share routine work experience, coordinate agreed tasks and help identify questions to clarify.",
                "start_ms": 58000,
                "end_ms": 66720
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Peer advice does not become clinical authority.",
                "start_ms": 67020,
                "end_ms": 70700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Each relationship has a purpose and a limit; verify the local roles.",
                "start_ms": 71000,
                "end_ms": 76600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-2.fil.1e2a31cc2ce6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1e2a31cc2ce6e24331ada007ca3d380dcb3ad2a1d223389b8d629cda68bc4f30",
            "sha256": "c49fbc25deebe148081cc65396e1adbb1f0300e9d044d8e00e632d83a3a2d6e4",
            "duration_seconds": 86.596,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apat na ugnayan, magkakaibang layunin",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ginagamit sa araling ito ang apat na ugnayan bilang ginawang balangkas sa pagtuturo, hindi opisyal na apat na antas ng pamamahala.",
                "start_ms": 3740,
                "end_ms": 13380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Komunidad: ibinabahagi ng mga residente at pamilya ang kanilang alalahanin, impormasyon at pagpili.",
                "start_ms": 13680,
                "end_ms": 21960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Makinig at maglinaw kasama nila; hindi lamang sila tagatanggap ng tulong.",
                "start_ms": 22260,
                "end_ms": 27740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinalagang midwife o health professional ng Rural Health Unit: humingi ng awtorisadong propesyonal na gabay sa tanong pangkalusugan, ayon sa lokal na kaayusang tiniyak.",
                "start_ms": 28040,
                "end_ms": 40560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi kapalit ng propesyonal na pagtatasa ang BHW o kapwa BHW.",
                "start_ms": 40860,
                "end_ms": 47100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Barangay officials: itanong sa responsableng lokal na contact ang suportang administratibo, pasilidad o kaayusan ng aktibidad.",
                "start_ms": 47400,
                "end_ms": 57160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Nakasalalay ang suporta sa lokal na papel at magagamit na kagamitan; walang garantiya.",
                "start_ms": 57460,
                "end_ms": 64140
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kapwa BHW: magbahagi ng karanasan sa karaniwang gawain, mag-ugnay ng napagkasunduang mga tungkulin at tumulong tukuyin ang dapat linawin.",
                "start_ms": 64440,
                "end_ms": 75720
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi nagiging klinikal na awtoridad ang payo ng kapwa BHW.",
                "start_ms": 76020,
                "end_ms": 81100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May layunin at hangganan ang bawat ugnayan; tiyakin ang lokal na papel.",
                "start_ms": 81400,
                "end_ms": 86520
              }
            ]
          }
        },
        "section-3": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-3.en.8f3a2920f542.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8f3a2920f54239314a5bce8c824b648f065d3f7420d177a7c35d740aeacbc041",
            "sha256": "e985831e79cb6b99a651a15f2445792f04a880490a0343af75f367b435ce66eb",
            "duration_seconds": 56.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose a contact for the concern",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For Nena's personal health question, Malou helps clarify the locally designated midwife or authorized health professional and how to contact them.",
                "start_ms": 2700,
                "end_ms": 12620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She explains: “This question needs professional guidance; I should not answer it through a guess.”",
                "start_ms": 12920,
                "end_ms": 19120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The exact local arrangement must be confirmed.",
                "start_ms": 19420,
                "end_ms": 22660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For the venue, Malou checks the activity's verified information and asks the responsible local coordinator if anything remains unclear.",
                "start_ms": 22960,
                "end_ms": 31920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ask a contact, “Is this within your role?",
                "start_ms": 32220,
                "end_ms": 35580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "If not, who is responsible?”",
                "start_ms": 35880,
                "end_ms": 38520
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Position or familiarity alone does not establish the right role.",
                "start_ms": 38820,
                "end_ms": 44180
              },
              {
                "zone": "body",
                "index": 7,
                "text": "This is an organizational example, not medical triage or a universal referral sequence.",
                "start_ms": 44480,
                "end_ms": 51080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose by the concern and confirmed role, rather than rank alone.",
                "start_ms": 51380,
                "end_ms": 56540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/section-3.fil.3078161687b0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3078161687b044af4c0ea068a1c7ffbfdfe8474b651b0924dcde2d9c2ea9f225",
            "sha256": "80045305b471c0c209230b1838ee7cf5bba20a59d6d21505eec655074392afcc",
            "duration_seconds": 62.616,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang contact ayon sa alalahanin",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Para sa personal na tanong pangkalusugan ni Nena, tumutulong si Malou na linawin ang lokal na itinalagang midwife o awtorisadong health professional at ang paraan ng pakikipag-ugnayan.",
                "start_ms": 3420,
                "end_ms": 15940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinaliwanag niya: “Kailangan dito ng propesyonal na gabay; hindi ako dapat sumagot sa pamamagitan ng hula.”",
                "start_ms": 16240,
                "end_ms": 23680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Dapat tiyakin ang mismong lokal na kaayusan.",
                "start_ms": 23980,
                "end_ms": 26940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Para sa lugar, sinusuri ni Malou ang natiyak na impormasyon ng aktibidad at nagtatanong sa responsableng lokal na coordinator kung may malabo pa.",
                "start_ms": 27240,
                "end_ms": 37120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itanong sa contact: “Saklaw po ba ito ng inyong papel?",
                "start_ms": 37420,
                "end_ms": 41740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung hindi, sino po ang responsable?”",
                "start_ms": 42040,
                "end_ms": 44840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi sapat ang posisyon o pagiging kakilala.",
                "start_ms": 45140,
                "end_ms": 48420
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Halimbawang pang-organisasyon ito, hindi medikal na triage o iisang proseso ng referral para sa lahat.",
                "start_ms": 48720,
                "end_ms": 56360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ayon sa alalahanin at natiyak na papel, hindi sa posisyon lamang.",
                "start_ms": 56660,
                "end_ms": 62540
              }
            ]
          }
        },
        "shared-support": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/shared-support.en.8b6326bb9fa2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8b6326bb9fa2a9b24d9667ad020871edaff4f7f8ab6df8da349a7e1c2ad90c7a",
            "sha256": "076e2c31eb05af626dc6827afc7e40bb6ac358269edbb75a3d5208200c986256",
            "duration_seconds": 58.201,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Coordinate support without replacing roles",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou keeps the questions separate while coordinating support.",
                "start_ms": 3700,
                "end_ms": 7780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "With Nena's agreement, she helps identify a suitable channel for the professional question.",
                "start_ms": 8080,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Separately, the responsible barangay contact may clarify the venue or a request for practical support.",
                "start_ms": 14100,
                "end_ms": 20860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A fellow BHW can help Malou organize an agreed routine task and check what remains unclear.",
                "start_ms": 21160,
                "end_ms": 28520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Nena contributes her preferences throughout.",
                "start_ms": 28820,
                "end_ms": 32300
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Malou confirms what was actually agreed and what is still unknown.",
                "start_ms": 32600,
                "end_ms": 38040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "An official or peer cannot replace the health professional's assessment.",
                "start_ms": 38340,
                "end_ms": 43820
              },
              {
                "zone": "body",
                "index": 7,
                "text": "No relationship guarantees transport, supplies, a response time or a successful outcome.",
                "start_ms": 44120,
                "end_ms": 52240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Coordinate distinct roles without promising resources or replacing assessment.",
                "start_ms": 52540,
                "end_ms": 58140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-relationships/shared-support.fil.284ae77c1442.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "284ae77c14429e93d0c82a158018930b6664aa0614ca9e0f17e00900e2e4b43f",
            "sha256": "6d1ecb602731ab410550f9fa304373a59f00dfb00c05713492f29c00e57e4ae8",
            "duration_seconds": 60.291,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mag-ugnay ng suporta nang may malinaw na papel",
                "start_ms": 0,
                "end_ms": 3800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pinaghihiwalay ni Malou ang mga tanong habang pinag-uugnay ang suporta.",
                "start_ms": 4100,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa pagsang-ayon ni Nena, tumutulong siyang tukuyin ang angkop na paraan para sa propesyonal na tanong.",
                "start_ms": 8920,
                "end_ms": 15800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hiwalay dito, maaaring linawin ng responsableng barangay contact ang lugar o hiling na praktikal na suporta.",
                "start_ms": 16100,
                "end_ms": 23860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring tulungan ng kapwa BHW si Malou na ayusin ang napagkasunduang karaniwang gawain at alamin ang malabo pa.",
                "start_ms": 24160,
                "end_ms": 32320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Patuloy na ibinabahagi ni Nena ang kaniyang pagpili.",
                "start_ms": 32620,
                "end_ms": 35860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tinitiyak ni Malou ang talagang napagkasunduan at ang hindi pa alam.",
                "start_ms": 36160,
                "end_ms": 41080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi kapalit ng health professional ang opisyal o kapwa BHW.",
                "start_ms": 41380,
                "end_ms": 47020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Walang garantiya ng transportasyon, kagamitan, oras ng sagot o matagumpay na resulta.",
                "start_ms": 47320,
                "end_ms": 54120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pag-ugnayin ang magkakaibang papel nang walang pangako o kapalit na pagtatasa.",
                "start_ms": 54420,
                "end_ms": 60220
              }
            ]
          }
        }
      }
    },
    "bhw-right-contact": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "contact-application": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-application.en.844783248522.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "844783248522f7a0e556a320d48fca9a9d92e9b945d8eea8f876bb5ba159cbef",
            "sha256": "44b804f61c033700e7becf2111ee60a2fe3a6c953d99d1134772460adf008052",
            "duration_seconds": 44.617,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose and explain",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A new BHW asks Malou how to file the first report.",
                "start_ms": 2300,
                "end_ms": 6740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is no immediate health concern in this situation.",
                "start_ms": 7040,
                "end_ms": 10960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose an appropriate first action and explain what to confirm with the supervisor.",
                "start_ms": 11260,
                "end_ms": 17020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Then summarize four relationships: the community for listening and participation; fellow BHWs for teamwork; the authorized health team for professional guidance; and local partners for administrative support.",
                "start_ms": 17320,
                "end_ms": 32400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "For each relationship, clarify the role, need and local process.",
                "start_ms": 32700,
                "end_ms": 39260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match the need to the role, verify the process and follow up.",
                "start_ms": 39560,
                "end_ms": 44560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-application.fil.b7d1a51d19f3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b7d1a51d19f30fab71f5af3e0da03525dab20e3f4270531915b95a21c277542c",
            "sha256": "3a36f65284c1da647747586df5034bcfbf181f7210f626ec7a3aa522268146dd",
            "duration_seconds": 52.637,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin at ipaliwanag",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May bagong BHW na nagtatanong kay Malou kung paano mag-file ng unang ulat.",
                "start_ms": 2780,
                "end_ms": 9540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Walang agarang alalahaning pangkalusugan sa sitwasyong ito.",
                "start_ms": 9840,
                "end_ms": 14040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang angkop na unang hakbang at ipaliwanag kung ano ang titiyakin sa supervisor.",
                "start_ms": 14340,
                "end_ms": 20580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pagkatapos, ibuod ang apat na ugnayan: komunidad para sa pakikinig at partisipasyon; kapwa BHW para sa pagtutulungan; awtorisadong health team para sa propesyonal na gabay; at mga lokal na katuwang para sa administratibong suporta.",
                "start_ms": 20880,
                "end_ms": 40440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa bawat ugnayan, linawin ang papel, pangangailangan at lokal na proseso.",
                "start_ms": 40740,
                "end_ms": 46980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itugma ang kailangan sa papel, tiyakin ang proseso at sundan.",
                "start_ms": 47280,
                "end_ms": 52560
              }
            ]
          }
        },
        "contact-classify": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-classify.en.cb822501112c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cb822501112c1c076cac4b6c0277dbd163ace13b79ec77b2b83d3d7ade6f14ea",
            "sha256": "58d51600f17256e3d16bcc226f81dbeb7e70be850869b00ee46e23c6ef7df9a8",
            "duration_seconds": 33.489,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What is needed?",
                "start_ms": 0,
                "end_ms": 1360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a fictional coordination desk, Malou has two requests: help filing a report and a health concern.",
                "start_ms": 1660,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Before choosing a contact, she clarifies the need, whether immediate help is needed, and the limits of her role.",
                "start_ms": 9360,
                "end_ms": 17520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Familiarity alone is not the basis.",
                "start_ms": 17820,
                "end_ms": 20980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "When immediate help is needed, follow the local referral or emergency process promptly; do not wait to find a perfect contact.",
                "start_ms": 21280,
                "end_ms": 30400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose by need and urgency.",
                "start_ms": 30700,
                "end_ms": 33420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-classify.fil.be0e25a347df.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "be0e25a347dfac3edf3ba526a91288a451ea82795b06d0593024157ed7d27d0d",
            "sha256": "24db276de5129fc99885943ef25fa4ff4757908443b9a1fda6f819efc24047fb",
            "duration_seconds": 39.236,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang kailangan?",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na coordination desk, may dalawang kahilingan si Malou: tulong sa pag-file ng ulat at alalahanin tungkol sa kalusugan.",
                "start_ms": 1900,
                "end_ms": 11460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bago pumili ng lalapitan, nililinaw niya ang pangangailangan, kung may agarang tulong na kailangan, at ang saklaw ng kanyang tungkulin.",
                "start_ms": 11760,
                "end_ms": 21600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi batayan ang pagiging kakilala lamang.",
                "start_ms": 21900,
                "end_ms": 25140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung agarang tulong ang kailangan, sundin agad ang lokal na referral o emergency process; huwag hintaying mahanap ang perpektong contact.",
                "start_ms": 25440,
                "end_ms": 34600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ayon sa pangangailangan at pagkaapurahan.",
                "start_ms": 34900,
                "end_ms": 39180
              }
            ]
          }
        },
        "contact-professional": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-professional.en.fd31bd5aae34.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fd31bd5aae34698ab1dcfa083a281b04a00ce81d2d8e57ba91a6f59350d5e6c4",
            "sha256": "05fe48ac6303fd3fb1b5edef001f226e8d07dac19d73877dd8cca8458c33bd36",
            "duration_seconds": 41.874,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A health concern",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For a clinical, uncertain or urgent concern, contact the appropriate authorized health professional and follow the local referral or emergency process.",
                "start_ms": 2020,
                "end_ms": 13700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The contact may be a midwife, nurse, doctor or RHU according to the assigned service and need; no single profession is sufficient for every case.",
                "start_ms": 14000,
                "end_ms": 25800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Malou does not diagnose or prescribe medicines.",
                "start_ms": 26100,
                "end_ms": 29980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If immediate help is needed, act promptly under the local process while arranging coordination.",
                "start_ms": 30280,
                "end_ms": 37160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clinical decisions belong to the appropriate authorized professional.",
                "start_ms": 37460,
                "end_ms": 41820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-professional.fil.22b14a9749bb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "22b14a9749bb9b02b34d606e5f4a7ba4a1ca3167c37530c269fa65530cd0ccec",
            "sha256": "595f168c94e752c0e43e90d1139dd78b796b2d479fcc5dbd7003daf25ed46dd4",
            "duration_seconds": 43.598,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Alalahaning pangkalusugan",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kapag klinikal, hindi tiyak o apurahan ang alalahanin, lumapit sa angkop na awtorisadong health professional at sundin ang lokal na referral o emergency process.",
                "start_ms": 2540,
                "end_ms": 14220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring contact ang midwife, nurse, doktor o RHU ayon sa nakatalagang serbisyo at pangangailangan; hindi sapat ang iisang propesyon para sa lahat ng kaso.",
                "start_ms": 14520,
                "end_ms": 27240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi nagdi-diagnose o nagtatakda ng gamot si Malou.",
                "start_ms": 27540,
                "end_ms": 31340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung agarang tulong ang kailangan, kumilos agad ayon sa lokal na proseso habang inaayos ang koordinasyon.",
                "start_ms": 31640,
                "end_ms": 38480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang klinikal na pasya ay para sa angkop na awtorisadong propesyonal.",
                "start_ms": 38780,
                "end_ms": 43540
              }
            ]
          }
        },
        "contact-verify": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-verify.en.218125211b1b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "218125211b1b7b8746df340b6284a11a242fd55d0314268a076dc36630528017",
            "sha256": "782991b3230d7b0383dc012a16ed493fbdc390ae7fa14ec6448911b0541ed92f",
            "duration_seconds": 41.848,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Verify and follow up",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Malou verifies who is on duty, how to contact them safely, the next action and when to follow up on the outcome.",
                "start_ms": 3020,
                "end_ms": 11700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If the first contact is unavailable, use the confirmed alternative under the local process; do not keep waiting when the need is urgent.",
                "start_ms": 12000,
                "end_ms": 20880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "With a nonhealth partner, share only the minimum information needed for coordination, consistent with consent and local policy.",
                "start_ms": 21180,
                "end_ms": 30540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Separate confirmed from unconfirmed arrangements and update the person who requested help.",
                "start_ms": 30840,
                "end_ms": 36680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Verify the contact, next action and outcome.",
                "start_ms": 36980,
                "end_ms": 41780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/contact-verify.fil.4e509cb330ab.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4e509cb330abdb691577fdba43f97792c008b71de2cd2ea6c4ba3fb9cb678660",
            "sha256": "952fc4bc0d1d8e4cb6a3360de5089c19122cfdc95f759a064d8091982d92510d",
            "duration_seconds": 44.696,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tiyakin at sundan",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinitiyak ni Malou kung sino ang naka-duty, paano ligtas na makikipag-ugnayan, ano ang susunod na hakbang at kailan susundan ang resulta.",
                "start_ms": 2300,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi makontak ang una, gamitin ang kumpirmadong alternatibo ayon sa lokal na proseso; huwag tumigil sa paghihintay kung apurahan.",
                "start_ms": 12840,
                "end_ms": 22320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa nonhealth partner, ibahagi lamang ang pinakamaliit na impormasyong kailangan sa koordinasyon, alinsunod sa pahintulot at lokal na patakaran.",
                "start_ms": 22620,
                "end_ms": 32980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ihiwalay ang kumpirmado sa hindi pa kumpirmado at magbalita sa taong humingi ng tulong.",
                "start_ms": 33280,
                "end_ms": 40120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang contact, susunod na hakbang at resulta.",
                "start_ms": 40420,
                "end_ms": 44620
              }
            ]
          }
        },
        "section-11": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/section-11.en.3d6bad2249c0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3d6bad2249c03ec32d56a9932ede3b6809f3e0668f86854899aa6631f73d85ac",
            "sha256": "d7ed5dd20c94a5415a76b70440242c78c37dd2c6918c26331b1ed260483b7747",
            "duration_seconds": 37.878,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it: the first report",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A new BHW is confused about filing the first report.",
                "start_ms": 2700,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou can ask an experienced fellow BHW for routine steps that the peer knows and can support competently.",
                "start_ms": 7720,
                "end_ms": 16400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Confirm the official form, method, deadline and recipient with the designated supervisor.",
                "start_ms": 16700,
                "end_ms": 23140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If the peer is unsure, ask the supervisor to clarify.",
                "start_ms": 23440,
                "end_ms": 27600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Use a blank example for practice, rather than an actual patient record.",
                "start_ms": 27900,
                "end_ms": 32700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Peer practical support; official confirmation with the supervisor.",
                "start_ms": 33000,
                "end_ms": 37800
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/section-11.fil.e49cfc21f4d9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e49cfc21f4d96de24a663dca47d8575d396d3a27cb78064de54a40187e7a5d27",
            "sha256": "b1a43c8e3d775fd8dba6d444386114c8c3886fd2447ad5109a1e3056225cd473",
            "duration_seconds": 43.703,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan mo: unang ulat",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nalilito ang bagong BHW sa pag-file ng unang ulat.",
                "start_ms": 2940,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring magpatulong si Malou sa kapwa BHW na may karanasan sa karaniwang hakbang na alam nito at saklaw ng kakayahan nito.",
                "start_ms": 7240,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tiyakin sa itinalagang supervisor ang opisyal na form, paraan, deadline at tumatanggap ng ulat.",
                "start_ms": 16020,
                "end_ms": 24300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung hindi tiyak ang sagot ng kapwa BHW, humingi ng paglilinaw sa supervisor.",
                "start_ms": 24600,
                "end_ms": 30920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gumamit ng blangkong halimbawa sa pagsasanay, hindi totoong patient record.",
                "start_ms": 31220,
                "end_ms": 36860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Praktikal na tulong ng kapwa BHW; opisyal na pagtitiyak sa supervisor.",
                "start_ms": 37160,
                "end_ms": 43640
              }
            ]
          }
        },
        "section-12": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/section-12.en.c11b43f6ae7b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c11b43f6ae7b50aa16e106f8c907b3667c9d6758a6bb60f9b3bdbe2c27052adc",
            "sha256": "119802fd9b58468a32f82ca937998a46ef40ebecde0af3bea748828200aa1d53",
            "duration_seconds": 42.292,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Wrong and right choices",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In a fictional example, Aling Nena asks about her child’s cough.",
                "start_ms": 2700,
                "end_ms": 7900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou should not choose the barangay captain for a clinical decision just because they often speak.",
                "start_ms": 8200,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The appropriate choice is guidance from the authorized health professional or RHU under the local process, without delaying immediate help when needed.",
                "start_ms": 15060,
                "end_ms": 25380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Transport support may be coordinated with the responsible local contact at the same time.",
                "start_ms": 25680,
                "end_ms": 31280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Support is separate from clinical decisions; Malou does not guarantee a vehicle or funding.",
                "start_ms": 31580,
                "end_ms": 37940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Coordinate support without delaying appropriate help.",
                "start_ms": 38240,
                "end_ms": 42240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-right-contact/section-12.fil.b97a5c23c79a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b97a5c23c79a3b3b087d1d1414384aeda1f62ae689ac586241652e5b0d8624ee",
            "sha256": "4a6b28b825ad4ab93d28eeedb889b28af4094c6fe65541696f1e420aaf2f26a2",
            "duration_seconds": 48.353,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mali at tamang pagpili",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na halimbawa, may tanong si Aling Nena tungkol sa ubo ng kanyang anak.",
                "start_ms": 2740,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maling piliin ni Malou ang barangay captain para sa klinikal na pasya dahil lamang palagi niya itong kausap.",
                "start_ms": 9440,
                "end_ms": 16800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tamang humingi ng gabay sa angkop na awtorisadong health professional o RHU ayon sa lokal na proseso, nang hindi inaantala ang agarang tulong kung kailangan.",
                "start_ms": 17100,
                "end_ms": 28860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring kasabay na iugnay sa responsableng lokal na contact ang suportang pantransportasyon.",
                "start_ms": 29160,
                "end_ms": 36320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hiwalay ang suporta sa klinikal na pasya; hindi ginagarantiya ni Malou ang sasakyan o pondo.",
                "start_ms": 36620,
                "end_ms": 43420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iugnay ang suporta nang hindi inaantala ang angkop na tulong.",
                "start_ms": 43720,
                "end_ms": 48280
              }
            ]
          }
        }
      }
    },
    "bhw-roles-application": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "applied-education": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-education.en.74ced2f5d230.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "74ced2f5d230fc1d7339453df044ff9e8cc9f23dcde93bbd85dcce3396826b6a",
            "sha256": "3a39c0e56875a7d63f962fef619338f04958591ccdfc37d0d5193b876f5f6941",
            "duration_seconds": 37.538,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen before explaining",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza asks the family: “What have you noticed about the water collecting here?",
                "start_ms": 2940,
                "end_ms": 7780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Is there anything you would like to ask the health team?”",
                "start_ms": 8080,
                "end_ms": 10680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She listens first, then uses a health team approved message and an explanation suited to the audience.",
                "start_ms": 10980,
                "end_ms": 18620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If she is unsure of an answer, she asks the health team.",
                "start_ms": 18920,
                "end_ms": 22560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This is the Health Educator role: help the family understand the message and find out what still needs clarification.",
                "start_ms": 22860,
                "end_ms": 30180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Health Educator: listen, use an approved message, and clarify questions.",
                "start_ms": 30480,
                "end_ms": 37480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-education.fil.dc97cc883324.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dc97cc883324641b9b5b368ececea630363082db12d6c7ab1343c4b0eb70cfcd",
            "sha256": "b6bd9fc211364f876306d3dceb63eb9b9b78b88e6ab329271d86e54981d918fc",
            "duration_seconds": 43.468,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig bago magpaliwanag",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinanong ni Riza ang pamilya: “Ano po ang napapansin ninyo sa tubig na naiipon dito?",
                "start_ms": 3460,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May gusto po ba kayong itanong sa health team?”",
                "start_ms": 9440,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nakinig muna siya, saka gumamit ng mensaheng aprubado ng health team at paliwanag na angkop sa kausap.",
                "start_ms": 13380,
                "end_ms": 22020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kapag hindi niya tiyak ang sagot, itatanong niya ito sa health team.",
                "start_ms": 22320,
                "end_ms": 26840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ito ang Health Educator na tungkulin: tulungang maunawaan ng pamilya ang mensahe, at alamin kung ano pa ang kailangang linawin.",
                "start_ms": 27140,
                "end_ms": 35900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Health Educator: makinig, gumamit ng aprubadong mensahe, at linawin ang tanong.",
                "start_ms": 36200,
                "end_ms": 43400
              }
            ]
          }
        },
        "applied-observation": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-observation.en.bf29fe907abf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bf29fe907abfe01796bc5421b4b83cb488f1953d9b8a649a87784ab25c4a14de",
            "sha256": "4aea5ce3b668b98aa72a1ea71e9f1cc0f314ed05d729628264cab64d808c010c",
            "duration_seconds": 40.829,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One observation, three roles",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "During a neighborhood visit, BHW Riza notices standing water in three yards.",
                "start_ms": 3260,
                "end_ms": 10340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The midwife instructs: “Record what you saw, ask whether anyone wants to speak with the health team, and report the actions still needed to me.”",
                "start_ms": 10640,
                "end_ms": 20480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Riza reads the instruction and clarifies uncertainty.",
                "start_ms": 20780,
                "end_ms": 25300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Standing water is an observation; it does not establish that residents are ill.",
                "start_ms": 25600,
                "end_ms": 30600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Which roles will she need to follow the whole instruction?",
                "start_ms": 30900,
                "end_ms": 34700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Read and clarify the instruction; separate observation from assumption.",
                "start_ms": 35000,
                "end_ms": 40760
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-observation.fil.b3f59eb39de0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b3f59eb39de01fcc46c862fae94228cfca4d01e46730dc47a43bbc33d2cfbb30",
            "sha256": "d9dd809f50914e3edd85eb46bdb6de09c15dcb42aed0ee94263925ebb0c381f3",
            "duration_seconds": 44.304,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang obserbasyon, tatlong tungkulin",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pagbisita sa purok, napansin ni BHW Riza ang naipong tubig sa tatlong bakuran.",
                "start_ms": 3700,
                "end_ms": 11140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tagubilin ng midwife: “Itala ang nakita, itanong kung may gustong kausapin ang health team, at iulat sa akin ang kailangan pang aksyon.”",
                "start_ms": 11440,
                "end_ms": 21960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Binasa ni Riza ang tagubilin at nilinaw ang hindi tiyak.",
                "start_ms": 22260,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang naipong tubig ay obserbasyon; hindi nito pinatutunayang may sakit ang mga residente.",
                "start_ms": 27320,
                "end_ms": 33560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Aling mga tungkulin ang kailangan upang masunod ang buong tagubilin?",
                "start_ms": 33860,
                "end_ms": 38900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Basahin at linawin ang tagubilin; ihiwalay ang nakita sa hinala.",
                "start_ms": 39200,
                "end_ms": 44240
              }
            ]
          }
        },
        "applied-organizing": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-organizing.en.136db19b8822.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "136db19b88226a015be8e007d690e7f8d40e0d1b675540421329072138326709",
            "sha256": "938522275e2afe266201e2a1c6b597c825b3f596010e34a049a3c5a2e0842d6b",
            "duration_seconds": 42.449,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Invite people to take part",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For a shared discussion, Riza speaks with residents, the purok leader, the council member, and health staff.",
                "start_ms": 2700,
                "end_ms": 10700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“When could we discuss what we observed and what we might do?”",
                "start_ms": 11000,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "she asks.",
                "start_ms": 14940,
                "end_ms": 16180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She listens to suggestions about the time and activity before they agree.",
                "start_ms": 16480,
                "end_ms": 23000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This is the Community Organizer role: connect people and encourage participation.",
                "start_ms": 23300,
                "end_ms": 29420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She does not present an activity as agreed before people have discussed it.",
                "start_ms": 29720,
                "end_ms": 34840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Community Organizer: invite, listen, and agree with the people involved.",
                "start_ms": 35140,
                "end_ms": 42380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/applied-organizing.fil.dccbf0199ac9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dccbf0199ac9c5535486007b3cd31c02fc3d21c70c477da8d3dc64a9c777a9d7",
            "sha256": "9cdc90bf251dfc4d73b9ee3d7880b10a9e9deb0b56141141956762765a870cae",
            "duration_seconds": 46.132,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Anyayahan ang mga makakatuwang",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Para sa sama-samang pagtalakay, kinausap ni Riza ang mga residente, purok leader, kagawad, at health staff.",
                "start_ms": 2660,
                "end_ms": 10180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Kailan po tayo maaaring mag-usap tungkol sa nakita natin at sa maaaring gawin?”",
                "start_ms": 10480,
                "end_ms": 17600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong niya.",
                "start_ms": 17900,
                "end_ms": 19460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pinakinggan niya ang kanilang mungkahi sa oras at gawain bago magkasundo.",
                "start_ms": 19760,
                "end_ms": 24560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ito ang Community Organizer na tungkulin: pag-ugnayin ang mga tao at hikayatin ang kanilang pakikilahok.",
                "start_ms": 24860,
                "end_ms": 32020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya itinuturing na napagkasunduan ang isang gawain hangga’t hindi pa ito napag-uusapan.",
                "start_ms": 32320,
                "end_ms": 38440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Community Organizer: mag-anyaya, makinig, at magkasundo kasama ang mga tao.",
                "start_ms": 38740,
                "end_ms": 46060
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/check.en.32fc2e746bb1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "32fc2e746bb18995c0977aaa7e89c3435038d6058a9cd970cf802192a084e794",
            "sha256": "e4d0ae521723579bc40d851fa2782cac6273eeb32eef67f3a4a17a60e03424ac",
            "duration_seconds": 38.583,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply and explain the roles",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Now it is your turn.",
                "start_ms": 2940,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose the report that addresses the whole instruction, then speak your own handover using observed, done, and needed.",
                "start_ms": 5040,
                "end_ms": 13160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Explain which actions used the Health Educator, Community Organizer, and Health Service Provider roles.",
                "start_ms": 13460,
                "end_ms": 20940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The online question prepares you for practice.",
                "start_ms": 21240,
                "end_ms": 24400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The facilitator observes your actual performance separately; lesson completion does not establish practical competence.",
                "start_ms": 24700,
                "end_ms": 32140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose the role, follow the instruction, record, and report what is needed.",
                "start_ms": 32440,
                "end_ms": 38520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/check.fil.76af0317b89f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "76af0317b89fde3ebcafdb2e56e616278ca95fb5d37c203743bd45c1165c414e",
            "sha256": "ab9bd0a0db9872fcbb9932c5883ff3e40f4578a0abd6b4f71c69e68b2c577210",
            "duration_seconds": 47.151,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin at ipaliwanag ang mga tungkulin",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ngayon, ikaw naman.",
                "start_ms": 3060,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang ulat na tumutugon sa buong tagubilin, saka bigkasin ang sarili mong handover gamit ang nakita, ginawa, at kailangan.",
                "start_ms": 5280,
                "end_ms": 16160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipaliwanag kung alin ang Health Educator, Community Organizer, at Health Service Provider na gawain.",
                "start_ms": 16460,
                "end_ms": 24780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang online na tanong ay paghahanda para sa pagsasanay.",
                "start_ms": 25080,
                "end_ms": 29040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hiwalay na oobserbahan ng facilitator ang aktwal mong pagganap; ang pagkumpleto ng aralin ay hindi katibayan ng praktikal na kakayahan.",
                "start_ms": 29340,
                "end_ms": 38980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang tungkulin, sundin ang tagubilin, itala, at iulat ang kailangan.",
                "start_ms": 39280,
                "end_ms": 47080
              }
            ]
          }
        },
        "handover": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/handover.en.4fa8ca13dee1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4fa8ca13dee1ea97af4382a81c2268f9b7ef808c4845cbd41103157ab9dda06b",
            "sha256": "9fdea43486871df5c59ed6eaf7002786ab20130124627023393ec959a65dd178",
            "duration_seconds": 42.867,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Observed, done, and needed",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza reports to the midwife: “There is standing water in three yards.",
                "start_ms": 3100,
                "end_ms": 7940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "I recorded the observation, listened to questions, and spoke with potential partners.",
                "start_ms": 8240,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A resident wants to speak with the health team; I explained the contact you confirmed.",
                "start_ms": 14660,
                "end_ms": 19180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "I still need guidance on the next step.”",
                "start_ms": 19480,
                "end_ms": 21880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Compare the report with the record and the instruction.",
                "start_ms": 22180,
                "end_ms": 25980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Share only relevant information with the appropriate recipient.",
                "start_ms": 26280,
                "end_ms": 30760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Explain where she used each role and what remains unfinished.",
                "start_ms": 31060,
                "end_ms": 35780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Short handover: observed + actual action taken + action still needed.",
                "start_ms": 36080,
                "end_ms": 42800
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/handover.fil.aa3782d47ef0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "aa3782d47ef0b20fce8b874004d049bd34966bd9df4c591e0d376b11a392cb0a",
            "sha256": "9df425713483d1dabc8efad2f91c3e6c172d068bc923daede8362f8bcdb30312",
            "duration_seconds": 47.02,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Nakita, ginawa, at kailangan",
                "start_ms": 0,
                "end_ms": 4080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iniulat ni Riza sa midwife: “May naipong tubig sa tatlong bakuran.",
                "start_ms": 4380,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Naitala ko ang obserbasyon, nakinig sa mga tanong, at kinausap ang mga makakatuwang.",
                "start_ms": 9720,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May residenteng gustong makausap ang health team; ipinaliwanag ko ang contact na kinumpirma ninyo.",
                "start_ms": 16020,
                "end_ms": 21900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kailangan ko pa ng gabay sa susunod na hakbang.”",
                "start_ms": 22200,
                "end_ms": 25360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ihambing ang ulat sa tala at sa tagubilin.",
                "start_ms": 25660,
                "end_ms": 29260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ibahagi lamang ang kaugnay na impormasyon sa tamang tatanggap.",
                "start_ms": 29560,
                "end_ms": 34080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ipaliwanag kung saan niya ginamit ang bawat tungkulin at kung ano pa ang hindi tapos.",
                "start_ms": 34380,
                "end_ms": 40380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maikling handover: nakita + aktwal na ginawa + kailangan pang aksyon.",
                "start_ms": 40680,
                "end_ms": 46960
              }
            ]
          }
        },
        "next-learning": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/next-learning.en.6b84c29e396f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6b84c29e396f40a0405d15969fa238df99f049dbc88a40c0746c3a7557497745",
            "sha256": "e30561e4c8dc02e094aa3efb166e9f889a48dfd3de0c1c0f9139d3652da23949",
            "duration_seconds": 53.995,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Guide and record the action",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A resident wants to speak with the health team.",
                "start_ms": 2740,
                "end_ms": 5340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Riza confirms the appropriate contact and local communication route with the midwife, then explains the next step to the resident.",
                "start_ms": 5640,
                "end_ms": 14280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Following the instruction, she records what she observed, the question, and what she actually did; she does not record a service as delivered when it was not.",
                "start_ms": 14580,
                "end_ms": 26060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This is the Health Service Provider role: guide residents and support the health team within her training.",
                "start_ms": 26360,
                "end_ms": 32880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Record selection connects to lesson 1.1.5; communication, community mobilization, and health-promotion teaching are developed further in later lessons.",
                "start_ms": 33180,
                "end_ms": 45820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Health Service Provider: confirm the contact, explain the next step, and record the actual action.",
                "start_ms": 46120,
                "end_ms": 53920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-application/next-learning.fil.3b989656a71a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3b989656a71a66e5082a31df45dbd9e9876d0bc2a887f3c3484092c85dbda099",
            "sha256": "98847de775334c734842c5b6a1551a9bf7498adb232de13522615c1094ba0855",
            "duration_seconds": 56.189,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gumabay at itala ang ginawa",
                "start_ms": 0,
                "end_ms": 3520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May residenteng gustong makausap ang health team.",
                "start_ms": 3820,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kinumpirma ni Riza sa midwife ang angkop na contact at lokal na paraan ng pakikipag-ugnayan, saka ipinaliwanag ang susunod na hakbang sa residente.",
                "start_ms": 7320,
                "end_ms": 17160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinala niya ang nakita, ang tanong, at ang aktwal na ginawa ayon sa tagubilin; hindi niya isinulat na may serbisyong naibigay kung wala naman.",
                "start_ms": 17460,
                "end_ms": 27300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ito ang Health Service Provider na tungkulin: gumabay at tumulong sa health team sa loob ng kanyang pagsasanay.",
                "start_ms": 27600,
                "end_ms": 35600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang pagpili ng tala ay kaugnay ng aralin 1.1.5; mas malalim na komunikasyon, community mobilization, at health-promotion teaching ay pag-aaralan sa mga susunod na aralin.",
                "start_ms": 35900,
                "end_ms": 48700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Health Service Provider: tiyakin ang contact, ipaliwanag ang hakbang, at itala ang aktwal na ginawa.",
                "start_ms": 49000,
                "end_ms": 56120
              }
            ]
          }
        }
      }
    },
    "bhw-roles-hepo": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/check.en.069d94fdebcb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "069d94fdebcbee22553b61679860e30ae28faac72bdd9ad40d8aa4866478cd7b",
            "sha256": "d448a0827e77c6406c2fea73cf25eddc4d6c2c65546450c433d5293d1c8d43cc",
            "duration_seconds": 20.715,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply your learning",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza brings residents together to plan a barangay clean-up drive.",
                "start_ms": 2060,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Which BHW role is most visible in this activity?",
                "start_ms": 7440,
                "end_ms": 12040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A BHW can combine education, community organizing, and service support to promote health.",
                "start_ms": 12340,
                "end_ms": 20660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/check.fil.7b305b1376d1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7b305b1376d1cc74e19175cb1e059e5b12d61a9c2be793d0c442340d4d51d1f1",
            "sha256": "58cc48a62fc7ce0c34446511e0209ee3100f24686e6769430b55647ffb59a068",
            "duration_seconds": 25.731,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin ang natutuhan",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinipon ni Riza ang mga residente upang planuhin ang paglilinis ng barangay.",
                "start_ms": 2620,
                "end_ms": 8860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Aling tungkulin ng BHW ang pinakakitang-kita sa gawaing ito?",
                "start_ms": 9160,
                "end_ms": 14480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maaaring pagsamahin ng BHW ang pagtuturo, pag-oorganisa, at pagtulong sa serbisyo upang isulong ang kalusugan.",
                "start_ms": 14780,
                "end_ms": 25660
              }
            ]
          }
        },
        "hepo": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/hepo.en.a7a98b4c0133.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a7a98b4c013350daf08a04c92374adef9e5dfbc953c4cf6b9fbe438922a2c7b9",
            "sha256": "b290896a82f5b88255ecab16b9d1290abb78ad9b2aee3a72f047625398b9c592",
            "duration_seconds": 46.524,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "HEPO: promoting health",
                "start_ms": 0,
                "end_ms": 3800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The Reference Manual uses the term barangay-level Health Education and Promotion Officer, or HEPO.",
                "start_ms": 4100,
                "end_ms": 12580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It describes the BHW’s role in sharing health information.",
                "start_ms": 12880,
                "end_ms": 17680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This role is expressed through being a Health Educator, Community Organizer, and Health Service Provider.",
                "start_ms": 17980,
                "end_ms": 25340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The visual connects related tasks; it is not an official organizational chart or proof of an appointment.",
                "start_ms": 25640,
                "end_ms": 33920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "HEPO means Health Education and Promotion Officer. It describes the BHW’s connected work in education, organizing, and service support.",
                "start_ms": 34220,
                "end_ms": 46460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/hepo.fil.ebff8b31fef1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ebff8b31fef107e2ca4697d3c5ecaf7daeeab61f3d432caf60a75a8d57c5ef53",
            "sha256": "54fa948f94fef07b909d1d2aa26b76cf96e0227606cb2cf1f3090f31eb32c186",
            "duration_seconds": 54.073,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "HEPO: pagsusulong ng kalusugan",
                "start_ms": 0,
                "end_ms": 3920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ginagamit ng Reference Manual ang katawagang barangay-level Health Education and Promotion Officer o HEPO.",
                "start_ms": 4220,
                "end_ms": 15060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inilalarawan nito ang papel ng BHW sa pagbabahagi ng impormasyong pangkalusugan.",
                "start_ms": 15360,
                "end_ms": 22680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Makikita ang papel na ito sa pagiging Health Educator, Community Organizer, at Health Service Provider.",
                "start_ms": 22980,
                "end_ms": 30980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang ugnayan sa larawan ay paliwanag ng magkakaugnay na gawain; hindi ito opisyal na organizational chart o patunay ng appointment.",
                "start_ms": 31280,
                "end_ms": 40480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang HEPO ay Health Education and Promotion Officer. Inilalarawan nito ang magkakaugnay na gawain ng BHW sa pagtuturo, pag-oorganisa, at pagtulong sa serbisyo.",
                "start_ms": 40780,
                "end_ms": 54020
              }
            ]
          }
        },
        "knowledge": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/knowledge.en.70aff9d4630a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "70aff9d4630aa6c0f300c66695a08f15d2b88cdbe7e286dff116df0004610014",
            "sha256": "f5a0e6a78eca32ea4aff00d24ba352c831bf0ccdac4730a5dbefd42ce4be2a90",
            "duration_seconds": 29.884,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Prepare before sharing",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza needs adequate knowledge of the barangay’s priority health programs and problems.",
                "start_ms": 2660,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Before teaching, she makes sure she understands the information.",
                "start_ms": 8920,
                "end_ms": 13880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "When a detail is uncertain, she confirms it with the appropriate health worker and uses approved materials.",
                "start_ms": 14180,
                "end_ms": 22020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Helping does not require guessing an answer.",
                "start_ms": 22320,
                "end_ms": 26000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Adequate knowledge supports all three roles.",
                "start_ms": 26300,
                "end_ms": 29820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/knowledge.fil.8886fadf3fc4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8886fadf3fc4cc925214c80ec7dc518c8e0ab90d047e6a4f294663c657dc0de0",
            "sha256": "21d008ff65f79179e374b4fcfe6a5dfb5738da0f74dcf620e89deec12776f8c0",
            "duration_seconds": 36.571,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bago magbahagi, maghanda",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kailangan ni Riza ng sapat na kaalaman sa mga prayoridad na programa at problemang pangkalusugan sa barangay.",
                "start_ms": 3540,
                "end_ms": 12300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bago magturo, sinisiguro niyang malinaw sa kanya ang impormasyong ibabahagi.",
                "start_ms": 12600,
                "end_ms": 18680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kapag may detalyeng hindi tiyak, kinukumpirma niya ito sa kaukulang health worker at ginagamit ang aprubadong materyal.",
                "start_ms": 18980,
                "end_ms": 27980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi kailangang hulaan ang sagot para makatulong.",
                "start_ms": 28280,
                "end_ms": 32240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sapat na kaalaman ang pundasyon ng tatlong tungkulin.",
                "start_ms": 32540,
                "end_ms": 36500
              }
            ]
          }
        },
        "morning": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/morning.en.6b4adcdcb332.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6b4adcdcb332ccd43f17190088a36d6c06abb807d51dcfba24d3e701708f8ab4",
            "sha256": "6705df4895f7c6d097cc1c78ea5a672ccd4f48364d51afb2e31795af9cbaf27f",
            "duration_seconds": 41.221,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One morning, many tasks",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At 8:00 a.m., BHW Riza leads a health discussion in the purok.",
                "start_ms": 3020,
                "end_ms": 8660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "At 10:00 a.m., she talks with the council member about a clean-up drive.",
                "start_ms": 8960,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "At 11:00 a.m., she helps Aling Nena contact the midwife about her child’s needs.",
                "start_ms": 14100,
                "end_ms": 20100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "One BHW does all three.",
                "start_ms": 20400,
                "end_ms": 23920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The curriculum describes UHC as strengthening primary care and health promotion, so the role extends beyond service support.",
                "start_ms": 24220,
                "end_ms": 33340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A BHW teaches and acts with the community as well as helping people reach services.",
                "start_ms": 33640,
                "end_ms": 41160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/morning.fil.7631e4b3e198.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7631e4b3e198fd36371bf6c506abd4ecee2fdbe09434277e043c6d57e7be3834",
            "sha256": "4aa2ba957118fd7a9ce9b1caecc2ee549d8fae19a799585d08d26f3a23f6b506",
            "duration_seconds": 50.39,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang umaga, maraming gawain",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Alas-otso, may talakayang pangkalusugan si BHW Riza sa purok.",
                "start_ms": 3420,
                "end_ms": 9780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Alas-diyes, kausap niya ang kagawad tungkol sa clean-up drive.",
                "start_ms": 10080,
                "end_ms": 15320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alas-onse, tinutulungan niya si Aling Nena na makausap ang midwife tungkol sa pangangailangan ng anak nito.",
                "start_ms": 15620,
                "end_ms": 23300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iisang BHW ang gumagawa ng tatlo.",
                "start_ms": 23600,
                "end_ms": 27840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa curriculum, ang direksyon ng UHC ay mas matibay na primary care at health promotion; kaya mas malawak ang papel kaysa pagtulong sa serbisyo lamang.",
                "start_ms": 28140,
                "end_ms": 40540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kasama sa gawain ng BHW ang pagtuturo at pagkilos kasama ang komunidad, bukod sa pagtulong sa serbisyo.",
                "start_ms": 40840,
                "end_ms": 50320
              }
            ]
          }
        },
        "prevention": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/prevention.en.7ec93c69284c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7ec93c69284c55094a9763080961eaa0341dd4a031af28b5e4b9c11aaa07f65f",
            "sha256": "220601e81a94317f37fecb086275cbfd90fa90717320906ade77edf282cbad21",
            "duration_seconds": 33.567,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Act with the community",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "When residents need care, the BHW helps them reach health services.",
                "start_ms": 2300,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW also teaches and encourages people to join health activities.",
                "start_ms": 7800,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For Riza’s clean-up drive, she shares information and invites residents to plan and act with her.",
                "start_ms": 14100,
                "end_ms": 21420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "These tasks connect education, community participation, and access to services.",
                "start_ms": 21720,
                "end_ms": 28600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Education and organizing contribute to health promotion.",
                "start_ms": 28900,
                "end_ms": 33500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-roles-hepo/prevention.fil.8625ae34a6c2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8625ae34a6c2e30ecc50a47e19048beac94b4d4d4a4806ba8cb141d3121800f3",
            "sha256": "49ccc951bf3cad9b90fe62dd2b117e4e8d967ae8f4a652b87a86770569f73fe0",
            "duration_seconds": 45.035,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kumilos kasama ang komunidad",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kapag nangangailangan ng pangangalaga ang mga residente, tinutulungan sila ng BHW na makalapit sa serbisyong pangkalusugan.",
                "start_ms": 3180,
                "end_ms": 12380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtuturo rin ang BHW at hinihikayat ang mga tao na makilahok sa mga gawaing pangkalusugan.",
                "start_ms": 12680,
                "end_ms": 20800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Para sa paglilinis ng barangay, nagbabahagi si Riza ng impormasyon at inaanyayahan ang mga residente na makipagplano at kumilos.",
                "start_ms": 21100,
                "end_ms": 31060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magkaugnay sa mga gawaing ito ang edukasyon, pakikilahok ng komunidad, at paglapit sa serbisyo.",
                "start_ms": 31360,
                "end_ms": 39200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kasama ang pagtuturo at pag-oorganisa sa pagsulong ng kalusugan.",
                "start_ms": 39500,
                "end_ms": 44980
              }
            ]
          }
        }
      }
    },
    "bhw-self-management": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "section-10": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/section-10.en.59e366a8a275.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "59e366a8a27515a84bb44b34c8ebe50c2ef19f95329c2c26d99b5b1f3989389a",
            "sha256": "0b96c8f6b24d119ae4dac86274d8ff0ea16d23277e9bf694977cc66e74a395d7",
            "duration_seconds": 73.822,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Develop one habit",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The reference gives eight habits: self-care, patience, one task at a time, reflection on your abilities, SMART goals, written weekly planning, meeting preparation and thinking before speaking.",
                "start_ms": 2220,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "To prepare for a meeting, ask for the agenda and read the materials.",
                "start_ms": 20120,
                "end_ms": 24920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Start with one habit you want to practice.",
                "start_ms": 25220,
                "end_ms": 28220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Malou’s example is: “On Monday, Wednesday and Friday this week, before starting my agreed work, I will write three priorities in my notebook.",
                "start_ms": 28520,
                "end_ms": 38280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "On Friday, I will check whether I did this on all three days.”",
                "start_ms": 38580,
                "end_ms": 42860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "It is specific, measurable, achievable, realistic and time-bound: SMART.",
                "start_ms": 43160,
                "end_ms": 52400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Her weekly plan includes a task, time and review.",
                "start_ms": 52700,
                "end_ms": 57260
              },
              {
                "zone": "body",
                "index": 7,
                "text": "This is a personal learning note, not an official form.",
                "start_ms": 57560,
                "end_ms": 61160
              },
              {
                "zone": "body",
                "index": 8,
                "text": "A change to an official assignment still requires checking the local process and permission.",
                "start_ms": 61460,
                "end_ms": 68180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose one habit, write a realistic goal and review the result.",
                "start_ms": 68480,
                "end_ms": 73760
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/section-10.fil.cdb3105c49d7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cdb3105c49d74e410df2d2aaaf4afd839541dbf6ed19a57fd024e697104dc0b3",
            "sha256": "e7987a7e5ae78aaa1748db867fb878456032de2437d2f0cb5df9491a6c424891",
            "duration_seconds": 86.465,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Paunlarin ang isang gawi",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May walong gawi sa sanggunian: pangangalaga sa sarili, pasensya, isang gawain sa isang pagkakataon, pagninilay sa sariling kakayahan, SMART goal, nakasulat na lingguhang plano, paghahanda sa pulong, at pag-iisip bago magsalita.",
                "start_ms": 2700,
                "end_ms": 23820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa paghahanda sa pulong, hingin ang agenda at basahin ang materyales.",
                "start_ms": 24120,
                "end_ms": 29680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin muna ang isang gawi na nais mong sanayin.",
                "start_ms": 29980,
                "end_ms": 33820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Halimbawa ni Malou: “Sa Lunes, Miyerkules at Biyernes ngayong linggo, bago simulan ang napagkasunduang gawain, isusulat ko sa kuwaderno ang tatlong prayoridad.",
                "start_ms": 34120,
                "end_ms": 45800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa Biyernes, titingnan ko kung nagawa ko ito sa tatlong araw.”",
                "start_ms": 46100,
                "end_ms": 50460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tiyak ito, nasusukat, naaabot, makatotohanan at may hangganan sa oras: SMART.",
                "start_ms": 50760,
                "end_ms": 61480
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Sa kanyang lingguhang plano, may gawain, oras at pagrepaso.",
                "start_ms": 61780,
                "end_ms": 68260
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ito ay sariling learning note, hindi opisyal na form.",
                "start_ms": 68560,
                "end_ms": 72720
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung babaguhin ang opisyal na assignment, tiyakin muna ang lokal na proseso at pahintulot.",
                "start_ms": 73020,
                "end_ms": 79060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng isang gawi, isulat ang makatotohanang layunin at repasuhin ang resulta.",
                "start_ms": 79360,
                "end_ms": 86400
              }
            ]
          }
        },
        "section-9": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/section-9.en.e48406048fc4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e48406048fc412eb7687dfcc87c6c5fab936e71b4490277ab7a257deeb2ff7c4",
            "sha256": "d5f4b321f649d8529d876d56db77f9306354f578e9ca8aacb82f2826cf98c4f2",
            "duration_seconds": 56.163,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Many tasks: where do you start?",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional situation, Malou needs to prepare the agreed invitations before ten o’clock.",
                "start_ms": 3540,
                "end_ms": 10020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She also has an afternoon meeting and unfinished routine work.",
                "start_ms": 10320,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She wants to help, but cannot complete everything at once.",
                "start_ms": 14940,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "What should she do first?",
                "start_ms": 20360,
                "end_ms": 22440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Self-management means organizing your thoughts, feelings and actions to carry out work.",
                "start_ms": 22740,
                "end_ms": 29180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Six skills guide you: **reliability**, **stress management**, **time management**, **trustworthiness**, **adaptability**, and **being honest and careful**.",
                "start_ms": 29480,
                "end_ms": 41160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "These skills develop with practice.",
                "start_ms": 41460,
                "end_ms": 44060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Taking on everything or always being available is not the measure of a good BHW.",
                "start_ms": 44360,
                "end_ms": 51160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose an appropriate action; you do not have to take on everything.",
                "start_ms": 51460,
                "end_ms": 56100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/section-9.fil.8279d0010067.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8279d00100679067ad76f733d637e74e7a99b66478e7419fd27f4fdff3cd2f83",
            "sha256": "d5031fc4afd842133c223367bd52b0f59ae83a11b10353765e54a327853a246e",
            "duration_seconds": 64.575,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Maraming gawain: saan magsisimula?",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na sitwasyon, kailangang ihanda ni Malou ang napagkasunduang mga paanyaya bago mag-alas-diyes.",
                "start_ms": 3780,
                "end_ms": 11060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May pulong din siya sa hapon at may natitirang karaniwang gawain.",
                "start_ms": 11360,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nais niyang tumulong, ngunit hindi niya kayang tapusin ang lahat nang sabay-sabay.",
                "start_ms": 16180,
                "end_ms": 22340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ano ang uunahin niya?",
                "start_ms": 22640,
                "end_ms": 24840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang pamamahala sa sarili ay pag-aayos ng sariling pag-iisip, damdamin at kilos upang magawa ang gawain.",
                "start_ms": 25140,
                "end_ms": 35140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Anim na kasanayan ang gabay: **maaasahan**, **stress management**, **time management**, **mapagkakatiwalaan**, **adaptability**, at **matapat at maingat**.",
                "start_ms": 35440,
                "end_ms": 47960
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Napauunlad ang mga ito sa pagsasanay.",
                "start_ms": 48260,
                "end_ms": 51460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi sukatan ng pagiging mabuting BHW ang pag-ako sa lahat o pagiging laging available.",
                "start_ms": 51760,
                "end_ms": 59760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang angkop na kilos; hindi kailangang akuin ang lahat.",
                "start_ms": 60060,
                "end_ms": 64500
              }
            ]
          }
        },
        "self-adaptability": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-adaptability.en.dfcd16a5443f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dfcd16a5443f5f0fb0348ec1d493a495fd919a49b59c166fc43b7674d71c9b36",
            "sha256": "043b5bdfeeb833806fc3db0b73b7a3948c1c4d2691c8e760fbdface21be0e098",
            "duration_seconds": 48.953,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Adapt to a change",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "**Adaptability** means being willing to accept and respond to change.",
                "start_ms": 2620,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou learns that the meeting has moved earlier.",
                "start_ms": 8160,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She first confirms the new time with the designated contact.",
                "start_ms": 11700,
                "end_ms": 16020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She checks how this affects the invitations and her preparation.",
                "start_ms": 16320,
                "end_ms": 20680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She explains what she can finish and asks for clarification if an assignment needs to change.",
                "start_ms": 20980,
                "end_ms": 27260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She adjusts her plan after the agreement is confirmed.",
                "start_ms": 27560,
                "end_ms": 31160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Adapting does not mean following without questions or working beyond your training and authorization.",
                "start_ms": 31460,
                "end_ms": 38700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ask for guidance when a new task is unclear or unsafe.",
                "start_ms": 39000,
                "end_ms": 44000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm the change before adjusting your plan and commitments.",
                "start_ms": 44300,
                "end_ms": 48900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-adaptability.fil.4b6c5fe50b5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4b6c5fe50b5ba59a180492571cc00423a778774f5d8e41f7a1bb518da1c31316",
            "sha256": "a4552c571d0236541c5ec2dcfc308ee27a4059b671f2149fcaa1b6ad1c94d67e",
            "duration_seconds": 52.167,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Marunong umangkop sa pagbabago",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang **adaptability** ay kahandaang tumanggap at makisabay sa pagbabago.",
                "start_ms": 2460,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nalaman ni Malou na mas maaga na ang pulong.",
                "start_ms": 8120,
                "end_ms": 11920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tinitiyak muna niya ang bagong oras sa itinalagang contact.",
                "start_ms": 12220,
                "end_ms": 16380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tinitingnan niya kung maaapektuhan ang mga paanyaya at ang paghahanda niya.",
                "start_ms": 16680,
                "end_ms": 21800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipinapaliwanag niya ang kaya niyang matapos at humihingi ng paglilinaw kung may kailangang baguhin sa assignment.",
                "start_ms": 22100,
                "end_ms": 29740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Inaayos niya ang plano matapos makumpirma ang napagkasunduan.",
                "start_ms": 30040,
                "end_ms": 34400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ang pag-angkop ay hindi pagsunod nang walang tanong o paggawa nang lampas sa pagsasanay at awtorisasyon.",
                "start_ms": 34700,
                "end_ms": 41700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kapag hindi malinaw o hindi ligtas ang bagong gawain, humingi ng gabay.",
                "start_ms": 42000,
                "end_ms": 47600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyakin ang pagbabago bago iayon ang plano at pangako.",
                "start_ms": 47900,
                "end_ms": 52100
              }
            ]
          }
        },
        "self-application-check": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-application-check.en.4cf03c4bfb55.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4cf03c4bfb55e2c4973c20c8667cb1ce25b08290257c362ad3595f254f081239",
            "sha256": "52c9b7c2ec46a6f8a00a3443333bbdcde7ea38787644a3df9d56cb490d366f1b",
            "duration_seconds": 56.163,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply: Malou’s day has changed",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On another fictional day, Malou has confirmed that the meeting is earlier.",
                "start_ms": 3580,
                "end_ms": 7900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Five invitations are not ready, and she cannot complete both tasks at once.",
                "start_ms": 8200,
                "end_ms": 13960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "There is no immediate danger in this situation.",
                "start_ms": 14260,
                "end_ms": 17220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "There is still time to contact the designated person.",
                "start_ms": 17520,
                "end_ms": 20880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose the best of the three responses and explain which skills it demonstrates.",
                "start_ms": 21180,
                "end_ms": 26420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Then name the six skills without looking.",
                "start_ms": 26720,
                "end_ms": 29440
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Identify one strength and one skill to practice.",
                "start_ms": 29740,
                "end_ms": 33460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Write or say one SMART goal and when you will review the result.",
                "start_ms": 33760,
                "end_ms": 39920
              },
              {
                "zone": "body",
                "index": 8,
                "text": "You may use a fictional example; you do not need to disclose a personal problem.",
                "start_ms": 40220,
                "end_ms": 45460
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Reading or slides provide what you need to answer without watching the optional story.",
                "start_ms": 45760,
                "end_ms": 51520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Self-management involves actions you practice and review.",
                "start_ms": 51820,
                "end_ms": 56100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-application-check.fil.91ce8a1874a1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "91ce8a1874a1762284d84e096b30d7954a0fab7d71e4713fbaad47b31b99a777",
            "sha256": "ccfd3b97f4109b71c959555b57b589ae4e3174783a13f48e19ee4bc531c08cad",
            "duration_seconds": 70.687,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ilapat: nagbago ang araw ni Malou",
                "start_ms": 0,
                "end_ms": 3880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa isa pang kathang-isip na araw, nakumpirma ni Malou na mas maaga na ang pulong.",
                "start_ms": 4180,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May limang paanyayang hindi pa handa at hindi niya matatapos ang dalawang gawain nang sabay.",
                "start_ms": 10280,
                "end_ms": 16400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Walang agarang panganib sa sitwasyong ito.",
                "start_ms": 16700,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May oras pa upang makipag-ugnayan sa itinalagang contact.",
                "start_ms": 20360,
                "end_ms": 25160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin ang pinakamainam na tugon sa tatlong pagpipilian at ipaliwanag kung aling kasanayan ang ipinakikita nito.",
                "start_ms": 25460,
                "end_ms": 34420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Pagkatapos, pangalanan ang anim na kasanayan nang hindi tumitingin.",
                "start_ms": 34720,
                "end_ms": 40160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Pumili ng isang kalakasan at isang kasanayang sasanayin.",
                "start_ms": 40460,
                "end_ms": 44700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sumulat o magsabi ng isang SMART goal at kung kailan mo rerepasuhin ang resulta.",
                "start_ms": 45000,
                "end_ms": 51840
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Maaari kang gumamit ng kathang-isip na halimbawa; hindi kailangang magbahagi ng personal na problema.",
                "start_ms": 52140,
                "end_ms": 59180
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Masasagutan ito gamit ang pagbasa o slides kahit hindi panoorin ang opsyonal na kuwento.",
                "start_ms": 59480,
                "end_ms": 65560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang self-management ay mga kilos na sinasanay at nirerepaso.",
                "start_ms": 65860,
                "end_ms": 70620
              }
            ]
          }
        },
        "self-reliability": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-reliability.en.ce7c803a6fac.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ce7c803a6fac54193f8dbba49e8cb713e305ee30fa7a09e3be0b2a91c37dd76e",
            "sha256": "36d282dc42b18f05aa722132f16e8edad54873f8366249f3c6cc12a24620d70b",
            "duration_seconds": 47.778,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Reliable: make a clear commitment",
                "start_ms": 0,
                "end_ms": 3640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Being **reliable** means delivering the good service expected of you.",
                "start_ms": 3940,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou checks the task she accepted, its deadline and whether she can do it well.",
                "start_ms": 8800,
                "end_ms": 14840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She prepares the invitations and checks completeness before reporting back.",
                "start_ms": 15140,
                "end_ms": 20780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If she cannot finish by the agreed time, she reports early what is done and what remains.",
                "start_ms": 21080,
                "end_ms": 27200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She asks the designated contact for clarification or support.",
                "start_ms": 27500,
                "end_ms": 32340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Reliability involves a realistic commitment and a clear update; it does not mean promising to do everything.",
                "start_ms": 32640,
                "end_ms": 41160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Make a realistic commitment, report early and check the result.",
                "start_ms": 41460,
                "end_ms": 47700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-reliability.fil.452bf20e8b82.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "452bf20e8b8207e81f97bd3b75305d4165ec90d4067f53a00c8026a215cec316",
            "sha256": "bf4363d3ddbe68d74e55194b498e9a396fb88738abdc1ba031c7ad1fd26af8d6",
            "duration_seconds": 51.278,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Maaasahan: malinaw ang pangako",
                "start_ms": 0,
                "end_ms": 3600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang **maaasahan** ay naghahatid ng mabuting serbisyong inaasahan sa kanya.",
                "start_ms": 3900,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tinitingnan ni Malou kung ano ang tinanggap niyang gawain, ang takdang oras at kung kaya niya itong gawin nang maayos.",
                "start_ms": 9200,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Inihahanda niya ang mga paanyaya at tinitingnan kung kumpleto bago magbalita.",
                "start_ms": 17060,
                "end_ms": 22500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung hindi niya matatapos sa napagkasunduang oras, maaga niyang sinasabi kung ano ang tapos at ano ang natitira.",
                "start_ms": 22800,
                "end_ms": 29960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Humihingi siya ng paglilinaw o suporta sa itinalagang contact.",
                "start_ms": 30260,
                "end_ms": 35580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang maaasahan ay may makatotohanang pangako at malinaw na pagbalita; hindi siya basta nangangakong kaya ang lahat.",
                "start_ms": 35880,
                "end_ms": 45040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makatotohanang pangako, maagang pagbalita at pagtitiyak ng resulta.",
                "start_ms": 45340,
                "end_ms": 51220
              }
            ]
          }
        },
        "self-stress-time": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-stress-time.en.7c0d291e0bdb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7c0d291e0bdb35be3662fbce7158393cb716a514e6b925543d2053a5e0fe12b6",
            "sha256": "0928e712e24b875aa1a715f62884d2e5d69fb48e5d206bf9c8503d82eeb39a74",
            "duration_seconds": 62.563,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Manage stress and time",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "**Stress management** means staying calm and focused under pressure.",
                "start_ms": 2580,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou notices that she is rushing.",
                "start_ms": 7760,
                "end_ms": 10720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She pauses briefly, drinks water and organizes her next step.",
                "start_ms": 11020,
                "end_ms": 15820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She cares for herself and seeks support when needed.",
                "start_ms": 16120,
                "end_ms": 20160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This does not promise to remove all stress, and an excessive workload is not one person’s fault.",
                "start_ms": 20460,
                "end_ms": 27540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "**Time management** means prioritizing important work to meet deadlines.",
                "start_ms": 27840,
                "end_ms": 32720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "She checks agreed times, prepares the invitations first and sets aside time to prepare for the meeting.",
                "start_ms": 33020,
                "end_ms": 39980
              },
              {
                "zone": "body",
                "index": 7,
                "text": "She finishes one task before moving to the next.",
                "start_ms": 40280,
                "end_ms": 44040
              },
              {
                "zone": "body",
                "index": 8,
                "text": "She also practices patience: other people may work to a different timeline.",
                "start_ms": 44340,
                "end_ms": 49540
              },
              {
                "zone": "body",
                "index": 9,
                "text": "This is routine work; an immediate danger must not wait just so a task list can be finished.",
                "start_ms": 49840,
                "end_ms": 56800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Care for yourself, prioritize work and seek support when needed.",
                "start_ms": 57100,
                "end_ms": 62500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-stress-time.fil.9674bc330119.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9674bc3301197ec35246e3c06f13bbec7f865dc2bc32b8863ae92db98901f58b",
            "sha256": "b08293a46a660e5af6facd7ea63a2fe2723f5021b28ea3a5b169d6ff4dc54e53",
            "duration_seconds": 71.993,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pamahalaan ang stress at oras",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang **stress management** ay pagpapanatiling kalmado at tutok sa gitna ng tensyon.",
                "start_ms": 3460,
                "end_ms": 9500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Napapansin ni Malou na nagmamadali siya.",
                "start_ms": 9800,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Humihinto siya sandali, umiinom ng tubig at inaayos ang susunod na hakbang.",
                "start_ms": 13380,
                "end_ms": 19380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Inaalagaan niya ang sarili at humihingi ng suporta kung kailangan.",
                "start_ms": 19680,
                "end_ms": 24760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi ito pangakong mawawala ang lahat ng stress, at hindi kasalanan ng isang tao ang sobrang bigat ng trabaho.",
                "start_ms": 25060,
                "end_ms": 32140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang **time management** ay pag-una sa mahalagang gawain upang matapos sa takdang oras.",
                "start_ms": 32440,
                "end_ms": 38840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Tinitingnan niya ang mga napagkasunduang oras, inuuna ang mga paanyaya, at naglalaan ng oras sa paghahanda sa pulong.",
                "start_ms": 39140,
                "end_ms": 47820
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Tinatapos niya ang isang gawain bago lumipat sa susunod.",
                "start_ms": 48120,
                "end_ms": 52560
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Matiyaga rin siya: maaaring iba ang oras ng ibang tao.",
                "start_ms": 52860,
                "end_ms": 57500
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Halimbawa ito ng karaniwang trabaho; ang agarang panganib ay hindi ipinagpapaliban para lang matapos ang listahan.",
                "start_ms": 57800,
                "end_ms": 65480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alagaan ang sarili, unahin ang gawain at humingi ng suporta kung kailangan.",
                "start_ms": 65780,
                "end_ms": 71940
              }
            ]
          }
        },
        "self-trust-honesty": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-trust-honesty.en.3b131ceb511d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3b131ceb511dfbfdcba0b68f355402e5b6b193434d79278904fba13cbba84038",
            "sha256": "c98fe104f978825a9c2626b1f2786323dedd9daecdbb0e9ce8bc5baeb177ea12",
            "duration_seconds": 63.66,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Trustworthy, honest and careful",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Being **trustworthy** means holding to principles, valuing the work and following moral standards.",
                "start_ms": 3740,
                "end_ms": 10540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou does not change an agreed process simply to appear faster.",
                "start_ms": 10840,
                "end_ms": 15640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She protects information entrusted to her and uses it only for an appropriate task.",
                "start_ms": 15940,
                "end_ms": 21980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Being **honest and careful** means considering what you say and how you treat others.",
                "start_ms": 22280,
                "end_ms": 28480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She says, “Twenty invitations are ready; five remain.”",
                "start_ms": 28780,
                "end_ms": 32860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She does not claim that everything is complete.",
                "start_ms": 33160,
                "end_ms": 36760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Before speaking, she checks whether the message is accurate, necessary and respectful.",
                "start_ms": 37060,
                "end_ms": 42500
              },
              {
                "zone": "body",
                "index": 7,
                "text": "A colleague’s private reason is not needed to explain unfinished work.",
                "start_ms": 42800,
                "end_ms": 47440
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Reliability concerns delivering service; trustworthiness concerns principles; honesty and care are shown in accurate, respectful words and actions.",
                "start_ms": 47740,
                "end_ms": 59740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Report the true result and speak respectfully.",
                "start_ms": 60040,
                "end_ms": 63600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-self-management/self-trust-honesty.fil.2181560151a5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2181560151a554511dd82d1645ab46bd8ef83440eb4aa77f364b52141cc9f504",
            "sha256": "4eaa5eec382887953eba3d39b5981a5289e5327070ab7478ce51e8dbddadd87e",
            "duration_seconds": 78.315,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mapagkakatiwalaan, matapat at maingat",
                "start_ms": 0,
                "end_ms": 4600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang **mapagkakatiwalaan** ay may prinsipyo, pagpapahalaga sa trabaho at pamantayang moral.",
                "start_ms": 4900,
                "end_ms": 12220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi pinapalitan ni Malou ang napagkasunduang proseso para lamang magmukhang mabilis.",
                "start_ms": 12520,
                "end_ms": 18640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iniingatan niya ang impormasyong ipinagkatiwala sa kanya at ginagamit lamang sa angkop na gawain.",
                "start_ms": 18940,
                "end_ms": 26740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang **matapat at maingat** ay maalalahanin sa sinasabi at sa pagtrato sa iba.",
                "start_ms": 27040,
                "end_ms": 33640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sinasabi niya, “Handa na ang dalawampung paanyaya; may lima pang natitira.”",
                "start_ms": 33940,
                "end_ms": 39300
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya sinasabing tapos na ang lahat.",
                "start_ms": 39600,
                "end_ms": 42240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Bago magsalita, iniisip niya kung tama, kailangan at magalang ang mensahe.",
                "start_ms": 42540,
                "end_ms": 49260
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi kailangan ang pribadong dahilan ng kasamahan upang ipaliwanag ang natitirang gawain.",
                "start_ms": 49560,
                "end_ms": 55760
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Ang pagiging maaasahan ay tungkol sa paghahatid ng serbisyo; ang pagiging mapagkakatiwalaan ay tungkol sa prinsipyo; ang pagiging matapat at maingat ay makikita sa tumpak at magalang na salita at kilos.",
                "start_ms": 56060,
                "end_ms": 72780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iulat ang totoong resulta at magsalita nang may paggalang.",
                "start_ms": 73080,
                "end_ms": 78240
              }
            ]
          }
        }
      }
    },
    "bhw-service-provider": {
      "module": "01-tungkulin-ng-bhw",
      "sections": {
        "boundaries": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/boundaries.en.34608082aba6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "34608082aba6033d5ca35877af862f3a990bd759b8dffa8f21dea24377d01a7b",
            "sha256": "6574581204d045ae171f216e1fd8c44a72899c99a0e11fa761dbd5b0320b4d4d",
            "duration_seconds": 39.837,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Know the limits of your role",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Examples of initial services include interviewing, taking vital signs, recording, preparing a household profile, and first aid.",
                "start_ms": 2740,
                "end_ms": 12820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Perform only tasks covered by your training, local policy, and required supervision.",
                "start_ms": 13120,
                "end_ms": 19720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This lesson does not teach measurement, first aid, or treatment.",
                "start_ms": 20020,
                "end_ms": 25140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If a request is beyond your scope or you are unsure, seek guidance from the midwife or health team.",
                "start_ms": 25440,
                "end_ms": 32520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Initial services are examples; follow training, local policy, and supervision.",
                "start_ms": 32820,
                "end_ms": 39780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/boundaries.fil.5bf801006391.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5bf801006391dc1c32e5122bb5fbc27b024f97a261671c0905b7e1d5f86a57bc",
            "sha256": "035dfe532d2c38823a77f4cf00e96192d337fca779e8f4e0032707732bbadede",
            "duration_seconds": 44.199,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Alamin ang saklaw ng sariling gawain",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kabilang sa mga halimbawa ng paunang serbisyo ang pakikipanayam, pagsukat ng vital signs, pagtatala, paggawa ng household profile, at paunang lunas.",
                "start_ms": 3060,
                "end_ms": 16220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gawin lamang ang saklaw ng iyong pagsasanay, lokal na patakaran, at kinakailangang pangangasiwa.",
                "start_ms": 16520,
                "end_ms": 23440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi itinuturo ng araling ito ang pagsukat, paunang lunas, o paggamot.",
                "start_ms": 23740,
                "end_ms": 29940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung lampas sa saklaw o hindi ka tiyak, humingi ng gabay sa midwife o health team.",
                "start_ms": 30240,
                "end_ms": 36480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mga halimbawa lamang ang paunang serbisyo; sundin ang pagsasanay, lokal na patakaran, at pangangasiwa.",
                "start_ms": 36780,
                "end_ms": 44140
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/check.en.973553dccdfd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "973553dccdfd8b0525315ad2bf21a2b4c6dfb0adaade6214c98172a6c60f25af",
            "sha256": "9832b5b73d60d3b9a980aaea99707438571043c120772663c8162a06ea58cb44",
            "duration_seconds": 20.898,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply your learning",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Aling Nena asks Riza what medicine to give her child.",
                "start_ms": 2020,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Giving that advice is outside Riza's training.",
                "start_ms": 6600,
                "end_ms": 10400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What is her best response?",
                "start_ms": 10700,
                "end_ms": 13220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen, stay within scope, guide, and follow through with the health team.",
                "start_ms": 13520,
                "end_ms": 20840
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/check.fil.3fe089935a49.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3fe089935a490b36d601e75c6dc630105f7e905442dd8a2124a882a385921489",
            "sha256": "77951a909b67c6853fc8be85858e25e739318cc91073bd55ae3441c27f278338",
            "duration_seconds": 21.943,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gamitin ang natutuhan",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinanong ni Aling Nena si Riza kung anong gamot ang ibibigay sa anak niya.",
                "start_ms": 2540,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi saklaw ng pagsasanay ni Riza ang pagbibigay ng payong iyon.",
                "start_ms": 7280,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano ang pinakamainam niyang gawin?",
                "start_ms": 11700,
                "end_ms": 14140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig, manatili sa saklaw, gumabay, at mag-follow-up kasama ang health team.",
                "start_ms": 14440,
                "end_ms": 21880
              }
            ]
          }
        },
        "clarify-need": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/clarify-need.en.7f2a721e06a8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7f2a721e06a8f2d66411beff0acbbdcd12b4a66a4963e2a6a034029161799c7b",
            "sha256": "1ccc8a855c9709100485f50f95b79820652a0bb10a078a7f4f12315927a10ea6",
            "duration_seconds": 27.115,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen before guiding",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza asks, “What help do you need, and have you spoken with a health worker?”",
                "start_ms": 2580,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She gives Aling Nena time to explain and repeats what she understood.",
                "start_ms": 7960,
                "end_ms": 13480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She does not guess at an illness or its treatment.",
                "start_ms": 13780,
                "end_ms": 17620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Understanding the need helps the health team provide appropriate guidance.",
                "start_ms": 17920,
                "end_ms": 22920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen and clarify the need before guiding someone.",
                "start_ms": 23220,
                "end_ms": 27060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/clarify-need.fil.ea452e80432d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea452e80432d548188af2ae2550c8c0ca2de9d6328e635bda04b6e905fb566b0",
            "sha256": "2e18acdf544f3a7367bb6f8d9fdc39120588f2960d34f309b4f8a637f78e9024",
            "duration_seconds": 32,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig bago gumabay",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tinanong ni Riza: “Ano po ang kailangan ninyong tulong, at may nakausap na po ba kayong health worker?”",
                "start_ms": 2740,
                "end_ms": 10020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hinayaan niyang magpaliwanag si Aling Nena at inulit ang naunawaan niya.",
                "start_ms": 10320,
                "end_ms": 15680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi siya nanghula ng sakit o ng kailangan nitong paggamot.",
                "start_ms": 15980,
                "end_ms": 19980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang malinaw na pangangailangan ang tutulong sa health team na magbigay ng angkop na gabay.",
                "start_ms": 20280,
                "end_ms": 26560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig at linawin ang pangangailangan bago gumabay.",
                "start_ms": 26860,
                "end_ms": 31940
              }
            ]
          }
        },
        "first-contact": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/first-contact.en.14e51bd12a72.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "14e51bd12a723f82842d286d27de078c5a32b3e4dc4167be6c0a5782114d64d1",
            "sha256": "44e7700bcbca182b41b851297fff49a91dfab298c6eabf6e84ae5281cf70ce37",
            "duration_seconds": 32.131,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Riza is the first person approached",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Aling Nena approaches BHW Riza.",
                "start_ms": 3340,
                "end_ms": 6540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She wants to know whom to speak with about her child's needs.",
                "start_ms": 6840,
                "end_ms": 10840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "As part of the city or municipal primary care team, Riza assists the barangay midwife.",
                "start_ms": 11140,
                "end_ms": 17860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She may be Aling Nena's first contact, but she does not have to answer every question or provide every treatment.",
                "start_ms": 18160,
                "end_ms": 26200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A BHW may be the first contact and works with the midwife and health team.",
                "start_ms": 26500,
                "end_ms": 32060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/first-contact.fil.fce92cc4460d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fce92cc4460d9a37372887754c46caa96d87fc4deca7917d48a0303a425f1999",
            "sha256": "7e4ce5f0ba1562ed024ab4784c9338b1765c3ef015249a73c2b7007058f90d79",
            "duration_seconds": 34.038,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Si Riza ang unang nilapitan",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lumapit si Aling Nena kay BHW Riza.",
                "start_ms": 2860,
                "end_ms": 6140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gusto niyang malaman kung sino ang makakausap tungkol sa pangangailangan ng anak niya.",
                "start_ms": 6440,
                "end_ms": 12160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Bilang bahagi ng primary care team ng lungsod o munisipyo, katuwang si Riza ng midwife sa barangay.",
                "start_ms": 12460,
                "end_ms": 19620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaari siyang maging unang contact ni Aling Nena, ngunit hindi niya kailangang sagutin o gamutin ang lahat.",
                "start_ms": 19920,
                "end_ms": 27920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maaaring unang lapitan ang BHW; katuwang siya ng midwife at health team.",
                "start_ms": 28220,
                "end_ms": 33980
              }
            ]
          }
        },
        "follow-up": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/follow-up.en.7afd6f94ecc5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7afd6f94ecc509f3080973a689577d9ec21880c5c9f817ac9fa60812875ba152",
            "sha256": "61aa3910e31d351995b22047238b7be78005bf77ec52f209c88c6dc332eb90ab",
            "duration_seconds": 31.556,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Follow through with the health team",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Helping does not end with directions.",
                "start_ms": 2620,
                "end_ms": 5580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Following the health team's instructions, Riza confirms what to monitor or record, when to follow up, and whom to update.",
                "start_ms": 5880,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She does not invent an outcome or promise that nothing further is needed.",
                "start_ms": 15500,
                "end_ms": 20500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The next lesson covers specific records and forms.",
                "start_ms": 20800,
                "end_ms": 25240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm what to report, when, and to whom under the health team’s instructions.",
                "start_ms": 25540,
                "end_ms": 31500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/follow-up.fil.5e0d5b82c363.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5e0d5b82c363d0b681b51cbc6f6b19b49dd14e635381f3acf273095f8ad3bb35",
            "sha256": "c4e709768cbe8ede9c36c90675f0a4736b1577137000de69ba307112ec334010",
            "duration_seconds": 34.168,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mag-follow-up kasama ang health team",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi nagtatapos ang pagtulong sa pagturo kung saan pupunta.",
                "start_ms": 3180,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ayon sa tagubilin ng health team, kinumpirma ni Riza kung ano ang dapat subaybayan o itala, kailan siya magfo-follow-up, at kanino siya mag-uulat.",
                "start_ms": 7560,
                "end_ms": 17240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi siya nag-imbento ng resulta o nangako na wala nang kailangang gawin.",
                "start_ms": 17540,
                "end_ms": 21860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tatalakayin sa susunod na aralin ang mga partikular na talaan at form.",
                "start_ms": 22160,
                "end_ms": 27440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin kung ano, kailan, at kanino mag-uulat ayon sa health team.",
                "start_ms": 27740,
                "end_ms": 34100
              }
            ]
          }
        },
        "guide": {
          "en": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/guide.en.83645d1c5f43.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "83645d1c5f43fc8206929d3c024dfb6b88ce45e965dd1973f9a5f340768721d9",
            "sha256": "52e593b2941f334b48f8758116fd39ca2c71f5e919dde45ffab4001c2c2d2287",
            "duration_seconds": 37.538,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Give a clear next step",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Riza confirms which health worker or facility Aling Nena should approach under local arrangements.",
                "start_ms": 2660,
                "end_ms": 9300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She explains whom to contact and how to get there.",
                "start_ms": 9600,
                "end_ms": 13280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She might say, “I will check with the health team who can speak with you and how you can reach them.”",
                "start_ms": 13580,
                "end_ms": 20100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She checks that Aling Nena understands the next step.",
                "start_ms": 20400,
                "end_ms": 24080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Follow local referral and emergency procedures when applicable; there is no single route for every place or situation.",
                "start_ms": 24380,
                "end_ms": 32620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm whom to approach and explain a clear next step.",
                "start_ms": 32920,
                "end_ms": 37480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/01-tungkulin-ng-bhw/bhw-service-provider/guide.fil.7167d92a9680.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7167d92a96800091eac42577466695cb28f79bc1d087316d6a31f8d767bfcd86",
            "sha256": "bd3e2f30bbce9dc053d4e2c264f4006b07e09f28e00fc55bd573f53c7fb2fdd5",
            "duration_seconds": 45.505,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sabihin ang malinaw na susunod na hakbang",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kinumpirma ni Riza kung aling health worker o pasilidad ang angkop lapitan ayon sa lokal na kaayusan.",
                "start_ms": 3340,
                "end_ms": 11180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinaliwanag niya kay Aling Nena kung sino ang kakausapin at paano makakarating doon.",
                "start_ms": 11480,
                "end_ms": 17440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaari niyang sabihin: “Titingnan ko po sa health team kung sino ang maaari ninyong makausap at kung paano kayo makakapunta.”",
                "start_ms": 17740,
                "end_ms": 26460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tiniyak niyang naunawaan ni Aling Nena ang susunod na hakbang.",
                "start_ms": 26760,
                "end_ms": 30720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sundin ang lokal na referral at emergency procedures kapag naaangkop; hindi iisa ang ruta sa lahat ng lugar o sitwasyon.",
                "start_ms": 31020,
                "end_ms": 39140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin kung sino ang lalapitan at ipaliwanag ang malinaw na susunod na hakbang.",
                "start_ms": 39440,
                "end_ms": 45440
              }
            ]
          }
        }
      }
    },
    "bhw-teamwork": {
      "module": "05-bhw-at-barangay",
      "sections": {
        "section-8": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/section-8.en.b7f01452d6cc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b7f01452d6cc178b5ae80de21dc88f1a9c6ce08d41ebc3c1514c5d963f20cedc",
            "sha256": "51717c158bfcd8bce978c643cc1596c44bc53ae7849ea3a46396eee2f4352aa2",
            "duration_seconds": 49.528,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One purpose, clear teamwork",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this fictional situation, Malou and two fellow BHWs are preparing invitations for an agreed outreach activity.",
                "start_ms": 3580,
                "end_ms": 12380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The purok and time are assigned, but it is not yet clear who will prepare the invitations or who will report completion.",
                "start_ms": 12680,
                "end_ms": 20960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Saying everyone will help is not enough.",
                "start_ms": 21260,
                "end_ms": 24020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Good teamwork uses a shared purpose, clear roles, early communication, openness to feedback and respectful relationships.",
                "start_ms": 24320,
                "end_ms": 33800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "These help the team carry out its work for community health.",
                "start_ms": 34100,
                "end_ms": 37700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Cooperation does not grant authority to make clinical decisions or share confidential information.",
                "start_ms": 38000,
                "end_ms": 44920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Explain the purpose and clarify your contribution and limits.",
                "start_ms": 45220,
                "end_ms": 49460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/section-8.fil.e78cf986210f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e78cf986210ff569db32dd9cfa70c4f734b14ea71aac9677bef4bd9fd2615878",
            "sha256": "52b1ec341e9bbb1310b416d7d215ed0da2d5ea67baa698a5e3dbd3726fc0c605",
            "duration_seconds": 62.72,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang layunin, malinaw na pagtutulungan",
                "start_ms": 0,
                "end_ms": 3720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na sitwasyon, naghahanda si Malou at dalawang kapwa BHW ng paanyaya para sa napagkasunduang outreach.",
                "start_ms": 4020,
                "end_ms": 14380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May nakatalagang purok at oras, ngunit hindi pa malinaw kung sino ang maghahanda ng mga paanyaya at sino ang magbabalita kapag tapos na.",
                "start_ms": 14680,
                "end_ms": 25000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi sapat ang sabihing tutulong ang lahat.",
                "start_ms": 25300,
                "end_ms": 28540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang mabuting pagtutulungan ay may iisang layunin, malinaw na tungkulin, maagang pag-uusap, bukas na pagtanggap sa puna, at magalang na ugnayan.",
                "start_ms": 28840,
                "end_ms": 41040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ginagamit ang mga ito upang maihatid nang maayos ang gawain para sa kalusugan ng komunidad.",
                "start_ms": 41340,
                "end_ms": 47380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang pagtutulungan ay hindi nagbibigay ng karapatang gumawa ng pasyang klinikal o magbahagi ng kumpidensiyal na impormasyon.",
                "start_ms": 47680,
                "end_ms": 57240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaliwanag ang layunin at linawin ang sariling ambag at hangganan.",
                "start_ms": 57540,
                "end_ms": 62660
              }
            ]
          }
        },
        "teamwork-application-check": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-application-check.en.eb41e9e270d8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eb41e9e270d8d06ca422da6cc67dac0f7f09e10f5e3ec555868a70ac5db7898b",
            "sha256": "158db088dfbbbecbe520effd398f910c0f115fbd2016132d1f27358feeff9780",
            "duration_seconds": 48.327,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply: a task will not be finished",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At another fictional outreach activity, Malou’s colleague cannot finish the assigned preparation.",
                "start_ms": 3700,
                "end_ms": 10540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is no immediate danger, but an assignment needs to change.",
                "start_ms": 10840,
                "end_ms": 15600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "There is still time to contact the designated supervisor.",
                "start_ms": 15900,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The colleague does not want to share her personal reason.",
                "start_ms": 20120,
                "end_ms": 23720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose the best of the three responses.",
                "start_ms": 24020,
                "end_ms": 26700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Explain how it shows clear roles, early communication and respectful teamwork.",
                "start_ms": 27000,
                "end_ms": 33440
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Then say who will accept the task, what permission must be checked and how completion will be confirmed.",
                "start_ms": 33740,
                "end_ms": 40540
              },
              {
                "zone": "body",
                "index": 7,
                "text": "You do not need to watch the optional story to answer.",
                "start_ms": 40840,
                "end_ms": 44280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Show teamwork through a specific, safe agreement.",
                "start_ms": 44580,
                "end_ms": 48260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-application-check.fil.abc2b01d061a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "abc2b01d061afdbd0bc90d2baa0c11e41c9afbe7c73208bdaacd00570d0ef325",
            "sha256": "16fa590c37f2c2c29b6964edeec4f2439384a3a3ebff124f01f68cc9b936a29a",
            "duration_seconds": 57.13,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ilapat: may hindi matatapos",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa isa pang kathang-isip na outreach, hindi matatapos ng kasama ni Malou ang nakatalagang paghahanda.",
                "start_ms": 3780,
                "end_ms": 10740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ito agarang panganib, ngunit kailangan ng pagbabago sa assignment.",
                "start_ms": 11040,
                "end_ms": 16000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May oras pa upang makipag-ugnayan sa itinalagang supervisor.",
                "start_ms": 16300,
                "end_ms": 20540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ayaw ibahagi ng kasama ang personal niyang dahilan.",
                "start_ms": 20840,
                "end_ms": 24240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin ang pinakamainam na tugon sa tatlong pagpipilian.",
                "start_ms": 24540,
                "end_ms": 28660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ipaliwanag kung paano nito naipakikita ang malinaw na tungkulin, maagang pag-uusap at magalang na pagtutulungan.",
                "start_ms": 28960,
                "end_ms": 37360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Pagkatapos, sabihin kung sino ang tatanggap sa gawain, anong pahintulot ang titiyakin, at paano malalaman na tapos na.",
                "start_ms": 37660,
                "end_ms": 46780
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi kailangan ang panonood ng opsyonal na kuwento upang sagutin ito.",
                "start_ms": 47080,
                "end_ms": 51880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipakita ang pagtutulungan sa tiyak at ligtas na kasunduan.",
                "start_ms": 52180,
                "end_ms": 57060
              }
            ]
          }
        },
        "teamwork-early-handoff": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-early-handoff.en.6ea68bfdf1bf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6ea68bfdf1bf00a6b2e45f091546bd1512edc249b0d54c4bcba65f95d1abc23c",
            "sha256": "0c8d70881ab67b622db36cd6e3d8a3b1770ab1beae9b4748adc247907eb59c88",
            "duration_seconds": 64.496,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Raise issues early, hand over clearly",
                "start_ms": 0,
                "end_ms": 3640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Before the deadline, a colleague says, “I cannot finish checking the invitations.”",
                "start_ms": 3940,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou responds, “Thank you for telling us early.",
                "start_ms": 9360,
                "end_ms": 12960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What is done and what remains?”",
                "start_ms": 13260,
                "end_ms": 16540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not demand private reasons or blame her colleague.",
                "start_ms": 16840,
                "end_ms": 21720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A handoff identifies what is done, what remains, the deadline and any permission still needed.",
                "start_ms": 22020,
                "end_ms": 29260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Changes requiring permission are checked with the designated supervisor.",
                "start_ms": 29560,
                "end_ms": 34240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The receiving person accepts and repeats the task; simply leaving a message is not enough.",
                "start_ms": 34540,
                "end_ms": 41460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Share only necessary information with an authorized recipient through an appropriate channel.",
                "start_ms": 41760,
                "end_ms": 48160
              },
              {
                "zone": "body",
                "index": 8,
                "text": "An immediate danger or serious breach is raised promptly with the appropriate contact under the local process; a peer discussion must not delay it.",
                "start_ms": 48460,
                "end_ms": 58980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Speak early and confirm that someone accepts the bounded task.",
                "start_ms": 59280,
                "end_ms": 64440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-early-handoff.fil.7b67fe858ac0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7b67fe858ac017c8fa6a966c541089928abe42b7220c1c7eabb8b919f58968c3",
            "sha256": "ba5af2cba3e1688316afb0f04d76f418188f7424f391720c41f22d81347e7499",
            "duration_seconds": 71.497,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Magsabi nang maaga, magpasa nang malinaw",
                "start_ms": 0,
                "end_ms": 4320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bago ang takdang oras, sinabi ng kasama: “Hindi ko matatapos ang pagtingin sa mga paanyaya.”",
                "start_ms": 4620,
                "end_ms": 11060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sumagot si Malou: “Salamat sa maagang pagsabi.",
                "start_ms": 11360,
                "end_ms": 16000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano na ang tapos at ano pa ang kailangan?”",
                "start_ms": 16300,
                "end_ms": 19940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi niya hinihingi ang pribadong dahilan o sinisisi ang kasama.",
                "start_ms": 20240,
                "end_ms": 25560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa paglipat ng gawain, nililinaw ang tapos, natitira, takdang oras at kailangan pang pahintulot.",
                "start_ms": 25860,
                "end_ms": 34340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tinitiyak sa itinalagang supervisor ang pagbabagong nangangailangan ng pahintulot.",
                "start_ms": 34640,
                "end_ms": 40520
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Tinatanggap at inuulit ng sasalo ang gawain; hindi sapat ang mag-iwan lang ng mensahe.",
                "start_ms": 40820,
                "end_ms": 47540
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ibinabahagi lamang ang impormasyong kailangan sa awtorisadong tatanggap gamit ang angkop na paraan.",
                "start_ms": 47840,
                "end_ms": 54960
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Ang agarang panganib o seryosong paglabag ay idinudulog kaagad sa angkop na contact ayon sa lokal na proseso; hindi kailangang hintayin ang usapang magkakasama.",
                "start_ms": 55260,
                "end_ms": 65980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maagang magsabi at tiyaking may tumanggap sa saklaw na gawain.",
                "start_ms": 66280,
                "end_ms": 71440
              }
            ]
          }
        },
        "teamwork-feedback-completion": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-feedback-completion.en.d44366c2f116.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d44366c2f116cd4cdb1784176c94195a59587885ce2ccd5ebf2b7a11dc457901",
            "sha256": "8d55de8f4a5d2ee78da6cc06006ec57e097f0e0d8bf83dadcdf6314ea5d13d04",
            "duration_seconds": 60.134,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Give feedback and confirm completion",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "After the task, Malou says, “Telling us early helped.",
                "start_ms": 3300,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Next time, let us write down who will report back.”",
                "start_ms": 8560,
                "end_ms": 11960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Her feedback names an action and a suggestion, not a personality trait.",
                "start_ms": 12260,
                "end_ms": 18300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She listens to her colleague’s explanation and asks what change would help.",
                "start_ms": 18600,
                "end_ms": 23960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The person who accepted the task reports, “The invitations were checked before ten o’clock.”",
                "start_ms": 24260,
                "end_ms": 30420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The group confirms completeness against the agreement and informs the designated contact.",
                "start_ms": 30720,
                "end_ms": 37240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "If work remains, they record the next step, responsible person and follow-up time.",
                "start_ms": 37540,
                "end_ms": 43340
              },
              {
                "zone": "body",
                "index": 7,
                "text": "A task is not complete merely because it was handed over.",
                "start_ms": 43640,
                "end_ms": 48760
              },
              {
                "zone": "body",
                "index": 8,
                "text": "The group thanks one another and offers a voluntary chance to check in socially.",
                "start_ms": 49060,
                "end_ms": 54260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm completion of the agreement; set a next step if anything remains.",
                "start_ms": 54560,
                "end_ms": 60080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-feedback-completion.fil.a1ff1c2bc47c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a1ff1c2bc47c14db8a8fe82cd08a1b8afb868147347e372434504a150b96e6f4",
            "sha256": "fc6fcb8abb9472f092bf8b8c3659348815a53222384369d79b69305545636d44",
            "duration_seconds": 63.504,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Magbigay ng puna at tiyaking tapos",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Matapos ang gawain, sinabi ni Malou: “Nakatulong ang maagang pagsabi.",
                "start_ms": 3340,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa susunod, isulat natin kung sino ang magbabalita.”",
                "start_ms": 8840,
                "end_ms": 13120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tiyak sa kilos at mungkahi ang puna, hindi sa pagkatao.",
                "start_ms": 13420,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakikinig siya sa paliwanag ng kasama at nagtatanong kung anong pagbabago ang makatutulong.",
                "start_ms": 18360,
                "end_ms": 25080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Nagbalita ang tumanggap ng gawain: “Nasuri na ang mga paanyaya bago mag-alas-diyes.”",
                "start_ms": 25380,
                "end_ms": 31700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tinitiyak ng grupo kung kumpleto ito ayon sa napagkasunduan at ipinapaalam sa itinakdang contact.",
                "start_ms": 32000,
                "end_ms": 38760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kung may natitira, itinatala ang susunod na hakbang, responsable at oras ng pagbalik.",
                "start_ms": 39060,
                "end_ms": 45820
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi itinuturing na tapos ang gawain dahil lamang naipasa na ito.",
                "start_ms": 46120,
                "end_ms": 51200
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Nagpapasalamat ang grupo at nag-aalok ng boluntaryong pagkakataong magkumustahan.",
                "start_ms": 51500,
                "end_ms": 57540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiyaking natapos ang napagkasunduan; magtakda ng susunod na hakbang kung may kulang.",
                "start_ms": 57840,
                "end_ms": 63440
              }
            ]
          }
        },
        "teamwork-five-practices": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-five-practices.en.c7fb911d43d6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c7fb911d43d683e06bef5ad8141d0b4e7f47f5fffcf91a4029eb863f34d3bb63",
            "sha256": "44bc9bfc13c5a486281be18e6ac21e6ab6c07005d6f6d2847bfbf54bbdb47b50",
            "duration_seconds": 56.163,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Five practices of a good team",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "First, clarify why you volunteered: to improve community health.",
                "start_ms": 2740,
                "end_ms": 7740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Second, clarify each member’s role and responsibility.",
                "start_ms": 8040,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Third, discuss issues affecting the work early.",
                "start_ms": 12500,
                "end_ms": 15980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Describing the effect on the task is enough; private reasons do not have to be disclosed.",
                "start_ms": 16280,
                "end_ms": 22400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Fourth, listen to feedback from colleagues and the community and use specific suggestions to improve the work.",
                "start_ms": 22700,
                "end_ms": 30700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Fifth, build good relationships, including outside work, while respecting personal lives.",
                "start_ms": 31000,
                "end_ms": 38440
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Such social activities are voluntary.",
                "start_ms": 38740,
                "end_ms": 41700
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Nobody has to spend money, join a trip or take part in a close-contact physical game to prove they are a good teammate.",
                "start_ms": 42000,
                "end_ms": 50640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Keep all five practices while respecting privacy and choice.",
                "start_ms": 50940,
                "end_ms": 56100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-five-practices.fil.161ee58fc927.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "161ee58fc927879bf28b4ca0ead748790ddd725d43815ba1fe549dcb35a46920",
            "sha256": "d01127a693159c8a7d88b68d3e4774d94ad7e8942d4f18578a0c88002048cd1d",
            "duration_seconds": 63.086,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Limang gawi ng mabuting koponan",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Una, linawin kung bakit nagboluntaryo: upang mapabuti ang kalusugan ng komunidad.",
                "start_ms": 2900,
                "end_ms": 9100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ikalawa, linawin ang tungkulin at pananagutan ng bawat miyembro.",
                "start_ms": 9400,
                "end_ms": 15000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ikatlo, pag-usapan nang maaga ang isyung nakaaapekto sa trabaho.",
                "start_ms": 15300,
                "end_ms": 20780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sapat na sabihin ang epekto sa gawain; hindi kailangang ibunyag ang pribadong dahilan.",
                "start_ms": 21080,
                "end_ms": 27200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ikaapat, pakinggan ang puna ng kasamahan at komunidad at gamitin ang tiyak na mungkahi upang mapabuti ang gawain.",
                "start_ms": 27500,
                "end_ms": 36780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ikalima, bumuo ng mabuting ugnayan, maging sa labas ng trabaho, nang may paggalang sa personal na buhay.",
                "start_ms": 37080,
                "end_ms": 45200
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Boluntaryo ang ganitong pakikisalamuha.",
                "start_ms": 45500,
                "end_ms": 48380
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Walang kailangang gumastos, sumama sa biyahe, o makipagdikit sa pisikal na laro upang patunayang mabuting kasamahan.",
                "start_ms": 48680,
                "end_ms": 57320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Panatilihin ang limang gawi at igalang ang pribasiya at pagpili.",
                "start_ms": 57620,
                "end_ms": 63020
              }
            ]
          }
        },
        "teamwork-role-agreement": {
          "en": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-role-agreement.en.e4adf09b9e90.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e4adf09b9e90b0a4dfbe17d93b6c5ac17bc84b43a603b61b959880bb1f4d255c",
            "sha256": "183274e141776fb13a1cbd9319c399ab1ffd87506d1546d7ff018a7ffd74e0e0",
            "duration_seconds": 55.745,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Agree on the task",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At the table, the group clarifies the task: prepare the invitations before ten o’clock.",
                "start_ms": 2860,
                "end_ms": 8860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Malou prepares them, one colleague checks completeness and another reports to the designated contact.",
                "start_ms": 9160,
                "end_ms": 17200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Each person repeats the task and time they accepted.",
                "start_ms": 17500,
                "end_ms": 21300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This is an example of sharing an already authorized task, not a universal rule for every barangay.",
                "start_ms": 21600,
                "end_ms": 29960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A change to an official assignment must first be checked against the local process and permission from the designated supervisor.",
                "start_ms": 30260,
                "end_ms": 39100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A peer BHW cannot assign work beyond a colleague’s training or authorization.",
                "start_ms": 39400,
                "end_ms": 45240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Also clarify whom to contact if there is a difficulty.",
                "start_ms": 45540,
                "end_ms": 49420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Task, recipient, time and contact: repeat and confirm the agreement.",
                "start_ms": 49720,
                "end_ms": 55680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/05-bhw-at-barangay/bhw-teamwork/teamwork-role-agreement.fil.cb393bbe4d16.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cb393bbe4d16da14e3c8f042dec84101cd01394976c0fcaa58721ce0aef376b5",
            "sha256": "7766c2def9cc844c6324a0ca7a414e3139522d4b9454dde401b58eaf09df9f2b",
            "duration_seconds": 60.787,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pagkasunduan ang gawain",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa mesa, nililinaw ng grupo ang gawain: ihanda ang mga paanyaya bago mag-alas-diyes.",
                "start_ms": 2580,
                "end_ms": 10300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Si Malou ang naghahanda, isang kasama ang tumitingin sa pagkakakumpleto, at ang isa ang nagbabalita sa itinakdang contact.",
                "start_ms": 10600,
                "end_ms": 19600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Inuulit ng bawat isa ang tinanggap na gawain at oras.",
                "start_ms": 19900,
                "end_ms": 23900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ito ay halimbawa ng paghahati ng gawaing napahintulutan na, hindi pangkalahatang tuntunin sa lahat ng barangay.",
                "start_ms": 24200,
                "end_ms": 31560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may pagbabago sa opisyal na assignment, tinitiyak muna ang lokal na proseso at pahintulot sa itinalagang supervisor.",
                "start_ms": 31860,
                "end_ms": 40540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi maaaring magtalaga ang kapwa BHW ng gawaing lampas sa pagsasanay o awtorisasyon ng kasama.",
                "start_ms": 40840,
                "end_ms": 49000
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Linawin din kung sino ang lalapitan kapag may hadlang.",
                "start_ms": 49300,
                "end_ms": 52740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gawain, tatanggap, oras at contact: ulitin at tiyakin ang kasunduan.",
                "start_ms": 53040,
                "end_ms": 60720
              }
            ]
          }
        }
      }
    },
