    "child-cough-breathing": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/action.en.06db1d47582b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "06db1d47582b6230746ae7eb908c00aa8dcdb69a384e90186af438c08509ae6e",
            "sha256": "540f8ac91a8f3e57279a19f97877e60e90636f7642dd429f7389eb8218e75e0a",
            "duration_seconds": 30.145,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Observe breathing difficulty and ask about general danger signs.",
                "start_ms": 2540,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Arrange prompt clinical assessment when breathing is difficult.",
                "start_ms": 7680,
                "end_ms": 12400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A trained assessor uses the current age-specific chart for respiratory rate; report observations without choosing a diagnosis.",
                "start_ms": 12700,
                "end_ms": 22340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Describe breathing observations, ask about danger signs and activate the confirmed urgent assessment route.",
                "start_ms": 22640,
                "end_ms": 30080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/action.fil.7a2cdeb70a46.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7a2cdeb70a468ad580e688742e147b2b0fa93e1a17246b45c19983affcff0e03",
            "sha256": "4ee32b5276e9709e0b9550ae28173daeaafcf2ff92be372bd4e891c69ca39661",
            "duration_seconds": 33.724,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Obserbahan ang hirap sa paghinga at itanong ang danger signs.",
                "start_ms": 2500,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kapag hirap huminga, iugnay agad sa klinikal na pagsusuri.",
                "start_ms": 7960,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang sanay na assessor ang gagamit ng kasalukuyang chart ayon sa edad para sa bilis ng paghinga.",
                "start_ms": 12860,
                "end_ms": 19540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iulat ang nakita nang hindi pumipili ng diagnosis.",
                "start_ms": 19840,
                "end_ms": 24440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ilarawan ang paghinga, itanong ang danger signs, at gamitin ang kumpirmadong daan sa agarang pagsusuri.",
                "start_ms": 24740,
                "end_ms": 33660
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/check-start.en.f60f7b2b6c9c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f60f7b2b6c9c3189d8eb7171a4311b5f35a1ea823bfd579ff72fde094031006a",
            "sha256": "83aeca2d49a97ebb810b4cf01e3251755d2545be5c4d25816eab48481ea7cb8e",
            "duration_seconds": 14.289,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2700,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5280,
                "end_ms": 8840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Breathing difficulty means prompt assessment, not a promise to wait.",
                "start_ms": 9140,
                "end_ms": 14220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/check-start.fil.300c5e881aa1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "300c5e881aa19429d81d920b40b9e60b5ae3ed3c6cde23ffbfa00202b6c075c6",
            "sha256": "1ea6c269ff57fb3e7eff37c4a0c2a6ddd7f03947e161e1973035b8d5e905da7e",
            "duration_seconds": 16.091,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2700,
                "end_ms": 5180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5480,
                "end_ms": 10240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kapag hirap huminga, agad ipasuri; walang pangakong puwedeng maghintay.",
                "start_ms": 10540,
                "end_ms": 16020
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/check-transfer.en.321cde429cc9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
