              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2700,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
