            "duration_seconds": 14.367,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2980,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5320,
                "end_ms": 8760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iulat ang nakita; sa sanay na assessor ang diagnosis.",
                "start_ms": 9060,
                "end_ms": 14300
              }
