          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/example.en.284bbe972833.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "284bbe97283319117e3bcf15f4a95da08867c5ff6c1cfc9e2e59ebd35ad5dc9a",
            "sha256": "f331ad32a1e1841e167eb15123cb328bceb797c0c473a7630b572360a8ce1e64",
            "duration_seconds": 33.358,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Aya appears to struggle for breath, and her family asks to wait until tomorrow.",
                "start_ms": 1980,
                "end_ms": 7780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW describes the breathing in plain words and asks about danger signs.",
                "start_ms": 8080,
                "end_ms": 14800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She tells the family she cannot promise it can wait and arranges prompt assessment.",
                "start_ms": 15100,
                "end_ms": 20620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She reports what she saw and leaves the rate chart and diagnosis to the trained assessor.",
                "start_ms": 20920,
                "end_ms": 27160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Describe the breathing, do not promise it can wait, and arrange prompt assessment.",
                "start_ms": 27460,
                "end_ms": 33300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/example.fil.303dccd824a3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "303dccd824a301f40bb38c93f7e2be8e684a57b33f6ad72ab9b08f2ed9de495b",
            "sha256": "998b659988e3d6daf3a5b06ab8760c9bec270e2d0b3a6778c2ac72d89c5fea0a",
            "duration_seconds": 38.504,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tila hirap huminga si Aya, at gustong maghintay ng pamilya hanggang bukas.",
                "start_ms": 2420,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inilalarawan ng BHW ang paghinga sa simpleng salita at itinatanong ang danger signs.",
                "start_ms": 9120,
                "end_ms": 17160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sinasabi niyang hindi niya maipapangakong puwedeng maghintay, at agad niyang ipinasusuri si Aya.",
                "start_ms": 17460,
                "end_ms": 23940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iniuulat niya ang nakita.",
                "start_ms": 24240,
                "end_ms": 26840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang sanay na assessor ang bahala sa chart at diagnosis.",
                "start_ms": 27140,
                "end_ms": 31580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ilarawan ang paghinga, huwag ipangakong puwedeng maghintay, at agad ipasuri.",
                "start_ms": 31880,
                "end_ms": 38440
              }
            ]
          }
        },
