                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2780,
                "end_ms": 8340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 8640,
                "end_ms": 12480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ilarawan ang paghinga, itanong ang danger signs, at gamitin ang kumpirmadong daan sa agarang pagsusuri.",
                "start_ms": 12780,
                "end_ms": 21980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang paglalarawan ng paghinga at agarang referral sa bagong kaso.",
                "start_ms": 22280,
                "end_ms": 28360
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/scene.en.2ff656f3d3fa.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2ff656f3d3faa6bde1602007786131df25cd9a6f10557cb48ba4b4349e6b23bd",
