            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/scene.fil.30bf5c8bc46f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "30bf5c8bc46fe20c860716df52492bc7aabec8a633159796f457525e9c72cc5e",
            "sha256": "86cfa43a4649fdede899f13ea9d69a701b6273a12ce287785fafac34076d80f2",
            "duration_seconds": 18.416,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Umuubo at tila hirap huminga si Aya, apat na taong gulang.",
                "start_ms": 1900,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong ang pamilya kung puwedeng bukas na magpatingin.",
                "start_ms": 7280,
                "end_ms": 11280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Umuubo at tila hirap huminga si Aya; gustong maghintay ng pamilya.",
                "start_ms": 11580,
                "end_ms": 18340
              }
            ]
