        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/scope.en.62c5dc0f4912.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "62c5dc0f4912639217ad1fd091c77c112bc57aeab6d8051c69447a14720477da",
            "sha256": "1c1ddc6a0ed59739a2365fd9be3dee0898605fa317b9bfc9c41b2ba2341461bd",
            "duration_seconds": 20.219,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not use a single old temperature or respiratory-rate threshold as a stand-alone referral rule, or promise that a child with breathing difficulty can wait.",
                "start_ms": 2420,
                "end_ms": 13380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No single old number decides; no promise that breathing difficulty can wait.",
                "start_ms": 13680,
                "end_ms": 20160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-cough-breathing/scope.fil.695b6a5c897d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "695b6a5c897d964d1ef22c0243842deafe91d4c96343ee4557aedd2e48e6d665",
            "sha256": "240abf968e100f1a75728c176234681eace0dd3acf585c77fa6f726146808fef",
            "duration_seconds": 20.924,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag gawing tanging batayan ng referral ang isang lumang bilang ng temperatura o paghinga.",
                "start_ms": 3260,
                "end_ms": 9620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag ipangakong maaaring maghintay ang batang hirap huminga.",
                "start_ms": 9920,
                "end_ms": 14760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang iisang lumang bilang na batayan; walang pangakong puwedeng maghintay.",
                "start_ms": 15060,
                "end_ms": 20860
              }
            ]
          }
        }
      }
    },
    "child-danger-signs": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/action.en.c30a09e6788d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c30a09e6788db5bc2cc1b0ec752d0f445da766924981579cd750f2cea6fef763",
            "sha256": "3012f7be771f06cacd3f20fcc97b3842af5b36a11d3b399df91d1c37a0d6772e",
            "duration_seconds": 28.944,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ask about drinking, vomiting and convulsions.",
                "start_ms": 2500,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Observe alertness and current convulsions.",
                "start_ms": 6880,
                "end_ms": 10400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Any general danger sign needs urgent facility assessment; communicate the exact sign and arrange safe transfer.",
                "start_ms": 10700,
                "end_ms": 19700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identify at least one danger sign, activate urgent referral and repeat the observation in a factual handover.",
                "start_ms": 20000,
                "end_ms": 28880
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/action.fil.80b555f9bc5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "80b555f9bc5b8ea04321474f75a97ad663dde6474f236e438e13114f433aa857",
            "sha256": "070ff94018e28a06475997a0dfc3b1e65c7cee23e0309247c3f439267a2a1815",
            "duration_seconds": 31.817,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itanong ang pag-inom, pagsusuka at kombulsyon.",
                "start_ms": 2580,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tingnan ang antas ng kamalayan at kasalukuyang kombulsyon.",
                "start_ms": 7720,
                "end_ms": 12120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung may kahit isang danger sign, agad ipasuri sa pasilidad.",
                "start_ms": 12420,
                "end_ms": 16860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sabihin ang eksaktong nakita at ayusin ang ligtas na paglipat.",
                "start_ms": 17160,
                "end_ms": 22800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tukuyin ang danger sign, magpa-agarang referral, at ulitin ang aktuwal na obserbasyon sa handover.",
                "start_ms": 23100,
                "end_ms": 31740
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/check-start.en.55e83d55424e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "55e83d55424e894f9dec8b2296b9708174545aab3a3c74083a35c05fbb2d823d",
            "sha256": "3c41679fe9d67308c957f7964baefbb896d4fb9cf8e14f61371911d7f14a096d",
            "duration_seconds": 13.923,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5160,
                "end_ms": 8840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Any one danger sign means urgent facility assessment.",
                "start_ms": 9140,
                "end_ms": 13860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/check-start.fil.821fa121fa50.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "821fa121fa5068483be6c4b74b64852b2550c19b493f8aff48d4872525714d8e",
            "sha256": "65eed666af0facda47df549f9b9601b808a46bc67507806bc4083cad95ae3faa",
            "duration_seconds": 14.838,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5280,
                "end_ms": 10120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kahit isang danger sign, agad ipasuri sa pasilidad.",
                "start_ms": 10420,
                "end_ms": 14780
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/check-transfer.en.525d31534664.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "525d3153466441567e524799b124ab15062842285ccdd620d8321c72b83f5061",
            "sha256": "56436bee3b1385ab5f4d30034d1164bd4f571fbec14f41e856b72aef2ff30a97",
            "duration_seconds": 12.173,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hand over the exact signs, not an illness label.",
                "start_ms": 7940,
                "end_ms": 12100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/check-transfer.fil.56b92db4e52b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "56b92db4e52b80d848ef63a4867e38d49083b9479bc37fec23e7ebe94ad1e11d",
            "sha256": "0754d6820739fad4a22ea0d092602f1aafb8d8e53d9797c183db7abc0e23ebfb",
            "duration_seconds": 13.531,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2660,
                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5160,
                "end_ms": 8520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iulat ang eksaktong senyales, hindi diagnosis.",
                "start_ms": 8820,
                "end_ms": 13460
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/example.en.8176f768afb1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8176f768afb168be5e10375277c3926a4412abd4dfdf24b7c527f98e39ee129e",
            "sha256": "9b20406780568829bf843cfcd8158f735edc19453f2d11d7a9eeeca96099748b",
            "duration_seconds": 36.415,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Niko cannot drink, vomits everything and is unusually hard to wake.",
                "start_ms": 2020,
                "end_ms": 8300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW knows one danger sign is enough, so she does not wait for more signs or name an illness.",
                "start_ms": 8600,
                "end_ms": 16960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She arranges urgent facility assessment and safe transfer.",
                "start_ms": 17260,
                "end_ms": 22300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In the handover she states the exact signs: cannot drink, vomits everything, hard to wake.",
                "start_ms": 22600,
                "end_ms": 30360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "One danger sign is enough: refer urgently and report the exact signs.",
                "start_ms": 30660,
                "end_ms": 36340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/example.fil.44332a4a2cd4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "44332a4a2cd4de658fb9fac169f523bdd3f1e6afd4c6c9a0381be34a9c3ef964",
            "sha256": "4245ce18418dad9c70b712ad5539d1e4babee561795ea8aa62935b834013d1d1",
            "duration_seconds": 41.744,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi makainom si Niko, isinusuka ang lahat at mahirap gisingin.",
                "start_ms": 2060,
                "end_ms": 7780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Alam ng BHW na sapat ang kahit isang danger sign.",
                "start_ms": 8080,
                "end_ms": 12960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi siya naghihintay ng iba pang senyales at hindi nagbibigay ng diagnosis.",
                "start_ms": 13260,
                "end_ms": 19260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Agad niyang ipinasusuri si Niko sa pasilidad at inaayos ang ligtas na paglipat.",
                "start_ms": 19560,
                "end_ms": 25640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa handover, sinasabi niya ang eksaktong nakita: hindi makainom, isinusuka ang lahat, mahirap gisingin.",
                "start_ms": 25940,
                "end_ms": 34820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sapat ang isang danger sign: agad i-refer at iulat ang eksaktong nakita.",
                "start_ms": 35120,
                "end_ms": 41680
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/next-step.en.1e1392f29cdd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1e1392f29cddfd997d907230a9f8a323f70c8aa8d6a4f8a522c23b7506f4ca1a",
            "sha256": "e307afb2cdcf92b5589e9c02d80c13e236698a49e879ac90b3c5240910aabbaf",
            "duration_seconds": 27.063,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2740,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 8160,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Identify at least one danger sign, activate urgent referral and repeat the observation in a factual handover.",
                "start_ms": 12500,
                "end_ms": 21260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Practise naming a danger sign and a factual handover with a new case.",
                "start_ms": 21560,
                "end_ms": 27000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/next-step.fil.d794bebf5a6b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d794bebf5a6bd9eda6218742477fea5f8f44f0a5776f58eb9d9c836926077bdc",
            "sha256": "cb488ee5e2835692d69d3f69cbb15dc8d5f1242e18aff14c21c6e8955d7c2d09",
            "duration_seconds": 27.063,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2740,
                "end_ms": 8140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 8440,
                "end_ms": 12400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tukuyin ang danger sign, magpa-agarang referral, at ulitin ang aktuwal na obserbasyon sa handover.",
                "start_ms": 12700,
                "end_ms": 20860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang pagtukoy ng danger sign at factual na handover sa bagong kaso.",
                "start_ms": 21160,
                "end_ms": 27000
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/scene.en.5b745ffcba83.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5b745ffcba830851e941d4d62365b7b067a180ed814cdb87430fee6f949751d7",
            "sha256": "4de65eda59bcd1dcb025ddc95725cedb8573817f41af9e733d535671c21469f1",
            "duration_seconds": 18.286,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A caregiver says three-year-old Niko cannot drink and vomits everything.",
                "start_ms": 1940,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He is unusually difficult to wake.",
                "start_ms": 7880,
                "end_ms": 10880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: Niko, three, cannot drink, vomits everything and is hard to wake.",
                "start_ms": 11180,
                "end_ms": 18220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/scene.fil.7502ccf07d46.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7502ccf07d4626fe4929da4276019181b48f94f25ac7a97c80476ba0ace8e434",
            "sha256": "3a67fa6203bef538d2723cfabbf004380b5e7c6790a6d7b181fd6e905894ee78",
            "duration_seconds": 20.454,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sabi ng tagapag-alaga, hindi makainom si Niko, tatlong taong gulang, at isinusuka ang lahat.",
                "start_ms": 1780,
                "end_ms": 8740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mahirap siyang gisingin.",
                "start_ms": 9040,
                "end_ms": 11240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Si Niko, tatlong taon, hindi makainom, isinusuka ang lahat at mahirap gisingin.",
                "start_ms": 11540,
                "end_ms": 20380
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/scope.en.a311287ebf68.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a311287ebf68d98b8417b4e187f64ce0191325c253c525d41c8ce0e4bf41da7f",
            "sha256": "3426984d0849e8bf6cb8078d284ae52bf29258750ce1c9be9951951ce3a93622",
            "duration_seconds": 18.312,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not label the illness, wait for every sign, or give anything by mouth to a child who cannot safely swallow.",
                "start_ms": 2780,
                "end_ms": 11700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No illness label, no waiting, nothing by mouth when swallowing is unsafe.",
                "start_ms": 12000,
                "end_ms": 18240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/child-danger-signs/scope.fil.a814dd9f402e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a814dd9f402e7f1ed9613651d8a2658de59f795217defa697e8a3972dc1c677e",
            "sha256": "f75a5d7c7ac5716da1088e969a44a4530ca09130211d77394b8e7d679d58fd2e",
            "duration_seconds": 18.312,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag magbigay ng diagnosis, maghintay ng lahat ng senyales, o magpainom sa batang hindi ligtas lumunok.",
                "start_ms": 3420,
                "end_ms": 11300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang diagnosis, walang paghihintay, walang ipaiinom kung hindi ligtas lumunok.",
                "start_ms": 11600,
                "end_ms": 18240
              }
            ]
          }
        }
      }
    },
    "childhood-immunization-follow-up": {
      "module": "chapter3/05-priority-area-3-get-vaccinated",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter3/05-priority-area-3-get-vaccinated/childhood-immunization-follow-up/action.en.e85e80cc7ddb.mp3",
            "voice": "en-PH-RosaNeural",
