                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2660,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5280,
                "end_ms": 10000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong, saka sundin ang training ayon sa edad.",
                "start_ms": 10300,
                "end_ms": 15140
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/check-transfer.en.45149778dd4f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "45149778dd4f17a82df17464a990e5f2940a2986ea7ea4fb7d2d21fe8f10b20c",
            "sha256": "c29282d01a312abe7447aa6faa8488ee66aae2302a8055f798105e2a239eb22c",
            "duration_seconds": 11.807,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4720,
                "end_ms": 7520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The infant card needs the infant manikin and pathway.",
                "start_ms": 7820,
                "end_ms": 11740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/check-transfer.fil.23c2ccf21ae3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "23c2ccf21ae3ccb5c061d022903e2ab06da999629b606da929a0dfcab1eb3c95",
            "sha256": "3bf27306e63447b8a69c86c78774454b4b5ae946a182b0ea3934e25ce78e4c4d",
            "duration_seconds": 14.602,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3380,
                "end_ms": 5580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5880,
                "end_ms": 9320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Infant manikin at infant pathway ang para sa card ng sanggol.",
                "start_ms": 9620,
                "end_ms": 14540
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/example.en.9e4b04815f6e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9e4b04815f6e448fe24960fc2b05c9576d28db0b9fc866461f4b1b66750bf7cb",
            "sha256": "e58e3dcf3d671eb4ae0279b02d92ba58d512e0cdd11231d721990e93b635ba5e",
            "duration_seconds": 33.254,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea sees that the adult cannot speak or cough effectively.",
                "start_ms": 2020,
                "end_ms": 6740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "This is not a mild cough, so she calls for help at once.",
                "start_ms": 7040,
                "end_ms": 12040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On the adult manikin, she follows the pathway the trainer approved.",
                "start_ms": 12340,
                "end_ms": 17020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For the infant card, she switches to the infant manikin and the infant pathway, with no adult thrusts and no blind finger sweeps.",
                "start_ms": 17320,
                "end_ms": 27280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea calls for help, then uses the right manikin and pathway for each age.",
                "start_ms": 27580,
                "end_ms": 33180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/example.fil.8b33833ad55c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8b33833ad55c33f10c8f3df04c8e71a524653926da4ffdae8e8d58944f1ab4de",
            "sha256": "75ca33719d6ef42c37e405e814cbc479f4cadbab73b7c5608b2ccd35503e28be",
            "duration_seconds": 36.937,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nakita ni Lea na hindi makapagsalita o makaubo nang mabisa ang adult.",
                "start_ms": 1740,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ito mabisang ubo, kaya humihingi agad siya ng tulong.",
                "start_ms": 7360,
                "end_ms": 12120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa adult manikin, sinusunod niya ang pathway na aprubado ng trainer.",
                "start_ms": 12420,
                "end_ms": 17540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa card ng sanggol, lumilipat siya sa infant manikin at infant pathway.",
                "start_ms": 17840,
                "end_ms": 23880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang adult thrust at walang bulag na paghugot sa bibig.",
                "start_ms": 24180,
                "end_ms": 28860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humihingi ng tulong si Lea, saka ginagamit ang tamang manikin at pathway sa bawat edad.",
                "start_ms": 29160,
                "end_ms": 36880
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/next-step.en.31d840f17e7e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "31d840f17e7e5619a00ea079fcbf8e998173a3dc1f81f58087a4747c28359124",
            "sha256": "548ba5acdff5b0a0e622f579533be85f9b8571f77dec25b86d5c1420026bec95",
            "duration_seconds": 25.704,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2580,
                "end_ms": 7340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 7640,
                "end_ms": 11600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "With two training manikins, classify cough versus severe obstruction and show the supervised age-specific response.",
                "start_ms": 11900,
                "end_ms": 21140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Practise both age pathways on manikins with a trainer.",
                "start_ms": 21440,
                "end_ms": 25640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/next-step.fil.e6ba24443a20.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6ba24443a20ed8f8d288a46bff8a0dd6be999e2c81de03d988d2ba5d36b5189",
            "sha256": "b587c702c76e1bebe998989dc1dc15774fccb996736af1470de69808da55d4c1",
            "duration_seconds": 26.175,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2820,
                "end_ms": 8980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 9280,
                "end_ms": 13280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa dalawang manikin, ihiwalay ang mabisang ubo sa malubhang bara at ipakita ang tugon ayon sa edad.",
                "start_ms": 13580,
                "end_ms": 21460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang dalawang pathway sa manikin kasama ang trainer.",
                "start_ms": 21760,
                "end_ms": 26120
              }
            ]
          }
        },
        "scene": {
          "en": {
