              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scene.fil.cf9929b1d9dd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf9929b1d9dd16761b497c93933f205d7a3034ac8114c31ce22fc580c3963ad1",
            "sha256": "ac59b2643addb39411e253dae960494e97191517c52b77f9873576dd60751eb9",
            "duration_seconds": 17.763,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa tanghalian, hindi makapagsalita o makaubo nang mabisa ang adult.",
                "start_ms": 2860,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May hiwalay na case card ng sanggol.",
                "start_ms": 8680,
                "end_ms": 11720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Hindi makapagsalita o makaubo nang mabisa ang adult",
                "start_ms": 12020,
