        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scope.en.d6c6afb89afe.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d6c6afb89afe888d5355b4416762878e601c1fab3e3fb257571f74ab90cdbf83",
            "sha256": "cb2d8b460f47ecee12ca07b2a221fb656da6471de57762b6ec7f63374c173e85",
            "duration_seconds": 19.513,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not apply adult abdominal thrusts to an infant, use blind finger sweeps, or rehearse thrusts on a live partner.",
                "start_ms": 2780,
                "end_ms": 12100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No adult thrusts on an infant, no blind finger sweeps, no thrusts on a live partner.",
                "start_ms": 12400,
                "end_ms": 19440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/choking-response/scope.fil.2cc73918f3e3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2cc73918f3e366022ec5996ed1a04240dd8d7ca90a9eb805daac5f22582ebdd3",
            "sha256": "4db1dc835a9c7785328d812403b451084e9a2ac83a2ab05d15b62cbb6a6d6d4b",
            "duration_seconds": 20.297,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag gumamit ng abdominal thrust sa sanggol, bulag na paghugot sa bibig, o magsanay ng thrust sa totoong kapareha.",
                "start_ms": 3100,
                "end_ms": 12020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang adult thrust sa sanggol, walang bulag na paghugot sa bibig, walang thrust sa totoong kapareha.",
                "start_ms": 12320,
                "end_ms": 20240
              }
            ]
          }
        }
      }
    },
    "communication-clarify": {
      "module": "06-komunikasyon",
      "sections": {
        "barriers": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/barriers.en.e3691f5783f7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e3691f5783f70c5c289f5bafe5e0245b7a8e9641ad4c8c974e81eaed120bb02e",
            "sha256": "f7287e155ef46a445d3c4f071c3365136e17e342d59c7b579925a0a7ed9f1b0f",
            "duration_seconds": 69.486,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Clarify barriers without judging the person",
                "start_ms": 0,
                "end_ms": 3920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In Liza’s own account, nobody could watch her child that day.",
                "start_ms": 4220,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "This differs from the neighbor’s claim, “She just does not want to go.”",
                "start_ms": 8800,
                "end_ms": 13320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "That is the neighbor’s statement, not Liza’s confirmed explanation.",
                "start_ms": 13620,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“Which part of getting there was difficult?”",
                "start_ms": 18360,
                "end_ms": 20920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gibs asks.",
                "start_ms": 21220,
                "end_ms": 22860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Timing, childcare, language or access may be barriers; let the person explain.",
                "start_ms": 23160,
                "end_ms": 29720
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Do not turn possibilities into a list of expected answers.",
                "start_ms": 30020,
                "end_ms": 35020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "The Rosario case in Module 7 connects poverty, service gaps and misinformation.",
                "start_ms": 35320,
                "end_ms": 41960
              },
              {
                "zone": "body",
                "index": 8,
                "text": "First clarify what the family was told, then separately ask what prevented them from getting help.",
                "start_ms": 42260,
                "end_ms": 48660
              },
              {
                "zone": "body",
                "index": 9,
                "text": "A barrier does not prove laziness or disobedience.",
                "start_ms": 48960,
                "end_ms": 52800
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Ask only for details relevant to the agreed task.",
                "start_ms": 53100,
                "end_ms": 56860
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Do not promise childcare, transport or an appointment that has not been confirmed.",
                "start_ms": 57160,
                "end_ms": 62640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A service barrier is information; distinguish the person’s account from what others say.",
                "start_ms": 62940,
                "end_ms": 69420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/barriers.fil.443c623ebc13.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "443c623ebc13ce15383f34491ffd68f611e786f3c1f5f75b03d05361a119155d",
            "sha256": "5fdd016e9713b6f9ede1ff9ff4458e5695de8c27b9bb62c0f6acdd1770d99a2e",
            "duration_seconds": 77.087,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Hadlang ang linawin, hindi pagkatao ang husgahan",
                "start_ms": 0,
                "end_ms": 4280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa sariling kuwento ni Liza, walang magbabantay sa anak noong araw na iyon.",
                "start_ms": 4580,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iba ito sa sabi ng kapitbahay na “Ayaw lang niyang pumunta.”",
                "start_ms": 9720,
                "end_ms": 13960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sabi iyon ng kapitbahay, hindi kinumpirmang paliwanag ni Liza.",
                "start_ms": 14260,
                "end_ms": 19580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“Aling bahagi po ng pagpunta ang naging mahirap?”",
                "start_ms": 19880,
                "end_ms": 23680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "tanong ni Gibs.",
                "start_ms": 23980,
                "end_ms": 25700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Maaaring oras, pag-aalaga, wika o pag-abot sa serbisyo ang hadlang; hayaang ang kausap ang magsabi.",
                "start_ms": 26000,
                "end_ms": 34400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Huwag gawing listahan ng inaasahang sagot ang mga posibilidad.",
                "start_ms": 34700,
                "end_ms": 39020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sa kasong Rosario sa Modyul 7, magkakaugnay ang kahirapan, kakulangan sa serbisyo at maling impormasyon.",
                "start_ms": 39320,
                "end_ms": 46880
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Linawin muna kung ano ang sinabi sa pamilya, saka hiwalay na itanong kung ano ang pumigil sa pagkuha ng tulong.",
                "start_ms": 47180,
                "end_ms": 55180
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Hindi patunay ng katamaran o pagsuway ang hadlang.",
                "start_ms": 55480,
                "end_ms": 59600
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Kunin lamang ang kaugnay na detalye para sa napagkasunduang gawain.",
                "start_ms": 59900,
                "end_ms": 64740
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Huwag mangako ng childcare, sasakyan o appointment na hindi pa nakumpirma.",
                "start_ms": 65040,
                "end_ms": 70960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang hadlang sa serbisyo ay impormasyon; ihiwalay ang sariling kuwento sa sabi ng iba.",
                "start_ms": 71260,
                "end_ms": 77020
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/check.en.b0246895b0e3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b0246895b0e336b514c9da124e86a0bbbc444f05671a241d06afab4db2b1c2c9",
            "sha256": "c8feec69ad2c9ede5f51f8b013bd30141a6c8dc97af7661f5de6468f2d110740",
            "duration_seconds": 29.544,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza says, “That day did not work.”",
                "start_ms": 2180,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gibs listens with his clipboard closed.",
                "start_ms": 5400,
                "end_ms": 8520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "He does not yet know what happened; no solution has been promised.",
                "start_ms": 8820,
                "end_ms": 13140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Look at the scene, choose the next question and explain your reason before viewing feedback.",
                "start_ms": 13440,
                "end_ms": 20120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Then compare your decision with your own practice attempt.",
                "start_ms": 20420,
                "end_ms": 24100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A clear question elicits information rather than the answer we expect.",
                "start_ms": 24400,
                "end_ms": 29480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/check.fil.2bf3d8e7f9e8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2bf3d8e7f9e85a5f1be4939cb05a8ef8e1fe44db1e2616d022178346315d9428",
            "sha256": "7fb3129644195466a10d389e3c5aafedc3c87eb2dfbb0866067d4ee261fbfbcc",
            "duration_seconds": 33.332,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinabi ni Liza, “Hindi puwede noong araw na iyon.”",
                "start_ms": 2740,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nakikinig si Gibs at nakasara ang clipboard niya.",
                "start_ms": 6600,
                "end_ms": 9840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa alam ni Gibs kung ano ang nangyari; wala pang ipinangakong solusyon.",
                "start_ms": 10140,
                "end_ms": 15340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tingnan ang tagpo, piliin ang susunod na tanong at ipaliwanag ang dahilan bago tingnan ang feedback.",
                "start_ms": 15640,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos, ihambing ang pasya sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 22220,
                "end_ms": 26940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang malinaw na tanong ay naglalabas ng impormasyon, hindi ng sagot na gusto nating marinig.",
                "start_ms": 27240,
                "end_ms": 33280
              }
            ]
          }
        },
        "clarify-detail": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/clarify-detail.en.f86356902ad6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f86356902ad6814c04e63f511a767b154d894f2eb3933057aafd5c022583d954",
            "sha256": "64c2cf8e94f453d755eaf4570b4e4e9a81d0f9ca567d7fb1a97fb5e80b597dea",
            "duration_seconds": 60.761,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What does “with me” mean?",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“I had nobody with me” is still unclear to Gibs.",
                "start_ms": 3380,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Do you mean someone to travel with you?”",
                "start_ms": 7600,
                "end_ms": 10480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "he asks.",
                "start_ms": 10780,
                "end_ms": 12140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“No.",
                "start_ms": 12440,
                "end_ms": 13520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Someone to watch my child,” Liza corrects him.",
                "start_ms": 13820,
                "end_ms": 17380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Thank you for clarifying,” Gibs replies.",
                "start_ms": 17680,
                "end_ms": 20680
              },
              {
                "zone": "body",
                "index": 6,
                "text": "He does not insist on his first interpretation.",
                "start_ms": 20980,
                "end_ms": 24380
              },
              {
                "zone": "body",
                "index": 7,
                "text": "“What do you mean by with me?”",
                "start_ms": 24680,
                "end_ms": 27320
              },
              {
                "zone": "body",
                "index": 8,
                "text": "is another useful question when the meaning is uncertain.",
                "start_ms": 27620,
                "end_ms": 31860
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Ask one question at a time; do not request the date, time and reason all at once.",
                "start_ms": 32160,
                "end_ms": 38760
              },
              {
                "zone": "body",
                "index": 10,
                "text": "If relevant to the agreed task, follow with “When was that?”",
                "start_ms": 39060,
                "end_ms": 43740
              },
              {
                "zone": "body",
                "index": 11,
                "text": "or “When was your last visit?”",
                "start_ms": 44040,
                "end_ms": 46560
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Do not guess a date the person cannot remember.",
                "start_ms": 46860,
                "end_ms": 50060
              },
              {
                "zone": "body",
                "index": 13,
                "text": "In this story, first clarify who was unavailable and what their role was.",
                "start_ms": 50360,
                "end_ms": 56040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The person can correct your understanding; accept the correction.",
                "start_ms": 56340,
                "end_ms": 60700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/clarify-detail.fil.b2d7891a6757.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b2d7891a6757a40a4c9971289bcffacf61fb9a01d85f72e89a4cdee8485ef6f5",
            "sha256": "ede293f1e780a24788992fa76dc18e50fd6d4155767fb3b130691e2d2729d704",
            "duration_seconds": 61.962,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ano ang ibig sabihin ng “kasama”?",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi pa malinaw kay Gibs ang “Wala akong kasama.”",
                "start_ms": 2900,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Kasama po ba sa biyahe ang ibig ninyo?”",
                "start_ms": 6880,
                "end_ms": 9360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong niya.",
                "start_ms": 9660,
                "end_ms": 11300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“Hindi po.",
                "start_ms": 11600,
                "end_ms": 13160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Magbabantay sa anak ko,” pagwawasto ni Liza.",
                "start_ms": 13460,
                "end_ms": 17140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Salamat po sa paglilinaw,” tugon ni Gibs.",
                "start_ms": 17440,
                "end_ms": 20920
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi niya ipinilit ang unang pagkaintindi.",
                "start_ms": 21220,
                "end_ms": 24300
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Maaari ring itanong ang “Ano po ang ibig ninyong sabihin sa kasama?”",
                "start_ms": 24600,
                "end_ms": 29800
              },
              {
                "zone": "body",
                "index": 8,
                "text": "kung hindi pa tiyak ang kahulugan.",
                "start_ms": 30100,
                "end_ms": 32580
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Isa-isahin ang tanong; huwag sabay na hingin ang petsa, oras at dahilan.",
                "start_ms": 32880,
                "end_ms": 38480
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Kung kailangan sa napagkasunduang gawain, saka itanong ang “Kailan po iyon?”",
                "start_ms": 38780,
                "end_ms": 44660
              },
              {
                "zone": "body",
                "index": 11,
                "text": "o “Kailan po kayo huling nakapunta?”",
                "start_ms": 44960,
                "end_ms": 47440
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Huwag hulaan ang petsang hindi maalala.",
                "start_ms": 47740,
                "end_ms": 50580
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Sa kuwentong ito, ang kailangang linawin muna ay kung sino ang wala at ano ang papel niya.",
                "start_ms": 50880,
                "end_ms": 56440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Puwedeng iwasto ng kausap ang pagkaintindi mo; tanggapin ang pagwawasto.",
                "start_ms": 56740,
                "end_ms": 61900
              }
            ]
          }
        },
        "confirm-summary": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/confirm-summary.en.67bd44b15079.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "67bd44b150795a9a52f05c008dd54d3b67724e7c76ec394182c85bef635c6afb",
            "sha256": "634628decdd9b5cd62ed5f619cc6fba17f8480007064e5a6d5f2f257376e5da8",
            "duration_seconds": 71.706,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Offer the summary as a question",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Have I understood correctly: getting there is always difficult because nobody can watch your child?”",
                "start_ms": 2340,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gibs asks.",
                "start_ms": 9720,
                "end_ms": 11200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Not always.",
                "start_ms": 11500,
                "end_ms": 12980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Only when my sister is away,” Liza corrects him.",
                "start_ms": 13280,
                "end_ms": 17360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“When your sister is away, it is difficult to find someone to watch your child.",
                "start_ms": 17660,
                "end_ms": 22900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Is that right?”",
                "start_ms": 23200,
                "end_ms": 24360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "“Yes,” she confirms.",
                "start_ms": 24660,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Gibs removes always from his summary.",
                "start_ms": 27320,
                "end_ms": 30640
              },
              {
                "zone": "body",
                "index": 8,
                "text": "“Would you like us to check the current service hours?”",
                "start_ms": 30940,
                "end_ms": 34060
              },
              {
                "zone": "body",
                "index": 9,
                "text": "he offers.",
                "start_ms": 34360,
                "end_ms": 35680
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Liza agrees to check the hours first; she does not yet know when she can attend.",
                "start_ms": 35980,
                "end_ms": 40940
              },
              {
                "zone": "body",
                "index": 11,
                "text": "This is a confirmed next step, not a promise of an appointment or childcare.",
                "start_ms": 41240,
                "end_ms": 46960
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Return a brief relevant summary, not every private detail.",
                "start_ms": 47260,
                "end_ms": 52140
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Use information for the authorized purpose under local policy.",
                "start_ms": 52440,
                "end_ms": 57480
              },
              {
                "zone": "body",
                "index": 14,
                "text": "If immediate help is needed, follow the local process; do not delay it to finish a routine conversation.",
                "start_ms": 57780,
                "end_ms": 65140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Summarize, invite correction, check the corrected summary and confirm the next step.",
                "start_ms": 65440,
                "end_ms": 71640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/confirm-summary.fil.51a211c68383.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "51a211c68383f6f9d3fb942a96a7dc6afac9596c44927c153393a52339203394",
            "sha256": "bce036de0a858ff083494ccf6de7d243af356de81b5c6398270bfb14f5cdb5c4",
            "duration_seconds": 74.736,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ibalik ang buod bilang tanong",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Tama po ba: palaging mahirap pumunta dahil walang magbabantay?”",
                "start_ms": 2700,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "tanong ni Gibs.",
                "start_ms": 7960,
                "end_ms": 9280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Hindi palagi.",
                "start_ms": 9580,
                "end_ms": 11260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kapag wala lang ang kapatid ko,” pagwawasto ni Liza.",
                "start_ms": 11560,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“Kapag wala ang kapatid ninyo, mahirap makahanap ng magbabantay sa anak.",
                "start_ms": 15780,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tama po ba?”",
                "start_ms": 20680,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 6,
                "text": "“Opo,” kinumpirma niya.",
                "start_ms": 22220,
                "end_ms": 24340
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Tinanggal ni Gibs ang salitang palagi sa buod.",
                "start_ms": 24640,
                "end_ms": 28600
              },
              {
                "zone": "body",
                "index": 8,
                "text": "“Gusto po ba ninyong alamin natin ang kasalukuyang oras ng serbisyo?”",
                "start_ms": 28900,
                "end_ms": 33420
              },
              {
                "zone": "body",
                "index": 9,
                "text": "alok niya.",
                "start_ms": 33720,
                "end_ms": 34720
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Pumayag si Liza na alamin muna ang oras; hindi pa tiyak kung kailan siya makakapunta.",
                "start_ms": 35020,
                "end_ms": 40700
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Ito ang nakumpirmang susunod na hakbang, hindi pangako ng appointment o childcare.",
                "start_ms": 41000,
                "end_ms": 46600
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Maikling kaugnay na buod lamang ang ibalik, hindi lahat ng pribadong detalye.",
                "start_ms": 46900,
                "end_ms": 52620
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Gamitin ang impormasyon ayon sa awtorisadong layunin at lokal na patakaran.",
                "start_ms": 52920,
                "end_ms": 58120
              },
              {
                "zone": "body",
                "index": 14,
                "text": "Kung kailangan ng agarang tulong, sundin ang lokal na proseso; huwag ipagpaliban ito para tapusin ang karaniwang usapan.",
                "start_ms": 58420,
                "end_ms": 66100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ibuod, humingi ng pagwawasto, ibalik ang inayos na buod at kumpirmahin ang susunod na hakbang.",
                "start_ms": 66400,
                "end_ms": 74680
              }
            ]
          }
        },
        "open-question": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/open-question.en.fdc495469049.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fdc495469049694dd42ac462d759491c3c5bc8f506955aa91475d663e16124bd",
            "sha256": "fe75a2cca07ed42a5790b5f9a912afb363632ee62949caf56b2bb42e87f06c3c",
            "duration_seconds": 57.887,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Open first, then clarify",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs, a male BHW, talks with Liza, 29, about her missed health-center visit.",
                "start_ms": 3460,
                "end_ms": 11340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "This story is fictional.",
                "start_ms": 11640,
                "end_ms": 13560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "They have already agreed on the purpose, language and a comfortable place.",
                "start_ms": 13860,
                "end_ms": 19140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“What happened when you could not attend?”",
                "start_ms": 19440,
                "end_ms": 21920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gibs asks.",
                "start_ms": 22220,
                "end_ms": 23940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“I had nobody with me,” Liza replies.",
                "start_ms": 24240,
                "end_ms": 27680
              },
              {
                "zone": "body",
                "index": 6,
                "text": "He gives her time to finish the story.",
                "start_ms": 27980,
                "end_ms": 30740
              },
              {
                "zone": "body",
                "index": 7,
                "text": "“You mean you did not want to go?”",
                "start_ms": 31040,
                "end_ms": 33600
              },
              {
                "zone": "body",
                "index": 8,
                "text": "already assumes a motive.",
                "start_ms": 33900,
                "end_ms": 36300
              },
              {
                "zone": "body",
                "index": 9,
                "text": "An open invitation lets Liza describe events in her own words.",
                "start_ms": 36600,
                "end_ms": 41600
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Then clarify one needed detail.",
                "start_ms": 41900,
                "end_ms": 44580
              },
              {
                "zone": "body",
                "index": 11,
                "text": "A yes-or-no answer can confirm a specific detail; it does not replace listening to the story.",
                "start_ms": 44880,
                "end_ms": 51280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start with an open invitation, then ask one focused question without blame.",
                "start_ms": 51580,
                "end_ms": 57820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/open-question.fil.53654dfd9046.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "53654dfd90468ec6c9a860e65e7bf6040a62f3008d828667962fdb7db52e9538",
            "sha256": "e712cd84cb780b4548b5305a7221bdc8f98bc7b9ccff03e8fea1066682fbc09c",
            "duration_seconds": 65.097,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bukas muna, saka linawin",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Gibs, lalaking BHW, ay nakikipag-usap kay Liza, 29 anyos, tungkol sa hindi niya pagpunta sa health center.",
                "start_ms": 3300,
                "end_ms": 12900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kathang-isip ang kuwentong ito.",
                "start_ms": 13200,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Napag-usapan na nila ang layunin, wika at komportableng lugar.",
                "start_ms": 15780,
                "end_ms": 21460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“Ano po ang nangyari noong hindi kayo nakapunta?”",
                "start_ms": 21760,
                "end_ms": 24920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "tanong ni Gibs.",
                "start_ms": 25220,
                "end_ms": 26540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Wala akong kasama,” sagot ni Liza.",
                "start_ms": 26840,
                "end_ms": 30240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Nagbigay siya ng oras para matapos ang kuwento.",
                "start_ms": 30540,
                "end_ms": 33620
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ang “Ibig ninyong sabihin, ayaw ninyong pumunta?”",
                "start_ms": 33920,
                "end_ms": 37440
              },
              {
                "zone": "body",
                "index": 8,
                "text": "ay may ipinapalagay nang motibo.",
                "start_ms": 37740,
                "end_ms": 40540
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Ang bukas na paanyaya ay nagbibigay kay Liza ng pagkakataong magsabi sa sarili niyang salita.",
                "start_ms": 40840,
                "end_ms": 47120
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Saka lamang maglinaw ng isang kailangang detalye.",
                "start_ms": 47420,
                "end_ms": 50820
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Maaaring oo o hindi ang sagot kung isang tiyak na detalye ang kinukumpirma; hindi ito kapalit ng pakikinig sa kuwento.",
                "start_ms": 51120,
                "end_ms": 59080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bukas na paanyaya muna; saka isang tiyak at walang paratang na tanong.",
                "start_ms": 59380,
                "end_ms": 65020
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/practice.en.e6dbeaf8d236.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6dbeaf8d236294b2969991230bc253ab325f1489de254d0a5cfc2cc79ad28a8",
            "sha256": "5367e2f2ecc3094a9ced860e748b41aa303ff5e856b4e762dc4ff068fdd4d6a6",
            "duration_seconds": 74.606,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use fictional BHW, Liza and observer cards.",
                "start_ms": 2300,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In the first round, start with an open invitation.",
                "start_ms": 6880,
                "end_ms": 10000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Liza replies, “I have nobody with me.”",
                "start_ms": 10300,
                "end_ms": 13980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Clarify whether this means a travel companion or someone to watch her child, then ask her to check your summary.",
                "start_ms": 14280,
                "end_ms": 21840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The observer records the exact question, answer and correction; do not guess a motive.",
                "start_ms": 22140,
                "end_ms": 28700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Repeat a step that needs support before rotating roles.",
                "start_ms": 29000,
                "end_ms": 32680
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Across three rounds, everyone practices as the BHW.",
                "start_ms": 32980,
                "end_ms": 37460
              },
              {
                "zone": "body",
                "index": 7,
                "text": "In the next round, clarify an ambiguous time; in the third, distinguish the neighbor’s claim from Liza’s own answer.",
                "start_ms": 37760,
                "end_ms": 45560
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Alone, write and say the invitation, clarification and summary aloud, then use the question aid.",
                "start_ms": 45860,
                "end_ms": 53500
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Peer feedback is not a facilitator grade.",
                "start_ms": 53800,
                "end_ms": 57160
              },
              {
                "zone": "body",
                "index": 10,
                "text": "At the next authorized visit, clarify one ambiguous answer before recording it.",
                "start_ms": 57460,
                "end_ms": 63340
              },
              {
                "zone": "body",
                "index": 11,
                "text": "No real resident record or private account is uploaded for practice.",
                "start_ms": 63640,
                "end_ms": 68680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A clear question elicits information rather than the answer we expect.",
                "start_ms": 68980,
                "end_ms": 74540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-clarify/practice.fil.7b420c1a80c4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7b420c1a80c4e8785f6d6a304414a772719cc864c4c296294c7694553dc7513d",
            "sha256": "197f1fe95af45abaff04bce29c334173d039f881be2bc21dfcf688773d58d0f3",
            "duration_seconds": 82.129,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamitin ang kathang-isip na cards para sa BHW, Liza at tagamasid.",
                "start_ms": 2940,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa unang round, magsimula sa bukas na paanyaya.",
                "start_ms": 10120,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sasagot si Liza ng “Wala akong kasama.”",
                "start_ms": 14460,
                "end_ms": 17900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Linawin kung kasama sa biyahe o magbabantay sa anak ang ibig sabihin, saka ipasuri ang iyong buod.",
                "start_ms": 18200,
                "end_ms": 25840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itala ng tagamasid ang eksaktong tanong, sagot at pagwawasto; huwag hulaan ang motibo.",
                "start_ms": 26140,
                "end_ms": 32100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ulitin ang hakbang na nangangailangan ng tulong bago magpalit ng papel.",
                "start_ms": 32400,
                "end_ms": 36880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Sa tatlong round, lahat ay susubok bilang BHW.",
                "start_ms": 37180,
                "end_ms": 41300
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sa susunod na round, linawin ang malabong oras; sa ikatlo, ihiwalay ang sabi ng kapitbahay sa sariling sagot ni Liza.",
                "start_ms": 41600,
                "end_ms": 51280
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung mag-isa, isulat at sabihin nang malakas ang paanyaya, paglilinaw at buod, saka gamitin ang question aid.",
                "start_ms": 51580,
                "end_ms": 59500
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Hindi grado ng facilitator ang peer feedback.",
                "start_ms": 59800,
                "end_ms": 63360
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Sa susunod na awtorisadong pagbisita, maglinaw ng isang malabong sagot bago magtala.",
                "start_ms": 63660,
                "end_ms": 70460
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Walang tunay na resident record o pribadong kuwentong ia-upload sa pagsasanay.",
                "start_ms": 70760,
                "end_ms": 75960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang malinaw na tanong ay naglalabas ng impormasyon, hindi ng sagot na gusto nating marinig.",
                "start_ms": 76260,
                "end_ms": 82060
              }
            ]
          }
        }
      }
    },
    "communication-explain": {
      "module": "06-komunikasyon",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/check.en.bd8cb5ca7ba6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bd8cb5ca7ba6c27c91af97298be655dc10c757b555114f07fb78659ba7b32f62",
            "sha256": "fb88de14fa146664b91b5068a6c586022e0bd7f43681d8f3803f8021d8061271",
            "duration_seconds": 44.513,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose a respectful repair",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs and Liza agree to ask the midwife about scheduling first.",
                "start_ms": 2740,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is no confirmed appointment.",
                "start_ms": 7720,
                "end_ms": 10360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "During teach-back, Liza says, “I have an appointment tomorrow.”",
                "start_ms": 10660,
                "end_ms": 15100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "That differs from Gibs’s explanation.",
                "start_ms": 15400,
                "end_ms": 18080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "What should he do next?",
                "start_ms": 18380,
                "end_ms": 19980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Choose an answer and explain why.",
                "start_ms": 20280,
                "end_ms": 22880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "After choosing, read all three rationales and the conversation’s ending.",
                "start_ms": 23180,
                "end_ms": 28260
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Compare it with your practice.",
                "start_ms": 28560,
                "end_ms": 30360
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Answering the check or watching the optional story does not replace an actual demonstration.",
                "start_ms": 30660,
                "end_ms": 36500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "When understanding differs, repair your explanation and check again. An unclear message is not the person’s fault.",
                "start_ms": 36800,
                "end_ms": 44440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/check.fil.94c2dd83cdc5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "94c2dd83cdc511e0d0613a0c5aa169c80b71e264594ae848555294170d3271fb",
            "sha256": "dd96ef5a67626f407234903936ce5106020ae2de8b15dd4f636f18cd2a23e2d6",
            "duration_seconds": 51.461,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang magalang na repair",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Magkasundo sina Gibs at Liza na magtatanong muna sa midwife tungkol sa iskedyul.",
                "start_ms": 2540,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Wala pang kumpirmadong appointment.",
                "start_ms": 8800,
                "end_ms": 11520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa teach-back, sabi ni Liza, “May appointment na ako bukas.”",
                "start_ms": 11820,
                "end_ms": 16100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi iyon ang planong ipinaliwanag ni Gibs.",
                "start_ms": 16400,
                "end_ms": 19440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ano ang susunod niyang gagawin?",
                "start_ms": 19740,
                "end_ms": 21740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Piliin ang sagot at sabihin kung bakit.",
                "start_ms": 22040,
                "end_ms": 25200
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Pagkatapos pumili, basahin ang paliwanag ng lahat ng tatlong sagot at ang pagtatapos ng usapan.",
                "start_ms": 25500,
                "end_ms": 32300
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ihambing sa ginawa mo sa pagsasanay.",
                "start_ms": 32600,
                "end_ms": 35240
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi kapalit ng aktuwal na demonstrasyon ang pagsagot sa check o panonood ng opsyonal na kuwento.",
                "start_ms": 35540,
                "end_ms": 42180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kapag iba ang pagkaunawa, ayusin ang sariling paliwanag at mag-check muli. Hindi kasalanan ng kausap ang hindi malinaw na mensahe.",
                "start_ms": 42480,
                "end_ms": 51400
              }
            ]
          }
        },
        "distress": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/distress.en.82ba094ca46c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "82ba094ca46cb9b77779c93201aa797e2f727394b764f4b1c9fac4681be7a431",
            "sha256": "77869728277f0be8a8a9be6b2277c80dcdf5c9c0d52e2db670a8624e4610e075",
            "duration_seconds": 92.264,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen without diagnosing",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ben, 37, says he has felt low for several weeks.",
                "start_ms": 2300,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gibs might ask, “Thank you for telling me.",
                "start_ms": 7320,
                "end_ms": 10080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "What feels hardest right now?”",
                "start_ms": 10380,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ben may choose not to share details.",
                "start_ms": 12840,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ask whether the setting is comfortable; do not infer a diagnosis from silence, posture or looking away.",
                "start_ms": 16020,
                "end_ms": 23420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“I want someone to talk to, but I do not know who,” Ben says.",
                "start_ms": 23720,
                "end_ms": 28640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "“I can listen.",
                "start_ms": 28940,
                "end_ms": 30300
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If you want, I can help identify a qualified health professional through the local health team,” Gibs replies.",
                "start_ms": 30600,
                "end_ms": 37520
              },
              {
                "zone": "body",
                "index": 8,
                "text": "He does not say “just think happy thoughts,” diagnose, or choose treatment.",
                "start_ms": 37820,
                "end_ms": 43380
              },
              {
                "zone": "body",
                "index": 9,
                "text": "In rehearsal, the contact’s name and availability are unknown.",
                "start_ms": 43680,
                "end_ms": 48360
              },
              {
                "zone": "body",
                "index": 10,
                "text": "“I do not have a confirmed time yet.",
                "start_ms": 48660,
                "end_ms": 51340
              },
              {
                "zone": "body",
                "index": 11,
                "text": "How do you understand our first step?”",
                "start_ms": 51640,
                "end_ms": 54120
              },
              {
                "zone": "body",
                "index": 12,
                "text": "“Find out the contact first; this is not an appointment yet,” Ben replies.",
                "start_ms": 54420,
                "end_ms": 59220
              },
              {
                "zone": "body",
                "index": 13,
                "text": "If the meaning differs, explain another way and ask again.",
                "start_ms": 59520,
                "end_ms": 63640
              },
              {
                "zone": "body",
                "index": 14,
                "text": "In a real immediate danger to safety, seek help at once according to verified local emergency procedures; do not delay for an ordinary interview or report.",
                "start_ms": 63940,
                "end_ms": 75580
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Do not invent a number or a universal protocol.",
                "start_ms": 75880,
                "end_ms": 79920
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Do not promise to conceal danger from people who need to help.",
                "start_ms": 80220,
                "end_ms": 84340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Listen and identify a qualified contact. In immediate danger, do not delay help for an ordinary interview.",
                "start_ms": 84640,
                "end_ms": 92200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/distress.fil.7bd8544664e4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7bd8544664e423753ea1efaf17e54927632b4d528dc9eab69d960e95094d324e",
            "sha256": "b2c7d1428bd080816160e3b4bb45a8741d72244328df9ac6908a123c9698a4c1",
            "duration_seconds": 102.635,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig nang walang diagnosis",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Ben, 37, ay nagsasabing ilang linggo na siyang malungkot.",
                "start_ms": 3180,
                "end_ms": 7940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Salamat sa pagsabi.",
                "start_ms": 8240,
                "end_ms": 9960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ano ang pinakamabigat para sa iyo ngayon?”",
                "start_ms": 10260,
                "end_ms": 13220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "ang maaaring itanong ni Gibs.",
                "start_ms": 13520,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Maaari ring piliin ni Ben na huwag ikuwento ang detalye.",
                "start_ms": 16180,
                "end_ms": 19620
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tanungin kung komportable ang lugar; huwag maghinuha ng diagnosis sa katahimikan, postura o pag-iwas ng tingin.",
                "start_ms": 19920,
                "end_ms": 28280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "“Gusto kong may makausap, pero hindi ko alam kung sino,” sabi ni Ben.",
                "start_ms": 28580,
                "end_ms": 33540
              },
              {
                "zone": "body",
                "index": 7,
                "text": "“Makikinig ako.",
                "start_ms": 33840,
                "end_ms": 35360
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung gusto mo, tutulong akong alamin ang kwalipikadong health professional sa lokal na health team,” tugon ni Gibs.",
                "start_ms": 35660,
                "end_ms": 42780
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Hindi niya sasabihing “isipin mo lang ang masasaya,” magbibigay ng diagnosis, o pipili ng paggamot.",
                "start_ms": 43080,
                "end_ms": 50320
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Sa pagsasanay, hindi pa alam ang pangalan at availability ng contact.",
                "start_ms": 50620,
                "end_ms": 56020
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“Wala pa akong kumpirmadong oras.",
                "start_ms": 56320,
                "end_ms": 58840
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Ano muna ang pagkaunawa mo sa hakbang natin?”",
                "start_ms": 59140,
                "end_ms": 62100
              },
              {
                "zone": "body",
                "index": 13,
                "text": "“Aalamin muna ang contact; hindi pa ito appointment,” sagot ni Ben.",
                "start_ms": 62400,
                "end_ms": 67320
              },
              {
                "zone": "body",
                "index": 14,
                "text": "Kung iba ang pagkaunawa, magpaliwanag sa ibang paraan at itanong muli.",
                "start_ms": 67620,
                "end_ms": 72540
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Sa tunay na agarang panganib sa kaligtasan, humingi kaagad ng tulong ayon sa natiyak na lokal na emergency procedure; huwag ipagpaliban dahil sa ordinaryong interview o report.",
                "start_ms": 72840,
                "end_ms": 83880
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Walang imbentong numero o iisang protocol para sa lahat.",
                "start_ms": 84180,
                "end_ms": 88420
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Huwag mangakong ililihim ang panganib sa mga taong kailangang tumulong.",
                "start_ms": 88720,
                "end_ms": 94000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makinig at alamin ang kwalipikadong contact. Sa agarang panganib, huwag antalahin ang tulong para sa ordinaryong interview.",
                "start_ms": 94300,
                "end_ms": 102580
              }
            ]
          }
        },
        "family-planning": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/family-planning.en.fbcd8d38276a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fbcd8d38276af8730ecd515f55817b3ad42c6ecfcaf0e78a0b101dd143c20f60",
            "sha256": "006497b85f15cb59367ef051e73ddf7670763662d435976bf5ade8c5228f624f",
            "duration_seconds": 99.527,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Room for questions and choice",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Jo, 24, is worried about something she heard about family planning.",
                "start_ms": 2940,
                "end_ms": 8060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“What specifically worries you?”",
                "start_ms": 8360,
                "end_ms": 10720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gibs asks.",
                "start_ms": 11020,
                "end_ms": 12380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "He listens without mocking her belief.",
                "start_ms": 12680,
                "end_ms": 15640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“I do not want someone choosing for me,” Jo says.",
                "start_ms": 15940,
                "end_ms": 19700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“You decide; you can raise your concern with a qualified provider,” Gibs replies.",
                "start_ms": 20000,
                "end_ms": 25600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Use only general information from approved materials and your own training.",
                "start_ms": 25900,
                "end_ms": 31260
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Choosing an appropriate method and clinical counseling are discussions between Jo and a midwife or qualified provider.",
                "start_ms": 31560,
                "end_ms": 39840
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Gibs does not select a method or prescribe.",
                "start_ms": 40140,
                "end_ms": 43780
              },
              {
                "zone": "body",
                "index": 9,
                "text": "He does not pressure Jo to decide or disclose private details.",
                "start_ms": 44080,
                "end_ms": 49040
              },
              {
                "zone": "body",
                "index": 10,
                "text": "In this fictional rehearsal, the contact’s name and hours are unknown.",
                "start_ms": 49340,
                "end_ms": 54460
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“If you want, I will ask the health team for the appropriate contact and how to request a private conversation.",
                "start_ms": 54760,
                "end_ms": 61120
              },
              {
                "zone": "body",
                "index": 12,
                "text": "The schedule is not confirmed.",
                "start_ms": 61420,
                "end_ms": 63660
              },
              {
                "zone": "body",
                "index": 13,
                "text": "To check that I explained clearly, what is the first step?”",
                "start_ms": 63960,
                "end_ms": 67360
              },
              {
                "zone": "body",
                "index": 14,
                "text": "“Find out the contact first; not choose a method now,” Jo replies.",
                "start_ms": 67660,
                "end_ms": 72340
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Before an actual visit, verify the contact, BHW role and arrangements for a private conversation with the local health team.",
                "start_ms": 72640,
                "end_ms": 81240
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Explain approved information use and who needs to receive it under local policy.",
                "start_ms": 81540,
                "end_ms": 86940
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Do not promise absolute secrecy.",
                "start_ms": 87240,
                "end_ms": 90360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hear the concern. Verify the contact with the health team. Respect choice; the BHW does not select the method.",
                "start_ms": 90660,
                "end_ms": 99460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/family-planning.fil.159d9661b299.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "159d9661b299027a900c9db950c6e06f3d519053eb87e8e40855dc52efd7f4d3",
            "sha256": "eef2044f9d310c5c8387955acc278579db9a924feb911d098e71144b612a241d",
            "duration_seconds": 110.393,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "May pagpili at puwang sa tanong",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Jo, 24, ay may takot sa narinig tungkol sa family planning.",
                "start_ms": 2980,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Ano ang partikular na ikinababahala mo?”",
                "start_ms": 8720,
                "end_ms": 11960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong ni Gibs.",
                "start_ms": 12260,
                "end_ms": 13980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakikinig siya nang hindi pinagtatawanan ang paniniwala.",
                "start_ms": 14280,
                "end_ms": 18320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“Ayokong may pumili para sa akin,” sabi ni Jo.",
                "start_ms": 18620,
                "end_ms": 22380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Ikaw ang magpapasya; puwede mong itanong ang concern sa kwalipikadong provider,” tugon ni Gibs.",
                "start_ms": 22680,
                "end_ms": 29640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Gamitin lamang ang pangkalahatang impormasyon mula sa aprubadong materyal at sariling pagsasanay.",
                "start_ms": 29940,
                "end_ms": 36580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ang pagpili ng angkop na paraan at klinikal na counseling ay usapan ni Jo at ng midwife o kwalipikadong provider.",
                "start_ms": 36880,
                "end_ms": 45200
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi pipili o magrereseta si Gibs.",
                "start_ms": 45500,
                "end_ms": 49020
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Hindi niya pipilitin si Jo na magpasya o magsabi ng pribadong detalye.",
                "start_ms": 49320,
                "end_ms": 54040
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Sa kathang-isip na pagsasanay, hindi pa alam ang oras o pangalan ng contact.",
                "start_ms": 54340,
                "end_ms": 59820
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“Kung gusto mo, aalamin ko sa health team ang tamang contact at kung paano humingi ng pribadong usapan.",
                "start_ms": 60120,
                "end_ms": 66840
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Hindi pa kumpirmado ang iskedyul.",
                "start_ms": 67140,
                "end_ms": 69540
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Para malaman kong malinaw ako, ano muna ang hakbang?”",
                "start_ms": 69840,
                "end_ms": 73560
              },
              {
                "zone": "body",
                "index": 14,
                "text": "“Alamin muna ang contact; hindi pumili ng paraan ngayon,” sagot ni Jo.",
                "start_ms": 73860,
                "end_ms": 79020
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Bago gamitin sa tunay na pagbisita, tiyakin sa lokal na health team ang aktuwal na contact, saklaw ng BHW at paraan ng pribadong usapan.",
                "start_ms": 79320,
                "end_ms": 89200
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Ipaliwanag ang aprubadong gamit ng impormasyon at sino lamang ang kailangang makatanggap nito ayon sa lokal na patakaran.",
                "start_ms": 89500,
                "end_ms": 97180
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Walang pangakong ganap na lihim.",
                "start_ms": 97480,
                "end_ms": 100640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pakinggan ang concern. Alamin ang contact sa health team. Igalang ang pagpili; hindi BHW ang pumipili ng paraan.",
                "start_ms": 100940,
                "end_ms": 110340
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/practice.en.f55e8023306d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f55e8023306d4c8db46f4ec66dc0ef5e1c7b6d89318c96545e8097346b9eb4b7",
            "sha256": "9b5aa0499bea928c4eab51cca19c83a4b97d3d0690055166f21bdb1ab4fd7d28",
            "duration_seconds": 105.195,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Three situations, everyone tries",
                "start_ms": 0,
                "end_ms": 3400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use fictional cards for Jo, Ben and Ramon.",
                "start_ms": 3700,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "No real resident record or forced personal story.",
                "start_ms": 7440,
                "end_ms": 11800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "In triads, play Gibs or BHW, resident, and observer.",
                "start_ms": 12100,
                "end_ms": 17380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Rotate roles over three rounds so everyone plays BHW and the group practices all three situations.",
                "start_ms": 17680,
                "end_ms": 26120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "BHW: acknowledge the concern without blame, explain one correct step in plain words, and ask for understanding in the person’s own words.",
                "start_ms": 26420,
                "end_ms": 36380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Resident: use the concern and misunderstanding on the card.",
                "start_ms": 36680,
                "end_ms": 40880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Observer: record one helpful exact phrase and one phrase to change; do not assign a facilitator grade.",
                "start_ms": 41180,
                "end_ms": 48580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Repair the confusing explanation and check again.",
                "start_ms": 48880,
                "end_ms": 52400
              },
              {
                "zone": "body",
                "index": 8,
                "text": "End with the resident describing the correct step, including what remains unconfirmed.",
                "start_ms": 52700,
                "end_ms": 57860
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Contact details and availability are not supplied on the cards; checking with the health team is the step, not a guaranteed service.",
                "start_ms": 58160,
                "end_ms": 67080
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Alone, write or speak both sides of the fictional conversation and repeat the repair and recheck.",
                "start_ms": 67380,
                "end_ms": 74300
              },
              {
                "zone": "body",
                "index": 11,
                "text": "A quiet pair, reading assistance, a preferred language, and practice without internet or a projector are available.",
                "start_ms": 74600,
                "end_ms": 82720
              },
              {
                "zone": "body",
                "index": 12,
                "text": "The standard stays the same; direct facilitator observation is still required.",
                "start_ms": 83020,
                "end_ms": 88060
              },
              {
                "zone": "body",
                "index": 13,
                "text": "At the next authorized visit, use teach-back with one approved message.",
                "start_ms": 88360,
                "end_ms": 93160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Concern → one step → their own explanation → repair → recheck. Everyone tries the BHW role; direct observation supplies evidence.",
                "start_ms": 93460,
                "end_ms": 105140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/practice.fil.15660757bc93.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "15660757bc93c5d90829397c6c52c61a97f520b848853350892cc4ab5c7a4933",
            "sha256": "8221d3a393775cf48ad258fa23216fee21a963451cba977deb8540682d7f9a3c",
            "duration_seconds": 118.857,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tatlong sitwasyon, lahat susubok",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumamit ng kathang-isip na cards para kay Jo, Ben at Ramon.",
                "start_ms": 3740,
                "end_ms": 8780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Walang tunay na resident record o sapilitang personal na kuwento.",
                "start_ms": 9080,
                "end_ms": 14000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa tatluhan, gumanap na Gibs o BHW, residente, at tagamasid.",
                "start_ms": 14300,
                "end_ms": 21420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa tatlong round, magpalit ng papel upang lahat ay maging BHW at masubukan ng grupo ang lahat ng sitwasyon.",
                "start_ms": 21720,
                "end_ms": 30080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "BHW: kilalanin ang concern nang walang paninisi, sabihin ang isang tamang hakbang sa payak na salita, at itanong ang pagkaunawa sa sariling salita.",
                "start_ms": 30380,
                "end_ms": 41660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Residente: gamitin ang concern at maling pagkaunawa sa card.",
                "start_ms": 41960,
                "end_ms": 46800
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Tagamasid: itala ang eksaktong linyang nakatulong at isang linyang babaguhin; huwag magbigay ng facilitator grade.",
                "start_ms": 47100,
                "end_ms": 55060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ayusin ang nakalilitong paliwanag at mag-check muli.",
                "start_ms": 55360,
                "end_ms": 58800
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Dapat magtapos ang residente sa sariling paliwanag ng tamang hakbang, kasama ang hindi pa kumpirmado.",
                "start_ms": 59100,
                "end_ms": 66260
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Ang lokal na contact at availability ay hindi ibinibigay sa cards; ang pagtiyak sa health team ang hakbang, hindi garantiya ng serbisyo.",
                "start_ms": 66560,
                "end_ms": 75120
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Kung mag-isa, isulat o sabihin ang dalawang panig ng kathang-isip na usapan at ulitin ang repair at recheck.",
                "start_ms": 75420,
                "end_ms": 83540
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Maaari ang tahimik na pares, tulong sa pagbasa o komportableng wika, walang internet o projector.",
                "start_ms": 83840,
                "end_ms": 91080
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Pareho ang pamantayan; kailangan pa rin ng direktang obserbasyon ng facilitator.",
                "start_ms": 91380,
                "end_ms": 96940
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Sa susunod na awtorisadong pagbisita, gamitin ang teach-back sa isang aprubadong mensahe.",
                "start_ms": 97240,
                "end_ms": 103440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Concern → isang hakbang → sariling paliwanag → repair → recheck. Lahat ay susubok bilang BHW; direktang obserbasyon ang ebidensiya.",
                "start_ms": 103740,
                "end_ms": 118780
              }
            ]
          }
        },
        "smoking": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/smoking.en.ec767169afb5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ec767169afb5d64d7754eeb200140168943d0669a03bfbb970181abb88c0d66d",
            "sha256": "23d466fd2e2c568084b26de93c054244f4269b268591a7bb1ab834ba45b34fac",
            "duration_seconds": 93.753,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Discuss without blame",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ramon, 45, feels attacked when called “undisciplined.”",
                "start_ms": 2340,
                "end_ms": 6580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“May we discuss smoking and the support you want?”",
                "start_ms": 6880,
                "end_ms": 10240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gibs asks.",
                "start_ms": 10540,
                "end_ms": 11820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If Ramon does not want to discuss it now, respect his answer.",
                "start_ms": 12120,
                "end_ms": 16360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“I want to cut down, but it is hard when I am stressed,” Ramon says.",
                "start_ms": 16660,
                "end_ms": 21660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“You want a change, and stress is a barrier.",
                "start_ms": 21960,
                "end_ms": 25360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Is that right?”",
                "start_ms": 25660,
                "end_ms": 27060
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Gibs checks.",
                "start_ms": 27360,
                "end_ms": 28760
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Listen to the answer.",
                "start_ms": 29060,
                "end_ms": 30620
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Offer only a step within the BHW role: ask the local health team about a qualified contact and support actually available.",
                "start_ms": 30920,
                "end_ms": 39920
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Neither a service nor a time is confirmed in this fictional situation.",
                "start_ms": 40220,
                "end_ms": 45260
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“If you want, we can first find out who you could speak with.",
                "start_ms": 45560,
                "end_ms": 49080
              },
              {
                "zone": "body",
                "index": 12,
                "text": "To check that I explained clearly, what will we do first?”",
                "start_ms": 49380,
                "end_ms": 52980
              },
              {
                "zone": "body",
                "index": 13,
                "text": "“Will you give me medicine?”",
                "start_ms": 53280,
                "end_ms": 55200
              },
              {
                "zone": "body",
                "index": 14,
                "text": "Ramon asks.",
                "start_ms": 55500,
                "end_ms": 56820
              },
              {
                "zone": "body",
                "index": 15,
                "text": "“I will not give or choose medicine.",
                "start_ms": 57120,
                "end_ms": 60000
              },
              {
                "zone": "body",
                "index": 16,
                "text": "We will identify the contact so you can ask a qualified provider.",
                "start_ms": 60300,
                "end_ms": 64780
              },
              {
                "zone": "body",
                "index": 17,
                "text": "How would you describe the first step?”",
                "start_ms": 65080,
                "end_ms": 67680
              },
              {
                "zone": "body",
                "index": 18,
                "text": "“Find out the contact; medication is a discussion with the provider,” Ramon replies.",
                "start_ms": 67980,
                "end_ms": 73660
              },
              {
                "zone": "body",
                "index": 19,
                "text": "No lecture, medication, dose or promised outcome.",
                "start_ms": 73960,
                "end_ms": 78040
              },
              {
                "zone": "body",
                "index": 20,
                "text": "Before an actual conversation, verify available local support and authorized messages; do not invent a service.",
                "start_ms": 78340,
                "end_ms": 86660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask permission, hear the person’s goal, offer one verified step and use teach-back.",
                "start_ms": 86960,
                "end_ms": 93680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/smoking.fil.dbab265d3524.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dbab265d35249dcac9ebd4425a466d1254419934e0e64c3053b5821d9e754868",
            "sha256": "c60cd08308e571476f3e4087ef14a57ea5b69fb00372c795c5034699022fb3e7",
            "duration_seconds": 101.904,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Pag-usapan nang walang paninisi",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Ramon, 45, ay napipikon kapag tinatawag na “walang disiplina.”",
                "start_ms": 2780,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Puwede ba nating pag-usapan ang paninigarilyo at ang suportang gusto mo?”",
                "start_ms": 8840,
                "end_ms": 13440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong ni Gibs.",
                "start_ms": 13740,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung ayaw muna ni Ramon, igalang ang sagot.",
                "start_ms": 15480,
                "end_ms": 18640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“Gusto kong mabawasan, pero mahirap kapag stress,” sabi ni Ramon.",
                "start_ms": 18940,
                "end_ms": 23580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Gusto mong may mabago, at hadlang ang stress.",
                "start_ms": 23880,
                "end_ms": 27280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Tama ba?”",
                "start_ms": 27580,
                "end_ms": 28740
              },
              {
                "zone": "body",
                "index": 7,
                "text": "paglilinaw ni Gibs.",
                "start_ms": 29040,
                "end_ms": 31280
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Pakinggan ang sagot.",
                "start_ms": 31580,
                "end_ms": 33060
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Mag-alok lamang ng hakbang na saklaw ng BHW: alamin sa lokal na health team ang kwalipikadong contact at suportang aktuwal na mayroon.",
                "start_ms": 33360,
                "end_ms": 43320
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Hindi pa kumpirmado ang serbisyo o oras sa kathang-isip na sitwasyon.",
                "start_ms": 43620,
                "end_ms": 48340
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“Kung gusto mo, aalamin muna natin kung sino ang makakausap.",
                "start_ms": 48640,
                "end_ms": 53000
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Para malaman kong malinaw ang paliwanag ko, ano muna ang gagawin natin?”",
                "start_ms": 53300,
                "end_ms": 58100
              },
              {
                "zone": "body",
                "index": 13,
                "text": "“Bibigyan mo ako ng gamot?”",
                "start_ms": 58400,
                "end_ms": 60640
              },
              {
                "zone": "body",
                "index": 14,
                "text": "tanong ni Ramon.",
                "start_ms": 60940,
                "end_ms": 62580
              },
              {
                "zone": "body",
                "index": 15,
                "text": "“Hindi ako magbibigay o pipili ng gamot.",
                "start_ms": 62880,
                "end_ms": 66160
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Aalamin muna ang contact para makapagtanong ka sa kwalipikadong provider.",
                "start_ms": 66460,
                "end_ms": 71820
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Paano mo sasabihin ang unang hakbang?”",
                "start_ms": 72120,
                "end_ms": 74680
              },
              {
                "zone": "body",
                "index": 18,
                "text": "“Alamin ang contact; sa provider ang usapan sa gamot,” sagot ni Ramon.",
                "start_ms": 74980,
                "end_ms": 79540
              },
              {
                "zone": "body",
                "index": 19,
                "text": "Walang sermon, gamot, dose o pangakong resulta.",
                "start_ms": 79840,
                "end_ms": 84920
              },
              {
                "zone": "body",
                "index": 20,
                "text": "Bago ang tunay na usapan, tiyakin ang aktuwal na lokal na suporta at awtorisadong mensahe; huwag mag-imbento ng serbisyo.",
                "start_ms": 85220,
                "end_ms": 93180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng pahintulot, pakinggan ang layunin, mag-alok ng isang natiyak na hakbang at gamitin ang teach-back.",
                "start_ms": 93480,
                "end_ms": 101840
              }
            ]
          }
        },
        "teach-back": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-explain/teach-back.en.af1b32ee149f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "af1b32ee149f5e38c6071672ea0dac357bc3ae7b471eecc41e6e7b7dd7c5d4c3",
            "sha256": "fb69d19b04384defee09eff25808efe39bf5e3fbe44e327ec8ba80d1b84db6e0",
            "duration_seconds": 94.407,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One step, then hear it back",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs, a male BHW, listens to Liza, 29.",
                "start_ms": 2780,
                "end_ms": 7220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“It is hard to go when nobody can look after my child,” Liza says.",
                "start_ms": 7520,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Your concern matters.",
                "start_ms": 12500,
                "end_ms": 14620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If you want, we can ask the midwife about scheduling,” Gibs replies.",
                "start_ms": 14920,
                "end_ms": 19320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "He promises neither an appointment nor childcare.",
                "start_ms": 19620,
                "end_ms": 23260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Give one step in plain words: “First we will ask the midwife when she can be contacted.”",
                "start_ms": 23560,
                "end_ms": 30280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Then ask: “To check that I explained clearly, how would you describe the next step in your own words?”",
                "start_ms": 30580,
                "end_ms": 37020
              },
              {
                "zone": "body",
                "index": 7,
                "text": "“Do I have an appointment tomorrow?”",
                "start_ms": 37320,
                "end_ms": 39640
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Liza asks.",
                "start_ms": 39940,
                "end_ms": 41420
              },
              {
                "zone": "body",
                "index": 9,
                "text": "“Not yet.",
                "start_ms": 41720,
                "end_ms": 42880
              },
              {
                "zone": "body",
                "index": 10,
                "text": "My explanation was unclear,” Gibs replies.",
                "start_ms": 43180,
                "end_ms": 47180
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“We will ask about scheduling first; there is no confirmed appointment.",
                "start_ms": 47480,
                "end_ms": 52240
              },
              {
                "zone": "body",
                "index": 12,
                "text": "What will we do first?”",
                "start_ms": 52540,
                "end_ms": 54460
              },
              {
                "zone": "body",
                "index": 13,
                "text": "“Ask about the schedule; I am not booked yet,” Liza says.",
                "start_ms": 54760,
                "end_ms": 59320
              },
              {
                "zone": "body",
                "index": 14,
                "text": "“Yes, that is the first step,” Gibs confirms.",
                "start_ms": 59620,
                "end_ms": 63580
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Teach-back checks the BHW’s explanation, not the person’s intelligence or memory.",
                "start_ms": 63880,
                "end_ms": 69920
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Explain, ask, repair the misunderstanding, and check again.",
                "start_ms": 70220,
                "end_ms": 75300
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Use a helpful picture and the person’s preferred language; stay within approved messages and the BHW role.",
                "start_ms": 75600,
                "end_ms": 83520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "One step → their own explanation → repair → recheck. Asking about scheduling is not a confirmed appointment.",
                "start_ms": 83820,
                "end_ms": 94340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-explain/teach-back.fil.206b1159c6ee.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "206b1159c6eef265f5648d25f4fb27cade7501844b6478108642d29cbfe0a001",
            "sha256": "e6a78ab5c8d1d518a6cab64b2fc1a1199c6a12455057921a55350b5593f45965",
            "duration_seconds": 99.683,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang hakbang, saka pakinggan ang balik",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Gibs, lalaking BHW, ay nakikinig kay Liza, 29.",
                "start_ms": 3420,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Mahirap pumunta kapag walang magbabantay sa anak ko,” sabi ni Liza.",
                "start_ms": 9200,
                "end_ms": 13960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Mahalaga ang alalahanin mo.",
                "start_ms": 14260,
                "end_ms": 16540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung gusto mo, maaari nating alamin ang iskedyul sa midwife,” tugon ni Gibs.",
                "start_ms": 16840,
                "end_ms": 22400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi niya ipinapangako ang appointment o childcare.",
                "start_ms": 22700,
                "end_ms": 26060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Isang hakbang muna, gamit ang payak na salita: “Magtatanong muna tayo sa midwife kung kailan siya maaaring makausap.”",
                "start_ms": 26360,
                "end_ms": 33760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Saka: “Para malaman kong malinaw ang paliwanag ko, paano mo ikukuwento ang susunod na hakbang sa sarili mong salita?”",
                "start_ms": 34060,
                "end_ms": 41940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "“May appointment na ako bukas?”",
                "start_ms": 42240,
                "end_ms": 44400
              },
              {
                "zone": "body",
                "index": 8,
                "text": "tanong ni Liza.",
                "start_ms": 44700,
                "end_ms": 46140
              },
              {
                "zone": "body",
                "index": 9,
                "text": "“Hindi pa.",
                "start_ms": 46440,
                "end_ms": 47880
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Hindi malinaw ang paliwanag ko,” sagot ni Gibs.",
                "start_ms": 48180,
                "end_ms": 51700
              },
              {
                "zone": "body",
                "index": 11,
                "text": "“Magtatanong muna tayo tungkol sa iskedyul; wala pang kumpirmadong appointment.",
                "start_ms": 52000,
                "end_ms": 56720
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Ano muna ang gagawin natin?”",
                "start_ms": 57020,
                "end_ms": 59060
              },
              {
                "zone": "body",
                "index": 13,
                "text": "“Magtatanong tungkol sa iskedyul; hindi pa ako naka-book,” sabi ni Liza.",
                "start_ms": 59360,
                "end_ms": 64040
              },
              {
                "zone": "body",
                "index": 14,
                "text": "“Tama, iyon muna,” tugon ni Gibs.",
                "start_ms": 64340,
                "end_ms": 67420
              },
              {
                "zone": "body",
                "index": 15,
                "text": "Ang teach-back ay check sa paliwanag ng BHW, hindi pagsusulit sa talino o memorya ng kausap.",
                "start_ms": 67720,
                "end_ms": 75480
              },
              {
                "zone": "body",
                "index": 16,
                "text": "Magpaliwanag, magtanong, ayusin ang hindi malinaw, at mag-check muli.",
                "start_ms": 75780,
                "end_ms": 81340
              },
              {
                "zone": "body",
                "index": 17,
                "text": "Gumamit ng angkop na larawan at wikang komportable ang kausap; manatili sa aprubadong mensahe at saklaw ng BHW.",
                "start_ms": 81640,
                "end_ms": 90720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Isang hakbang → sariling paliwanag → ayusin → mag-check muli. Hindi pa appointment ang pagtatanong sa iskedyul.",
                "start_ms": 91020,
                "end_ms": 99620
              }
            ]
          }
        }
      }
    },
    "communication-handoff": {
      "module": "06-komunikasyon",
      "sections": {
        "audience": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/audience.en.f35c41ddca17.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f35c41ddca1773261f19887efaf75f4a928886257f49b01f9b8ca4c5cedb006c",
            "sha256": "c4aa71a6fc66386b73e0002e27c680c7d47eb304da895b3f0d2c39cfa0a40cf5",
            "duration_seconds": 42.58,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Adapt the message to the audience",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza and the midwife need different information.",
                "start_ms": 3140,
                "end_ms": 6460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Liza needs a plain next step and a contact.",
                "start_ms": 6760,
                "end_ms": 11200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The midwife needs the concern, verified details and requested help.",
                "start_ms": 11500,
                "end_ms": 17500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A barangay planning meeting needs aggregated barriers without identifying people.",
                "start_ms": 17800,
                "end_ms": 23760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose a picture, spoken explanation or secure written report to fit the audience and purpose; do not turn a private case into a public story.",
                "start_ms": 24060,
                "end_ms": 35940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The same concern can be presented differently for the purpose and appropriate recipient.",
                "start_ms": 36240,
                "end_ms": 42520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/audience.fil.21c78bffb05a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "21c78bffb05a3d3075eab26647b952025607a4d3bdd882ff416065b095e23b81",
            "sha256": "1bd2b7080b509badaa29af4c8c3f23cee9b45d05bfa24eaa14b420c2882c7995",
            "duration_seconds": 48.588,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Iangkop ang mensahe sa tatanggap",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Magkaiba ang kailangan ni Liza at ng midwife.",
                "start_ms": 3540,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kay Liza: payak na susunod na hakbang at kung sino ang lalapitan.",
                "start_ms": 8120,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa midwife: maikling concern, natiyak na detalye at hinihinging tulong.",
                "start_ms": 14460,
                "end_ms": 20940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa barangay planning meeting: pinagsama-samang hadlang na walang pagkakakilanlan.",
                "start_ms": 21240,
                "end_ms": 26720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pumili ng larawan, pasalitang paliwanag o ligtas na nakasulat na ulat ayon sa layunin at kakayahan ng tatanggap; huwag gawing pampublikong kuwento ang pribadong kaso.",
                "start_ms": 27020,
                "end_ms": 41260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang parehong concern ay maaaring ilahad nang magkaiba ayon sa layunin at tamang tatanggap.",
                "start_ms": 41560,
                "end_ms": 48520
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/check.en.1fb16926b5ea.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1fb16926b5ea206145cd23cea71a8bbef604c0760256c10ae4c3a5215beb48f1",
            "sha256": "e21b12cab8a83070b07935899167a0e54c1230c5c05230b6d28ac4ba7eaf8dd3",
            "duration_seconds": 16.614,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2100,
                "end_ms": 6740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7040,
                "end_ms": 10400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A handoff gives the right person enough to act while protecting private details.",
                "start_ms": 10700,
                "end_ms": 16540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/check.fil.53da54e424ec.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "53da54e424ec57cae61c912f5830f89728704b530a25ae86a493bd4ef574ca5a",
            "sha256": "37673bce16239678290f9f25373b2a882dcca12b7d713edfcf0d398e6fc30c45",
            "duration_seconds": 20.715,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3140,
                "end_ms": 8300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8600,
                "end_ms": 13040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ulat ay sapat para makakilos ang tamang tao, habang protektado ang pribadong detalye.",
                "start_ms": 13340,
                "end_ms": 20660
              }
            ]
          }
        },
        "handoff": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/handoff.en.5aba4e99d371.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5aba4e99d3710bbae03f905538dd30a1f351e1b6af05742bf3be7e34a98986fd",
            "sha256": "eb011a5f40e0dbf97232811f5b85f24b148c9bb5f380d6f4ec7c170abc079c06",
            "duration_seconds": 60.056,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Report enough for action",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Gibs has heard Liza, 29, describe a childcare barrier to attending the health center.",
                "start_ms": 3020,
                "end_ms": 11180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The last attendance date remains unconfirmed.",
                "start_ms": 11480,
                "end_ms": 14960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gibs uses the approved form: date, relevant concern, information source, action taken and needed follow-up.",
                "start_ms": 15260,
                "end_ms": 24580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For example: “Liza reports difficulty finding childcare; last attendance date needs verification.",
                "start_ms": 24880,
                "end_ms": 32360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Requests a conversation with the midwife about scheduling.”",
                "start_ms": 32660,
                "end_ms": 36540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Send this to the appropriate health team member through an authorized channel.",
                "start_ms": 36840,
                "end_ms": 41840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Keep names and private details out of public group chats.",
                "start_ms": 42140,
                "end_ms": 46820
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Confirm receipt and identify who will act next.",
                "start_ms": 47120,
                "end_ms": 51360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Recording and presenting information requires clarity, a next step and the appropriate recipient.",
                "start_ms": 51660,
                "end_ms": 59980
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/handoff.fil.c86859ad068b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c86859ad068bcd412e18635715482327be1bfe0e126daaec1b6989cc008822d7",
            "sha256": "b24af2b1b4988074c190f6aea2b7b81d7702c303cfde3c9f22755d9d7a680dc1",
            "duration_seconds": 72.333,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Iulat ang kailangan para makakilos",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si BHW Gibs ay nakinig kay Liza, 29.",
                "start_ms": 3780,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinabi ni Liza na walang magbabantay sa anak kaya mahirap pumunta sa health center; hindi pa nakumpirma ang huling attendance.",
                "start_ms": 8760,
                "end_ms": 18080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ginagamit ni Gibs ang aprubadong form: petsa, kaugnay na concern, pinagmulan ng impormasyon, ginawa at kailangang follow-up.",
                "start_ms": 18380,
                "end_ms": 30060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Halimbawa: “Ayon kay Liza, problema ang magbabantay sa anak; petsa ng huling pagpunta ay ibeberipika.",
                "start_ms": 30360,
                "end_ms": 40040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Humihingi ng pakikipag-usap sa midwife tungkol sa iskedyul.”",
                "start_ms": 40340,
                "end_ms": 44580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ibigay ito sa tamang health team member sa awtorisadong paraan.",
                "start_ms": 44880,
                "end_ms": 49880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Huwag ilagay ang pangalan at pribadong detalye sa pampublikong group chat.",
                "start_ms": 50180,
                "end_ms": 55580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Tanungin kung natanggap ang ulat at kung sino ang susunod na kikilos.",
                "start_ms": 55880,
                "end_ms": 60960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagtatala at paglalahad ng impormasyon ay dapat malinaw, may susunod na hakbang at para lamang sa tamang tatanggap.",
                "start_ms": 61260,
                "end_ms": 72260
              }
            ]
          }
        },
        "meeting": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/meeting.en.849d0bfe8ed8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "849d0bfe8ed85cfa9a75b6cdbfd47cf93e825ed557a6735c384bd9f7de8499ed",
            "sha256": "e4340df13e54b2566c83cc2a601be2bcb74dae90443eee9dc8ce06c1cc1372ca",
            "duration_seconds": 37.721,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Present at a meeting without names",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In this exercise, three fictional households share a childcare barrier.",
                "start_ms": 3420,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Prepare a one-minute report without names or identifying details: what is the pattern, what information is missing, and what small service change could be discussed?",
                "start_ms": 9200,
                "end_ms": 21640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "End with a clear question for the group.",
                "start_ms": 21940,
                "end_ms": 24700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not promise that a proposal is approved before the responsible people decide.",
                "start_ms": 25000,
                "end_ms": 30840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A meeting presentation asks for a concrete decision while protecting private stories.",
                "start_ms": 31140,
                "end_ms": 37660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/meeting.fil.f69c7cf8f31a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f69c7cf8f31a2f4908194e3f7a18a971e0597a75e1597b7d9fa1dac2a9cc0f45",
            "sha256": "3433c06066b00e67a391f9e87424d0637935b3599fcc75e4da5cf21ff36d3c41",
            "duration_seconds": 41.77,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ipaliwanag sa pulong nang walang pangalan",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pagsasanay, tatlong kathang-isip na pamilya ang may parehong hadlang sa childcare.",
                "start_ms": 3780,
                "end_ms": 10260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maghanda ng isang minutong ulat na walang pangalan o detalyeng makakakilala sa kanila: ano ang pattern, anong impormasyon ang kulang, at anong maliit na pagbabago sa serbisyo ang maaaring pag-usapan?",
                "start_ms": 10560,
                "end_ms": 24400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tapusin sa malinaw na tanong sa grupo.",
                "start_ms": 24700,
                "end_ms": 27700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag ipangakong aprubado na ang mungkahi bago magpasya ang may tungkulin.",
                "start_ms": 28000,
                "end_ms": 33480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang paglalahad sa pulong ay humihingi ng konkretong desisyon habang pinangangalagaan ang pribadong kuwento.",
                "start_ms": 33780,
                "end_ms": 41700
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/practice.en.e987d77bd1f5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e987d77bd1f5d58dbeffa3ecdfbb4a835298db2bc95fc6c0f194fbdd33c4a58f",
            "sha256": "167d0f5bfba9a5c7a9a1568cca060e6df1bda0e3c4e006ee1dc2698294613a6f",
            "duration_seconds": 38.217,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Replace “The family is difficult” with three sentences: Liza’s concern; confirmed and unconfirmed details; help requested from the midwife.",
                "start_ms": 2820,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Add the authorized channel and how receipt will be confirmed.",
                "start_ms": 15120,
                "end_ms": 19960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask a partner whether the next step is clear.",
                "start_ms": 20260,
                "end_ms": 23300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, check the four elements.",
                "start_ms": 23600,
                "end_ms": 26680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "In the next handoff, confirm the recipient and follow-up owner.",
                "start_ms": 26980,
                "end_ms": 32020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A handoff gives the right person enough to act while protecting private details.",
                "start_ms": 32320,
                "end_ms": 38160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-handoff/practice.fil.1100cbc1f0e8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1100cbc1f0e8c9fc135f92d6dbce026bcbbed2589a3b0e4b43efc8fa6c2e5dd1",
            "sha256": "f5b94b1d5de59336dbea973535c3e527987ff3c710248f36b09d528914091a3a",
            "duration_seconds": 45.427,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Palitan ang “Mahirap kausap ang pamilya” ng tatlong pangungusap: concern ni Liza; natiyak at hindi pa tiyak; tulong na hinihingi sa midwife.",
                "start_ms": 3420,
                "end_ms": 15740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Idagdag ang awtorisadong channel at paano kukumpirmahin ang pagtanggap.",
                "start_ms": 16040,
                "end_ms": 21760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipabasa sa kapareha: alam ba niya ang susunod na hakbang?",
                "start_ms": 22060,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mag-isa, suriin gamit ang apat na bahagi.",
                "start_ms": 27320,
                "end_ms": 31560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa susunod na ulat, kumpirmahin ang tumanggap at may-ari ng follow-up.",
                "start_ms": 31860,
                "end_ms": 37780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ulat ay sapat para makakilos ang tamang tao, habang protektado ang pribadong detalye.",
                "start_ms": 38080,
                "end_ms": 45360
              }
            ]
          }
        }
      }
    },
    "communication-listen": {
      "module": "06-komunikasyon",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/check.en.dcdaa412d29b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dcdaa412d29b3eb79cc71ba434fd0c72f581997b4f3e1e7fd39f750f795d4d71",
            "sha256": "6df064c60cb7e3b76421dbbd0b3bd48fe1c9267d38216e5727cf43244886e5f3",
            "duration_seconds": 27.533,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the scene: the neighbor answers for Liza.",
                "start_ms": 1860,
                "end_ms": 5620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gibs holds a closed clipboard.",
                "start_ms": 5920,
                "end_ms": 8360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "He has not yet checked where, in which language and with whom Liza feels comfortable talking.",
                "start_ms": 8660,
                "end_ms": 14900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Choose the first step and explain your reason before viewing feedback.",
                "start_ms": 15200,
                "end_ms": 19880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Then compare your decision with your practice attempt.",
                "start_ms": 20180,
                "end_ms": 23340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Give Liza a choice and a voice, then check understanding.",
                "start_ms": 23640,
                "end_ms": 27480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/check.fil.c3b213b32b6f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c3b213b32b6fe1f89781617fede646c260f4ad6b95f301516356fa13929ef7f4",
            "sha256": "346aefebef1e3eec9db0bb267d8d17327bf1942bfd492896e36c4f1e0090a89b",
            "duration_seconds": 33.228,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bumalik sa tagpo: ang kapitbahay ang sumasagot para kay Liza.",
                "start_ms": 2500,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hawak ni Gibs ang nakasarang clipboard.",
                "start_ms": 7760,
                "end_ms": 10480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa niya alam kung saan, sa anong wika at kanino kasama komportable si Liza.",
                "start_ms": 10780,
                "end_ms": 17460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Piliin ang unang hakbang at ipaliwanag ang dahilan bago tingnan ang feedback.",
                "start_ms": 17760,
                "end_ms": 23080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos, ihambing ang pasya sa ginawa mo sa pagsasanay.",
                "start_ms": 23380,
                "end_ms": 27900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bigyan ng pagpili at boses si Liza, saka tiyakin ang pagkaintindi.",
                "start_ms": 28200,
                "end_ms": 33160
              }
            ]
          }
        },
        "listen": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/listen.en.d6c6e47f2ab2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d6c6e47f2ab2faf7c9b3f8ceee1c5a500c4516eed7e9d420078866a1864ddc7e",
            "sha256": "ad6fb29571fd5b498a4654f24bf22c9e75a49103004a2ed775a8a89116b10f8d",
            "duration_seconds": 43.494,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Listen before giving advice",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs sits at Liza’s level and puts his phone away.",
                "start_ms": 3220,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“What would you like to tell me about getting to the health center?”",
                "start_ms": 7000,
                "end_ms": 10240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "he asks.",
                "start_ms": 10540,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "He allows time and does not interrupt.",
                "start_ms": 12080,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Liza says getting there is difficult when nobody can look after her child.",
                "start_ms": 15460,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“It sounds difficult to manage caregiving and getting there,” Gibs replies.",
                "start_ms": 20120,
                "end_ms": 25840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "He does not call Liza lazy or promise to fix everything.",
                "start_ms": 26140,
                "end_ms": 29940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "He uses a calm voice and allows pauses.",
                "start_ms": 30240,
                "end_ms": 33280
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Do not force eye contact; comfortable listening is not measured by staring.",
                "start_ms": 33580,
                "end_ms": 39100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Allow time for the account and acknowledge difficulty without blame.",
                "start_ms": 39400,
                "end_ms": 43440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/listen.fil.6d66945bc07f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6d66945bc07f01127fb74a27979b7745ccef3e6e77fc2d2b9d924dbcc76135be",
            "sha256": "7eb9a5a5454ca0c57b3c1fe474fb65a25c637f98bd2b525550299ad757a8ec7e",
            "duration_seconds": 47.935,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makinig bago magpayo",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Umupo si Gibs nang kapantay ni Liza at itinabi ang telepono.",
                "start_ms": 2380,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Ano po ang gusto ninyong ikuwento tungkol sa pagpunta sa health center?”",
                "start_ms": 6600,
                "end_ms": 10760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong niya.",
                "start_ms": 11060,
                "end_ms": 12220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nagbigay siya ng oras at hindi sumabat.",
                "start_ms": 12520,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sinabi ni Liza na mahirap pumunta kapag walang magbabantay sa anak.",
                "start_ms": 15780,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Mukhang mahirap pagsabayin ang pag-aalaga at pagpunta roon,” tugon ni Gibs.",
                "start_ms": 20120,
                "end_ms": 25760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi niya tinawag na tamad si Liza o nangakong maaayos ang lahat.",
                "start_ms": 26060,
                "end_ms": 30660
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Gumamit siya ng mahinahong boses at sapat na paghinto.",
                "start_ms": 30960,
                "end_ms": 35360
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Huwag pilitin ang eye contact; ang komportableng pakikinig ay hindi sinusukat sa pagtitig.",
                "start_ms": 35660,
                "end_ms": 42060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magbigay ng oras sa kuwento at kilalanin ang hirap nang walang paratang.",
                "start_ms": 42360,
                "end_ms": 47880
              }
            ]
          }
        },
        "liza": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/liza.en.f880278eea9b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f880278eea9b8a270f76a30fee49857200c5b29833ba74e61c15049969bc7810",
            "sha256": "07b7963bbb89ba72078653788cb2d90165c03f682fb532425a9cb493b1e8f929",
            "duration_seconds": 34.873,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Why is Liza quiet?",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs, a male BHW, visits Liza, 29, for a household profile.",
                "start_ms": 2660,
                "end_ms": 9220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A neighbor sits beside Liza and answers for her.",
                "start_ms": 9520,
                "end_ms": 13720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Liza gives short replies and looks toward the door.",
                "start_ms": 14020,
                "end_ms": 17500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "These cues do not tell Gibs for certain how she feels.",
                "start_ms": 17800,
                "end_ms": 21840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "He pauses the questions.",
                "start_ms": 22140,
                "end_ms": 24220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Before continuing, what should he check about Liza’s comfort and choices?",
                "start_ms": 24520,
                "end_ms": 29280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pause and ask what the person prefers; do not guess the reason for silence.",
                "start_ms": 29580,
                "end_ms": 34820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/liza.fil.947df9854c6d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "947df9854c6def3fd636436b493c24d001f8fc2b88abc1989bdd1637d1007c46",
            "sha256": "5062e66e7d4b44cee172dc7f1f741716802f014c53d0a0228da465c99ec4328e",
            "duration_seconds": 36.833,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bakit tahimik si Liza?",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Gibs, isang lalaking BHW, ay bumisita kay Liza, 29 anyos, para sa household profile.",
                "start_ms": 2220,
                "end_ms": 10060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Katabi ni Liza ang kapitbahay na sumasagot para sa kanya.",
                "start_ms": 10360,
                "end_ms": 13720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maikli ang sagot ni Liza at tumitingin siya sa pinto.",
                "start_ms": 14020,
                "end_ms": 17700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi nito tiyak na sinasabi kung ano ang nararamdaman niya.",
                "start_ms": 18000,
                "end_ms": 21800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huminto muna si Gibs sa pagtatanong.",
                "start_ms": 22100,
                "end_ms": 24380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Bago magpatuloy, ano ang dapat niyang alamin tungkol sa ginhawa at pagpili ni Liza?",
                "start_ms": 24680,
                "end_ms": 31360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huminto at itanong ang gusto ng kausap; huwag hulaan ang dahilan ng katahimikan.",
                "start_ms": 31660,
                "end_ms": 36780
              }
            ]
          }
        },
        "permission": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/permission.en.4041e78d3059.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4041e78d30591af91e441c7d740385141af0c3175b0f2e4d5220e799b1bbc2aa",
            "sha256": "32fedbb5914a2be2a68b76f45c264eea18a52a89d7a284bf194771166d44ab3a",
            "duration_seconds": 49.162,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ask permission and offer choices",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs explains: “This is for an authorized household profile and health-service planning.",
                "start_ms": 2900,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Only relevant information will be used by the authorized health team under local policy.",
                "start_ms": 9200,
                "end_ms": 14320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May we talk?”",
                "start_ms": 14620,
                "end_ms": 16060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "He asks about Liza’s preferred language, place and whether she wants a support person present.",
                "start_ms": 16360,
                "end_ms": 22400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“Here in the quieter part, in Filipino, just us for now,” Liza replies.",
                "start_ms": 22700,
                "end_ms": 28180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She may pause, leave a question unanswered for now or choose another time.",
                "start_ms": 28480,
                "end_ms": 33360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Gibs does not promise absolute secrecy.",
                "start_ms": 33660,
                "end_ms": 36900
              },
              {
                "zone": "body",
                "index": 7,
                "text": "If immediate help is needed, do not delay it to complete a routine interview; follow the local process.",
                "start_ms": 37200,
                "end_ms": 44040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The person chooses a comfortable place, language and support person.",
                "start_ms": 44340,
                "end_ms": 49100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/permission.fil.e556f22af84c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e556f22af84c1c88af981481b3bcd4b293ea55a8ed57a70c3c81f8e42fa2a40f",
            "sha256": "60dce0934aad4d82fff1d38b0d031fdcd5327c869e668093215401d85b8df266",
            "duration_seconds": 56.033,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Humingi ng pahintulot at mag-alok ng pagpili",
                "start_ms": 0,
                "end_ms": 4080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinaliwanag ni Gibs: “Para po ito sa awtorisadong household profile at pagpaplano ng serbisyong pangkalusugan.",
                "start_ms": 4380,
                "end_ms": 11860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kaugnay na impormasyon lamang ang gagamitin ng awtorisadong health team ayon sa lokal na patakaran.",
                "start_ms": 12160,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaari po ba tayong mag-usap?”",
                "start_ms": 18180,
                "end_ms": 20180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tinanong niya ang gustong wika, lugar at kung nais ni Liza ng kasamang susuporta sa kanya.",
                "start_ms": 20480,
                "end_ms": 27160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "“Dito po sa mas tahimik na bahagi, sa Filipino, tayo muna,” sagot ni Liza.",
                "start_ms": 27460,
                "end_ms": 32460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Maaari siyang magpahinga, hindi muna sumagot o pumili ng ibang oras.",
                "start_ms": 32760,
                "end_ms": 38360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi pangako ng ganap na lihim ang paliwanag ni Gibs.",
                "start_ms": 38660,
                "end_ms": 42500
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung kailangan ng agarang tulong, huwag itong ipagpaliban para makumpleto ang karaniwang interview; sundin ang lokal na proseso.",
                "start_ms": 42800,
                "end_ms": 50280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang kausap ang pumipili ng komportableng lugar, wika at kasama.",
                "start_ms": 50580,
                "end_ms": 55980
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/practice.en.12b535e84c65.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "12b535e84c65c2cbc3ddb4dfa73d14f1f590a9bc3287e59699a4a1b4a4cc5496",
            "sha256": "6901b00a0e3e63817e098a22b8e5d97ca5bc7fe0056d29e830531b6e0669640e",
            "duration_seconds": 48.797,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use the fictional role cards: Gibs, Liza and observer.",
                "start_ms": 2420,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Rehearse permission, choice of place and language, listening without interruption, and a summary with an accuracy check.",
                "start_ms": 7760,
                "end_ms": 17160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Liza chooses whether she wants a support person.",
                "start_ms": 17460,
                "end_ms": 20660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The observer records the exact helpful phrase and any rushed step.",
                "start_ms": 20960,
                "end_ms": 26200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Repeat that part before rotating roles.",
                "start_ms": 26500,
                "end_ms": 29540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Everyone practices as the BHW.",
                "start_ms": 29840,
                "end_ms": 32640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Alone, say both roles aloud and check the listening aid.",
                "start_ms": 32940,
                "end_ms": 36940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "At the next authorized visit, rehearse the same opening.",
                "start_ms": 37240,
                "end_ms": 41000
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Do not upload a resident’s private account.",
                "start_ms": 41300,
                "end_ms": 44660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Repeat the step needing work; peer feedback is practice.",
                "start_ms": 44960,
                "end_ms": 48720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/practice.fil.a42caab66ef8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a42caab66ef8227b2df736db57564850a2ae5124b75f767e4445eae376fa14c6",
            "sha256": "5455dffc6f9c0ea21c3b51cc85ebbd5291f586eba64fabedf481597fe08743c3",
            "duration_seconds": 52.637,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamitin ang kathang-isip na role cards: Gibs, Liza at tagamasid.",
                "start_ms": 2820,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Magsanay ng pahintulot, pagpili ng lugar at wika, pakikinig nang hindi sumasabat, at buod na may pagtiyak.",
                "start_ms": 8560,
                "end_ms": 16920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Si Liza ang pipili kung may kasamang susuporta.",
                "start_ms": 17220,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itala ng tagamasid ang eksaktong linyang nakatulong at ang hakbang na minadali.",
                "start_ms": 20680,
                "end_ms": 25960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ulitin ang bahaging iyon bago magpalit ng papel.",
                "start_ms": 26260,
                "end_ms": 29420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Lahat ay susubok bilang BHW.",
                "start_ms": 29720,
                "end_ms": 33160
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kung mag-isa, sabihin nang malakas ang dalawang papel at itsek ang listening aid.",
                "start_ms": 33460,
                "end_ms": 38660
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sa susunod na awtorisadong pagbisita, sanayin ang parehong pambungad.",
                "start_ms": 38960,
                "end_ms": 43640
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Huwag mag-upload ng pribadong kuwento ng residente.",
                "start_ms": 43940,
                "end_ms": 47020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ulitin ang hindi pa malinaw na hakbang; feedback ng kapareha ay pagsasanay.",
                "start_ms": 47320,
                "end_ms": 52560
              }
            ]
          }
        },
        "profile": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-listen/profile.en.4fa60ff0f040.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4fa60ff0f040bff559d28c774570dde26bcd5f4ef5cd7d867b780e6b7154178d",
            "sha256": "e45a11235ba24d664a4944e133956d9efee37f243ae09a04dbcec2c5154a6589",
            "duration_seconds": 49.972,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Summarize and check accuracy",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Have I understood correctly: getting there is difficult when nobody can look after your child?”",
                "start_ms": 2900,
                "end_ms": 9180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gibs asks.",
                "start_ms": 9480,
                "end_ms": 11000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Yes, when my sister is away,” Liza clarifies.",
                "start_ms": 11300,
                "end_ms": 15460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Gibs offers a more accurate summary: “When your sister is away, it is difficult to find childcare.",
                "start_ms": 15760,
                "end_ms": 22520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Is that right?”",
                "start_ms": 22820,
                "end_ms": 24140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Liza confirms it.",
                "start_ms": 24440,
                "end_ms": 26400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "This is a fictional accuracy check, not an actual record.",
                "start_ms": 26700,
                "end_ms": 30980
              },
              {
                "zone": "body",
                "index": 7,
                "text": "In an authorized profile, collect only relevant information, do not guess missing answers and respect a wish not to answer yet.",
                "start_ms": 31280,
                "end_ms": 41000
              },
              {
                "zone": "body",
                "index": 8,
                "text": "No childcare arrangement or appointment has been promised.",
                "start_ms": 41300,
                "end_ms": 45500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask whether the summary is accurate and let the person correct it.",
                "start_ms": 45800,
                "end_ms": 49920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-listen/profile.fil.4ea13b5f19d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ea13b5f19d0b05282f420e6467142e777be6c9ff9398729a1d7900d6f0417f2",
            "sha256": "c6eea6b674c3b580fe319ae71509fa18dc318485cba896e69bf480cf8c532037",
            "duration_seconds": 50.233,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ibuod at tiyaking tama",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Tama po ba ang pagkaintindi ko: mahirap pumunta kapag walang magbabantay sa anak ninyo?”",
                "start_ms": 2660,
                "end_ms": 9100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "tanong ni Gibs.",
                "start_ms": 9400,
                "end_ms": 11000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Opo, kapag wala ang kapatid ko,” paglilinaw ni Liza.",
                "start_ms": 11300,
                "end_ms": 15740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ibinalik ni Gibs ang mas tumpak na buod: “Kapag wala ang kapatid ninyo, mahirap makahanap ng magbabantay.",
                "start_ms": 16040,
                "end_ms": 24280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tama po ba?”",
                "start_ms": 24580,
                "end_ms": 25780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kinumpirma ito ni Liza.",
                "start_ms": 26080,
                "end_ms": 28040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Kathang-isip na halimbawa ito ng pagtitiyak, hindi aktuwal na rekord.",
                "start_ms": 28340,
                "end_ms": 32900
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Sa awtorisadong profile, kunin lamang ang kaugnay na impormasyon, huwag hulaan ang patlang at igalang ang ayaw munang sagutin.",
                "start_ms": 33200,
                "end_ms": 41920
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Walang ipinangakong childcare o appointment.",
                "start_ms": 42220,
                "end_ms": 45540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tanungin kung tama ang buod at hayaan ang kausap na magwasto.",
                "start_ms": 45840,
                "end_ms": 50160
              }
            ]
          }
        }
      }
    },
    "communication-record": {
      "module": "06-komunikasyon",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/check.en.e8ce6fa508a4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e8ce6fa508a42f7f7ebb92943ee564308a8ff74c6d512fd49693c98d196af2d3",
            "sha256": "ff61e519a38033bf3bf4313eca97a3bbb5afb904676840deb584d5bd602a26cf",
            "duration_seconds": 40.934,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the initial scene, before clarification: Liza reports a canceled schedule; the neighbor says she is not interested.",
                "start_ms": 1940,
                "end_ms": 10020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "No card has been shown and Gibs has not seen the authorized attendance record.",
                "start_ms": 10320,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Which initial note is appropriate?",
                "start_ms": 16020,
                "end_ms": 18260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Choose and explain your reason before viewing feedback and the corrected note.",
                "start_ms": 18560,
                "end_ms": 23600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Then compare it with your practice attempt.",
                "start_ms": 23900,
                "end_ms": 26420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A screen choice, lesson completion or watching the optional story does not prove that you can perform the task.",
                "start_ms": 26720,
                "end_ms": 34680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clear sources and explicit gaps prevent a guess becoming an official record.",
                "start_ms": 34980,
                "end_ms": 40860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/check.fil.695d5a2fd3a1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "695d5a2fd3a10517ee1bc91975eec389501c5c90bd0439422c7bd1e573bc67a8",
            "sha256": "ba62fc0e9ffeead50ded44d210db613955e182995a7e4818790b5fb35e786989",
            "duration_seconds": 48.118,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bumalik sa unang tagpo, bago ang paglilinaw: sinabi ni Liza na kinansela ang schedule; sabi ng kapitbahay, hindi siya interesado.",
                "start_ms": 2740,
                "end_ms": 12100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Walang card na naipakita at hindi pa nakita ni Gibs ang awtorisadong attendance record.",
                "start_ms": 12400,
                "end_ms": 18440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Aling paunang tala ang angkop?",
                "start_ms": 18740,
                "end_ms": 20860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Piliin at ipaliwanag ang dahilan bago tingnan ang feedback at ang iwinastong tala.",
                "start_ms": 21160,
                "end_ms": 26920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pagkatapos, ihambing sa sarili mong pagsasanay.",
                "start_ms": 27220,
                "end_ms": 30980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang pagpili sa screen, pagkumpleto ng aralin o panonood ng opsyonal na kuwento ay hindi patunay na kaya mo nang gawin ang gawain.",
                "start_ms": 31280,
                "end_ms": 40640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Malinaw na pinagmulan at tapat na pagmarka sa kulang ang pumipigil sa hula na maging opisyal na tala.",
                "start_ms": 40940,
                "end_ms": 48060
              }
            ]
          }
        },
        "conflicting-accounts": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/conflicting-accounts.en.c93fc9fe955a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c93fc9fe955a9856e52fcf93a37d59ca5493abcb279b4f6a3e9cdeeb89a2b6ee",
            "sha256": "500f2adf6b1906c0341afdfcd68ae204b4e70bd2e530ee2c54f6fc7e053ac9ce",
            "duration_seconds": 64.496,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "When accounts differ",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Liza says: “The schedule was canceled.”",
                "start_ms": 1900,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The neighbor says: “She did not want to go.”",
                "start_ms": 5280,
                "end_ms": 8200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gibs does not choose a story because one voice is louder.",
                "start_ms": 8500,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“What do you mean by canceled?”",
                "start_ms": 12760,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "he asks Liza.",
                "start_ms": 15500,
                "end_ms": 17060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“I could not go when my sister was away.",
                "start_ms": 17360,
                "end_ms": 20240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "I am not sure whether the center canceled it,” she clarifies.",
                "start_ms": 20540,
                "end_ms": 24420
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Gibs summarizes: “You could not go when your sister was away; the schedule status is still uncertain.",
                "start_ms": 24720,
                "end_ms": 31920
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Is that right?”",
                "start_ms": 32220,
                "end_ms": 33660
              },
              {
                "zone": "body",
                "index": 9,
                "text": "“Yes,” Liza replies.",
                "start_ms": 33960,
                "end_ms": 36080
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Record this as Liza’s clarification, keeping the source of the first statement and its correction clear.",
                "start_ms": 36380,
                "end_ms": 42460
              },
              {
                "zone": "body",
                "index": 11,
                "text": "If the neighbor’s report is relevant to the task, attribute it to the neighbor; it is not proof of Liza’s motive.",
                "start_ms": 42760,
                "end_ms": 49600
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Trust and careful verification work together.",
                "start_ms": 49900,
                "end_ms": 53100
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Do not label a resident dishonest or noncompliant merely because accounts differ.",
                "start_ms": 53400,
                "end_ms": 59440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "When accounts differ, clarify and verify before deciding.",
                "start_ms": 59740,
                "end_ms": 64420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/conflicting-accounts.fil.4fd6e95f01b2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4fd6e95f01b22999d0d2f5f5fc2ca75f55d5a8be925a6ce4661c94dd524ae45e",
            "sha256": "e4aecb1d2d121d846b154e41c6f9152a241144a399a2d78f01bc7ee9815b1063",
            "duration_seconds": 72.725,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kapag may magkaibang kuwento",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sabi ni Liza: “Kinansela ang schedule.”",
                "start_ms": 2780,
                "end_ms": 6500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sabi ng kapitbahay: “Ayaw niyang pumunta.”",
                "start_ms": 6800,
                "end_ms": 10120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pipili si Gibs dahil mas malakas ang boses ng isa.",
                "start_ms": 10420,
                "end_ms": 14260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "“Ano po ang ibig ninyong sabihin sa kinansela?”",
                "start_ms": 14560,
                "end_ms": 18040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "tanong niya kay Liza.",
                "start_ms": 18340,
                "end_ms": 19900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "“Hindi ako nakapunta noong wala ang kapatid ko.",
                "start_ms": 20200,
                "end_ms": 23280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi ko tiyak kung kinansela ng center,” paglilinaw niya.",
                "start_ms": 23580,
                "end_ms": 27780
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Ibinuod ni Gibs: “Hindi kayo nakapunta nang wala ang kapatid ninyo; hindi pa tiyak ang status ng schedule.",
                "start_ms": 28080,
                "end_ms": 36160
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Tama po ba?”",
                "start_ms": 36460,
                "end_ms": 37820
              },
              {
                "zone": "body",
                "index": 9,
                "text": "“Opo,” sagot ni Liza.",
                "start_ms": 38120,
                "end_ms": 40360
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Itala ang paglilinaw bilang sinabi ni Liza at panatilihing malinaw ang pinagmulan ng unang pahayag at pagwawasto.",
                "start_ms": 40660,
                "end_ms": 48540
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Kung mahalaga sa gawain ang ulat ng kapitbahay, iugnay ito sa kanya; hindi ito katunayan ng motibo ni Liza.",
                "start_ms": 48840,
                "end_ms": 56600
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Ang pagtitiwala at maingat na pagberipika ay magkasabay.",
                "start_ms": 56900,
                "end_ms": 61020
              },
              {
                "zone": "body",
                "index": 13,
                "text": "Huwag tawaging sinungaling o hindi sumusunod ang residente dahil lamang magkaiba ang kuwento.",
                "start_ms": 61320,
                "end_ms": 67440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kapag magkaiba ang kuwento, maglinaw at magberipika bago magpasya.",
                "start_ms": 67740,
                "end_ms": 72660
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/practice.en.e0435701e2cd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e0435701e2cd8a54a0dc24a1fffdec5f9c3c75cece3792c149af0523189ed48a",
            "sha256": "75f1569f177e58991f3323cd3e77796d918d1fc3b96de4e17f5a39d71509629f",
            "duration_seconds": 75.572,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "First draw three boxes: “Reported,” “Observed,” and “Unconfirmed.”",
                "start_ms": 2580,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Split the first box into “Liza reports” and “neighbor reports” to make the recording aid’s four columns.",
                "start_ms": 8680,
                "end_ms": 16480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sort the fictional source cards into the correct column.",
                "start_ms": 16780,
                "end_ms": 20420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Write a short note containing Liza’s clarification and one step to verify the date.",
                "start_ms": 20720,
                "end_ms": 26280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Check it for guesses, diagnoses, judgments or irrelevant details.",
                "start_ms": 26580,
                "end_ms": 32100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "In a triad, rotate as BHW, resident and observer through three rounds so everyone attempts the BHW role.",
                "start_ms": 32400,
                "end_ms": 42080
              },
              {
                "zone": "body",
                "index": 6,
                "text": "The observer records exact evidence and one step to repeat; this is feedback, not a facilitator grade.",
                "start_ms": 42380,
                "end_ms": 50220
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Alone, sort paper cards, underline sources and correct the note.",
                "start_ms": 50520,
                "end_ms": 55800
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Cards may be read aloud or used in the preferred language.",
                "start_ms": 56100,
                "end_ms": 59820
              },
              {
                "zone": "body",
                "index": 9,
                "text": "No internet, projector, real resident record or upload is needed.",
                "start_ms": 60120,
                "end_ms": 66040
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Repeat the difficult part before continuing.",
                "start_ms": 66340,
                "end_ms": 69140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clear sources and explicit gaps prevent a guess becoming an official record.",
                "start_ms": 69440,
                "end_ms": 75520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/practice.fil.87f74220d8cd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "87f74220d8cd076586cf9827a46b42099d5918b9a597dc0186728c935cce9742",
            "sha256": "9ea2adb6ff5b57769a7ce73c57e7874364977b73f92dbc1a2862df57e684944e",
            "duration_seconds": 86.518,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumawa muna ng tatlong kahon: “Sinabi,” “Nakita,” at “Hindi pa tiyak.”",
                "start_ms": 3060,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa unang kahon, paghiwalayin ang “ayon kay Liza” at “ayon sa kapitbahay” upang magkaroon ng apat na hanay sa recording aid.",
                "start_ms": 9440,
                "end_ms": 19120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ilagay ang kathang-isip na source cards sa tamang hanay.",
                "start_ms": 19420,
                "end_ms": 23500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Gumawa ng maikling tala na may paglilinaw ni Liza at isang hakbang sa pagberipika ng petsa.",
                "start_ms": 23800,
                "end_ms": 31520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipasuri kung may hula, diagnosis, husga o hindi kaugnay na detalye.",
                "start_ms": 31820,
                "end_ms": 37980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa triad, magpalit bilang BHW, residente at tagamasid sa tatlong round upang lahat ay sumubok bilang BHW.",
                "start_ms": 38280,
                "end_ms": 48120
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Itala ng tagamasid ang eksaktong ebidensya at isang kailangang ulitin; feedback ito, hindi grado ng facilitator.",
                "start_ms": 48420,
                "end_ms": 57100
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Kung mag-isa, iayos ang papel na cards, salungguhitan ang pinagmulan at iwasto ang tala.",
                "start_ms": 57400,
                "end_ms": 64320
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Maaaring basahin nang malakas ang cards o gumamit ng gustong wika.",
                "start_ms": 64620,
                "end_ms": 69100
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Walang internet, projector, totoong resident record o upload na kailangan.",
                "start_ms": 69400,
                "end_ms": 75440
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Ulitin ang mahirap na bahagi bago magpatuloy.",
                "start_ms": 75740,
                "end_ms": 78940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Malinaw na pinagmulan at tapat na pagmarka sa kulang ang pumipigil sa hula na maging opisyal na tala.",
                "start_ms": 79240,
                "end_ms": 86440
              }
            ]
          }
        },
        "relevant-detail": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/relevant-detail.en.11baffeb4bf5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "11baffeb4bf57c03c17d29e5d8ad0f5c302a3d387304d634b00df2776c5451e1",
            "sha256": "708b0871ff1151adebe5b9b549af96ee5198f3e47e302aab258e1da25c1e8a89",
            "duration_seconds": 67.971,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Only relevant details",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“This is for an authorized household profile and health-service planning,” Gibs explains.",
                "start_ms": 2460,
                "end_ms": 8580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Only relevant information will be used by the authorized health team under local policy.",
                "start_ms": 8880,
                "end_ms": 14720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May we clarify the barrier to getting there?”",
                "start_ms": 15020,
                "end_ms": 18100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Liza chooses Filipino and a quieter place.",
                "start_ms": 18400,
                "end_ms": 22120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The access barrier is relevant to this task; gossip about the neighbor’s debt is not.",
                "start_ms": 22420,
                "end_ms": 28100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Real names or addresses are unnecessary on the rehearsal sheet.",
                "start_ms": 28400,
                "end_ms": 32560
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Do not guess missing entries on an official form.",
                "start_ms": 32860,
                "end_ms": 36580
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Explaining information use is not a promise of absolute secrecy.",
                "start_ms": 36880,
                "end_ms": 41720
              },
              {
                "zone": "body",
                "index": 8,
                "text": "For questions about correction, access or keeping records, ask the authorized custodian about the actual local process; do not invent a universal form or deletion date.",
                "start_ms": 42020,
                "end_ms": 54300
              },
              {
                "zone": "body",
                "index": 9,
                "text": "If immediate help is needed, follow the local process and do not delay it to finish the interview.",
                "start_ms": 54600,
                "end_ms": 61080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Record only what the authorized task needs; explain its use and follow local policy.",
                "start_ms": 61380,
                "end_ms": 67900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/relevant-detail.fil.b93d3bd10482.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b93d3bd104828bd02ac60a149831beb9cb67d9e88d924c3599db9986a8438e4c",
            "sha256": "51a41ca5570ba9eda16a5ba151c5d5fa943626949f8dfa1a3d360148b423b7ae",
            "duration_seconds": 73.535,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kaugnay na detalye lamang",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Para po ito sa awtorisadong household profile at pagpaplano ng serbisyong pangkalusugan,” paliwanag ni Gibs.",
                "start_ms": 2380,
                "end_ms": 9220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Kaugnay na impormasyon lamang ang gagamitin ng awtorisadong health team ayon sa lokal na patakaran.",
                "start_ms": 9520,
                "end_ms": 15600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaari po ba nating linawin ang hadlang sa pagpunta?”",
                "start_ms": 15900,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pinili ni Liza ang Filipino at isang mas tahimik na lugar.",
                "start_ms": 20360,
                "end_ms": 24440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang hadlang sa pagpunta ay kaugnay ng gawaing ito; ang tsismis tungkol sa utang ng kapitbahay ay hindi.",
                "start_ms": 24740,
                "end_ms": 32460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi kailangan ang tunay na pangalan o address sa papel ng pagsasanay.",
                "start_ms": 32760,
                "end_ms": 37120
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Huwag hulaan ang patlang sa opisyal na form.",
                "start_ms": 37420,
                "end_ms": 40220
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi pangako ng ganap na lihim ang paliwanag sa paggamit.",
                "start_ms": 40520,
                "end_ms": 44840
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Kung may tanong tungkol sa pagwawasto, access o pag-iingat ng rekord, itanong ang aktuwal na lokal na proseso sa awtorisadong tagapangasiwa; huwag mag-imbento ng iisang form o petsa ng pagbura.",
                "start_ms": 45140,
                "end_ms": 58380
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Kung kailangan ng agarang tulong, sundin ang lokal na proseso at huwag itong ipagpaliban para matapos ang interview.",
                "start_ms": 58680,
                "end_ms": 65600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itala lamang ang kailangan sa awtorisadong gawain; ipaliwanag ang gamit at sundin ang lokal na patakaran.",
                "start_ms": 65900,
                "end_ms": 73460
              }
            ]
          }
        },
        "sources": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/sources.en.3260609f5d0d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3260609f5d0d1b9837628121f8ed584af43d75870d6c79c49e8921fcd8bdb767",
            "sha256": "8a9898c46dfcb3153a4aeada5adc0896f5e9dbb91ae307021f09be61ea4fe879",
            "duration_seconds": 72.699,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Reported, observed, and unconfirmed",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gibs, a male BHW, visits Liza, 29, for an authorized household profile.",
                "start_ms": 3540,
                "end_ms": 10540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He asks permission and listens first.",
                "start_ms": 10840,
                "end_ms": 13560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Liza says: “Getting there is difficult when nobody can look after my two children.”",
                "start_ms": 13860,
                "end_ms": 19220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The neighbor says: “She is not interested.”",
                "start_ms": 19520,
                "end_ms": 23080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "This rehearsal is not an actual record.",
                "start_ms": 23380,
                "end_ms": 26260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Separate four columns: Liza’s report, the neighbor’s report, direct observations, and unconfirmed details.",
                "start_ms": 26560,
                "end_ms": 35280
              },
              {
                "zone": "body",
                "index": 6,
                "text": "When the appointment card is requested, Gibs observes that no card is shown during the conversation.",
                "start_ms": 35580,
                "end_ms": 41620
              },
              {
                "zone": "body",
                "index": 7,
                "text": "This does not prove that Liza had no appointment or did not attend.",
                "start_ms": 41920,
                "end_ms": 46640
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Gibs has not seen the authorized attendance record.",
                "start_ms": 46940,
                "end_ms": 50580
              },
              {
                "zone": "body",
                "index": 9,
                "text": "The visit date and status remain unconfirmed.",
                "start_ms": 50880,
                "end_ms": 54440
              },
              {
                "zone": "body",
                "index": 10,
                "text": "A nod, silence or glance toward the door is only an observation, not proof of agreement, refusal, feelings or a diagnosis.",
                "start_ms": 54740,
                "end_ms": 64940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "When assessing information, distinguish reports, observations and details still requiring verification.",
                "start_ms": 65240,
                "end_ms": 72640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/sources.fil.4e559b947e5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4e559b947e5bf11e5457d511489825a341ff0075f3dd8a8168f372f16d0c5cc4",
            "sha256": "25bc6e9aabbde9716073cea943ef122cdd9a197b571cdef22abe562cbf5eb1e6",
            "duration_seconds": 78.707,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sinabi, nakita, at hindi pa tiyak",
                "start_ms": 0,
                "end_ms": 4320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Gibs, isang lalaking BHW, ay bumisita kay Liza, 29, para sa awtorisadong household profile.",
                "start_ms": 4620,
                "end_ms": 13020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagpaalam siya at nakinig muna.",
                "start_ms": 13320,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sinabi ni Liza: “Mahirap pumunta kapag walang magbabantay sa dalawang anak ko.”",
                "start_ms": 16180,
                "end_ms": 21780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sabi ng kapitbahay: “Hindi siya interesado.”",
                "start_ms": 22080,
                "end_ms": 25760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa pagsasanay na ito, hindi ito aktuwal na rekord.",
                "start_ms": 26060,
                "end_ms": 29380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ihiwalay ang apat na hanay: sinabi ni Liza, iniulat ng kapitbahay, direktang nakita, at hindi pa natiyak.",
                "start_ms": 29680,
                "end_ms": 39040
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Nang hilingin ang appointment card, nakita ni Gibs na walang card na naipakita sa pag-uusap.",
                "start_ms": 39340,
                "end_ms": 45860
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Hindi nito pinatutunayang walang appointment o hindi pumunta si Liza.",
                "start_ms": 46160,
                "end_ms": 50960
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Hindi pa nakita ni Gibs ang awtorisadong attendance record.",
                "start_ms": 51260,
                "end_ms": 55220
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Ang petsa at status ng pagbisita ay hindi pa nakumpirma.",
                "start_ms": 55520,
                "end_ms": 59680
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Ang pagtango, pananahimik o pagtingin sa pinto ay obserbasyon lamang, hindi patunay ng pagsang-ayon, pagtanggi, damdamin o diagnosis.",
                "start_ms": 59980,
                "end_ms": 71020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa pagsusuri ng impormasyon, ihiwalay ang sinabi, nakita at kailangan pang beripikahin.",
                "start_ms": 71320,
                "end_ms": 78640
              }
            ]
          }
        },
        "verify-gap": {
          "en": {
            "src": "/training/audio/06-komunikasyon/communication-record/verify-gap.en.da33812a35a3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "da33812a35a3a29a2241f6d7d7f1e7b0489c05addf7711e024f352606d5abb3e",
            "sha256": "21e3a25c32a04a40d7266bf3b80ddf67a634512b17777605b80455f4641cdb3b",
            "duration_seconds": 78.942,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Verify the gap and correct honestly",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Incorrect initial note: “The center canceled the appointment.”",
                "start_ms": 3340,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It treats unconfirmed information as established.",
                "start_ms": 7360,
                "end_ms": 10880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gibs corrects the fictional practice sheet: “Liza first reported a canceled schedule.",
                "start_ms": 11180,
                "end_ms": 16700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Liza clarified during the conversation that she could not attend when her sister was away and was unsure whether the center canceled it.",
                "start_ms": 17000,
                "end_ms": 24800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "No card was shown.",
                "start_ms": 25100,
                "end_ms": 26700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Date and status: not yet confirmed.”",
                "start_ms": 27000,
                "end_ms": 29880
              },
              {
                "zone": "body",
                "index": 6,
                "text": "He does not replace one guess with another.",
                "start_ms": 30180,
                "end_ms": 32940
              },
              {
                "zone": "body",
                "index": 7,
                "text": "One suitable step is to ask the authorized midwife to check the relevant attendance record with him under the local access procedure.",
                "start_ms": 33240,
                "end_ms": 41520
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Ask only what is needed; do not investigate Liza’s entire life.",
                "start_ms": 41820,
                "end_ms": 46860
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Liza confirms the summary of her own report and is willing to clarify the date she remembers.",
                "start_ms": 47160,
                "end_ms": 53240
              },
              {
                "zone": "body",
                "index": 10,
                "text": "That is the confirmed ending of the conversation, not confirmation of attendance or a new appointment.",
                "start_ms": 53540,
                "end_ms": 60140
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Until suitable verification is available, keep the gap marked “not yet confirmed.”",
                "start_ms": 60440,
                "end_ms": 65640
              },
              {
                "zone": "body",
                "index": 12,
                "text": "In a real record, follow the local correction process and preserve the source of the change.",
                "start_ms": 65940,
                "end_ms": 71900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A correction keeps its source; a gap stays unconfirmed until suitable verification is available.",
                "start_ms": 72200,
                "end_ms": 78880
              }
            ]
          },
          "fil": {
            "src": "/training/audio/06-komunikasyon/communication-record/verify-gap.fil.b83fc1126c81.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b83fc1126c81cf2db63fd8c71f9f6aa254e398c24bbb4a470c6bc219179db8b3",
            "sha256": "48374458005f6dc00ee06daae786d62b1419b23967ab97309f5910578eb5ddca",
            "duration_seconds": 86.7,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Beripikahin ang kulang, itama nang tapat",
                "start_ms": 0,
                "end_ms": 3600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maling paunang tala: “Kinansela ng center ang appointment.”",
                "start_ms": 3900,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ginawa nitong tiyak ang hindi pa natiyak.",
                "start_ms": 9120,
                "end_ms": 11920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iwinasto ni Gibs sa kathang-isip na practice sheet: “Unang sinabi ni Liza: kinansela ang schedule.",
                "start_ms": 12220,
                "end_ms": 19940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Paglilinaw ni Liza sa pag-uusap: hindi siya nakapunta nang wala ang kapatid; hindi niya tiyak kung kinansela ng center.",
                "start_ms": 20240,
                "end_ms": 28000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang card na naipakita.",
                "start_ms": 28300,
                "end_ms": 30700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Petsa at status: hindi pa nakumpirma.”",
                "start_ms": 31000,
                "end_ms": 34120
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi niya pinalitan ang hula ng panibagong hula.",
                "start_ms": 34420,
                "end_ms": 38140
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Isang angkop na hakbang: hilingin sa awtorisadong midwife na tingnan kasama niya ang kaugnay na attendance record, ayon sa lokal na access procedure.",
                "start_ms": 38440,
                "end_ms": 47680
              },
              {
                "zone": "body",
                "index": 8,
                "text": "Tanungin lamang ang kailangan; hindi kailangang siyasatin ang buong buhay ni Liza.",
                "start_ms": 47980,
                "end_ms": 53300
              },
              {
                "zone": "body",
                "index": 9,
                "text": "Kinumpirma ni Liza ang buod ng sarili niyang sinabi at handa siyang linawin ang petsang naaalala niya.",
                "start_ms": 53600,
                "end_ms": 59880
              },
              {
                "zone": "body",
                "index": 10,
                "text": "Ito ang totoong pagtatapos ng pag-uusap, hindi kumpirmasyon ng attendance o bagong appointment.",
                "start_ms": 60180,
                "end_ms": 67020
              },
              {
                "zone": "body",
                "index": 11,
                "text": "Hangga’t wala ang angkop na beripikasyon, manatiling “hindi pa nakumpirma” ang puwang.",
                "start_ms": 67320,
                "end_ms": 73440
              },
              {
                "zone": "body",
                "index": 12,
                "text": "Sa totoong rekord, sundin ang lokal na proseso sa pagwawasto at panatilihin ang pinagmulan ng pagbabago.",
                "start_ms": 73740,
                "end_ms": 80020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagwawasto ay may pinagmulan; ang kulang ay hindi pa tiyak hangga’t walang angkop na beripikasyon.",
                "start_ms": 80320,
                "end_ms": 86640
              }
            ]
          }
        }
      }
    },
    "community-action-followup": {
      "module": "chapter2/06-community-mobilization",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/action.en.14d03f21570d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "14d03f21570dc07f723c8fe6c06b8f792bca9b336a76db89ff7217da825fb618",
            "sha256": "ee12cedc18221f3d17e7bff279f71309067b5ef1f925fc43b8d0f3010545e72b",
            "duration_seconds": 35.788,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Record the action, owner, resources and date.",
                "start_ms": 2340,
                "end_ms": 7620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Confirm resources instead of assuming they exist.",
                "start_ms": 7920,
                "end_ms": 12160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Agree on follow-up and a simple result measure.",
                "start_ms": 12460,
                "end_ms": 16780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask residents whether the method helped.",
                "start_ms": 17080,
                "end_ms": 20200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "When a commitment is missed, discuss the barrier respectfully and adjust the plan together.",
                "start_ms": 20500,
                "end_ms": 26940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Complete the group’s action plan. Add a timely-update measure and a response to an unfinished commitment.",
                "start_ms": 27240,
                "end_ms": 35720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/action.fil.134b82131cfb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "134b82131cfb88edae80b7ea0cc4f6715b4d0293b162307581e5531febdd9a03",
            "sha256": "5a9adb442f2e6308c0eee69a399491c4a851079f835e998e0861e9259944871a",
            "duration_seconds": 39.941,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itala ang gagawin, responsable, kailangan at petsa.",
                "start_ms": 2340,
                "end_ms": 8860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kumpirmahin muna ang resources; huwag ipalagay na mayroon.",
                "start_ms": 9160,
                "end_ms": 14040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magkasundo sa follow-up at simpleng panukat ng resulta.",
                "start_ms": 14340,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tanungin ang residente kung nakatulong ang paraan.",
                "start_ms": 19280,
                "end_ms": 22960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may hindi nagawa, alamin ang hadlang nang magalang at baguhin ang plano kasama nila.",
                "start_ms": 23260,
                "end_ms": 29660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Punan ang action plan ng grupo. Magdagdag ng panukat sa napapanahong balita at tugon kapag may hindi nakatapos.",
                "start_ms": 29960,
                "end_ms": 39880
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/check-start.en.d6f85dc0d652.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d6f85dc0d652a068678129a382bcb6d430da9d8810b510b7de58624169692683",
            "sha256": "a089b84751ff994c86e433e85d9fdf3fce5b701cd7a678fdb99d9af751708f9f",
            "duration_seconds": 12.696,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 4780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5080,
                "end_ms": 8640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This makes the agreement specific and reviewable.",
                "start_ms": 8940,
                "end_ms": 12620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/check-start.fil.7946e964d3dd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7946e964d3ddc4cb8440ff2a5ab3921a0e909b73a738415521a200249ea6efeb",
            "sha256": "2dba9fc302e85c1907259ddc4521d5a68b433e5c64413ca484c244c3e167e09e",
            "duration_seconds": 15.438,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2940,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5400,
                "end_ms": 10360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ginagawang malinaw at masusuri ang napagkasunduan.",
                "start_ms": 10660,
                "end_ms": 15380
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/check-transfer.en.ddab6f72b552.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ddab6f72b552d16977f62d9d28fe0cc010b1b06b2a2cbf1322f021bc2628446b",
            "sha256": "a8596173985ef8ef1dfdb1005f9cdc4b11cbbbe520c19238dfa941a2a8d5a10b",
            "duration_seconds": 13.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2660,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This maintains accountability while addressing the actual problem.",
                "start_ms": 8140,
                "end_ms": 13060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/check-transfer.fil.240ba152b34d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "240ba152b34d991ff3db6c8b00e9169167811eff4528d9a1297dcc8079221c80",
            "sha256": "b0969601fab5c063a55aab37b69211ac4f52b74eada0cd1a6434d198b375645a",
            "duration_seconds": 14.315,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2700,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4720,
                "end_ms": 8320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pinananatili ang pananagutan habang inaayos ang aktuwal na problema.",
                "start_ms": 8620,
                "end_ms": 14260
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/example.en.fb2b623edb5d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fb2b623edb5d35079bd8972603326fea1920247b0a7ffca6e5dca106b10dd1d5",
            "sha256": "85d8d931771d3942d67e6ab8ef0dc0b732a04b0af2e4d31d2c5e88eaed6fce85",
            "duration_seconds": 36.833,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Plan: Ina confirms the time with the BHS.",
                "start_ms": 1940,
                "end_ms": 6300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Volunteers deliver invitations before the agreed day.",
                "start_ms": 6600,
                "end_ms": 10800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "At follow-up, they ask whether residents received and understood the update before the visit.",
                "start_ms": 11100,
                "end_ms": 18140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Short of paper?",
                "start_ms": 18440,
                "end_ms": 20040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Confirm another method first.",
                "start_ms": 20340,
                "end_ms": 23060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A member who could not finish is not shamed.",
                "start_ms": 23360,
                "end_ms": 27040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Includes an action, owner, resource confirmation, date, measure and respectful community follow-up.",
                "start_ms": 27340,
                "end_ms": 36780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/example.fil.555120c42445.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "555120c42445b46af04df71198c96aafaa616825959e09f4a8b1cdd95d73701c",
            "sha256": "6a03b0988ba5e66244fb1aba1149b963b1ee5d03011eea6714bf42c507a4642d",
            "duration_seconds": 40.124,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Plano: kukumpirmahin ni Ina ang oras sa BHS.",
                "start_ms": 1980,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihahatid ng boluntaryong grupo ang paanyaya bago ang napiling araw.",
                "start_ms": 7280,
                "end_ms": 12640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa follow-up, itatanong kung natanggap at naunawaan ang balita bago ang pagbisita.",
                "start_ms": 12940,
                "end_ms": 19660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kulang ang papel?",
                "start_ms": 19960,
                "end_ms": 21600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kumpirmahin muna ang ibang paraan.",
                "start_ms": 21900,
                "end_ms": 24860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi ipapahiya ang kasaping hindi nakatapos.",
                "start_ms": 25160,
                "end_ms": 29280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May gawain, responsable, kumpirmasyon ng resources, petsa, panukat at magalang na follow-up kasama ang komunidad.",
                "start_ms": 29580,
                "end_ms": 40060
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/next-step.en.ce1d2ede6d77.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ce1d2ede6d77fb55d308d481e8ae82ecb339722a736483689878423507b0c048",
            "sha256": "a9cad4a98bf08ab17a394825fd327adc37c08155ee82b784b6b89a520493f43e",
            "duration_seconds": 31.713,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The group has actions, owners, dates and a measure.",
                "start_ms": 2700,
                "end_ms": 8060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, ask a colleague to review the fictional action plan.",
                "start_ms": 8360,
                "end_ms": 13200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: accountability — fulfilling and respectfully following up agreed responsibilities.",
                "start_ms": 13500,
                "end_ms": 21380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If results fall short, plan again with affected people.",
                "start_ms": 21680,
                "end_ms": 26600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, ask a colleague to review the fictional action plan.",
                "start_ms": 26900,
                "end_ms": 31660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/next-step.fil.9a4c42bed3ea.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9a4c42bed3ea149dc890949f41d4c4087193e6644a741775ca84680cd2265602",
            "sha256": "d5862828a67cb8687fe2d5f0e14dba72576340355860dc92fbef2bab26521347",
            "duration_seconds": 35.892,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May gagawin, responsable, petsa at panukat na ang grupo.",
                "start_ms": 2540,
                "end_ms": 9700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, ipasuri sa katrabaho ang action plan para sa kathang-isip na kaso.",
                "start_ms": 10000,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: pananagutan — pagtupad at magalang na pagbalik sa napagkasunduang tungkulin.",
                "start_ms": 16420,
                "end_ms": 24620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kapag kulang ang resulta, magplano muli kasama ang apektado.",
                "start_ms": 24920,
                "end_ms": 30000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, ipasuri sa katrabaho ang kathang-isip na action plan.",
                "start_ms": 30300,
                "end_ms": 35820
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/scene.en.e8d71284ec3c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e8d71284ec3c76552c8a1bc6b8783a66317120ba37ef7dd353210610200411c0",
            "sha256": "f106c4c3845d3533cdc511f867ee2035d59622379949c06242519293c435d308",
            "duration_seconds": 25.652,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The group agrees on personal invitations for people without phones.",
                "start_ms": 2220,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Someone calls the effort successful because many attended the meeting.",
                "start_ms": 7360,
                "end_ms": 11920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "It is not yet known whether updates reached people in time.",
                "start_ms": 12220,
                "end_ms": 16420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The group needs clear actions and a way to review results.",
                "start_ms": 16720,
                "end_ms": 21560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "An action plan and result measure are needed.",
                "start_ms": 21860,
                "end_ms": 25580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/scene.fil.88193ee23810.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "88193ee23810b748750d72f409dc012c83967709c9cd78bfd0f40b8db4e0234d",
            "sha256": "07778dfb573cd3720023d683f3f4b3dc164210cc405963bd6a6c8f923e3f6d07",
            "duration_seconds": 30.328,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 4400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Napagkasunduan ng grupo ang personal na paanyaya para sa walang cellphone.",
                "start_ms": 4700,
                "end_ms": 9900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May gustong magsabing matagumpay na dahil marami ang dumalo sa pulong.",
                "start_ms": 10200,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa alam kung nakarating sa oras ang balita.",
                "start_ms": 16420,
                "end_ms": 20340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kailangan ng grupo ng malinaw na gagawin at paraan ng pagsusuri.",
                "start_ms": 20640,
                "end_ms": 26160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan ng plano at panukat ng resulta.",
                "start_ms": 26460,
                "end_ms": 30260
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/scope.en.f232cc69516b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f232cc69516b15ec3bfc9786e9f5eda6984c3f9483ac7aaf3c7d3999cab09ec1",
            "sha256": "30f60ffd83417dc998def585b171bea31b0fa7e0701076eed393ad598ce93491",
            "duration_seconds": 30.485,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not promise unconfirmed funds, transport or services.",
                "start_ms": 2540,
                "end_ms": 7540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use combined counts and avoid publishing personal reasons for nonattendance.",
                "start_ms": 7840,
                "end_ms": 13720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Measures should support improvement, not punishment.",
                "start_ms": 14020,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask the organizer to confirm required permissions and reporting arrangements.",
                "start_ms": 18360,
                "end_ms": 24040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Promise nothing unconfirmed; measures support improvement, not punishment.",
                "start_ms": 24340,
                "end_ms": 30420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-action-followup/scope.fil.20e5a9582bba.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "20e5a9582bba0fea8de3f90662cb8dd887e09d91fcbbbc12e147a7fef908e89d",
            "sha256": "748861bc4e29553da80dc5115997a8cbeda1354d200a0823e526180d1f8d245a",
            "duration_seconds": 35.553,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag mangako ng pondo, sasakyan o serbisyo na hindi pa kumpirmado.",
                "start_ms": 3180,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gumamit ng pinagsamang bilang at iwasang ilathala ang personal na dahilan ng hindi pagdalo.",
                "start_ms": 9720,
                "end_ms": 16240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang panukat ay dapat makatulong sa pagpapabuti, hindi sa pagparusa.",
                "start_ms": 16540,
                "end_ms": 21900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipasuri sa organizer ang kailangang pahintulot at paraan ng pag-uulat.",
                "start_ms": 22200,
                "end_ms": 27560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang pangakong hindi kumpirmado; panukat para sa pagpapabuti, hindi parusa.",
                "start_ms": 27860,
                "end_ms": 35500
              }
            ]
          }
        }
      }
    },
    "community-issue": {
      "module": "chapter2/06-community-mobilization",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/action.en.c718341bb258.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c718341bb2588fecb1ef19f070bf9e3a51e622b1599e3634994a78e66a1b7620",
            "sha256": "a6ee279eb05a15ea7665859c012d860b737574c09f116f0edb8e2349b7ab0a24",
            "duration_seconds": 37.433,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hear affected people before choosing a solution.",
                "start_ms": 2540,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Separate reports from assumptions.",
                "start_ms": 6680,
                "end_ms": 9960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask whose voice is missing.",
                "start_ms": 10260,
                "end_ms": 13020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Together, state what is happening, who is affected and what evidence exists.",
                "start_ms": 13320,
                "end_ms": 19800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mark what remains unknown.",
                "start_ms": 20100,
                "end_ms": 22660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Community members share decisions rather than simply receiving instructions.",
                "start_ms": 22960,
                "end_ms": 28840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Make an issue card: reported concern, affected people, missing voices and the next question.",
                "start_ms": 29140,
                "end_ms": 37380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/action.fil.81b040edcd29.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81b040edcd29e689bb372cb4f6f0db2f232890f6789962e8f251860c6eab9845",
            "sha256": "7bc8c916d7f7e550fe82e94d7b235649df5acacd645ffd2d644ab414929dd9ba",
            "duration_seconds": 42.658,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pakinggan ang mga apektado bago pumili ng solusyon.",
                "start_ms": 2500,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihiwalay ang iniulat sa hula.",
                "start_ms": 7080,
                "end_ms": 10440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itanong kung sino pa ang hindi naririnig.",
                "start_ms": 10740,
                "end_ms": 14100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Bumuo kasama nila ng maikling pahayag: ano ang nangyayari, kanino at anong ebidensiya ang mayroon.",
                "start_ms": 14400,
                "end_ms": 22680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Markahan ang hindi pa alam.",
                "start_ms": 22980,
                "end_ms": 25580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang komunidad ay kasamang nagpapasya, hindi tagatanggap lamang ng utos.",
                "start_ms": 25880,
                "end_ms": 31640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumawa ng issue card: ano ang naiulat, sino ang apektado, sino ang hindi pa naririnig at ano ang itatanong.",
                "start_ms": 31940,
                "end_ms": 42580
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/check-start.en.4cbedb2f14e5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4cbedb2f14e5c3b96a3b92915fd0a6cd1453026a438b72a51f694f362571d41f",
            "sha256": "d3b7d6d900450cd3d6d38b2a72361069b1b728bba977cebbcb59d2f45a48f692",
            "duration_seconds": 15.856,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2700,
                "end_ms": 5180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5480,
                "end_ms": 9240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This is the specific report; its extent and causes still need clarification.",
                "start_ms": 9540,
                "end_ms": 15780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/check-start.fil.2d9481ebffdd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2d9481ebffdd66d0348ca7fefcea4a6d671bd2801bc4487e8170b4c9191fab81",
            "sha256": "c8190289c26d17c8edb04a6b2c9ae60e847e7c18f6fd3ae26d3f384743fe54f4",
            "duration_seconds": 16.118,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2580,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 4720,
                "end_ms": 9400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ito ang tiyak na naiulat; kailangan pang linawin ang lawak at dahilan.",
                "start_ms": 9700,
                "end_ms": 16060
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/check-transfer.en.7c6bc1ac3227.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7c6bc1ac3227a0296d93beb48f76743b6dd6082813043990a84f45ceddbe4ba2",
            "sha256": "1c9af80b43cd60a6cca9835bc524f64f498f97b43a09de9a9fc2136064547817",
            "duration_seconds": 11.964,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2780,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4840,
                "end_ms": 7480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Affected people help identify a workable solution.",
                "start_ms": 7780,
                "end_ms": 11900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/check-transfer.fil.3b5c403142ff.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3b5c403142ff988bc858f00350c5d7e674ec798ee57bb901b03afe5bec7b6088",
            "sha256": "781e030c6e2bcd6912a42e84cfd9b6946b5425398873351e7812e584883f881b",
            "duration_seconds": 17.136,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 5240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 5540,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 7960,
                "end_ms": 11320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kasama ang apektado sa pagtukoy ng magagamit na solusyon.",
                "start_ms": 11620,
                "end_ms": 17060
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/example.en.25cfde4e38c8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "25cfde4e38c84224cb0fd4bc19d6f60d5c38ed7c120e854912a6e62e93999a98",
            "sha256": "d93e68197f9b0f4c2fdbd8b3f124a24865a2ac0e41da20960402cc56635f523a",
            "duration_seconds": 30.929,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The group writes: “Three residents report learning the new time late.",
                "start_ms": 2100,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "We do not yet know how people without phones receive updates.”",
                "start_ms": 7600,
                "end_ms": 12040
