            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In fictional Purok Maligaya, three residents say they learned about a BHS schedule change too late.",
                "start_ms": 1940,
                "end_ms": 9740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A leader says, “They just refuse to follow.”",
                "start_ms": 10040,
                "end_ms": 13280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "BHW Ina has not heard from people without phones or those working during the day.",
                "start_ms": 13580,
                "end_ms": 20940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "What is the actual issue?",
                "start_ms": 21240,
                "end_ms": 23600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Whose voice is missing?",
                "start_ms": 23900,
                "end_ms": 26020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/scene.fil.c7441d9df74e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c7441d9df74ef575a7d4a90b304dc200387f089fab2c96140843ab7cfd631bd6",
            "sha256": "f27a18a137de87ecc66abdaa04310d1a72eecd7d4eecee250934afebb0e15900",
            "duration_seconds": 27.246,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na Purok Maligaya, tatlong residente ang nagsabing huli nilang nalaman ang pagbabago ng oras sa BHS.",
                "start_ms": 1860,
                "end_ms": 10220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sabi ng isang lider, “Ayaw lang nilang sumunod.”",
                "start_ms": 10520,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi pa naririnig ni BHW Ina ang mga walang cellphone at nagtatrabaho sa araw.",
                "start_ms": 14660,
                "end_ms": 21780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ano ang tunay na isyu?",
                "start_ms": 22080,
                "end_ms": 24280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sino pa ang hindi naririnig?",
                "start_ms": 24580,
                "end_ms": 27180
