        "scope": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/scope.en.eac8885d49b3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eac8885d49b3e1494064fd7edf2294f29cb1b3d7084821a06e4ee73123b125a1",
            "sha256": "65e681ab3a12daf65c0b6610565086a084c5a5e81086ca094551d0114bda0bb6",
            "duration_seconds": 31.843,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Community mobilization involves identifying needs, acting and reviewing results together.",
                "start_ms": 2460,
                "end_ms": 9900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "People do not need to disclose personal circumstances publicly.",
                "start_ms": 10200,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Use combined, non-identifying information.",
                "start_ms": 15460,
                "end_ms": 19180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "For sensitive concerns, ask whether a small, private conversation is more appropriate.",
                "start_ms": 19480,
                "end_ms": 25920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Decide with the community; no one has to share personal circumstances publicly.",
                "start_ms": 26220,
                "end_ms": 31780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/community-issue/scope.fil.237a852028ea.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "237a852028ea6191433f1f30dcd18ad81d7d9cab56afbd043273a369f3ca5159",
            "sha256": "31aab0ff92a283e94c341075a3bc3579d64842e699fe79e2aa20dcfc0eb0b335",
            "duration_seconds": 37.12,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang community mobilization ay sama-samang pagtukoy, pagkilos at pagsusuri sa lokal na pangangailangan.",
                "start_ms": 3380,
                "end_ms": 11900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi kailangan ang pampublikong pagsasalaysay ng personal na kalagayan.",
                "start_ms": 12200,
                "end_ms": 17960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gumamit ng pinagsama at hindi makikilalang impormasyon.",
                "start_ms": 18260,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung sensitibo ang isyu, itanong kung ang maliit at pribadong usapan ang mas angkop.",
                "start_ms": 23640,
                "end_ms": 30360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kasama ang komunidad sa pagpapasya; walang sapilitang pampublikong personal na kuwento.",
                "start_ms": 30660,
                "end_ms": 37060
              }
            ]
          }
        }
      }
