    "convulsion-response": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/action.en.49a3f163004f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "49a3f163004f88c074b77c1be8db260efa068176d6ec83f616f3780b3928ebc9",
            "sha256": "9722b43ebc5469ea8eada73528663cc12e3e7eed583b56f38fcf1dab713582e2",
            "duration_seconds": 29.597,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Clear nearby hazards, cushion the head if possible and note the start time.",
                "start_ms": 2900,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Seek urgent help for a child and monitor breathing after the episode.",
                "start_ms": 9360,
                "end_ms": 14640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Give the responding clinician a factual description.",
                "start_ms": 14940,
                "end_ms": 19020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clear a simulated space, call for help, state time and observations, and reject restraint and mouth insertion.",
                "start_ms": 19320,
                "end_ms": 29520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/action.fil.d0a90e1f2761.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d0a90e1f2761fbbb8ba97707809bfd6590696f867de7fcef444893bea91d8b5f",
            "sha256": "ba10608762e07db185e5b3e3766097586f621736c4b4c9c52e9bf9218f07b163",
            "duration_seconds": 32.496,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Alisin ang panganib sa paligid, sapinan ang ulo kung kaya at tandaan ang oras ng simula.",
                "start_ms": 2220,
                "end_ms": 9780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Humingi agad ng tulong para sa bata at bantayan ang paghinga pagkatapos.",
                "start_ms": 10080,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ibigay sa rumespondeng clinician ang factual na paglalarawan ng nakita.",
                "start_ms": 16020,
                "end_ms": 21540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Linisin ang paligid sa simulation, humingi ng tulong, sabihin ang oras at nakita, at tanggihan ang pagpigil at kutsara.",
                "start_ms": 21840,
                "end_ms": 32440
              }
            ]
          }
        },
