            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2740,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5200,
                "end_ms": 9120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Clear hazards and cushion the head; never restrain or use a spoon.",
                "start_ms": 9420,
                "end_ms": 15100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/check-start.fil.2c3ca831b764.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2c3ca831b7645768c2be6c5617e5491eaf9a4d5b5b6a91896944b130381eac50",
            "sha256": "b0f45c1b6b449cbcdf613eb0acb176dc69062eddf2fa68f8d1d9054f8d512f16",
            "duration_seconds": 16.953,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2200
