                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5000,
                "end_ms": 9640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alisin ang panganib at sapinan ang ulo; huwag pigilan o gumamit ng kutsara.",
                "start_ms": 9940,
                "end_ms": 16900
              }
            ]
          }
        },
