            "duration_seconds": 15.334,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3180,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5280,
                "end_ms": 8600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pagkatapos: walang ipaiinom bago lubos na magkamalay; bantayan ang paghinga.",
