            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW kindly tells the neighbor not to hold the child down or put a spoon in the mouth.",
                "start_ms": 2100,
                "end_ms": 9620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She moves nearby hazards, cushions the head and says the start time aloud.",
                "start_ms": 9920,
                "end_ms": 15920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She has someone call the confirmed contact and watches breathing after the shaking stops.",
                "start_ms": 16220,
                "end_ms": 22740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The clinician gets a factual description: the start time and what was seen.",
                "start_ms": 23040,
                "end_ms": 28360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Decline restraint and the spoon; protect, time, call and describe.",
                "start_ms": 28660,
                "end_ms": 35940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/convulsion-response/example.fil.86d63af6e522.mp3",
