            "sha256": "427aeb58f6c2e773f0a40ba6f944ab509e5cec9dd2dc96f4e0f07a547fdbf46a",
            "duration_seconds": 40.725,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mahinahong sinabi ng BHW sa kapitbahay na huwag pigilan ang bata o lagyan ng kutsara ang bibig.",
                "start_ms": 2100,
                "end_ms": 10260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inalis niya ang panganib sa paligid, sinapinan ang ulo at sinabi nang malakas ang oras ng simula.",
                "start_ms": 10560,
                "end_ms": 18840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nagpatawag siya sa kumpirmadong contact at binantayan ang paghinga pagkatapos ng pangingisay.",
                "start_ms": 19140,
                "end_ms": 26620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Factual ang ulat sa clinician: ang oras ng simula at ang nakita.",
                "start_ms": 26920,
                "end_ms": 32440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tanggihan ang pagpigil at kutsara; protektahan, orasan, tumawag at iulat.",
                "start_ms": 32740,
                "end_ms": 40660
              }
            ]
          }
        },
