            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag pigilan ang bata o maglagay ng anuman sa bibig.",
                "start_ms": 3220,
                "end_ms": 7660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag magpakain o magpainom bago siya lubos na magkamalay.",
                "start_ms": 7960,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag umasa sa pagpupunas ng malamig na tubig para mapatigil ang kombulsyon.",
                "start_ms": 13220,
                "end_ms": 18780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang pagpigil, walang anuman sa bibig, walang pagkain o inumin bago lubos na magkamalay.",
                "start_ms": 19080,
                "end_ms": 27400
              }
            ]
          }
        }
      }
    },
    "cough-etiquette": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/action.en.b050a0be7bb1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b050a0be7bb1c7adf0cae39c987fc6c707b372f52932a57cc3644af741bc5efc",
            "sha256": "20c738de9e856926a1c2d225c53f4c9de7c74f3dab579ca725f1ce1b834e34f2",
            "duration_seconds": 33.228,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Cover nose and mouth with a tissue when coughing or sneezing.",
                "start_ms": 2540,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Without tissue, use the inside of a bent elbow rather than hands.",
                "start_ms": 7480,
                "end_ms": 12440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Discard used tissue in the designated bin.",
                "start_ms": 12740,
                "end_ms": 16100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Clean hands after contact with respiratory secretions.",
                "start_ms": 16400,
                "end_ms": 20720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report symptoms to staff and follow their instructions.",
                "start_ms": 21020,
                "end_ms": 25140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mime tissue and elbow methods. Show disposal and hand hygiene; explain reporting to staff.",
                "start_ms": 25440,
                "end_ms": 33160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/action.fil.677636c3e3fd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "677636c3e3fda4f2d1c6ffd9c5cb8afb7bdd2520c2b8d5a9c319cc6debbe48f6",
            "sha256": "77157bf1e83881ce0ff0b3e58a4609a483422545219e607de468705942d20741",
            "duration_seconds": 39.393,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Takpan ang ilong at bibig gamit ang tissue kapag umuubo o bumabahing.",
                "start_ms": 2420,
                "end_ms": 8540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung walang tissue, gamitin ang loob ng nakabaluktot na siko, hindi ang palad.",
                "start_ms": 8840,
                "end_ms": 14720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itapon ang ginamit na tissue sa itinalagang basurahan.",
                "start_ms": 15020,
                "end_ms": 19060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Linisin ang kamay matapos mahawakan ang sipon o laway.",
                "start_ms": 19360,
                "end_ms": 24040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipaalam ang sintomas sa staff at sundin ang kanilang tagubilin.",
                "start_ms": 24340,
                "end_ms": 29220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gayahin ang tissue at elbow methods. Ipakita ang pagtatapon at hand hygiene; ipaliwanag ang pag-uulat sa staff.",
                "start_ms": 29520,
                "end_ms": 39320
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-start.en.cf5abf76bb2c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf5abf76bb2cde4de67fa9acb298e9c220c1e7a55b17b76569ea3779a44e4d79",
            "sha256": "bc33e2f4a63ee1fd73892005101643b266f52d9d0a087bff8f1caa4809a5369f",
            "duration_seconds": 13.531,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2820,
                "end_ms": 5220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5520,
                "end_ms": 8960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This covers nose and mouth without using hands.",
                "start_ms": 9260,
                "end_ms": 13460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-start.fil.a5aae9f00f05.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a5aae9f00f05dddad27e7f89e25a82d1ab439908d779a5dca51b144b665bdbe0",
            "sha256": "40eba7b1ec8e9e91a564175b0f9994ff148547f6f8d296bfe99c2bab2732f26f",
            "duration_seconds": 15.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2900,
                "end_ms": 5260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5560,
                "end_ms": 10360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Natatakpan ang ilong at bibig nang hindi ginagamit ang palad.",
                "start_ms": 10660,
                "end_ms": 15060
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-transfer.en.408a1dda4a79.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "408a1dda4a79f4a057989ad3470c86025e86ba9fc6ae76261faaf0896320ec98",
            "sha256": "d2d6049df6667a487dedc80744b5a661e7035a50e9412340ff42112476cb64cf",
            "duration_seconds": 11.807,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2740,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hand hygiene is part of the complete sequence.",
                "start_ms": 8180,
                "end_ms": 11740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/check-transfer.fil.e34bd4598481.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e34bd45984811d76d5ff0b35fd490483383abf00421a033e2bcc819a551bdc7e",
            "sha256": "4b99e801bab5cb808d12d0b0cbad990bd9beabb3c17748f123864161780be1a3",
            "duration_seconds": 13.923,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 4180,
                "end_ms": 5940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 6240,
                "end_ms": 9560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bahagi ng kumpletong sequence ang hand hygiene.",
                "start_ms": 9860,
                "end_ms": 13860
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/example.en.e6f09eaf1813.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6f09eaf1813ece20425e5b48d6f51ffe0a1a8b37511208e278f425ed556793b",
            "sha256": "a952b82803c3c1e9edb58d3ff7e557967d7517b87527a81b7eb7437f05c6ae17",
            "duration_seconds": 34.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rina: “Tissues are available here.",
                "start_ms": 2100,
                "end_ms": 4940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If none are available, sneeze into your elbow.”",
                "start_ms": 5240,
                "end_ms": 8880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She points out the bin and hand-hygiene station.",
                "start_ms": 9180,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She reports symptoms and asks staff about the waiting area.",
                "start_ms": 12840,
                "end_ms": 17200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Follow the facility protocol and staff assistance for a recommended mask.",
                "start_ms": 17500,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She does not diagnose Mang Lito.",
                "start_ms": 23640,
                "end_ms": 26520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Rina offers a tissue or the elbow, points to the bin and hand hygiene, and reports to staff.",
                "start_ms": 26820,
                "end_ms": 34220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/example.fil.01a6166d8be4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "01a6166d8be42ecef63fce1db6a637d9b548c8e6b7ab310fae13707d4e666b59",
            "sha256": "b98243dec1617dc59dc6a47e1518e38324919b2a3b179460c0173d9a726e9740",
            "duration_seconds": 36.441,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rina: “May tissue po rito.",
                "start_ms": 1980,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung wala, sa siko po tayo bumahing.”",
                "start_ms": 5000,
                "end_ms": 8240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinuro niya ang basurahan at hand-hygiene station.",
                "start_ms": 8540,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipinaalam niya sa staff ang sintomas at tinanong ang waiting area.",
                "start_ms": 12840,
                "end_ms": 17720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may inirerekomendang mask, sundin ang facility protocol at tulong ng staff.",
                "start_ms": 18020,
                "end_ms": 23940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi niya pinangalanan ang sakit ni Mang Lito.",
                "start_ms": 24240,
                "end_ms": 27360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nag-alok si Rina ng tissue o siko, itinuro ang basurahan at hand hygiene, at nag-ulat sa staff.",
                "start_ms": 27660,
                "end_ms": 36380
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/next-step.en.af54b9c2cc0e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "af54b9c2cc0eed4ec84a403d769e58c6a9f9d6ab2e4961c297b19d75d14887e2",
            "sha256": "a49b1b3f577f81910a721420188314c788c718e0b7b50692b1e711b7163d2b7b",
            "duration_seconds": 30.276,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rina demonstrates both tissue and elbow methods, disposal and hand hygiene.",
                "start_ms": 2220,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, practise both methods with clean props under observation.",
                "start_ms": 8920,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: cough etiquette — actions that reduce spread of respiratory secretions.",
                "start_ms": 14460,
                "end_ms": 21220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Include respectful explanation and reporting.",
                "start_ms": 21520,
                "end_ms": 25120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Demonstrate both methods with clean props under observation.",
                "start_ms": 25420,
                "end_ms": 30220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/next-step.fil.f947c355bb71.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f947c355bb711cc0fe127e41cb634f786331a9e18403d6f9e923d6970ec6cf38",
            "sha256": "61bf49411d1368d060c936680b40531e145e5493e0119414655f93ebc2d05688",
            "duration_seconds": 33.881,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naipakita ni Rina ang tissue at siko, pagtatapon at hand hygiene.",
                "start_ms": 2900,
                "end_ms": 8940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, magpaobserba ng dalawang paraan gamit ang malinis na props.",
                "start_ms": 9240,
                "end_ms": 15000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: cough etiquette — kilos na nagpapababa ng pagkalat ng respiratory secretions.",
                "start_ms": 15300,
                "end_ms": 23060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Isama ang magalang na paliwanag at pag-uulat.",
                "start_ms": 23360,
                "end_ms": 27440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipakita ang dalawang paraan gamit ang malinis na props habang inoobserbahan.",
                "start_ms": 27740,
                "end_ms": 33820
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/scene.en.884c9bc5fdb7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "884c9bc5fdb7cf8cf7c9fcd69dbf625c6910fa19e859dbfdb2b6853a24141abd",
            "sha256": "7b71e63ec0b1dd964754f13072f411f1eea86670296a9a707e9df059b18f93fd",
            "duration_seconds": 24.973,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In a role-play, Mang Lito is about to sneeze in the waiting area.",
                "start_ms": 1980,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He has no tissue in his pocket.",
                "start_ms": 7880,
                "end_ms": 10680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tissues and a bin are available at the station.",
                "start_ms": 10980,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "BHW Rina will help without embarrassing him or asking him to cough toward anyone.",
                "start_ms": 15120,
                "end_ms": 22160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "How can you help respectfully?",
                "start_ms": 22460,
                "end_ms": 24900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/scene.fil.499762b8d476.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "499762b8d476c251dd547597169c160be0ea09b6c07dfc07639bf668b72f82b9",
            "sha256": "6e769ee36b83512afe763086f6d102f3776cee888900ef6bb07c5f5a9771c217",
            "duration_seconds": 22.805,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa role-play, babahing si Mang Lito sa waiting area.",
                "start_ms": 2260,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Wala siyang tissue sa bulsa.",
                "start_ms": 6560,
                "end_ms": 9080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May tissue at basurahan sa station.",
                "start_ms": 9380,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tutulong si BHW Rina nang hindi siya pinapahiya o hinihiling na umubo sa ibang tao.",
                "start_ms": 12760,
                "end_ms": 19640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Paano tutulong nang may respeto?",
                "start_ms": 19940,
                "end_ms": 22740
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/cough-etiquette/scope.en.24516d40a5c0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "24516d40a5c0425a0f3459d741c856ff8c12752b0ef7f6489566c65ea7869a3e",
            "sha256": "e69d026842e2c2be3c04caf1f314a559a86a7d7a67c3ed876859a6b72f6a8259",
            "duration_seconds": 29.336,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mime the actions; do not actually cough or spit toward a partner.",
                "start_ms": 2420,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not handle someone else’s used tissue outside the appropriate procedure.",
                "start_ms": 7800,
                "end_ms": 13360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Covering your own mouth when another person coughs does not replace respiratory controls.",
                "start_ms": 13660,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Protect privacy when reporting.",
                "start_ms": 20120,
                "end_ms": 22640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mime only; never cough toward a partner, and protect privacy when reporting.",
                "start_ms": 22940,
                "end_ms": 29260
