    "diarrhea-dehydration": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/action.en.7e568f9d4e59.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7e568f9d4e599d2317b83234635e1845ad121ed54ddea83dfb4bf0a20ca77d39",
            "sha256": "239c16b6822363a146abe7598cc95fd6d7fdc0ec654b2b068d64a688320c3a0d",
            "duration_seconds": 34.482,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ask about ability to drink, vomiting, blood in stool and alertness.",
                "start_ms": 2380,
                "end_ms": 8300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Encourage continued breastfeeding when the child can feed.",
                "start_ms": 8600,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Explain that packaged ORS uses safe water and the exact packet directions.",
                "start_ms": 13020,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Refer urgently for danger signs or dehydration concerns.",
                "start_ms": 20040,
                "end_ms": 25160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use the packet label in a dry simulation, explain safe water and continued feeding, and identify a referral trigger.",
                "start_ms": 25460,
                "end_ms": 34420
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/action.fil.c7b6f091824a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c7b6f091824a683e16646568f2cbc1a07156b431255e5ef1a6564a1c06937da8",
            "sha256": "6bc1501b2525c096f323c98b2fb1962ede7ef3afebb5352ff556d998cf084cb6",
            "duration_seconds": 36.493,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itanong ang pag-inom, pagsusuka, dugo sa dumi at kamalayan.",
                "start_ms": 2300,
                "end_ms": 7740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hikayatin ang patuloy na pagpapasuso kung kayang sumuso ng bata.",
                "start_ms": 8040,
                "end_ms": 13480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipaliwanag na ligtas na tubig at eksaktong panuto ng sachet ang gamit sa ORS.",
                "start_ms": 13780,
                "end_ms": 20220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "I-refer agad kung may danger sign o alalahanin sa dehydration.",
                "start_ms": 20520,
                "end_ms": 25600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gamitin ang label ng sachet sa dry simulation, ipaliwanag ang ligtas na tubig at pagpapasuso, at tukuyin ang referral trigger.",
                "start_ms": 25900,
                "end_ms": 36420
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/check-start.en.a16b0e3308d2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a16b0e3308d27671305abeb1d7840436a1a151b9c361b62a843a73406ee619e8",
            "sha256": "61892a3a4f72f355fb0de8fa37e161f5324035f0004332da558ba87e5578ade5",
            "duration_seconds": 15.569,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2460,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5000,
                "end_ms": 8480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask about drinking, vomiting, blood in stool and alertness first.",
                "start_ms": 8780,
                "end_ms": 15500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/check-start.fil.5151cdce66e8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5151cdce66e87aca55e3bd0f879e2cc092532839c0bd28d4a95a23026024e3ad",
            "sha256": "6cfa0dbc1de1275b968b4d752f3c7821247b7182c47dde214c2835b93ea38753",
            "duration_seconds": 17.371,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5320,
                "end_ms": 10560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Unahin ang tanong sa pag-inom, pagsusuka, dugo sa dumi at kamalayan.",
                "start_ms": 10860,
                "end_ms": 17300
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/check-transfer.en.68b7ae910f43.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "68b7ae910f4315bd7c54e8eaf40d6887c493f6d9d07edc25dffea37579fd6517",
            "sha256": "22a5fd550b5e91bf2f13a3fd5ef5718dd4aec85b01fc048e63744be879d2443c",
            "duration_seconds": 12.8,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2620,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Read the amount and mixing from the packet, not from memory.",
                "start_ms": 8100,
                "end_ms": 12740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/check-transfer.fil.b71a272809ce.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b71a272809ceee8b9bad544c37c2a75b66f01e3e4df1631845447779666f49e8",
            "sha256": "5e2d3a00047472e3a72ba7c491439873e6213c6f9cc79939123293d40d89274d",
            "duration_seconds": 15.726,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 4160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 4460,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 6560,
                "end_ms": 9680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Basahin sa sachet ang dami at pagtimpla, hindi mula sa alaala.",
                "start_ms": 9980,
                "end_ms": 15660
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/example.en.61c6b2cf5b90.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "61c6b2cf5b90ff29c152cfd5e835ab9f54e189011bdb924b171f59f90f503415",
            "sha256": "92667fa9e47b5f22d10c545916bca116437623f846cac7bcc0cd8e6c3e75266b",
            "duration_seconds": 37.799,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW first asks whether Mina can drink, is vomiting, has blood in her stool and is alert.",
                "start_ms": 2020,
                "end_ms": 9980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mina is still breastfeeding, so the BHW encourages the caregiver to continue.",
                "start_ms": 10280,
                "end_ms": 16560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Holding the sachet, the BHW reads its directions aloud and explains that it needs safe water.",
                "start_ms": 16860,
                "end_ms": 24140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She also names when to go urgently: any danger sign or dehydration concern.",
                "start_ms": 24440,
                "end_ms": 30920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask first, keep breastfeeding, read the packet, and name when to refer.",
                "start_ms": 31220,
                "end_ms": 37740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/example.fil.b8c69d6ecd9b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b8c69d6ecd9b021377de378dd82d4487af775f5f880c7b53f2a874b9ad16797e",
            "sha256": "5339ccafa3396f33e837a9e08e00c4af567d1e2e53e536405b5fda2318004b40",
            "duration_seconds": 43.337,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Unang itinatanong ng BHW kung nakaiinom si Mina, kung sumusuka, kung may dugo sa dumi at kung alerto siya.",
                "start_ms": 1820,
                "end_ms": 10820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sumususo pa si Mina, kaya hinihikayat ng BHW na ituloy ito.",
                "start_ms": 11120,
                "end_ms": 17040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hawak ang sachet, binabasa niya nang malakas ang panuto at ipinapaliwanag na kailangan ng ligtas na tubig.",
                "start_ms": 17340,
                "end_ms": 25860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sinasabi rin niya kung kailan agad pupunta: kapag may danger sign o alalahanin sa dehydration.",
                "start_ms": 26160,
                "end_ms": 33520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magtanong muna, ituloy ang pagpapasuso, basahin ang sachet, at sabihin kung kailan magre-refer.",
                "start_ms": 33820,
                "end_ms": 43260
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/next-step.en.d5188320d24f.mp3",
