            "duration_seconds": 27.193,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2460,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 7720,
                "end_ms": 11840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Use the packet label in a dry simulation, explain safe water and continued feeding, and identify a referral trigger.",
                "start_ms": 12140,
                "end_ms": 21820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Practise a dry ORS explanation from a real packet label.",
                "start_ms": 22120,
                "end_ms": 27120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/diarrhea-dehydration/next-step.fil.ec53dcd1fbf2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ec53dcd1fbf2eec1bbbbf8a19da60a1b542bca23f8bb56c78470535b5344cd09",
            "sha256": "1a2d61fe8b17a4c9ecfe16ee47ea7b18bbb59b44495f9643dcee892ac5cacd30",
            "duration_seconds": 29.388,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2360
              },
