                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Check the official warning and local plan.",
                "start_ms": 2380,
                "end_ms": 5700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Identify confirmed contacts for evacuation, clinical continuity, WASH and psychosocial support.",
                "start_ms": 6000,
                "end_ms": 14680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Report immediate risk to the right team, confirm handover, and set follow-up.",
                "start_ms": 14980,
                "end_ms": 21380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A responder should rest and seek support when it is unsafe to continue.",
                "start_ms": 21680,
                "end_ms": 26960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "In a 10-minute tabletop, sequence priorities, handover, continuity, follow-up and responder support.",
                "start_ms": 27260,
                "end_ms": 36380
