                "index": 1,
                "text": "May pamilyang kailangan ng tulong sa paglikas.",
                "start_ms": 8040,
                "end_ms": 11600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nauubos ang gamot ng residente.",
                "start_ms": 11900,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi tiyak ang tubig; pagod ang volunteer.",
                "start_ms": 14960,
                "end_ms": 18920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sabay ang baha at advisory: paglikas, gamot, tubig at pagod na volunteer.",
                "start_ms": 19220,
                "end_ms": 27260
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/disaster-tabletop/scope.en.75dccba747e0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "75dccba747e011c5f06ff82bf515bbf8fea9060b8ce485362a4791dc28bd2767",
            "sha256": "be4cf3ac48d490fbcb92daf47b5a44ea94cca9aef56e58410e5321363288d8d7",
            "duration_seconds": 26.096,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "This is a tabletop only.",
                "start_ms": 2580,
                "end_ms": 5500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It does not replace official incident command, clinical assessment, water testing or a live drill.",
                "start_ms": 5800,
                "end_ms": 13760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Verify every contact and route before use.",
                "start_ms": 14060,
                "end_ms": 18540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A tabletop does not replace official command or a live drill; verify every contact.",
                "start_ms": 18840,
                "end_ms": 26040
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/disaster-tabletop/scope.fil.9f93cfb160c2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9f93cfb160c2308f3ab6db80fb28d3abaea98a0635817ed3f16578c92a8600f8",
            "sha256": "57d82fc14581596ff2b29d066df092624f80c52f54d2e0473bf48470343b3159",
            "duration_seconds": 24.973,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tabletop lamang ito.",
                "start_ms": 2980,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi kapalit ng opisyal na incident command, clinical assessment, tubig testing o live drill.",
                "start_ms": 5400,
                "end_ms": 13400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kumpirmahin ang lahat ng contact at ruta bago gamitin.",
                "start_ms": 13700,
                "end_ms": 17980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi kapalit ng opisyal na command o live drill ang tabletop; kumpirmahin ang bawat contact.",
                "start_ms": 18280,
