    "drowning-response": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/action.en.f95f6916580c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f95f6916580c4a6c9c60a853e4698e9dbcff623650ba6a5b1d039b42d4e3a567",
            "sha256": "f29a2b8deb3a1bf924609e886d154a3a5b89dbccd7e46190f66d42529387e135",
            "duration_seconds": 28.395,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Call trained rescuers and keep yourself out of the water.",
                "start_ms": 2460,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use an available reach or throw aid only when safe.",
                "start_ms": 6680,
                "end_ms": 11560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Once rescued by trained personnel, arrange urgent medical assessment and follow the current drowning resuscitation protocol.",
                "start_ms": 11860,
                "end_ms": 20740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose a safe shore response, activate trained rescue and state the need for medical assessment.",
                "start_ms": 21040,
                "end_ms": 28320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/action.fil.6f191506e22a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6f191506e22a31269a6265a7571615d64a8b3452739df9cc56116633db312dfc",
            "sha256": "14796f3daa8e49e7fd752f21156fbc312f3b928fc6c25fe1ee98cfd390fdd0e1",
            "duration_seconds": 34.168,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tawagin ang sanay na rescuer at huwag lumusong sa tubig.",
                "start_ms": 2460,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gumamit ng abot o hagis na tulong kung mayroon, at kung ligtas lamang.",
                "start_ms": 7080,
                "end_ms": 13520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kapag nailigtas na ng sanay na rescuer, ayusin ang agarang medikal na pagsusuri.",
                "start_ms": 13820,
                "end_ms": 20100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sundin ang kasalukuyang drowning resuscitation protocol.",
                "start_ms": 20400,
                "end_ms": 24720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang ligtas na tugon sa pampang, tawagin ang sanay na rescuer at ipaliwanag ang pangangailangan sa pagsusuri.",
                "start_ms": 25020,
                "end_ms": 34100
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/check-start.en.d255d4ffda7a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d255d4ffda7ad753ef16cc8e911a805d19a43c4f6879a180bd4217f54ba9848f",
            "sha256": "676efe8cf1d4966c8f5d46defa85226e5cd11e5d9439dde6b59810a032c3c7a6",
            "duration_seconds": 12.852,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2420,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5000,
                "end_ms": 8520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Call trained rescuers and stay out of the water.",
                "start_ms": 8820,
                "end_ms": 12780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/check-start.fil.cb8d02d1144c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cb8d02d1144c8dafc80b0a3a79587c60d568b887c17051db84f044a2af2c729b",
            "sha256": "3825c024978a377b2aa14b81978738d64e0b2e9735db94347432eb424d3562d0",
            "duration_seconds": 14.994,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 3060,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5400,
                "end_ms": 10280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tawagin ang sanay na rescuer at huwag lumusong.",
                "start_ms": 10580,
                "end_ms": 14940
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/check-transfer.en.f40e7f38684f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f40e7f38684f7ad042bc8c2b0a51eb22af4861a9a8ad19c60166d5f77fea420c",
            "sha256": "125d738f9a912418f61146244527bea6b2505629d5674160da5a226a80339cdf",
            "duration_seconds": 13.845,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4760,
                "end_ms": 7400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "After rescue, arrange urgent medical assessment; do not invert the person.",
                "start_ms": 7700,
                "end_ms": 13780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/check-transfer.fil.9ae593861654.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9ae5938616542583f851e07547d70cf098290249b777d6f746324d7f09c03b1e",
            "sha256": "26d6edacfad6f5a646843792ca80cadad1ab8ac8379943cd0521e441f3467e35",
            "duration_seconds": 14.602,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2700,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4960,
                "end_ms": 8400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kapag nailigtas, ayusin ang agarang pagsusuri; huwag baligtarin ang tao.",
                "start_ms": 8700,
                "end_ms": 14540
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/example.en.b2fa7b7126f1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b2fa7b7126f1787ef837abcfa2f9ad7c84e943166c2634de35c56ca06931e5cc",
            "sha256": "f463a67898a87933e0a45e04ddcea2b8106e9588bc2d2f1abcf8ffdc7c830dd9",
            "duration_seconds": 32.836,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea stays on dry ground at the flooded canal and does not enter the water.",
                "start_ms": 1860,
                "end_ms": 7540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She calls trained rescuers and gives the location.",
                "start_ms": 7840,
                "end_ms": 11440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "When a bystander urges her to jump in, she says no and uses a reach or throw aid only if it is safe.",
                "start_ms": 11740,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She states that the person will need urgent medical assessment once rescued.",
                "start_ms": 20680,
                "end_ms": 26080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea stays on dry ground, calls rescuers and states the need for medical assessment.",
                "start_ms": 26380,
                "end_ms": 32780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/example.fil.46c4d2c804a1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "46c4d2c804a14220e45a19d6fc6c03c1c1851c9499cb8cfc54bbed495553670b",
            "sha256": "11a7cb6355495b58274df6c37c5e5aa2cda3cca9a76e080fcee83c39c11b6072",
            "duration_seconds": 36.833,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nananatili si Lea sa tuyong lupa sa tabi ng binahang kanal at hindi lumulusong.",
                "start_ms": 1900,
                "end_ms": 7940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tinatawagan niya ang sanay na rescuer at sinasabi ang lokasyon.",
                "start_ms": 8240,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nang udyukan siya ng saksi na lumusong, tumanggi siya.",
                "start_ms": 13380,
                "end_ms": 17860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Gumagamit lamang siya ng abot o hagis na tulong kung ligtas.",
                "start_ms": 18160,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sinasabi niyang kailangan ng agarang medikal na pagsusuri kapag nailigtas na ang tao.",
                "start_ms": 23660,
                "end_ms": 29540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nasa tuyong lupa si Lea, tumatawag ng rescuer at sinasabing kailangan ng pagsusuri.",
                "start_ms": 29840,
                "end_ms": 36760
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/next-step.en.5b7c1b650082.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5b7c1b6500820eafa66326a4c5de81143cc714ce271b19ddc611f9724aed8aad",
            "sha256": "90894eb97cd42fe04444ed91fc4068ae9fd3814ff2dc7bd4052b438fdb8e3ea2",
            "duration_seconds": 23.066,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2740,
                "end_ms": 7620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 7920,
                "end_ms": 11880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose a safe shore response, activate trained rescue and state the need for medical assessment.",
                "start_ms": 12180,
                "end_ms": 19540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 19840,
                "end_ms": 23000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/next-step.fil.f539e9518e74.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f539e9518e740ce6697e0d09939adda04d170ad66e3ba1a3ecbeec522b2abe42",
            "sha256": "40c6b872112f3814867cfcf5f8c2d3d35b1a02056e2aa3ceccfbc6041dc0b9b4",
            "duration_seconds": 26.436,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2860,
                "end_ms": 8860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 9160,
                "end_ms": 13320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Piliin ang ligtas na tugon sa pampang, tawagin ang sanay na rescuer at ipaliwanag ang pangangailangan sa pagsusuri.",
                "start_ms": 13620,
                "end_ms": 22580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 22880,
                "end_ms": 26360
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/scene.en.ea0959b922c6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea0959b922c6e958996a0dc7cb087d6aecc63516e5a739c7308e6ed3d966f3b7",
            "sha256": "68335aec81c8a2b0e25319b2e2cae99ee80aabce918583200bedaab65abe3961",
            "duration_seconds": 17.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A person is struggling beyond the edge of a flooded canal.",
                "start_ms": 1940,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The BHW is on dry ground without water-rescue training.",
                "start_ms": 6680,
                "end_ms": 11880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: A person is struggling beyond the edge of a flooded canal",
                "start_ms": 12180,
                "end_ms": 17540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/scene.fil.817c6d466d5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "817c6d466d5b0a707a8fd16c8a30d8ff86d415a5f4fb3be59b4defe922bfe43a",
            "sha256": "406fb9084df7eb456bfe302a1e0079b5091fbc363e2f9dc348304f0ec9f64cca",
            "duration_seconds": 18.913,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May taong nahihirapan sa tubig, lampas sa gilid ng binahang kanal.",
                "start_ms": 2100,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nasa tuyong lupa ang BHW at walang water-rescue training.",
                "start_ms": 7320,
                "end_ms": 12880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: May taong nahihirapan lampas sa gilid ng binahang kanal",
                "start_ms": 13180,
                "end_ms": 18860
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/scope.en.b1f54d40dfeb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b1f54d40dfebe843760ae3cd564e0f894110ac6aeb91ea6863bff3fa20f190ca",
            "sha256": "408284ec39d07d9762b118c129329f6d8a8e819173fd73b2d2a6f4e13741656c",
            "duration_seconds": 21.238,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not enter unsafe water, invert the person to drain water, or assume ordinary compression-only CPR covers drowning-specific ventilation needs.",
                "start_ms": 2540,
                "end_ms": 15260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not enter unsafe water or invert the person to drain water.",
                "start_ms": 15560,
                "end_ms": 21160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/drowning-response/scope.fil.5c132fde9c4a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5c132fde9c4a42b7f67b6a4da0e9691da4e32f2d1da197717e8b95a0fe1484b5",
            "sha256": "82635566bc128c66951d3c4c1a442ab3ebc62819629f03189491db0f4497292c",
            "duration_seconds": 22.727,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag lumusong sa mapanganib na tubig o baligtarin ang tao para patuluin ang tubig.",
                "start_ms": 3060,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag ipagpalagay na sapat ang karaniwang compression-only CPR sa pangangailangan sa bentilasyon ng nalunod.",
                "start_ms": 9720,
                "end_ms": 17640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag lumusong sa mapanganib na tubig o baligtarin ang tao.",
                "start_ms": 17940,
                "end_ms": 22660
              }
            ]
          }
        }
      }
    },
    "effective-safe-person-centered": {
      "module": "chapter2/02-quality-service",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/action.en.9447a448403a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9447a448403ab499c7e7d2eecf98170e630ea5b1d6ab4276ee6a01d409c164b2",
            "sha256": "c63589e42cbf1c539dae3e1590d1766fcdafcb1d7d62e95bbbec2c6401d1ec70",
            "duration_seconds": 34.978,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Check three dimensions.",
                "start_ms": 2300,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Effective: confirm information against current guidance or with the designated staff.",
                "start_ms": 4960,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Safe: notice potential harm and seek appropriate help.",
                "start_ms": 11660,
                "end_ms": 16620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "People-centered: ask about needs and preferences.",
                "start_ms": 16920,
                "end_ms": 20720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Speed or courtesy alone does not make service high quality.",
                "start_ms": 21020,
                "end_ms": 26100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Compare the two encounters. For each dimension, record the evidence and one improvement. Explain the difference to a partner.",
                "start_ms": 26400,
                "end_ms": 34920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/action.fil.d30c3e24d98c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d30c3e24d98ce2b07b6250e2900b84a78c32addcb584c20ad9c2f0b38ab41416",
            "sha256": "f7e24057898547b0236574897a853f6cae1d3723544d7eb187aa7aadea0ebbb2",
            "duration_seconds": 41.143,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Suriin ang tatlong katangian.",
                "start_ms": 2420,
                "end_ms": 5460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Epektibo: kumpirmahin ang impormasyon sa kasalukuyang gabay o nakatalagang staff.",
                "start_ms": 5760,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ligtas: pansinin ang maaaring makapinsala at humingi ng angkop na tulong.",
                "start_ms": 13220,
                "end_ms": 19620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nakatuon sa tao: itanong ang pangangailangan at kagustuhan.",
                "start_ms": 19920,
                "end_ms": 25400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi sapat na mabilis o magalang lamang ang serbisyo.",
                "start_ms": 25700,
                "end_ms": 30340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihambing ang dalawang usapan. Sa bawat katangian, itala ang ebidensiya at isang pagbabago. Ipaliwanag ang pagkakaiba sa kapareha.",
                "start_ms": 30640,
                "end_ms": 41080
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/check-start.en.cff3751afd87.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cff3751afd8715a86ab62f864ce634965770d85a137882162021b7d72fafeb06",
            "sha256": "d95adb4b33f3d4fa938652ef9784b74789ac863c97ee523588c5b1585d0e3312",
            "duration_seconds": 13.453,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2500,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4960,
                "end_ms": 8440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This establishes a reliable basis before giving a schedule.",
                "start_ms": 8740,
                "end_ms": 13380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/check-start.fil.be397e885bd2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "be397e885bd2f2d1615bef00710c014c05c4ed89023f2ddd156b3346cafca3b9",
            "sha256": "32070efdbdf18ca0b6224f435e4a24bd9fe3aa9984ac9f837a176c8ba0df3500",
            "duration_seconds": 15.282,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2780,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5440,
                "end_ms": 10400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May mapagkakatiwalaang batayan bago magbigay ng iskedyul.",
                "start_ms": 10700,
                "end_ms": 15220
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/check-transfer.en.fecac31294f4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fecac31294f4c9c375c918d58cd5d4f1e350a083ec6df2ef4a6ce50446b9417a",
            "sha256": "3360d5b96c1df5e5528dc05df23ca20baeb6ee8e5bf5216fd8f01c04938ae46e",
            "duration_seconds": 11.755,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2700,
                "end_ms": 4580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4880,
                "end_ms": 7640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safety and responsiveness to needs also matter.",
                "start_ms": 7940,
                "end_ms": 11700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/check-transfer.fil.35ee592b9d73.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "35ee592b9d737aaa5bb6cc897bf4237e52238f2e5f0fac8f125b495d100825d8",
            "sha256": "b750186432bb1f10cecc469147f553fa05952f4ccda516306526299de2b9c76a",
            "duration_seconds": 12.957,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2620,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4800,
                "end_ms": 8000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan din ang kaligtasan at pagtugon sa pangangailangan.",
                "start_ms": 8300,
                "end_ms": 12900
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/example.en.959f1818cec5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "959f1818cec51d4f0beb692f9a66790d7729ff2dc946893932049bdadff415b4",
            "sha256": "9ef89259297ead639e7f29af11e9f2d380f97cef07198b734ab978a3f7e15a74",
            "duration_seconds": 30.955,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the second encounter, Mila confirms the schedule with staff.",
                "start_ms": 2020,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks for the box to be removed from the walkway.",
                "start_ms": 6960,
                "end_ms": 10640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She asks what time Nena can manage and explains the confirmed options.",
                "start_ms": 10940,
                "end_ms": 16220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Information is reliable, the path is safer and Nena participates in the decision.",
                "start_ms": 16520,
                "end_ms": 23320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identifies evidence for all three dimensions and proposes an appropriate improvement for each.",
                "start_ms": 23620,
                "end_ms": 30900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/example.fil.05a69beb3095.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "05a69beb3095cb527dd3fd0f056141c3430dac58cc4ccb7266bf5580562e590f",
            "sha256": "cdc8c7d246c8f446c95824a67841ec5773776bf9bad3892cee50c0739867f134",
            "duration_seconds": 34.9,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa ikalawang usapan, kinumpirma ni Mila ang iskedyul sa staff.",
                "start_ms": 2060,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hiniling niyang alisin ang kahon sa daanan.",
                "start_ms": 7280,
                "end_ms": 10560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itinanong niya kung anong oras ang kaya ni Nena.",
                "start_ms": 10860,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ipinaliwanag niya ang mga kumpirmadong pagpipilian.",
                "start_ms": 14960,
                "end_ms": 19320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Epektibo ang impormasyon, mas ligtas ang daan, at kasama si Nena sa pagpapasya.",
                "start_ms": 19620,
                "end_ms": 26100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tinutukoy ang ebidensiya para sa tatlong katangian at nagmumungkahi ng isang angkop na pagbabago sa bawat isa.",
                "start_ms": 26400,
                "end_ms": 34840
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/next-step.en.2a55cddd6ecf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2a55cddd6ecf86ead855f4e4ccf0d32b3121263a2b9fcef655190582e3841dbc",
            "sha256": "a11dacfa6d5a5d337a6a2d0a825bcdc203ff3fc28ba62a4cc5fe122a11ecd004",
            "duration_seconds": 32.209,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nena chooses a confirmed time.",
                "start_ms": 2500,
                "end_ms": 5420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mila checks every dimension rather than only speed.",
                "start_ms": 5720,
                "end_ms": 10360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On Monday, compare two fictional visits using three questions: Is the basis reliable?",
                "start_ms": 10660,
                "end_ms": 18260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Is it safe?",
                "start_ms": 18560,
                "end_ms": 20080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Have we considered the person?",
                "start_ms": 20380,
                "end_ms": 22780
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Word: effective — consistent with appropriate guidance and purpose.",
                "start_ms": 23080,
                "end_ms": 28960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 29260,
                "end_ms": 32140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/next-step.fil.61e01c285c12.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "61e01c285c1201cbaa9e45625a63188994758d9fb35283744848ecb4f5f43e5b",
            "sha256": "b180b917356ff2a472922e921f4d200890977c03e41680637016e70b58351aaa",
            "duration_seconds": 36.937,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nakapili si Nena ng kumpirmadong oras.",
                "start_ms": 2740,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinuri ni Mila ang bawat katangian, hindi lamang ang bilis ng usapan.",
                "start_ms": 7080,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, ihambing ang dalawang kathang-isip na pagbisita gamit ang tatlong tanong: Tama ba ang batayan?",
                "start_ms": 13020,
                "end_ms": 21700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ligtas ba?",
                "start_ms": 22000,
                "end_ms": 23400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Naisaalang-alang ba ang tao?",
                "start_ms": 23700,
                "end_ms": 26260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Salita: epektibo — naaayon sa tamang gabay at layunin.",
                "start_ms": 26560,
                "end_ms": 32800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 33100,
                "end_ms": 36860
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/scene.en.566533108e5d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "566533108e5d3a7d6f4bd9fbe106e37f7ef7c4431787808ee3d6f1770ac12103",
            "sha256": "e21cd89404813f04a8d966c13798bedd87e4c01abfdff44a987502c64f90454e",
            "duration_seconds": 26.018,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a fictional BHS, Nena asks about the schedule.",
                "start_ms": 1940,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In the first encounter, BHW Mila reads an old message.",
                "start_ms": 6680,
                "end_ms": 11840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A box blocks the walkway.",
                "start_ms": 12140,
                "end_ms": 14860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nobody asks when Nena can return.",
                "start_ms": 15160,
                "end_ms": 18440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The conversation is fast, but is it good service?",
                "start_ms": 18740,
                "end_ms": 22900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Fast, but high quality?",
                "start_ms": 23200,
                "end_ms": 25960
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/scene.fil.93fd952dadab.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "93fd952dadabcd7f1f7fd03eac2068886bc894b9ede54c1d8d406c0b72f7b73a",
            "sha256": "e1f6c4f8ff1a318dba7b41e704c253a15cffa645c64158ea9a54adcd90c6d9df",
            "duration_seconds": 27.429,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na BHS, humingi si Nena ng impormasyon tungkol sa iskedyul.",
                "start_ms": 1980,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa unang usapan, binasa ni BHW Mila ang lumang mensahe.",
                "start_ms": 8120,
                "end_ms": 13400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May kahong nakaharang sa daan.",
                "start_ms": 13700,
                "end_ms": 16260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi naitanong kung kailan makakabalik si Nena.",
                "start_ms": 16560,
                "end_ms": 20160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mabilis ang usapan, pero dekalidad ba ito?",
                "start_ms": 20460,
                "end_ms": 24220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mabilis, pero dekalidad ba?",
                "start_ms": 24520,
                "end_ms": 27360
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/effective-safe-person-centered/scope.en.42bdd1f99ae7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "42bdd1f99ae7a2604097ff123f61ea6f972d1d0a724bfd73bc7391b56df5d66a",
