    "essential-health-packages": {
      "module": "chapter2/07-disaster-preparedness",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/action.en.357ee6d4a948.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "357ee6d4a94899c631a87eddbe536ebaf1b2407baadb427a2db4cddcd0326db2",
            "sha256": "4760af86b1f518a7d74134a86c3c3f372d1693cd7d2d20911c5327da25b0ca2d",
            "duration_seconds": 40.777,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Identify and link four domains: medical/public health, nutrition, safe water/sanitation/hygiene (WASH), and mental health/psychosocial support (MHPSS).",
                "start_ms": 2700,
                "end_ms": 19220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Alert assigned staff to urgent risk and interrupted services.",
                "start_ms": 19520,
                "end_ms": 24360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "For a distressed person, check safety, listen with consent, and link to practical help and qualified support.",
                "start_ms": 24660,
                "end_ms": 33660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match four fictional needs to the appropriate service and state referral and follow-up.",
                "start_ms": 33960,
                "end_ms": 40720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/action.fil.c5843efa7011.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c5843efa7011c6ae4f251519754d7af9f00684f695706d15099185f2f4684bac",
            "sha256": "a6edf439f20a98e98492f188e87c367ef3a43d03b24c82c276929f2a2ea8a621",
            "duration_seconds": 44.095,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tukuyin ang apat na larangan: medical/public health, nutrisyon, WASH, at mental health/psychosocial support (MHPSS).",
                "start_ms": 2460,
                "end_ms": 15860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iugnay ang bawat pangangailangan sa tamang staff.",
                "start_ms": 16160,
                "end_ms": 20200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipaabot agad ang panganib at naputol na serbisyo.",
                "start_ms": 20500,
                "end_ms": 24580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa nababagabag, suriin ang kaligtasan.",
                "start_ms": 24880,
                "end_ms": 28880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Makinig nang may pahintulot at iugnay sa praktikal na tulong at kwalipikadong suporta.",
                "start_ms": 29180,
                "end_ms": 35860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itugma ang apat na fictional pangangailangan sa tamang serbisyo at sabihin ang referral at follow-up.",
                "start_ms": 36160,
                "end_ms": 44040
              }
            ]
          }
        },
