              {
                "zone": "body",
                "index": 2,
                "text": "Nakinig siya sa nababagabag nang hindi pinilit ang salaysay at nag-alok ng referral.",
                "start_ms": 13660,
                "end_ms": 20540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tubig sa WASH, pagkain sa nutrition, gamot sa clinician; mahinahong pakikinig at referral.",
                "start_ms": 20840,
                "end_ms": 31080
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/next-step.en.57c8a24e345a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "57c8a24e345aa655af0119fd8cfb6d5d48490619e36b691f1d6cda5124421b4e",
            "sha256": "a7ddaf7ef7181e1f0af98007f6a68e583ef2c6d442b53d29da5a1d339fdb487d",
            "duration_seconds": 20.637,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, verify four service contacts and backups; check access for children, pregnant people, people with disabilities and those taking regular medicines.",
                "start_ms": 2540,
                "end_ms": 14940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Verify four service contacts and backups, and check access.",
                "start_ms": 15240,
                "end_ms": 20560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/next-step.fil.9f1b87fd78ca.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9f1b87fd78caa1163eb9bc4b5d62781e34277f295be8607edbdb1e19fa3c555b",
            "sha256": "5760bfaf754ef4aaeec12eb6a05f72c262eb6e50e211fc3a1f09aa1a7971383c",
            "duration_seconds": 23.719,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, ipa-verify ang apat na service contact at alternatibo.",
                "start_ms": 2740,
                "end_ms": 8260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Suriin ang access para sa bata, buntis, may kapansanan at may regular na gamot.",
                "start_ms": 8560,
                "end_ms": 16200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipa-verify ang apat na service contact at alternatibo, at suriin ang access.",
                "start_ms": 16500,
                "end_ms": 23660
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/scene.en.d19c27950a68.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d19c27950a68207db504b492291ad2bcae3981242b3fd265f69985206530de4c",
            "sha256": "ad786ca06f59060f4d21304c60d1ca7bbdd31de958472022bc1c1a6397dea3f5",
            "duration_seconds": 22.256,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a temporary shelter, a child may lack food, safe water is limited, a resident needs regular medicine, and another is distressed.",
                "start_ms": 1860,
                "end_ms": 13100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "At the shelter, food, safe water, regular medicine and distress are four different needs.",
                "start_ms": 13400,
                "end_ms": 22200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/scene.fil.cc4c711752c0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cc4c711752c0a48c31fd3f7a1b6bfb49d00c844ef35b764417279555c6e67423",
            "sha256": "3ebceaa6276c591d88e9688dddf2abc16ff5c2b33b0b1a5fac16a54232ab31d9",
            "duration_seconds": 26.41,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pansamantalang silungan, maaaring kulang sa pagkain ang isang bata at limitado ang ligtas na tubig.",
                "start_ms": 1780,
                "end_ms": 9940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May residenteng nangangailangan ng regular na gamot; ang isa ay nababagabag.",
                "start_ms": 10240,
                "end_ms": 16440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa silungan, apat na magkaibang pangangailangan ang pagkain, ligtas na tubig, regular na gamot at pagkabagabag.",
                "start_ms": 16740,
                "end_ms": 26340
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/scope.en.38cbe051ce87.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "38cbe051ce876e4dcc341a90a4b982446d18450ed759b72572874cf2bdcfb013",
            "sha256": "0f779e9e35372b5206e76c54c078e4da80d5274558dc76471e505ac2b6ec9d1e",
            "duration_seconds": 24.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Recognizing a domain does not authorize prescribing, ration-setting, declaring water safe or providing therapy.",
                "start_ms": 2420,
                "end_ms": 11700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Follow local clinical and service protocols.",
                "start_ms": 12000,
                "end_ms": 15680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Link and report; do not prescribe, set rations, declare water safe or give therapy.",
                "start_ms": 15980,
                "end_ms": 24540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/essential-health-packages/scope.fil.f1e806c2f4d5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f1e806c2f4d5bb11f224a2a92879d057c97c86150a6c3d6c9a94462f40a046b6",
            "sha256": "aba4ea32b6a9c8fe6144829178d5f2cfbe0159e0c0a66146bc89104e9c35986b",
            "duration_seconds": 26.096,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi ito pahintulot na magreseta, magtakda ng ration, magdeklara ng ligtas na tubig o magbigay ng therapy.",
                "start_ms": 2780,
                "end_ms": 12140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sundin ang lokal na clinical at service protocol.",
                "start_ms": 12440,
                "end_ms": 16720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iugnay at iulat; huwag magreseta, magtakda ng ration, magdeklara ng ligtas na tubig o magbigay ng therapy.",
                "start_ms": 17020,
                "end_ms": 26020
              }
            ]
          }
        }
      }
    },
    "evacuation-contacts": {
      "module": "chapter2/07-disaster-preparedness",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/action.en.9cf2e4fe26b7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9cf2e4fe26b76d48c8b69e02df6630f3235c527dffa071105ae782ee2458c7be",
            "sha256": "07a0809698b3528f5989df3bfc6b0616c5b1cb8f148278a43c83eeb1875b79ad",
            "duration_seconds": 28.682,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Read the current official warning and confirm the evacuation order, safe route, accessible shelter and contact with the barangay DRRM focal person.",
                "start_ms": 2380,
                "end_ms": 14580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Relay only the verified message, recording its time and source.",
                "start_ms": 14880,
                "end_ms": 20720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Using a mock advisory, state source/time, confirmed action and contact to verify.",
                "start_ms": 21020,
                "end_ms": 28620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/action.fil.6d9bd264eea7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6d9bd264eea7ea7e51a75ecbf79ac57f1a0228b31708f66041706f492fd7292b",
            "sha256": "d20d1c69976684af9a1b4b621076f544c7cc356bb2571e36b856710a535e3892",
            "duration_seconds": 31.53,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Basahin ang kasalukuyang opisyal na babala at kumpirmahin sa barangay DRRM focal person ang evacuation order, ligtas na ruta, accessible na silungan at contact.",
                "start_ms": 2300,
                "end_ms": 16220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipaliwanag lamang ang beripikadong mensahe; itala ang oras at pinagmulan.",
                "start_ms": 16520,
                "end_ms": 22680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gamit ang mock advisory, sabihin ang source/oras, kumpirmadong aksiyon at contact na kukumpirmahin.",
                "start_ms": 22980,
                "end_ms": 31460
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/check-start.en.dcbc1f7abe4b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dcbc1f7abe4b3a6597e7057d7fd7bfdd0d93055b826709270b7eca25aa5e12dc",
            "sha256": "d52495fadc2301ad0ba42312e364b5e1e5c9d4ba8643d96337e37b5dc0234fa5",
            "duration_seconds": 13.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2380,
                "end_ms": 4380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4680,
                "end_ms": 8120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check the current official update and route before advising.",
                "start_ms": 8420,
                "end_ms": 13060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/check-start.fil.1d6bbd14bf5a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1d6bbd14bf5a7560f7f1b5b8edf28283fe547fc1d1fcc1c8ebc5b18e7ea95e56",
            "sha256": "3578c7ac136e1e0421c16b8db8b7e0edc66d55ecfd0b45216cc3609c6dc52cf2",
            "duration_seconds": 15.882,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2860,
                "end_ms": 5380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5680,
                "end_ms": 10600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Suriin ang kasalukuyang opisyal na update at ruta bago magpayo.",
                "start_ms": 10900,
                "end_ms": 15820
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/check-transfer.en.d4b3c2c25bf0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d4b3c2c25bf0cc44757ed13cb8193b46aa5262bffe0a98103bea2cf60413b40f",
            "sha256": "277f0613d3234fd4c79e549480f8c9e9bc9a83c049c163e7a60e7adc145bf35a",
            "duration_seconds": 13.375,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2580,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Relay only what is verified, with its source and time.",
                "start_ms": 7900,
                "end_ms": 13300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/check-transfer.fil.df20e879c322.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "df20e879c3224f042663659d441ca9dd7c166310e26deada5c857e5c6e1df755",
            "sha256": "e780cc8edb33fdc0444dc2fe4c06e37a45aa7eadcd56e475cf02e60d63590e0c",
            "duration_seconds": 13.61,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3140,
                "end_ms": 5180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5480,
                "end_ms": 8480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipaabot lamang ang beripikado, kasama ang source at oras.",
                "start_ms": 8780,
                "end_ms": 13540
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/example.en.743c53bd9726.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "743c53bd97267c4006dda56116e448b9c4d026b9f201533d7cebc0e6b86d286e",
            "sha256": "68f194613046f3a2a15e1bb8fca3e4814527d64982c471f7a10466ce8983248e",
            "duration_seconds": 19.879,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW checks the advisory date and calls the official contact.",
                "start_ms": 2180,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "They state what is confirmed and what still awaits an answer.",
                "start_ms": 7800,
                "end_ms": 12600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check the advisory date, call the official contact, and say what is confirmed and pending.",
                "start_ms": 12900,
                "end_ms": 19820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/example.fil.9115987fa6e4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9115987fa6e4684e05439f6ffc5096719943faa034daf1a6a8b4fb14f34c10d5",
            "sha256": "e12e885b09f58e84a9106b7a0c7df5af1d8012c57169e78291739668593bc5d2",
            "duration_seconds": 24.137,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinuri ng BHW ang petsa ng advisory at tumawag sa opisyal na contact.",
                "start_ms": 2260,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sinabi niya kung ano ang kumpirmado at kung ano ang naghihintay pa ng sagot.",
                "start_ms": 9720,
                "end_ms": 15240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Suriin ang petsa ng advisory, tawagan ang opisyal na contact, at sabihin ang kumpirmado at hinihintay pa.",
                "start_ms": 15540,
                "end_ms": 24060
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/next-step.en.f1fd8ef793ff.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f1fd8ef793ff85747cf9afa086c1d0311898ed83a49718b95984663a6775ad28",
            "sha256": "0faebae210d26a1404d21a310deaf48349684ea980eec87689bcbdc3a63855f8",
            "duration_seconds": 19.435,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, verify the contact directory, warning source, route and accessible shelter; record date and confirmer.",
                "start_ms": 2540,
                "end_ms": 12420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Verify the directory, warning source and route; record date and confirmer.",
                "start_ms": 12720,
                "end_ms": 19360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/next-step.fil.017b1cea1d46.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "017b1cea1d46ebdce6768fdbefa3b1685f9dc1fb2b998bba3468910f2baa8dca",
            "sha256": "1331786f766e96e6ecfb750ac28a416ebb60347d4fe039d9792ded8351dcabc3",
            "duration_seconds": 22.518,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, ipa-verify ang contact directory, warning source, ruta at accessible shelter; lagyan ng petsa at taong nagkumpirma.",
                "start_ms": 2620,
                "end_ms": 13740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipa-verify ang directory, warning source at ruta; itala ang petsa at nagkumpirma.",
                "start_ms": 14040,
                "end_ms": 22440
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/evacuation-contacts/scene.en.403abb04a3b1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "403abb04a3b1f16f7285f9b9527ccf616978903662f86d4b9089acb5a529c34a",
            "sha256": "cdedfaed59ed5d2190a1f73be78c4f674c345dc18c5613e6bde4f0244b05e187",
            "duration_seconds": 19.879,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Heavy rain is forecast.",
                "start_ms": 1900,
                "end_ms": 4100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nena’s family asks when and where to evacuate, but the printed directory is old.",
                "start_ms": 4400,
                "end_ms": 11400
              },
              {
