                "text": "She marks the expired item and the unsealed packet, sets both aside unused, and reports them to the named replacement owner.",
                "start_ms": 14900,
                "end_ms": 24940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Having them in the kit does not mean she may use them.",
                "start_ms": 25240,
                "end_ms": 29640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea fills every row, sets aside the expired and unsealed items unused, and reports them to the owner.",
                "start_ms": 29940,
                "end_ms": 38740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/first-aid-kit/example.fil.a79163bb4721.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a79163bb4721e19e81e8081577a014caf178283564e07a9825f251c5fda810f5",
            "sha256": "9e7c4aa7a677ab5054b2c1f0d42e91fb9025ec2c76b655e5186e530923de4e76",
            "duration_seconds": 43.86,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isinasantabi ni Lea ang lumang inventory sheet at ginagamit ang kasalukuyang lokal na listahan.",
                "start_ms": 2100,
                "end_ms": 8940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa bawat gamit, itinatala niya ang dami, selyo, expiry at imbakan.",
                "start_ms": 9240,
                "end_ms": 16880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Minamarkahan niya ang expired item at ang bukas na pakete.",
                "start_ms": 17180,
                "end_ms": 22060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Inihihiwalay niya ang dalawa nang hindi ginagamit at iniuulat sa responsable sa palit.",
                "start_ms": 22360,
                "end_ms": 28520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi pahintulot gumamit ang pagkakaroon nito sa kit.",
                "start_ms": 28820,
                "end_ms": 33020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pinupunan ni Lea ang bawat hanay, inihihiwalay nang hindi ginagamit ang expired at bukas na gamit, at iniuulat sa responsable.",
                "start_ms": 33320,
                "end_ms": 43800
              }
            ]
          }
        },
