            "sha256": "59fef9794789650b2b5b362fb68a2b06a5f728e01c405121a1645c87c312840f",
            "duration_seconds": 20.558,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
