        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/first-aid-kit/scope.en.55905c841777.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "55905c841777788113447935df46c67805a6071edcd331842437a76ae17a2492",
            "sha256": "03c627f37a98931044dcdf9be6dc78c7e95e9a86e0ede9dc44211c73ab2592bb",
            "duration_seconds": 20.663,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not copy the old manual’s drug list as a standing prescription, use expired stock, or assume a kit item certifies the BHW to administer it.",
                "start_ms": 2620,
                "end_ms": 14940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "An item in the kit is not a prescription or permission to use it.",
                "start_ms": 15240,
                "end_ms": 20600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/first-aid-kit/scope.fil.82dca83faa8b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "82dca83faa8b480893e489bab53a45814c36d4e3e89d75a037b0eab7e9266cf1",
            "sha256": "4e629b4bab1858622a27da9d5c064e021efb4b1234cc3e64909b29602ffa4dd0",
            "duration_seconds": 18.155,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag gawing reseta ang lumang listahan ng gamot, gamitin ang expired stock, o ipagpalagay na pahintulot ang pagkakaroon ng gamit.",
                "start_ms": 3900,
                "end_ms": 13020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi reseta o pahintulot gumamit ang gamit na nasa kit.",
                "start_ms": 13320,
                "end_ms": 18080
              }
            ]
          }
        }
      }
