    "food-water-sanitation": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/action.en.0b2829f1d3de.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0b2829f1d3de35e3b066dc69a7dfab1a3daccc16d66f676b609012494083c546",
            "sha256": "e630afa0679eb7d64888424d6b760957dfa741ee640ac3725de441187515a4c1",
            "duration_seconds": 36.258,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For food: keep hands, utensils and surfaces clean.",
                "start_ms": 2500,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Separate raw and cooked food.",
                "start_ms": 7440,
                "end_ms": 10120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Cook thoroughly.",
                "start_ms": 10420,
                "end_ms": 12100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Keep food at safe temperatures instead of leaving it exposed.",
                "start_ms": 12400,
                "end_ms": 16960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Use safe water and ingredients.",
                "start_ms": 17260,
                "end_ms": 20380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Wash produce with safe water.",
                "start_ms": 20680,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Protect food from insects and rodents.",
                "start_ms": 23660,
                "end_ms": 26900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mark risks in the household story. Complete the food, water and sanitation rows and add a contact for uncertainties.",
                "start_ms": 27200,
                "end_ms": 36200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/action.fil.68e3a31d2a95.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "68e3a31d2a95ba8a5cab0d828c7e93ec4ba11fb7b47556e705709c09fa382587",
            "sha256": "299c0e68d9e384a1c995249bfc18f74ffd1715e5693f1bdf5b083c71ee3baa50",
            "duration_seconds": 44.904,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pagkain: panatilihing malinis ang kamay, kagamitan at lugar.",
                "start_ms": 2460,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihiwalay ang hilaw sa luto.",
                "start_ms": 9200,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Lutuing mabuti.",
                "start_ms": 12860,
                "end_ms": 14620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Panatilihin sa ligtas na temperatura ang pagkain; huwag basta iwang nakabuyangyang.",
                "start_ms": 14920,
                "end_ms": 21360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gumamit ng ligtas na tubig at sangkap.",
                "start_ms": 21660,
                "end_ms": 24820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hugasan ang prutas at gulay gamit ang ligtas na tubig.",
                "start_ms": 25120,
                "end_ms": 29600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Takpan laban sa insekto at daga.",
                "start_ms": 29900,
                "end_ms": 33180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Markahan ang panganib sa kuwento ng bahay. Punan ang pagkain, tubig at sanitasyon na hanay; magdagdag ng contact para sa hindi tiyak.",
                "start_ms": 33480,
                "end_ms": 44840
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/check-start.en.237d6dcd8b2c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "237d6dcd8b2c41453230fd7a9a106d0aca91f50037d517ba699531e5266d1e7a",
            "sha256": "5d681f9bccdfd623bb2847bcbbe8c831b020dbf0e9deb20ed784e02463857f9f",
            "duration_seconds": 14.838,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2580,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5120,
                "end_ms": 8680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A reliable basis and instructions are needed, not appearance alone.",
                "start_ms": 8980,
                "end_ms": 14780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/check-start.fil.d18ec91baba3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d18ec91baba36e7c78b03626b8351b4b55c80b6c3349a11e9d1104c1cb0d6b3b",
            "sha256": "020f8a197de4cbfccca5947b6af885fb5eb7fd644bf34b08583f3c4f96c45bd2",
            "duration_seconds": 15.438,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2540,
                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5160,
                "end_ms": 9960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kailangan ng tamang batayan at tagubilin, hindi hitsura lamang.",
                "start_ms": 10260,
                "end_ms": 15380
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/check-transfer.en.479d66f419d3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "479d66f419d3d4475f2d375b420e5b2a0ae33359dad15b0f77b4db87c63c4f1b",
            "sha256": "14d439de2987c13e878cff3148118f5e6d361d0eb4824f31c89c499247213b34",
            "duration_seconds": 11.076,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2700,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This reduces transfer from raw food.",
                "start_ms": 7780,
                "end_ms": 11020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/check-transfer.fil.54467d132ca7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "54467d132ca7e8b3dd63633cacb3d2fd740a386b13052fa36a05b7d9531cdbe3",
            "sha256": "76df6c1246ec0f8eb01ca0613be0808a61053c502a28712f3078dafef222889e",
            "duration_seconds": 14.237,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3740,
                "end_ms": 5820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 6120,
                "end_ms": 9600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nababawasan ang paglipat mula sa hilaw na pagkain.",
                "start_ms": 9900,
                "end_ms": 14180
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/example.en.f087455ea0ce.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f087455ea0ce64ca3c619a09d7fd42a96526b39e1f994804b4b986e04cc1dfc3",
            "sha256": "22ed040c1da5c97fec9bed359a7322848cb314c2c0db577cdf66c189337a695e",
            "duration_seconds": 32.418,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mila chooses to separate raw and cooked food.",
                "start_ms": 2020,
                "end_ms": 6140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She will cover stored water and avoid dipping hands or cups into it.",
                "start_ms": 6440,
                "end_ms": 11880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Clear appearance does not establish safety.",
                "start_ms": 12180,
                "end_ms": 15980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "They will confirm a safe source with health or water staff.",
                "start_ms": 16280,
                "end_ms": 20880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The household will use a toilet and provide soap and water for washing.",
                "start_ms": 21180,
                "end_ms": 26380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mila chooses the changes; clear water is not promised as safe.",
                "start_ms": 26680,
                "end_ms": 32360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/example.fil.07b656be2ec9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "07b656be2ec90b52b7edaa230066a739f16fbcb7753898fd5073d81f324e40f5",
            "sha256": "356eefd2478f18d768fd262e8101d626ee0ccc5d33645ea6e92274d31b5ddbb7",
            "duration_seconds": 36.989,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pinili ni Mila na paghiwalayin ang hilaw at luto.",
                "start_ms": 1940,
                "end_ms": 6340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tatakpan niya ang lalagyan ng tubig at iiwasang maisawsaw ang kamay o baso.",
                "start_ms": 6640,
                "end_ms": 12880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi patunay ng kaligtasan ang linaw ng tubig.",
                "start_ms": 13180,
                "end_ms": 17660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kukumpirmahin nila ang ligtas na pinagkukunan sa health o water staff.",
                "start_ms": 17960,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gagamit ng palikuran at maghahanda ng sabon at tubig para sa paghuhugas.",
                "start_ms": 23660,
                "end_ms": 29540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Si Mila ang pumipili ng pagbabago; hindi ipinapangakong ligtas ang malinaw na tubig.",
                "start_ms": 29840,
                "end_ms": 36920
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/next-step.en.6afb6919b92f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6afb6919b92fc1e12bdf843eeccebe05e85ff186dde09f481f9cab157d92302e",
            "sha256": "119e8c95c8c68cacff55e61fd471809beb2423c6d9c34d72808ee64b6b69705e",
            "duration_seconds": 30.798,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The plan covers food handling, protected water and a handwashing station.",
                "start_ms": 2500,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, review the household checklist with the supervisor.",
                "start_ms": 8400,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Wash before preparing food or eating and after using the toilet.",
                "start_ms": 13220,
                "end_ms": 18580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Word: sanitation — safe management of excreta to prevent environmental contamination.",
                "start_ms": 18880,
                "end_ms": 27000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Review the household checklist with the supervisor.",
                "start_ms": 27300,
                "end_ms": 30740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/next-step.fil.d1704a0263e8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d1704a0263e89ef70e9c40cae64b209a3ad9ca5e5d7847285a81ec6a9d7d9cc4",
            "sha256": "3ea9789b853c9b611259a2e25890eaad1b59a018c5b399b0351772c2fb7d7748",
            "duration_seconds": 36.937,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May tatlong hakbang: ayusin ang pagkain, protektahan ang tubig at maghanda ng handwashing station.",
                "start_ms": 2740,
                "end_ms": 11220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, ipasuri ang household checklist sa supervisor.",
                "start_ms": 11520,
                "end_ms": 16400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maghugas bago humawak ng pagkain at kumain, at matapos gumamit ng palikuran.",
                "start_ms": 16700,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: sanitasyon — ligtas na pamamahala ng dumi upang hindi makontamina ang kapaligiran.",
                "start_ms": 23640,
                "end_ms": 32960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipasuri sa supervisor ang household checklist.",
                "start_ms": 33260,
                "end_ms": 36860
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/scene.en.bd7835fcb891.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bd7835fcb8912c48949460daea7694852a965f01df0e7a4d80dacec324cbbf50",
            "sha256": "2d9bfa023ea2c271cd28108d6dc822ce2cd0bf53694ab2939f845961dd858bde",
            "duration_seconds": 26.436,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In Mila’s fictional home, raw chicken sits beside cooked food.",
                "start_ms": 1900,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Drinking water is uncovered and a cup is dipped into it.",
                "start_ms": 7240,
                "end_ms": 11640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“The water looks clear,” she says.",
                "start_ms": 11940,
                "end_ms": 14900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "There is no soap near the toilet.",
                "start_ms": 15200,
                "end_ms": 17840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The BHW asks permission before discussing these observations.",
                "start_ms": 18140,
                "end_ms": 23700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No soap near the toilet.",
                "start_ms": 24000,
                "end_ms": 26360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/scene.fil.50e25cbe6dde.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "50e25cbe6ddef21ea8d6a94ca6201c3bc44f9ce36b8e6d1defd331b012545919",
            "sha256": "a3c5e6c9fa484fd846fb2cd81ca24e31bca11045c9c4144ad06241e697252b61",
            "duration_seconds": 29.675,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na bahay ni Mila, magkatabi ang hilaw na manok at lutong pagkain.",
                "start_ms": 2380,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bukas ang lalagyan ng tubig at isinasawsaw ang baso.",
                "start_ms": 8920,
                "end_ms": 13480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Malinaw naman ang tubig,” sabi niya.",
                "start_ms": 13780,
                "end_ms": 17060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Walang sabon sa tabi ng palikuran.",
                "start_ms": 17360,
                "end_ms": 20360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hihingi ng pahintulot ang BHW bago talakayin ang mga napansin.",
                "start_ms": 20660,
                "end_ms": 26460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang sabon sa tabi ng palikuran.",
                "start_ms": 26760,
                "end_ms": 29600
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/scope.en.d445c10d4e33.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d445c10d4e33cacd25228c032017483d11d2fde967c1a59e29643553b5041f69",
            "sha256": "349909bf6dd019fb02008e488ff68682f2fe329fe592449330b4542b31fcf5c2",
            "duration_seconds": 37.46,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "When water safety is uncertain, use current local advice and a confirmed treatment method.",
                "start_ms": 2740,
                "end_ms": 9700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not guess chlorine amounts or boiling instructions.",
                "start_ms": 10000,
                "end_ms": 14360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the sanitary inspector to assess toilet and septic-tank location.",
                "start_ms": 14660,
                "end_ms": 19980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "One distance alone cannot guarantee water safety.",
                "start_ms": 20280,
                "end_ms": 24800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Use no hot water or chemicals in this exercise.",
                "start_ms": 25100,
                "end_ms": 29580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No guessed chlorine or boiling instructions; the sanitary inspector assesses toilet siting.",
                "start_ms": 29880,
                "end_ms": 37400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/food-water-sanitation/scope.fil.517acb7c780f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "517acb7c780ff3e9930c59ca05d4e98d51b25b6392fea2dc01ba0c6e21ddc847",
            "sha256": "9f57a0d77542a540febd12654c3d2a4c8fa097abf9c7595b95d0a7dd89a3ef4f",
            "duration_seconds": 39.497,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kung hindi tiyak ang tubig, sundin ang kasalukuyang lokal na advisory at kumpirmadong paraan ng treatment.",
                "start_ms": 3340,
                "end_ms": 10980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag manghula ng dami ng chlorine o tagal ng pagpapakulo.",
                "start_ms": 11280,
                "end_ms": 16640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipasuri sa sanitary inspector ang lokasyon ng palikuran at septic tank.",
                "start_ms": 16940,
                "end_ms": 22140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi ginagarantiya ng isang distansya ang ligtas na tubig.",
                "start_ms": 22440,
                "end_ms": 27360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang mainit na tubig o kemikal sa practice.",
                "start_ms": 27660,
                "end_ms": 31860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang hulang chlorine o pagpapakulo; sanitary inspector ang susuri sa lokasyon ng palikuran.",
                "start_ms": 32160,
                "end_ms": 39440
              }
            ]
          }
        }
      }
    },
    "fracture-dislocation": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/action.en.f6fba1cedd6a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f6fba1cedd6a09d318a95cc1e31b29bb09fa36c8db5d4f10e1d286c4ac590b9f",
            "sha256": "a0264390c3d7c386aa0761839fddb9b681df02b4ff3e046c725387d11a93c341",
            "duration_seconds": 28.056,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Avoid unnecessary movement.",
                "start_ms": 2420,
                "end_ms": 5420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Support the injured part in the position found and arrange prompt assessment.",
                "start_ms": 5720,
                "end_ms": 11800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Check for other urgent concerns and follow trained/local instructions for immobilization and transfer.",
                "start_ms": 12100,
                "end_ms": 20100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Use a prop to show support in place, explain when movement is unsafe and make the referral call.",
                "start_ms": 20400,
                "end_ms": 28000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/action.fil.1061391f0be1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1061391f0be17199e3a19f2128bba002ee841812193d2f90d51dc2e08bfee4fb",
            "sha256": "7cb4e4ce39fff971c22020650bc4000b9ff67ce748f295213ddd95092256c664",
            "duration_seconds": 30.616,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang hindi kailangang galaw.",
                "start_ms": 2900,
                "end_ms": 5620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Suportahan ang bahaging nasugatan sa posisyong nakita at ayusin ang agarang pagsusuri.",
                "start_ms": 5920,
                "end_ms": 12640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tingnan kung may iba pang agarang problema.",
                "start_ms": 12940,
                "end_ms": 15740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sundin ang sanay o lokal na tagubilin sa immobilization at paglipat.",
                "start_ms": 16040,
                "end_ms": 21400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumamit ng props para ipakita ang suporta sa posisyon, ipaliwanag ang panganib ng paggalaw at tumawag.",
                "start_ms": 21700,
                "end_ms": 30540
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/check-start.en.9e2f922a0592.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9e2f922a05924f4deb2b67598dc104c89e06c3ee2a038bf849fd4ce67fd2f015",
            "sha256": "ae52dc26d3ca2e6a809550de5f231aadfa759ad32f0f485e1aa158fc937e582d",
            "duration_seconds": 13.976,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2620,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5120,
                "end_ms": 8520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Support the arm as found; do not straighten or massage it.",
                "start_ms": 8820,
                "end_ms": 13900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/check-start.fil.e4e75dfc127d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e4e75dfc127d09db260815c7df8ddccc6ddb4db16881646b159629fdf85725bc",
            "sha256": "48949fef231b758d0d7e5c8d43c462d3d5490f42e1feba9b927a00fa3d0bcb0e",
            "duration_seconds": 15.882,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 4860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5160,
                "end_ms": 10000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Suportahan ang braso sa posisyong nakita; huwag ituwid o imasahe.",
                "start_ms": 10300,
                "end_ms": 15820
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/check-transfer.en.f6a5c660c09d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f6a5c660c09db89e793f511e36932c50554bee96fe462f178552329f7aad8c38",
            "sha256": "dffda87217e80f4d9684aaa9a0c2a2be05660a3fdaa1386a9d2c8daa0424dcc0",
            "duration_seconds": 12.774,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2780,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5000,
                "end_ms": 7800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check for other urgent concerns and arrange prompt assessment.",
                "start_ms": 8100,
                "end_ms": 12700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/check-transfer.fil.0bb2a1e0012d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0bb2a1e0012d2029dd49e219e819963b27313b40919c193a1c7cc85f81305702",
            "sha256": "de28b96dd045cf78d836dda13976905edbcaac0581340ffbfe01a520266b4f48",
            "duration_seconds": 13.793,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2180,
                "end_ms": 4220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4520,
                "end_ms": 7760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tingnan ang iba pang agarang problema at ayusin ang agarang pagsusuri.",
                "start_ms": 8060,
                "end_ms": 13740
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/fracture-dislocation/example.en.cf8dce4c9567.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cf8dce4c956773febeb31d3dff2218b2f07f74f2aea7a2e82301dc2a707c3dc9",
            "sha256": "aa280c404f4009eeb07e8f6ce51eed0e3bae2190e9edbb52a4f96fd5f57b928b",
            "duration_seconds": 32.235,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea asks the cyclist to keep still and supports the forearm in the position she found it.",
                "start_ms": 1980,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "When the cyclist asks her to pull it straight, Lea explains that she will not straighten it and will avoid unnecessary movement.",
                "start_ms": 9360,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She checks for other urgent concerns.",
                "start_ms": 18180,
                "end_ms": 21020
              },
              {
