              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use a current DOH and local checklist.",
                "start_ms": 2340,
                "end_ms": 5980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Prioritize safe water, food, light, communication, basic hygiene, water-protected documents and first-aid supplies.",
                "start_ms": 6280,
                "end_ms": 17520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Include personal medicines and infant needs under the family’s care plan; check expiry and portability.",
                "start_ms": 17820,
                "end_ms": 25380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Select items for the fictional family, explain why, and set a date to recheck.",
                "start_ms": 25680,
                "end_ms": 31920
