                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Basain at sabunin ang kamay.",
                "start_ms": 2460,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kuskusin ang palad sa palad, saka bawat likod ng kamay habang nakasalikop ang daliri.",
                "start_ms": 5960,
                "end_ms": 12520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kuskusin ang pagitan ng mga daliri at likod ng daliri laban sa kabilang palad.",
                "start_ms": 12820,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Paikuting kuskusin ang bawat hinlalaki.",
                "start_ms": 20040,
                "end_ms": 23080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ikuskos ang dulo ng daliri at kuko sa kabilang palad.",
                "start_ms": 23380,
                "end_ms": 27980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Gawin sa magkabilang kamay.",
                "start_ms": 28280,
                "end_ms": 30560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng paraan para sa dalawang card: may dumi at walang dumi. Ipakita ang handwash at handrub sa supervisor.",
                "start_ms": 30860,
                "end_ms": 40220
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/check-start.en.709458e588c0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "709458e588c05eca2797e8c1923b0f004efd903604f6d31ba4098339c7c71c6b",
            "sha256": "d620ed44816b6bba21feb60499427e194324e1119407b24f7152b9bd67cedd72",
            "duration_seconds": 12.016,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2580,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5040,
                "end_ms": 8480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Complete washing and appropriate drying.",
                "start_ms": 8780,
                "end_ms": 11940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/check-start.fil.ab59913d482c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ab59913d482c80d0e9923a4e8180c8030271c40a28de33d43d33c5ad2a90ff7b",
            "sha256": "7b1877b8ddbd9b3ef175e513e3b7a4c4bb6e32c17607815a9130396b872fbe85",
            "duration_seconds": 14.002,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2500,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5000,
                "end_ms": 9440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gawin ang buong paghuhugas at tamang pagpapatuyo.",
                "start_ms": 9740,
                "end_ms": 13940
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/check-transfer.en.8df258f08292.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8df258f08292dcee931670ba6bb6c20921f8c4066dd58bbe6a8960e6addc7666",
            "sha256": "90d1c2a5bc1b325a0da53c630486a5be3395a7cda4c90b302e278fb8af68ae24",
            "duration_seconds": 12.852,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2540,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4720,
                "end_ms": 7560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Let hands dry while completing rubbing across all surfaces.",
                "start_ms": 7860,
                "end_ms": 12780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/check-transfer.fil.9e56dd05671b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9e56dd05671b14b7150a3c07217a91269828247182d6b07565dedfa4ac4dffbf",
            "sha256": "57f12499935d3be2a4559689c3c226f58007229cc74d62e7043d01819a15ab61",
            "duration_seconds": 14.237,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3540,
                "end_ms": 5460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5760,
                "end_ms": 9000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hayaang matuyo habang kinukumpleto ang handrub sa lahat ng bahagi.",
                "start_ms": 9300,
                "end_ms": 14180
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/example.en.b5266c41c60b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b5266c41c60b158d24e0bb6eaff9f07f4e3ddbfd73d95b72b881596b492de250",
            "sha256": "2128becb2e2c350b2bf85c3a34180f8ed155894d68664fbd55ef3e626318e735",
            "duration_seconds": 38.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Rinse and dry with a single-use towel.",
                "start_ms": 1940,
                "end_ms": 5340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use the towel to close a manual tap.",
                "start_ms": 5640,
                "end_ms": 9160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The complete healthcare wash takes 40–60 seconds.",
                "start_ms": 9460,
                "end_ms": 13780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "When handrub is appropriate and hands are not visibly dirty, apply enough to cover all surfaces.",
                "start_ms": 14080,
                "end_ms": 21320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Rub the same surfaces until dry: 20–30 seconds for the complete handrub.",
                "start_ms": 21620,
                "end_ms": 28060
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Do not rinse or wipe it off.",
                "start_ms": 28360,
                "end_ms": 31080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dry with a single-use towel; rub handrub until dry and never wipe it off.",
                "start_ms": 31380,
                "end_ms": 38060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/example.fil.a8d5e7563f06.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a8d5e7563f065c581df024dd339f4852d400a95b174728dd2eb87509328699c1",
            "sha256": "a1e739a7a19c307ebf37aa3c02a4d862d07bd22b16f003b8295fb0463215a35c",
            "duration_seconds": 45.401,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Banlawan at patuyuin gamit ang single-use towel.",
                "start_ms": 2180,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gamitin ang towel sa pagsara ng manwal na gripo.",
                "start_ms": 7240,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa healthcare demonstration, 40–60 segundo ang buong paghuhugas.",
                "start_ms": 11700,
                "end_ms": 17740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung angkop ang handrub at walang nakikitang dumi, gumamit ng sapat para sa lahat ng bahagi.",
                "start_ms": 18040,
                "end_ms": 24960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kuskusin ang parehong mga bahagi hanggang matuyo: 20–30 segundo ang buong handrub.",
                "start_ms": 25260,
                "end_ms": 34020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Huwag banlawan o punasan ang handrub.",
                "start_ms": 34320,
                "end_ms": 37280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Patuyuin gamit ang single-use towel; kuskusin ang handrub hanggang matuyo at huwag punasan.",
                "start_ms": 37580,
                "end_ms": 45340
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/next-step.en.39c42db45244.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "39c42db45244466c3c2acbbaf1513dde53094953ac6c40c50ae190459ecfa57e",
            "sha256": "c183be02cc9ba0b0c1d92eaed94766968ce3efb657b9141151c2a3723fa47b39",
            "duration_seconds": 32.392,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Clean hands before touching a patient, before a clean task, after body-fluid exposure risk, after touching a patient and after touching their surroundings.",
                "start_ms": 2660,
                "end_ms": 16220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, ask the supervisor to observe using the checklist.",
                "start_ms": 16520,
                "end_ms": 21760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: hand hygiene — appropriate cleaning at the right time.",
                "start_ms": 22060,
                "end_ms": 27820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask the supervisor to observe both methods with the checklist.",
                "start_ms": 28120,
                "end_ms": 32320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/next-step.fil.12fce858caee.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "12fce858caee3ff36475c4f60207d314dd10e18141f131b7d160f21c94f4718d",
            "sha256": "cfd98cff47657990d847724510f88e31cdbe12d5786714997d0f973d1719eab0",
            "duration_seconds": 35.213,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Linisin ang kamay bago humawak sa pasyente, bago ang malinis na gawain, pagkatapos ng panganib sa body fluids, pagkatapos humawak sa pasyente, at pagkatapos humawak sa paligid niya.",
                "start_ms": 2620,
                "end_ms": 17060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, magpaobserba sa supervisor gamit ang checklist.",
                "start_ms": 17360,
                "end_ms": 22560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: hand hygiene — tamang paglilinis sa tamang pagkakataon.",
                "start_ms": 22860,
                "end_ms": 29220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magpaobserba sa supervisor ng dalawang paraan gamit ang checklist.",
                "start_ms": 29520,
                "end_ms": 35160
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/scene.en.c86730caff7d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c86730caff7d9aa23a3c9e43ad00b4b66d41b7976a6e421bf9ba4b712e776a3c",
            "sha256": "fd6b3677c7902cfbf7795c3acdd88c3c8c28e1434a1fe84a03c1fdc4f3343288",
            "duration_seconds": 25.548,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Lea prepares for simulated care.",
                "start_ms": 1980,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Her hands are visibly dirty.",
                "start_ms": 6360,
                "end_ms": 9000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Soap, water, single-use towels and alcohol-based handrub are available.",
                "start_ms": 9300,
                "end_ms": 16060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A quick rinse is insufficient.",
                "start_ms": 16360,
                "end_ms": 19360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "First choose an appropriate method.",
                "start_ms": 19660,
                "end_ms": 22660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Which method should she choose?",
                "start_ms": 22960,
                "end_ms": 25480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/scene.fil.ebed32b5fab8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ebed32b5fab8eafd66f1753029e131d208a8e9fcf05f13445ec1ffbedb746b40",
            "sha256": "caa72150c9edb17468037d581f99d3127b9d85bef17d3643856f413f19f84e6d",
            "duration_seconds": 27.141,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maghahanda si BHW Lea sa simulated na pag-aalaga.",
                "start_ms": 1980,
                "end_ms": 7340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May nakikitang dumi sa kamay niya.",
                "start_ms": 7640,
                "end_ms": 10040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May sabon, tubig, single-use towel at alcohol-based handrub sa station.",
                "start_ms": 10340,
                "end_ms": 17340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi sapat ang mabilis na pagdaan sa tubig.",
                "start_ms": 17640,
                "end_ms": 21040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Piliin muna ang angkop na paraan.",
                "start_ms": 21340,
                "end_ms": 24260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Aling paraan ang pipiliin?",
                "start_ms": 24560,
                "end_ms": 27080
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/scope.en.915e351a193e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "915e351a193efe719d13445f4617809cc5ec0e5546bd22b289d794b2084740df",
            "sha256": "202ed3157a3bf051fd70cc364a7f83dcefb4eacda50bd9469f3fdb71915ad7b8",
            "duration_seconds": 32.549,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use soap and water for visible dirt and after using the toilet.",
                "start_ms": 2340,
                "end_ms": 7220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gloves do not replace hand hygiene; clean hands after removing them.",
                "start_ms": 7520,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Follow additional IPC instructions for specific infections.",
                "start_ms": 12860,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "This practice is not surgical hand preparation.",
                "start_ms": 18360,
                "end_ms": 21840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "A brief count does not replace the complete procedure.",
                "start_ms": 22140,
                "end_ms": 26420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Soap and water for visible dirt; gloves do not replace hand hygiene.",
                "start_ms": 26720,
                "end_ms": 32480
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/hand-hygiene/scope.fil.e996414d7db7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e996414d7db7fbc1fc215b97c5e34972f73288fbd781b4abe17e81c04e9fc7ee",
            "sha256": "cfd5b45a86f8b8b91c1152f9af85f9e6c3e64923a466fed74383f91db542af66",
            "duration_seconds": 37.355,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sabon at tubig kung may nakikitang dumi at pagkatapos gumamit ng palikuran.",
                "start_ms": 3220,
                "end_ms": 9020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi kapalit ng hand hygiene ang gloves; maglinis pagkatapos alisin ang mga ito.",
                "start_ms": 9320,
                "end_ms": 15800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sundin ang dagdag na instruction ng IPC staff kung may partikular na impeksyon.",
                "start_ms": 16100,
                "end_ms": 21940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi surgical hand preparation ang practice na ito.",
                "start_ms": 22240,
                "end_ms": 26000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag gawing kapalit ng buong procedure ang maikling bilang lamang.",
                "start_ms": 26300,
                "end_ms": 30940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sabon at tubig kung may nakikitang dumi; hindi kapalit ng hand hygiene ang gloves.",
                "start_ms": 31240,
                "end_ms": 37280
              }
            ]
          }
        }
      }
    },
    "hazards-capacities": {
      "module": "chapter2/07-disaster-preparedness",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/07-disaster-preparedness/hazards-capacities/action.en.ad9a575ebd49.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ad9a575ebd49941425338b4299761ef5669c31ed2ac719adf6e9fec46f796886",
            "sha256": "c348f17f04ee65a80106200dbf16bd93cdf5d5fc22cad12e2f5eb4cba0c47f4d",
            "duration_seconds": 26.984,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mark the flood hazard, people who may need help, and possible routes and resources.",
                "start_ms": 2460,
                "end_ms": 9100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record uncertainties.",
                "start_ms": 9400,
                "end_ms": 11480
              },
              {
                "zone": "body",
