        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/example.en.235d18f59083.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "235d18f59083a3b3a9289ecfa7c7cad138f6c71705e3da763eb6dfa7addb8683",
            "sha256": "63ba979cbd86a676beea8e92bcf091001c6b2118b99808d1fdad4f1decf59360",
            "duration_seconds": 37.355,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "When the health worker arrives, Lea says what happened and when.",
                "start_ms": 2060,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She reports the response and breathing she observed, what she has done, the help already called, any changes, and the support needed.",
                "start_ms": 7280,
                "end_ms": 17080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She gives no guess about the injury.",
                "start_ms": 17380,
                "end_ms": 20500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She asks the receiver to confirm the urgent concern and the next action, and records only the facts needed.",
                "start_ms": 20800,
                "end_ms": 29240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea hands over facts and times in order, then asks the receiver to confirm the next action.",
                "start_ms": 29540,
                "end_ms": 37300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/incident-handover/example.fil.e9030b08ce24.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e9030b08ce24dad42e8d51f42bc928411a7db0a4d1085b27d744fec659728646",
