            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pagdating ng health worker, sinasabi ni Lea ang nangyari at kailan.",
                "start_ms": 1860,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iniuulat niya ang nakitang tugon at paghinga, ang ginawa, at ang natawag na tulong.",
                "start_ms": 7600,
                "end_ms": 14200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sinasabi rin niya ang pagbabago at kailangang tulong.",
                "start_ms": 14500,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi siya nanghuhula ng diagnosis.",
                "start_ms": 19280,
                "end_ms": 22520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hinihiling niyang kumpirmahin ng tatanggap ang agarang alalahanin at susunod na hakbang.",
                "start_ms": 22820,
                "end_ms": 29860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Itinatala lamang niya ang kinakailangang facts.",
                "start_ms": 30160,
                "end_ms": 34320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iniuulat ni Lea ang facts at oras nang maayos, saka hinihiling sa tatanggap na kumpirmahin ang susunod na hakbang.",
                "start_ms": 34620,
                "end_ms": 44140
              }
            ]
          }
        },
