            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Source: report symptoms and follow the source-control protocol.",
                "start_ms": 2580,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Environment: have ventilation and layout reviewed.",
                "start_ms": 8120,
                "end_ms": 12640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Work practices: confirm the reporting route and waiting area.",
                "start_ms": 12940,
                "end_ms": 18180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "PPE: use what the task, risk and training require.",
                "start_ms": 18480,
                "end_ms": 23800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "These controls work together.",
                "start_ms": 24100,
                "end_ms": 26540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Complete four rows: source, environment, work practices and PPE. Add a proposal and the person who must confirm it.",
                "start_ms": 26840,
                "end_ms": 37720
              }
            ]
          },
          "fil": {
