                "zone": "body",
                "index": 0,
                "text": "Pinagmulan: ipaalam ang sintomas at sundin ang source-control protocol.",
                "start_ms": 2500,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kapaligiran: ipasuri ang bentilasyon at ayos ng lugar.",
                "start_ms": 9440,
                "end_ms": 14800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gawain: kumpirmahin ang ruta ng pag-uulat at waiting area.",
                "start_ms": 15100,
                "end_ms": 21060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "PPE: gamitin ang itinakda ayon sa gawain, panganib at training.",
                "start_ms": 21360,
                "end_ms": 27720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Magkakasamang kailangan ang mga kontrol.",
                "start_ms": 28020,
                "end_ms": 31100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Punan ang apat na hanay: pinagmulan, kapaligiran, gawain at PPE. Isulat ang mungkahi at taong dapat magkumpirma.",
                "start_ms": 31400,
                "end_ms": 45560
              }
            ]
          }
        },
