          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/example.en.edb3d680746d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "edb3d680746d4ca1c25baf5be30196e98f86c5eba866e711cc7719bba4d7d8dc",
            "sha256": "f49daeb68a0ed2c38442ea881b5cc5422cce2434a57704b0ae7975f4139fd596",
            "duration_seconds": 34.194,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW informs designated staff about the cough.",
                "start_ms": 2060,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Staff identify the waiting area and appropriate mask under the protocol.",
                "start_ms": 7280,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A ventilation concern goes to the responsible person.",
                "start_ms": 13380,
                "end_ms": 17260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The contact for future arrivals is clarified.",
                "start_ms": 17560,
                "end_ms": 21400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The BHW does not decide diagnosis or treatment.",
                "start_ms": 21700,
                "end_ms": 26500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Staff set the waiting area and mask; the ventilation concern goes to the responsible person.",
                "start_ms": 26800,
                "end_ms": 34120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/example.fil.072f25c6f30d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "072f25c6f30d386aa1b5d11ea2e11691c09677f1b75983d3e67ef7e6c99009b7",
            "sha256": "f4b40b4696efefeb9047c06a7b35df3af0a2f6614ee1e704b1694da703db0007",
            "duration_seconds": 34.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipinaalam ng BHW ang pag-ubo sa nakatalagang staff.",
                "start_ms": 1820,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itinuro ng staff ang napiling waiting area at angkop na mask ayon sa protocol.",
                "start_ms": 6960,
                "end_ms": 12920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipinasa sa responsable ang concern sa bentilasyon.",
                "start_ms": 13220,
                "end_ms": 17420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nilinaw ang contact para sa susunod na pagdating.",
                "start_ms": 17720,
                "end_ms": 22120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi nagpasya ang BHW ng diagnosis o treatment.",
                "start_ms": 22420,
                "end_ms": 27260
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Staff ang nagtuturo ng waiting area at mask; sa responsable ang concern sa bentilasyon.",
                "start_ms": 27560,
                "end_ms": 34200
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/next-step.en.e6a7324c1aa1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6a7324c1aa14f156f7de254a486cb97a73226a5ef5b49c25f5702892fd14450",
            "sha256": "c9dbfc0118738ee7028651111221a556dd4814bd2f450bee5904990c985ff37c",
            "duration_seconds": 28.369,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Each control now has an owner.",
                "start_ms": 2660,
                "end_ms": 5580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, map the four types for a fictional BHS.",
                "start_ms": 5880,
                "end_ms": 10480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: layered controls — complementary ways to prevent exposure.",
                "start_ms": 10780,
                "end_ms": 16780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "PPE does not replace safer environments and work practices.",
                "start_ms": 17080,
                "end_ms": 22280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Map the four control types for a fictional BHS, each with an owner.",
                "start_ms": 22580,
                "end_ms": 28300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/next-step.fil.460ee922839b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "460ee922839be0aff80dc0fc7c513ef45b63ade5477b6d98302b2962b151eb66",
            "sha256": "e318fb5e0ec32b01327caf4e96e9dc71497ab038cb2327c077c95d8b86e4f18a",
            "duration_seconds": 34.534,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May responsable na sa bawat kontrol.",
                "start_ms": 2620,
                "end_ms": 5860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, gumawa ng mapa ng apat na uri gamit ang fictional BHS.",
                "start_ms": 6160,
                "end_ms": 12400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: layered controls — magkakaugnay na paraan ng pag-iwas.",
                "start_ms": 12700,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi pinapalitan ng PPE ang maayos na lugar at gawain.",
                "start_ms": 20120,
                "end_ms": 25280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumawa ng mapa ng apat na uri ng kontrol para sa fictional na BHS, may responsable ang bawat isa.",
                "start_ms": 25580,
                "end_ms": 34460
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/scene.en.431426ef60d9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "431426ef60d9af381ed3224c641070125dc94481a766075ae0c7ceecf51c711f",
            "sha256": "720246df8a73ed7644b71111531a1818ad65c6a63e44e2100cf6aac08517bb66",
            "duration_seconds": 28.212,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a simulated BHS, someone is coughing in a crowded queue.",
                "start_ms": 1980,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A window is closed and the BHW does not know whom to notify.",
                "start_ms": 7720,
                "end_ms": 13520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Masks are available, but the process is unclear.",
                "start_ms": 13820,
                "end_ms": 18420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Distributing one item will not address every problem.",
                "start_ms": 18720,
                "end_ms": 23240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Masks are available; the process is incomplete.",
                "start_ms": 23540,
                "end_ms": 28140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/scene.fil.34bd9ab8337d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "34bd9ab8337d0f33122746fa0c4637208187f2aac9b8c513ec4c734ed55d2ec2",
            "sha256": "0749b03174813176b23d040dd466f1a127b84a349b0b0f0b0f8fea5ca6d6fcd5",
            "duration_seconds": 28.212,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa simulated na BHS, may umuubo sa siksik na pila.",
                "start_ms": 1900,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sarado ang bintana at hindi alam ng BHW kung sino ang dapat sabihan.",
                "start_ms": 7800,
                "end_ms": 13840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May mask sa kahon, pero walang malinaw na proseso.",
                "start_ms": 14140,
                "end_ms": 18300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi sapat ang pamimigay ng isang gamit para ayusin ang lahat.",
                "start_ms": 18600,
                "end_ms": 24120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May mask, pero kulang ang proseso.",
                "start_ms": 24420,
                "end_ms": 28140
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/scope.en.b8eecaad323c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b8eecaad323cb9a31add84cf2a0550dfbd9f09d2f71be7d09cf4ed0c0776d11b",
            "sha256": "1c00fdb98429ab154825e46122dea8abe363cbc8d91b9e29c602b448fdef94b7",
            "duration_seconds": 33.698,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not alter ventilation or isolation arrangements without facility guidance.",
                "start_ms": 2460,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A mask is not sufficient for every exposure.",
                "start_ms": 9120,
                "end_ms": 13040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Respirators have different use and fit requirements and need appropriate training.",
                "start_ms": 13340,
                "end_ms": 19260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If protection is inadequate for a task, seek guidance and safe support first.",
                "start_ms": 19560,
                "end_ms": 25800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not change ventilation or isolation alone; a mask is not enough for every exposure.",
                "start_ms": 26100,
                "end_ms": 33620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-control-levels/scope.fil.863503bd51a9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "863503bd51a9521933c962f7a5078c0469fb478b4a83107ce4839cf571d5db4e",
            "sha256": "30835acc5f438246a1ffa45ef618810a2a46494c1391031dfaa02eed03b5e92a",
            "duration_seconds": 33.959,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag baguhin ang bentilasyon o isolation area nang walang gabay ng facility.",
                "start_ms": 3140,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag ituring na sapat ang mask para sa lahat ng exposure.",
                "start_ms": 9200,
                "end_ms": 13480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iba ang gamit at fit requirements ng respirator; kailangan ang angkop na training.",
                "start_ms": 13780,
                "end_ms": 19780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung kulang ang proteksiyon para sa gawain, humingi muna ng gabay at ligtas na suporta.",
                "start_ms": 20080,
                "end_ms": 26800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag baguhin mag-isa ang bentilasyon o isolation; hindi sapat ang mask sa lahat ng exposure.",
                "start_ms": 27100,
                "end_ms": 33900
              }
            ]
          }
        }
      }
    },
    "infection-routes": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/action.en.370eeb0a3d62.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "370eeb0a3d62e661094c9afce84e35320ac4d04813dd7060e5f53988ec6c070d",
            "sha256": "dae257942717a66e2bbcbbfac4410d7e7e44da2195609247064b059260733ae5",
            "duration_seconds": 34.691,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Direct contact involves transfer through direct touch.",
                "start_ms": 2540,
                "end_ms": 6900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Indirect contact involves a contaminated object or hands.",
                "start_ms": 7200,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Infectious respiratory particles may be inhaled or land directly on a nearby person’s eyes, nose or mouth.",
                "start_ms": 12500,
                "end_ms": 21500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A touch or cough alone does not prove infection.",
                "start_ms": 21800,
                "end_ms": 25960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sort eight exposure cards. For each, state a possible route and one control or person to approach.",
                "start_ms": 26260,
                "end_ms": 34620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/action.fil.2de1c18dc613.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2de1c18dc613856123dc802ffd78a90464cd14fc85d21679ed7c5456faf0a1b9",
            "sha256": "ef2c1500722f4011a873e2f95005f2aa9b535dec538cd0fe2a12d5a02a277c1e",
            "duration_seconds": 41.012,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Direct contact: tuwirang paglipat sa pagdikit.",
                "start_ms": 2740,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Indirect contact: dumaraan sa kontaminadong bagay o kamay.",
                "start_ms": 7240,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa hangin, maaaring malanghap ang nakahahawang respiratory particles.",
                "start_ms": 13020,
                "end_ms": 18700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaari ring direktang tumama ang mga ito sa mata, ilong o bibig ng kalapit na tao.",
                "start_ms": 19000,
                "end_ms": 26000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi lahat ng pagdikit o pag-ubo ay patunay ng impeksyon.",
                "start_ms": 26300,
                "end_ms": 31220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ayusin ang walong exposure card. Para sa bawat isa, sabihin ang posibleng daan at isang kontrol o taong lalapitan.",
                "start_ms": 31520,
                "end_ms": 40960
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/check-start.en.5f5aa2f18ed7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5f5aa2f18ed7642c157f367eced4f064672036047c80b13e794ddd076caf0bd2",
            "sha256": "1966e71b127a45037592b4ea2fffc57e75b0aa36e27acf9895178c4fc4f89f05",
            "duration_seconds": 12.957,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2540,
                "end_ms": 4620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4920,
                "end_ms": 8600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The possible transfer is through an object and hands.",
                "start_ms": 8900,
                "end_ms": 12900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/check-start.fil.7fa7ffcc5962.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7fa7ffcc5962635a6eeee38dd5a96c7d12870a66560ad61f88188ca4bd749394",
            "sha256": "d33e1d04e37763fe94416fd0d104c6d317b12479320adf2b15701e131cb7fad9",
            "duration_seconds": 14.733,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2820,
                "end_ms": 4620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 4920,
                "end_ms": 9920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dumaraan sa bagay at kamay ang posibleng mikrobyo.",
                "start_ms": 10220,
                "end_ms": 14660
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/check-transfer.en.0e22ecb800e4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0e22ecb800e4a617654c5c2d9c60701b61cb097040598de1e381d037a8f3f730",
            "sha256": "72f62ffb80361af175a01aedc2b3460400ac0a2d126a7d43c9de6ba07c601bb2",
            "duration_seconds": 16.091,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2580,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4840,
                "end_ms": 7600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Possible inhalation: follow the BHS's agreed arrangements for space, reporting and protection.",
                "start_ms": 7900,
                "end_ms": 16020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/check-transfer.fil.f6a85ded471a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f6a85ded471aee1440101b523c724d6321c9893b4504412d8ed746019a8007b0",
            "sha256": "a80cef7eb219f7f7be3c8841ddb3eb63195639b42187d4cdcd6f11687108c396",
            "duration_seconds": 17.528,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2980,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5120,
                "end_ms": 8600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa posibleng paglanghap, sundin ang napagkasunduang ayos ng lugar, pag-uulat at proteksiyon ng BHS.",
                "start_ms": 8900,
                "end_ms": 17460
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/example.en.1f02bedd4ba4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1f02bedd4ba4ba6dc9602bc08271890bbcb5a1a2ef3725e65350fdaf07d4b3ec",
            "sha256": "eca0c48d7b7e928104e469a61d36f0df01f2223447b6bd6f247a635e29ca6975",
            "duration_seconds": 39.131,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Other cards show fecal contamination of food or water: fecal-oral spread; an infected mosquito bite: vector-borne spread; a contaminated needle: possible blood exposure.",
                "start_ms": 1980,
                "end_ms": 15300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Some infections pass to a baby during pregnancy, birth or breastfeeding.",
                "start_ms": 15600,
                "end_ms": 21600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ordinary social contact alone does not explain these routes.",
                "start_ms": 21900,
                "end_ms": 27180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Match each card with an appropriate preventive action.",
                "start_ms": 27480,
                "end_ms": 31560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Other routes: fecal-oral, vector-borne, blood, and some from mother to child.",
                "start_ms": 31860,
                "end_ms": 39060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/example.fil.81124484c8a9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81124484c8a9af99f12e7efa4f0b32828db12ad3f6551404033d64fdcf33de8a",
            "sha256": "4cf4aae8ec133017760a9adb8eb586beb4841885cae143c5dbf1173420290a73",
            "duration_seconds": 40.438,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May iba pang card: dumi sa pagkain o tubig — fecal-oral; kagat ng lamok na may dalang mikrobyo — vector-borne.",
                "start_ms": 1900,
                "end_ms": 10940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kontaminadong karayom — posibleng pagkalantad sa dugo.",
                "start_ms": 11240,
                "end_ms": 15760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "May ilang impeksyong naipapasa sa sanggol sa pagbubuntis, panganganak o pagpapasuso.",
                "start_ms": 16060,
                "end_ms": 22660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi ito naipapaliwanag ng ordinaryong pakikisalamuha lamang.",
                "start_ms": 22960,
                "end_ms": 28240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Iugnay ang bawat card sa angkop na pag-iwas.",
                "start_ms": 28540,
                "end_ms": 32300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iba pang daan: fecal-oral, vector-borne, dugo, at ilan mula ina sa sanggol.",
                "start_ms": 32600,
                "end_ms": 40360
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/next-step.en.e7d976ac064a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e7d976ac064a42f4e8c465dbef82baedec9d242e7aa310e2c15ddf5bd33820f6",
            "sha256": "77f00c8dae0ef58bd7a3da9487b81dc5ef459e908869bd0f9ea28236cd5f3096",
            "duration_seconds": 30.851,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Jo explains possible routes without labeling people.",
                "start_ms": 2540,
                "end_ms": 7500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, sort the eight cards with a partner and ask the supervisor to review the matches.",
                "start_ms": 7800,
                "end_ms": 14960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: transmission — how germs move.",
                "start_ms": 15260,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Controls depend on tasks and risks rather than guesses.",
                "start_ms": 20120,
                "end_ms": 25000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sort the eight cards with a partner; ask the supervisor to review the matches.",
                "start_ms": 25300,
                "end_ms": 30780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/next-step.fil.5e625893dec2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5e625893dec24a11c375dade2e8ef797cc440da47c556ee129ba6e5d649f5b63",
            "sha256": "c7b99ef72c088a5f1881b632ee6f0b5cc2cc5b02082ef58dead3db1f5d40a2e5",
            "duration_seconds": 33.855,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naipaliwanag ni Jo ang posibleng daan nang walang bansag sa tao.",
                "start_ms": 2660,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, gamitin ang walong card sa kapareha at ipasuri ang pag-uugnay sa supervisor.",
                "start_ms": 8160,
                "end_ms": 15560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: transmission — paraan ng paglipat ng mikrobyo.",
                "start_ms": 15860,
                "end_ms": 21140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang tamang kontrol ay nakabatay sa gawain at panganib, hindi sa hula.",
                "start_ms": 21440,
                "end_ms": 26400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ayusin ang walong card kasama ang kapareha; ipasuri sa supervisor ang pag-uugnay.",
                "start_ms": 26700,
                "end_ms": 33780
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/scene.en.48a843f5c696.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "48a843f5c6963cc579199b18cead13dec8beaf1064ba8b2d47dda2ad714e49eb",
            "sha256": "33f3f80f935606f2e5ca7ff1f1be96236ecf2b5e700fc1a0114a2bbaf668ca05",
            "duration_seconds": 32.183,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Jo has three cards: contaminated hands, a used object and an enclosed room with someone coughing.",
                "start_ms": 1900,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nobody’s illness is known.",
                "start_ms": 12840,
                "end_ms": 15520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Infection involves germs entering and multiplying in the body.",
                "start_ms": 15820,
                "end_ms": 20740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Symptoms may not be obvious.",
                "start_ms": 21040,
                "end_ms": 23760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Identify a possible route, rather than naming a disease.",
                "start_ms": 24060,
                "end_ms": 28620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "What is a possible route for germs?",
                "start_ms": 28920,
                "end_ms": 32120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/scene.fil.ac1dc3240951.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ac1dc324095134cdaeb3c3bdbd601d85bf59083f8431890708bf2992e43891cb",
            "sha256": "3d75626756a47bb44f896650785f5fb36665b34e7178981d21cea390d8905b81",
            "duration_seconds": 33.306,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May tatlong card si BHW Jo: kamay na may kontaminasyon, ginamit na bagay, at saradong silid na may umuubo.",
                "start_ms": 1700,
                "end_ms": 11900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi pa alam ang sakit ng sinuman.",
                "start_ms": 12200,
                "end_ms": 15400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang impeksyon ay pagpasok at pagdami ng mikrobyo sa katawan.",
                "start_ms": 15700,
                "end_ms": 20780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring walang kapansin-pansing sintomas.",
                "start_ms": 21080,
                "end_ms": 24120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kailangang tukuyin ang posibleng daan ng mikrobyo, hindi pangalanan ang sakit.",
                "start_ms": 24420,
                "end_ms": 30180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ano ang posibleng daan ng mikrobyo?",
                "start_ms": 30480,
                "end_ms": 33240
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/scope.en.991513b80042.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "991513b800428ee648cef8dc3640c53e74cd77ada2e8c432cbd68eeaacea7a5f",
            "sha256": "1a72b657188e124a66f29cf96f19a94d458669f8d7b526100b3717baa3bbac66",
            "duration_seconds": 33.228,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A germ may spread by more than one route.",
                "start_ms": 2540,
                "end_ms": 5980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not diagnose or label people from a card or appearance.",
                "start_ms": 6280,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Apply standard precautions to all patients.",
                "start_ms": 11660,
                "end_ms": 15580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Designated clinical staff decide testing, treatment and additional precautions.",
                "start_ms": 15880,
                "end_ms": 22240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not handle needles during practice.",
                "start_ms": 22540,
                "end_ms": 25500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Name a possible route, never a diagnosis; clinical staff decide testing and treatment.",
                "start_ms": 25800,
                "end_ms": 33160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/infection-routes/scope.fil.c8d628c5de9a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c8d628c5de9aa46ddfd78f15cafb4bf7402ea7b3e9ece83036c2b14f5197dafe",
            "sha256": "e19606ce3149b1514ca3ead4b60691f4df2b4e6c3ed7adc992579b35ccb98487",
            "duration_seconds": 37.224,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maaaring higit sa isang daan ang mikrobyo.",
                "start_ms": 3140,
                "end_ms": 6820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag magdiagnose o magbansag batay sa card o hitsura.",
                "start_ms": 7120,
                "end_ms": 11680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sundin ang karaniwang pag-iingat sa lahat ng pasyente.",
                "start_ms": 11980,
                "end_ms": 16260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang desisyon tungkol sa pagsusuri, paggamot at dagdag na precautions ay sa nakatalagang clinical staff.",
                "start_ms": 16560,
                "end_ms": 24720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag humawak ng karayom sa practice.",
                "start_ms": 25020,
                "end_ms": 28420
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Posibleng daan ang sabihin, hindi diagnosis; clinical staff ang nagpapasya sa pagsusuri at paggamot.",
                "start_ms": 28720,
                "end_ms": 37160
              }
            ]
          }
        }
      }
    },
