            "sha256": "16c041f483b9dbb4ecb706613c1a8f6d8fba03e86a4564e6b172df4a64c7cdec",
            "duration_seconds": 17.976,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and safety",
                "start_ms": 0,
                "end_ms": 2184
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Avoid this action: Change the number on paper merely to make it match.",
                "start_ms": 2184,
                "end_ms": 7224
              },
              {
                "zone": "body",
                "index": 1,
                "text": "If the next step is uncertain, consult the midwife or approved local protocol.",
                "start_ms": 7224,
                "end_ms": 12936
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Avoid this action: Change the number on paper merely to make it match.",
                "start_ms": 12936,
                "end_ms": 17976
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter3/12-bhs-equipment-supplies-and-records/inventory/scope.fil.5030c0558ae8.mp3",
            "voice": "fil-PH-BlessicaNeural",
            "content_hash": "5030c0558ae8d83c85e4b7d5af6a38aa0b220f7c3b45d4d515a45b84e8668261",
            "sha256": "a7f1c9d7e44d94203330806ee784111981f1b049170625eb264ecca75dc682ba",
            "duration_seconds": 19.488,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at kaligtasan",
                "start_ms": 0,
                "end_ms": 2328
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Baguhin ang bilang sa papel para lamang magtugma.",
                "start_ms": 2328,
                "end_ms": 7680
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kung hindi tiyak ang susunod na hakbang, humingi ng gabay sa midwife o aprubadong lokal na protocol.",
                "start_ms": 7680,
                "end_ms": 14136
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iwasan ang ganitong kilos: Baguhin ang bilang sa papel para lamang magtugma.",
                "start_ms": 14136,
                "end_ms": 19488
              }
            ]
          }
        }
      }
