    "invite-and-remove-barriers": {
      "module": "chapter2/06-community-mobilization",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/action.en.809f3ff0e9e8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "809f3ff0e9e80c6ee09d3295c77bd3ebc246c3b605bf19aa32a3c0eb2877c8ef",
            "sha256": "d580ba5a255d952cd122eaae501586aeaae92c18463b47e61065c9ca64c2015e",
            "duration_seconds": 40.333,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Identify affected residents, local leaders and others who can help.",
                "start_ms": 2420,
                "end_ms": 8340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ask who is trusted to invite them.",
                "start_ms": 8640,
                "end_ms": 11720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Explore barriers involving time, location, language and speaking.",
                "start_ms": 12020,
                "end_ms": 17700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Agree on options such as personal invitations, suitable timing or small conversations.",
                "start_ms": 18000,
                "end_ms": 25760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not assume a leader represents everyone.",
                "start_ms": 26060,
                "end_ms": 29500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Create rows for Ruben, Sari and Eva. Add each barrier, inviter, invitation method and follow-up date.",
                "start_ms": 29800,
                "end_ms": 40280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/action.fil.59a1e94c4958.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "59a1e94c495888d46e751dd0cf02d0761ccafa9e2475926cdf3992b9e6770f30",
            "sha256": "5581c6fd604260344b10d54b53b42d3959d46f9195f4cf22bcc498330d0229c7",
            "duration_seconds": 43.572,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tukuyin ang apektadong residente, lokal na lider at iba pang makatutulong.",
                "start_ms": 2660,
                "end_ms": 8700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tanungin kung sino ang pinagkakatiwalaang mag-imbita.",
                "start_ms": 9000,
                "end_ms": 12840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alamin ang hadlang sa oras, lugar, wika at pagsasalita.",
                "start_ms": 13140,
                "end_ms": 19780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magkasundo sa paraan: personal na paanyaya, angkop na oras o maliit na usapan.",
                "start_ms": 20080,
                "end_ms": 28160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag ipagpalagay na kinakatawan ng lider ang lahat.",
                "start_ms": 28460,
                "end_ms": 32860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumawa ng tatlong hanay para kina Ruben, Sari at Eva. Ilagay ang hadlang, tagapag-imbita, paraan at petsa ng pagbalik.",
                "start_ms": 33160,
                "end_ms": 43520
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/check-start.en.6a6bc4b9abd5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6a6bc4b9abd59de5f24a31bfa3c1228ed1628d8f78bd1aec2bdd31ef29a7883c",
            "sha256": "683fa79a12f32320cf516cc7ef92b695feaff3db02e011f6047d63e702c33bb3",
            "duration_seconds": 12.016,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2620,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4960,
                "end_ms": 8560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sari helps choose a method she can use.",
                "start_ms": 8860,
                "end_ms": 11940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/check-start.fil.27b1741b03c7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "27b1741b03c74980a93753d781af211b09ab336f623f66651d6a10e5ea4a34f8",
            "sha256": "cca90b264ffc7c397db6ad626e63b6831cc0f5df1759cfc7515f635e6c69e30f",
            "duration_seconds": 14.811,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2860,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5280,
                "end_ms": 10160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kasama si Sari sa pagpili ng magagamit na paraan.",
                "start_ms": 10460,
                "end_ms": 14740
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/check-transfer.en.7b77626a3423.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7b77626a34237fc4e02f9e40279462b97d370d592593420b4c713f5e149c0c8e",
            "sha256": "1eb0edd10bd99d8e07d8e5fb175874eed8ef2bde263ab1db359a433782aa7e8b",
            "duration_seconds": 12.095,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2620,
                "end_ms": 4500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4800,
                "end_ms": 7520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This respects the barrier while allowing participation.",
                "start_ms": 7820,
                "end_ms": 12020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/check-transfer.fil.54f9357cee1d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "54f9357cee1d503c4908cd6cc63647c5f5fdac3af2dc783c96b4085005daac7d",
            "sha256": "efdb20d2a2073c347f270a55592c27458b49597d1ecfd3c39be545b19d288d38",
            "duration_seconds": 13.296,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2460,
                "end_ms": 4300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4600,
                "end_ms": 7920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nirerespeto ang hadlang habang binubuksan ang pakikilahok.",
                "start_ms": 8220,
                "end_ms": 13220
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/example.en.97fc57e1208c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "97fc57e1208c29c9705394619b0174390000eb3f3e4ea80e00b7492d9acd05f0",
            "sha256": "b26034f967e96a86bcb931bec34a92e20a14cc7c694e3cb28c118b852f78e7b2",
            "duration_seconds": 31.347,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "With the leader, Ina asks Ruben about timing.",
                "start_ms": 2100,
                "end_ms": 6340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sari chooses a personal invitation.",
                "start_ms": 6640,
                "end_ms": 9760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Eva prefers a small conversation.",
                "start_ms": 10060,
                "end_ms": 13220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "They record who will invite each group and when to report back.",
                "start_ms": 13520,
                "end_ms": 18600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Participation is voluntary, with another way to offer suggestions.",
                "start_ms": 18900,
                "end_ms": 24180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Plans for all three barriers with clear inviters and voluntary participation options.",
                "start_ms": 24480,
                "end_ms": 31280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/example.fil.b234fbbf2573.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b234fbbf2573bbe6ce7ff1850485a6c65a633b59663044c08ddeb29cb53eeede",
            "sha256": "a2ca5f40efc9bdd32374c6d5cb923822e1fdb445c4888182e55d4905997391fb",
            "duration_seconds": 36.023,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kasama ang lider, tinanong ni Ina si Ruben tungkol sa oras.",
                "start_ms": 2060,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Personal na paanyaya ang pinili ni Sari.",
                "start_ms": 7480,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mas nais ni Eva ang maliit na usapan.",
                "start_ms": 11660,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinala nila kung sino ang mag-iimbita at kailan magbabalita.",
                "start_ms": 15480,
                "end_ms": 21000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Nilinaw na kusang-loob ang pagsali at puwedeng magbigay ng mungkahi sa ibang paraan.",
                "start_ms": 21300,
                "end_ms": 27540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May plano para sa tatlong hadlang, malinaw na tagapag-imbita at kusang-loob na paraan ng pakikilahok.",
                "start_ms": 27840,
                "end_ms": 35960
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/next-step.en.9b4db6217d5c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9b4db6217d5c1cb2bde96036871d1dbe59637cdf9e229462f0e991d70977aefd",
            "sha256": "7195516870b26c13846a9b3971641ecef2766fd5a689f2b9505a1103133e2625",
            "duration_seconds": 29.858,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Invitations now respond to the barriers discussed.",
                "start_ms": 2380,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, create an invitation map using fictional roles.",
                "start_ms": 6560,
                "end_ms": 11680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: stakeholder — someone affected by or able to contribute to the issue.",
                "start_ms": 11980,
                "end_ms": 19300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Attendance is only a start; meaningful participation matters.",
                "start_ms": 19600,
                "end_ms": 24960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, make an invitation map for a fictional case.",
                "start_ms": 25260,
                "end_ms": 29780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/next-step.fil.323eb383f9da.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "323eb383f9dac68c71167360848042ad43e5e6b664e4da5046274f6fab7d283a",
            "sha256": "5fe272571d2037c489434a6ddd0f04be6523ca87f77f81c902cfa5c635f9f06a",
            "duration_seconds": 33.515,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May iba-ibang paraan ng paanyaya ayon sa napag-usapang hadlang.",
                "start_ms": 2340,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, gumawa ng mapa ng paanyaya gamit ang kathang-isip na mga papel.",
                "start_ms": 7720,
                "end_ms": 14800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: stakeholder — taong apektado o may maiaambag sa isyu.",
                "start_ms": 15100,
                "end_ms": 22220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang pagdalo ay simula lamang; mahalaga ang aktuwal na pakikilahok.",
                "start_ms": 22520,
                "end_ms": 27960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, gumawa ng invitation map para sa kathang-isip na kaso.",
                "start_ms": 28260,
                "end_ms": 33460
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/scene.en.fc354b4be8e1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fc354b4be8e15bd4f2dd687230dcf32bf2d2d9d7d572a826491288495f3e9110",
            "sha256": "a57300bec6dcfe93aa7daa6b6755dc0bccea628e98d94dd1ecd6d066fc465bcb",
            "duration_seconds": 25.835,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ina will convene a discussion about late schedule updates.",
                "start_ms": 1980,
                "end_ms": 6340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A local leader is trusted by residents.",
                "start_ms": 6640,
                "end_ms": 9880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ruben works during the day.",
                "start_ms": 10180,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sari has no phone.",
                "start_ms": 12760,
                "end_ms": 14920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Eva feels nervous speaking in a large group.",
                "start_ms": 15220,
                "end_ms": 19420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "One chat invitation is not enough.",
                "start_ms": 19720,
                "end_ms": 22920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "One chat is not enough.",
                "start_ms": 23220,
                "end_ms": 25780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/scene.fil.da600c79ba6b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "da600c79ba6bc70977b3a37b354a16ad3b0fd07178e4fad9f7297fa0cfd59cd3",
            "sha256": "cef06bc8fa8f0aac6c9872efac78deab89519169a4b3785241eb2c2111a1b7a9",
            "duration_seconds": 28.97,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Magpapatawag ng usapan si Ina tungkol sa huling balita sa iskedyul.",
                "start_ms": 1940,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May lider na kilala ng mga residente.",
                "start_ms": 8000,
                "end_ms": 11080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Si Ruben ay nagtatrabaho sa araw.",
                "start_ms": 11380,
                "end_ms": 14500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Si Sari ay walang cellphone.",
                "start_ms": 14800,
                "end_ms": 17760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Si Eva ay kinakabahang magsalita sa malaking grupo.",
                "start_ms": 18060,
                "end_ms": 22340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi sapat ang isang chat invitation.",
                "start_ms": 22640,
                "end_ms": 26040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi sapat ang iisang chat.",
                "start_ms": 26340,
                "end_ms": 28900
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/scope.en.3d795e3a9ce6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3d795e3a9ce61f57697d8c2154b2663cfc455b2b09d10ef7d41c94f11a39e686",
            "sha256": "accdd11a95d2a6091424374abf9da85e96ff3299132d42b2faec02b55510f3a7",
            "duration_seconds": 30.877,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not make attendance a condition for services.",
                "start_ms": 2700,
                "end_ms": 6620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not promise payment or rewards to recruit participants.",
                "start_ms": 6920,
                "end_ms": 12080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Clarify practical participation support with the organizer under local policy.",
                "start_ms": 12380,
                "end_ms": 18020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Respect refusal and do not expose someone’s personal reason.",
                "start_ms": 18320,
                "end_ms": 23120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Participation is voluntary: services never depend on attendance, and no rewards are promised.",
                "start_ms": 23420,
                "end_ms": 30820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/06-community-mobilization/invite-and-remove-barriers/scope.fil.ad7aa6c26f5b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ad7aa6c26f5bb4648e75fd4201f4af9e0e2ec3410f11228695b5a98bae572f31",
            "sha256": "a9c7f6df17dbcec7653cbd99244476f0b1b860e9e3b28c6692e8f560f4da9907",
            "duration_seconds": 32.418,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag gawing kondisyon sa serbisyo ang pagdalo.",
                "start_ms": 3140,
                "end_ms": 6620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag mangako ng bayad o gantimpala para makahikayat.",
                "start_ms": 6920,
                "end_ms": 11320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang praktikal na suporta sa pakikilahok ay kailangang linawin sa organizer ayon sa lokal na patakaran.",
                "start_ms": 11620,
                "end_ms": 19340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Igalang ang pagtanggi at huwag ilantad ang personal na dahilan nito.",
                "start_ms": 19640,
                "end_ms": 24880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kusang-loob ang pagsali: walang serbisyong kapalit ng pagdalo at walang pangakong gantimpala.",
                "start_ms": 25180,
                "end_ms": 32340
              }
            ]
          }
        }
      }
    },
    "ipc-monitor-and-improve": {
      "module": "chapter2/03-infection-control",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/action.en.02f9e217da24.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "02f9e217da24107923e5cf9df0f410b1fdd7ba020e25a39565c87b5be5d563d0",
            "sha256": "01bafa888de3ede797c3575976003ddc9dc8a92ea6c8e9c7536bb0aec563a05b",
            "duration_seconds": 36.023,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Record the specific observation, place and time.",
                "start_ms": 2380,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Report the gap and follow the agreed safe interim arrangement.",
                "start_ms": 7240,
                "end_ms": 12200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Agree on an action, owner and follow-up.",
                "start_ms": 12500,
                "end_ms": 16860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Choose an observable measure: is soap available and does the station work?",
                "start_ms": 17160,
                "end_ms": 22840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not infer complete practice from attendance.",
                "start_ms": 23140,
                "end_ms": 27340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Make an improvement card for missing soap. Record the interim arrangement and two possible follow-up outcomes.",
                "start_ms": 27640,
                "end_ms": 35960
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/action.fil.280d6fcf858d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "280d6fcf858dd9161fdfdddf05b3db1bdb6cc2bde455624b3eaab7592a5b944f",
            "sha256": "6cb76d5c5ee915bcff1522eadfce5a58c31266aa533d78c4da1dee9f04600a66",
            "duration_seconds": 40.751,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Itala ang tiyak na nakita, lugar at oras.",
                "start_ms": 2620,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipaalam ang kakulangan sa responsable at sundin ang pansamantalang ligtas na kaayusan.",
                "start_ms": 7760,
                "end_ms": 14800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magkasundo sa gagawin, tao at follow-up.",
                "start_ms": 15100,
                "end_ms": 19900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pumili ng panukat na makikita: may sabon ba at gumagana ba ang station?",
                "start_ms": 20200,
                "end_ms": 26160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag ipagpalagay na kumpleto ang practice dahil may attendance.",
                "start_ms": 26460,
                "end_ms": 31180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gumawa ng improvement card para sa kulang na sabon. Itala ang pansamantalang kaayusan at resulta ng dalawang posibleng follow-up.",
                "start_ms": 31480,
                "end_ms": 40680
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/check-start.en.4323c0f8180f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4323c0f8180f69688d92f5612cc791c18d365f4ba0698f662689f457aaac35fd",
            "sha256": "6affb6f497e888a7b891c1de748f76f117e9ba8a28e8905f6997ec7cc4451e85",
            "duration_seconds": 13.322,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5040,
                "end_ms": 8640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This identifies what was seen, where and when.",
                "start_ms": 8940,
                "end_ms": 13260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/check-start.fil.4ea27982f22b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ea27982f22b2a0ed7d408ca8b3feea1616cc76c177b546be406c6f38309db88",
            "sha256": "c46166953cb8afe272e51eb3cb6066f6e60993f031c1ef6559b6d6b444abc9b7",
            "duration_seconds": 16.091,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 3180,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5960,
                "end_ms": 10960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Malinaw ang nakita, lugar at oras.",
                "start_ms": 11260,
                "end_ms": 16020
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/check-transfer.en.e87d98168cf7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e87d98168cf7ce98ab16e890e142337ee7007c2f89bf1760e26d719375ebfe6c",
            "sha256": "d675a9a6b54a43198751bee28d8547dbce82be6e898fbdde31ba2dfb6f77f0fd",
            "duration_seconds": 12.042,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2820,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5120,
                "end_ms": 7880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The record is accurate and prompts further action.",
                "start_ms": 8180,
                "end_ms": 11980
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/check-transfer.fil.e78aa4ed3c6e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e78aa4ed3c6ede80f11a9aa5dba150005683e1ec4bc574e408aa3e2cca455836",
            "sha256": "e6f38ce6fcc47b464e6cfb8367eec9099681ed98679b768e8fd8ace268827194",
            "duration_seconds": 13.218,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3060,
                "end_ms": 5340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5640,
                "end_ms": 9240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tapat ang tala at may susunod na aksyon.",
                "start_ms": 9540,
                "end_ms": 13140
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/example.en.0418c0f598f4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0418c0f598f4b2803d60f5bf8e02fb7c5cba7a867b2a996a62fd5c338f9e4e49",
            "sha256": "9e6edf450169530a7ceef9fd654d18c3ec81acfc46e3107e9b393b9bb84fcd60",
            "duration_seconds": 33.306,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Aya records: “Station A, nine o’clock: no soap.”",
                "start_ms": 1940,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The nurse arranges a refill and an interim station.",
                "start_ms": 7280,
                "end_ms": 11720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "At follow-up, soap and running water are available.",
                "start_ms": 12020,
                "end_ms": 16260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Aya records the date and evidence.",
                "start_ms": 16560,
                "end_ms": 20480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If unresolved, she records that honestly and reports it again.",
                "start_ms": 20780,
                "end_ms": 25780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "At follow-up, record the evidence, or record the gap as unresolved and report it again.",
                "start_ms": 26080,
                "end_ms": 33240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/example.fil.8fc4a4c78fbc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8fc4a4c78fbc33151744b9f9bf05a38ea870d885caba31940cdb1f7177be1b89",
            "sha256": "21d3afeb2c97d2cb6311b9a0b9ff1184a9a21feed22637fdc9f7ceaf2e85e39e",
            "duration_seconds": 36.754,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tala ni Aya: “Station A, alas-nuwebe: walang sabon.”",
                "start_ms": 1900,
                "end_ms": 8020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipinaalam sa nurse, na nagtakda ng refill at pansamantalang station.",
                "start_ms": 8320,
                "end_ms": 14000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa pagbalik, may sabon na at gumagana ang tubig.",
                "start_ms": 14300,
                "end_ms": 18660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Isinulat ang petsa at ebidensiya.",
                "start_ms": 18960,
                "end_ms": 22280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung hindi pa naayos, “hindi pa naayos” ang ilalagay at muling ipaaalam.",
                "start_ms": 22580,
                "end_ms": 29060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa follow-up, itala ang ebidensiya, o itala na hindi pa naayos at muling ipaalam.",
                "start_ms": 29360,
                "end_ms": 36680
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/next-step.en.125dc0920e02.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "125dc0920e02d4de09f5a5a7fda544963d85be3bbb3f7816bc29786c7af24b73",
            "sha256": "77e3c7c5d24ee7cfff181e42e201cffbff2c97026bc5e162ebc2fd97b51b5768",
            "duration_seconds": 31.713,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The supply gap is addressed with follow-up evidence.",
                "start_ms": 2340,
                "end_ms": 6540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, use a blank improvement card for a fictional station with the supervisor.",
                "start_ms": 6840,
                "end_ms": 13080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: monitoring — repeated checks using agreed criteria.",
                "start_ms": 13380,
                "end_ms": 20020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Distinguish what is known, observed and still unverified.",
                "start_ms": 20320,
                "end_ms": 25880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Complete a blank improvement card for a fictional station with the supervisor.",
                "start_ms": 26180,
                "end_ms": 31660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/next-step.fil.936385633618.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "936385633618c94efa55b93a22cee58dcdc13878d69fa923c52ca4c466e8257e",
            "sha256": "9fc7d3a8cd1d5f55231e4e6efcff258a90563805fbd6578b50139194d6ca4a87",
            "duration_seconds": 36.049,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naayos ang supply gap at may ebidensiya ng follow-up.",
                "start_ms": 2660,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, gamitin ang blangkong improvement card sa fictional na station kasama ang supervisor.",
                "start_ms": 7680,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: monitoring — paulit-ulit na pagsusuri gamit ang napagkasunduang batayan.",
                "start_ms": 16180,
                "end_ms": 24060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ihiwalay ang alam, nakita at kailangan pang suriin.",
                "start_ms": 24360,
                "end_ms": 29480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Punan ang blangkong improvement card para sa fictional na station kasama ang supervisor.",
                "start_ms": 29780,
                "end_ms": 35980
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/scene.en.9096a960f301.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9096a960f301db36b89d062417be41e72d86a0f2a0fcf4393b1813203dc35981",
            "sha256": "ddc29e6e1e8dfeabe46ce185f078953a35b9cb9b919cbc05b443fcd9eed80fa7",
            "duration_seconds": 29.231,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "During a practice inspection, the handwashing station has no soap.",
                "start_ms": 1940,
                "end_ms": 6860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The training attendance sheet is complete.",
                "start_ms": 7160,
                "end_ms": 10320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A colleague says, “Everyone attended, so we are fine.”",
                "start_ms": 10620,
                "end_ms": 14700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "BHW Aya recognizes that attendance, supplies and actual practice differ.",
                "start_ms": 15000,
                "end_ms": 22200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "What should she record?",
                "start_ms": 22500,
                "end_ms": 24620
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Attendance does not prove supplies or practice.",
                "start_ms": 24920,
                "end_ms": 29160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/scene.fil.5f3fb584b2c0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5f3fb584b2c013d713f065f2c3a056462d6178faf686095b7b67054b34e9beb4",
            "sha256": "f030e55027b05a7b2f0988d46a9fd41fbfdba9c33eb2e9edca50828884e67374",
            "duration_seconds": 30.537,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
