        "scope": {
          "en": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/scope.en.631f72102ea6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "631f72102ea61ba0390e8830d88bc5f970c60c09b5e69a8d3b965bb85914e544",
            "sha256": "33b940326233a33214839e043c426adc20f4380f54d8037a51ff7cade1dc094b",
            "duration_seconds": 35.318,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Follow local observation and privacy rules.",
                "start_ms": 2860,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "BHWs are not automatically authorized to conduct clinical audits or investigate outbreaks.",
                "start_ms": 6720,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Report exposures or immediate hazards promptly rather than waiting for routine follow-up.",
                "start_ms": 15060,
                "end_ms": 21900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Quiz completion does not replace observation of a procedure.",
                "start_ms": 22200,
                "end_ms": 27040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "BHWs do not run clinical audits; report exposures and immediate hazards promptly.",
                "start_ms": 27340,
                "end_ms": 35260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/03-infection-control/ipc-monitor-and-improve/scope.fil.248505a3f8a1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "248505a3f8a19c6e2dc2b4499832b08baef1101aff7f4eca02bdc633adc804dc",
            "sha256": "05e8307bd27fe826f231caa6a0b5a72bb8fb5980dc8ae60f18ec27875d0e2d29",
            "duration_seconds": 36.833,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sundin ang lokal na observation at privacy rules.",
                "start_ms": 3060,
                "end_ms": 7540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi awtomatikong awtorisado ang BHW na magsagawa ng clinical audit o mag-imbestiga ng outbreak.",
                "start_ms": 7840,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iulat agad ang exposure o agarang panganib; huwag hintayin ang petsa ng routine follow-up.",
                "start_ms": 16180,
                "end_ms": 23500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang quiz completion ay hindi kapalit ng naobserbahang procedure.",
                "start_ms": 23800,
                "end_ms": 28720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi nagsasagawa ang BHW ng clinical audit; iulat agad ang exposure at agarang panganib.",
                "start_ms": 29020,
                "end_ms": 36780
              }
            ]
          }
        }
      }
