    "listen-and-clarify": {
      "module": "chapter2/01-difficult-situations",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/action.en.0c5a5b2116de.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0c5a5b2116de19013bb8aefc7ece7f270ee813305acb7367ef7636db86d55999",
            "sha256": "a7289e962f049a6848dfcba5e271ad6b0babac344418dd43016057cd3c9e6ef5",
            "duration_seconds": 30.171,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use a calm voice.",
                "start_ms": 2500,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Say, “I would like to hear what happened.”",
                "start_ms": 5200,
                "end_ms": 8680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Offer a more private, safe place if she wants.",
                "start_ms": 8980,
                "end_ms": 12980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask, “What concerns you most?”",
                "start_ms": 13280,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Listen without interrupting.",
                "start_ms": 16420,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Summarize what she said, then ask, “Have I understood correctly?”",
                "start_ms": 19280,
                "end_ms": 24120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ask about the concern, listen, summarize and check understanding.",
                "start_ms": 24420,
                "end_ms": 30100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/listen-and-clarify/action.fil.de3b74349779.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "de3b743497797036d9cb9c5cd6f4cca24be18fb446250cf10089596105664bbb",
            "sha256": "94fbf4944f39c9b532bda2580b0d4234f4b281d9293b8f2657c7820b483d573b",
            "duration_seconds": 37.016,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Magsalita sa mahinahong boses.",
                "start_ms": 3060,
                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sabihin: “Gusto ko pong marinig ang nangyari.”",
                "start_ms": 6360,
                "end_ms": 10400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mag-alok ng lugar na mas pribado at ligtas kung nais niya.",
                "start_ms": 10700,
                "end_ms": 15460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magtanong: “Ano po ang pinaka-inaalala ninyo?”",
                "start_ms": 15760,
                "end_ms": 19880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Makinig nang hindi sumasabat.",
                "start_ms": 20180,
                "end_ms": 23020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ibuod ang sinabi, saka itanong: “Tama po ba ang pagkaintindi ko?”",
                "start_ms": 23320,
                "end_ms": 29000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Itanong ang alalahanin, makinig, ibuod at ipasuri ang pagkaintindi.",
                "start_ms": 29300,
                "end_ms": 36940
              }
            ]
          }
        },
