                "end_ms": 13700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Is that right?”",
                "start_ms": 14000,
                "end_ms": 15480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Liza: “Yes, that is the problem.”",
                "start_ms": 15780,
                "end_ms": 19860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Jun clarifies the concern before suggesting a step.",
                "start_ms": 20160,
                "end_ms": 24280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "In the conversation with Liza, uses a calm voice and open question, lets her finish, summarizes her reply and invites correction.",
                "start_ms": 24580,
                "end_ms": 35620
              }
