                "end_ms": 6060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ko alam kung sino ang kakausapin.”",
                "start_ms": 6360,
                "end_ms": 9480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Jun: “Dalawang punta na po, pero hindi pa malinaw kung sino ang tutulong.",
                "start_ms": 9780,
                "end_ms": 15620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tama po ba?”",
                "start_ms": 15920,
                "end_ms": 17240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Liza: “Oo, iyon ang problema.”",
                "start_ms": 17540,
                "end_ms": 21740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Nalinaw ang alalahanin bago nagbigay ng mungkahi si Jun.",
                "start_ms": 22040,
                "end_ms": 26600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa usapan kay Liza, gumamit ng mahinahong boses at bukas na tanong; hinayaang matapos ang sagot; ibinuod ito at humingi ng pagwawasto.",
                "start_ms": 26900,
                "end_ms": 37860
              }
            ]
