                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "At a barangay in Iloilo, Liza meets BHW Jun.",
                "start_ms": 2060,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“You keep coming back.",
                "start_ms": 8000,
                "end_ms": 9880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nothing happens!”",
                "start_ms": 10180,
                "end_ms": 11860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Her voice is raised.",
                "start_ms": 12160,
                "end_ms": 14400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "People in the queue are listening.",
                "start_ms": 14700,
                "end_ms": 17180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Jun needs to find out what happened without arguing.",
