            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Calm listening is not a promise to grant every request.",
                "start_ms": 2460,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Clarify and connect the resident with the appropriate staff.",
                "start_ms": 7720,
                "end_ms": 12040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the midwife or supervisor for support when the situation is unsafe or beyond your role.",
                "start_ms": 12340,
                "end_ms": 19740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If there is immediate danger, use the local emergency service from a safe place.",
                "start_ms": 20040,
                "end_ms": 25960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Seek the appropriate support when a situation exceeds your role.",
                "start_ms": 26260,
                "end_ms": 31580
