                "end_ms": 21220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Dinala niya ang tanong ni Joel sa clinician nito.",
                "start_ms": 21520,
                "end_ms": 25160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa bawat worksheet, minarkahan niyang kulang ang local authorization.",
