            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c9f372865232a69e855e580d44d43167f6a882669929367780dbbd20a46691b5",
            "sha256": "018510967bceec374aedd9d16460c5f3cf944d942b2d6815b3b60a62e3f8f319",
            "duration_seconds": 34.403,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW reads the current card and listens to the resident.",
                "start_ms": 2100,
                "end_ms": 7100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Both plants are called “tsaang gubat,” but the card lists one botanical name and part.",
                "start_ms": 7400,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "The identity of the yard plants is uncertain, so the BHW does not prepare or provide either one.",
                "start_ms": 13980,
                "end_ms": 22420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The BHW asks about symptoms and medicines and consults a clinician.",
                "start_ms": 22720,
                "end_ms": 28280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Two plants, one name: the card, not the name, guides the check.",
                "start_ms": 28580,
                "end_ms": 34340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/example.fil.7d5af14cf46f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7d5af14cf46ffa196efde2a9407901e74cba36ebdf6c2e871002e13625c5a777",
            "sha256": "e4af1243052b5f7a836199a08f53e67ab040f18d7abbfdae93525f371015d323",
            "duration_seconds": 37.642,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Binasa ng BHW ang kasalukuyang card at pinakinggan ang residente.",
                "start_ms": 2060,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Parehong tinatawag na “tsaang gubat” ang dalawang halaman, pero iisang botanical name at bahagi ang nasa card.",
                "start_ms": 8400,
                "end_ms": 16240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi tiyak ang identity ng mga halaman, kaya hindi naghanda o nagbigay ang BHW.",
                "start_ms": 16540,
                "end_ms": 23820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinanong niya ang sintomas at gamot, at iniugnay ang residente sa clinician.",
                "start_ms": 24120,
                "end_ms": 30400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Dalawang halaman, iisang pangalan: ang card, hindi ang pangalan, ang batayan.",
                "start_ms": 30700,
                "end_ms": 37580
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/next-step.en.83bcdfdbe87d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "83bcdfdbe87d4c7dd00572c5000b8fcb2f7d14c75ed4cbb0dde078900599e0a9",
            "sha256": "a6e250862563f6bd3e1dafea1ca7d46cf43a9b745502b1faadea9ff197bf8097",
            "duration_seconds": 15.856,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, review the card with a supervisor.",
                "start_ms": 2580,
                "end_ms": 6140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mark what needs confirmation before a real consultation.",
                "start_ms": 6440,
                "end_ms": 10920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "On Monday, mark with a supervisor what needs confirmation.",
                "start_ms": 11220,
                "end_ms": 15780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/next-step.fil.754bae2a594d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "754bae2a594d04d98e6d684f44e94334d7ed0dcc2d6c02aa42ade00ac2601256",
            "sha256": "4924d7a36b73108ea61417e9a6a746b806918d5e031f684dc0867a001ec667ff",
            "duration_seconds": 18.521,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, dalhin ang card sa supervisor.",
                "start_ms": 2820,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Markahan ang dapat kumpirmahin bago gamitin sa tunay na konsultasyon.",
                "start_ms": 6720,
                "end_ms": 12640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa Lunes, markahan kasama ang supervisor ang dapat kumpirmahin.",
                "start_ms": 12940,
                "end_ms": 18460
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scene.en.485a5ce17d0c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "485a5ce17d0c1e189796765c9e76e76e10ebac1ff895398850e6d99e416032ff",
            "sha256": "8ba77d3ac1024537124d7fc088cd6ba833e22a3716066274d98d43de2b3ff99a",
            "duration_seconds": 15.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Two yard plants share the local name “tsaang gubat.”",
                "start_ms": 1940,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A resident asks which one to use.",
                "start_ms": 6680,
                "end_ms": 9760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: two yard plants are both called “tsaang gubat”",
                "start_ms": 10060,
                "end_ms": 15060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scene.fil.c12f4794501c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c12f4794501c26e381dae33b3c0c5780aef8b94ebea0654aae0baf5da23d9257",
            "sha256": "9f65418374ac75c430e0645a0c99bfd5a8eaf6685e5c907692f2a4658c57404d",
            "duration_seconds": 17.528,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dalawang halaman sa isang bakuran ang parehong tinatawag na “tsaang gubat.”",
                "start_ms": 1740,
                "end_ms": 7700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong ang residente kung alin ang gagamitin.",
                "start_ms": 8000,
                "end_ms": 11520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: dalawang halaman sa bakuran ang tinatawag na “tsaang gubat”",
                "start_ms": 11820,
                "end_ms": 17460
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scope.en.c72be68bc2e6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c72be68bc2e6fde15c0718f3ebcfb93dca7960eeff787c6f3ebe55885dd61e54",
            "sha256": "ff59a3eacb871507a5b11ad4589a3bf223c0f7856280acf3e2865cdf025e9c1b",
            "duration_seconds": 18.756,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A local name, picture or “natural” label alone does not establish identity, efficacy or safety.",
                "start_ms": 2500,
                "end_ms": 11900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A name, picture or “natural” label is not proof of identity or safety.",
                "start_ms": 12200,
                "end_ms": 18680
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/plant-scope-identification/scope.fil.d07784a4502e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d07784a4502e3a6ab34b79b7540fb126264d1361d86ed600c234fb6e6f436f6f",
            "sha256": "e8bf078d60e69b40a32b6c997faaa6e7b3d6f45fbd1af53341f84bb90272aa0f",
            "duration_seconds": 21.185,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang local name, larawan at “natural” na label ay hindi sapat na patunay ng identity, bisa o kaligtasan.",
                "start_ms": 3460,
                "end_ms": 13300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi patunay ng identity o kaligtasan ang pangalan, larawan o “natural” na label.",
                "start_ms": 13600,
                "end_ms": 21120
              }
            ]
          }
        }
      }
    },
    "poisoning-response": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/action.en.097459e8f1fd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "097459e8f1fd91e60a3f08034089d479c6a5cc39190262a69146cd7c26708e7e",
            "sha256": "f7abd1921ac1dedac7581be50e781e4c4943b31655b6fafeeeec824e07f8881b",
            "duration_seconds": 40.098,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Avoid exposure, move others away and activate the verified emergency or poison-advice route.",
                "start_ms": 2100,
                "end_ms": 9940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Read the product label only if you can do so without exposure, such as from a container already away from the spill or held by someone else.",
                "start_ms": 10240,
                "end_ms": 20520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Give the label, estimated time, exposure route, symptoms and age to the responder.",
                "start_ms": 20820,
                "end_ms": 29340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Follow their instructions.",
                "start_ms": 29640,
                "end_ms": 31920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Rehearse the information call from a fictional label while keeping the simulated scene clear of exposure.",
                "start_ms": 32220,
                "end_ms": 40020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/action.fil.5af6cc549e65.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5af6cc549e651a5e57d340e79b73f1639538363c0ecc2c5652a59abce767fe0c",
            "sha256": "2789cf38cbffd858f3c22ea6bd42b7e8d99faa25667b8709a40944c37308e746",
            "duration_seconds": 38.113,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iwasan ang exposure, ilayo ang iba at tawagan ang kumpirmadong emergency o poison adviser.",
                "start_ms": 2700,
                "end_ms": 10860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Basahin lamang ang label kung walang exposure, gaya ng lalagyang malayo na sa spill o hawak ng iba.",
                "start_ms": 11160,
                "end_ms": 18720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ibigay ang label, tinatayang oras, paraan ng exposure, sintomas at edad.",
                "start_ms": 19020,
                "end_ms": 27100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sundin ang kanilang tagubilin.",
                "start_ms": 27400,
                "end_ms": 30080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang tawag gamit ang kathang-isip na label habang iniiwasan ang simulated exposure.",
                "start_ms": 30380,
                "end_ms": 38060
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/check-start.en.636274e8360d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "636274e8360d85e525db5975f8b88061e39320d27a5771fb2f2d017d311d36f8",
            "sha256": "45d1e16458f25f8bd37a54feddfa94be6009e61792b624212be860ad2da3e423",
            "duration_seconds": 14.237,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2740,
                "end_ms": 4940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5240,
                "end_ms": 8440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Move away from the smell and call the verified advice route first.",
                "start_ms": 8740,
                "end_ms": 14180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/check-start.fil.5addd48f722d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5addd48f722dc5302af486a21e5d33000c0e5557e6b73434dde7e3517e55a240",
            "sha256": "23473c4e97676bdf635a6f9de48fa5ee9f36d1dbe4a9af611dece920034c555c",
            "duration_seconds": 15.804,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2580,
                "end_ms": 4700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5000,
                "end_ms": 10400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lumayo sa amoy at unahing tawagan ang kumpirmadong adviser.",
                "start_ms": 10700,
                "end_ms": 15740
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/check-transfer.en.3c3ea6e5494e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3c3ea6e5494ee41a935bb962c0cfca9feb7323f0668bf8ba220c64719e0f0389",
            "sha256": "b1c70703734f25e07d0b70b6acce2e21bb8fb4eab47a2d357567143a9deb7b85",
            "duration_seconds": 14.811,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2860,
                "end_ms": 4660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4960,
                "end_ms": 7720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Report the label if safely read, time, route, symptoms and age.",
                "start_ms": 8020,
                "end_ms": 14740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/check-transfer.fil.e6bbf6632952.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6bbf66329520836619d2cfc1e1a3165c290ee551bc3d022dd845ba00fe9b936",
            "sha256": "d0a8af6bdc25ab873464220bc819a555dbe47a011d7c70c1c7a0c8f8581a837c",
            "duration_seconds": 18.129,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3340,
                "end_ms": 5380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5680,
                "end_ms": 9240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iulat ang label kung ligtas mabasa, oras, paraan, sintomas at edad.",
                "start_ms": 9540,
                "end_ms": 18060
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/example.en.c0305fcc025a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c0305fcc025abc3cda30ea94e87e1508f7b709e65ac3ae8ed1757a51d738218a",
            "sha256": "1e171bf98629a6ee1cf1bb0898fc54a327a38a3d7f6fc8d15397936448a7f794",
            "duration_seconds": 39.523,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea moves the family away from the sharp smell and calls the verified poison-advice contact.",
                "start_ms": 2300,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She does not reach into the smell for the container.",
                "start_ms": 9440,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She gives what she can safely know: the label if it can be read without exposure, the estimated time, exposure route, symptoms and the child's age.",
                "start_ms": 13300,
                "end_ms": 25740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "When a relative wants to make the child vomit, she says no and follows the adviser's instructions.",
                "start_ms": 26040,
                "end_ms": 33040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea stays clear of the smell, calls and reports only what she can safely know.",
                "start_ms": 33340,
                "end_ms": 39460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/poisoning-response/example.fil.758237f91d0e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "758237f91d0e6989d82a3ebadfb68e5c5573f90f1b35fde458ec684beeb0323d",
            "sha256": "a1b59dbeaccc305d7e31eea2f5f45671e3bfebb8f615d52ca24275bd31544327",
            "duration_seconds": 42.031,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Inilalayo ni Lea ang pamilya sa matapang na amoy at tinatawagan ang kumpirmadong poison adviser.",
                "start_ms": 2140,
                "end_ms": 9820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya kinukuha ang lalagyan sa loob ng amoy.",
                "start_ms": 10120,
                "end_ms": 14240
              },
              {
                "zone": "body",
