                "index": 0,
                "text": "Pause and notice the setting.",
                "start_ms": 2220,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Introduce yourself and the purpose.",
                "start_ms": 5320,
                "end_ms": 7960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask permission to talk.",
                "start_ms": 8260,
                "end_ms": 10500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Say, “What would you like to clarify about the visit?”",
                "start_ms": 10800,
                "end_ms": 14400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Listen before explaining.",
                "start_ms": 14700,
                "end_ms": 17380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "If the time or place is unsuitable, offer another opportunity.",
                "start_ms": 17680,
                "end_ms": 22640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Write the purpose, opening question, permission request and support contact for Rosa’s situation.",
                "start_ms": 22940,
                "end_ms": 31740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/action.fil.b4bccc0828be.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b4bccc0828bed5ea5cfe50c4125830dbb017817998645ad5d54ee346aa32457e",
            "sha256": "11b1822177b3b2f71d3af63c229481c3eb82aa30f5c41c6f6496127041862d31",
            "duration_seconds": 36.493,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huminto muna at pansinin ang lugar.",
                "start_ms": 2420,
                "end_ms": 5900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipakilala ang sarili at layunin.",
                "start_ms": 6200,
                "end_ms": 9120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itanong kung puwedeng makipag-usap.",
                "start_ms": 9420,
                "end_ms": 12260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sabihin: “Ano po ang gusto ninyong linawin tungkol sa pagbisita?”",
                "start_ms": 12560,
                "end_ms": 17360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pakinggan ang sagot bago magpaliwanag.",
                "start_ms": 17660,
                "end_ms": 20940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung hindi angkop ang oras o lugar, mag-alok ng ibang pagkakataon.",
                "start_ms": 21240,
                "end_ms": 26520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Isulat ang layunin, unang tanong, pahintulot na hihingin at contact para sa tulong sa sitwasyon ni Rosa.",
                "start_ms": 26820,
                "end_ms": 36420
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/check-start.en.4dccc4e3c172.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4dccc4e3c172a67b4eb13fdce6900b62bd75c1647558d7af2a639b0e8b1ac7ab",
            "sha256": "1f62cd5956dd81ae0be590e5a62d8a8ff616f8cfa7c296774f3926260237901c",
            "duration_seconds": 13.375,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2340,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read why each choice helps or does not help.",
                "start_ms": 4720,
                "end_ms": 9000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "The open question gives Rosa room to explain.",
                "start_ms": 9300,
                "end_ms": 13300
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/check-start.fil.f2adbf1af36e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f2adbf1af36e9d6729218b4bc554db8120601abde154e04b02871328e0b8fc4b",
            "sha256": "fc790285e729c2bdb65c2ff3979d96d59b2b785f9b9c93024016bf9323c70a26",
            "duration_seconds": 16.927,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2660,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag para sa bawat pagpipilian.",
                "start_ms": 5320,
                "end_ms": 10800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Bukas ang tanong at nagbibigay ng pagkakataong magpaliwanag si Rosa.",
                "start_ms": 11100,
                "end_ms": 16860
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/check-transfer.en.135ea4efd886.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "135ea4efd886fb42abc28041d7d84d81f9187a6c3cf3300ea7091937264bfa59",
            "sha256": "797a63d3aad15f5cb0fd14fc55e59f3f597483698b0f3963ce02212019ab05a0",
            "duration_seconds": 12.173,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2500,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose the appropriate next step.",
                "start_ms": 4840,
                "end_ms": 7520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This respects the agreement and gives a clear next step.",
                "start_ms": 7820,
                "end_ms": 12100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/check-transfer.fil.2c6b514428c7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2c6b514428c768317de070aa9ada945b686786396f2563a8be488792e3bed415",
            "sha256": "3ab194df977e925f8fd1648e0e9c4d0aab392b5bb964243c18dee347c409024f",
            "duration_seconds": 15.047,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang nangyari sa kuwento.",
                "start_ms": 2500,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5320,
                "end_ms": 8680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sinusunod nito ang napagkasunduan at may malinaw na susunod na hakbang.",
                "start_ms": 8980,
                "end_ms": 14980
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/example.en.d7533e5bf85f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d7533e5bf85fa304e5c318bb27cbede155177930206c6c93120155c87f3ccc7e",
            "sha256": "22d3aa55c15dd56ed3a4174484473405cee128a770594189bef9ea15197b84ab",
            "duration_seconds": 32.888,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Amina: “May I explain the visit?”",
                "start_ms": 1980,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Rosa: “The neighbors can hear.”",
                "start_ms": 5400,
                "end_ms": 8080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Amina: “Would you prefer another time?”",
                "start_ms": 8380,
                "end_ms": 11180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Rosa chooses the afternoon.",
                "start_ms": 11480,
                "end_ms": 14040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Amina does not write “uncooperative.”",
                "start_ms": 14340,
                "end_ms": 18100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "What she has learned is a concern about privacy.",
                "start_ms": 18400,
                "end_ms": 22400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Shows four plan elements: purpose, permission, an open question and a support route, without guessing Rosa’s motive.",
                "start_ms": 22700,
                "end_ms": 32820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/example.fil.ea7f15fdad90.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea7f15fdad90b4e9b5f5216a7a446acc57018b700f86a3cd6853ee7af48f1b7a",
            "sha256": "dac968c6fbd4152d54160f4d27ef322e563645adb59ce320bfbb5a69fa46d507",
            "duration_seconds": 40.803,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawa ng usapan",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Amina: “Puwede po bang ipaliwanag ko ang pagbisita?”",
                "start_ms": 2500,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Rosa: “Naririnig ng kapitbahay.”",
                "start_ms": 6960,
                "end_ms": 10120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Amina: “Mas gusto po ba ninyong mag-usap sa ibang oras?”",
                "start_ms": 10420,
                "end_ms": 15020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pinili ni Rosa ang hapon.",
                "start_ms": 15320,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi isinulat ni Amina na “ayaw makipagtulungan.”",
                "start_ms": 18180,
                "end_ms": 22740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang nalaman niya ay alalahanin sa pribadong usapan.",
                "start_ms": 23040,
                "end_ms": 27440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipinapakita ang apat na bahagi ng plano: layunin, pahintulot, bukas na tanong at paraan ng paghingi ng tulong. Walang hula sa motibo ni Rosa.",
                "start_ms": 27740,
                "end_ms": 40740
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/next-step.en.4ebd16d9ae8c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4ebd16d9ae8cb77f1d348c3258d50b650f5fa3327ccfcc5b012bf576cba97f4b",
            "sha256": "81854efd36115f8b4d8df9cc9b9c886f0adae0d45c393c61efd53845b0fae52f",
            "duration_seconds": 29.414,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Amina and Rosa agree to talk that afternoon.",
                "start_ms": 2500,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Amina records the return time and the concern to clarify.",
                "start_ms": 6720,
                "end_ms": 11480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On Monday, bring the blank plan to the midwife.",
                "start_ms": 11780,
                "end_ms": 15860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Confirm whom to contact for support.",
                "start_ms": 16160,
                "end_ms": 19080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Word: permission — agreement to the requested conversation.",
                "start_ms": 19380,
                "end_ms": 24900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose one action and follow up on the result.",
                "start_ms": 25200,
                "end_ms": 29360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/next-step.fil.5850939fa409.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5850939fa4099a9e2d269f1c060f99a5c149a72a682e21d70025ae8032621526",
            "sha256": "4fcd5d98e464d7be35f4bdc0595d6a7c7a225979cc896bd56041f651b651344b",
            "duration_seconds": 35.318,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nagkasundo sina Amina at Rosa na mag-usap sa hapon.",
                "start_ms": 2460,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Isinulat ni Amina ang oras ng pagbalik at alalahaning kailangang linawin.",
                "start_ms": 7560,
                "end_ms": 13560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, dalhin ang blangkong plano sa midwife.",
                "start_ms": 13860,
                "end_ms": 17900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kumpirmahin ang contact na tatawagan kung kailangan ng tulong.",
                "start_ms": 18200,
                "end_ms": 22640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Salita: pahintulot — pagsang-ayon sa hinihinging pakikipag-usap.",
                "start_ms": 22940,
                "end_ms": 30060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng isang hakbang at balikan ang naging resulta.",
                "start_ms": 30360,
                "end_ms": 35240
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/scene.en.7caa23709c97.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7caa23709c97ad393103b1ce629e8efeaf289324716f9cac18b697dbce2d88d7",
            "sha256": "c8909b1bb3c8c5f94ef5ef174a6fe638ede1921bef1437fdf6cbfc869ca49b08",
            "duration_seconds": 24.059,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Amina arrives at Rosa’s home in Cotabato.",
                "start_ms": 1820,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Why do you need our names again?”",
                "start_ms": 7240,
                "end_ms": 9600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Rosa asks.",
                "start_ms": 9900,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Neighbors are outside.",
                "start_ms": 12080,
                "end_ms": 14240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Amina has a schedule, but she does not yet know Rosa’s concern.",
                "start_ms": 14540,
                "end_ms": 19540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Find out the concern before choosing a response.",
                "start_ms": 19840,
                "end_ms": 24000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/scene.fil.0491408c3926.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0491408c39265fff918a8c3f74e480628725d142bc53759469416a10f05af662",
            "sha256": "4709c0c1c7b40fd1428e1e42380a07ec997acaa8af73866bd147d57ff21c3c9f",
            "duration_seconds": 27.35,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 4440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dumating si BHW Amina sa bahay ni Rosa sa Cotabato.",
                "start_ms": 4740,
                "end_ms": 9460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Bakit pangalan na naman namin?”",
                "start_ms": 9760,
                "end_ms": 12160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "tanong ni Rosa.",
                "start_ms": 12460,
                "end_ms": 13980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Nasa labas ang mga kapitbahay.",
                "start_ms": 14280,
                "end_ms": 16840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "May iskedyul si Amina, pero hindi pa niya alam ang alalahanin ni Rosa.",
                "start_ms": 17140,
                "end_ms": 22740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alamin ang alalahanin bago pumili ng tugon.",
                "start_ms": 23040,
                "end_ms": 27280
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/scope.en.8c795016c8b2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8c795016c8b2ce681acf10826d6c73587599deff9b8668b64c3ffdcf43c706c2",
            "sha256": "4ea6fc401eb632abbbd8791c44592707273f1900e81166ae265794cfa77f090a",
            "duration_seconds": 31.896,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW can listen, explain and plan a return visit.",
                "start_ms": 2660,
                "end_ms": 8580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not force entry or promise services outside your control.",
                "start_ms": 8880,
                "end_ms": 13920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the midwife or assigned supervisor when the next step is unclear.",
                "start_ms": 14220,
                "end_ms": 19460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If there is immediate danger, prioritize getting help safely through the local emergency service.",
                "start_ms": 19760,
                "end_ms": 26360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Seek the appropriate support when a situation exceeds your role.",
                "start_ms": 26660,
                "end_ms": 31820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/prepare-a-response/scope.fil.d11f389c557e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d11f389c557e124b9df4e8ceacbb7d57a24fb99af483b194792b158108662bd3",
            "sha256": "636bde9e30908aae06dc3118b8d778c8de94bf50236cf337eda5a06c94054af1",
            "duration_seconds": 36.258,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maaaring makinig, magpaliwanag at magplano ng pagbalik ang BHW.",
                "start_ms": 3100,
                "end_ms": 10260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi niya kailangang pilitin ang pagpasok o mangako ng serbisyong hindi niya hawak.",
                "start_ms": 10560,
                "end_ms": 16520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Humingi ng gabay sa midwife o nakatalagang supervisor kapag hindi malinaw ang susunod na hakbang.",
                "start_ms": 16820,
                "end_ms": 24180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may agarang panganib, unahin ang ligtas na paghingi ng tulong sa lokal na emergency service.",
                "start_ms": 24480,
                "end_ms": 31400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong sa tamang tao kapag lampas sa saklaw.",
                "start_ms": 31700,
                "end_ms": 36180
              }
            ]
          }
        }
      }
    },
    "privacy-and-inclusion": {
      "module": "chapter2/02-quality-service",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/action.en.ff29d7c4b88d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ff29d7c4b88d15822afd31be715f20bd2ac15d411e32055a4f5df3268b6ba834",
            "sha256": "e6351c261b3d0b75803673f47623fed9d0b89e48ae4b65c8330e5fe65b71e352",
            "duration_seconds": 35.135,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not answer the public question about the condition.",
                "start_ms": 2420,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Offer a private conversation and ask what help is wanted.",
                "start_ms": 6680,
                "end_ms": 11400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "You can read the form calmly in an agreed setting.",
                "start_ms": 11700,
                "end_ms": 16060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Respect religion, culture, identity and circumstances.",
                "start_ms": 16360,
                "end_ms": 22040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Difficulty reading calls for support, not judgment.",
                "start_ms": 22340,
                "end_ms": 26740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Do not answer publicly. Offer privacy, ask what support Alex prefers and explain the next step.",
                "start_ms": 27040,
                "end_ms": 35080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/action.fil.5bb093bff386.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5bb093bff386b6644817a004ce4febfb70c37ff6de15904ab991b026d2a61573",
            "sha256": "6b5ffbff0dc3a09058784dead3e7f899e6bfcad40629a47c0e701d405c7fdfe5",
            "duration_seconds": 43.154,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag sagutin sa publiko ang tanong tungkol sa kondisyon.",
                "start_ms": 2580,
                "end_ms": 6500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mag-alok ng pribadong usapan at itanong kung anong tulong ang nais.",
                "start_ms": 6800,
                "end_ms": 12480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaaring basahin nang mahinahon ang form sa napagkasunduang lugar.",
                "start_ms": 12780,
                "end_ms": 18060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Igalang ang relihiyon, kultura, pagkakakilanlan at kalagayan sa buhay.",
                "start_ms": 18360,
                "end_ms": 26040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang hadlang sa pagbasa ay dahilan upang tumulong, hindi upang manghusga.",
                "start_ms": 26340,
                "end_ms": 32220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Huwag sagutin sa publiko. Mag-alok ng pribadong usapan, itanong ang gustong tulong ni Alex at ipaliwanag ang susunod na hakbang.",
                "start_ms": 32520,
                "end_ms": 43080
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/check-start.en.58c27cf59ee9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "58c27cf59ee99861e873b5179b9da9cacf8fa3a8829969d410a6043e85b5b62c",
            "sha256": "3724343e3e81f1be6ab75c0a55377441d8950ed1200d2e02047fcea69a83a307",
            "duration_seconds": 13.087,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2500,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 4720,
                "end_ms": 8320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This addresses the concern without disclosing the condition.",
                "start_ms": 8620,
                "end_ms": 13020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/check-start.fil.5bba2a31ad22.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5bba2a31ad22b35d6c1c163f9af7ac9d224ad1db411d0067411311994a432dfe",
            "sha256": "9bbb0d6f2586bb045aabf760b3781b701db21ccb0013c4514f72db240bce992f",
            "duration_seconds": 16.248,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2540,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5120,
                "end_ms": 10080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tinutugunan nito ang alalahanin nang hindi inilalantad ang kondisyon.",
                "start_ms": 10380,
                "end_ms": 16180
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/check-transfer.en.a579c088852f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a579c088852f6ff7ace9601fc7c76e814d810a42cff7e07fa8f58b6a9bccb77d",
            "sha256": "e95bba832c99dfc6e66bd0fabbcfdee478b6487cb742f4bcd923d15a1f3cb09f",
            "duration_seconds": 12.095,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2620,
                "end_ms": 4460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4760,
                "end_ms": 7680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This respects the requested support and privacy.",
                "start_ms": 7980,
                "end_ms": 12020
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/check-transfer.fil.b0eb268a7856.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b0eb268a7856a7b0db82588f2582ecaa6452aedc755374b836663d5660075e2d",
            "sha256": "e2c296a6c79bc1c4f2859d156b7df9e0217b569a65abd8c6d452dc5ba1ba1890",
            "duration_seconds": 13.009,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2580,
                "end_ms": 4420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4720,
                "end_ms": 8040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tumutugon ito sa hiniling na tulong at pribadong usapan.",
                "start_ms": 8340,
                "end_ms": 12940
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/example.en.7bf6d979b5d5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7bf6d979b5d5de659919a935a5f535cd2e16af6fa69d17a8b1f82c700328a2cf",
            "sha256": "58a975132dcd5873d8d5a1c58de87370ad472e1992ca0e96859272d1bb2aa0b7",
            "duration_seconds": 32.131,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lorna: “Would you like to speak over there?",
                "start_ms": 2100,
                "end_ms": 5420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "What help would you prefer with the form?”",
                "start_ms": 5720,
                "end_ms": 8160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alex: “Please read it slowly.”",
                "start_ms": 8460,
                "end_ms": 11420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Lorna follows the agreement.",
                "start_ms": 11720,
                "end_ms": 14200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She does not disclose the condition to the queue.",
                "start_ms": 14500,
                "end_ms": 18020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "She asks whether Alex wants a support person before involving anyone else.",
                "start_ms": 18320,
                "end_ms": 23680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Avoids disclosing the condition, seeks agreement on setting and support, and explains without judgment.",
                "start_ms": 23980,
                "end_ms": 32060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/example.fil.34d375ebac18.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "34d375ebac186db5efd6766c071ae2b6b3883ebe046bf9c95a9de72eac3d411d",
            "sha256": "489ad3de6e30b8757017da49723766ad85aed420f38b87b118ec65a03760e5cb",
            "duration_seconds": 35.213,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lorna: “Doon po ba tayo mag-usap?",
                "start_ms": 2060,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Anong tulong ang gusto ninyo sa form?”",
                "start_ms": 5960,
                "end_ms": 8520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alex: “Pakibasa po nang dahan-dahan.”",
                "start_ms": 8820,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sinunod ni Lorna ang napagkasunduan.",
                "start_ms": 12760,
                "end_ms": 15840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi niya sinabi sa pila ang kondisyon ni Alex.",
                "start_ms": 16140,
                "end_ms": 19940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Tinanong niya kung nais nitong may kasamang tumulong, bago mag-imbita ng iba.",
                "start_ms": 20240,
                "end_ms": 25360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Hindi inilalantad ang kondisyon; humihingi ng pahintulot sa lugar at tulong; nagbibigay ng paliwanag nang walang panghuhusga.",
                "start_ms": 25660,
                "end_ms": 35140
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/next-step.en.ba9e8826c04c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ba9e8826c04c25cd8c1ab59a4a650f7c3d63b8b4be8d8937a29db5b106aadb99",
            "sha256": "ce7f7c91eae489ceb9d37d67425bb525fecb9b994e886f9b31fbf786c22587d9",
            "duration_seconds": 24.137,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Alex understands the form without personal details being disclosed to the queue.",
                "start_ms": 2620,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, practise offering private support with a blank form.",
                "start_ms": 8760,
                "end_ms": 13680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Word: equitable service — responding to different needs without judgment.",
                "start_ms": 13980,
                "end_ms": 20580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 20880,
                "end_ms": 24080
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/next-step.fil.55fd62327cbd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "55fd62327cbd8fe307af5f79e35622a3800d62fedf6fb408af1dcf323d83a1f8",
            "sha256": "62127aaaf0fe64d7a3a74fb9463622d33ae5d5a4638189dd40fe2ad133173ff5",
            "duration_seconds": 29.022,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naintindihan ni Alex ang form nang hindi isiniwalat sa pila ang personal na detalye.",
                "start_ms": 2580,
                "end_ms": 9780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, magsanay ng pribadong pag-aalok ng tulong gamit ang blangkong form.",
                "start_ms": 10080,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Salita: pantay na serbisyo — tumutugon sa magkaibang pangangailangan nang walang panghuhusga.",
                "start_ms": 17060,
                "end_ms": 24980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 25280,
                "end_ms": 28960
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/scene.en.96c16ffbe931.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "96c16ffbe931b89063ff79c72b099e7ce9227264093c1eec4c1d49b6845aef11",
            "sha256": "71067d3a5bed6ff973231f4e85e7eece9f289a687e6f43393144d338ad1225f8",
            "duration_seconds": 22.439,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the queue, Alex tells BHW Lorna that the form is difficult to read.",
                "start_ms": 1900,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Someone loudly asks about Alex’s condition.",
                "start_ms": 8120,
                "end_ms": 12040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alex does not want others to hear.",
                "start_ms": 12340,
                "end_ms": 15260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Help is needed without embarrassment.",
                "start_ms": 15560,
                "end_ms": 19040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "How can you help without disclosure?",
                "start_ms": 19340,
                "end_ms": 22380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/scene.fil.92dc0f49ce0e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "92dc0f49ce0e291261171585cdb35d7631ad3c696cfe531d71dc45bb4f198a3e",
            "sha256": "b363194973f71b8c7ec19b9ccf1660c46076d7424b4ab45d548ec918c56bf4dd",
            "duration_seconds": 24.816,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pila, sinabi ni Alex kay BHW Lorna na nahihirapan siyang basahin ang form.",
                "start_ms": 2020,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May taong nagtanong nang malakas kung ano ang kondisyon niya.",
                "start_ms": 9200,
                "end_ms": 13320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ayaw ni Alex na marinig ng iba ang sagot.",
                "start_ms": 13620,
                "end_ms": 16940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kailangan niya ng tulong nang hindi napapahiya.",
                "start_ms": 17240,
                "end_ms": 20880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Paano tutulong nang hindi inilalantad?",
                "start_ms": 21180,
                "end_ms": 24740
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/scope.en.133bce4df35c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "133bce4df35c686747ae378e564b0c32e05c443dbff526f24d833cb838d843f9",
            "sha256": "9a53e80ddc082d8dfbd6d1f07aafd5f9326ecb769dda14e445afd12bdb156c50",
            "duration_seconds": 26.854,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use the authorized process for handling and sharing information.",
                "start_ms": 2300,
                "end_ms": 7260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not promise absolute secrecy in every situation.",
                "start_ms": 7560,
                "end_ms": 12080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If unsure who needs the information, ask the supervisor.",
                "start_ms": 12380,
                "end_ms": 16980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not send a photograph of the form to a public chat.",
                "start_ms": 17280,
                "end_ms": 21560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm boundaries and requirements with the appropriate person.",
                "start_ms": 21860,
                "end_ms": 26780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/privacy-and-inclusion/scope.fil.cb4cc1f1e895.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cb4cc1f1e8954869d2a47550ea10a8a85cbbc73904a935c748ee359739a77c39",
            "sha256": "eb03ec250b1641f975a078eff206d6ad98b43203c07eaee20419b4e3e101864b",
            "duration_seconds": 27.324,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamitin ang awtorisadong paraan ng paghawak at pagbabahagi ng impormasyon.",
                "start_ms": 3380,
                "end_ms": 8980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag mangako ng ganap na lihim sa lahat ng sitwasyon.",
                "start_ms": 9280,
                "end_ms": 13120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung hindi malinaw kung sino ang dapat makaalam, itanong sa supervisor.",
                "start_ms": 13420,
                "end_ms": 18660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag magpadala ng larawan ng form sa pampublikong chat.",
                "start_ms": 18960,
                "end_ms": 22960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin ang saklaw at kailangan sa tamang tao.",
                "start_ms": 23260,
                "end_ms": 27260
              }
            ]
          }
        }
      }
    },
    "problem-action-plan": {
      "module": "07-problema",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/check.en.e323bc21c3d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e323bc21c3d0810070e74d724eb7c937307558826273ba400199ba013bbd88bf",
            "sha256": "46401dfbe1fa7ce7a02464cf4880f9ba9f531c66c872ac4ffb801a5792168b88",
            "duration_seconds": 16.614,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2220,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7320,
                "end_ms": 10720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A plan names who acts and how to tell whether the barrier decreased.",
                "start_ms": 11020,
                "end_ms": 16540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/check.fil.64217adde7f5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "64217adde7f5c8e6563f8d8dcd14271cb563c8158ae88c1b96fab3cc23c31d5e",
            "sha256": "5c8fe73beb7d0062ef5e67c5f4010c5473aee15b6267e32704fc2c05bcb223fe",
            "duration_seconds": 19.853,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3220,
                "end_ms": 8660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8960,
                "end_ms": 13360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang plano ay may taong kikilos at paraan upang malaman kung bumaba ang hadlang.",
                "start_ms": 13660,
                "end_ms": 19780
              }
            ]
          }
        },
        "compare-solutions": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/compare-solutions.en.16f691986918.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "16f691986918a28289593913477c2382eab3623d1d3a916efd110c14533bd40b",
            "sha256": "ccc10429cdfa3c7d56767d9935e56ae39d0f7901f821d3d97c4c7b7a50510163",
            "duration_seconds": 55.197,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Match the solution to the cause",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nestor, 41, and the families have confirmed scheduling and childcare barriers in the example.",
                "start_ms": 3260,
                "end_ms": 10540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "They need the midwife and other partners to plan a response.",
                "start_ms": 10840,
                "end_ms": 15440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If scheduling and childcare are the barriers, another poster may be insufficient.",
                "start_ms": 15740,
                "end_ms": 21860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Compare two proposals: a poster alone, or discussion with the health center and households about a more accessible schedule.",
                "start_ms": 22160,
                "end_ms": 31800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Which addresses the verified cause?",
                "start_ms": 32100,
                "end_ms": 35020
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Who can implement it?",
                "start_ms": 35320,
                "end_ms": 37560
              },
              {
                "zone": "body",
                "index": 6,
                "text": "What time, people and costs are involved?",
                "start_ms": 37860,
                "end_ms": 42180
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Do not promise a new service or funding until the responsible authority agrees.",
                "start_ms": 42480,
                "end_ms": 48720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Compare solutions against the cause and resources, not convenience alone.",
                "start_ms": 49020,
                "end_ms": 55140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/compare-solutions.fil.41b4f52925be.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "41b4f52925beefb0775b22475838ceb6519837bbc2945f877f35d3e3f880bcb8",
            "sha256": "63c97813cea5d49dc1ea70ec44ecf05b60667f196062513476d84eb7fb23191b",
            "duration_seconds": 62.407,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Solusyon na tumatama sa sanhi",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Nestor, 41, at ang mga pamilya ay nakumpirmang ang iskedyul at childcare ang hadlang sa mga pagbisita sa halimbawa.",
                "start_ms": 3220,
                "end_ms": 13140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan nila ang midwife at iba pang katuwang para magplano.",
                "start_ms": 13440,
                "end_ms": 18160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung schedule at childcare ang hadlang, baka hindi sapat ang dagdag na poster.",
                "start_ms": 18460,
                "end_ms": 24100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ihambing ang dalawang mungkahi: bagong poster lamang, o pakikipag-usap sa health center at mga pamilya tungkol sa mas naaabot na schedule.",
                "start_ms": 24400,
                "end_ms": 36320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alin ang tumatama sa natiyak na sanhi?",
                "start_ms": 36620,
                "end_ms": 40580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sino ang may kakayahang magpatupad?",
                "start_ms": 40880,
                "end_ms": 43560
              },
              {
                "zone": "body",
                "index": 6,
                "text": "May oras, tao at gastusin ba?",
                "start_ms": 43860,
                "end_ms": 47660
              },
              {
                "zone": "body",
                "index": 7,
                "text": "Huwag mangakong may bagong serbisyo o pondo hangga’t hindi ito napagkasunduan ng may awtoridad.",
                "start_ms": 47960,
                "end_ms": 55520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Paghambingin ang solusyon ayon sa sanhi at resources, hindi sa dali lamang ng paggawa.",
                "start_ms": 55820,
                "end_ms": 62340
              }
            ]
          }
        },
        "partners": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/partners.en.a52f0c6ce605.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a52f0c6ce6055b6f4a3f5d806f6fd4412935d59de0c6a327bfab0f6048034d49",
            "sha256": "81b70905041e1ef8b21fe6ee205e9ce9c86cb8cdf678cfdb63523a9c9de5d39e",
            "duration_seconds": 41.117,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Who should take part?",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A BHW cannot alone fix transport, water and service schedules.",
                "start_ms": 2100,
                "end_ms": 9140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On the problem map, mark actions within the BHW’s role, issues for the health team, and needs requiring barangay or other agencies.",
                "start_ms": 9440,
                "end_ms": 21160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Include affected residents, particularly those who seldom attend meetings.",
                "start_ms": 21460,
                "end_ms": 27020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Report patterns without unnecessary personal details and return to residents with the agreement.",
                "start_ms": 27320,
                "end_ms": 34320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Solutions need owners and partners; not every task belongs to the BHW.",
                "start_ms": 34620,
                "end_ms": 41060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/partners.fil.b51c592c0ca4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b51c592c0ca48db6f334fc8739619daf2191f8979562a96f05a30fa666c1feb4",
            "sha256": "1b1bf4604f5473abcbd54d8744883b9189773b863817a15d706dc0a62aaafcbf",
            "duration_seconds": 45.636,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sino ang dapat kasama?",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi kayang ayusin ng BHW mag-isa ang transportasyon, tubig at schedule ng serbisyo.",
                "start_ms": 2380,
                "end_ms": 10580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa problem map, markahan kung ano ang maaaring gawin ng BHW, alin ang kailangang iakyat sa health team, at alin ang nangangailangan ng barangay o ibang ahensya.",
                "start_ms": 10880,
                "end_ms": 22920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Anyayahan ang mga residenteng apektado, kabilang ang hindi madalas makadalo sa pulong.",
                "start_ms": 23220,
                "end_ms": 29420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iulat ang pattern na walang personal na detalyeng hindi kailangan.",
                "start_ms": 29720,
                "end_ms": 34560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Balikan sila tungkol sa napagkasunduan.",
                "start_ms": 34860,
                "end_ms": 37860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang solusyon ay may may-ari at kasosyo; hindi lahat ng gawain ay ibinabagsak sa BHW.",
                "start_ms": 38160,
                "end_ms": 45560
              }
            ]
          }
        },
        "plan": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/plan.en.316b27498749.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "316b27498749df47b2b59178054d95d2c637cfdb8a991f43fd086a96b49b343c",
            "sha256": "42649aa46a1221663a298973f18d487bd12f5bf6260e4fd55d20e07f2a55b7f2",
            "duration_seconds": 44.33,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Turn a proposal into agreed work",
                "start_ms": 0,
                "end_ms": 3520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nestor proposes a simple plan: consult affected households this week, send aggregated preferred times to the midwife, and discuss one trial schedule with the barangay health planning team.",
                "start_ms": 3820,
                "end_ms": 17660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Name an owner, resources, deadline and measure, such as attendance among those invited.",
                "start_ms": 17960,
                "end_ms": 25280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On the review date, ask whether the barrier decreased, not merely whether a meeting happened.",
                "start_ms": 25580,
                "end_ms": 32140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Confirm each partner’s contribution first.",
                "start_ms": 32440,
                "end_ms": 35880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A recommendation becomes a plan when it names an owner, resources, date and outcome measure.",
                "start_ms": 36180,
                "end_ms": 44260
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/plan.fil.53648ccc30d5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "53648ccc30d568096b712aaa1a73ff5aec5872f8e6483396149809a6c7d5bff7",
            "sha256": "d46cb3fa087d202b5328fc9caf39ff4bd37e28ba633292b717e71091235d204c",
            "duration_seconds": 52.767,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Mula mungkahi tungo sa napagkasunduang gawain",
                "start_ms": 0,
                "end_ms": 4400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumawa si Nestor ng simpleng plano: kausapin ang mga apektadong pamilya ngayong linggo; isumite sa midwife ang pinagsama-samang preferred times; talakayin ang isang pagsubok na schedule sa barangay health planning team.",
                "start_ms": 4700,
                "end_ms": 21340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tukuyin ang responsable, kailangang resources, deadline at sukatan—halimbawa, bilang ng nakadalo sa mga inimbitahan.",
                "start_ms": 21640,
                "end_ms": 32960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa review date, itanong kung nabawasan ang hadlang, hindi lang kung natapos ang meeting.",
                "start_ms": 33260,
                "end_ms": 39500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kumpirmahin muna ang ambag ng bawat kasosyo.",
                "start_ms": 39800,
                "end_ms": 43720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang rekomendasyon ay nagiging plano kapag may responsable, resources, petsa at sukatan ng resulta.",
                "start_ms": 44020,
                "end_ms": 52700
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/practice.en.12821869ae3f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "12821869ae3ff3c68090c66692438dc045cf4034ccd4efff77ceed4f9a52d6de",
            "sha256": "e95249539c9e5bd9dd52bf2ef101c88015abb8b2f4a6830c849ef97d27b24c7d",
            "duration_seconds": 42.527,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Fill in: cause; proposal; owner; resources; deadline; measure; review date.",
                "start_ms": 2700,
                "end_ms": 13900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Compare a poster and trial schedule before choosing.",
                "start_ms": 14200,
                "end_ms": 18560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "In pairs, the midwife asks about agreement and resources.",
                "start_ms": 18860,
                "end_ms": 24100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Revise and repeat the one-minute recommendation.",
                "start_ms": 24400,
                "end_ms": 28040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, answer the same questions.",
                "start_ms": 28340,
                "end_ms": 31340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Bring the proposal to the next team meeting before implementation.",
                "start_ms": 31640,
                "end_ms": 36200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A plan names who acts and how to tell whether the barrier decreased.",
                "start_ms": 36500,
                "end_ms": 42460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/practice.fil.021f4f6c795a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "021f4f6c795a852e4d6c337ab8f9a8fef5fabadbf32f22546863d1f82657ca76",
            "sha256": "ea4ddb66d7856fb7ed00a8b689701965672e738850273fa06584c97fc0ea2780",
            "duration_seconds": 48.17,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Punan: sanhi; mungkahi; owner; kailangan; deadline; sukatan; review date.",
                "start_ms": 3740,
                "end_ms": 15220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihambing ang poster at trial schedule bago pumili.",
                "start_ms": 15520,
                "end_ms": 19840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magpares: isa ang midwife na magtatanong kung may pagsang-ayon at resources.",
                "start_ms": 20140,
                "end_ms": 26660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Baguhin ang plano at ulitin ang isang minutong rekomendasyon.",
                "start_ms": 26960,
                "end_ms": 32160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, sagutin ang parehong tanong.",
                "start_ms": 32460,
                "end_ms": 35740
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Dalhin ang mungkahi sa susunod na team meeting bago ipatupad.",
                "start_ms": 36040,
                "end_ms": 41240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang plano ay may taong kikilos at paraan upang malaman kung bumaba ang hadlang.",
                "start_ms": 41540,
                "end_ms": 48100
              }
            ]
          }
        },
        "review": {
          "en": {
            "src": "/training/audio/07-problema/problem-action-plan/review.en.8b5b4247520e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8b5b4247520e0e8b64d969210c2e3697645214152816dc75880a15b438f98879",
            "sha256": "23afdf985d06f04a0b580641ea25bf264dff1e096e17928c4219b287e06c6235",
            "duration_seconds": 40.202,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "When the first plan does not work",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The schedule moved earlier but two households still missed the visit.",
                "start_ms": 3140,
                "end_ms": 8580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not label the families as failures.",
                "start_ms": 8880,
                "end_ms": 12240
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Recheck barriers: did work, costs or notice change?",
                "start_ms": 12540,
                "end_ms": 17500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Compare invitations and attendance before and after the trial.",
                "start_ms": 17800,
                "end_ms": 23600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Identify which assumption was wrong and what small change to try.",
                "start_ms": 23900,
                "end_ms": 29460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "One small trial does not prove the whole problem is solved.",
                "start_ms": 29760,
                "end_ms": 34640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Review uses results to revise assumptions and the plan.",
                "start_ms": 34940,
                "end_ms": 40140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-action-plan/review.fil.4067f850b75f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4067f850b75fad06e8eb7279e2ca516ee99021ab4c4170e6907feb074500503e",
            "sha256": "bde39dffd57f279f1db85c0ff825bb1080e074799e75cce3717b822843242189",
            "duration_seconds": 45.767,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kapag hindi gumana ang unang plano",
                "start_ms": 0,
                "end_ms": 4040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Naging mas maaga ang schedule pero dalawa pa rin ang hindi nakadalo.",
                "start_ms": 4340,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag agad sabihing bigo ang pamilya.",
                "start_ms": 9360,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kumustahin ang access barrier: may pagbabago ba sa trabaho, gastos o abiso?",
                "start_ms": 12860,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ihambing ang bilang ng inimbitahan at nakadalo bago at matapos ang pagsubok.",
                "start_ms": 20360,
                "end_ms": 27400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tukuyin kung aling palagay ang mali at anong maliit na pagbabago ang susubukan.",
                "start_ms": 27700,
                "end_ms": 33860
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang isang maliit na trial ay hindi patunay na nalutas na ang buong problema.",
                "start_ms": 34160,
                "end_ms": 39480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang review ay pagkakataong baguhin ang palagay at plano gamit ang resulta.",
                "start_ms": 39780,
                "end_ms": 45700
              }
            ]
          }
        }
      }
    },
    "problem-causes": {
      "module": "07-problema",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/07-problema/problem-causes/check.en.a54b6ad39e5c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a54b6ad39e5c0e51b5f133572cc8b8625e0c4ce59443059e546982ceff1a0176",
            "sha256": "88b8ab5edb4c466e6e86d81fe782afc879721bcfbbe2f595892b95348b63883c",
            "duration_seconds": 18.207,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2220,
                "end_ms": 7220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7520,
                "end_ms": 10880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Five Whys structures inquiry with others; evidence supports the proposed causes.",
                "start_ms": 11180,
                "end_ms": 18140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-causes/check.fil.8443986037bc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8443986037bc7ed56226ee3bade9a7b34a62a54a2d5c3c6dcb32ede770302abe",
            "sha256": "21d58fe11f47200e4d3b13c4c6b41b08826ce02a0f861cf8185190608463d82e",
            "duration_seconds": 21.473,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2980,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8160,
                "end_ms": 12920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang Five Whys ay paraan ng pagtatanong kasama ang iba; ang ebidensya ang nagpapatibay sa sanhi.",
                "start_ms": 13220,
                "end_ms": 21420
              }
            ]
          }
        },
        "manual-example": {
          "en": {
            "src": "/training/audio/07-problema/problem-causes/manual-example.en.ea8ac7b6042e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea8ac7b6042e2b3885fc7f0f7e5568e31f08d7e9e4bb30ba48668718548477a3",
            "sha256": "fcb7644146422feecb918f17b138c0a2a0871cb95fcd0aec58b6b41c5d7d4409",
            "duration_seconds": 45.349,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The manual’s diarrhoea example",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The Reference Manual uses a child’s diarrhoea death to investigate connected barriers to care and safe water.",
                "start_ms": 3060,
                "end_ms": 11540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "In the deck’s sample ranking, gaps in BHW training and teaching safe drinking-water preparation rank highly.",
                "start_ms": 11840,
                "end_ms": 20800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "This does not make training the cause of every death.",
                "start_ms": 21100,
                "end_ms": 25300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Check explanations against evidence; poverty, transport and service gaps may also contribute.",
                "start_ms": 25600,
                "end_ms": 33800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The example examines a system, not treatment instructions.",
                "start_ms": 34100,
                "end_ms": 38860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A worked example teaches a method; real priorities come from local evidence.",
                "start_ms": 39160,
                "end_ms": 45280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-causes/manual-example.fil.2e35a45173ef.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2e35a45173ef80363897a5217a287d6ecbcb7858c53009ac122390822d019491",
            "sha256": "56f6e4e9ba658eb1c22750b374cd129a500eb6faff6accbd21fdc7bf4ba3a611",
            "duration_seconds": 53.42,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang halimbawa ng batang nagtatae",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Reference Manual, ang pagkamatay ng batang nagtatae ay ginagamit upang siyasatin ang magkakaugnay na hadlang sa pangangalaga at ligtas na tubig.",
                "start_ms": 2740,
                "end_ms": 14180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa halimbawang talahanayan ng deck, nauuna ang kakulangan sa BHW training at pagtuturo ng wastong paghahanda ng inuming tubig.",
                "start_ms": 14480,
                "end_ms": 24320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi ibig sabihing training ang sanhi ng bawat pagkamatay.",
                "start_ms": 24620,
                "end_ms": 29180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tiyaking tugma ang paliwanag sa ebidensya; maaaring kasabay ang kahirapan, transportasyon at kakulangan sa serbisyo.",
                "start_ms": 29480,
                "end_ms": 38960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang halimbawa ay para sa pagsusuri ng sistema, hindi gabay sa paggamot.",
                "start_ms": 39260,
                "end_ms": 45060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang worked example ay paraan ng pagsusuri; ang totoong prayoridad ay manggagaling sa lokal na ebidensya.",
                "start_ms": 45360,
                "end_ms": 53360
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/07-problema/problem-causes/practice.en.bd1bb0a7c59b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bd1bb0a7c59b80beb8977d0b4f602bed09c161a8bb0684a4382d2fdc0bd85af9",
            "sha256": "b82d33f6fe6c591a61e77d9731eba0faa65dca1c806cf9a2ca4c5f730b49a7c1",
            "duration_seconds": 41.613,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Put the missed visit at the center of a page.",
                "start_ms": 2980,
                "end_ms": 6540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Draw childcare and transport-cost branches.",
                "start_ms": 6840,
                "end_ms": 10680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mark each cause reported, verified or to check.",
                "start_ms": 10980,
                "end_ms": 16060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Name a person to consult or record to check on each branch.",
                "start_ms": 16360,
                "end_ms": 21600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ask a partner to identify one unsupported arrow.",
                "start_ms": 21900,
                "end_ms": 26260
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Alone, circle it and write a verification question.",
                "start_ms": 26560,
                "end_ms": 30560
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Bring the resident’s perspective to the next case discussion.",
                "start_ms": 30860,
                "end_ms": 34820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Five Whys structures inquiry with others; evidence supports the proposed causes.",
                "start_ms": 35120,
                "end_ms": 41560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-causes/practice.fil.a8677a11f0fd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a8677a11f0fd9979e396e343f2e533e947ef43f770798653c0bfc5587fa9fa8e",
            "sha256": "b83bdaa79e2251449502865d28e501e5935f2b24c53da2c86a45987c04964de7",
            "duration_seconds": 49.972,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ilagay ang missed visit sa gitna ng papel.",
                "start_ms": 3260,
                "end_ms": 7420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gumawa ng dalawang sangay: childcare at pamasahe.",
                "start_ms": 7720,
                "end_ms": 13040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Markahan ang bawat sanhi ng “sinabi,” “natiyak” o “susuriin.”",
                "start_ms": 13340,
                "end_ms": 19940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Magtalaga ng taong kakausapin o rekord na susuriin sa bawat sangay.",
                "start_ms": 20240,
                "end_ms": 26160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipasuri sa kapareha ang isang arrow na walang ebidensya.",
                "start_ms": 26460,
                "end_ms": 30900
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung mag-isa, bilugan ito at isulat ang tanong sa beripikasyon.",
                "start_ms": 31200,
                "end_ms": 36600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Sa susunod na case discussion, dalhin ang pananaw ng residente.",
                "start_ms": 36900,
                "end_ms": 41940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang Five Whys ay paraan ng pagtatanong kasama ang iba; ang ebidensya ang nagpapatibay sa sanhi.",
                "start_ms": 42240,
                "end_ms": 49920
              }
            ]
          }
        },
        "rosario": {
          "en": {
            "src": "/training/audio/07-problema/problem-causes/rosario.en.c3c29ebf3c16.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c3c29ebf3c16b2a5fff6b0c0d167ae289b1b0a2a1af0acec1fdaa56cfa0413e3",
            "sha256": "c42af930d86e47ea988022291c44f96e664cb16f26cb915a1c39f7b0d094c45f",
            "duration_seconds": 48.013,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Rosario is a child",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In the Zuellig Family Foundation case study, Rosario is a child aged one year and four months.",
                "start_ms": 2660,
                "end_ms": 10180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Her death is linked to measles with diarrhoea, dehydration and malnutrition amid an unsafe environment, low income, misinformation and barriers to services.",
                "start_ms": 10480,
                "end_ms": 23520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Draw separate branches for environment, livelihood and health services.",
                "start_ms": 23820,
                "end_ms": 30580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not blame the mother alone or turn medicines mentioned in the historical story into current medical advice.",
                "start_ms": 30880,
                "end_ms": 39320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Illness has a context: water, income, information and access to services interact.",
                "start_ms": 39620,
                "end_ms": 47940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-causes/rosario.fil.755196000613.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "755196000613f859e38f8e75911a5d10e45687cbbc6732b4c91be86fc1ced710",
            "sha256": "97e2cdf3a0c36378b047548b4d8de5ec6a9bcd04ab22a2bd8bfb02531876f141",
            "duration_seconds": 52.532,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Si Rosario ay isang bata",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa case study ng Zuellig Family Foundation, si Rosario ay batang isang taon at apat na buwan.",
                "start_ms": 3180,
                "end_ms": 11060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang kanyang pagkamatay ay iniuugnay sa tigdas na may pagtatae, dehydration at malnutrition, sa konteksto ng maruming kapaligiran, kakulangan sa kita, maling impormasyon at hadlang sa serbisyo.",
                "start_ms": 11360,
                "end_ms": 26360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gumuhit ng magkakahiwalay na sanga para sa kapaligiran, kabuhayan at serbisyong pangkalusugan.",
                "start_ms": 26660,
                "end_ms": 36180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag sisihin lamang ang ina o gawing payong medikal ngayon ang mga gamot na nabanggit sa lumang kuwento.",
                "start_ms": 36480,
                "end_ms": 44120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang sakit ay may konteksto: ang tubig, kita, impormasyon at access sa serbisyo ay magkakaugnay.",
                "start_ms": 44420,
                "end_ms": 52460
              }
            ]
          }
        },
        "whys": {
          "en": {
            "src": "/training/audio/07-problema/problem-causes/whys.en.dad479f53536.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dad479f53536ca11460cb3f7b186ae22e38d2dd227c830c4141b6131e39b2b92",
            "sha256": "06a97ca188059ffd8d42d3c1a2f5c38ab1f72b2ba4facb5443c82792c4a1305f",
            "duration_seconds": 61.78,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Every why needs evidence",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nestor, 41, is investigating missed visits by three example households.",
                "start_ms": 3260,
                "end_ms": 9700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "He consults residents and health-center staff before recommending changes.",
                "start_ms": 10000,
                "end_ms": 15320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask why the visit was missed, then why the reported reason arose.",
                "start_ms": 15620,
                "end_ms": 21260
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In this fictional example, childcare was unavailable; the schedule overlapped work; only one time was communicated; household availability had not been checked.",
                "start_ms": 21560,
                "end_ms": 34320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "These are possible explanations to confirm with residents, BHWs and health-center staff.",
                "start_ms": 34620,
                "end_ms": 42100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Reaching exactly five whys is not the goal.",
                "start_ms": 42400,
                "end_ms": 46840
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Reach an actionable cause supported by evidence; follow separate branches when there is more than one cause.",
                "start_ms": 47140,
                "end_ms": 55220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Five Whys investigates evidence-based causes with others instead of repeating blame.",
                "start_ms": 55520,
                "end_ms": 61720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-causes/whys.fil.67ca5830d8ed.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "67ca5830d8ed096aedbbbfa152d5d932885ad48a6e0b70b91cb2ccba3f0471b8",
            "sha256": "f84d400eb7404cc9de81e813bcc1f56a0f38707f2ca05b9db7280e9cb77afe0e",
            "duration_seconds": 68.676,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bawat bakit, may batayan",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Nestor, 41, ay nagsisiyasat sa missed visits ng tatlong pamilya sa halimbawa.",
                "start_ms": 2820,
                "end_ms": 11220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nakikipag-usap siya sa mga residente at health-center staff bago magmungkahi.",
                "start_ms": 11520,
                "end_ms": 17440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tanungin kung bakit hindi nakarating, saka kung bakit nangyari ang ibinigay na dahilan.",
                "start_ms": 17740,
                "end_ms": 23820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa kathang-isip na halimbawa, walang magbabantay sa anak; kasabay ng pagpasok sa trabaho ang schedule; iisang oras lang ang naipabatid; hindi nasuri ang kakayahang dumalo ng pamilya.",
                "start_ms": 24120,
                "end_ms": 39280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Mga posibleng paliwanag ito na dapat kumpirmahin kasama ang residente, BHW at health-center staff.",
                "start_ms": 39580,
                "end_ms": 48100
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Hindi paligsahan ang pag-abot sa eksaktong limang bakit.",
                "start_ms": 48400,
                "end_ms": 53240
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Huminto sa isang nasusuring sanhi; kung may dalawang dahilan, sundan ang dalawang sanga.",
                "start_ms": 53540,
                "end_ms": 59980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang Five Whys ay paghanap ng nasusuring sanhi kasama ang iba, hindi paulit-ulit na paninisi.",
                "start_ms": 60280,
                "end_ms": 68600
              }
            ]
          }
        }
      }
    },
    "problem-define": {
      "module": "07-problema",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/07-problema/problem-define/check.en.2e5416d246e0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2e5416d246e02aea5cb2a31be0a9f990ad2a9c2c490745ec06268bbeaad5e51d",
            "sha256": "9d2ce00b171904d9b119bbd17fe7136ce2d1179058b29c3488a8f05bba79d9ac",
            "duration_seconds": 16.771,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2380,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7600,
                "end_ms": 11080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Describe the event and evidence before choosing a cause or solution.",
                "start_ms": 11380,
                "end_ms": 16700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-define/check.fil.62d4c3c6b989.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "62d4c3c6b989f6effaed971040d79a587239f73869bcaa88d66c3d3e90b2c533",
            "sha256": "d4fa8fb27ee04f030dcc1f21777565b873fda8938bdb552b46d8f505f68af037",
            "duration_seconds": 20.402,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2980,
                "end_ms": 8180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8480,
                "end_ms": 13320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ilarawan muna ang pangyayari at ebidensya bago pumili ng dahilan o solusyon.",
                "start_ms": 13620,
                "end_ms": 20340
              }
            ]
          }
        },
        "missed-visits": {
          "en": {
            "src": "/training/audio/07-problema/problem-define/missed-visits.en.9d174900a8f1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9d174900a8f1033b2f09584cb28125aede7ffde290280382cb7a8a32f2c423d3",
            "sha256": "42b73d55d151b5dbd56eec07f62e2ec30ee37f0d7a092b54547726b2b077398f",
            "duration_seconds": 41.561,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Three visits, the same barrier",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Nestor, 41, revisits three households that missed an agreed health-center visit.",
                "start_ms": 3580,
                "end_ms": 11220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Instead of labeling them “uncooperative,” he records dates, missed visits and the residents’ stated reasons.",
                "start_ms": 11520,
                "end_ms": 19680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "These three households are a training example, not data from your barangay.",
                "start_ms": 19980,
                "end_ms": 25660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "The problem is inability to reach a service on the agreed day; its causes still need investigation before choosing a solution.",
                "start_ms": 25960,
                "end_ms": 35160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Define the problem using events and evidence rather than judgments about people.",
                "start_ms": 35460,
                "end_ms": 41500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-define/missed-visits.fil.fb16a7e00ba7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fb16a7e00ba79f60f134a1e0392e45b4c89d31ab6b89c43118effd2a1d0d1a4a",
            "sha256": "fd86e3e562282ac801eb47964b99dec39eec3a5eaf05697ca173f6150936ed70",
            "duration_seconds": 48.039,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tatlong balik, parehong hadlang",
                "start_ms": 0,
                "end_ms": 3520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si BHW Nestor, 41 anyos, ay bumalik sa tatlong kabahayang hindi nakadalo sa napagkasunduang health-center visit.",
                "start_ms": 3820,
                "end_ms": 13740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa halip na isulat na “pasaway,” inilista niya ang petsa, bilang ng hindi nakadalo at mga dahilang mismong sinabi ng residente.",
                "start_ms": 14040,
                "end_ms": 24840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang tatlong kabahayan ay halimbawa sa pagsasanay, hindi datos ng inyong barangay.",
                "start_ms": 25140,
                "end_ms": 32100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang problema ay “hindi makarating sa serbisyo sa takdang araw”; kailangan pang siyasatin ang dahilan bago pumili ng solusyon.",
                "start_ms": 32400,
                "end_ms": 41480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tukuyin ang problema gamit ang pangyayari at ebidensya, hindi husga sa tao.",
                "start_ms": 41780,
                "end_ms": 47980
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/07-problema/problem-define/practice.en.bc26f38603b4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "bc26f38603b477b40aea8ec1e08cdd46b6a35233da6390bf107fe0861f24f63e",
            "sha256": "2bdc4c7519da5712d3349cf1fdc05cf28f1953fa3a4ae4a285a2322dc836cb94",
            "duration_seconds": 39.576,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Write: “Three households in the example missed agreed visits; they report barriers to attending.",
                "start_ms": 2860,
                "end_ms": 11180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Dates and each barrier still need clarification.”",
                "start_ms": 11480,
                "end_ms": 15680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Compare with “The families lack discipline.”",
                "start_ms": 15980,
                "end_ms": 19660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In pairs, underline the event, source and gap.",
                "start_ms": 19960,
                "end_ms": 24720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, use the same checklist.",
                "start_ms": 25020,
                "end_ms": 27980
              },
              {
                "zone": "body",
                "index": 5,
                "text": "In your next problem report, seek the affected residents’ perspectives too.",
                "start_ms": 28280,
                "end_ms": 33600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Describe the event and evidence before choosing a cause or solution.",
                "start_ms": 33900,
                "end_ms": 39500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-define/practice.fil.ed93637f8649.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ed93637f8649b14c3c5f49848d4dc4e1a7a62b7080ef55a94af4908384de2512",
            "sha256": "c60d8d52eeca02c547b37b38cb45c34fa7763057a6b60f880c4e9c74547c1872",
            "duration_seconds": 47.256,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isulat: “Tatlong pamilya sa halimbawa ang hindi nakapunta sa napagkasunduang araw; ayon sa kanila, may hadlang sa pagpunta.",
                "start_ms": 3180,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan pang linawin ang petsa at bawat hadlang.”",
                "start_ms": 15480,
                "end_ms": 19920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ihambing sa “Walang disiplina ang mga pamilya.”",
                "start_ms": 20220,
                "end_ms": 24380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa pares, salungguhitan ang pangyayari, pinagmulan at kulang.",
                "start_ms": 24680,
                "end_ms": 30240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, gamitin ang parehong checklist.",
                "start_ms": 30540,
                "end_ms": 34420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Sa susunod na problemang iuulat, humingi rin ng pananaw ng apektadong residente.",
                "start_ms": 34720,
                "end_ms": 40760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ilarawan muna ang pangyayari at ebidensya bago pumili ng dahilan o solusyon.",
                "start_ms": 41060,
                "end_ms": 47180
              }
            ]
          }
        },
        "worked-example": {
          "en": {
            "src": "/training/audio/07-problema/problem-define/worked-example.en.07f7911f6eb4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "07f7911f6eb4454344d13e7ed1b93e65c220a01eb8e3e7dcbfcf0a7ed7706a02",
            "sha256": "3228c9818dcbb609080bc0868fbd81cbc32233946f550730984411423b27f267",
            "duration_seconds": 30.929,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Separate the problem from a guess",
                "start_ms": 0,
                "end_ms": 3240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Three households missed visits” describes the event in the example.",
                "start_ms": 3540,
                "end_ms": 8620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“They did not want to go” guesses at motivation.",
                "start_ms": 8920,
                "end_ms": 13000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“We need a poster” proposes a solution.",
                "start_ms": 13300,
                "end_ms": 16980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Before choosing a solution, find out what each household reports and which records can clarify the situation.",
                "start_ms": 17280,
                "end_ms": 25240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Describe the event and evidence before choosing a cause or solution.",
                "start_ms": 25540,
                "end_ms": 30860
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-define/worked-example.fil.9498e7f6290e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "9498e7f6290eac23bec301de9554993ae09bb952151f97de415601bb7ae20490",
            "sha256": "9d5e79aae430e2caeae86c5dc3ff320eaf58ee7be5e73061065e608c2b83cdc2",
            "duration_seconds": 32.993,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ihiwalay ang problema sa hula",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "“Tatlong pamilya ang hindi nakapunta” ay paglalarawan ng pangyayari sa halimbawa.",
                "start_ms": 3380,
                "end_ms": 9740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "“Ayaw nilang pumunta” ay hula sa motibo.",
                "start_ms": 10040,
                "end_ms": 13640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“Kailangan ng poster” ay mungkahing solusyon.",
                "start_ms": 13940,
                "end_ms": 17380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Bago pumili ng solusyon, alamin ang sinabi ng bawat pamilya at kung anong rekord ang makatutulong sa paglilinaw.",
                "start_ms": 17680,
                "end_ms": 26240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ilarawan muna ang pangyayari at ebidensya bago pumili ng dahilan o solusyon.",
                "start_ms": 26540,
                "end_ms": 32940
              }
            ]
          }
        }
      }
    },
    "problem-prioritize": {
      "module": "07-problema",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/07-problema/problem-prioritize/check.en.eb37fa5490b3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eb37fa5490b3534dfd311b117fbb696a083b88dc17621866ea85666f432120f7",
            "sha256": "26a3002e1291b5cb1c6ffdb5b7bb6e09ee1179153ec89eecc91c5462320cc542",
            "duration_seconds": 18.129,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2260,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7000,
                "end_ms": 10320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Totals guide planning; evidence, discussion and urgent referral when needed still matter.",
                "start_ms": 10620,
                "end_ms": 18060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-prioritize/check.fil.db4c8f035952.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "db4c8f03595222ebbb59fecc798f8f8efe9e4c75175d2bad435b3809a0cd988c",
            "sha256": "38f4812d7a62d9425bf9598113ff8659e5cb9083c14243bccadbd25d8e82235d",
            "duration_seconds": 21.159,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3340,
                "end_ms": 7780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8080,
                "end_ms": 12600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang total ay gabay sa pagpaplano; kailangan pa rin ang ebidensya, pag-uusap at agarang referral kapag kailangan.",
                "start_ms": 12900,
                "end_ms": 21100
              }
            ]
          }
        },
        "criteria": {
          "en": {
            "src": "/training/audio/07-problema/problem-prioritize/criteria.en.0d89d84fd3f4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0d89d84fd3f4142785be3d1d0afa2c638934e470f7a44b5ebfdff64e3404310e",
            "sha256": "aeb4e6e5dd6e88d4923a0f61cadbac15046a88f4698616a4ea7f82d8d58f5359",
            "duration_seconds": 46.785,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Make priorities explicit",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For planning, score each problem from 1 to 5 on four criteria: how many are affected, severity of the effects, feasibility with available resources, and urgency.",
                "start_ms": 2900,
                "end_ms": 16420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A higher feasibility score means more achievable.",
                "start_ms": 16720,
                "end_ms": 20160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Add the four scores and discuss their evidence with the group.",
                "start_ms": 20460,
                "end_ms": 24980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A high total suggests a starting priority, not permission to ignore serious danger.",
                "start_ms": 25280,
                "end_ms": 31680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Refer someone needing urgent care immediately rather than waiting for a planning score.",
                "start_ms": 31980,
                "end_ms": 38500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Priorities require explicit criteria and local judgment; they do not replace immediate referral.",
                "start_ms": 38800,
                "end_ms": 46720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/07-problema/problem-prioritize/criteria.fil.85f2f4c8c63b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "85f2f4c8c63b3de7c3dd6f3bec35a2aa94545b271d98c8b5bbb852d1ee99601c",
            "sha256": "eaceacaea35b58eb8ef4a73ccc8b59940a67ba9dc222492c2fd6d62de7f1bbac",
            "duration_seconds": 53.812,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang prayoridad nang malinaw",
                "start_ms": 0,
                "end_ms": 2920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa pagpaplano, bigyan ang bawat problema ng 1–5 sa apat na batayan: laki o dami ng apektado, kabigatan ng epekto, kakayahang malutas gamit ang resources, at pagkamadalian.",
                "start_ms": 3220,
                "end_ms": 20220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mas mataas na feasibility score ang mas kayang tugunan.",
                "start_ms": 20520,
                "end_ms": 25120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pagsamahin ang apat na marka at ipaliwanag ang batayan kasama ang grupo.",
                "start_ms": 25420,
                "end_ms": 31620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang mataas na kabuuan ay panimulang prayoridad, hindi utos na balewalain ang malubhang panganib.",
                "start_ms": 31920,
                "end_ms": 38680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang nangangailangan ng agarang pangangalaga ay i-refer agad; hindi hinihintay ang planning score.",
                "start_ms": 38980,
                "end_ms": 45980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang prayoridad ay may malinaw na batayan at lokal na paghatol; hindi nito pinapalitan ang agarang referral.",
                "start_ms": 46280,
                "end_ms": 53760
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/07-problema/problem-prioritize/practice.en.fff3178825e3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fff3178825e3acf70a41b3c7a102ea5ef66d1efc3d716cec262655df53503401",
            "sha256": "79e3ff21ffc45d08e22327c6dee63a0cfc851940461d901a9ba2b9e5628c0d02",
            "duration_seconds": 35.135,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Copy the three example rows and calculate totals.",
                "start_ms": 2900,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Explain why 19 ranks first, then list evidence needed before using those scores locally.",
                "start_ms": 7320,
                "end_ms": 14480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Simulate a tie: discuss urgency and resources.",
                "start_ms": 14780,
                "end_ms": 19660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, write the explanation.",
                "start_ms": 19960,
                "end_ms": 22800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "At the next planning meeting, ask where the scores came from.",
                "start_ms": 23100,
                "end_ms": 26820
              },
              {
