            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2001586cd5eccc4af3fd12b878936c3c26b894c5fa938fb98274853a100c30cd",
            "sha256": "90cb12e5b189c8f354e25422d5245968e3526527de0db205992fb84bc622da17",
            "duration_seconds": 37.799,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Separate the resident’s words from your assumptions.",
                "start_ms": 2580,
                "end_ms": 6700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Share only necessary information with the authorized colleague.",
                "start_ms": 7000,
                "end_ms": 11720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Include the action, agreement and support still needed.",
                "start_ms": 12020,
                "end_ms": 16940
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Then ask yourself: Did I listen?",
                "start_ms": 17240,
                "end_ms": 20240
              },
              {
                "zone": "body",
                "index": 4,
                "text": "What helped?",
                "start_ms": 20540,
                "end_ms": 21820
              },
              {
                "zone": "body",
                "index": 5,
                "text": "What one thing will I change next time?",
                "start_ms": 22120,
                "end_ms": 25200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Write a three-line handover about Elena. Ask a partner to check for assumptions or unnecessary details. Identify one change for next time.",
                "start_ms": 25500,
                "end_ms": 37740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/report-and-reflect/action.fil.e47dd8d9e915.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
