                "end_ms": 6860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iulat sa awtorisadong katrabaho ang kailangang impormasyon lamang.",
                "start_ms": 7160,
                "end_ms": 12360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Isama ang ginawa, napagkasunduan at kailangan pang tulong.",
                "start_ms": 12660,
                "end_ms": 17700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Pagkatapos, itanong sa sarili: Nakinig ba ako?",
                "start_ms": 18000,
                "end_ms": 22280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ano ang nakatulong?",
                "start_ms": 22580,
                "end_ms": 24580
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ano ang isang babaguhin ko sa susunod?",
                "start_ms": 24880,
                "end_ms": 27960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sumulat ng tatlong linyang handover tungkol kay Elena. Ipasuri sa kapareha kung may hula o hindi kailangang detalye. Tukuyin ang isang pagbabago sa susunod.",
                "start_ms": 28260,
                "end_ms": 40900
              }
            ]
          }
        },
