                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Handover: “Nagtanong si Elena kung sino ang makakakita ng household form.",
                "start_ms": 2500,
                "end_ms": 9060
              },
              {
                "zone": "body",
