                "zone": "body",
                "index": 0,
                "text": "Natanggap ng midwife ang maikling handover at kukumpirmahin ang oras.",
                "start_ms": 2660,
                "end_ms": 8580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Isinulat ni Datu ang isang babaguhin sa susunod na usapan.",
                "start_ms": 8880,
                "end_ms": 13560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, ipasuri sa midwife ang blangkong handover checklist.",
                "start_ms": 13860,
                "end_ms": 19100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Gumamit ng kathang-isip na kaso sa practice.",
                "start_ms": 19400,
                "end_ms": 23280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Salita: handover — paglilipat ng mahalagang impormasyon sa susunod na tutulong.",
                "start_ms": 23580,
                "end_ms": 30500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Pumili ng isang hakbang at balikan ang naging resulta.",
                "start_ms": 30800,
                "end_ms": 35560
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/report-and-reflect/scene.en.27d15cd28120.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "27d15cd281207a66479425fb2c3736dc07fd24599d6df57882c6abe3c61b560a",
            "sha256": "60ceba83736a0229d67dc60b96789be5dad3dbab2907f94b454d23fc72e041fc",
            "duration_seconds": 22.413,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Datu listened to Elena.",
                "start_ms": 2140,
                "end_ms": 5660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Elena asked who could see her household form.",
                "start_ms": 5960,
                "end_ms": 9120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She agreed to talk again with the midwife.",
                "start_ms": 9420,
                "end_ms": 12460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Datu needs to hand over the concern without telling the whole barangay.",
                "start_ms": 12760,
                "end_ms": 18400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Find out the concern before choosing a response.",
                "start_ms": 18700,
                "end_ms": 22340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/report-and-reflect/scene.fil.b9f2448c1b97.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b9f2448c1b97c682c7d231f78ac289bcde961f0e03cddb449a42a3d96a95b300",
            "sha256": "5c0c076c22d3fdadbf2894a09a297fdd4b588c93d77216700d5b1dd177226774",
            "duration_seconds": 25.809,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Nakinig si BHW Datu kay Elena.",
                "start_ms": 1820,
                "end_ms": 5700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nagtanong si Elena kung sino ang makakakita ng kanyang household form.",
                "start_ms": 6000,
                "end_ms": 11080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pumayag siyang mag-usap muli kasama ang midwife.",
                "start_ms": 11380,
                "end_ms": 14980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kailangang ibahagi ni Datu ang usapan nang hindi ikinukuwento sa buong barangay.",
                "start_ms": 15280,
                "end_ms": 21280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Alamin ang alalahanin bago pumili ng tugon.",
                "start_ms": 21580,
                "end_ms": 25740
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/01-difficult-situations/report-and-reflect/scope.en.4f7cbe6fe0e9.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4f7cbe6fe0e97065814d5a289a0cd3bab982cfd7249c5d8ff29f5eed70254392",
            "sha256": "d9d9ab76aab34acd07998b97204c2d093ff133cad4ca4be4681b346d93188a02",
            "duration_seconds": 29.858,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use the authorized reporting channel in your locality.",
                "start_ms": 2700,
                "end_ms": 6860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not put personal stories in a public chat.",
                "start_ms": 7160,
                "end_ms": 10960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the midwife or supervisor if you are unsure which details are needed.",
                "start_ms": 11260,
                "end_ms": 16660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "If there is immediate danger, prioritize the emergency contact, then complete the necessary report.",
                "start_ms": 16960,
                "end_ms": 24440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Seek the appropriate support when a situation exceeds your role.",
                "start_ms": 24740,
                "end_ms": 29780
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/01-difficult-situations/report-and-reflect/scope.fil.243597d03ec0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "243597d03ec07ef4fdc36f066cb71a36c65e2064274b3972ab5075856482bfff",
            "sha256": "0ab7a5955f59ab142ad6d24dd70a9b0a12b011c48c674cec727acfaf99178905",
            "duration_seconds": 31.478,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamitin ang awtorisadong paraan ng pag-uulat sa inyong lugar.",
                "start_ms": 2900,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag ilagay ang personal na kuwento sa pampublikong chat.",
                "start_ms": 8160,
                "end_ms": 12400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Humingi ng gabay sa midwife o supervisor kung hindi tiyak kung anong detalye ang kailangan.",
                "start_ms": 12700,
                "end_ms": 19020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may agarang panganib, unahin ang emergency contact at saka kumpletuhin ang kinakailangang ulat.",
                "start_ms": 19320,
                "end_ms": 26920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong sa tamang tao kapag lampas sa saklaw.",
                "start_ms": 27220,
                "end_ms": 31420
              }
            ]
          }
        }
      }
    },
    "resources-audit": {
      "module": "09-sustainable-practices",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/check.en.e7c6058c2cc6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e7c6058c2cc642ab8fa01cdec698a39d5e29b16350b2a6e9c2c2c06b84ad265c",
            "sha256": "40893bbeb9bbdf8a4d22e8fa943577cbac9f8d0c1d8e98ad363a9ff3816cd572",
            "duration_seconds": 18.756,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2100,
                "end_ms": 6900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7200,
                "end_ms": 10480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start with observed waste and a reliable routine, not an assumption that the budget is insufficient.",
                "start_ms": 10780,
                "end_ms": 18700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/check.fil.decd12214ed3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "decd12214ed3938bf0a6ecce29c94473e1e702dd0016e63b7917fd40c7d24fe7",
            "sha256": "fe311ad86affbe92f3cd191d9f78d1f20403df0ac144829aa3e4685dbbfe8c6c",
            "duration_seconds": 21.577,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3380,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8800,
                "end_ms": 13320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magsimula sa nakitang pag-aaksaya at maayos na routine, hindi sa hula na kulang ang budget.",
                "start_ms": 13620,
                "end_ms": 21500
              }
            ]
          }
        },
        "elena": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/elena.en.189c66bf6365.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "189c66bf6365416cbd3660c2e3b45031f8da774c2349f51d7abdf4d3d5b8789d",
            "sha256": "3df78bffc016407129165f137e7a633099597a4858e9c7612350b4fed52cf7e3",
            "duration_seconds": 41.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Supplies run out before the week ends",
                "start_ms": 0,
                "end_ms": 2960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Elena, 38, is preparing health teaching at the BHS.",
                "start_ms": 3260,
                "end_ms": 9020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A tap leaks, incorrect handouts are repeatedly printed, and missing supplies are bought again.",
                "start_ms": 9320,
                "end_ms": 16520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She does not immediately conclude that the budget is too small.",
                "start_ms": 16820,
                "end_ms": 21620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She records where water, paper, electricity and time are being wasted.",
                "start_ms": 21920,
                "end_ms": 28560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Effective workplace practice delivers needed services while reducing wasted resources.",
                "start_ms": 28860,
                "end_ms": 36220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Identify wasted resources before choosing a saving measure.",
                "start_ms": 36520,
                "end_ms": 41200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/elena.fil.3908dbcca07e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3908dbcca07e3dc76f382102485312b5f2f006862cb9001c59b24767347d1e67",
            "sha256": "3ef95118507df594195fc282c695707c1a6737df12e2c04e29ab83d608684e10",
            "duration_seconds": 46.263,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ubos ang supplies bago matapos ang linggo",
                "start_ms": 0,
                "end_ms": 3280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si BHW Elena, 38 anyos, ay naghahanda ng health teaching sa BHS.",
                "start_ms": 3580,
                "end_ms": 11100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May tumutulong gripo, paulit-ulit na maling printout at mga gamit na hindi makita kaya bumibili ulit.",
                "start_ms": 11400,
                "end_ms": 19920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi agad “kulang ang budget” ang konklusyon niya.",
                "start_ms": 20220,
                "end_ms": 24180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itinala niya kung saan nauubos ang tubig, papel, kuryente at oras.",
                "start_ms": 24480,
                "end_ms": 31320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang mabisang gawi ay naghahatid ng kinakailangang serbisyo habang binabawasan ang nasasayang na resources.",
                "start_ms": 31620,
                "end_ms": 40380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tukuyin muna ang nasasayang na resources bago pumili ng pagtitipid.",
                "start_ms": 40680,
                "end_ms": 46200
              }
            ]
          }
        },
        "inventory": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/inventory.en.824b11b72f9a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "824b11b72f9a70695502d8ab74b7167d0710fbd5a80e3a9845411265fcc5ad7b",
            "sha256": "7e05d6d7bcaa3db609550c2e33f5c295f0db434518d7d5d5f47c5b13bcad678e",
            "duration_seconds": 40.176,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Find it, count it, return it",
                "start_ms": 0,
                "end_ms": 4000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Assign labeled places for approved supplies.",
                "start_ms": 4300,
                "end_ms": 8060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Count stock before requesting more and check expiry under the local inventory procedure.",
                "start_ms": 8360,
                "end_ms": 14960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Separate and report expired or damaged items; do not distribute them simply to use them up.",
                "start_ms": 15260,
                "end_ms": 22540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Return reusable teaching materials to their place.",
                "start_ms": 22840,
                "end_ms": 26840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Orderly storage reduces duplicate ordering and searching time while making real shortages visible.",
                "start_ms": 27140,
                "end_ms": 34460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Orderly storage supports safe use and accurate resource requests.",
                "start_ms": 34760,
                "end_ms": 40120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/inventory.fil.3d817c04266c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3d817c04266caa5e71196cfa3f6381d42d3dcfa0bd0237baa42f2d3a445d30e9",
            "sha256": "e33b6169c9680b9fd083284eb0916c84d3fdfd544263072ccb2ba54e4ac08014",
            "duration_seconds": 46.55,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Makita, mabilang, maibalik",
                "start_ms": 0,
                "end_ms": 4560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Maglaan ng may-label na lugar para sa aprubadong supplies.",
                "start_ms": 4860,
                "end_ms": 9420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bilangin ang stock bago humingi ng dagdag at suriin ang expiry ayon sa lokal na inventory procedure.",
                "start_ms": 9720,
                "end_ms": 17080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ihiwalay at iulat ang expired o sirang gamit; huwag ipamigay para lang maubos.",
                "start_ms": 17380,
                "end_ms": 24220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ibalik sa tamang lugar ang reusable teaching materials.",
                "start_ms": 24520,
                "end_ms": 28600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang orderly storage ay nakababawas sa duplicate orders at oras ng paghahanap, habang madaling makita ang tunay na kakulangan.",
                "start_ms": 28900,
                "end_ms": 38700
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang maayos na imbakan ay tumutulong sa ligtas na paggamit at tumpak na paghingi ng resources.",
                "start_ms": 39000,
                "end_ms": 46480
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/practice.en.495ed302e28f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "495ed302e28f6a909878d7c7b04f64a99e27da66ba9f8dae3fef0fba889eba6d",
            "sha256": "44dcf98bba88d6d644fc4202a444b28b0c33724605ecd332c69e730463ae871e",
            "duration_seconds": 38.713,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Make an audit with resource, observed waste, evidence and a safe next step.",
                "start_ms": 2900,
                "end_ms": 10380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use Elena’s three examples; do not invent bills or quantities.",
                "start_ms": 10680,
                "end_ms": 15320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Show a partner how labels and stock counts prevent duplicate orders.",
                "start_ms": 15620,
                "end_ms": 20660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, check a fictional teaching kit.",
                "start_ms": 20960,
                "end_ms": 24720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "At the next duty, observe one resource and discuss findings with the supervisor.",
                "start_ms": 25020,
                "end_ms": 31140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Start with observed waste and a reliable routine, not an assumption that the budget is insufficient.",
                "start_ms": 31440,
                "end_ms": 38640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/practice.fil.8d9aee5a1ff1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "8d9aee5a1ff1feff37bdae274fbb2b083c5b1cfeb15453ff4c3b314cf67f0dc7",
            "sha256": "cc8da33267ed949b0740ed8a6047426f79aabe03960035598b06fa4c0e376135",
            "duration_seconds": 44.095,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumawa ng audit na may resource, nakitang pag-aaksaya, ebidensya at ligtas na susunod na hakbang.",
                "start_ms": 3340,
                "end_ms": 11780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gamitin ang tatlong halimbawa ni Elena; huwag mag-imbento ng bill o dami.",
                "start_ms": 12080,
                "end_ms": 18040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipakita sa kapareha kung paano ang label at stock count ay iiwas sa dobleng order.",
                "start_ms": 18340,
                "end_ms": 24740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mag-isa, sundan ang checklist gamit ang kunwaring teaching kit.",
                "start_ms": 25040,
                "end_ms": 30280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa susunod na duty, obserbahan ang isang resource at talakayin ang findings sa supervisor.",
                "start_ms": 30580,
                "end_ms": 37100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Magsimula sa nakitang pag-aaksaya at maayos na routine, hindi sa hula na kulang ang budget.",
                "start_ms": 37400,
                "end_ms": 44040
              }
            ]
          }
        },
        "seven-s": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/seven-s.en.1dea5e0c8c9d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1dea5e0c8c9d106fd2360bdb4052215a67480bc4411f51d555d9250da13393c6",
            "sha256": "0826b56b1e8a5e5eee7d4a0071e500b18d1286c2ae7ed0936ec1771d5bca6ffb",
            "duration_seconds": 42.292,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "7S as a daily routine",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use 7S to maintain order: remove unnecessary items, arrange what is needed, clean the area, standardize the method, ensure safety, practice self-discipline and sustain the routine.",
                "start_ms": 3140,
                "end_ms": 20060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "For example, give the teaching kit a label, contents checklist, cleaning schedule and a person checking it before and after use.",
                "start_ms": 20360,
                "end_ms": 31000
              },
              {
                "zone": "body",
                "index": 2,
                "text": "A single cleanup is insufficient if disorder returns the following week.",
                "start_ms": 31300,
                "end_ms": 36660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A simple routine and clear responsibility sustain order.",
                "start_ms": 36960,
                "end_ms": 42240
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-audit/seven-s.fil.3cac2a9b31f3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3cac2a9b31f3a8f6c8b5e19b1f969191581262a1ed738d20fdcc72d5855dc815",
            "sha256": "5c3bda00a33e8e9f8ab7d917f142808ffa371371fb27609374fcd76d87df8ca9",
            "duration_seconds": 50.312,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "7S bilang araw-araw na routine",
                "start_ms": 0,
                "end_ms": 3480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamitin ang 7S upang mapanatili ang kaayusan: alisin ang hindi kailangan, ayusin ang kailangan, linisin ang lugar, magtakda ng pare-parehong paraan, gawing ligtas, gawin ang tungkulin nang hindi laging inuutusan, at ipagpatuloy ang routine.",
                "start_ms": 3780,
                "end_ms": 26700
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Halimbawa, may label ang teaching kit, checklist ng laman, nakatakdang paglilinis at taong sumusuri bago at matapos gamitin.",
                "start_ms": 27000,
                "end_ms": 38440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi sapat ang isang “general cleaning” kung babalik sa dating kalat sa susunod na linggo.",
                "start_ms": 38740,
                "end_ms": 44860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang kaayusan ay pinananatili ng simpleng routine at pananagutan.",
                "start_ms": 45160,
                "end_ms": 50240
              }
            ]
          }
        }
      }
    },
    "resources-monitor": {
      "module": "09-sustainable-practices",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/check.en.92bb1fbffb81.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "92bb1fbffb81eb4332e953e1032fd1d4b5fbd4d8f78384f958aa60b6b37f5125",
            "sha256": "56efaabfeb6c70fb525b86a8b7ad4ccc42468d4ce3918830f8d78a82a598db9f",
            "duration_seconds": 17.528,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2260,
                "end_ms": 6780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7080,
                "end_ms": 10360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lower consumption is a success only when correct, safe service is still delivered.",
                "start_ms": 10660,
                "end_ms": 17460
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/check.fil.164e67f07ea5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "164e67f07ea546cb2950334d11c507b450f3b08ec551f000695e6f7d8fe63e91",
            "sha256": "0df45e028827c1df88688e67673ad0f334f9b7659b1796567b5a6b2f5546dd4a",
            "duration_seconds": 21.891,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3140,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8760,
                "end_ms": 13440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang mas mababang konsumo ay tagumpay lamang kung naibibigay pa rin ang tama at ligtas na serbisyo.",
                "start_ms": 13740,
                "end_ms": 21820
              }
            ]
          }
        },
        "communicate": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/communicate.en.c567faa481b6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c567faa481b6624835986c1e48a63790de60257f2613eefbbe2f6a09292678b6",
            "sha256": "e12d1730923eb9f67bdc01311d79aa500349da2bc7f702a508cfae482d6e7c86",
            "duration_seconds": 36.833,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Share the proposal with colleagues",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Describe waste without blame: “There are two versions in the drawer, which causes reprinting.”",
                "start_ms": 2940,
                "end_ms": 9380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Present the proposal, responsibilities and review date.",
                "start_ms": 9680,
                "end_ms": 14480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask colleagues about overlooked barriers, such as lack of internet for the updated file.",
                "start_ms": 14780,
                "end_ms": 21180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A controlled paper master may be needed.",
                "start_ms": 21480,
                "end_ms": 24680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Resourcefulness finds safe, approved alternatives rather than bypassing policy.",
                "start_ms": 24980,
                "end_ms": 31300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A change lasts when colleagues understand it and can carry it out.",
                "start_ms": 31600,
                "end_ms": 36760
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/communicate.fil.b3f70630da8f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b3f70630da8f9b36c1cadb5f53841aeb0520c981eb7a70e90fef921eecad5bcd",
            "sha256": "4d8d284ee516cc1a93b26adf7295f2064fda97ca4f5d516fd60c3ee537b53c14",
            "duration_seconds": 44.095,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ibahagi ang mungkahi sa kasama",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sabihin ang napansing aksaya nang walang paninisi: “May dalawang bersyon sa drawer kaya may nauulit na print.”",
                "start_ms": 3180,
                "end_ms": 12020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ilahad ang mungkahi, sino ang may trabaho at kailan rerepasuhin.",
                "start_ms": 12320,
                "end_ms": 17880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Tanungin ang kasama kung may hadlang na hindi nakita, tulad ng walang internet para kunin ang bagong file.",
                "start_ms": 18180,
                "end_ms": 26140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maaaring kailangan ang controlled paper master.",
                "start_ms": 26440,
                "end_ms": 30320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang resourcefulness ay paghahanap ng ligtas at aprubadong alternatibo, hindi paglabag sa policy.",
                "start_ms": 30620,
                "end_ms": 37860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Mas napapanatili ang pagbabago kapag naiintindihan at kayang gawin ng kasama.",
                "start_ms": 38160,
                "end_ms": 44040
              }
            ]
          }
        },
        "compare": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/compare.en.739adcdfe55c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "739adcdfe55c1a4c6778a7c9cd3d8d0f1bc2669f26b1c5f4c2fb983d2db0bf62",
            "sha256": "788a92ca817191d07f5631d2a49606d6b0124b81e565606bb885a67e54e9ac4d",
            "duration_seconds": 41.404,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try a simple comparison",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Fictional data: previously, 20 of 100 printed pages had to be reprinted because the version was wrong; after the checklist, 5 of 100.",
                "start_ms": 2780,
                "end_ms": 14300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Reprints decreased by 15 per 100 pages, from 20% to 5%.",
                "start_ms": 14600,
                "end_ms": 22400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Before declaring success, check whether session types were comparable and participants still received correct materials.",
                "start_ms": 22700,
                "end_ms": 31420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Patient names are unnecessary for measuring print waste.",
                "start_ms": 31720,
                "end_ms": 36040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Compare resources across similar work and check quality too.",
                "start_ms": 36340,
                "end_ms": 41340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/compare.fil.5d596be634cc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5d596be634cc9d891b723ed1c1fe99c88f7f01e177e7affde57e7aaded7aaca7",
            "sha256": "98b33f9b8107a498a35e681ed550b12bb521a37e9d760f0605d1a163db6413ba",
            "duration_seconds": 43.285,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan ang simpleng paghahambing",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kathang-isip na datos: dati, 20 sa 100 printed pages ang inuulit dahil maling bersyon; matapos ang checklist, 5 sa 100.",
                "start_ms": 3020,
                "end_ms": 14660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Bumaba ang reprints ng 15 bawat 100 pahina, mula 20% tungong 5%.",
                "start_ms": 14960,
                "end_ms": 23360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Bago sabihing matagumpay, itanong kung pareho ang uri ng sessions at kung nakatanggap pa rin ng tamang materyal ang mga kalahok.",
                "start_ms": 23660,
                "end_ms": 32820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi kailangan ng patient name para masukat ang print waste.",
                "start_ms": 33120,
                "end_ms": 37520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihambing ang resources sa magkatulad na gawain at tingnan din ang kalidad.",
                "start_ms": 37820,
                "end_ms": 43220
              }
            ]
          }
        },
        "handover": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/handover.en.122c4b0e457a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "122c4b0e457a4dbec9b133c9175114e41884171a98126666d1b95abd3088bd44",
            "sha256": "bcd92da320cdd6efedc9ae7dd926f1861d92ac936194c6f50244ff68249c612c",
            "duration_seconds": 37.721,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Keep the routine when people change",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "When Elena is absent, a colleague should still be able to use the teaching kit and checklist.",
                "start_ms": 3180,
                "end_ms": 9540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Keep a short routine at the work area, orient new colleagues and identify who receives stock-gap reports.",
                "start_ms": 9840,
                "end_ms": 18560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "During review, remove unhelpful steps and preserve necessary safeguards.",
                "start_ms": 18860,
                "end_ms": 25020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A sustainable system does not depend on one diligent person’s memory.",
                "start_ms": 25320,
                "end_ms": 31200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A routine that colleagues can inherit lasts longer than an individual workaround.",
                "start_ms": 31500,
                "end_ms": 37660
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/handover.fil.14d0629b7063.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "14d0629b7063e6a0b3dbc04f204eecf474258977da20925cc485328fcebb84e8",
            "sha256": "9a2ddc50249c4384d22fb00236632b9f505197fd196bba774add50d5c4ec8e5d",
            "duration_seconds": 41.117,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Panatilihin kahit magpalit ng tao",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Kapag wala si Elena, dapat magamit pa rin ng kapalit ang teaching kit at checklist.",
                "start_ms": 3740,
                "end_ms": 10060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ilagay ang maikling routine sa lugar ng trabaho, ituro sa bagong kasama at tukuyin kung kanino iuulat ang stock gap.",
                "start_ms": 10360,
                "end_ms": 19600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa review, alisin ang hakbang na walang silbi at panatilihin ang proteksyong kailangan.",
                "start_ms": 19900,
                "end_ms": 26860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang sustainable na sistema ay hindi umaasa sa alaala ng iisang masipag na tao.",
                "start_ms": 27160,
                "end_ms": 34000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang routine na naipapasa sa kasama ay mas tumatagal kaysa personal na diskarte lamang.",
                "start_ms": 34300,
                "end_ms": 41060
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/practice.en.50b7316e7641.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "50b7316e76417f4914fdd0a7f84e6a1908a1e6f4db9f90ed4029e9152bf2221c",
            "sha256": "1e461b2888f8e5edeeef4d8b25d46fede0837ff518ae085ba086c2e928af6a0a",
            "duration_seconds": 42.998,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Fill a trial card: problem, change, owner, baseline, quality measure, review date.",
                "start_ms": 2740,
                "end_ms": 12100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Use 20/100 and 5/100 for a fair comparison.",
                "start_ms": 12400,
                "end_ms": 18520
              },
              {
                "zone": "body",
                "index": 2,
                "text": "In pairs, one colleague has no internet; explain the controlled paper master and handover.",
                "start_ms": 18820,
                "end_ms": 25860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, write the replacement colleague’s routine.",
                "start_ms": 26160,
                "end_ms": 30120
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ask the team to review the trial before starting and set a review date.",
                "start_ms": 30420,
                "end_ms": 35660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lower consumption is a success only when correct, safe service is still delivered.",
                "start_ms": 35960,
                "end_ms": 42920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/practice.fil.2fbdb8d50af7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2fbdb8d50af7d1b22f7164446610e5dde23d001eaf9c63bfdac51442d65da847",
            "sha256": "e7275c223bed9511fbffb71f6000b3c7d293284f252b3fffd70810689ef98518",
            "duration_seconds": 48.457,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Punan ang trial card: problema, pagbabago, owner, baseline, sukatan ng kalidad, review date.",
                "start_ms": 3620,
                "end_ms": 12940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Gamitin ang 20/100 at 5/100 para sa patas na paghahambing.",
                "start_ms": 13240,
                "end_ms": 20800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magpares: isa ang kasamahang walang internet; ipaliwanag ang controlled paper master at handover.",
                "start_ms": 21100,
                "end_ms": 29740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mag-isa, isulat ang magiging routine ng kapalit.",
                "start_ms": 30040,
                "end_ms": 34160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa team meeting, ipasuri ang trial bago simulan at magtakda ng review.",
                "start_ms": 34460,
                "end_ms": 40460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang mas mababang konsumo ay tagumpay lamang kung naibibigay pa rin ang tama at ligtas na serbisyo.",
                "start_ms": 40760,
                "end_ms": 48400
              }
            ]
          }
        },
        "trial": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/trial.en.82a2adcf3543.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "82a2adcf35430d9246d50bc9e0b3dc047ed879f4e11f0291c8569b699c6aab93",
            "sha256": "0cf64a6783dc1560af26bcddde9fcc3e6df058ddfd935c85f69a5662be274280",
            "duration_seconds": 55.693,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "One change, an owner and a measure",
                "start_ms": 0,
                "end_ms": 3720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Elena, 38, is preparing a trial to reduce incorrect printouts at the BHS.",
                "start_ms": 4020,
                "end_ms": 11300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The team needs an agreement and a measure of correct, timely materials.",
                "start_ms": 11600,
                "end_ms": 17800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Elena proposes checking the approved handout before each print run.",
                "start_ms": 18100,
                "end_ms": 23180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She prepares the checklist, the midwife confirms the version, and after two weeks they review incorrect printouts and any delayed sessions.",
                "start_ms": 23480,
                "end_ms": 33280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Record session counts to compare similar workloads.",
                "start_ms": 33580,
                "end_ms": 37460
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Share results and revise the process if quality suffers.",
                "start_ms": 37760,
                "end_ms": 42640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Agree on the change rather than issuing a new rule to everyone without discussion.",
                "start_ms": 42940,
                "end_ms": 49100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A sustainable practice has an owner, measured results and regular review.",
                "start_ms": 49400,
                "end_ms": 55640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/trial.fil.55a0f9862dae.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "55a0f9862daefab75586acad509b363df067205edc03da2cf87b6b5c34649337",
            "sha256": "9970f3c3301003c9a4a95cde86599e68c7894936d9ce66fb53ef7a001b0d351a",
            "duration_seconds": 65.855,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Isang pagbabago, may may-ari at sukatan",
                "start_ms": 0,
                "end_ms": 4680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Elena, 38, ay naghahanda ng trial upang bawasan ang maling printout sa BHS.",
                "start_ms": 4980,
                "end_ms": 12220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan ang kasunduan ng team at sukatan ng tama at napapanahong materyal.",
                "start_ms": 12520,
                "end_ms": 18680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mungkahi ni Elena: i-check ang approved handout bago bawat print run.",
                "start_ms": 18980,
                "end_ms": 25340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Siya ang maghahanda ng checklist, ang midwife ang kukumpirma sa bersyon, at susuriin nila makalipas ang dalawang linggo ang bilang ng maling printout at kung may naantalang session.",
                "start_ms": 25640,
                "end_ms": 39600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Itala ang bilang ng sessions upang makumpara ang magkatulad na trabaho.",
                "start_ms": 39900,
                "end_ms": 45500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ibahagi ang resulta sa kasama at baguhin ang proseso kung may epekto sa kalidad.",
                "start_ms": 45800,
                "end_ms": 51520
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ang pagbabago ay kailangang napagkasunduan, hindi basta bagong utos sa lahat.",
                "start_ms": 51820,
                "end_ms": 58060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang sustainable na gawi ay may responsable, sinusukat na resulta at regular na review.",
                "start_ms": 58360,
                "end_ms": 65800
              }
            ]
          }
        },
        "workload": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/workload.en.3ec0bb708cd1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3ec0bb708cd1abff6da88b2b8c3d15abda072054834eb2841af88768e2389590",
            "sha256": "b8f254822bd806de8d0661662469546e7900c6f8450397c78983c735f8c05e3d",
            "duration_seconds": 35.422,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "When workloads differ",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "One week has five teaching sessions and the next has ten.",
                "start_ms": 2580,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Total paper use can rise even when the process improves.",
                "start_ms": 7680,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Compare correct materials and reprints per session or per 100 pages, alongside complaints or delays.",
                "start_ms": 13020,
                "end_ms": 21540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not claim savings from a raw total alone.",
                "start_ms": 21840,
                "end_ms": 25880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Distinguish workload changes from process changes.",
                "start_ms": 26180,
                "end_ms": 30660
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A fair comparison accounts for the amount of work performed.",
                "start_ms": 30960,
                "end_ms": 35360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-monitor/workload.fil.c239f59dcdd5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c239f59dcdd57262ef0019d9fb4dd50bd230f52291a318c08c22deb8f4455359",
            "sha256": "099d594620f9c7ea996b3a2572e000a16ac3cfd3fe129cec7937003220ea3ad9",
            "duration_seconds": 40.438,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kapag iba-iba ang workload",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Isang linggo ay 5 ang teaching sessions; sa susunod ay 10.",
                "start_ms": 2820,
                "end_ms": 8220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Maaaring dumami ang nagamit na papel kahit mas mahusay ang proseso.",
                "start_ms": 8520,
                "end_ms": 13960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ihambing ang wastong materyal at reprints kada session o bawat 100 pahina, kasama ang anumang reklamo o delay.",
                "start_ms": 14260,
                "end_ms": 25420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag mag-claim ng savings mula sa raw total lamang.",
                "start_ms": 25720,
                "end_ms": 29560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ihiwalay ang pagbabago sa workload mula sa pagbabago sa paraan.",
                "start_ms": 29860,
                "end_ms": 34940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang patas na paghahambing ay isinasaalang-alang ang dami ng trabahong ginawa.",
                "start_ms": 35240,
                "end_ms": 40360
              }
            ]
          }
        }
      }
    },
    "resources-safe-change": {
      "module": "09-sustainable-practices",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/check.en.477719e5a12b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "477719e5a12b1baafa9d1ac44f12691443543fd85d737da850a51c4f9c40c6c3",
            "sha256": "e3777c9107cbfaf3d520727a9ba7e96dcd3d4531697927cbd9b4907b42e661e4",
            "duration_seconds": 16.875,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2140,
                "end_ms": 7060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7360,
                "end_ms": 10600
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reduce waste and rework while preserving essential protection and services.",
                "start_ms": 10900,
                "end_ms": 16820
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/check.fil.d9dcbb95f23b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d9dcbb95f23b0696397816e335ec80ab314fd9c22b1cddfa79952a98ac451f9b",
            "sha256": "676b0b5796f7cb7823fc305e957ca37eca92284703187c2ecb519333d6fd2f75",
            "duration_seconds": 20.036,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2980,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8800,
                "end_ms": 13400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makatipid sa waste at rework; panatilihin ang proteksyon at serbisyong kailangan.",
                "start_ms": 13700,
                "end_ms": 19980
              }
            ]
          }
        },
        "materials": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/materials.en.50fdbf9f294f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "50fdbf9f294f2433d42056abde2a9f4e941f4bbe86fb1f73cf32b2ec7f75cd55",
            "sha256": "32bbb4f41ecfde80ef3bad85c6645c0dba3d46c5688cc1783fc58e44e442a6b2",
            "duration_seconds": 41.691,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Reduce unnecessary use, preserve safety",
                "start_ms": 0,
                "end_ms": 4320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "For health teaching, a durable reusable visual can replace repeated disposable decorations.",
                "start_ms": 4620,
                "end_ms": 11900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Follow BHS policy on unnecessary single-use plastics and proper segregation.",
                "start_ms": 12200,
                "end_ms": 19280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Clinical single-use items are different: needles, lancets and other single-use items must not be made reusable.",
                "start_ms": 19580,
                "end_ms": 28020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "When uncertain, ask the supervisor rather than inventing cleaning or reuse methods.",
                "start_ms": 28320,
                "end_ms": 35200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Waste reduction does not authorize reuse of clinical single-use items.",
                "start_ms": 35500,
                "end_ms": 41620
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/materials.fil.c6e3d6dd94bb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c6e3d6dd94bbe068d93d2388e1ea650cdeeb98a67e80996a3bedb7cd14ef890a",
            "sha256": "866799dd90db94ad32b836aa40d976d265a69c2d3b0479d64bb7e51116bab1df",
            "duration_seconds": 49.162,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bawasan ang hindi kailangan, panatilihin ang ligtas",
                "start_ms": 0,
                "end_ms": 4760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa health teaching, maaaring gumamit ng matibay na reusable visual sa halip na paulit-ulit na disposable decoration.",
                "start_ms": 5060,
                "end_ms": 15540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sundin ang BHS policy sa hindi kailangang single-use plastics at tamang segregation.",
                "start_ms": 15840,
                "end_ms": 22880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iba ang clinical single-use items: hindi ginagawang reusable ang karayom, lancet o iba pang item na para sa isang gamit lamang.",
                "start_ms": 23180,
                "end_ms": 33180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may duda sa materyal, itanong sa supervisor; huwag mag-imbento ng paraan ng paglilinis o pagre-reuse.",
                "start_ms": 33480,
                "end_ms": 41840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagbawas ng basura ay hindi pahintulot na muling gamitin ang clinical single-use items.",
                "start_ms": 42140,
                "end_ms": 49100
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/practice.en.ea01cc32a6fe.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ea01cc32a6fea60e612c7f94734b5ed259c4a689736760dad784e3b9f3f112b7",
            "sha256": "e3f71669ae1c7194dbd55eaeb8bd6a54e0cf24090e6e753f9c69588af40f0d87",
            "duration_seconds": 40.411,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Compare “repair the leak” with “reduce handwashing.”",
                "start_ms": 2700,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "List savings, potential harm and safeguards.",
                "start_ms": 8160,
                "end_ms": 13160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose and explain to a partner.",
                "start_ms": 13460,
                "end_ms": 16620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Repeat with a reusable visual versus reusing a clinical single-use item.",
                "start_ms": 16920,
                "end_ms": 23040
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, write the rejected option and reason.",
                "start_ms": 23340,
                "end_ms": 27340
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Before trying a workplace change, confirm policy and safety checks with the supervisor.",
                "start_ms": 27640,
                "end_ms": 34160
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reduce waste and rework while preserving essential protection and services.",
                "start_ms": 34460,
                "end_ms": 40340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/practice.fil.ed94f6a69ef0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ed94f6a69ef023634e81f522a613b6f9f82aeb758f7624e76a04fbfa51a4713a",
            "sha256": "d6d18882ef86d740e5b60464e9af69278dd828c6d8a8c30760d11cea94fe107f",
            "duration_seconds": 44.878,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ihambing ang “ayusin ang leak” at “bawasan ang handwashing.”",
                "start_ms": 3620,
                "end_ms": 9540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ilista ang matitipid, posibleng pinsala at safeguard.",
                "start_ms": 9840,
                "end_ms": 14800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pumili at ipaliwanag sa kapareha.",
                "start_ms": 15100,
                "end_ms": 18660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ulitin gamit ang reusable visual laban sa clinical single-use reuse.",
                "start_ms": 18960,
                "end_ms": 25080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, isulat ang tinanggihang opsyon at dahilan.",
                "start_ms": 25380,
                "end_ms": 30140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Bago subukan ang pagbabago sa trabaho, kumpirmahin sa supervisor ang policy at safety check.",
                "start_ms": 30440,
                "end_ms": 38080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makatipid sa waste at rework; panatilihin ang proteksyon at serbisyong kailangan.",
                "start_ms": 38380,
                "end_ms": 44820
              }
            ]
          }
        },
        "utilities": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/utilities.en.81cb3a4314d6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81cb3a4314d64af644e9cd4dac99ce7714f36b59a99ac49f7e359528cfec4d52",
            "sha256": "693f53adfd1f7413f4be891454fa43cac7eb1c756a1bb09ff9e67496a60d08a2",
            "duration_seconds": 51.252,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Water and electricity with safeguards",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Elena, 38, wants to reduce waste at the BHS while preserving safe, correct services.",
                "start_ms": 3860,
                "end_ms": 11980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She needs to check each proposal with the team.",
                "start_ms": 12280,
                "end_ms": 15720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Report the leaking tap and follow up on its repair.",
                "start_ms": 16020,
                "end_ms": 20140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Switch off unnecessary lights or equipment according to facility instructions.",
                "start_ms": 20440,
                "end_ms": 26400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not turn off cold-chain equipment, required ventilation or other critical systems simply to lower a bill.",
                "start_ms": 26700,
                "end_ms": 35380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Do not reduce handwashing water to save money.",
                "start_ms": 35680,
                "end_ms": 39600
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Target leaks and unnecessary consumption while preserving safe care.",
                "start_ms": 39900,
                "end_ms": 45340
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safe conservation removes waste while preserving what care requires.",
                "start_ms": 45640,
                "end_ms": 51200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/utilities.fil.24f9e7942590.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "24f9e79425900bd9c445557580f30ecf41d19e776a19763f8c01c551ceddd693",
            "sha256": "ab7f5085611541cc5726eb1533eae236780a667e928fdda68660176f8a6faebe",
            "duration_seconds": 58.07,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Tubig at kuryente na may pag-iingat",
                "start_ms": 0,
                "end_ms": 3360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Elena, 38, ay gustong bawasan ang waste sa BHS habang naibibigay pa rin ang ligtas at tamang serbisyo.",
                "start_ms": 3660,
                "end_ms": 12540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Kailangan niyang suriin ang bawat mungkahi kasama ang team.",
                "start_ms": 12840,
                "end_ms": 17640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Iulat ang tumutulong gripo at subaybayan kung napaayos.",
                "start_ms": 17940,
                "end_ms": 22660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Patayin ang hindi kailangang ilaw o kagamitan ayon sa facility instructions.",
                "start_ms": 22960,
                "end_ms": 29000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag patayin ang cold-chain equipment, kinakailangang bentilasyon o ibang kritikal na sistema para lamang bumaba ang bill.",
                "start_ms": 29300,
                "end_ms": 38220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Huwag bawasan ang handwashing water upang makatipid.",
                "start_ms": 38520,
                "end_ms": 42640
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Ang target ay tagas at hindi kailangang konsumo, habang nananatiling ligtas ang pangangalaga.",
                "start_ms": 42940,
                "end_ms": 50180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ligtas na pagtitipid ay nag-aalis ng aksaya at pinananatili ang kailangan sa pangangalaga.",
                "start_ms": 50480,
                "end_ms": 58000
              }
            ]
          }
        },
        "worked-example": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/worked-example.en.dfb4bbfee595.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dfb4bbfee595b2370c37b667e8f4cb2ca924cec94a858f85272043eb0e59379a",
            "sha256": "5253da8382be546d6a8274c79b28d37ce07842aabd5448f7a05c0a5cdf473b84",
            "duration_seconds": 36.441,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Check why waste occurs",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "In Elena’s example, rework may come from an outdated drawer copy or an incorrect choice before printing.",
                "start_ms": 2500,
                "end_ms": 10500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Inspect sample incorrect printouts, compare them with the approved master and ask the person who printed them.",
                "start_ms": 10800,
                "end_ms": 18600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Record which explanation the evidence supports.",
                "start_ms": 18900,
                "end_ms": 22980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Confirm with the supervisor using local document-control procedures before changing the routine.",
                "start_ms": 23280,
                "end_ms": 29960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reduce waste and rework while preserving essential protection and services.",
                "start_ms": 30260,
                "end_ms": 36380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/worked-example.fil.69f853c781f6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "69f853c781f65054b21591c19bc15ff74ee591c06e9784794906aade558b838e",
            "sha256": "5072e0d5758b213ce3a2d85df2d188418a02e19022e8c7bad1919dc498205d3f",
            "duration_seconds": 38.243,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Alamin kung bakit nasasayang",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa halimbawa ni Elena, maaaring maling bersyon sa drawer o maling pagpili bago mag-print ang sanhi ng rework.",
                "start_ms": 2700,
                "end_ms": 10980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Suriin ang sample ng mga maling printout, ihambing sa aprubadong master, at tanungin ang taong nag-print.",
                "start_ms": 11280,
                "end_ms": 19160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itala kung aling sanhi ang sinusuportahan ng ebidensya.",
                "start_ms": 19460,
                "end_ms": 24100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kumpirmahin sa supervisor gamit ang lokal na document-control procedure bago baguhin ang routine.",
                "start_ms": 24400,
                "end_ms": 31320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Makatipid sa waste at rework; panatilihin ang proteksyon at serbisyong kailangan.",
                "start_ms": 31620,
                "end_ms": 38180
              }
            ]
          }
        },
        "workflow": {
          "en": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/workflow.en.2d4dd145dd8f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2d4dd145dd8fbee264f38dc5a563dcbd55de08e7fed20a0c15336de0efb48091",
            "sha256": "0f743c8c9de54ddf0b075e3d1443f886fa1a48a26305ed29cb1f7cc8ad159039",
            "duration_seconds": 38.217,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Improve the flow, not just the speed",
                "start_ms": 0,
                "end_ms": 3560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Before printing, Elena checks the date and approved version of the handout.",
                "start_ms": 3860,
                "end_ms": 9260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She assembles session materials together to avoid repeated trips to the cabinet.",
                "start_ms": 9560,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Supply delivery can be combined with a planned safe route, but urgent referral must not be delayed to save travel.",
                "start_ms": 15500,
                "end_ms": 23780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Measure quality service delivered and time saved; the number of rushed clients is not a measure of good work.",
                "start_ms": 24080,
                "end_ms": 32480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Productivity means quality service with less waste and rework.",
                "start_ms": 32780,
                "end_ms": 38140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/09-sustainable-practices/resources-safe-change/workflow.fil.6c359f264704.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6c359f2647049541abbd72a5741a1ab682165141b9bcd23c9cff6a6e3693a850",
            "sha256": "f4deebf79eb9b253eb31b3cdf56285a0f0adf49f5d23043fccc6a3d68af048de",
            "duration_seconds": 45.714,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ayusin ang daloy, hindi bilisan lang",
                "start_ms": 0,
                "end_ms": 3080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bago mag-print, suriin ni Elena ang petsa at aprubadong bersyon ng handout.",
                "start_ms": 3380,
                "end_ms": 9660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ihanda nang magkakasama ang kailangan sa session upang hindi pabalik-balik sa cabinet.",
                "start_ms": 9960,
                "end_ms": 16800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Maaaring pagsamahin ang ligtas na delivery ng supplies sa planadong ruta, ngunit hindi ipagpaliban ang agarang referral para makatipid sa biyahe.",
                "start_ms": 17100,
                "end_ms": 28540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sukatin ang naihatid na dekalidad na serbisyo at oras na natipid; hindi sukatan ng husay ang dami lang ng minadaling kliyente.",
                "start_ms": 28840,
                "end_ms": 38640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang productivity ay dekalidad na serbisyo na may mas kaunting aksaya at pag-uulit.",
                "start_ms": 38940,
                "end_ms": 45660
              }
            ]
          }
        }
      }
    },
