    "safety-controls": {
      "module": "08-osh",
      "sections": {
        "body": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/body.en.16e8bb1b2f20.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "16e8bb1b2f20ad36063dbe8b898e5103d03542ddb19441c47e3c0ab8b4add933",
            "sha256": "04f6016f073b5b67bee637f4ea1252f4fbbf6571cb40e20ba3024eedfaf098ca",
            "duration_seconds": 36.415,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Protect the body during work",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana walks far and often stands for long periods.",
                "start_ms": 2540,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Plan breaks and changes of position, use comfortable footwear and a supportive chair.",
                "start_ms": 7480,
                "end_ms": 13800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Arrange supplies to reduce repeated bending and heavy carrying; ask for lifting assistance.",
                "start_ms": 14100,
                "end_ms": 21100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Report pain to the supervisor and seek assessment when needed.",
                "start_ms": 21400,
                "end_ms": 25920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Enduring pain is not proof of dedication.",
                "start_ms": 26220,
                "end_ms": 29900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safer posture, breaks and sensible carrying are part of work preparation.",
                "start_ms": 30200,
                "end_ms": 36360
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/body.fil.56d26acc2810.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "56d26acc2810cba0b092c91f1c6d26f7a87c363f3c1a4e86fdfe39dc7a6bd0ae",
            "sha256": "9269e17f3f00a6fbad3bfb69e872f205dd554a3df429597cb75eb0707331cd9f",
            "duration_seconds": 44.356,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Alagaan ang katawan habang nagtatrabaho",
                "start_ms": 0,
                "end_ms": 3760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mahaba ang lakad ni Ana at madalas siyang nakatayo.",
                "start_ms": 4060,
                "end_ms": 7940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Magplano ng pahinga at pagbabago ng posisyon, gumamit ng komportableng sapatos at maayos na upuang may sandalan.",
                "start_ms": 8240,
                "end_ms": 16760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ayusin ang mga gamit upang hindi paulit-ulit yumuko o magdala nang mabigat; humingi ng tulong sa pagbuhat.",
                "start_ms": 17060,
                "end_ms": 25380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung may pananakit, sabihin sa supervisor at magpasuri kung kailangan.",
                "start_ms": 25680,
                "end_ms": 31360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi kailangang tiisin ang sakit upang patunayang masipag.",
                "start_ms": 31660,
                "end_ms": 36900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ligtas na posisyon, pahinga at tamang pagdadala ay bahagi ng paghahanda sa trabaho.",
                "start_ms": 37200,
                "end_ms": 44280
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/check.en.a9a6504952a7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a9a6504952a7c7830c94677167eab8bf04ad6f7ec3c5bccc5fd2b099148a0d52",
            "sha256": "a8c881d14a1756dd010aeefe838a82ea997534fc3cdb8dda0a76c4b02eb9f28d",
            "duration_seconds": 18.207,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1920
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2220,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7280,
                "end_ms": 10880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose controls for the hazard; PPE cannot replace every change needed in the work.",
                "start_ms": 11180,
                "end_ms": 18140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/check.fil.3206b2e300b2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3206b2e300b24b33482781aa88c65d6387b8949ade44e85148e0a10785a6bca8",
            "sha256": "e6a1138d1225a095ff0d9c0a9e0950de5edcb8a0824ac9cc6523cede96ff9b17",
            "duration_seconds": 21.133,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2780,
                "end_ms": 8180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8480,
                "end_ms": 12920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang kontrol ayon sa panganib; hindi kayang palitan ng PPE ang lahat ng pag-aayos sa gawain.",
                "start_ms": 13220,
                "end_ms": 21060
              }
            ]
          }
        },
        "infection": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/infection.en.d7de2fad7a0e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "d7de2fad7a0ec0e76285528d263e135b0e1523168cb83f99d136d3fc0ee3eb7e",
            "sha256": "4063eb3ee59a4d185d2cc6eca8805e736e108477fb8dc3dd3cf530c7ee040ece",
            "duration_seconds": 47.125,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose controls for the hazard",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Infections do not all spread through the same route.",
                "start_ms": 2660,
                "end_ms": 6500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "During client contact, follow hand hygiene, respiratory hygiene, ventilation and task-appropriate PPE under local protocols.",
                "start_ms": 6800,
                "end_ms": 18160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Gloves do not replace hand hygiene.",
                "start_ms": 18460,
                "end_ms": 21700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Mosquito exposure calls for bite prevention and attention to breeding sites.",
                "start_ms": 22000,
                "end_ms": 27920
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Keep the area clean and handle waste safely.",
                "start_ms": 28220,
                "end_ms": 32380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Do not mix cleaning chemicals or invent dilutions; follow labels and facility instructions.",
                "start_ms": 32680,
                "end_ms": 40200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Infection prevention combines appropriate practices, equipment and surroundings.",
                "start_ms": 40500,
                "end_ms": 47060
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/infection.fil.2c1ff0dcf0d0.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2c1ff0dcf0d0bf5bad6009afe7eb5e18bdac58dc3e9077215d5e16c97d074d9e",
            "sha256": "48d0bbb5288d292745de6fcf4bffb4c0d7bd3f30607787aa96a34d4bfc0ffad3",
            "duration_seconds": 49.607,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang kontrol ayon sa panganib",
                "start_ms": 0,
                "end_ms": 3200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Hindi pare-pareho ang ruta ng impeksyon.",
                "start_ms": 3500,
                "end_ms": 6380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa pakikisalamuha sa kliyente, sundin ang hand hygiene, respiratory hygiene, bentilasyon at task-appropriate PPE ayon sa lokal na protocol.",
                "start_ms": 6680,
                "end_ms": 18760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ang gloves ay hindi kapalit ng paglilinis ng kamay.",
                "start_ms": 19060,
                "end_ms": 23060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa lamok, mahalaga ang pag-iwas sa kagat at mga lugar na pinamumugaran.",
                "start_ms": 23360,
                "end_ms": 29080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Panatilihing malinis ang lugar at ligtas ang waste handling.",
                "start_ms": 29380,
                "end_ms": 34220
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Huwag paghaluin ang cleaning chemicals o mag-imbento ng dilution; sundin ang label at facility instructions.",
                "start_ms": 34520,
                "end_ms": 42560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang infection prevention ay kombinasyon ng tamang gawain, kagamitan at kapaligiran.",
                "start_ms": 42860,
                "end_ms": 49540
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/practice.en.b7aecde3ea7b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b7aecde3ea7be15c8843375a9cd916916280496fddae93559c0ad619eeb889fa",
            "sha256": "2aafed694f49311ef5c53f5a8088f3a0b932044195abd5131f6fea14b2214851",
            "duration_seconds": 46.629,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Make five hazard-control cards: sharps–proper container; infection–task-appropriate prevention; body pain–work adjustment and breaks; stress–agreed workload and support; accidents–safe route and avoiding threats.",
                "start_ms": 2780,
                "end_ms": 21300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Match them and explain why PPE alone is insufficient.",
                "start_ms": 21600,
                "end_ms": 26760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "In pairs, ask what must pause when protection is missing.",
                "start_ms": 27060,
                "end_ms": 31660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, explain each card aloud.",
                "start_ms": 31960,
                "end_ms": 35280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Check one control before the next duty.",
                "start_ms": 35580,
                "end_ms": 38740
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Choose controls for the hazard; PPE cannot replace every change needed in the work.",
                "start_ms": 39040,
                "end_ms": 46560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/practice.fil.11368d0d04a2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "11368d0d04a2f6a42e3c8ea79fb7071741e52f1bfbb7d37e6b96abc07f1a9ff0",
            "sha256": "5bf91741c53be2e3713c29499922ba7ef80889481503b7fdbce66abafdc8f4e3",
            "duration_seconds": 53.786,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gumawa ng limang hazard-control card: sharps–tamang lalagyan; infection–task-appropriate prevention; body pain–ayos ng gawain at pahinga; stress–agreed workload at support; aksidente–ligtas na ruta at pag-iwas sa banta.",
                "start_ms": 2940,
                "end_ms": 23580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipares at ipaliwanag kung bakit hindi sapat ang PPE lamang.",
                "start_ms": 23880,
                "end_ms": 29040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa pares, magtanong kung anong gawain ang dapat ihinto kapag kulang ang proteksyon.",
                "start_ms": 29340,
                "end_ms": 36340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mag-isa, sabihin ang paliwanag sa bawat card.",
                "start_ms": 36640,
                "end_ms": 40800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "I-check ang isang kontrol bago ang susunod na duty.",
                "start_ms": 41100,
                "end_ms": 44900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Piliin ang kontrol ayon sa panganib; hindi kayang palitan ng PPE ang lahat ng pag-aayos sa gawain.",
                "start_ms": 45200,
                "end_ms": 53720
              }
            ]
          }
        },
        "sharps": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/sharps.en.eb4658dd0980.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "eb4658dd0980e90cf92aa2585d22882b3d11ef37d0d69fb177dfa9982a2aa4f8",
            "sha256": "c4052cdc11a9cc76422ff8917855b2aa471e107b91d66743f24cff30f58c7e68",
            "duration_seconds": 41.718,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A needle is not ordinary waste",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The trained user places a used needle or lancet directly into the proper sharps container at the point of use.",
                "start_ms": 3340,
                "end_ms": 11380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not recap, bend or hand-pass it.",
                "start_ms": 11680,
                "end_ms": 16320
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Keep it out of ordinary bins and never compress a nearly full container’s contents.",
                "start_ms": 16620,
                "end_ms": 23420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Follow its fill line and local replacement procedure.",
                "start_ms": 23720,
                "end_ms": 27840
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If loose sharps are found, keep others away and obtain trained assistance; do not pick them up by hand.",
                "start_ms": 28140,
                "end_ms": 35820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Safe sharps disposal requires the right container and trained handling.",
                "start_ms": 36120,
                "end_ms": 41640
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/sharps.fil.e0d3244b4f60.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e0d3244b4f60cf3adaba196d0bc29957e34bae1af8e190f0011da82ec0632d8b",
            "sha256": "57fd77792f4e5217e3ac52d1ce0cd4ceb6d8a3a450514fc3ac69f19ba7b39a70",
            "duration_seconds": 46.341,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang karayom ay hindi ordinaryong basura",
                "start_ms": 0,
                "end_ms": 3440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang ginamit na karayom o lancet ay inilalagay agad ng sinanay na gumagamit sa tamang sharps container sa lugar ng paggamit.",
                "start_ms": 3740,
                "end_ms": 12780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag ibalik ang takip, baluktutin o ipasa nang kamay sa iba.",
                "start_ms": 13080,
                "end_ms": 18680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag ilagay sa ordinaryong basurahan o siksikin ang laman ng halos punong container.",
                "start_ms": 18980,
                "end_ms": 25540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sundin ang fill line at lokal na pagpapalit ng lalagyan.",
                "start_ms": 25840,
                "end_ms": 30280
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung may nakitang nakakalat na sharps, ilayo ang iba at humingi ng sinanay na tulong; huwag damputin nang kamay.",
                "start_ms": 30580,
                "end_ms": 38780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ligtas na pagtatapon ng sharps ay nangangailangan ng tamang lalagyan at sinanay na paghawak.",
                "start_ms": 39080,
                "end_ms": 46280
              }
            ]
          }
        },
        "workload": {
          "en": {
            "src": "/training/audio/08-osh/safety-controls/workload.en.a6a16bc5c26b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a6a16bc5c26b7abd2820b6f39db80d13b8c4b604cc5ee58befe982bccd38a435",
            "sha256": "3b983a9be015b2c8f3dd9ec67e5a8e8a05908ff3c267648647c905c550e2c471",
            "duration_seconds": 37.669,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Time and capacity have limits",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana is asked to make an extra evening visit while already exhausted.",
                "start_ms": 3420,
                "end_ms": 8980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Explain what can be done within agreed hours and what needs reassignment.",
                "start_ms": 9280,
                "end_ms": 14680
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask the midwife or coordinator for support and arrange rest.",
                "start_ms": 14980,
                "end_ms": 19820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Clear goals and boundaries for volunteer duties help prevent overload.",
                "start_ms": 20120,
                "end_ms": 25000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Reporting risk and asking for help are compatible with caring for others.",
                "start_ms": 25300,
                "end_ms": 31300
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reporting excessive workload and setting boundaries are part of workplace safety.",
                "start_ms": 31600,
                "end_ms": 37600
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-controls/workload.fil.3deda125d7cc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3deda125d7cc82895e8c3c24c92d5ef852295ce4d44759b4cb2ab06194f7dc8b",
            "sha256": "05570b801d3c204dcb23f6ca26fcb7fe66ab436145807dea40371f3044e553df",
            "duration_seconds": 45.584,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "May hangganan ang oras at kapasidad",
                "start_ms": 0,
                "end_ms": 3200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May humiling kay Ana ng dagdag na lakad sa gabi kahit pagod na siya.",
                "start_ms": 3500,
                "end_ms": 8860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipaalam kung anong trabaho ang kaya sa napagkasunduang oras at alin ang kailangang muling italaga.",
                "start_ms": 9160,
                "end_ms": 17200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Humingi ng suporta sa midwife o coordinator at magtakda ng pahinga.",
                "start_ms": 17500,
                "end_ms": 23380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang malinaw na layunin at hangganan ng boluntaryong gawain ay nakakatulong sa pag-iwas sa sobrang pagod.",
                "start_ms": 23680,
                "end_ms": 31480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi kabawasan sa malasakit ang pagsasabi ng panganib o paghingi ng tulong.",
                "start_ms": 31780,
                "end_ms": 37940
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pag-uulat ng sobrang workload at pagtakda ng hangganan ay bahagi ng kaligtasan sa trabaho.",
                "start_ms": 38240,
                "end_ms": 45520
              }
            ]
          }
        }
      }
    },
    "safety-demonstrate": {
      "module": "08-osh",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/08-osh/safety-demonstrate/check.en.0cf29e8ec51b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0cf29e8ec51b4a41b634e92b35d678a28941465407d2b5652b6f998b11548314",
            "sha256": "857d0ed72d7879046ace6f442074ca7ad13235ebcf4326e97a9013b6a8c31307",
            "duration_seconds": 18.599,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 2000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2300,
                "end_ms": 6980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7280,
                "end_ms": 10400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Demonstrate safe practice; after exposure, obtain help immediately without waiting for symptoms.",
                "start_ms": 10700,
                "end_ms": 18540
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-demonstrate/check.fil.0870dc230055.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0870dc230055d3753f8acbc68648098e371631cfd93fe921c1ab7fba78979c05",
            "sha256": "58a76881740f0f7cc3b7e57f3a869489167fc06ea30a850c3650ec1a90df00aa",
            "duration_seconds": 22.883,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 3100,
                "end_ms": 8740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 9040,
                "end_ms": 13760
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipakita ang ligtas na gawain; sa exposure, agarang tulong ang una at hindi hinihintay ang sintomas.",
                "start_ms": 14060,
                "end_ms": 22820
              }
            ]
          }
        },
        "exposure": {
          "en": {
            "src": "/training/audio/08-osh/safety-demonstrate/exposure.en.817018dd492c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "817018dd492c7300021de304464a928f45be1e7986d1dd35880a5ad997fabc11",
            "sha256": "069584f6ed7dbe3c417e1b239d9bb3eae7f6a4ee48c896d20f09d7124bb0850a",
            "duration_seconds": 53.577,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "If stuck, act immediately",
                "start_ms": 0,
                "end_ms": 3160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana, 33, is in a health-station safety practice.",
                "start_ms": 3460,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The injury in the next example is simulated; no real needles or body fluids are used.",
                "start_ms": 8680,
                "end_ms": 15280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "After a used-needle injury, wash the wound with soap and water.",
                "start_ms": 15580,
                "end_ms": 20620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Report immediately to the midwife or designated supervisor and obtain immediate medical evaluation from a qualified provider.",
                "start_ms": 20920,
                "end_ms": 30480
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Do not wait until the end of the shift or for symptoms.",
                "start_ms": 30780,
                "end_ms": 34500
              },
              {
                "zone": "body",
                "index": 5,
                "text": "A clinician decides on assessment and any post-exposure treatment.",
                "start_ms": 34800,
                "end_ms": 40320
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Document the event through the local incident process so the cause can also be addressed.",
                "start_ms": 40620,
                "end_ms": 46580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Report and obtain immediate evaluation after a needlestick; washing alone is insufficient.",
                "start_ms": 46880,
                "end_ms": 53520
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-demonstrate/exposure.fil.aef03183a129.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "aef03183a129f0e68b350ee3e93ca707f1ef66a4c1ce8beae67b4f86acdf9d41",
            "sha256": "e78ee84c94fe0a78930bb753ca77d0178aa006298354a32db023504b75508b72",
            "duration_seconds": 58.776,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kung natusok, kumilos agad",
                "start_ms": 0,
                "end_ms": 3040
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Ana, 33, ay nasa safety practice sa health station.",
                "start_ms": 3340,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang injury sa susunod na halimbawa ay simulation; walang tunay na karayom o body fluid sa pagsasanay.",
                "start_ms": 8400,
                "end_ms": 15840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung natusok ng ginamit na karayom, hugasan ang sugat gamit ang sabon at tubig.",
                "start_ms": 16140,
                "end_ms": 22660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iulat agad sa midwife o nakatalagang supervisor at kumuha kaagad ng medical evaluation sa kwalipikadong provider.",
                "start_ms": 22960,
                "end_ms": 32440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Huwag hintaying matapos ang duty o magkaroon ng sintomas.",
                "start_ms": 32740,
                "end_ms": 37140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Ang clinician ang magpapasya sa pagsusuri at anumang kailangan na post-exposure treatment.",
                "start_ms": 37440,
                "end_ms": 44400
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Itala ang pangyayari sa lokal na incident process upang matugunan din ang dahilan ng aksidente.",
                "start_ms": 44700,
                "end_ms": 52140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang needlestick injury ay iulat at ipasuri kaagad; hindi sapat ang paghuhugas lamang.",
                "start_ms": 52440,
                "end_ms": 58720
              }
            ]
          }
        },
        "near-miss": {
          "en": {
            "src": "/training/audio/08-osh/safety-demonstrate/near-miss.en.15e998c8345d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "15e998c8345d585147f75d86dee76bcee1fe4bb2b20abc245947d8273985a579",
            "sha256": "a749abc38eefc92f3ff2f1754e5786c180c942e48362bd0dfac7c90698c7f371",
            "duration_seconds": 38.557,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Report a near miss too",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana nearly slips but nobody is hurt.",
                "start_ms": 2620,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Report the hazard, time, location and control through the local process.",
                "start_ms": 6560,
                "end_ms": 12960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "After an incident, prepare available information for referral and any applicable benefits process, but paperwork must not delay urgent care.",
                "start_ms": 13260,
                "end_ms": 24300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "BHW insurance and benefits are not identical; confirm your applicable arrangements with the coordinator.",
                "start_ms": 24600,
                "end_ms": 32680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reporting a near miss creates a chance to prevent the next injury.",
                "start_ms": 32980,
                "end_ms": 38500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-demonstrate/near-miss.fil.0dbe1b2b2e31.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0dbe1b2b2e31ca45f0f1cbb66f5999fd4b47861f46a49b7f08539c946fb102cd",
            "sha256": "38f2eab322d757f3e63f99f8c3e3f3ff87a0c419bee4082eb3ca78d7b07f117a",
            "duration_seconds": 44.042,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Iulat kahit muntik lamang",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Muntik madulas si Ana pero walang nasaktan.",
                "start_ms": 3420,
                "end_ms": 6860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mahalaga pa ring iulat ang hazard, oras, lugar at ginawang kontrol sa lokal na proseso.",
                "start_ms": 7160,
                "end_ms": 14760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung may insidente, ihanda ang available na impormasyon para sa referral at naaangkop na benefits process, ngunit huwag hayaang maantala ng papel ang agarang pangangalaga.",
                "start_ms": 15060,
                "end_ms": 27220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi lahat ng BHW ay pareho ang insurance o benepisyo; kumpirmahin sa coordinator kung ano ang naaangkop sa iyo.",
                "start_ms": 27520,
                "end_ms": 36440
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pag-uulat ng muntikang insidente ay pagkakataong maiwasan ang susunod na pinsala.",
                "start_ms": 36740,
                "end_ms": 43980
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/08-osh/safety-demonstrate/practice.en.a8305424dff4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a8305424dff466cec076dd713f875f1d4ef8ee76a00f20796660d20b3135c64b",
            "sha256": "a3c05a782db12ee3b890010b0093ef496e516a794e4e739ff6c61f386d325ccc",
            "duration_seconds": 47.177,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2720
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use a dummy box to show when replacement is needed.",
                "start_ms": 3020,
                "end_ms": 7380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Follow the local demonstration checklist for hand hygiene and PPE.",
                "start_ms": 7680,
                "end_ms": 12760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Then rehearse a needlestick: state the first action, call the simulated contact and arrange immediate evaluation.",
                "start_ms": 13060,
                "end_ms": 22060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In pairs, record any delay or unsafe step and repeat.",
                "start_ms": 22360,
                "end_ms": 28160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, rehearse reporting; a trainer must observe the physical demonstration.",
                "start_ms": 28460,
                "end_ms": 34540
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Before duty, know where to obtain immediate evaluation.",
                "start_ms": 34840,
                "end_ms": 39400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Demonstrate safe practice; after exposure, obtain help immediately without waiting for symptoms.",
                "start_ms": 39700,
                "end_ms": 47100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-demonstrate/practice.fil.c79b620d9987.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c79b620d99878fabfacc609d57bf5d2e948dabc600995e50d7b475dfd1d72f3f",
            "sha256": "c374bb826dbb70fbd135568c98683f1809e9f3dbf5bfbfd70f827b5984e1b65b",
            "duration_seconds": 53.473,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2800
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ipakita gamit ang dummy box kung kailan kailangan ng replacement.",
                "start_ms": 3100,
                "end_ms": 8100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sundin ang lokal na demo checklist para sa hand hygiene at PPE.",
                "start_ms": 8400,
                "end_ms": 13280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pagkatapos, gumanap sa needlestick scenario: sabihin ang unang hakbang, tawagan ang kunwaring contact at ayusin ang agarang evaluation.",
                "start_ms": 13580,
                "end_ms": 25180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa pares, itala ang anumang delay o unsafe step at ulitin.",
                "start_ms": 25480,
                "end_ms": 30720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, i-rehearse ang reporting sequence; ang physical demo ay kailangang makita ng trainer.",
                "start_ms": 31020,
                "end_ms": 38620
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Bago ang duty, alamin kung saan pupunta para sa agarang evaluation.",
                "start_ms": 38920,
                "end_ms": 44680
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipakita ang ligtas na gawain; sa exposure, agarang tulong ang una at hindi hinihintay ang sintomas.",
                "start_ms": 44980,
                "end_ms": 53420
              }
            ]
          }
        },
        "return-demo": {
          "en": {
            "src": "/training/audio/08-osh/safety-demonstrate/return-demo.en.68ffd783c3cd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "68ffd783c3cd32a6e581b41bed8b13aa2a099c00e5518f3f7cc1619a00ae4cfb",
            "sha256": "02e28eed8f41f52f74a731feb7793a498aa3e206894f67733816c930ff2b9d10",
            "duration_seconds": 41.509,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "A safe return demonstration",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Using dummy equipment, show where the sharps container belongs and when replacement is needed.",
                "start_ms": 2980,
                "end_ms": 9940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Demonstrate hand hygiene and PPE use/removal following the trainer-approved local protocol.",
                "start_ms": 10240,
                "end_ms": 18360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Practice uses no real used needles or body fluids.",
                "start_ms": 18660,
                "end_ms": 23620
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In a short posture exercise, adjust the chair and bag; avoid painful stretching.",
                "start_ms": 23920,
                "end_ms": 29640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "The facilitator observes actions rather than relying only on verbal answers.",
                "start_ms": 29940,
                "end_ms": 35780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Competence is shown through a safe demonstration within the scope of training.",
                "start_ms": 36080,
                "end_ms": 41440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-demonstrate/return-demo.fil.6930aea81878.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6930aea81878623d818be549ca61e14870b3af625d0fdbf7997240a1e5127479",
            "sha256": "e673fb141e68d5dbcf5ac08ef0e84575765afd9aa4b52bde8d25748bdd53d429",
            "duration_seconds": 43.494,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Return demonstration na ligtas",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Gamit ang dummy equipment, ipakita kung saan dapat naroon ang sharps container at kung kailan kailangang palitan.",
                "start_ms": 3140,
                "end_ms": 10780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipakita ang hand hygiene at paggamit/pagtanggal ng PPE ayon sa trainer-approved local protocol.",
                "start_ms": 11080,
                "end_ms": 19120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Walang tunay na ginamit na karayom o body fluid sa practice.",
                "start_ms": 19420,
                "end_ms": 23580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa maikling activity tungkol sa posisyon, ayusin ang upuan at bag; huwag gumawa ng masakit na stretch.",
                "start_ms": 23880,
                "end_ms": 31400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ang facilitator ang titingin sa kilos, hindi lang sa pagsagot.",
                "start_ms": 31700,
                "end_ms": 36220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang competency ay nakikita sa ligtas na demonstrasyon sa loob ng saklaw ng pagsasanay.",
                "start_ms": 36520,
                "end_ms": 43440
              }
            ]
          }
        }
      }
    },
    "safety-identify": {
      "module": "08-osh",
      "sections": {
        "ana": {
          "en": {
            "src": "/training/audio/08-osh/safety-identify/ana.en.cc1c39f9488c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "cc1c39f9488c334d02363c5cdd971e062d881ab08898b56361ec055676c3d05c",
            "sha256": "3255c80ca88b3d7048cb1168b86732770482d2e6a9a8514206b908257ebc76a0",
            "duration_seconds": 40.986,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Before Ana starts work",
                "start_ms": 0,
                "end_ms": 2400
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana, 33, will assist at the health station before household visits.",
                "start_ms": 2700,
                "end_ms": 8500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The entrance floor is wet, the sharps box is nearly full and a hot walk lies ahead.",
                "start_ms": 8800,
                "end_ms": 16160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "“I will be careful” is not enough.",
                "start_ms": 16460,
                "end_ms": 19540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She identifies each hazard, who might be harmed and the control needed.",
                "start_ms": 19840,
                "end_ms": 25680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "She checks the local protocol and confirms the reporting contact and tasks within her training with the midwife.",
                "start_ms": 25980,
                "end_ms": 33580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Workplace safety starts by identifying hazards and local requirements before the task.",
                "start_ms": 33880,
                "end_ms": 40920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-identify/ana.fil.066cb3f024b8.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "066cb3f024b8acb306ecd4a9fda55e98d47236731d9c699cf703aae076c2021b",
            "sha256": "50d6daeaaf735c7749e4ec0b2cf6a8cea541a24ff936a924ef1cc823032d79e0",
            "duration_seconds": 48.823,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Bago simulan ni Ana ang araw",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Ana, 33 anyos, ay BHW na tutulong sa health station bago mag-household visit.",
                "start_ms": 2820,
                "end_ms": 10660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May basang sahig sa pasukan, halos puno ang sharps box at mainit ang nakaabang na lakad.",
                "start_ms": 10960,
                "end_ms": 18800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Hindi sapat ang “mag-iingat ako.”",
                "start_ms": 19100,
                "end_ms": 22060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tinutukoy niya ang hazard, sino ang maaaring masaktan, at anong kontrol ang kailangan.",
                "start_ms": 22360,
                "end_ms": 29520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Tinitingnan niya ang lokal na protocol at kinukumpirma sa midwife kung kanino mag-uulat at alin lang ang gawaing saklaw ng kanyang pagsasanay.",
                "start_ms": 29820,
                "end_ms": 40020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang kaligtasan sa trabaho ay nagsisimula sa pagtukoy ng hazard at lokal na requirements bago ang gawain.",
                "start_ms": 40320,
                "end_ms": 48760
              }
            ]
          }
        },
        "check": {
          "en": {
            "src": "/training/audio/08-osh/safety-identify/check.en.949f7b25c9be.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "949f7b25c9be4015683f96a1e04f9f7ffdd0cd2ff2d89e35814be6c3438d4f64",
            "sha256": "189854427cf0c30eda3d39c0fc32c1f3f34c09fa192f9903f7b696f947a34182",
            "duration_seconds": 18.416,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2260,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7880,
                "end_ms": 11080
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Recognizing a hazard should lead to a specific control and responsible contact.",
                "start_ms": 11380,
                "end_ms": 18340
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-identify/check.fil.5bde17eb96d1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5bde17eb96d147486830bb77522c876ca16e1b4a57018aadadf451e7c525bc45",
            "sha256": "ce684328c95f5d5fafe8fc8b64bbb2bd20dbdd0bde8c4deaa9dd1b21952719fa",
            "duration_seconds": 19.252,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2860,
                "end_ms": 8220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8520,
                "end_ms": 12920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagkilala sa panganib ay dapat humantong sa tiyak na kontrol at taong tutugon.",
                "start_ms": 13220,
                "end_ms": 19180
              }
            ]
          }
        },
        "inspect": {
          "en": {
            "src": "/training/audio/08-osh/safety-identify/inspect.en.804a9e8eace1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "804a9e8eace18e928120564884c4ed2acd9f6b3118f89dca7b131c49a1a3a3ef",
            "sha256": "37e8e0c177094965360592556e8cebd1eb5da4efbfccbf5e9dde8ef462b8192c",
            "duration_seconds": 37.172,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Inspect a work area",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "A fictional station has a wet floor, a blocked exit and no soap at the sink.",
                "start_ms": 2420,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "For each, name the hazard, possible harm, immediate control and reporting contact.",
                "start_ms": 9120,
                "end_ms": 16120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "First keep people away from danger and seek the right assistance.",
                "start_ms": 16420,
                "end_ms": 21820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A checklist that only says “be careful” is incomplete.",
                "start_ms": 22120,
                "end_ms": 26200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Check that the problem is corrected before removing the warning.",
                "start_ms": 26500,
                "end_ms": 31020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A checklist should lead to controls and follow-up, not merely count hazards.",
                "start_ms": 31320,
                "end_ms": 37120
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-identify/inspect.fil.ac8043f8f207.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ac8043f8f2072b3f68a2ec953d3a2a896eed01749b0447215a0b2e8c2f8be5bf",
            "sha256": "c57dc334ef7d69576b4ca46da3b7c5bd8ec0e3b5f39a4322d4bcfee8f151d519",
            "duration_seconds": 42.945,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Suriin ang isang work area",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na station, may basang sahig, nakaharang na labasan at walang sabon sa hugasan.",
                "start_ms": 2740,
                "end_ms": 9740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Para sa bawat isa, sabihin ang hazard, maaaring epekto, agarang kontrol at taong aabisuhan.",
                "start_ms": 10040,
                "end_ms": 18840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Unahin ang paglayo ng tao sa panganib at paghingi ng tamang tulong.",
                "start_ms": 19140,
                "end_ms": 24380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Hindi kumpleto ang checklist kung ang nakasulat ay “mag-ingat” lamang.",
                "start_ms": 24680,
                "end_ms": 29760
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Balikan kung naayos ang problema bago alisin ang babala.",
                "start_ms": 30060,
                "end_ms": 35060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang checklist ay dapat humantong sa kontrol at follow-up, hindi sa pagbilang lamang ng hazards.",
                "start_ms": 35360,
                "end_ms": 42880
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/08-osh/safety-identify/practice.en.fb8ee0b23eaf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fb8ee0b23eaf3cd9607b798f944fd96d83d9e47fcee1c0822693381c3a8351fb",
            "sha256": "42e20dacd24ce04d3dd04d4a0f57d9f705963eca92410857c006e867db0386ce",
            "duration_seconds": 44.278,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Draw five boxes: needlestick injury; infection exposure; body discomfort; stress from excessive work; work-related accidents.",
                "start_ms": 3060,
                "end_ms": 15500
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Give a station or home-visit example for each.",
                "start_ms": 15800,
                "end_ms": 19560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Choose one and write the harm, control and contact.",
                "start_ms": 19860,
                "end_ms": 24660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "In pairs, replace a vague “be careful” with a specific action.",
                "start_ms": 24960,
                "end_ms": 30600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alone, use the checklist.",
                "start_ms": 30900,
                "end_ms": 33420
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Before the next duty, perform a short hazard check.",
                "start_ms": 33720,
                "end_ms": 37840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Recognizing a hazard should lead to a specific control and responsible contact.",
                "start_ms": 38140,
                "end_ms": 44220
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-identify/practice.fil.4e85563b3079.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "4e85563b30792ce78ecf4b5152df69f26f9c055c5485044bbf202e74c6ce09ea",
            "sha256": "8e62fc2d1a138c5f6bd88143b1e7482b841a355140a6dea20dd11d898afcb273",
            "duration_seconds": 53.055,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 3120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Iguhit ang limang kahon: tusok ng karayom; exposure sa impeksyon; pananakit ng katawan; stress sa sobrang trabaho; aksidente sa gawain.",
                "start_ms": 3420,
                "end_ms": 16780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Magbigay ng isang halimbawa sa bawat isa mula sa station o home visit.",
                "start_ms": 17080,
                "end_ms": 23640
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Pumili ng isa at isulat ang pinsala, kontrol at contact.",
                "start_ms": 23940,
                "end_ms": 29660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa pares, suriin kung “mag-ingat” lang ang kontrol at palitan ng tiyak na aksyon.",
                "start_ms": 29960,
                "end_ms": 37000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung mag-isa, gamitin ang checklist.",
                "start_ms": 37300,
                "end_ms": 40380
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Bago ang susunod na duty, magsagawa ng maikling hazard check.",
                "start_ms": 40680,
                "end_ms": 45880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang pagkilala sa panganib ay dapat humantong sa tiyak na kontrol at taong tutugon.",
                "start_ms": 46180,
                "end_ms": 52980
              }
            ]
          }
        }
      }
    },
    "safety-prepare": {
      "module": "08-osh",
      "sections": {
        "check": {
          "en": {
            "src": "/training/audio/08-osh/safety-prepare/check.en.1ae742f86d75.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1ae742f86d754ce8be5f4846356a0947529401ae367bb4ee47c126c618088b85",
            "sha256": "b25804755b5255e61060c1fa617ffac4c4ce892ed1d909f6504e1355e1210e62",
            "duration_seconds": 18.808,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the next step",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer and explain why before viewing the feedback.",
                "start_ms": 2460,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then compare it with your own practice attempt.",
                "start_ms": 7760,
                "end_ms": 11040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A checklist must support a decision about safe starting conditions, not just list equipment.",
                "start_ms": 11340,
                "end_ms": 18740
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-prepare/check.fil.7807b3a28591.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7807b3a285912f0c7bc11a8526aa80e48485490af2bff5ffc35d8d0a04f3eb4f",
            "sha256": "9c1d1ca6ec7c911db43506573b98a8c32445fcae7ba342f237410beb1c61b35b",
            "duration_seconds": 20.689,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang susunod na hakbang",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin ang sagot at ipaliwanag kung bakit bago tingnan ang feedback.",
                "start_ms": 2900,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, ihambing sa sarili mong ginawa sa pagsasanay.",
                "start_ms": 8760,
                "end_ms": 13280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang checklist ay dapat may desisyon kung ligtas nang magsimula, hindi listahan lamang ng gamit.",
                "start_ms": 13580,
                "end_ms": 20620
              }
            ]
          }
        },
        "combined-hazards": {
          "en": {
            "src": "/training/audio/08-osh/safety-prepare/combined-hazards.en.144a339d17e7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "144a339d17e723450b9a6a8d9dc1c9e650af8c5ea068c9d5e22fa56284b9baf3",
            "sha256": "d71011e09f422fc8953dfb06107b939cab3c8c3d57b21634fd1247ef026533f0",
            "duration_seconds": 37.564,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "When hazards combine",
                "start_ms": 0,
                "end_ms": 2160
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Clients arrive in a surge, the room is hot and some PPE is unavailable.",
                "start_ms": 2460,
                "end_ms": 9300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "As a group, identify tasks to pause, tasks that can be modified and who must decide.",
                "start_ms": 9600,
                "end_ms": 17560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Consider staffing capacity and client flow; extra BHW hours should not be the only answer.",
                "start_ms": 17860,
                "end_ms": 26100
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Propose one safer alternative for supervisor approval.",
                "start_ms": 26400,
                "end_ms": 30880
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Combined hazards may require changing the work and obtaining the appropriate decision.",
                "start_ms": 31180,
                "end_ms": 37500
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-prepare/combined-hazards.fil.f6e1f52dd2e7.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f6e1f52dd2e7adcd7740984ad03fe19825cbfa8183941ff9247a0af9c559eeb3",
            "sha256": "7b2547f7f014fde6ea4cb0ded218b3c5acbfff5b852232570c0d214da2db6b8c",
            "duration_seconds": 41.247,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Kapag pinagsama ang mga panganib",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May dagsa ng kliyente, mainit ang silid at ubos ang ilang PPE.",
                "start_ms": 2900,
                "end_ms": 8340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa grupo, tukuyin kung aling gawain ang kailangang ihinto, alin ang maaaring baguhin, at kanino hihingi ng desisyon.",
                "start_ms": 8640,
                "end_ms": 18120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Isama ang kapasidad ng staff at daloy ng kliyente; huwag gawing tanging sagot ang dagdag na oras ng BHW.",
                "start_ms": 18420,
                "end_ms": 27060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Maglatag ng isang ligtas na alternatibo na dapat aprubahan ng supervisor.",
                "start_ms": 27360,
                "end_ms": 33520
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kapag magkakasabay ang hazards, kailangang baguhin ang gawain at humingi ng tamang desisyon.",
                "start_ms": 33820,
                "end_ms": 41180
              }
            ]
          }
        },
        "field-preparation": {
          "en": {
            "src": "/training/audio/08-osh/safety-prepare/field-preparation.en.fe2a1c67ca72.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "fe2a1c67ca72c50cfdb32001a16c93909a9f7c0e3055deafcaafe9f7679b77f6",
            "sha256": "2ee5f5f3bf7ba781a2f89e1f3182a6dd501a5d745b13c05603df16e537b477e3",
            "duration_seconds": 41.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Plan a safe field visit",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Before leaving, check weather, slippery paths, dogs and possible threats.",
                "start_ms": 2660,
                "end_ms": 8940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Share the route and expected return time; use a buddy system when local protocols call for one.",
                "start_ms": 9240,
                "end_ms": 16160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Carry drinking water and plan shade and rest during heat.",
                "start_ms": 16460,
                "end_ms": 20900
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not enter an unsafe situation; arrange an alternative.",
                "start_ms": 21200,
                "end_ms": 26080
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report accidents, bites or illness promptly and follow the appropriate referral rather than finishing the household list first.",
                "start_ms": 26380,
                "end_ms": 35500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A safe route and clear reporting contact matter as much as the visit list.",
                "start_ms": 35800,
                "end_ms": 41200
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-prepare/field-preparation.fil.e537bb98b24a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e537bb98b24af5315e9b2e0c10e1eced789b285704d249b6732e48e54586b476",
            "sha256": "fed63a9be8a3d79541054829c861e19fc375f2aced034602124a18be2b2948e8",
            "duration_seconds": 49.398,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Planuhin ang ligtas na pagbisita",
                "start_ms": 0,
                "end_ms": 2840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bago lumakad, suriin ang panahon, madulas na daan, aso at posibleng banta.",
                "start_ms": 3140,
                "end_ms": 10540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ipaalam ang ruta at inaasahang balik; gumamit ng buddy system kung itinakda ng lokal na protocol.",
                "start_ms": 10840,
                "end_ms": 18360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magdala ng inuming tubig at magplano ng lilim at pahinga sa init.",
                "start_ms": 18660,
                "end_ms": 24300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Huwag tumuloy sa lugar na hindi ligtas; makipag-ugnayan para sa alternatibo.",
                "start_ms": 24600,
                "end_ms": 30600
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Iulat agad ang aksidente, kagat o pagkakasakit at sundin ang naaangkop na referral, sa halip na tapusin muna ang listahan ng bahay.",
                "start_ms": 30900,
                "end_ms": 42060
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang ligtas na ruta at malinaw na reporting contact ay kasinghalaga ng listahan ng bibisitahin.",
                "start_ms": 42360,
                "end_ms": 49320
              }
            ]
          }
        },
        "practice": {
          "en": {
            "src": "/training/audio/08-osh/safety-prepare/practice.en.08571bc4a45a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "08571bc4a45abb3ba70a35bd8370e03caf1234fa68c51236aec0db5ad9f47d39",
            "sha256": "e92834544168c7ff3d574d2a954593c727f08ba17d5cf27fa7a933116e9bd779",
            "duration_seconds": 38.975,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Try it, then repeat",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Fill a card: task and scope; supplies and protection; route and weather; contact and return time; pause conditions.",
                "start_ms": 3060,
                "end_ms": 12820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Tell your partner: “There is no soap and a threat on the route.”",
                "start_ms": 13120,
                "end_ms": 18960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Explain what pauses and whose decision is needed.",
                "start_ms": 19260,
                "end_ms": 23700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Alone, write the response.",
                "start_ms": 24000,
                "end_ms": 26640
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Before the next visit, confirm the route and contact.",
                "start_ms": 26940,
                "end_ms": 31460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "A checklist must support a decision about safe starting conditions, not just list equipment.",
                "start_ms": 31760,
                "end_ms": 38920
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-prepare/practice.fil.f0277bb3b5cb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f0277bb3b5cb716d5eef821a49c703c6de8afff07d6fb33516d475bdf51fe7b4",
            "sha256": "06d0ab77eca1394aa5495b5a012d293b216d872cc8fc8dd7c2b71eeac6511902",
            "duration_seconds": 42.397,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan, saka ulitin",
                "start_ms": 0,
                "end_ms": 2640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Punan ang card: gawain at saklaw; supplies at proteksyon; ruta at panahon; contact at oras ng balik; dahilan para mag-pause.",
                "start_ms": 2940,
                "end_ms": 14420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sabihin sa kapareha: “Walang sabon at may banta sa ruta.”",
                "start_ms": 14720,
                "end_ms": 19800
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipakita kung ano ang hindi muna gagawin at kanino hihingi ng pasya.",
                "start_ms": 20100,
                "end_ms": 25660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kung mag-isa, sagutin ang parehong sitwasyon sa papel.",
                "start_ms": 25960,
                "end_ms": 29800
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Bago ang susunod na visit, kumpirmahin ang ruta at contact.",
                "start_ms": 30100,
                "end_ms": 34900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ang checklist ay dapat may desisyon kung ligtas nang magsimula, hindi listahan lamang ng gamit.",
                "start_ms": 35200,
                "end_ms": 42320
              }
            ]
          }
        },
        "station-preparation": {
          "en": {
            "src": "/training/audio/08-osh/safety-prepare/station-preparation.en.7c1377e069d1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7c1377e069d1887a9979c231cd281e4f0abf36ca7a6bcd426bcf220f61bf939f",
            "sha256": "5d7fbaa72083b474aefe9bddf379fe0cedc6703024eeed90d144a63f847b2659",
            "duration_seconds": 52.872,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Prepare the area and equipment",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ana, 33, is preparing for station work and home visits on a hot day.",
                "start_ms": 2780,
                "end_ms": 8980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She needs to check supplies and the route with the midwife.",
                "start_ms": 9280,
                "end_ms": 13560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Arrange for the slippery entrance to be corrected and keep people away from the hazard.",
                "start_ms": 13860,
                "end_ms": 19860
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Check for the correct sharps container, hand-hygiene supplies and PPE required for the task.",
                "start_ms": 20160,
                "end_ms": 27360
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Know the safe route and incident contact.",
                "start_ms": 27660,
                "end_ms": 31660
              },
              {
                "zone": "body",
                "index": 5,
                "text": "If essential protection is missing or a task exceeds training, pause and escalate to the supervisor.",
                "start_ms": 31960,
                "end_ms": 39760
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Gloves or a mask do not replace removing a hazard when removal is possible.",
                "start_ms": 40060,
                "end_ms": 46180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Prepare controls and equipment; report gaps before undertaking unsafe work.",
                "start_ms": 46480,
                "end_ms": 52800
              }
            ]
          },
          "fil": {
            "src": "/training/audio/08-osh/safety-prepare/station-preparation.fil.a271949af474.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a271949af47423100350ca2686292ab316039296476402677905ea3a868a5866",
            "sha256": "68ef76a3ca82d533e6e9d2adac902d343833aee000f1cd8404a6795f7e291c4f",
            "duration_seconds": 58.854,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ihanda ang lugar at kagamitan",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Si Ana, 33, ay naghahanda ng station duty at home visits sa mainit na araw.",
                "start_ms": 3180,
                "end_ms": 9740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May mga gamit at rutang kailangan munang suriin kasama ang midwife.",
                "start_ms": 10040,
                "end_ms": 15160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipaayos ang madulas na pasukan at ilayo muna ang mga tao sa panganib.",
                "start_ms": 15460,
                "end_ms": 21140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Tiyaking may angkop na lalagyan ng sharps, hand-hygiene supplies at PPE na itinakda para sa gawain.",
                "start_ms": 21440,
                "end_ms": 30400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Alamin ang ligtas na ruta at contact kapag may insidente.",
                "start_ms": 30700,
                "end_ms": 35140
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung kulang ang mahalagang proteksyon o lampas sa pagsasanay ang ipinapagawa, huminto at iakyat sa supervisor.",
                "start_ms": 35440,
                "end_ms": 44000
              },
              {
                "zone": "body",
                "index": 6,
                "text": "Hindi pinapalitan ng gloves o mask ang pag-alis ng hazard kung kaya itong alisin.",
                "start_ms": 44300,
                "end_ms": 50900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ihanda ang kontrol at kagamitan; iulat ang kulang bago magsagawa ng hindi ligtas na gawain.",
                "start_ms": 51200,
                "end_ms": 58800
              }
            ]
          }
        }
      }
    },
    "sambong": {
      "module": "chapter2/05-medicinal-plants",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/05-medicinal-plants/sambong/action.en.924ad8365896.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "924ad83658963a57a8255aaf5003cd35b42638fbc19116b9a34ba28858b2d2fb",
            "sha256": "6ec50dee337859ea8716af3adf21104cdd0e73e2a22d06571c37c106ff4a838c",
            "duration_seconds": 34.351,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find Blumea balsamifera on the reference card.",
                "start_ms": 2420,
                "end_ms": 5940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is leaves; the use topic is kidney-stone concern under clinical advice.",
                "start_ms": 6240,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 12860,
                "end_ms": 16060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 16360,
                "end_ms": 19680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Seek prompt facility assessment for severe pain and changed urination.",
                "start_ms": 19980,
                "end_ms": 25500
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Match two Sambong cards; choose Blumea balsamifera, leaves, use and safe next step.",
                "start_ms": 25800,
                "end_ms": 34280
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/05-medicinal-plants/sambong/action.fil.7c0cfefda00f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "7c0cfefda00f7af7633d35d2192dbff000f470434cd0aaa540ed532118df2cf8",
            "sha256": "f9bd3c1b9524caa6212aa10949056dc0bb2c3425995d5d21c9e2ca5ee1d0ab8d",
            "duration_seconds": 39.184,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa reference card, hanapin ang Blumea balsamifera.",
                "start_ms": 2260,
                "end_ms": 6940
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ang nakalistang bahagi ay dahon; ang paksang gamit ay pag-aalaga sa kidney-stone concern sa payo ng clinician.",
                "start_ms": 7240,
                "end_ms": 15880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sabihin kung ano ang alam at hindi alam.",
                "start_ms": 16180,
                "end_ms": 19420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Itanong ang kasalukuyang gamot at sintomas.",
                "start_ms": 19720,
                "end_ms": 23560
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Ipasuri agad ang matinding sakit at pagbabago sa pag-ihi sa health facility.",
                "start_ms": 23860,
                "end_ms": 29380
              },
              {
                "zone": "takeaway",
                "index": 0,
