                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea stops at the roadside and watches the traffic before stepping closer.",
                "start_ms": 1900,
                "end_ms": 7300
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She asks the bystander to call the confirmed contact and says the location aloud.",
                "start_ms": 7600,
                "end_ms": 13360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "From a safe position, she checks whether the rider responds and breathes normally, then reports what she saw.",
                "start_ms": 13660,
                "end_ms": 21540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She does not ask for the full story first, and she waits for trained help.",
                "start_ms": 21840,
                "end_ms": 27320
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea checks traffic, has the bystander call the confirmed contact, and reports what she saw.",
                "start_ms": 27620,
                "end_ms": 33940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/scene-help-referral/example.fil.1d4a78d03bff.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1d4a78d03bffd1498fa3df578c77f3874c6e202e95df3c3886887019d4b8305b",
