            "duration_seconds": 40.856,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huminto si Lea sa gilid ng kalsada at tiningnan muna ang trapiko.",
                "start_ms": 1980,
                "end_ms": 7460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pinakiusapan niya ang saksi na tawagan ang kumpirmadong contact at sinabi nang malakas ang lokasyon.",
                "start_ms": 7760,
                "end_ms": 15560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Mula sa ligtas na puwesto, sinuri niya kung tumutugon at normal na humihinga ang sakay.",
                "start_ms": 15860,
                "end_ms": 23340
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iniulat niya ang nakita.",
                "start_ms": 23640,
                "end_ms": 26200
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi muna niya inalam ang buong kuwento, at hinintay niya ang sanay na tulong.",
                "start_ms": 26500,
                "end_ms": 32460
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tiningnan ni Lea ang trapiko, pinatawag ang saksi sa kumpirmadong contact, at iniulat ang nakita.",
                "start_ms": 32760,
                "end_ms": 40800
              }
            ]
