            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sort: identify unneeded items and seek authorization before removal.",
                "start_ms": 2660,
                "end_ms": 9100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Systematize: arrange items according to use.",
                "start_ms": 9400,
                "end_ms": 13720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sweep: maintain cleanliness using the assigned procedure.",
                "start_ms": 14020,
                "end_ms": 19060
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Standardize: agree on labels, arrangement and a checklist.",
                "start_ms": 19360,
                "end_ms": 24680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "At the desk, inspect the poster, forms, dust and containers.",
                "start_ms": 24980,
                "end_ms": 31020
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Using safe props, inspect all seven categories at Tess’s desk. Assign one improvement, owner, date and evidence.",
                "start_ms": 31320,
                "end_ms": 41560
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/action.fil.aee6e718c763.mp3",
