                "zone": "body",
                "index": 0,
                "text": "Sort: tukuyin ang hindi kailangan at humingi ng pahintulot bago alisin.",
                "start_ms": 2420,
                "end_ms": 8900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Systematize: ayusin ang gamit ayon sa paggamit.",
                "start_ms": 9200,
                "end_ms": 14200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sweep: panatilihing malinis ayon sa nakatalagang paraan.",
                "start_ms": 14500,
                "end_ms": 19980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Standardize: magkasundo sa label, ayos at checklist.",
                "start_ms": 20280,
                "end_ms": 26160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Sa mesa, suriin ang poster, forms, alikabok at lalagyan.",
                "start_ms": 26460,
                "end_ms": 32980
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Gamit ang ligtas na props, suriin ang lahat ng 7S sa mesa ni Tess. Magtalaga ng isang pagbabago, responsable, petsa at ebidensiya.",
                "start_ms": 33280,
                "end_ms": 44920
