            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "69ef92f0daefbe8588891a4a2f329324cee5b69df6f7d838c7c92ab0f636e7a6",
            "sha256": "784cec5ce5094a8fea633ebd7bce47804d0a2a231d6dcec10bcd9c8d6bcb6539",
            "duration_seconds": 40.908,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Safety: iulat ang kahong nakaharang at ipaayos ang daan.",
                "start_ms": 1860,
                "end_ms": 7580
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Self-discipline: gampanan ang nakatalagang pagsusuri nang hindi laging inuutusan.",
                "start_ms": 7880,
                "end_ms": 14840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sustain: ulitin at balikan ang routine.",
                "start_ms": 15140,
                "end_ms": 19380
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Napagkasunduan ni Tess at staff ang araw-araw na checklist at pagsusuri sa Biyernes.",
                "start_ms": 19680,
                "end_ms": 26400
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kumpleto ang pitong kategorya; hindi lang pagwawalis.",
                "start_ms": 26700,
                "end_ms": 30900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nasusuri ang lahat ng pitong kategorya at may ligtas, awtorisadong pagbabago na may responsable at petsa ng pagbalik.",
                "start_ms": 31200,
                "end_ms": 40840
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/next-step.en.c074f470b75e.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c074f470b75e1d5588b9e561fd0e22e8749305e20e43befdb6cc3eb695781f17",
            "sha256": "425c38061d1cff2a4bdd144114ee5c52ffba7fc0d3ef78688f8ff8767a4809e5",
            "duration_seconds": 27.246,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tess’s group has a checklist, owner and review date.",
                "start_ms": 2580,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On Monday, use the seven-row job aid at a simulated desk.",
                "start_ms": 7440,
                "end_ms": 12280
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Record one improvement and how to tell whether it happened.",
                "start_ms": 12580,
                "end_ms": 17180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Word: sustain — maintaining and reviewing the agreed routine over time.",
                "start_ms": 17480,
                "end_ms": 23800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 24100,
                "end_ms": 27180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/next-step.fil.2acce1f26e51.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "2acce1f26e5196fb2e72d0a062a95625724942e8a9d89cbb9a3bc18c950ce9fd",
            "sha256": "40a6d2f2a78c856c69bb76700d93fc10b3da57faed7c00c60f3d9d618b1b4192",
            "duration_seconds": 34.273,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May checklist, responsable at petsa ng pagbalik ang grupo ni Tess.",
                "start_ms": 2420,
                "end_ms": 8420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa Lunes, gamitin ang pitong hanay ng job aid sa simulated na mesa.",
                "start_ms": 8720,
                "end_ms": 15200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itala ang isang pagbabago at kung paano malalamang nagawa ito.",
                "start_ms": 15500,
                "end_ms": 20740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: sustain — tuluy-tuloy na pagpapanatili at pagsusuri ng napagkasunduang gawain.",
                "start_ms": 21040,
                "end_ms": 30000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 30300,
                "end_ms": 34220
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/scene.en.e637a2908ed3.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e637a2908ed355abdb7f8024f540cfbd842b9e13ff4e34c5a55fb7f6d52198b3",
            "sha256": "010c898660389932ca64f2ce21bda277bb5cd30c46d289604cd50cfa1f943ce4",
            "duration_seconds": 28.16,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "BHW Tess inspects a simulated desk.",
                "start_ms": 1900,
                "end_ms": 5900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is an old poster, mixed blank forms and dust.",
                "start_ms": 6200,
                "end_ms": 10760
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Containers have no labels.",
                "start_ms": 11060,
                "end_ms": 13700
              },
              {
                "zone": "body",
                "index": 3,
                "text": "A box blocks the walkway.",
                "start_ms": 14000,
                "end_ms": 16520
              },
              {
                "zone": "body",
                "index": 4,
                "text": "No checker or review date is assigned.",
                "start_ms": 16820,
                "end_ms": 20180
              },
              {
                "zone": "body",
                "index": 5,
                "text": "The team needs order that lasts beyond one cleaning session.",
                "start_ms": 20480,
                "end_ms": 25240
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "No owner or review date.",
                "start_ms": 25540,
                "end_ms": 28100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/scene.fil.6e7061b00019.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "6e7061b000198b0b99795edece82ea57050b2b2bdabe2d93002d843ac5312a6d",
            "sha256": "49d66feb420af6b03a76851d847db92edab14759523a23c48319a575df4155c4",
            "duration_seconds": 31.843,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sinusuri ni BHW Tess ang kathang-isip na mesa.",
                "start_ms": 1780,
                "end_ms": 7140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "May lumang poster, halo-halong blangkong form at alikabok.",
                "start_ms": 7440,
                "end_ms": 12880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Walang label sa lalagyan.",
                "start_ms": 13180,
                "end_ms": 15460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May kahon sa daan.",
                "start_ms": 15760,
                "end_ms": 17680
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Walang nakatalagang tagasuri o petsa ng pagbalik.",
                "start_ms": 17980,
                "end_ms": 22940
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kailangan ng kaayusan na magpapatuloy matapos ang isang paglilinis.",
                "start_ms": 23240,
                "end_ms": 28120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang responsable o petsa ng pagsusuri.",
                "start_ms": 28420,
                "end_ms": 31780
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/scope.en.808cc23895ba.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "808cc23895bae8be8b9afe061a1f8641d3c3408589570eb436db02c5841fc07f",
            "sha256": "549cc2e0f1d18872def402e25dc6b4dbd5501baf6776b73cacd93624e3683edc",
            "duration_seconds": 29.205,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Use blank paper and safe props in practice.",
                "start_ms": 2740,
                "end_ms": 6660
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not discard records, medicines or equipment without authorization.",
                "start_ms": 6960,
                "end_ms": 13120
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Do not handle sharps or contaminated items as part of this activity.",
                "start_ms": 13420,
                "end_ms": 18540
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Report hazards to the assigned staff and follow the local procedure.",
                "start_ms": 18840,
                "end_ms": 24040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm boundaries and requirements with the appropriate person.",
                "start_ms": 24340,
                "end_ms": 29140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/seven-s-improvement/scope.fil.ed82731759eb.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ed82731759eb9e131a3d0806de0cb3d73c11f73c6fffc786a8ab4fba4c47dd02",
            "sha256": "d3cf59babec9052f6bc2546ff1f3075de0bf2d70e6727d73fb3d2f6f4bacdeae",
            "duration_seconds": 30.616,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Blangkong papel at ligtas na props lamang ang gamitin sa practice.",
                "start_ms": 2980,
                "end_ms": 7980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag magtapon ng rekord, gamot o kagamitan nang walang awtorisasyon.",
                "start_ms": 8280,
                "end_ms": 14160
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Huwag humawak ng matutulis o kontaminadong bagay bilang bahagi ng gawaing ito.",
                "start_ms": 14460,
                "end_ms": 20300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Iulat ang panganib sa nakatalagang staff at sundin ang lokal na pamamaraan.",
                "start_ms": 20600,
                "end_ms": 26360
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kumpirmahin ang saklaw at kailangan sa tamang tao.",
                "start_ms": 26660,
                "end_ms": 30540
              }
            ]
          }
        }
      }
    },
    "shock-loss-consciousness": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/action.en.a7726f2bbc95.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a7726f2bbc951a56f630b4c1b45cb0e2aaac191eccc63dfd2c49c3593bc1cf37",
            "sha256": "9dbd70a2ca91c4ec1fecf5baf5870a71a71b887d4262648a0b8e14aa81340bf6",
            "duration_seconds": 32.47,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Check scene safety, response and normal breathing.",
                "start_ms": 2620,
                "end_ms": 7220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Activate emergency help and request trained assessment.",
                "start_ms": 7520,
                "end_ms": 12040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "If not breathing normally, follow the locally trained CPR/AED response; if breathing, keep watching until help arrives.",
                "start_ms": 12340,
                "end_ms": 22540
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Demonstrate safe activation, response/breathing observation and an appropriate handover without oral intake.",
                "start_ms": 22840,
                "end_ms": 32400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/action.fil.31ca67017fe2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "31ca67017fe24234ad8695019eba5166f291d49ad6f3a5b01184f03172b493ca",
            "sha256": "18591802edc879e5f4a42adfac80e9c573016534dd4046e9c9c1ef00e5881ad5",
            "duration_seconds": 31.19,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2080
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Suriin ang paligid, tugon at normal na paghinga.",
                "start_ms": 2380,
                "end_ms": 7020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Humingi agad ng emergency help at sanay na assessor.",
                "start_ms": 7320,
                "end_ms": 11480
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kung hindi normal ang paghinga, sundin ang natutunang CPR/AED; kung humihinga, bantayan hanggang dumating ang tulong.",
                "start_ms": 11780,
                "end_ms": 21820
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Ipakita ang ligtas na pagtawag, obserbasyon sa tugon at paghinga, at handover nang walang pagpapainom.",
                "start_ms": 22120,
                "end_ms": 31120
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/check-start.en.e6f6eb7560bf.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e6f6eb7560bfc097cbb1bcbf67898186b21e1c06745775db18639a40f65a6adc",
            "sha256": "a9f1972411f1b633fd3eb0654dbf251dbdb2c3d42392e855838b99af94b5f7d3",
            "duration_seconds": 14.759,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2580,
                "end_ms": 5100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5400,
                "end_ms": 9280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Activate help and check response and breathing before anything else.",
                "start_ms": 9580,
                "end_ms": 14700
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/check-start.fil.63ef0392f7dc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "63ef0392f7dceedeb653a3a6ddfdd9b46580f55ac7c87ea678209cf4656ffddb",
            "sha256": "6ff8ce484b545af6ec32a778d9a73fd6e321102bec54a23c0abf4782ee607f85",
            "duration_seconds": 15.647,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2860,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5200,
                "end_ms": 9920
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Humingi ng tulong at suriin ang tugon at paghinga bago ang lahat.",
                "start_ms": 10220,
                "end_ms": 15580
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/check-transfer.en.3a06b814fb5a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "3a06b814fb5aeef3235b6702d5eb41d819dcc922d70728276ddc9f0825069861",
            "sha256": "7e079854e7dbe3cb5faee75e48425a7c225af7cf40ead3646afcce860a91a11a",
            "duration_seconds": 13.218,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2740,
                "end_ms": 4780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 5080,
                "end_ms": 7800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nothing by mouth for an unresponsive person; keep watching.",
                "start_ms": 8100,
                "end_ms": 13140
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/check-transfer.fil.afee506e5029.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "afee506e5029b3494c353914280e49b83b802561328cd881039f8c05a2f9db34",
            "sha256": "632057557eafb168cb022f85ec5dd2b38105d2905e0375c15a8476cfb2ab9882",
            "duration_seconds": 13.636,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2500,
                "end_ms": 4340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 4640,
                "end_ms": 7840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang ipaiinom sa hindi tumutugon; patuloy na magbantay.",
                "start_ms": 8140,
                "end_ms": 13580
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/example.en.03008698848f.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "03008698848f7b4fe302100420a8176c04666811f6d111ce93cb39f116e8a44e",
            "sha256": "60f82895befaab5474a0793f5ce56a501e50a1b324329bef55ee0abd4dde6f8b",
            "duration_seconds": 38.792,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "The BHW checks that the waiting area is safe, then asks, \"Can you hear me?\"",
                "start_ms": 2140,
                "end_ms": 8380
              },
              {
                "zone": "body",
                "index": 1,
                "text": "There is no answer.",
                "start_ms": 8680,
                "end_ms": 10840
              },
              {
                "zone": "body",
                "index": 2,
                "text": "She has someone call the confirmed contact and checks for normal breathing.",
                "start_ms": 11140,
                "end_ms": 16300
              },
              {
                "zone": "body",
                "index": 3,
                "text": "To the relative she says, \"Nothing by mouth while she cannot respond.\"",
                "start_ms": 16600,
                "end_ms": 22440
              },
              {
                "zone": "body",
                "index": 4,
                "text": "If breathing is not normal, she follows her local CPR/AED training; if it is, she keeps watching until help arrives.",
                "start_ms": 22740,
                "end_ms": 32580
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Check, call, watch breathing, and decline the sweet drink.",
                "start_ms": 32880,
                "end_ms": 38720
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/example.fil.81a1b52d3f62.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "81a1b52d3f6249ad8d1d034087e984f6b43a2824ff1c954128568f5f7e3c5606",
            "sha256": "e73573a040ebefd5d39a3ec18b7c5446a502eef856c962555804c6a2288fb0fb",
            "duration_seconds": 42.136,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1640
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Tiniyak ng BHW na ligtas ang waiting area, saka nagtanong: \"Naririnig n'yo po ba ako?\"",
                "start_ms": 1940,
                "end_ms": 9100
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Walang sagot.",
                "start_ms": 9400,
                "end_ms": 10920
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Nagpatawag siya sa kumpirmadong contact at sinuri ang normal na paghinga.",
                "start_ms": 11220,
                "end_ms": 16580
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sinabi niya sa kamag-anak: \"Walang ipaiinom habang hindi siya tumutugon.\"",
                "start_ms": 16880,
                "end_ms": 23160
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Kung hindi normal ang paghinga, susundin niya ang natutunang CPR/AED.",
                "start_ms": 23460,
                "end_ms": 29700
              },
              {
                "zone": "body",
                "index": 5,
                "text": "Kung normal, babantayan niya hanggang dumating ang tulong.",
                "start_ms": 30000,
                "end_ms": 33960
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Suriin, tumawag, bantayan ang paghinga, at tanggihan ang matamis na inumin.",
                "start_ms": 34260,
                "end_ms": 42060
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/next-step.en.e19f27639039.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e19f27639039176a49d12d81f754484310cbdc1c75a19237289be1fac2b7de34",
            "sha256": "2e40ddd3ce869774d48e21fed4c4771ce2b947202cf5d610882a820d03dafff5",
            "duration_seconds": 27.455,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "On Monday, use the same checklist with a new fictional case.",
                "start_ms": 2620,
                "end_ms": 7820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Record observations and the confirmed contact.",
                "start_ms": 8120,
                "end_ms": 11960
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Demonstrate safe activation, response/breathing observation and an appropriate handover without oral intake.",
                "start_ms": 12260,
                "end_ms": 21180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Practise the call, breathing check and refusal of oral intake with a new case.",
                "start_ms": 21480,
                "end_ms": 27400
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/next-step.fil.e298021f03e5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "e298021f03e5e225d7acf7b8901563ed38b1b556f8c697ae58f54b683f577b95",
            "sha256": "51484c5bdc0280de7747470c3e20b502ca06c7b79b118349da49bc2be6ec713e",
            "duration_seconds": 29.153,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2480
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa Lunes, gamitin ang kaparehong checklist sa bagong kathang-isip na kaso.",
                "start_ms": 2780,
                "end_ms": 9060
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Itala ang nakita at kung sino ang tatawagan.",
                "start_ms": 9360,
                "end_ms": 13600
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ipakita ang ligtas na pagtawag, obserbasyon sa tugon at paghinga, at handover nang walang pagpapainom.",
                "start_ms": 13900,
                "end_ms": 21860
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sanayin ang tawag, pagsuri sa paghinga at pagtanggi sa pagpapainom sa bagong kaso.",
                "start_ms": 22160,
                "end_ms": 29080
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/scene.en.5e19128d3567.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "5e19128d3567f48e6efd7912c74906ead68f6bb3aa2061eae52f4c535d3f3838",
            "sha256": "ff7dd29c5e9e9d3721e345d1c5cfe54bd0508194d2de3bd64ac59a1b8fa7003a",
            "duration_seconds": 17.162,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "An adult collapses at the waiting area and does not respond when spoken to.",
                "start_ms": 1980,
                "end_ms": 7180
              },
              {
                "zone": "body",
                "index": 1,
                "text": "A relative offers a sweet drink.",
                "start_ms": 7480,
                "end_ms": 10200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Case: An adult collapses and does not respond; a relative offers a sweet drink.",
                "start_ms": 10500,
                "end_ms": 17100
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/scene.fil.dec4c299fce1.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "dec4c299fce1894aadc1e7a261015b36866e82d4416fb5d75c15b1a791d0303c",
            "sha256": "0ecfc63a7066eadf5e1b429af8925cf11425b0c1bedfcaa459731618c8e760bb",
            "duration_seconds": 19.435,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1560
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Bumagsak ang isang nasa hustong gulang sa waiting area at hindi tumutugon.",
                "start_ms": 1860,
                "end_ms": 7860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Nag-alok ng matamis na inumin ang kamag-anak.",
                "start_ms": 8160,
                "end_ms": 11560
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Kaso: Bumagsak at hindi tumutugon ang adult; nag-alok ng matamis na inumin ang kamag-anak.",
                "start_ms": 11860,
                "end_ms": 19380
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/scope.en.ceee68a3d945.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ceee68a3d94532e2e116a7713d737dbfe02643c5d49c77df10705027889e7ab9",
            "sha256": "30cc6e33243709a493063e25400bbdf5b0212285d114452ee7e7fe74739a57d5",
            "duration_seconds": 20.976,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Do not give food, candy or water to an unresponsive person.",
                "start_ms": 2620,
                "end_ms": 8020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Do not infer the cause of collapse from a single clue or delay emergency activation.",
                "start_ms": 8320,
                "end_ms": 15200
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Nothing by mouth, no guessing the cause, no delay in calling.",
                "start_ms": 15500,
                "end_ms": 20900
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/shock-loss-consciousness/scope.fil.73e0a28ddbdd.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "73e0a28ddbddb3098511308d6cf8777e1f1792f898a7d47233e868b24da68ded",
            "sha256": "a4d27fd176e841648e8b9339df343fd7c75f215143f3f7e8861cc939544ef79a",
            "duration_seconds": 24.477,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Huwag bigyan ng pagkain, kendi o tubig ang taong hindi tumutugon.",
                "start_ms": 3060,
                "end_ms": 9220
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Huwag hulaan ang sanhi ng pagbagsak mula sa iisang palatandaan, at huwag ipagpaliban ang pagtawag.",
                "start_ms": 9520,
                "end_ms": 17280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Walang ipaiinom, walang panghuhula ng sanhi, walang pagpapaliban ng tawag.",
                "start_ms": 17580,
                "end_ms": 24420
              }
            ]
          }
        }
      }
    },
    "snakebite-response": {
      "module": "chapter2/04-first-aid",
      "sections": {
        "action": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/action.en.90e95ebad4e4.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "90e95ebad4e44a798f13533f6118c3ce6d348d43cd3acfc3bc58be4478d893a2",
            "sha256": "d4e9b332ab484a706a8a573adf3f7f1138e31ffad9a542236888ad0da94a759e",
            "duration_seconds": 23.249,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 1960
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Move away from the snake, keep the person calm and as still as possible, remove tight items if safe, and arrange rapid transport to a health facility.",
                "start_ms": 2260,
                "end_ms": 14340
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Report time and observations.",
                "start_ms": 14640,
                "end_ms": 17480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Reject the cord and walking plan, keep the person still and call for transport.",
                "start_ms": 17780,
                "end_ms": 23180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/action.fil.037480391da5.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "037480391da5dfbd262936fa0465a94385ca8b36a6526dd54b465575953fd1c2",
            "sha256": "934b3215dd0eb6f80e7ee538cbe9943f9b72b008568201fd1550283755a37605",
            "duration_seconds": 28.134,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lumayo sa ahas.",
                "start_ms": 2500,
                "end_ms": 4740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pakalmahin ang tao at panatilihing hindi gumagalaw.",
                "start_ms": 5040,
                "end_ms": 9400
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Alisin ang masisikip na bagay kung ligtas.",
                "start_ms": 9700,
                "end_ms": 13140
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ayusin ang mabilis na transport.",
                "start_ms": 13440,
                "end_ms": 16320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Iulat ang oras at nakita.",
                "start_ms": 16620,
                "end_ms": 19780
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tanggihan ang tali at paglalakad, panatilihing hindi gumagalaw ang tao at tumawag ng transport.",
                "start_ms": 20080,
                "end_ms": 28080
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/check-start.en.1af149c201e2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "1af149c201e22a9d57497e1f758578b40529d72b50a4dacc9726ec6916d16a0c",
            "sha256": "fdf29740a3c82b2e2d10ee0ef87cb430b5d7ccf755f3905bd858c4f2de6733ed",
            "duration_seconds": 14.655,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2660,
                "end_ms": 5020
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5320,
                "end_ms": 9280
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Keep him calm and still; decline the cord and the walk.",
                "start_ms": 9580,
                "end_ms": 14580
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/check-start.fil.b87f369b641d.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b87f369b641d9853c1ac1c22c69601d2a5bef47460b5ae6fc1cb9372e716f44b",
            "sha256": "ae7130f126cf6fde57c43934e5d8d220d462d6964cb1f234d9608418c73a0b88",
            "duration_seconds": 16.771,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2360
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2660,
                "end_ms": 4820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5120,
                "end_ms": 10000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Panatilihing kalmado at hindi gumagalaw; tanggihan ang tali at paglalakad.",
                "start_ms": 10300,
                "end_ms": 16700
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/check-transfer.en.a6e227f5878b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "a6e227f5878b92b6a35436a34d4a9210ebc50b729beb994ecc5c6132bce0d8f7",
            "sha256": "8090b1298d92fb7904835b2af41a0672bbf10706969bf5a738af2453c99aa84b",
            "duration_seconds": 12.042,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2620,
                "end_ms": 4460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4760,
                "end_ms": 7640
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Call for transport with the bite time and what you see.",
                "start_ms": 7940,
                "end_ms": 11980
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/check-transfer.fil.b1488522f01b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b1488522f01ba3ddf030749f39c66c57889661b899f89b9a8147d68a0e078378",
            "sha256": "34cbac8966b502b5b2c2b6c05595304b11703496e8d032eb9c3d2a949e169beb",
            "duration_seconds": 13.897,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 2900,
                "end_ms": 4900
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5200,
                "end_ms": 8480
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Tumawag ng transport kasama ang oras ng kagat at ang nakita.",
                "start_ms": 8780,
                "end_ms": 13820
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/example.en.b48ad01fed55.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "b48ad01fed55822e3902c552ad344d938b99cd71e3266a37d99208d40ebf6726",
            "sha256": "97e0656a6c51d3902ca091d01e5cb97776ec6814908f72b1d02d61d4fc6b32a9",
            "duration_seconds": 34.247,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Lea helps the worker move away from the snake and keeps him calm and as still as possible.",
                "start_ms": 2180,
                "end_ms": 9260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "She tells the friends kindly, \"No cord, and he should not walk.",
                "start_ms": 9560,
                "end_ms": 15040
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Transport will come to him.\"",
                "start_ms": 15340,
                "end_ms": 17740
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She removes tight items if it is safe, calls for transport, and reports the time of the bite and what she sees.",
                "start_ms": 18040,
                "end_ms": 27040
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Lea declines the cord and the walk, keeps him still and calls transport with the bite time.",
                "start_ms": 27340,
                "end_ms": 34180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/04-first-aid/snakebite-response/example.fil.666952f78b76.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "666952f78b76d88d8d335cb2320977f6a5f9a42920a07e5f6978622e41e1c681",
            "sha256": "16f8493949d8e50226a5ac2bd32eb6aa2f24b38c98e12f795e8e0864636cddf4",
            "duration_seconds": 41.77,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Inilalayo ni Lea sa ahas ang manggagawa.",
                "start_ms": 2140,
                "end_ms": 5780
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pinakakalma niya ito at pinananatiling hindi gumagalaw.",
                "start_ms": 6080,
                "end_ms": 10880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Magalang niyang sinasabi sa mga kasama: \"Walang tali, at hindi siya maglalakad.",
                "start_ms": 11180,
                "end_ms": 17660
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ang transport ang pupunta sa kanya.\"",
