            "content_hash": "ec6193adb97533dfd854d4d341f303ba57b1422f5712529e2a738a67a9d07ff1",
            "sha256": "78c9f549a67a18d5505c3377751cea93ba1ef3d79056063ea5d5d93927bde114",
            "duration_seconds": 36.232,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "What to do and say",
                "start_ms": 0,
                "end_ms": 2120
              },
              {
                "zone": "body",
                "index": 0,
                "text": "List the steps from arrival to follow-up.",
                "start_ms": 2420,
                "end_ms": 5980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Mark delays, barriers and repeated work.",
                "start_ms": 6280,
                "end_ms": 10560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Ask staff about the correct contact and whether the earlier record can be used.",
                "start_ms": 10860,
                "end_ms": 17020
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Confirm the next step with Pilar.",
                "start_ms": 17320,
                "end_ms": 19960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Choose an improvement that preserves necessary checks and permission.",
                "start_ms": 20260,
                "end_ms": 25220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Draw the four steps in the story. Mark one barrier. Propose a change with an owner, confirmation, date and measure.",
                "start_ms": 25520,
                "end_ms": 36160
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/action.fil.0eca9d7b044c.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "0eca9d7b044c9299f7330bd564607ba75363eda9d3674b66f5093adaa987ef18",
            "sha256": "42cc9d15fdee02de089b4d1279a36e24236fd499885d38bde000cc97b7faa967",
            "duration_seconds": 40.699,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Gawin at sabihin",
                "start_ms": 0,
                "end_ms": 2520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ilista ang hakbang mula pagdating hanggang follow-up.",
                "start_ms": 2820,
                "end_ms": 6820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Markahan ang pagkaantala, hadlang at dobleng gawain.",
                "start_ms": 7120,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Itanong sa staff ang tamang contact at kung magagamit ang naunang tala.",
                "start_ms": 13020,
                "end_ms": 18420
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Kumpirmahin ang susunod na hakbang kay Pilar.",
                "start_ms": 18720,
                "end_ms": 21880
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Pumili ng pagbabago na hindi nag-aalis ng kailangang pagsusuri o pahintulot.",
                "start_ms": 22180,
                "end_ms": 28220
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Iguhit ang apat na hakbang sa kuwento. Markahan ang isang hadlang. Gumawa ng mungkahi na may responsable, kumpirmasyon, petsa at panukat.",
                "start_ms": 28520,
                "end_ms": 40640
              }
            ]
          }
        },
        "check-start": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/check-start.en.73924e10f3f6.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "73924e10f3f6402bd290cd82cd6e550dcb5a960a33017621f643077979998321",
            "sha256": "91744afb0cc2041239d7afc367a184c46e74455dfc1a38d420ee1b3d0e941bf3",
            "duration_seconds": 14.237,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Choose the first response",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Choose an answer first.",
                "start_ms": 2620,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Then read the explanation for each option.",
                "start_ms": 5440,
                "end_ms": 9000
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This establishes a clear destination before giving directions.",
                "start_ms": 9300,
                "end_ms": 14180
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/check-start.fil.f4ca5316bb17.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "f4ca5316bb175f80cd6940c70da42773411a8c10553ee2fa22fb6b7a2af17450",
            "sha256": "628936089a8c81d211666153b5ef0f65dcfabf1a731ed0e6855c06169b26d062",
            "duration_seconds": 14.446,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Piliin ang unang tugon",
                "start_ms": 0,
                "end_ms": 2600
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Piliin muna ang sagot.",
                "start_ms": 2900,
                "end_ms": 4980
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Pagkatapos, basahin ang paliwanag sa bawat pagpipilian.",
                "start_ms": 5280,
                "end_ms": 9800
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "May malinaw na pupuntahan bago magbigay ng tagubilin.",
                "start_ms": 10100,
                "end_ms": 14380
              }
            ]
          }
        },
        "check-transfer": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/check-transfer.en.ec3150871e67.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ec3150871e675e7b760dd14af073a83e02e9bafaa0ca9242a443e07b19609768",
            "sha256": "c6aae7e64a373e58039542f4e068673e0211e2856c89cb80838cfbee7113eaf6",
            "duration_seconds": 13.453,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Apply it to the situation",
                "start_ms": 0,
                "end_ms": 2280
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Return to the story.",
                "start_ms": 2580,
                "end_ms": 4540
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Choose an appropriate next step.",
                "start_ms": 4840,
                "end_ms": 7400
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "This explores less duplication while preserving required processes.",
                "start_ms": 7700,
                "end_ms": 13380
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/check-transfer.fil.92737f05ce49.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "92737f05ce4903d2b878b540f80735149c8b5e7febcbbf9b3fa9a42dbc938fac",
            "sha256": "73d3d1cb1f20199cf6472dee3a9d4cd3db27e46c527805469d975ed2110ed20a",
            "duration_seconds": 15.778,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Subukan sa sitwasyon",
                "start_ms": 0,
                "end_ms": 3000
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Balikan ang kuwento.",
                "start_ms": 3300,
                "end_ms": 5140
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Piliin ang angkop na susunod na hakbang.",
                "start_ms": 5440,
                "end_ms": 8840
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Binabawasan ang posibleng pag-uulit habang pinananatili ang kailangang proseso.",
                "start_ms": 9140,
                "end_ms": 15700
              }
            ]
          }
        },
        "example": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/example.en.ac97d6eaeb53.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ac97d6eaeb53681c55219397f43a86f8802f2833df150b613e9a64d69e771caa",
            "sha256": "f04240667a6c99818280d6777f0e7201d6936ec61ab7862864c46b960f336594",
            "duration_seconds": 39.053,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Worked example",
                "start_ms": 0,
                "end_ms": 1760
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Map: arrival → asking around → repeating the form → waiting.",
                "start_ms": 2060,
                "end_ms": 8820
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Arnel proposes a clear contact card.",
                "start_ms": 9120,
                "end_ms": 12560
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Staff will confirm when the earlier record can be used.",
                "start_ms": 12860,
                "end_ms": 17220
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Next week they will count return visits caused by an incorrect contact.",
                "start_ms": 17520,
                "end_ms": 22960
              },
              {
                "zone": "body",
                "index": 4,
                "text": "They will not claim improvement before reviewing results.",
                "start_ms": 23260,
                "end_ms": 28180
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Maps the pathway, identifies a barrier and records a change, owner, confirmation and measure within role boundaries.",
                "start_ms": 28480,
                "end_ms": 39000
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/example.fil.42882d74c75a.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "42882d74c75a191087b93cd22881c89d988ec3f0cff8dfbf1e470aa408eec164",
            "sha256": "eb1765528f16d6ed79ba6d69a2bf127c762c2d4a5d8899f16f341abf87f798de",
            "duration_seconds": 44.826,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawang sagot",
                "start_ms": 0,
                "end_ms": 1680
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Mapa: pagdating → pagtatanong → pagpuno muli → paghihintay.",
                "start_ms": 1980,
                "end_ms": 9260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Iminungkahi ni Arnel ang malinaw na contact card.",
                "start_ms": 9560,
                "end_ms": 13440
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Kukumpirmahin ng staff kung kailan puwedeng gamitin ang naunang tala.",
                "start_ms": 13740,
                "end_ms": 18980
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Sa susunod na linggo, bibilangin nila ang pagbalik dahil sa maling contact.",
                "start_ms": 19280,
                "end_ms": 24720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Hindi pa nila sinasabing bumuti ang serbisyo hangga’t walang resulta.",
                "start_ms": 25020,
                "end_ms": 30140
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Naiguguhit ang daloy, natutukoy ang hadlang at naitatala ang pagbabago, responsable, kumpirmasyon at panukat nang hindi lumalampas sa tungkulin.",
                "start_ms": 30440,
                "end_ms": 44760
              }
            ]
          }
        },
        "next-step": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/next-step.en.aa3cca8dd1ca.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "aa3cca8dd1caa7a9f0fe9764acc708d9532dad920534c0a509357aad72477d02",
            "sha256": "31a043bee69bab9d00f99f490ba9fd0a220cf64f7611ddc1428bce842ae2698f",
            "duration_seconds": 28.003,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "On Monday, try this",
                "start_ms": 0,
                "end_ms": 2240
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pilar has a contact and an agreed update time.",
                "start_ms": 2540,
                "end_ms": 6620
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Staff still need to review use of the earlier record.",
                "start_ms": 6920,
                "end_ms": 11200
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On Monday, map a fictional visit and ask staff to review one proposed improvement.",
                "start_ms": 11500,
                "end_ms": 18460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Word: integrated — relevant services and providers are coordinated.",
                "start_ms": 18760,
                "end_ms": 24720
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Try the task and review the result.",
                "start_ms": 25020,
                "end_ms": 27940
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/next-step.fil.c23fa88496ff.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c23fa88496ff3d6d166a54b4eed87665a17d157ea5dcab45ba564ff0295837f3",
            "sha256": "3c96d1cfe85518a78f8f54c45b450e5a6a2b26358b8c6385b1834fd82d7b415b",
            "duration_seconds": 29.884,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Sa Lunes, gawin ito",
                "start_ms": 0,
                "end_ms": 2320
              },
              {
                "zone": "body",
                "index": 0,
                "text": "May contact at takdang update na si Pilar.",
                "start_ms": 2620,
                "end_ms": 6260
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Susuriin pa ng staff ang paggamit ng naunang tala.",
                "start_ms": 6560,
                "end_ms": 10880
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa Lunes, gumawa ng mapa ng kathang-isip na pagbisita at ipasuri ang isang pagbabago.",
                "start_ms": 11180,
                "end_ms": 18500
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Salita: integrated — magkakaugnay ang angkop na serbisyo at tagapagbigay.",
                "start_ms": 18800,
                "end_ms": 26120
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Subukan ang gawain at balikan ang resulta.",
                "start_ms": 26420,
                "end_ms": 29820
              }
            ]
          }
        },
        "scene": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scene.en.ee8a72c081cc.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "ee8a72c081cc976ce66b36b46babc9e07cb802f9979184d1b387af57c265855c",
            "sha256": "4f3b8ae71d6733425ad137df452b6679dd866adef0b5bb1af4493d2db53256d1",
            "duration_seconds": 27.507,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "The situation",
                "start_ms": 0,
                "end_ms": 1840
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Pilar has returned to the BHS twice.",
                "start_ms": 2140,
                "end_ms": 5860
              },
              {
                "zone": "body",
                "index": 1,
                "text": "On the first visit, the staff contact was unclear.",
                "start_ms": 6160,
                "end_ms": 10080
              },
              {
                "zone": "body",
                "index": 2,
                "text": "On the second, she was asked to write the same details again.",
                "start_ms": 10380,
                "end_ms": 14820
              },
              {
                "zone": "body",
                "index": 3,
                "text": "She works in the afternoon.",
                "start_ms": 15120,
                "end_ms": 17320
              },
              {
                "zone": "body",
                "index": 4,
                "text": "BHW Arnel wants to help without promising that everything will finish in one day.",
                "start_ms": 17620,
                "end_ms": 24380
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Where could a barrier be reduced?",
                "start_ms": 24680,
                "end_ms": 27440
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scene.fil.c8b3b4eff4b2.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "c8b3b4eff4b23f1eb970538831f4d64ccec7353c9cd6fa512eadea9f8a2360d2",
            "sha256": "37606ddbb85263a682d9940b6e8ccc0ce896ee7bab977cf5a674b929c656fd16",
            "duration_seconds": 28.317,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Ang sitwasyon",
                "start_ms": 0,
                "end_ms": 1520
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Dalawang beses nang bumalik si Pilar sa BHS.",
                "start_ms": 1820,
                "end_ms": 5740
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Sa unang punta, hindi malinaw kung aling staff ang lalapitan.",
                "start_ms": 6040,
                "end_ms": 10720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Sa ikalawa, pinasulat muli ang parehong detalye.",
                "start_ms": 11020,
                "end_ms": 15180
              },
              {
                "zone": "body",
                "index": 3,
                "text": "May trabaho siya sa hapon.",
                "start_ms": 15480,
                "end_ms": 17720
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Gustong tumulong ni BHW Arnel nang hindi nangangakong matatapos ang lahat sa isang araw.",
                "start_ms": 18020,
                "end_ms": 24900
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Saan maaaring bawasan ang hadlang?",
                "start_ms": 25200,
                "end_ms": 28240
              }
            ]
          }
        },
        "scope": {
          "en": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scope.en.67b9fc42694b.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "67b9fc42694b147c8d1ac91671dc56694e6ef1b834f10648f9d26d5bf9e8b08b",
            "sha256": "c21c87b0821b4de76e84dde4d5840ce20344d75c62909ef2b96a99bb6e251ce6",
            "duration_seconds": 29.388,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Scope and support",
                "start_ms": 0,
                "end_ms": 2200
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Integrated service connects the appropriate providers.",
                "start_ms": 2500,
                "end_ms": 6460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "It does not mean the BHW delivers every service.",
                "start_ms": 6760,
                "end_ms": 11360
              },
              {
                "zone": "body",
                "index": 2,
                "text": "Do not remove a form or check that staff require.",
                "start_ms": 11660,
                "end_ms": 15780
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Do not change queue priority without authorization.",
                "start_ms": 16080,
                "end_ms": 20000
              },
              {
                "zone": "body",
                "index": 4,
                "text": "Report barriers and have the proposal reviewed.",
                "start_ms": 20300,
                "end_ms": 24100
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Confirm boundaries and requirements with the appropriate person.",
                "start_ms": 24400,
                "end_ms": 29320
              }
            ]
          },
          "fil": {
            "src": "/training/audio/chapter2/02-quality-service/timely-integrated-service/scope.fil.778e36b23012.mp3",
            "voice": "gemini:gemini-3.8-flash-tts:Kore",
            "content_hash": "778e36b230122845e931a00cb176b297c7044aeea36d16c91bda3468ae29fe1e",
            "sha256": "9d4866d3cd940207e6410dbaa2e3db842cfe697ddfa62797b6cc4745c6364a5c",
            "duration_seconds": 32.47,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Saklaw at paghingi ng tulong",
                "start_ms": 0,
                "end_ms": 2880
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Ang integrated na serbisyo ay may ugnayan sa tamang tagapagbigay.",
                "start_ms": 3180,
                "end_ms": 8460
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Hindi ibig sabihin na gagawin ng BHW ang lahat ng serbisyo.",
                "start_ms": 8760,
                "end_ms": 14080
              },
              {
