                "end_ms": 2440
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Find Carmona retusa on the reference card.",
                "start_ms": 2740,
                "end_ms": 6420
              },
              {
                "zone": "body",
                "index": 1,
                "text": "The listed part is leaves; the use topic is stomach pain requiring assessment.",
                "start_ms": 6720,
                "end_ms": 12720
              },
              {
                "zone": "body",
                "index": 2,
                "text": "State what is known and unknown.",
                "start_ms": 13020,
                "end_ms": 16460
              },
              {
                "zone": "body",
                "index": 3,
                "text": "Ask about current medicine and symptoms.",
                "start_ms": 16760,
