            "sha256": "97e5550ed9fd3e61a677fc2c057402dbde205c0cefae84646f6b33febd41452b",
            "duration_seconds": 23.352,
            "timings": [
              {
                "zone": "heading",
                "index": 0,
                "text": "Halimbawa",
                "start_ms": 0,
                "end_ms": 1872
              },
              {
                "zone": "body",
                "index": 0,
                "text": "Sa kathang-isip na kasong ito, ginamit ni Mira ang kasalukuyang lokal na gabay bago sumagot.",
                "start_ms": 1872,
                "end_ms": 7920
              },
              {
                "zone": "body",
                "index": 1,
                "text": "Ito ang ipinakita niya sa observer: Iugnay ang nasuring WASH prevention sa angkop na assessment at ipasa ang concern sa health team.",
                "start_ms": 7920,
                "end_ms": 17304
              },
              {
                "zone": "takeaway",
                "index": 0,
                "text": "Sa kathang-isip na kasong ito, ginamit ni Mira ang kasalukuyang lokal na gabay bago sumagot.",
                "start_ms": 17304,
                "end_ms": 23352
              }
            ]
          }
        },
