              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "f35c41ddca1773261f19887efaf75f4a928886257f49b01f9b8ca4c5cedb006c",
              "sha256": "c4aa71a6fc66386b73e0002e27c680c7d47eb304da895b3f0d2c39cfa0a40cf5",
              "duration_seconds": 42.58,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Adapt the message to the audience",
                  "start_ms": 0,
                  "end_ms": 2840
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Liza and the midwife need different information.",
                  "start_ms": 3140,
                  "end_ms": 6460
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Liza needs a plain next step and a contact.",
                  "start_ms": 6760,
                  "end_ms": 11200
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "The midwife needs the concern, verified details and requested help.",
                  "start_ms": 11500,
                  "end_ms": 17500
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "A barangay planning meeting needs aggregated barriers without identifying people.",
                  "start_ms": 17800,
                  "end_ms": 23760
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Choose a picture, spoken explanation or secure written report to fit the audience and purpose; do not turn a private case into a public story.",
                  "start_ms": 24060,
                  "end_ms": 35940
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "The same concern can be presented differently for the purpose and appropriate recipient.",
                  "start_ms": 36240,
                  "end_ms": 42520
                }
              ]
            },
            "fil": {
              "src": "/training/audio/06-komunikasyon/communication-handoff/audience.fil.21c78bffb05a.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "21c78bffb05a3d3075eab26647b952025607a4d3bdd882ff416065b095e23b81",
              "sha256": "1bd2b7080b509badaa29af4c8c3f23cee9b45d05bfa24eaa14b420c2882c7995",
              "duration_seconds": 48.588,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Iangkop ang mensahe sa tatanggap",
                  "start_ms": 0,
                  "end_ms": 3240
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Magkaiba ang kailangan ni Liza at ng midwife.",
                  "start_ms": 3540,
                  "end_ms": 7820
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Kay Liza: payak na susunod na hakbang at kung sino ang lalapitan.",
                  "start_ms": 8120,
                  "end_ms": 14160
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Sa midwife: maikling concern, natiyak na detalye at hinihinging tulong.",
                  "start_ms": 14460,
                  "end_ms": 20940
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Sa barangay planning meeting: pinagsama-samang hadlang na walang pagkakakilanlan.",
                  "start_ms": 21240,
                  "end_ms": 26720
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Pumili ng larawan, pasalitang paliwanag o ligtas na nakasulat na ulat ayon sa layunin at kakayahan ng tatanggap; huwag gawing pampublikong kuwento ang pribadong kaso.",
                  "start_ms": 27020,
                  "end_ms": 41260
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ang parehong concern ay maaaring ilahad nang magkaiba ayon sa layunin at tamang tatanggap.",
                  "start_ms": 41560,
                  "end_ms": 48520
                }
              ]
            }
          },
