    const frame = frameAt(bytes, offset);
    if (!frame || frame.offset + frame.length > bytes.length) break;
    frames.push(frame);
    offset += frame.length;
  }
  if (offset !== bytes.length) throw new Error(`unparseable MP3 data at byte ${offset} of ${bytes.length}`);
